window.ITEMS=[{"id": "bc90-1-2", "exam": "bc90-1", "nums": [2], "form": "單題", "img": "img/bc90-1-2.png", "source": "曾國藩語（出處待查，一般認為出自其家書）", "author": "曾國藩", "genre": "經典語錄", "types": ["句意理解", "文意推論"], "passage": "凡富貴功名，半由人事，半由天命；唯讀書做人，全憑自己作主。", "translation": "凡是富貴和功名，一半靠人的努力，一半靠上天的安排；只有讀書和做人，完全由自己決定。", "keywords": [{"w": "凡", "m": "凡是、所有"}, {"w": "人事", "m": "人的作為、努力"}, {"w": "天命", "m": "上天安排的命運"}, {"w": "唯", "m": "只有"}], "questions": [{"n": 2, "stem": "清儒曾國藩云：「凡富貴功名，半由人事，半由天命；唯讀書做人，全憑自己作主。」由此可推知他的想法為何？", "options": {"A": "讀書做人，操之在己", "B": "謀事在人，成事在天", "C": "發憤向學，功名可得", "D": "富貴功名，命中注定"}, "answer": "A", "explain": "句子分成兩半：富貴功名「半由人事，半由天命」，讀書做人卻「全憑自己作主」，後半用「唯」強調，是全句重點，所以「讀書做人，操之在己」最符合。(B)只說到前半「富貴功名」的部分，不是他要強調的想法；(C)原文說功名有一半靠天命，不能保證努力就「可得」；(D)原文說只「半由天命」，不是完全「命中注定」。", "skill": "遇到「凡……；唯……」的對照句，重點通常落在「唯」後面那一半；再逐一核對選項有沒有把「一半」說成「全部」。"}], "difficulty": "易", "label": "90年第一次基測", "year": 90, "kind": "基測"}, {"id": "bc90-1-8", "exam": "bc90-1", "nums": [8], "form": "單題", "img": "img/bc90-1-8.png", "source": "(A)彭端淑〈為學一首示子姪〉；其餘選項出處待查", "author": "彭端淑等", "genre": "其他", "types": ["句意理解", "人物情感"], "passage": "(A)吾數年來欲買舟而下，猶未能也。子何恃而往？(B)我軍若進，中其計也，汝輩焉知？宜速退。(D)應是母慈重，使爾悲不任。", "translation": "(A)我好幾年來想要租船順江而下（去南海），還沒能做到。你憑什麼前往呢？(B)我軍如果前進，就中了敵人的計謀，你們哪裡知道？應該趕快撤退。(D)應該是母親的慈愛太深重，才使你悲傷得承受不住。", "keywords": [{"w": "恃", "m": "依靠、憑藉"}, {"w": "焉", "m": "怎麼、哪裡（疑問詞）"}, {"w": "汝輩", "m": "你們"}, {"w": "宜", "m": "應該"}, {"w": "不任", "m": "承受不了"}], "questions": [{"n": 8, "stem": "下列各句所傳達的語氣，何者說明正確？", "options": {"A": "「吾數年來欲買舟而下，猶未能也。子何恃而往？」——輕視的語氣", "B": "「我軍若進，中其計也，汝輩焉知？宜速退。」——勸慰的語氣", "C": "「我親愛的手足，不要傷悲。」——斥責的語氣", "D": "「應是母慈重，使爾悲不任。」——肯定的語氣"}, "answer": "A", "explain": "(A)出自〈為學〉，富和尚自己準備多年都去不了南海，反問窮和尚「你憑什麼去？」帶有看不起對方的輕視語氣，正確。(B)「汝輩焉知？」是責備部下不懂情勢，屬於斥責、命令的語氣，不是勸慰；(C)「不要傷悲」是安慰對方，屬於勸慰語氣，不是斥責；(D)「應是」表示推測，是揣度的語氣，不是肯定。", "skill": "抓住句中的語氣標記詞：「何恃」反問→輕視、「焉知」反問→責備、「不要……」→勸慰、「應是」→推測。"}], "difficulty": "中", "label": "90年第一次基測", "year": 90, "kind": "基測"}, {"id": "bc90-1-30", "exam": "bc90-1", "nums": [30], "form": "單題", "img": "img/bc90-1-30.png", "source": "命題者自撰書信", "author": "", "genre": "書信序跋", "types": ["文化常識"], "passage": "建國兄：前日到貴府打擾，受到賢伉儷熱情招待，深情厚誼，永銘內心。而賢姪的應對得體也叫人讚賞；想到小兒粗魯不文，調教無方，深感慚愧。來日，敝伉儷定當好好向吾兄請教。專此，順頌時綏　弟信華敬上　三月三十一日", "translation": "建國兄：前幾天到府上打擾，受到你們夫妻熱情招待，這份深厚情誼會永遠記在心裡。你兒子應對得體也令人稱讚；想到我兒子粗魯沒教養，是我教導不當，覺得很慚愧。改天我們夫妻一定好好向你請教。", "keywords": [{"w": "賢伉儷", "m": "敬稱對方夫婦"}, {"w": "賢姪", "m": "稱朋友的兒子"}, {"w": "小兒", "m": "謙稱自己的兒子"}, {"w": "愚夫婦", "m": "謙稱自己夫妻（「伉儷」只能用來稱別人）"}, {"w": "時綏", "m": "書信結尾問候語，祝對方時時平安"}], "questions": [{"n": 30, "stem": "上面這封信畫線處所使用的稱謂，何者不恰當？", "options": {"A": "甲", "B": "乙", "C": "丙", "D": "丁"}, "answer": "D", "explain": "「伉儷」是對別人夫妻的敬稱，只能稱對方，所以甲「賢伉儷」稱對方夫婦正確；寫信人自稱夫妻應該謙稱「愚夫婦」，丁「敝伉儷」把敬稱用在自己身上，不恰當。乙「賢姪」稱朋友的兒子、丙「小兒」謙稱自己的兒子，都正確。", "skill": "稱謂題先分「稱別人用敬詞（賢、令、貴）、稱自己用謙詞（愚、小、敝、家、舍）」，再看詞語本身是不是只能用於他人。"}], "difficulty": "中", "label": "90年第一次基測", "year": 90, "kind": "基測"}, {"id": "bc90-1-32", "exam": "bc90-1", "nums": [32], "form": "單題", "img": "img/bc90-1-32.png", "source": "蘇軾〈記承天夜遊〉", "author": "蘇軾", "genre": "山水遊記", "types": ["人物情感", "比較閱讀"], "passage": "庭中如積水空明，水中藻荇交橫，蓋竹柏影也。何夜無月？何處無竹柏？但少閑人如吾兩人耳！", "translation": "庭院中的月光像積水一樣清澈透明，水中好像有水藻、荇菜交錯縱橫，原來是竹子和柏樹的影子。哪一個夜晚沒有月亮？哪個地方沒有竹柏？只是缺少像我們兩人這樣的閒人罷了！", "keywords": [{"w": "蓋", "m": "原來是"}, {"w": "但", "m": "只是"}, {"w": "閑人", "m": "清閒、有雅興欣賞景物的人"}, {"w": "耳", "m": "罷了"}], "questions": [{"n": 32, "stem": "蘇軾〈記承天夜遊〉：「庭中如積水空明，水中藻荇交橫，蓋竹柏影也。何夜無月？何處無竹柏？但少閑人如吾兩人耳！」作者所呈現的心境與下列何者最接近？", "options": {"A": "忙人無是非，閑人是非多", "B": "人閑桂花落，夜靜春山空", "C": "人莫樂於閑，非無所事事之謂也", "D": "江山風月，本無常主，閑者便是主人"}, "answer": "D", "explain": "月色、竹柏到處都有，只有像他們這樣的「閑人」才懂得欣賞，意思是：美景屬於有閒情去領略的人。(D)「江山風月本來沒有固定的主人，有閒情的人就是主人」，與此最接近。(A)說閒人容易惹是非，與欣賞美景無關；(B)王維詩句，描寫夜晚春山的寂靜景色，是寫景，不是「只有閒人才能享有美景」的心境；(C)說真正的閒樂不是無所事事，重點在如何善用閒暇，與題幹強調閒人才能欣賞美景不同。", "skill": "先把引文濃縮成一句主旨（美景常在，唯閒人能賞），再找選項中同樣把「閑」和「享有風月」連在一起的句子。"}], "difficulty": "中", "label": "90年第一次基測", "year": 90, "kind": "基測"}, {"id": "bc90-1-33", "exam": "bc90-1", "nums": [33, 34, 35], "form": "題組", "img": "img/bc90-1-33.png", "source": "周邦彥〈浣溪沙〉", "author": "周邦彥", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感", "典故出處"], "passage": "樓上晴天碧四垂，樓前芳草接天涯，勸君莫上最高梯。　新筍已成堂下竹，落花都上燕巢泥，忍聽林表杜鵑啼。", "translation": "樓上晴朗的碧空向四方垂落，樓前的芳草一直綿延到天邊；勸你不要登上最高的樓梯（以免望遠思鄉）。新長的竹筍已經長成堂前的竹子，落花都被燕子銜去築成巢泥了；怎麼忍心聽林梢杜鵑的啼叫聲。", "keywords": [{"w": "四垂", "m": "天空向四方低垂"}, {"w": "天涯", "m": "天邊，極遠之處"}, {"w": "忍聽", "m": "怎忍聽，不忍聽"}, {"w": "林表", "m": "樹林梢頭"}, {"w": "杜鵑", "m": "鳥名，啼聲似「不如歸去」，象徵思歸"}], "questions": [{"n": 33, "stem": "這闋詞中，作者想藉「登樓」表達什麼？", "options": {"A": "兒女私情", "B": "思鄉之情", "C": "壯志豪情", "D": "悼念之情"}, "answer": "B", "explain": "登高望遠看見芳草「接天涯」，引發對遠方家鄉的思念，所以勸人「莫上最高梯」；末句又寫不忍聽杜鵑（不如歸去）的啼聲，可見是思鄉之情。詞中沒有寫戀人(A)、沒有抒發抱負(C)、也沒有悼念逝者(D)。", "skill": "古典詩詞的「登樓、望遠、芳草、天涯、杜鵑」多與思鄉懷人有關，抓住意象群再判斷情感。"}, {"n": 34, "stem": "「新筍已成堂下竹，落花都上燕巢泥」，這兩句的意境近於下列何者？", "options": {"A": "燕去燕來還過日，花開花落即經春", "B": "好鳥枝頭亦朋友，落花水面皆文章", "C": "人生到處知何似，應似飛鴻踏雪泥", "D": "勸君莫惜金縷衣，勸君惜取少年時"}, "answer": "A", "explain": "竹筍長成竹子、落花變成燕巢泥，都表示時間已經過了一段，春去夏來，暗示離家已久。(A)燕子來去、花開花落，一個春天就過去了，同樣寫時光流轉。(B)寫自然萬物皆可親、皆有趣味；(C)蘇軾以飛鴻踏雪泥比喻人生行蹤無定；(D)勸人珍惜青春，屬於勸勉，不是寫景中暗示時序推移。", "skill": "先問「這兩句的景物變化說明了什麼？」——答案是時間流逝，再找同樣用景物變化寫時光的句子。"}, {"n": 35, "stem": "古典詩詞中，常用一些特定的典故或詞語來表達一定的意涵。以這闋詞為例，下列各項說明，何者正確？", "options": {"A": "「新筍」暗示「重生」", "B": "「落花」暗示「懷舊」", "C": "「杜鵑」暗示「思歸」", "D": "「芳草」暗示「忠君」"}, "answer": "C", "explain": "杜鵑鳥叫聲像「不如歸去」，傳統詩詞常用來表達旅人思歸，正確。(A)新筍成竹只是表示時間推移，不是重生；(B)落花在此點出春去夏來，暗示離家已久，沒有懷舊的意思；(D)芳草接天涯是寫遠望之景，引發思鄉，與忠君無關。", "skill": "記住常見意象的固定意涵（杜鵑＝思歸、鴻雁＝書信、柳＝送別、月＝思鄉），再回到詞句檢查是否合用。"}], "difficulty": "易", "label": "90年第一次基測", "year": 90, "kind": "基測"}, {"id": "bc90-1-36", "exam": "bc90-1", "nums": [36, 37, 38], "form": "題組", "img": "img/bc90-1-36.png", "source": "韓愈〈雜說四〉", "author": "韓愈", "genre": "說理議論", "types": ["主旨寓意", "寫作手法", "句意理解"], "passage": "世有伯樂，然後有千里馬。千里馬常有，而伯樂不常有。故雖有名馬，祇辱於奴隸人之手，駢死於槽櫪之間，不以千里稱也。\n馬之千里者，一食或盡粟一石。食馬者，不知其能千里而食也。是馬也，雖有千里之能，食不飽，力不足，才美不外見，且欲與常馬等，不可得，安求其能千里也？\n策之不以其道，食之不能盡其材，鳴之而不能通其意，執策而臨之，曰：「天下無馬。」嗚呼！其真無馬耶？其真不知馬也！", "translation": "世上先有伯樂，然後才有千里馬。千里馬常常有，但伯樂不常有。所以即使有名馬，也只能在奴僕手中受委屈，和普通馬一起死在馬廄裡，不能以千里馬聞名。\n能跑千里的馬，一餐有時要吃掉一石糧食。餵馬的人不知道牠能跑千里而照普通馬餵牠。這匹馬雖有跑千里的能力，卻吃不飽、力氣不足，才能與優點表現不出來，想和普通馬一樣都做不到，又怎能要求牠跑千里呢？\n鞭策牠不用正確方法，餵養牠不能讓牠發揮才能，牠嘶鳴卻不懂牠的意思，還拿著鞭子對著牠說：「天下沒有好馬。」唉！難道真的沒有好馬嗎？其實是真的不認識好馬啊！", "keywords": [{"w": "祇", "m": "只"}, {"w": "駢", "m": "並列、一起"}, {"w": "槽櫪", "m": "馬槽，養馬的地方"}, {"w": "食（ㄙˋ）", "m": "通「飼」，餵養"}, {"w": "見（ㄒㄧㄢˋ）", "m": "通「現」，顯現"}, {"w": "安", "m": "怎麼"}, {"w": "策", "m": "鞭打、鞭策；也指馬鞭"}, {"w": "其", "m": "表示反問或推測的語氣，難道"}], "questions": [{"n": 36, "stem": "作者想藉本文來抒發什麼？", "options": {"A": "悲傷賢士懷才不遇", "B": "感慨「天下無馬」", "C": "憾恨伯樂不遇千里馬", "D": "譏評養馬人不懂養馬的方法"}, "answer": "A", "explain": "本文以千里馬比喻人才、伯樂比喻能識才的君主，千里馬被埋沒就是人才得不到賞識，作者藉此抒發賢士懷才不遇的悲哀。(B)「天下無馬」是食馬者的錯誤說法，作者正是要反駁它；(C)文中是說千里馬遇不到伯樂，不是伯樂遇不到千里馬；(D)只看到表面故事，養馬人其實比喻不識人才的上位者。", "skill": "託物寓意的文章要「翻譯比喻」：馬＝人才、伯樂＝識才者、食馬者＝庸碌當權者，再找出作者真正想說的事。"}, {"n": 37, "stem": "本文用什麼方法來表達主旨？", "options": {"A": "借景物來抒情", "B": "借故事來說理", "C": "用直言來勸諫", "D": "用史實來批判"}, "answer": "B", "explain": "全文借千里馬被埋沒的故事，說明人才需要被賞識的道理，屬於借故事（託物）說理。文中沒有寫景(A)；作者沒有直接說出「君主要重用人才」，所以不是直言(C)；伯樂雖是古人，但文章重點在食馬者不識良馬的比喻，不是敘述歷史事件(D)。", "skill": "判斷寫作手法時，問自己：作者有沒有直接把道理說出來？沒有、而是透過一件事來暗示，就是「借事說理」。"}, {"n": 38, "stem": "下列文意的說明，何者正確？", "options": {"A": "「世有伯樂，然後有千里馬」——只有伯樂才養得出千里馬", "B": "「不知其能千里而食也」——把千里馬當作普通馬來餵養", "C": "「策之不以其道」——不能擬定正確的養馬策略", "D": "「鳴之而不能通其意」——馬不能了解主人呼喚的用意"}, "answer": "B", "explain": "(B)「食」讀作ㄙˋ，餵養；不知道牠能跑千里而照一般方式餵牠，就是把千里馬當普通馬養，正確。(A)意思是有伯樂才能「發現」千里馬，不是「養出」；(C)「策」是鞭打、駕馭，意思是駕馭牠不用正確方法，不是擬定策略；(D)是馬嘶鳴而人不懂馬的意思，主客顛倒了。", "skill": "文言字詞題先確認關鍵字的意思（食＝飼、策＝鞭打），再看動作的主詞是誰（誰鳴、誰不通其意）。"}], "difficulty": "中", "label": "90年第一次基測", "year": 90, "kind": "基測"}, {"id": "bc90-1-41", "exam": "bc90-1", "nums": [41, 42], "form": "題組", "img": "img/bc90-1-41.png", "source": "改寫自《資治通鑑‧唐紀》（長孫皇后賀太宗）", "author": "", "genre": "史傳人物", "types": ["主旨寓意", "句意理解", "人物情感"], "passage": "吾聞國有賢君，而後有不屈之臣。桀、紂獨夫，不容逢、干。今聞魏徵抗顏直諫，是知陛下之聖明也，吾何不賀陛下？", "translation": "我聽說國家有賢明的君主，然後才有不屈服的臣子。夏桀、商紂是無道的暴君，容不下關龍逢、比干這樣的忠臣。如今聽說魏徵面色嚴正地直言進諫，由此可知陛下是聖明的君主，我怎麼能不向陛下道賀呢？", "keywords": [{"w": "獨夫", "m": "無道、眾叛親離的君主"}, {"w": "逢、干", "m": "關龍逢（夏桀時忠臣）、比干（商紂時忠臣），皆因直諫被殺"}, {"w": "抗顏", "m": "面色嚴正不屈"}, {"w": "是", "m": "這、由此"}, {"w": "何", "m": "為什麼、怎麼"}], "questions": [{"n": 41, "stem": "下列敘述，何者是本文的主旨？", "options": {"A": "唐太宗擇善固執，不隨波逐流", "B": "魏徵心直口快，不顧太宗的顏面", "C": "桀、紂、逢、干的行為，不容於天地", "D": "皇后聰明機智，婉轉地化解了太宗的怒氣"}, "answer": "D", "explain": "太宗本來滿腹怒火，皇后不正面為魏徵辯護，而是穿禮服向太宗道賀，說「有賢君才有直臣」，讓太宗明白魏徵直諫正證明自己聖明，怒氣就消了。全文重點在皇后的機智勸解。(A)太宗原本生氣，談不上擇善固執；(B)魏徵是忠心直諫，而且他只是引起事件的人，不是主旨；(C)逢、干是忠臣，不是「不容於天地」的人，是桀紂容不下他們。", "skill": "找主旨看「事件的轉折是誰造成的」：開頭太宗發怒、結尾怒火消散，中間做事的人（皇后）就是重點。"}, {"n": 42, "stem": "有關本文的說明，下列敘述何者正確？", "options": {"A": "魏徵以下犯上，其行徑與桀、紂無異", "B": "桀、紂雖然暴虐無道，卻有忠臣魏徵的輔助", "C": "太宗能接納逢、干等人的諫言，因此留名青史", "D": "「國有賢君，而後有不屈之臣」，是皇后用來讚美太宗的話"}, "answer": "D", "explain": "皇后說「國有賢君，而後有不屈之臣」，再說聽聞魏徵直諫「是知陛下之聖明」，正是用來讚美太宗，正確。(A)魏徵是忠臣直諫，與暴君桀紂完全不同；(B)輔佐桀、紂的忠臣是關龍逢、比干，魏徵是唐太宗的臣子；(C)逢、干是夏、商時人，太宗接納的是魏徵的諫言。", "skill": "人名對應題要把人物和時代、身分配好（逢—桀、干—紂、魏徵—太宗），再判斷說話者的用意。"}], "difficulty": "易", "label": "90年第一次基測", "year": 90, "kind": "基測"}, {"id": "bc90-2-8", "exam": "bc90-2", "nums": [8], "form": "單題", "img": "img/bc90-2-8.png", "source": "(A)陶淵明〈五柳先生傳〉；(B)文天祥就義事蹟（出處待查）；(C)《列子‧湯問》〈愚公移山〉；(D)彭端淑〈為學一首示子姪〉", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "(A)酣觴賦詩，以樂其志 (B)南面再拜就死 (C)甚矣！汝之不慧 (D)僧之富者不能至", "translation": "(A)暢快飲酒、作詩，來使自己的心志快樂。(B)面向南方拜了兩拜，然後從容就義。(C)太過分了！你的不聰明。（你實在太不聰明了！）(D)和尚中富有的那一個卻去不成。", "keywords": [{"w": "酣觴", "m": "盡情飲酒"}, {"w": "南面", "m": "面向南方（南宋朝廷所在）"}, {"w": "再拜", "m": "拜兩次"}, {"w": "就死", "m": "受死、就義"}, {"w": "甚矣", "m": "太過分了（倒裝句的謂語提前）"}, {"w": "僧之富者", "m": "富有的和尚（定語後置）"}], "questions": [{"n": 8, "stem": "下列選項改寫後，何者的意思和原意不一樣？", "options": {"A": "酣觴賦詩，以樂其志 → 以酣觴賦詩樂其志", "B": "南面再拜就死 → 再拜，就死南面", "C": "甚矣！汝之不慧 → 汝之不慧甚矣", "D": "僧之富者不能至 → 富僧不能至"}, "answer": "B", "explain": "(B)原句「南面」修飾「再拜」，是面向南方行禮後就義；改寫成「再拜，就死南面」，變成拜過之後「死在南方／面向南方而死」，面南的動作從「拜」跑到「死」，意思改變了。(A)只是把「以」移到前面，都是用飲酒作詩來使心志快樂；(C)原句是把「甚矣」提前的倒裝句，還原後意思相同；(D)「僧之富者」就是「富僧」，屬於定語後置的還原。", "skill": "判斷改寫是否等義，先找出每個修飾語原本修飾哪個動作，再看改寫後修飾對象有沒有換人；倒裝句、定語後置還原後意思不變。"}], "difficulty": "難", "label": "90年第二次基測", "year": 90, "kind": "基測"}, {"id": "bc90-2-14", "exam": "bc90-2", "nums": [14], "form": "單題", "img": "img/bc90-2-14.png", "source": "孟浩然〈過故人莊〉；(A)王維〈山居秋暝〉；(C)王之渙〈登鸛雀樓〉；(D)陶淵明〈歸園田居〉", "author": "孟浩然等", "genre": "古典詩詞曲", "types": ["虛詞句式", "詩詞賞析"], "passage": "待到重陽日，還來就菊花。(A)明月松間照 (B)把酒話桑麻 (C)白日依山盡 (D)但使願無違", "translation": "等到重陽節那天，我還要再來欣賞菊花。(A)明亮的月光照在松林間。(B)端著酒談論農事。(C)夕陽靠著山慢慢落下。(D)只要不違背我的心願就好。", "keywords": [{"w": "還", "m": "再、又（副詞）"}, {"w": "就", "m": "靠近、前往（欣賞）"}, {"w": "把", "m": "拿著、端著"}, {"w": "盡", "m": "完、消失（動詞）"}, {"w": "但", "m": "只（副詞）"}], "questions": [{"n": 14, "stem": "「待到重陽日，還來就菊花」，句中「還」字的詞性與下列何者相同？", "options": {"A": "「明」月松間照", "B": "把「酒」話桑麻", "C": "白日依山「盡」", "D": "「但」使願無違"}, "answer": "D", "explain": "「還來」的「還」是「再」，修飾動詞「來」，是副詞。(D)「但」是「只」，修飾後面的「使」，也是副詞，答案。(A)「明」修飾名詞「月」，是形容詞；(B)「酒」是「把」的受詞，是名詞；(C)「盡」是「落盡、消失」，是動詞。", "skill": "判斷詞性看它修飾誰：放在動詞前面、表示程度／範圍／時間的是副詞；修飾名詞的是形容詞。"}], "difficulty": "中", "label": "90年第二次基測", "year": 90, "kind": "基測"}, {"id": "bc90-2-15", "exam": "bc90-2", "nums": [15], "form": "單題", "img": "img/bc90-2-15.png", "source": "辛棄疾〈清平樂‧村居〉", "author": "辛棄疾", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "茅簷低小，溪上青青草。醉裡吳音相媚好，白髮誰家翁媼？　大兒鋤豆溪東，中兒正織雞籠，最喜小兒亡賴，溪頭臥剝蓮蓬。", "translation": "茅草屋的屋簷低矮，溪邊長滿青青的草。帶著醉意用吳地方言親暱交談的，是哪一家的白髮老公公、老婆婆？大兒子在溪東邊的豆田鋤草，二兒子正在編雞籠，最討人喜歡的是頑皮的小兒子，趴在溪邊剝蓮蓬吃。", "keywords": [{"w": "吳音", "m": "吳地（江南）方言"}, {"w": "相媚好", "m": "互相逗樂、親熱交談"}, {"w": "翁媼", "m": "老公公和老婆婆"}, {"w": "亡賴", "m": "同「無賴」，此指頑皮可愛"}], "questions": [{"n": 15, "stem": "辛棄疾〈清平樂〉：「茅簷低小，溪上青青草。醉裡吳音相媚好，白髮誰家翁媼？　大兒鋤豆溪東，中兒正織雞籠，最喜小兒亡賴，溪頭臥剝蓮蓬。」有關這闋詞的內容安排，次序為何？", "options": {"A": "先寫空間，再寫時間", "B": "先寫景物，再寫人情", "C": "先寫遠景，再寫近景", "D": "先寫事理，再寫感想"}, "answer": "B", "explain": "開頭「茅簷低小，溪上青青草」寫農村景物，接著寫老夫婦親熱交談、三個兒子各自做事，寫的是一家人的生活與情味，所以是先景物、後人情。(A)詞中沒有時間的推移；(C)茅簷、溪草都是眼前近景，沒有由遠到近的安排；(D)全詞是描寫，沒有講道理也沒有直接發表感想。", "skill": "分析結構時把每一句標上「景／人／事／理」，看標籤的先後順序就能判斷安排。"}], "difficulty": "易", "label": "90年第二次基測", "year": 90, "kind": "基測"}, {"id": "bc90-2-18", "exam": "bc90-2", "nums": [18], "form": "單題", "img": "img/bc90-2-18.png", "source": "《三國志‧吳書‧周瑜傳》", "author": "陳壽", "genre": "史傳人物", "types": ["句意理解", "文意推論"], "passage": "瑜少精意於音樂，雖三爵之後，其有闕誤，瑜必知之，知之必顧。故時人謠曰：「曲有誤，周郎顧。」", "translation": "周瑜年輕時就精通音樂，即使喝了三杯酒以後，演奏中只要有缺漏錯誤，周瑜一定知道，知道了一定會回頭看。所以當時的人編了歌謠說：「曲子彈錯了，周郎就會回頭看。」", "keywords": [{"w": "精意", "m": "專心鑽研"}, {"w": "爵", "m": "酒杯"}, {"w": "闕誤", "m": "缺漏、錯誤"}, {"w": "顧", "m": "回頭看，表示關注"}, {"w": "謠", "m": "編成歌謠傳唱"}], "questions": [{"n": 18, "stem": "「瑜少精意於音樂，雖三爵之後，其有闕誤，瑜必知之，知之必顧。故時人謠曰：『曲有誤，周郎顧。』」這段文字旨在說明周瑜具備什麼？", "options": {"A": "專精的音樂素養", "B": "嶔崎磊落的品格", "C": "犯顏直諫的勇氣", "D": "千杯不醉的海量"}, "answer": "A", "explain": "「精意於音樂」、即使喝了酒，曲子一有錯也立刻聽得出來，說明他音樂造詣很深。(B)品格正直光明、(C)敢於冒犯君主直言，文中都沒提到；(D)「三爵之後」只是強調喝酒後仍聽得出錯，重點不在酒量。", "skill": "抓主旨先找開頭的總說句（瑜少精意於音樂），後面的例子都是用來支持它的。"}], "difficulty": "易", "label": "90年第二次基測", "year": 90, "kind": "基測"}, {"id": "bc90-2-21", "exam": "bc90-2", "nums": [21], "form": "單題", "img": "img/bc90-2-21.png", "source": "(A)中華民國國歌；(B)白居易〈慈烏夜啼〉；(C)周敦頤〈愛蓮說〉；(D)《論語‧衛靈公》", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "(A)咨爾多士，為民前鋒 (B)嗟哉斯徒輩，其心不如禽 (C)噫！菊之愛，陶後鮮有聞 (D)其恕乎！己所不欲，勿施於人", "translation": "(A)啊！你們這些志士，要做人民的前鋒。(B)唉！這班人，他們的心連禽獸都不如。(C)唉！喜愛菊花的人，在陶淵明以後就很少聽說了。(D)大概就是「恕」吧！自己不想要的，不要加在別人身上。", "keywords": [{"w": "咨", "m": "嘆詞，表示呼告"}, {"w": "嗟哉", "m": "唉，嘆詞"}, {"w": "噫", "m": "唉，表示感嘆、惋惜"}, {"w": "鮮", "m": "少"}, {"w": "其……乎", "m": "大概……吧，表推測"}], "questions": [{"n": 21, "stem": "下列各句所傳達的語氣，何者說明錯誤？", "options": {"A": "「咨爾多士，為民前鋒」——期勉的語氣", "B": "「嗟哉斯徒輩，其心不如禽」——斥責的語氣", "C": "「噫！菊之愛，陶後鮮有聞」——驚訝的語氣", "D": "「其恕乎！己所不欲，勿施於人」——推測的語氣"}, "answer": "C", "explain": "〈愛蓮說〉的「噫！菊之愛，陶後鮮有聞」是感嘆陶淵明之後很少有人愛菊（隱逸者少），是感慨、惋惜的語氣，不是驚訝，所以說明錯誤。(A)國歌勉勵志士做人民前鋒，是期勉；(B)罵這些人心不如禽獸，是斥責；(D)「其……乎」表示「大概是……吧」，是推測語氣。", "skill": "嘆詞本身不決定語氣，要看後面接的內容：感嘆少有人做到→惋惜，罵人→斥責；「其……乎」固定表推測。"}], "difficulty": "中", "label": "90年第二次基測", "year": 90, "kind": "基測"}, {"id": "bc90-2-28", "exam": "bc90-2", "nums": [28], "form": "單題", "img": "img/bc90-2-28.png", "source": "秦觀〈鵲橋仙〉", "author": "秦觀", "genre": "古典詩詞曲", "types": ["詩詞賞析", "主旨寓意", "比較閱讀"], "passage": "纖雲弄巧，飛星傳恨，銀漢迢迢暗度。金風玉露一相逢，便勝卻人間無數。　柔情似水，佳期如夢，忍顧鵲橋歸路。兩情若是久長時，又豈在朝朝暮暮。", "translation": "纖細的雲彩變化出巧妙的花樣，飛逝的流星傳遞著離別的愁恨，牛郎織女悄悄渡過遙遠的銀河。在秋風白露中相會一次，就勝過人間無數次的相聚。柔情像流水一樣綿長，相會的美好時光像夢一樣短暫，怎忍心回頭看鵲橋上回去的路。兩人的感情如果長久不變，又何必在乎是否天天朝夕相處。", "keywords": [{"w": "銀漢", "m": "銀河"}, {"w": "迢迢", "m": "遙遠的樣子"}, {"w": "金風玉露", "m": "秋風白露，指七夕時節"}, {"w": "勝卻", "m": "勝過"}, {"w": "忍顧", "m": "怎忍回頭看"}, {"w": "朝朝暮暮", "m": "天天早晚在一起"}], "questions": [{"n": 28, "stem": "秦觀〈鵲橋仙〉：「纖雲弄巧，飛星傳恨，銀漢迢迢暗度。金風玉露一相逢，便勝卻人間無數。　柔情似水，佳期如夢，忍顧鵲橋歸路。兩情若是久長時，又豈在朝朝暮暮。」這闋詞對於感情的看法，與下列何者相似？", "options": {"A": "不在乎天長地久，只在乎曾經擁有", "B": "只要是此情長在，無須要常相廝守", "C": "問世間情是何物，直教人生死相許", "D": "衣帶漸寬終不悔，為伊消得人憔悴"}, "answer": "B", "explain": "末兩句「兩情若是久長時，又豈在朝朝暮暮」是說感情只要長久，不必天天在一起，與(B)相同。(A)恰好相反，詞人重視的正是感情的長久；(C)元好問的句子，強調情的力量大到使人以生死相許；(D)柳永的句子，寫為思念而消瘦也不後悔，重點是痴情執著，不是「不必常相守」。", "skill": "詞的主旨常在結尾，先把末句翻成白話，再找意思一致、而不只是「同樣寫愛情」的選項。"}], "difficulty": "易", "label": "90年第二次基測", "year": 90, "kind": "基測"}, {"id": "bc90-2-33", "exam": "bc90-2", "nums": [33], "form": "單題", "img": "img/bc90-2-33.png", "source": "(A)《論語‧八佾》；(B)周敦頤〈愛蓮說〉；(C)《論語‧為政》；(D)俗語", "author": "", "genre": "經典語錄", "types": ["虛詞句式"], "passage": "(A)君子無所爭，必也射乎 (B)蓮，花之君子者也 (C)樊遲曰：何謂也 (D)無魚，蝦也好", "translation": "(A)君子沒有什麼可爭的，如果一定要爭，大概就是射箭比賽吧。(B)蓮花是花中的君子。(C)樊遲說：「這是什麼意思呢？」(D)沒有魚，蝦子也好。", "keywords": [{"w": "也（句中）", "m": "表停頓，引起下文"}, {"w": "也（句末，判斷）", "m": "表肯定、判斷"}, {"w": "也（何謂也）", "m": "同「耶」，表疑問"}], "questions": [{"n": 33, "stem": "下列各句中的「也」字，何者表達停頓的語氣？", "options": {"A": "君子無所爭，必也射乎", "B": "蓮，花之君子者也", "C": "樊遲曰：何謂也", "D": "無魚，蝦也好"}, "answer": "A", "explain": "(A)「必也射乎」的「也」放在句中，讓語氣稍作停頓再帶出「射乎」，表停頓。(B)放在句末，配合「……者……也」表判斷、肯定；(C)「何謂也」的「也」通「耶」，表疑問；(D)白話「也」是副詞，表示「同樣、亦」。", "skill": "文言「也」先看位置：句末多表判斷或疑問（看有無疑問詞），句中多表停頓；白話的「也」是副詞「亦」。"}], "difficulty": "中", "label": "90年第二次基測", "year": 90, "kind": "基測"}, {"id": "bc90-2-34", "exam": "bc90-2", "nums": [34], "form": "單題", "img": "img/bc90-2-34.png", "source": "命題者自撰書信", "author": "", "genre": "書信序跋", "types": ["文化常識"], "passage": "父母親大人鈞鑒：八月二十五日拜別足下，乘車抵達學校，隨即辦理入學手續，並住進第一宿舍二○三室，一切均安，懇釋慈念。敬祝大安　兒文風叩上　八月二十六日", "translation": "父母親大人：八月二十五日拜別您們後，搭車到了學校，馬上辦好入學手續，住進第一宿舍二○三室，一切都平安，請放下掛念。敬祝平安。兒子文風敬上。", "keywords": [{"w": "膝下", "m": "對父母、祖父母的提稱語"}, {"w": "鈞鑒", "m": "對長官的提稱語"}, {"w": "足下", "m": "對平輩的稱呼"}, {"w": "大安", "m": "對平輩的問候語（對父母用「福安」「金安」）"}, {"w": "叩上", "m": "對尊親長輩的末啟詞"}], "questions": [{"n": 34, "stem": "文風寫信給雙親。信上畫線部分何者正確？", "options": {"A": "鈞鑒", "B": "足下", "C": "大安", "D": "叩上"}, "answer": "D", "explain": "寫給父母時，末啟詞用「叩上」「敬稟」等，表示恭敬，(D)正確。(A)「鈞鑒」用於長官，對父母應用「膝下」；(B)「足下」是對平輩的稱呼，不能用來稱父母；(C)「大安」是對平輩的問候，對父母應用「福安」或「金安」。", "skill": "書信用語依「收信人身分」分級：父母祖父母（膝下、福安、叩上）、師長（尊前、道安）、長官（鈞鑒、鈞安）、平輩（大鑒、大安），逐一配對檢查。"}], "difficulty": "中", "label": "90年第二次基測", "year": 90, "kind": "基測"}, {"id": "bc90-2-35", "exam": "bc90-2", "nums": [35, 36], "form": "題組", "img": "img/bc90-2-35.png", "source": "俞樾〈一笑〉", "author": "俞樾", "genre": "筆記小品", "types": ["文意推論", "字詞解釋", "主旨寓意"], "passage": "有漁婦素不蓄鏡，每日梳洗，以水自鑒而已。其夫偶為買一鏡歸，婦取視之，驚告其姑曰：「吾夫又娶一新婦來矣！」姑取視之，嘆曰：「娶婦猶可，奈何并與親家母俱來！」", "translation": "有個漁夫的妻子向來不擁有鏡子，每天梳洗，只用水面照自己罷了。她丈夫偶然替她買了一面鏡子回家，她拿起來一看，驚慌地告訴婆婆說：「我丈夫又娶了一個新媳婦回來了！」婆婆拿過來一看，嘆氣說：「娶個媳婦還算可以，為什麼連親家母也一起帶來了！」", "keywords": [{"w": "素", "m": "向來、平常"}, {"w": "蓄", "m": "擁有、存放"}, {"w": "鑒", "m": "照"}, {"w": "姑", "m": "婆婆（丈夫的母親）"}, {"w": "猶可", "m": "還可以"}, {"w": "奈何", "m": "為什麼、怎麼"}, {"w": "俱", "m": "一起"}], "questions": [{"n": 35, "stem": "由上文可知，漁人家中發生什麼事？", "options": {"A": "漁人之婦因年老色衰被丈夫遺棄", "B": "漁人之婦及婆婆皆遭到新婦欺凌", "C": "漁人之婦因生活經驗的限制而自尋苦惱", "D": "漁人因愛屋及烏，也邀請新岳母來同住"}, "answer": "C", "explain": "漁婦和婆婆從沒用過鏡子，把鏡中自己的影像誤認為別人，一個以為丈夫娶了新婦，一個以為親家母也來了，其實根本沒有人來，是因見識有限而自己製造煩惱。(A)(B)(D)都把誤會當成真的發生了，丈夫並沒有娶妻，也沒有人欺凌或同住。", "skill": "笑話題要找「笑點」：人物以為發生了什麼 vs. 實際上發生了什麼，答案通常在兩者的落差。"}, {"n": 36, "stem": "下列「」中的說明何者正確？", "options": {"A": "有漁婦「素不蓄鏡」——容貌醜陋，不喜歡照鏡子", "B": "每日梳洗，「以水自鑒而已」——強調水是大自然中最好的保養品", "C": "「其夫偶為買一鏡歸」，婦取視之——漁夫買鏡送給新娶的老婆來表達情意", "D": "「娶婦猶可」，奈何并與親家母俱來——漁夫之母認為兒子娶新婦是無妨的"}, "answer": "D", "explain": "「娶婦猶可」意思是「娶個新媳婦還說得過去」，表示婆婆認為兒子娶新婦還可以接受，(D)正確。(A)「素不蓄鏡」只是向來沒有鏡子，文中沒說她醜；(B)「以水自鑒」是用水當鏡子照，不是講保養；(C)鏡子是買給原本的妻子，並沒有新娶的老婆。", "skill": "解釋句意時先查關鍵字（蓄＝擁有、鑒＝照、猶可＝還可以），再檢查選項有沒有加入原文沒有的內容。"}], "difficulty": "易", "label": "90年第二次基測", "year": 90, "kind": "基測"}, {"id": "bc90-2-37", "exam": "bc90-2", "nums": [37, 38, 39], "form": "題組", "img": "img/bc90-2-37.png", "source": "司馬遷《史記‧平原君虞卿列傳》", "author": "司馬遷", "genre": "史傳人物", "types": ["人物情感", "句意理解", "字詞解釋"], "passage": "秦之圍邯鄲，趙使平原君求救，合從於楚，約與食客門下有勇力文武備具者二十人偕……得十九人，餘無可取者，無以滿二十人。門下有毛遂者，前。自贊於平原君曰：「……今少一人，願君即以遂備員而行矣。」平原君曰：「先生處勝之門下，幾年於此矣？」毛遂曰：「三年於此矣。」平原君曰：「夫賢士之處世也，譬若錐之處囊中，其末立見……先生不能，先生留！」毛遂曰：「臣乃今日請處囊中耳！使遂蚤得處囊中，乃穎脫而出，非特其末見而已。」平原君竟與毛遂偕。", "translation": "秦國包圍邯鄲，趙王派平原君去求救，要和楚國締結合縱盟約。平原君打算從門下食客中挑選有勇力、文武兼備的二十人同行……只選到十九人，其餘沒有可取的，湊不滿二十人。門下有個叫毛遂的人走上前，向平原君推薦自己說：「……現在還少一人，希望您就讓我湊足人數一起去吧。」平原君說：「先生在我門下幾年了？」毛遂說：「三年了。」平原君說：「賢能的人活在世上，就像錐子放在袋子裡，尖端立刻就會露出來……先生（三年都沒表現）是沒有才能，先生留下吧！」毛遂說：「我就是今天才請求放進袋子裡啊！假如我早一點被放進袋子裡，整個錐身都會脫穎而出，不只是尖端露出來而已。」平原君終於帶毛遂一起去了。", "keywords": [{"w": "偕", "m": "一同"}, {"w": "自贊", "m": "自我推薦"}, {"w": "備員", "m": "湊足人數"}, {"w": "勝", "m": "平原君趙勝自稱"}, {"w": "錐", "m": "鑽孔用的尖銳器具"}, {"w": "見（ㄒㄧㄢˋ）", "m": "通「現」，顯露"}, {"w": "蚤", "m": "通「早」"}, {"w": "穎脫", "m": "錐身整個露出（穎：錐尖以下的部分）"}, {"w": "非特", "m": "不只"}], "questions": [{"n": 37, "stem": "從毛遂與平原君的對話，可以看出毛遂的個性如何？", "options": {"A": "韜光養晦", "B": "勇於表現", "C": "目中無人", "D": "自怨自艾"}, "answer": "B", "explain": "毛遂主動上前「自贊」推薦自己，被質疑時還能據理反駁，表現出勇於表現自我的個性。(A)韜光養晦是隱藏才能，與他主動自薦相反，且對話中看不出他之前是否刻意隱藏；(C)他態度自信但仍稱「臣」、請求機會，不是目中無人；(D)他沒有怨嘆自己。", "skill": "人物個性題只能根據題目指定的範圍（這段對話）中的言行來判斷，不要加入文本外的推測。"}, {"n": 38, "stem": "平原君曰：「夫賢士之處世也，譬若錐之處囊中，其末立見」的意思為何？", "options": {"A": "有才華必立即展現", "B": "才情應該深藏不露", "C": "人才必等伯樂而顯", "D": "賢才可以改造時代"}, "answer": "A", "explain": "錐子放在袋中，尖端馬上就會刺出來；比喻真正有才能的人，很快就會顯露出來。所以平原君認為毛遂三年沒被注意，代表沒有才能。(B)與「末立見」相反；(C)比喻強調才能自然顯露，不是等人發掘；(D)與比喻無關。", "skill": "比喻句先找喻體與喻依的對應（錐＝賢士、囊＝世間、末立見＝才能立刻顯露），再把對應換回去。"}, {"n": 39, "stem": "毛遂曰：「臣乃今日請處囊中耳！使遂蚤得處囊中，乃穎脫而出，非特其末見而已。」這段話的意義為何？", "options": {"A": "承蒙厚愛，愧不敢當", "B": "才能平庸，猶待歷練", "C": "適才適所，必能有為", "D": "沈寂無聞，必然無才"}, "answer": "C", "explain": "毛遂說自己今天才請求被放進袋中，假如早點有機會，整個錐身都會露出來——意思是有才能的人只要被放在適合的位置、得到機會，必能大有作為，(C)正確。(A)他是在爭取機會，不是謙讓；(B)他認為自己有才，不是平庸；(D)是平原君的看法，正是毛遂要反駁的。", "skill": "對話中的反駁句，要先弄清對方原本的論點，再看說話者如何翻轉：平原君「沒露出就是無才」→毛遂「沒機會進袋子，給機會才能顯露」。"}], "difficulty": "中", "label": "90年第二次基測", "year": 90, "kind": "基測"}, {"id": "bc91-1-3", "exam": "bc91-1", "nums": [3], "form": "單題", "img": "img/bc91-1-3.png", "source": "(A)白居易〈問劉十九〉；(B)王維〈送別〉（山中相送罷）；(C)張祜〈宮詞〉；(D)賈島〈尋隱者不遇〉", "author": "白居易、王維、張祜、賈島", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "(A)綠螘新醅酒，紅泥小火爐。晚來天欲雪，能飲一杯無？(B)山中相送罷，日暮掩柴扉。春草明年綠，王孫歸不歸？(C)故國三千里，深宮二十年。一聲何滿子，雙淚落君前。(D)松下問童子，言師採藥去。只在此山中，雲深不知處。", "translation": "(A)新釀的酒浮著綠色酒渣，紅泥小火爐正燒著。傍晚天快下雪了，能來喝一杯嗎？(B)在山中送別了朋友，傍晚關上柴門。明年春草再綠時，你回不回來呢？(C)離家鄉三千里，在深宮住了二十年。一唱起〈何滿子〉，眼淚就在君王面前落下。(D)在松樹下問隱者的童子，他說師父採藥去了。就在這座山裡，只是雲太深，不知道在哪裡。", "keywords": [{"w": "綠螘", "m": "酒面浮起的綠色泡沫，代指美酒"}, {"w": "醅", "m": "未過濾的酒"}, {"w": "無", "m": "句末疑問詞，同「否」"}, {"w": "王孫", "m": "指遠行的友人"}, {"w": "言", "m": "（童子）說"}], "questions": [{"n": 3, "stem": "下列各詩，何者是「有問有答」的寫法？", "options": {"A": "「綠螘新醅酒，紅泥小火爐。晚來天欲雪，能飲一杯無？」", "B": "「山中相送罷，日暮掩柴扉。春草明年綠，王孫歸不歸？」", "C": "「故國三千里，深宮二十年。一聲何滿子，雙淚落君前。」", "D": "「松下問童子，言師採藥去。只在此山中，雲深不知處。」"}, "answer": "D", "explain": "(D)詩人「問童子」，後三句「言師採藥去。只在此山中，雲深不知處」是童子的回答，問句省略、答句寫出，是有問有答的寫法。(A)以「能飲一杯無？」邀請朋友，只有問沒有答；(B)「王孫歸不歸？」是設想明年的疑問，也沒有回答；(C)是敘述宮女的悲哀，沒有問答。", "skill": "找「問」的動作或問句後，檢查後文有沒有出現回答的內容；只有問句結尾的是「有問無答」。"}], "difficulty": "易", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-1-7", "exam": "bc91-1", "nums": [7], "form": "單題", "img": "img/bc91-1-7.png", "source": "(C)唐寅〈元宵〉；(D)蘇軾〈陽關曲‧中秋月〉；(A)(B)出處待查", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "詩詞賞析"], "passage": "(A)爆竹聲中歲又除，頓回和氣滿寰區。春風解綠江南樹，不與人間染白鬚。(B)鼓聲三下紅旗開，兩龍躍出浮水來。棹影斡波飛萬劍，鼓聲劈浪鳴千雷。(C)有燈無月不娛人，有月無燈不算春。春到人間人似玉，燈燒月下月如銀。(D)暮雲收盡溢清寒，銀漢無聲轉玉盤。此生此夜不長好，明年明月何處看。", "translation": "(A)在爆竹聲中又過完一年，祥和之氣頓時充滿天下；春風能吹綠江南的樹，卻不能把人間的白鬍子染黑。(B)鼓敲三下、紅旗一揮，兩條龍船躍出水面；船槳翻動水波像萬把飛劍，鼓聲劈開浪花像千聲雷響。(C)有燈沒月亮不好玩，有月亮沒燈不像春天；春到人間人像玉一樣美，燈在月下照耀，月光如銀。(D)晚雲散盡，清冷的寒氣瀰漫，銀河無聲，明月像玉盤般轉動；這一生這樣美好的夜晚不常有，明年的明月要在哪裡看呢？", "keywords": [{"w": "歲除", "m": "一年結束，除夕"}, {"w": "寰區", "m": "全國、全天下"}, {"w": "棹", "m": "船槳"}, {"w": "斡", "m": "運轉、旋轉"}, {"w": "銀漢", "m": "銀河"}, {"w": "玉盤", "m": "比喻圓月"}], "questions": [{"n": 7, "stem": "下列描繪節慶景象的詩句，何者所對應的節日正確？", "options": {"A": "爆竹聲中歲又除，頓回和氣滿寰區。春風解綠江南樹，不與人間染白鬚——元宵", "B": "鼓聲三下紅旗開，兩龍躍出浮水來。棹影斡波飛萬劍，鼓聲劈浪鳴千雷——端午", "C": "有燈無月不娛人，有月無燈不算春。春到人間人似玉，燈燒月下月如銀——中秋", "D": "暮雲收盡溢清寒，銀漢無聲轉玉盤。此生此夜不長好，明年明月何處看——七夕"}, "answer": "B", "explain": "(B)鼓聲、紅旗、兩條龍船競渡、船槳翻浪，寫的是端午節划龍舟，正確。(A)「爆竹聲中歲又除」是除夕、新年，不是元宵；(C)又有燈又有月、「不算春」，是正月十五元宵節賞燈，不是中秋；(D)「轉玉盤」寫圓月，是蘇軾的中秋詩，不是七夕（七夕月亮是彎月）。", "skill": "抓每首詩的「節日關鍵物」：爆竹＝除夕新年、燈＋月＋春＝元宵、龍舟鼓聲＝端午、圓月玉盤＝中秋、牛郎織女鵲橋＝七夕。"}], "difficulty": "中", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-1-9", "exam": "bc91-1", "nums": [9], "form": "單題", "img": "img/bc91-1-9.png", "source": "王陽明語（出處待查）", "author": "王守仁", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "智者不以無過為喜，人之大德在於改過，做一新人。", "translation": "有智慧的人不以「沒有犯錯」為可喜，人最大的美德在於能改正過錯，重新做一個新的人。", "keywords": [{"w": "不以……為喜", "m": "不把……當作可喜的事"}, {"w": "大德", "m": "最盛美的德行"}], "questions": [{"n": 9, "stem": "王陽明說：「智者不以無過為喜，人之大德在於改過，做一新人。」這段話最主要的意思是什麼？", "options": {"A": "說明人非聖賢，孰能無過", "B": "勉勵人謹言慎行，避免犯錯", "C": "強調知過改過、日新又新的重要性", "D": "指出智者以有過為喜、以重生為榮"}, "answer": "C", "explain": "重點在「人之大德在於改過，做一新人」，強調知錯能改、不斷更新自己，(C)正確。(A)只說到人都會犯錯，沒有點出「改過」這個重點；(B)要人避免犯錯，與「不以無過為喜」的意思相反；(D)「不以無過為喜」不等於「以有過為喜」，犯錯本身並不可喜，可喜的是改過。", "skill": "「不以A為喜」不能直接反推成「以非A為喜」；找主旨要看句中下判斷的「大德在於……」。"}], "difficulty": "易", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-1-14", "exam": "bc91-1", "nums": [14], "form": "單題", "img": "img/bc91-1-14.png", "source": "題幹改寫自王安石〈傷仲永〉；(A)《論語‧學而》；(B)彭端淑〈為學一首示子姪〉；(C)《淮南子‧說山》；(D)《孟子‧告子上》", "author": "", "genre": "說理議論", "types": ["主旨寓意", "比較閱讀"], "passage": "(A)學而時習之，不亦說乎 (B)聰與敏，可恃而不可恃也 (C)謂學不暇給者，雖暇亦不能學 (D)一日暴之，十日寒之，未有能生者也", "translation": "(A)學習了又時常溫習，不也很快樂嗎？(B)聰明和敏捷，可以依靠卻又不能完全依靠。(C)說忙得沒時間學習的人，即使有空也不會學習。(D)曬一天太陽，又凍十天，沒有能生長的。", "keywords": [{"w": "說", "m": "同「悅」，快樂"}, {"w": "恃", "m": "依靠"}, {"w": "不暇給", "m": "忙得沒空"}, {"w": "暴（ㄆㄨˋ）", "m": "同「曝」，曬"}], "questions": [{"n": 14, "stem": "「方仲永為一農家子弟，五歲時無師自通寫了一首詩，不但極富意義，文詞運用亦巧妙，眾人皆讚為奇才。其父遂帶領仲永四處展現才藝，卻未曾安排他接受教育。久之，仲永奇才就不復存在了。」下列何者最貼近以上這則故事的寓意？", "options": {"A": "學而時習之，不亦說乎", "B": "聰與敏，可恃而不可恃也", "C": "謂學不暇給者，雖暇亦不能學", "D": "一日暴之，十日寒之，未有能生者也"}, "answer": "B", "explain": "方仲永天資聰穎，卻因沒有接受教育而才能消失，說明天分不能完全依靠，還要後天學習，與(B)「聰明敏捷可以依靠，卻也不能只依靠」最貼近。(A)講學習溫習的快樂；(C)批評以沒空為藉口不學習的人；(D)比喻做事不能持之以恆，仲永不是時學時停，而是根本沒學。", "skill": "寓意題先用一句話概括故事（天才不學→才能消失），再把文言選項逐一翻成白話比對核心概念。"}], "difficulty": "中", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-1-17", "exam": "bc91-1", "nums": [17], "form": "單題", "img": "img/bc91-1-17.png", "source": "陳子昂〈登幽州臺歌〉；(D)崔顥〈黃鶴樓〉", "author": "陳子昂", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "前不見古人，後不見來者。念天地之悠悠，獨愴然而涕下。", "translation": "往前看不到古代的賢君，往後看不到未來的明主。想到天地如此遼闊無窮，獨自悲傷地流下眼淚。", "keywords": [{"w": "悠悠", "m": "空闊無際、長遠無窮"}, {"w": "愴然", "m": "悲傷的樣子"}, {"w": "涕", "m": "眼淚"}], "questions": [{"n": 17, "stem": "翻開辭典，可看到詞義及例證的說明。以下的詞義與例證，何者與陳子昂詩句「前不見古人，後不見來者。念天地之悠悠，獨愴然而涕下。」中的「悠悠」詞義相同？", "options": {"A": "憂思，如「悠悠我思」", "B": "眾多，如「悠悠者天下皆是」", "C": "荒謬不合事理，如「悠悠之談」", "D": "空闊無際，如「白雲千載空悠悠」"}, "answer": "D", "explain": "「天地之悠悠」形容天地遼闊無窮，是「空闊無際」的意思，與崔顥「白雲千載空悠悠」（白雲在天空長久飄蕩）相同。(A)憂思、(B)眾多、(C)荒謬，都不能用來形容天地。", "skill": "一詞多義題先看詞語修飾的對象（天地），再把各選項的義項代入原句，通順合理的就是答案。"}], "difficulty": "易", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-1-27", "exam": "bc91-1", "nums": [27], "form": "單題", "img": "img/bc91-1-27.png", "source": "陶淵明〈歸園田居〉其三", "author": "陶淵明", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "種豆南山下，草盛豆苗稀。晨興理荒穢，帶月荷鋤歸。道狹草木長，夕露沾我衣。衣沾不足惜，但使願無違。", "translation": "在南山下種豆，雜草茂盛，豆苗卻很稀少。清晨起來去清除雜草，傍晚披著月光扛著鋤頭回家。小路狹窄、草木叢生，夜晚的露水沾濕了我的衣服。衣服濕了不值得可惜，只要不違背我歸隱田園的心願就好。", "keywords": [{"w": "晨興", "m": "早上起來"}, {"w": "荒穢", "m": "田中的雜草"}, {"w": "荷", "m": "扛著"}, {"w": "但使", "m": "只要"}, {"w": "願", "m": "歸隱躬耕的心願"}], "questions": [{"n": 27, "stem": "「種豆南山下，草盛豆苗稀。晨興理荒穢，帶月荷鋤歸。道狹草木長，夕露沾我衣。衣沾不足惜，但使願無違。」若不論本詩的創作年代，如何從其結構判斷它不是「五言律詩」？", "options": {"A": "句數太多", "B": "偶數句沒有押韻", "C": "第二聯及第三聯均無對仗", "D": "不合乎起承轉合的型式"}, "answer": "C", "explain": "五言律詩規定八句，且中間第二聯（頷聯）、第三聯（頸聯）必須對仗。本詩「晨興理荒穢，帶月荷鋤歸」「道狹草木長，夕露沾我衣」都不對仗，所以不是律詩。(A)本詩正好八句，句數符合；(B)偶數句「稀、歸、衣、違」都押韻；(D)全詩依序寫種豆、勞動、歸途、心願，仍有起承轉合。", "skill": "判斷近體詩先數句數（絕句4、律詩8），再查偶數句押韻，最後檢查律詩中間兩聯是否對仗。"}], "difficulty": "中", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-1-29", "exam": "bc91-1", "nums": [29], "form": "單題", "img": "img/bc91-1-29.png", "source": "(C)《列子‧湯問》〈愚公移山〉；(D)《論語‧子路》（今本作「民無所措手足」）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)盤根錯節 (B)不知所措 (C)移一山厝朔東 (D)民安所錯其手足", "translation": "(A)樹根盤曲、枝節交錯。(B)不知道該把手腳放在哪裡（慌張失措）。(C)把一座山放到朔方的東邊。(D)人民要把手腳放在哪裡（不知如何是好）。", "keywords": [{"w": "錯（盤根錯節）", "m": "交錯、交雜"}, {"w": "措", "m": "安置、放置"}, {"w": "厝", "m": "放置"}, {"w": "錯（民安所錯）", "m": "同「措」，安置"}, {"w": "安", "m": "何、哪裡"}], "questions": [{"n": 29, "stem": "下列各句「」中的字義，何者與其他三者不同？", "options": {"A": "盤根「錯」節", "B": "不知所「措」", "C": "移一山「厝」朔東", "D": "民安所「錯」其手足"}, "answer": "A", "explain": "(A)「盤根錯節」的「錯」是交錯、交雜。(B)「措」、(C)「厝」、(D)「錯」（通「措」）都是「安置、放置」的意思，所以(A)與其他三者不同。", "skill": "形近、音近字（錯、措、厝）在文言中常可通用為「安置」；遇到同一字時要看詞語結構，「錯節」與「盤根」相對，是交錯義。"}], "difficulty": "中", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-1-31", "exam": "bc91-1", "nums": [31], "form": "單題", "img": "img/bc91-1-31.png", "source": "情境取材〈木蘭詩〉", "author": "", "genre": "其他", "types": ["文化常識", "字詞解釋"], "passage": "（題目考古代城市名稱：郭、市、闕）", "translation": "郭：外城；市：城中做買賣的市集；闕：宮門前兩側的樓臺，代指宮殿。", "keywords": [{"w": "郭", "m": "外城（城牆外圍的城）"}, {"w": "市", "m": "市集、市場"}, {"w": "闕", "m": "宮門兩側的高臺，借指宮廷"}], "questions": [{"n": 31, "stem": "下圖為「木蘭凱旋歸來，自城外入宮朝觀天子」的路線圖，她途中所經之地的正確順序是什麼？", "options": {"A": "郭→市→闕", "B": "市→郭→闕", "C": "市→闕→郭", "D": "闕→市→郭"}, "answer": "A", "explain": "從城外進來，先經過外城城牆「郭」，再穿過城中熱鬧的「市」集，最後到達宮門「闕」朝見天子。圖中由左到右依序是田野、城牆（郭）、市集人群（市）、宮殿（闕），所以是(A)。", "skill": "文化常識題先把古代名詞翻成現代概念（郭＝外城、市＝市場、闕＝宮門），再對照圖片的空間順序。"}], "difficulty": "易", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-1-35", "exam": "bc91-1", "nums": [35, 36, 37], "form": "題組", "img": "img/bc91-1-35.png", "source": "鄭燮〈濰縣署中寄舍弟墨第四書〉", "author": "鄭燮（鄭板橋）", "genre": "書信序跋", "types": ["文意推論", "字詞解釋", "句意理解"], "passage": "吾輩讀書人，入則孝，出則弟，守先待後，得志，澤加於民；不得志，修身見於世；所以又高於農夫一等。今則不然，一捧書本，便想中舉人，中進士，作官如何攫取金錢，造大房屋，置多田產。起手便錯走了路頭，後來越做越壞，總沒有個好結果。其不能發達者，鄉里作惡，小頭銳面，更不可當。夫束修自好者，豈無其人？經濟自期，抗懷千古者，亦所在多有；而好人為壞人所累，遂令我輩開不得口。", "translation": "我們讀書人，在家孝順父母，出外敬愛兄長，守住先賢的學問來傳給後人；得志時，把恩澤施給百姓；不得志時，修養自身以表現於世；所以地位比農夫高一等。現在卻不是這樣，一拿起書本，就想考中舉人、進士，想著做官如何搜刮金錢、蓋大房子、買很多田產。一開始就走錯了路，後來越做越壞，總沒有好結果。那些沒能飛黃騰達的，就在鄉里作惡，一副尖頭尖臉、鑽營取巧的樣子，更叫人受不了。那些約束自己、潔身自愛的人，難道沒有嗎？以經世濟民自我期許、志向與古人相比的人，也到處都有；只是好人被壞人連累，使我們讀書人說不出話來。", "keywords": [{"w": "弟（ㄊㄧˋ）", "m": "同「悌」，敬愛兄長"}, {"w": "守先待後", "m": "守住先賢之道，以傳給後人"}, {"w": "澤加於民", "m": "把恩澤施給百姓"}, {"w": "見（ㄒㄧㄢˋ）", "m": "同「現」，表現"}, {"w": "攫取", "m": "奪取"}, {"w": "小頭銳面", "m": "頭小臉尖，形容鑽營取巧的樣子"}, {"w": "束修自好", "m": "約束自己、潔身自愛"}, {"w": "經濟", "m": "經世濟民"}, {"w": "抗懷千古", "m": "志向高遠，可與古人相比"}, {"w": "累", "m": "連累"}], "questions": [{"n": 35, "stem": "作者認為當時讀書人受尊重的程度不如從前，其主要原因何在？", "options": {"A": "讀書的方法不同", "B": "讀書的態度不同", "C": "讀書的目的不同", "D": "讀書的內容不同"}, "answer": "C", "explain": "以前讀書人讀書是為了修身、「澤加於民」；現在「一捧書本，便想中舉人，中進士，作官如何攫取金錢」，讀書變成求官發財的工具，關鍵是讀書的目的改變了。文中沒有比較讀書方法(A)、內容(D)；(B)態度太籠統，文中對比的是「為什麼讀書」。", "skill": "找「今昔對比」的文章，把「從前……」和「今則不然……」並排，看兩邊差在哪一個層面。"}, {"n": 36, "stem": "本文中的詞語應用在口語中，下列何者最恰當？", "options": {"A": "初生嬰兒「小頭銳面」、小手小腳的嬌憨模樣，真是可愛", "B": "為政者若能造福鄉里，「澤加於民」，就會得到百姓的愛戴", "C": "她的歌聲有如黃鶯出谷，當代難得一見，可說是「抗懷千古」", "D": "歌迷們「守先待後」，將演唱會後台團團圍住，等待偶像出現"}, "answer": "B", "explain": "「澤加於民」是把恩惠施給百姓，用來形容為政者造福鄉里，正確。(A)「小頭銳面」是貶義，形容鑽營取巧的樣子，不能形容可愛的嬰兒；(C)「抗懷千古」指志向高遠可比古人，不是形容歌聲；(D)「守先待後」是傳承先賢之道，不是「先到先等」。", "skill": "詞語運用題先確認詞語的正確意思和褒貶，再檢查選項是否只是「望文生義」。"}, {"n": 37, "stem": "「夫束修自好者，豈無其人？經濟自期，抗懷千古者，亦所在多有」，是在說明什麼？", "options": {"A": "只要潔身自好，一定有欣賞自己的人", "B": "有志節的讀書人，往往出於亂世之中", "C": "世人都嚮往功名利祿，唯讀書人能堅定自持", "D": "雖然世風日下，但是仍有懷抱理想的讀書人"}, "answer": "D", "explain": "「豈無其人？」是反問，意思是「當然有這樣的人」；「亦所在多有」是「到處都有」。作者在批評讀書人風氣敗壞之後，補充說明仍有潔身自愛、懷抱理想的讀書人，(D)正確。(A)文中沒說會有人欣賞；(B)沒有提到亂世；(C)作者正是批評許多讀書人追求功名利祿，不是「唯讀書人能堅定自持」。", "skill": "反問句「豈無……？」要轉成肯定句「一定有……」，再配合上下文判斷作者的語意轉折。"}], "difficulty": "中", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-1-38", "exam": "bc91-1", "nums": [38, 39], "form": "題組", "img": "img/bc91-1-38.png", "source": "《世說新語‧德行》", "author": "劉義慶", "genre": "筆記小品", "types": ["主旨寓意", "人物情感", "典故出處"], "passage": "庾公乘馬有的盧，或語令賣去。庾云：「賣之必有買者，即當害其主。寧有不安己而移於他人哉？昔孫叔敖殺兩頭蛇以為後人，古之美談。效之，不亦達乎？」", "translation": "庾亮騎的馬中有一匹「的盧」（被認為會害主人的凶馬），有人勸他把馬賣掉。庾亮說：「賣掉牠一定有人買，那就會害了新主人。哪有對自己不利就轉嫁給別人的道理呢？從前孫叔敖殺死兩頭蛇是為了後來的人，是古代的美談。我效法他，不也是通達事理嗎？」", "keywords": [{"w": "的盧", "m": "額有白斑的馬，傳說會妨害主人，指凶馬"}, {"w": "或", "m": "有人"}, {"w": "語（ㄩˋ）", "m": "告訴"}, {"w": "寧", "m": "難道、哪裡"}, {"w": "孫叔敖殺兩頭蛇", "m": "傳說見兩頭蛇者必死，孫叔敖殺而埋之，以免他人再見"}, {"w": "達", "m": "通達事理"}], "questions": [{"n": 38, "stem": "本文的主旨在說明庾公為人如何？", "options": {"A": "不迷信、不貪財利", "B": "安分守己，逆來順受", "C": "欲效法孫叔敖，追求美名", "D": "有「己所不欲，勿施於人」的精神"}, "answer": "D", "explain": "庾亮認為凶馬賣給別人就會害了別人，「寧有不安己而移於他人哉？」自己不想要的禍害，不轉嫁給別人，正是「己所不欲，勿施於人」。(A)他仍相信的盧會害主，談不上不迷信，文章重點也不在不貪財；(B)文中不是在講忍受不幸；(C)效法孫叔敖是為了不害他人，不是為了追求美名。", "skill": "人物主旨題抓人物的關鍵句（寧有不安己而移於他人哉），把它轉成一句常見格言再比對選項。"}, {"n": 39, "stem": "本文的寫作手法著重在描寫什麼？", "options": {"A": "人物的神采風度", "B": "歷史的真實事蹟", "C": "理想的幻滅", "D": "風土與人情"}, "answer": "A", "explain": "《世說新語》擅長用一件小事、一兩句話表現人物的品格風度，本文藉庾亮對凶馬的處理表現他推己及人的胸懷，著重描寫人物的神采風度。(B)重點不在考證史實；(C)(D)文中都沒有。", "skill": "認識文本類型的特色：《世說新語》＝記人物言行、重神采風度的筆記小說。"}], "difficulty": "中", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-1-40", "exam": "bc91-1", "nums": [40, 41], "form": "題組", "img": "img/bc91-1-40.png", "source": "《佛光詩語》", "author": "", "genre": "古典詩詞曲", "types": ["句意理解", "主旨寓意"], "passage": "回憶當年我養兒，我兒今又養孫兒，我兒餓我由他餓，莫教孫兒餓我兒。", "translation": "回想當年我養育兒子，如今兒子又在養育孫子。兒子讓我挨餓就隨他讓我餓吧，可千萬別讓孫子將來也讓我兒子挨餓。", "keywords": [{"w": "由他", "m": "隨他、任憑他"}, {"w": "莫教", "m": "不要讓"}, {"w": "餓我", "m": "使我挨餓（「餓」作使動用法）"}], "questions": [{"n": 40, "stem": "詩中「父、子、孫」三人，正在挨餓的是誰？", "options": {"A": "父", "B": "子", "C": "孫", "D": "父、子"}, "answer": "A", "explain": "「我兒餓我」是「兒子使我挨餓」，所以正在挨餓的是說話的「我」，也就是父親。「莫教孫兒餓我兒」是希望將來孫子不要讓兒子挨餓，兒子現在並沒有挨餓。七言詩一般為上四下三，第三句應讀作「我兒餓我／由他餓」。", "skill": "注意「餓我」的使動用法（使我餓），並按七言詩上四下三的節奏斷句。"}, {"n": 41, "stem": "這首詩的主旨在表達什麼？", "options": {"A": "百善孝為先", "B": "父母對子女無悔的愛", "C": "子女有奉養父母的責任", "D": "受西方風氣影響，中國孝道不存"}, "answer": "B", "explain": "父親被兒子餓著，卻說「由他餓」，不計較，反而擔心兒子將來被孫子虧待，表現出父母對子女無怨無悔的愛。(A)(C)是從子女角度講孝道，但詩人並沒有要求兒子奉養；(D)詩中沒有提到西方風氣。", "skill": "主旨題要從說話者的態度出發：他不責怪、反而替對方擔心→表現的是付出的愛。"}], "difficulty": "中", "label": "91年第一次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-4", "exam": "bc91-2", "nums": [4], "form": "單題", "img": "img/bc91-2-4.png", "source": "(A)李文炤〈勤訓〉；(B)文天祥事蹟（《宋史‧文天祥傳》）；(C)鄭燮〈寄弟墨書〉；(D)《列子‧湯問》〈愚公移山〉", "author": "", "genre": "史傳人物", "types": ["人物情感", "句意理解"], "passage": "頭可得，蘭不可得。(A)徒然食息於天地之間，一蠹耳 (B)宋亡，惟可死，不可生，願一死足矣 (C)我獨何人，貪求無厭，窮民將何所措手足乎 (D)子子孫孫，無窮匱也；而山不加增，何苦而不平", "translation": "我的頭可以拿去，蘭花卻不能畫給你。(A)白白在天地間吃飯呼吸，只是一隻蛀蟲罷了。(B)宋朝滅亡了，我只能死，不能活，只求一死就滿足了。(C)我是什麼人，怎能貪求沒有滿足，窮苦百姓要把手腳放在哪裡（怎麼活下去）呢？(D)子子孫孫沒有窮盡，而山不會增高，何愁挖不平？", "keywords": [{"w": "徒然", "m": "白白地"}, {"w": "蠹", "m": "蛀蟲，比喻無用之人"}, {"w": "惟", "m": "只"}, {"w": "無厭", "m": "不滿足"}, {"w": "措", "m": "安置"}, {"w": "匱", "m": "缺乏、窮盡"}], "questions": [{"n": 4, "stem": "宋末鄭思肖曾對著一個強迫他畫蘭的無理縣吏說：「頭可得，蘭不可得。」這樣的表現，與下列何人透過言語所流露的氣節相近？", "options": {"A": "慨歎「徒然食息於天地之間，一蠹耳」的李文炤", "B": "誓言「宋亡，惟可死，不可生，願一死足矣」的文天祥", "C": "自省「我獨何人，貪求無厭，窮民將何所措手足乎」的鄭板橋", "D": "堅信「子子孫孫，無窮匱也；而山不加增，何苦而不平」的愚公"}, "answer": "B", "explain": "鄭思肖寧可被殺也不屈從，表現寧死不屈的氣節；文天祥說宋亡後只求一死、不肯苟活，同樣是寧死不屈，(B)正確。(A)感慨不勞動的人是社會蛀蟲，講的是勤勞；(C)鄭板橋反省自己不可貪求，表現仁民愛物；(D)愚公表現的是堅持毅力，不是氣節。", "skill": "先把題幹人物的行為歸類成一種品格（寧死不屈），再看哪個選項人物的話也屬於同一類。"}], "difficulty": "易", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-11", "exam": "bc91-2", "nums": [11], "form": "單題", "img": "img/bc91-2-11.png", "source": "(A)金昌緒〈春怨〉；(B)李商隱〈登樂遊原〉；(C)汪洙〈神童詩‧四喜〉；(D)白居易〈慈烏夜啼〉", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)打起黃鶯兒，莫教枝上啼。啼時驚妾夢，不得到遼西。(B)向晚意不適，驅車登古原。夕陽無限好，只是近黃昏。(C)久旱逢甘雨，他鄉遇故知。洞房花燭夜，金榜題名時。(D)昔有吳起者，母歿喪不臨。嗟哉斯徒輩，其心不如禽。", "translation": "(A)把黃鶯趕走，別讓牠在樹枝上叫；牠一叫就驚醒我的夢，使我在夢中到不了遼西（見不到戍邊的丈夫）。(B)傍晚心情不好，駕車登上古老的高原；夕陽無比美好，只可惜已接近黃昏。(C)久旱遇到及時雨，在他鄉遇見老朋友，新婚之夜，考中功名之時。(D)從前有個吳起，母親死了也不回去奔喪；唉，這種人，他的心連禽鳥都不如。", "keywords": [{"w": "妾", "m": "古代女子自稱"}, {"w": "遼西", "m": "征夫戍守之地"}, {"w": "意不適", "m": "心情不愉快"}, {"w": "歿", "m": "死"}, {"w": "臨", "m": "親臨（奔喪）"}, {"w": "嗟哉", "m": "唉，感嘆詞"}], "questions": [{"n": 11, "stem": "下列各選項「」中的詩句所表達的心情，何者說明不正確？", "options": {"A": "打起黃鶯兒，莫教枝上啼。「啼時驚妾夢，不得到遼西」——開朗", "B": "向晚意不適，驅車登古原。「夕陽無限好，只是近黃昏」——惆悵", "C": "「久旱逢甘雨，他鄉遇故知。」洞房花燭夜，金榜題名時——驚喜", "D": "昔有吳起者，母歿喪不臨。「嗟哉斯徒輩，其心不如禽」——鄙斥"}, "answer": "A", "explain": "(A)女子怨黃鶯吵醒她，害她在夢中無法到遼西和丈夫相會，表達的是思念丈夫的哀怨，不是開朗，說明錯誤。(B)夕陽雖美卻將逝去，充滿惆悵；(C)久旱逢雨、他鄉遇友，都是意外的喜悅；(D)斥責吳起不孝連鳥都不如，是鄙視斥責。", "skill": "判斷詩中情感，先找出「人物想要什麼卻得不到」：得不到→怨、悵；意外得到→喜。"}], "difficulty": "中", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-17", "exam": "bc91-2", "nums": [17], "form": "單題", "img": "img/bc91-2-17.png", "source": "(A)李白〈獨坐敬亭山〉；(C)杜甫〈自京赴奉先縣詠懷五百字〉；(B)(D)出處待查", "author": "", "genre": "古典詩詞曲", "types": ["寫作手法", "詩詞賞析"], "passage": "(A)眾鳥高飛盡，孤雲獨去閒 (B)六代興亡國，三杯為爾歌 (C)朱門酒肉臭，路有凍死骨 (D)故人江海別，幾度隔山川", "translation": "(A)成群的鳥都高飛遠去，一片孤雲獨自悠閒飄走。(B)六個朝代興亡的國都，我舉起三杯酒為你歌唱。(C)富貴人家的酒肉多得發臭，路上卻有凍死的屍骨。(D)老朋友在江海分別後，隔著山川已經好幾年。", "keywords": [{"w": "對偶", "m": "上下句字數相等、句法相似、詞性相當"}, {"w": "朱門", "m": "紅漆大門，指富貴人家"}], "questions": [{"n": 17, "stem": "「對偶」必須字數相等、句法相似、詞性相當。根據上述原則，下列何者是對偶？", "options": {"A": "眾鳥高飛盡，孤雲獨去閒", "B": "六代興亡國，三杯為爾歌", "C": "朱門酒肉臭，路有凍死骨", "D": "故人江海別，幾度隔山川"}, "answer": "C", "explain": "(C)「朱門／路」都是名詞（地點），「酒肉／凍死骨」都是名詞性詞語，「臭／有」詞性位置雖不同，但整句「富家奢侈」與「窮人凍死」句法相應、對比鮮明，是對偶句。(A)「高飛盡」與「獨去閒」結構接近，但標準答案不採用；(B)「興亡國」與「為爾歌」詞性不相當；(D)「江海別」與「隔山川」語序不同。", "skill": "逐字對位比較上下句的詞性，名詞對名詞、動詞對動詞，若有一處對不上就不是工整對偶。"}], "difficulty": "難", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-18", "exam": "bc91-2", "nums": [18], "form": "單題", "img": "img/bc91-2-18.png", "source": "(B)《論語‧為政》；(C)《呂氏春秋‧盡數》；(D)朱熹〈訓學齋規〉", "author": "", "genre": "經典語錄", "types": ["句意理解"], "passage": "(B)知之為知之，不知為不知 (C)戶樞不蠹，流水不腐 (D)讀書有三到：心到、眼到、口到。三到之中，心到最急", "translation": "(B)知道就說知道，不知道就說不知道。(C)常轉動的門軸不會被蟲蛀，流動的水不會腐臭。(D)讀書要做到三到：心到、眼到、口到；三者之中，心到最要緊。", "keywords": [{"w": "戶樞", "m": "門軸"}, {"w": "蠹", "m": "蛀蝕"}, {"w": "急", "m": "重要、要緊"}], "questions": [{"n": 18, "stem": "下列各選項「」中的文句說明，何者適當？", "options": {"A": "「一分耕耘，一分收穫」——求學時要善於利用時間，才能有好成績", "B": "「知之為知之，不知為不知」——研究學問應該誠實，不能自欺欺人", "C": "「戶樞不蠹，流水不腐」——為學應該認真勤奮，以彌補先天的不足", "D": "「讀書有三到：心到、眼到、口到。三到之中，心到最急」——急切的求知欲是學習的動力"}, "answer": "B", "explain": "(B)孔子教子路求知要誠實，知道就是知道，不知道就承認不知道，正確。(A)強調付出多少收穫多少，重點是「勤」，不是「利用時間」；(C)比喻常運動、常活動就不會敗壞，沒有「彌補先天不足」的意思；(D)「心到最急」的「急」是「要緊」，意思是專心最重要，不是「急切的求知欲」。", "skill": "注意文言字的古今義差異（急＝要緊），並檢查說明有沒有加入原句沒有的內容。"}], "difficulty": "中", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-20", "exam": "bc91-2", "nums": [20], "form": "單題", "img": "img/bc91-2-20.png", "source": "(A)陶淵明〈五柳先生傳〉；(B)《史記‧張釋之馮唐列傳》；(C)《孟子‧告子下》；(D)《孟子‧盡心上》", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "(A)不戚戚於貧賤，不汲汲於富貴 (B)今法如此而更重之，是法不信於民也 (C)舜發於畎畝之中，傅說舉於版築之間 (D)得志，澤加於民；不得志，修身見於世", "translation": "(A)不因貧賤而憂愁，不急著追求富貴。(B)現在法律規定如此，卻又加重處罰，這樣法律就不被人民信任了。(C)舜從田野中被起用，傅說從築牆的工作中被提拔。(D)得志時，把恩澤施給百姓；不得志時，修養自身以表現於世。", "keywords": [{"w": "於（被動）", "m": "被"}, {"w": "於（對象）", "m": "對於、因為"}, {"w": "於（處所）", "m": "在、從"}, {"w": "戚戚", "m": "憂愁的樣子"}, {"w": "汲汲", "m": "急切追求的樣子"}], "questions": [{"n": 20, "stem": "「甲敗於乙」是說甲被乙打敗。下列各選項的「於」字，何者也屬於這種用法？", "options": {"A": "不戚戚「於」貧賤，不汲汲於富貴", "B": "今法如此而更重之，是法不信「於」民也", "C": "舜發「於」畎畝之中，傅說舉於版築之間", "D": "得志，澤加「於」民；不得志，修身見於世"}, "answer": "B", "explain": "「法不信於民」是「法律不被人民信任」，「於」表被動，與「甲敗於乙」相同。(A)「於」是「因為、對於」；(C)「於」是「從、在」，表處所；(D)「於」是「到、給」，表對象。", "skill": "判斷被動「於」：把「於」換成「被」讀讀看，主語是承受動作的一方而句意通順，就是被動。"}], "difficulty": "中", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-21", "exam": "bc91-2", "nums": [21], "form": "單題", "img": "img/bc91-2-21.png", "source": "《孟子‧告子上》〈弈秋〉", "author": "孟子", "genre": "經典語錄", "types": ["字詞解釋", "虛詞句式"], "passage": "今夫弈之為數，小數也；不專心致志，則不得也。弈秋，通國之善弈者也。使弈秋誨二人弈，其一人專心致志，惟弈秋之為聽；一人雖聽之，一心以為有鴻鵠將至，思援弓繳而射之。雖與之俱學，弗若之矣。為是其智弗若與？曰：非然也。", "translation": "下棋作為一種技藝，只是小技藝；但不專心致志，就學不會。弈秋是全國最會下棋的人。讓弈秋教兩個人下棋，其中一人專心致志，只聽弈秋的話；另一人雖然也在聽，心裡卻想著有天鵝要飛來，想拉弓搭箭去射牠。雖然和前一人一起學，卻比不上他。是因為他的聰明比不上嗎？回答說：不是這樣的。", "keywords": [{"w": "為（ㄨㄟˊ）", "m": "作為、是"}, {"w": "為（ㄨㄟˋ）", "m": "因為"}, {"w": "數", "m": "技藝"}, {"w": "誨", "m": "教導"}, {"w": "鴻鵠", "m": "天鵝"}, {"w": "繳", "m": "繫在箭上的絲繩"}, {"w": "弗若", "m": "比不上"}], "questions": [{"n": 21, "stem": "下列選項中「為」字的讀音，何者與其它三者不同？", "options": {"A": "今夫弈之「為」數，小數也；不專心致志，則不得也", "B": "使弈秋誨二人弈，其一人專心致志，惟弈秋之「為」聽", "C": "一人雖聽之，一心以「為」有鴻鵠將至，思援弓繳而射之", "D": "雖與之俱學，弗若之矣。「為」是其智弗若與？曰：非然也"}, "answer": "D", "explain": "(D)「為是其智弗若與」的「為」是「因為」，讀ㄨㄟˋ。(A)「為數」是「作為技藝」、(B)「惟弈秋之為聽」是賓語提前的結構助詞、(C)「以為」是「認為」，都讀ㄨㄟˊ。", "skill": "「為」表原因、目的（因為、為了、替）讀ㄨㄟˋ；表「是、作為、認為」或結構助詞讀ㄨㄟˊ。"}], "difficulty": "中", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-22", "exam": "bc91-2", "nums": [22], "form": "單題", "img": "img/bc91-2-22.png", "source": "出處待查（一般引為梁啟超或袁枚論讀書語）", "author": "", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "如能用古人而不為古人所惑，能役古人而不為古人所奴，則載籍皆似為我調查，而使古人為我書記，多多益善矣。", "translation": "如果能運用古人的學問而不被古人迷惑，能驅使古人的見解而不被古人奴役，那麼所有書籍都像在替我調查資料，讓古人當我的書記，越多越好。", "keywords": [{"w": "為……所", "m": "被（被動句式）"}, {"w": "役", "m": "驅使、使用"}, {"w": "載籍", "m": "書籍"}, {"w": "書記", "m": "記錄文書的人"}, {"w": "多多益善", "m": "越多越好"}], "questions": [{"n": 22, "stem": "「如能用古人而不為古人所惑，能役古人而不為古人所奴，則載籍皆似為我調查，而使古人為我書記，多多益善矣。」句中「能用古人而不為古人所惑，能役古人而不為古人所奴」的意思是什麼？", "options": {"A": "讀書時能吸收古人思想的精華，捨棄不合時宜的見解", "B": "讀書時能熟悉古人的生活背景，與他們的心靈相契合", "C": "讀書時能對古人感到迷惑的問題加以分析理解", "D": "藉著讀書豐富自己的見聞，開拓自己的視野"}, "answer": "A", "explain": "「用古人、役古人」是吸收、運用古人的學問；「不為古人所惑、所奴」是不被古人的錯誤或過時見解迷惑、牽著走，合起來就是取其精華、去其糟粕，(A)正確。(B)講與古人心靈契合，沒有「不被迷惑」的意思；(C)誤把「為古人所惑」當成「古人感到迷惑」；(D)只講增廣見聞，沒有批判吸收的意思。", "skill": "看到「為……所……」先翻成「被……」，再弄清楚是誰被誰怎麼樣。"}], "difficulty": "中", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-29", "exam": "bc91-2", "nums": [29], "form": "單題", "img": "img/bc91-2-29.png", "source": "(A)王維〈雜詩〉；(B)宋之問〈渡漢江〉；(C)賀知章〈回鄉偶書〉；(D)杜甫〈聞官軍收河南河北〉", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)君自故鄉來，應知故鄉事。來日綺窗前，寒梅著花未？(B)嶺外音書絕，經冬復立春。近鄉情更怯，不敢問來人。(C)少小離家老大回，鄉音無改鬢毛摧。兒童相見不相識，笑問客從何處來。(D)白日放歌須縱酒，青春作伴好還鄉。即從巴峽穿巫峽，便下襄陽向洛陽。", "translation": "(A)你從故鄉來，應該知道故鄉的事；你來的那天，我家雕花窗前的寒梅開花了沒？(B)在嶺南和家裡音信斷絕，過了冬天又到春天；越接近家鄉心裡越害怕，不敢向迎面來的人打聽家中情況。(C)年少離家、年老才回來，鄉音沒變，鬢髮卻已稀疏；孩子們見了不認識我，笑著問客人從哪裡來。(D)大白天放聲高歌還要痛快喝酒，趁著明媚春光正好結伴回鄉；立刻從巴峽穿過巫峽，再順流到襄陽、前往洛陽。", "keywords": [{"w": "綺窗", "m": "雕花的窗"}, {"w": "著花未", "m": "開花了沒有"}, {"w": "音書", "m": "書信、消息"}, {"w": "怯", "m": "害怕"}, {"w": "摧", "m": "稀疏脫落"}, {"w": "青春", "m": "春天"}], "questions": [{"n": 29, "stem": "下列詩句，何者不是用來描述返鄉的心境？", "options": {"A": "君自故鄉來，應知故鄉事。來日綺窗前，寒梅著花未", "B": "嶺外音書絕，經冬復立春。近鄉情更怯，不敢問來人", "C": "少小離家老大回，鄉音無改鬢毛摧。兒童相見不相識，笑問客從何處來", "D": "白日放歌須縱酒，青春作伴好還鄉。即從巴峽穿巫峽，便下襄陽向洛陽"}, "answer": "A", "explain": "(A)詩人人在異鄉，向故鄉來的人打聽家中梅花，表達的是思鄉，不是返鄉。(B)「近鄉情更怯」是快到家時的忐忑；(C)年老回鄉被兒童當成客人的感慨；(D)聽到收復失土，急著結伴還鄉的喜悅，三者都是返鄉的心境。", "skill": "區分「思鄉」與「返鄉」：看詩人此時是在異鄉想家，還是正在回家的路上或已到家。"}], "difficulty": "中", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-31", "exam": "bc91-2", "nums": [31], "form": "單題", "img": "img/bc91-2-31.png", "source": "釋志南〈絕句〉", "author": "志南", "genre": "古典詩詞曲", "types": ["詩詞賞析"], "passage": "吹面不寒楊柳風", "translation": "吹在臉上一點也不覺得寒冷的，是吹動楊柳的春風。", "keywords": [{"w": "楊柳風", "m": "春風"}], "questions": [{"n": 31, "stem": "「吹面不寒楊柳風」和以下哪個成語所描述的情境最相近？", "options": {"A": "春風滿面", "B": "春風化雨", "C": "春風和暢", "D": "春寒料峭"}, "answer": "C", "explain": "春風吹在臉上不覺得冷，是溫和舒暢的春風，與「春風和暢」相同。(A)形容人滿臉笑容、得意；(B)比喻良師的教化；(D)形容初春仍有寒意，與「不寒」相反。", "skill": "成語常有比喻義，選情境相近時要用字面上真正描寫天氣的成語，並排除比喻人事的。"}], "difficulty": "易", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-33", "exam": "bc91-2", "nums": [33], "form": "單題", "img": "img/bc91-2-33.png", "source": "(A)《孟子‧告子下》；(B)劉蓉〈習慣說〉；(C)《國語‧魯語下》〈敬姜論勞逸〉；(D)《論語‧陽貨》", "author": "", "genre": "說理議論", "types": ["主旨寓意", "比較閱讀"], "passage": "(A)人恆過，然後能改 (B)習之中人，甚矣哉 (C)勞則思，逸則淫，物之情也 (D)飽食終日，無所用心，難矣哉", "translation": "(A)人常常犯錯，然後才能改正。(B)習慣對人的影響，真是太大了啊！(C)勞動就會思考，安逸就會放縱，這是萬物的常情。(D)整天吃飽飯，什麼心思都不用，這樣的人真難有成就啊！", "keywords": [{"w": "恆", "m": "常常"}, {"w": "中（ㄓㄨㄥˋ）人", "m": "影響人"}, {"w": "甚矣哉", "m": "太厲害了啊"}, {"w": "淫", "m": "放縱、過度"}], "questions": [{"n": 33, "stem": "「有一個實驗是這樣的：在盛滿水的鍋子放入一條魚，然後把水的溫度以非常緩慢的速度逐漸升高。剛開始魚兒在水中悠然自得，一點都沒有異樣，但是在兩個小時之後，魚兒竟一點也沒有掙扎地死了。」此則故事的寓意是在說明何種道理？", "options": {"A": "人恆過，然後能改", "B": "習之中人，甚矣哉", "C": "勞則思，逸則淫，物之情也", "D": "飽食終日，無所用心，難矣哉"}, "answer": "B", "explain": "水溫慢慢升高，魚逐漸習慣而失去警覺，最後死了也不掙扎，說明環境逐漸形成的習慣對生物影響極大，與(B)「習慣影響人真是太大了」相同。(A)講犯錯後改過；(C)「淫」是放縱過度，魚悠游是正常生活，並非過度行為；(D)批評無所用心的人。", "skill": "先抓故事的關鍵變化（慢慢變化→習慣→失去警覺），再找選項中同樣講「習慣」影響的句子。"}], "difficulty": "中", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-34", "exam": "bc91-2", "nums": [34, 35, 36], "form": "題組", "img": "img/bc91-2-34.png", "source": "蘇軾〈記承天夜遊〉", "author": "蘇軾", "genre": "山水遊記", "types": ["文意推論", "人物情感", "寫作手法"], "passage": "元豐六年十月十二日，夜，解衣欲睡；月色入戶，欣然起行。念無與樂者，遂至承天寺，尋張懷民。懷民亦未寢，相與步於中庭。\n庭下如積水空明，水中藻荇交橫，蓋竹柏影也。\n何夜無月？何處無竹柏？但少閑人如吾兩人耳！", "translation": "元豐六年十月十二日夜晚，我脫了衣服正要睡覺，月光照進門內，我高興地起身出門。想到沒有可以一起同樂的人，就到承天寺找張懷民。懷民也還沒睡，我們便一起在庭院中散步。\n庭院中月光像積水一樣清澈透明，水中好像有水藻、荇菜交錯，原來是竹子和柏樹的影子。\n哪個夜晚沒有月亮？哪裡沒有竹柏？只是缺少像我們兩人這樣的閒人罷了！", "keywords": [{"w": "戶", "m": "門"}, {"w": "欣然", "m": "高興的樣子"}, {"w": "念", "m": "想到"}, {"w": "相與", "m": "一起"}, {"w": "空明", "m": "清澈透明"}, {"w": "蓋", "m": "原來是"}, {"w": "但", "m": "只是"}, {"w": "耳", "m": "罷了"}], "questions": [{"n": 34, "stem": "根據文意，作者為什麼要到承天寺？", "options": {"A": "失眠難耐", "B": "心緒無聊", "C": "偕友賞月", "D": "參禪求道"}, "answer": "C", "explain": "作者因「月色入戶，欣然起行」，又「念無與樂者」，才到承天寺找張懷民一起賞月，(C)正確。他本來準備睡覺，不是失眠(A)；「念無與樂者」是想找人同樂，不是無聊(B)；到寺裡是找朋友，不是參禪(D)。", "skill": "找動機要看動作前的原因句：「月色入戶，欣然起行」「念無與樂者」→ 找朋友一起賞月。"}, {"n": 35, "stem": "本文末句「但少閑人如吾兩人耳！」表達出怎樣的感慨？", "options": {"A": "標榜自己有隨遇而安的修養", "B": "自嘲自己與張懷民一事無成", "C": "有閑情逸致才能欣賞到美景", "D": "無所事事的人才能欣賞美景"}, "answer": "C", "explain": "月色竹柏處處都有，卻少有人欣賞，只有像他們這樣有閒情的人才能領略，(C)正確。(A)蘇軾確有隨遇而安的修養，但文中沒有刻意標榜；(B)「閑人」不是自嘲無成；(D)「閑」指心境閒適、不為俗務所役，不是無所事事。", "skill": "「閑人」要從文脈理解為「有閒情的人」，避免用現代負面義（游手好閒）解讀。"}, {"n": 36, "stem": "下列語句，何者點出了題目中的「遊」字？", "options": {"A": "月色入戶，欣然起行", "B": "相與步於中庭", "C": "水中藻荇交橫", "D": "何夜無月？何處無竹柏"}, "answer": "B", "explain": "「相與步於中庭」寫兩人在承天寺庭院中散步，才真正點出「承天夜遊」的「遊」。(A)只是遊的動機，此時還不知去哪裡；(C)是寫景；(D)是抒發感慨。", "skill": "題目扣題的句子要同時符合題目的每個要素（承天、夜、遊），找實際出現該動作的那一句。"}], "difficulty": "易", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-37", "exam": "bc91-2", "nums": [37, 38, 39], "form": "題組", "img": "img/bc91-2-37.png", "source": "《韓非子‧說難》", "author": "韓非", "genre": "寓言故事", "types": ["文意推論", "人物情感", "主旨寓意"], "passage": "彌子瑕有寵於衛君。衛國之法，竊駕君車者罪刖。彌子瑕母病，人聞，有夜告彌子瑕者，彌子瑕矯駕君車以出，君聞而賢之曰：「孝哉！為母之故，忘其犯刖罪。」異日，與君遊於果園，食桃而甘，不盡，以其半啖君。君曰：「愛我哉！忘其口味，以啖寡人。」及彌子瑕色衰愛弛，得罪於君，君曰：「是固嘗矯駕吾車，又嘗啖我以餘桃。」", "translation": "彌子瑕受到衛君寵愛。衛國的法律規定，偷駕國君車子的人要處以砍腳的刑罰。彌子瑕的母親生病，有人聽說了，連夜通知他，彌子瑕就假借君命駕著國君的車子出去。衛君聽說後反而稱讚他說：「真孝順啊！為了母親，竟忘了自己會犯砍腳的罪。」另一天，他和衛君在果園遊玩，吃到一顆很甜的桃子，沒吃完，就把剩下的一半給衛君吃。衛君說：「真愛我啊！忘了自己愛吃，把桃子給我吃。」等到彌子瑕容貌衰老、衛君對他的寵愛減退，他得罪了衛君，衛君說：「這個人本來就曾經假借我的名義駕我的車，又曾經把吃剩的桃子給我吃。」", "keywords": [{"w": "有寵於", "m": "受到……寵愛"}, {"w": "刖", "m": "砍斷雙腳的刑罰"}, {"w": "矯", "m": "假託（君命）"}, {"w": "賢之", "m": "認為他賢德"}, {"w": "啖", "m": "給人吃"}, {"w": "弛", "m": "鬆懈、減退"}, {"w": "固", "m": "本來"}], "questions": [{"n": 37, "stem": "由上文可知，彌子瑕竊駕君車的原因何在？", "options": {"A": "知法犯法，故意挑戰法令", "B": "衛國之法，不處罰竊車賊", "C": "母親患急病，無暇顧及法律", "D": "與國君同遊，當然不算竊車"}, "answer": "C", "explain": "「彌子瑕母病，人聞，有夜告彌子瑕者，彌子瑕矯駕君車以出」，是母親生病，情急之下顧不得法律，(C)正確。(A)他不是故意挑戰法令；(B)衛國法律明定「罪刖」；(D)竊車時並非與國君同遊。", "skill": "問原因就回到事件前一句找觸發事件（母病、夜告）。"}, {"n": 38, "stem": "由上文可知，彌子瑕將桃子分與衛君吃，當時衛君的想法是什麼？", "options": {"A": "桃子很甜，彌子瑕捨不得個人獨享", "B": "彌子瑕故意示好，以考驗衛君的愛", "C": "彌子瑕平日就驕縱，不顧君臣之禮", "D": "桃子是衛君的最愛，不容他人分享"}, "answer": "A", "explain": "衛君當時說「愛我哉！忘其口味，以啖寡人」，認為彌子瑕愛他，桃子好吃也捨不得自己吃完，(A)正確。(C)是後來失寵時的看法，不是「當時」；(B)(D)文中都沒有根據。", "skill": "題目問「當時」的想法，就只找當時那句話（愛我哉），不要用後來的態度回推。"}, {"n": 39, "stem": "根據上文，衛君改變了對彌子瑕的態度，關鍵在何處？", "options": {"A": "彌子瑕仗勢欺人，衛君已經忍無可忍", "B": "彌子瑕目中無人，衛君自覺受到冒犯", "C": "彌子瑕不再迷人，衛君已經感到厭倦", "D": "彌子瑕得罪他人，衛君難以再袒護他"}, "answer": "C", "explain": "「及彌子瑕色衰愛弛」：彌子瑕容貌衰老，衛君的寵愛就減退了，同樣兩件事從「孝、愛我」變成罪狀，可見關鍵是衛君不再喜愛他，(C)正確。(A)(B)(D)文中都沒有仗勢欺人、目中無人或得罪他人的敘述。", "skill": "比較前後態度：事情沒變，評價卻變了，原因就在中間插入的轉折句（色衰愛弛）。"}], "difficulty": "中", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc91-2-40", "exam": "bc91-2", "nums": [40, 41], "form": "題組", "img": "img/bc91-2-40.png", "source": "梁啟超〈論毅力〉", "author": "梁啟超", "genre": "說理議論", "types": ["文意推論", "寫作手法"], "passage": "天下古今成敗之林，若是其莽然不一途也。要其何以成？何以敗？曰有毅力者成，反是者敗。蓋人生歷程，大抵逆境居十之六七，順境亦居十之三四。而順逆兩境，又常相間以迭乘。無論事之大小，而必有數次乃至十數次之阻力。其阻力雖或大或小，然要之無可逃避者也。其在志力薄弱之士，始固曰吾欲云云，吾欲云云，其意以為天下事固易易也，及驟嘗焉，而阻力猝來，頹然喪矣。", "translation": "天下古今成功與失敗的事例，像草叢一樣繁雜，不是只有一條路。總歸來說，為什麼成功？為什麼失敗？答案是：有毅力的人成功，相反的就失敗。人生的歷程，大概逆境占十分之六七，順境也占十分之三四，而順境逆境又常常交替出現。無論事情大小，一定會有幾次甚至十幾次的阻力。阻力雖然有大有小，總之都是無法逃避的。那些意志薄弱的人，一開始總說「我想要怎樣、我想要怎樣」，以為天下事很容易；等到一嘗試，阻力突然來到，就頹喪洩氣了。", "keywords": [{"w": "林", "m": "眾多（事例）"}, {"w": "莽然", "m": "草叢生的樣子，喻人事繁雜"}, {"w": "要", "m": "總括、歸納"}, {"w": "蓋", "m": "發語詞，大抵"}, {"w": "迭乘", "m": "交替出現"}, {"w": "云云", "m": "如此如此"}, {"w": "驟", "m": "一下子、開始"}, {"w": "猝", "m": "突然"}, {"w": "頹然", "m": "頹喪的樣子"}], "questions": [{"n": 40, "stem": "作者以為「無毅力者敗」，下列何者是其立論的前提？", "options": {"A": "機會稍縱即逝。不能掌握先機，當機立斷，事業難成", "B": "挫折為人生所不能免。心靈脆弱，一蹶不起者，斷難成事", "C": "成功的祕訣在嘗試。害怕失敗而怯於嘗試，將與成功無緣", "D": "企圖心是衝刺的動力。胸無大志者，恐難希冀意外的成就"}, "answer": "B", "explain": "作者先說人生逆境占十之六七、任何事都有無可逃避的阻力（挫折不可免），再說意志薄弱者遇阻就頹喪，所以無毅力者失敗，(B)正確。(A)講把握機會、(C)講勇於嘗試、(D)講企圖心，都不是文中的論證前提。", "skill": "找立論前提就找作者「先肯定的普遍事實」（蓋人生歷程……無可逃避者也），再看結論如何由它推出。"}, {"n": 41, "stem": "下列敘述，何者是本文論述的方法？", "options": {"A": "廣泛的說明各行各業中獨佔鰲頭的人都令人敬佩", "B": "以成敗對比，舉例論述事業成敗的原因極為複雜", "C": "從正面立說，舉例說明意志堅強、無懼失敗是成功的關鍵", "D": "從反面強調，空有理想但卻經不起挫折打擊的人難以成功"}, "answer": "D", "explain": "本段後半描寫「志力薄弱之士」起初說得容易，一遇阻力就頹喪，是從反面說明經不起挫折的人無法成功，(D)正確。(A)文中沒有談各行各業；(B)作者雖說成敗事例繁雜，但結論是成敗關鍵單一（毅力），且未舉例；(C)節錄部分沒有從正面舉例說明成功者。", "skill": "判斷論述方法要看例子是寫「成功的人」（正面）還是「失敗的人」（反面），並注意有沒有真的舉例。"}], "difficulty": "難", "label": "91年第二次基測", "year": 91, "kind": "基測"}, {"id": "bc92-1-4", "exam": "bc92-1", "nums": [4], "form": "單題", "img": "img/bc92-1-4.png", "source": "《禮記‧檀弓上》", "author": "", "genre": "經典語錄", "types": ["句意理解", "文化常識"], "passage": "生，於我乎館；死，於我乎殯。", "translation": "（朋友沒有歸宿）活著的時候，就住在我家；死了，就在我家辦喪事。", "keywords": [{"w": "館", "m": "住宿、安頓"}, {"w": "殯", "m": "停放靈柩、辦喪事"}, {"w": "乎", "m": "於、在"}], "questions": [{"n": 4, "stem": "孔子以「生，於我乎館；死，於我乎殯」的精神來待人接物，下列何者與孔子的這種胸懷較為相近？", "options": {"A": "忠", "B": "孝", "C": "仁", "D": "信"}, "answer": "C", "explain": "孔子對無依無靠的朋友，活著時收留他住，死了替他辦喪事，是推己及人、關愛他人的「仁」，(C)正確。(A)忠是盡心竭力事君或做事；(B)孝是對父母；(D)信是守信用，都不是這段話表現的重點。", "skill": "先翻譯行為（照顧朋友生死），再對應儒家德目：愛人＝仁、盡己＝忠、事親＝孝、守諾＝信。"}], "difficulty": "中", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-1-11", "exam": "bc92-1", "nums": [11], "form": "單題", "img": "img/bc92-1-11.png", "source": "(B)徐霞客語（後人概括）；(C)元稹〈離思〉；(A)(D)俗諺／佛家偈語", "author": "", "genre": "古典詩詞曲", "types": ["寫作手法", "詩詞賞析"], "passage": "(A)人無千日好，花無百日紅 (B)五嶽歸來不看山，黃山歸來不看嶽 (C)曾經滄海難為水，除卻巫山不是雲 (D)千江有水千江月，萬里無雲萬里天", "translation": "(A)人沒有一千天都好的，花沒有一百天都紅的。(B)遊過五嶽回來就不想看其他山，遊過黃山回來連五嶽也不想看了。(C)看過大海，別的水都算不上水；除了巫山的雲，別的都稱不上雲。(D)千條江有水就有千個月影，萬里無雲就是萬里晴天。", "keywords": [{"w": "甲", "m": "第一、居首位"}, {"w": "五嶽", "m": "泰、華、衡、恆、嵩五座名山"}, {"w": "滄海", "m": "大海"}, {"w": "除卻", "m": "除了"}], "questions": [{"n": 11, "stem": "「桂林山水甲天下，陽朔山水甲桂林」，這兩句話透過「天下」、「桂林」、「陽朔」的層層比較，來說明陽朔的山水美景冠絕天下。下列何者也使用了相同的技巧？", "options": {"A": "人無千日好，花無百日紅", "B": "五嶽歸來不看山，黃山歸來不看嶽", "C": "曾經滄海難為水，除卻巫山不是雲", "D": "千江有水千江月，萬里無雲萬里天"}, "answer": "B", "explain": "(B)五嶽勝過一般的山，黃山又勝過五嶽，由「山→五嶽→黃山」層層比較，凸顯黃山最美，與題幹相同。(A)說好景不常，沒有層層比較；(C)以滄海、巫山比喻曾經的最愛，只有一層比較；(D)是對稱的寫景，沒有比較高下。", "skill": "層遞比較的特徵是「A＜B、B＜C」兩次比較形成一條階梯，找出能排成三層的選項。"}], "difficulty": "中", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-1-13", "exam": "bc92-1", "nums": [13], "form": "單題", "img": "img/bc92-1-13.png", "source": "《孟子‧盡心上》", "author": "孟子", "genre": "經典語錄", "types": ["字詞解釋"], "passage": "居惡在？仁是也；路惡在？義是也。", "translation": "心安住的地方在哪裡？就是仁；人生該走的路在哪裡？就是義。", "keywords": [{"w": "惡（ㄨ）", "m": "何、哪裡"}, {"w": "居", "m": "居處，比喻心之所在"}, {"w": "是", "m": "這、這個（指代）"}], "questions": [{"n": 13, "stem": "「居惡在？仁是也；路惡在？義是也。」句中「惡」字的字義，應是下列何者？", "options": {"A": "何，哪裡", "B": "恨，討厭", "C": "患，憂慮", "D": "甚，非常"}, "answer": "A", "explain": "「惡在」讀ㄨ，是「在哪裡」的問句，後面用「仁是也」「義是也」回答，(A)正確。代入(B)(C)(D)都無法和後面的回答配合。", "skill": "句子後面若緊接著回答（……是也），前面的關鍵字多半是疑問詞，「惡」放在「在」前常作「哪裡」。"}], "difficulty": "易", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-1-17", "exam": "bc92-1", "nums": [17], "form": "單題", "img": "img/bc92-1-17.png", "source": "文天祥〈絕命辭〉（衣帶贊）", "author": "文天祥", "genre": "經典語錄", "types": ["句意理解", "人物情感"], "passage": "孔曰成仁，孟云取義；惟其義盡，所以仁至。讀聖賢書，所學何事？而今而後，庶幾無愧！", "translation": "孔子說要成就仁德，孟子說要捨生取義；只有把道義盡到了，仁德才算達到。讀聖賢的書，學的是什麼呢？從今以後，大概可以無愧於心了。", "keywords": [{"w": "成仁", "m": "犧牲生命以成全仁德"}, {"w": "取義", "m": "捨生以取義"}, {"w": "惟其", "m": "正因為、只有"}, {"w": "庶幾", "m": "差不多、或許可以"}], "questions": [{"n": 17, "stem": "文天祥的絕命辭：「孔曰成仁，孟云取義；惟其義盡，所以仁至。讀聖賢書，所學何事？而今而後，庶幾無愧！」其中「所學何事」指的是什麼？", "options": {"A": "精進學業，造就經國濟世美名", "B": "為國盡忠，不惜犧牲自己生命", "C": "紹繼聖賢，復興中華傳統文化", "D": "效法先賢，著書立言揚名後世"}, "answer": "B", "explain": "前文說孔子「成仁」、孟子「取義」，都是為道義犧牲生命；文天祥寫此辭時即將就義，「所學何事」就是學到了為國盡忠、捨生取義，(B)正確。(A)(D)重點在求名，(C)講文化傳承，都與「成仁取義」及就義的情境不合。", "skill": "反問句「所學何事？」的答案通常就在前文，往前找作者引用的道理（成仁、取義）。"}], "difficulty": "易", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-1-19", "exam": "bc92-1", "nums": [19], "form": "單題", "img": "img/bc92-1-19.png", "source": "(A)翁森〈四時讀書樂〉；(B)黃檗禪師詩句；(D)李白〈把酒問月〉；(C)出處待查", "author": "", "genre": "古典詩詞曲", "types": ["主旨寓意", "比較閱讀"], "passage": "(A)好鳥枝頭亦朋友，落花水面皆文章 (B)不經一番寒徹骨，焉得梅花撲鼻香 (C)不逢大匠材難用，唯有伯樂識良駒 (D)今人不見古時月，今月曾經照古人", "translation": "(A)枝頭的鳥是朋友，水面的落花都是文章。(B)不經過一番刺骨的寒冷，哪能有撲鼻的梅花香？(C)遇不到高明的工匠，好木材也難被利用；只有伯樂才能識別好馬。(D)現在的人看不到古時的月亮，現在的月亮卻曾照過古人。", "keywords": [{"w": "焉得", "m": "怎能得到"}, {"w": "大匠", "m": "技藝高明的工匠"}], "questions": [{"n": 19, "stem": "「黃媽慶是藝文界譽為三冠王的藝術家，其作品題材多數來自於他生活周邊的事物，如蔬菜、瓜果、花卉、昆蟲等。創作風格寫實且具個人特色，其木雕特色在於保持原來樸實無華的本質。」從藝術家黃媽慶的作品取材來看，可與下列何者相映襯？", "options": {"A": "好鳥枝頭亦朋友，落花水面皆文章", "B": "不經一番寒徹骨，焉得梅花撲鼻香", "C": "不逢大匠材難用，唯有伯樂識良駒", "D": "今人不見古時月，今月曾經照古人"}, "answer": "A", "explain": "黃媽慶取材於身邊的蔬果、花卉、昆蟲，正如(A)把枝頭小鳥、水面落花都當成朋友與文章材料，都是從日常自然事物中取材。(B)講經過磨練才有成就；(C)講人才需被賞識；(D)感嘆時光流逝、古今同月。", "skill": "題目限定比較的面向（作品取材），只要找出同樣講「材料來自日常周遭」的句子，別被其他特色干擾。"}], "difficulty": "中", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-1-23", "exam": "bc92-1", "nums": [23], "form": "單題", "img": "img/bc92-1-23.png", "source": "張籍〈節婦吟〉", "author": "張籍", "genre": "古典詩詞曲", "types": ["人物情感", "詩詞賞析"], "passage": "君知妾有夫，贈妾雙明珠。感君纏綿意，繫在紅羅襦。妾家高樓連苑起，良人執戟明光裡。知君用心如日月，事夫誓擬同生死。還君明珠雙淚垂，恨不相逢未嫁時。", "translation": "你明知我已有丈夫，還送我一對明珠。我感激你情意纏綿，把明珠繫在紅色絲綢短衣上。我家的高樓連著皇家園林，丈夫在明光殿持戟當侍衛。我知道你的心意光明如日月，但我侍奉丈夫，發誓要和他同生共死。把明珠還給你時，我雙眼垂淚，只恨沒能在未出嫁前遇見你。", "keywords": [{"w": "妾", "m": "女子自稱"}, {"w": "羅襦", "m": "絲綢短衣"}, {"w": "良人", "m": "丈夫"}, {"w": "戟", "m": "古兵器，戈矛合體"}, {"w": "明光", "m": "宮殿名，明光殿"}, {"w": "擬", "m": "打算"}], "questions": [{"n": 23, "stem": "「君知妾有夫，贈妾雙明珠，感君纏綿意，繫在紅羅襦。妾家高樓連苑起，良人執戟明光裡。知君用心如日月，事夫誓擬同生死。還君明珠雙淚垂，恨不相逢未嫁時。」下列何者，是這首詩中已婚女子面對第三者追求時的心態？", "options": {"A": "堅守婚約，委婉拒絕", "B": "深情可感，欣然接受", "C": "此生無緣，承諾來生", "D": "欲語還休，暗通款曲"}, "answer": "A", "explain": "女子說「事夫誓擬同生死」，最後「還君明珠」，表示選擇婚姻、拒絕追求者；「雙淚垂」「恨不相逢未嫁時」則讓拒絕顯得溫婉有情，(A)正確。(B)她最後退還明珠，沒有接受；(C)詩中只有遺憾，沒有承諾來生；(D)她明白拒絕，並未私下往來。", "skill": "情感複雜的詩，要以「最後的行動」（還珠）判斷選擇，以「語氣」（垂淚、恨不相逢）判斷方式。"}], "difficulty": "中", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-1-27", "exam": "bc92-1", "nums": [27], "form": "單題", "img": "img/bc92-1-27.png", "source": "王國維《人間詞話》", "author": "王國維", "genre": "說理議論", "types": ["文意推論", "寫作手法"], "passage": "大家之作，其言情也必沁人心脾，其寫景也必豁人耳目。其辭脫口而出，無矯揉妝束之態。以其所見者真，所知者深也。", "translation": "大作家的作品，抒情一定深入人心，寫景一定讓人眼界開闊。文辭像脫口而出一樣自然，沒有做作修飾的樣子。這是因為他們看到的真切、了解的深刻。", "keywords": [{"w": "大家", "m": "成就很高的作家"}, {"w": "沁人心脾", "m": "深入人心"}, {"w": "豁人耳目", "m": "使人耳目開闊"}, {"w": "矯揉妝束", "m": "刻意做作、修飾"}, {"w": "以", "m": "因為"}], "questions": [{"n": 27, "stem": "「大家之作，其言情也必沁人心脾，其寫景也必豁人耳目。其辭脫口而出，無矯揉妝束之態。以其所見者真，所知者深也。」根據上文，下列何者是詩詞大家作品之所以出色的根本原因？", "options": {"A": "委婉曲折的抒情筆法", "B": "歷歷如繪的敘景場面", "C": "爐火純青的巧妙修辭", "D": "真切深刻的見解感悟"}, "answer": "D", "explain": "末句「以其所見者真，所知者深也」用「以」（因為）說明原因：見得真、知得深，就是真切深刻的見解感悟，(D)正確。(A)(B)是作品表現出來的結果，不是根本原因；(C)文中反而說「無矯揉妝束之態」，不強調修辭技巧。", "skill": "問「原因」就找文中的因果詞（以、因、故），「以其……也」後面就是答案。"}], "difficulty": "易", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-1-30", "exam": "bc92-1", "nums": [30], "form": "單題", "img": "img/bc92-1-30.png", "source": "《世說新語‧賢媛》（陶侃母責子）", "author": "劉義慶", "genre": "史傳人物", "types": ["虛詞句式", "字詞解釋"], "passage": "汝為吏，以官物見餉，非唯不益，乃增吾憂也。", "translation": "你當官吏，拿公家的東西送給我，不但沒有好處，反而增加我的憂慮。", "keywords": [{"w": "見", "m": "放在動詞前，代稱「我」"}, {"w": "餉", "m": "贈送食物"}, {"w": "非唯", "m": "不只"}, {"w": "乃", "m": "反而"}], "questions": [{"n": 30, "stem": "「陶侃有一次拿公物孝敬母親，陶母對他說：『汝為吏，以官物見餉，非唯不益，乃增吾憂也。』」上文中，「見餉」的「見」字為代詞性助詞，代稱「我」，故「見餉」即「餉我」。下列文句中的「見」字，何者也屬於這種用法？", "options": {"A": "四處旅行，增廣「見」聞", "B": "招待不周，請多「見」諒", "C": "閣下所言，何以「見」得", "D": "論點切要，「見」地不凡"}, "answer": "B", "explain": "「請多見諒」就是「請多原諒我」，「見」代稱說話者自己，與「見餉」相同，(B)正確。(A)「見聞」是看到聽到的事；(C)「見得」是「看得出、斷定」；(D)「見地」是見解，三者的「見」都是看、見解的意思。", "skill": "把「見＋動詞」改寫成「動詞＋我」試試看，若意思通順（見諒＝諒我）就是代詞性的「見」。"}], "difficulty": "中", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-1-33", "exam": "bc92-1", "nums": [33], "form": "單題", "img": "img/bc92-1-33.png", "source": "蘇軾〈西湖〉詩聯（相傳）", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "詩詞賞析"], "passage": "一盞寒泉薦秋菊，三更畫舫穿藕花。", "translation": "用一杯清涼的泉水供奉秋菊；三更半夜，畫船穿行在荷花叢中。", "keywords": [{"w": "薦", "m": "進獻、供奉"}, {"w": "畫舫", "m": "裝飾華美的遊船"}, {"w": "平仄", "m": "平聲（一、二聲）與仄聲（三、四聲及入聲）"}, {"w": "瓊漿", "m": "美酒"}], "questions": [{"n": 33, "stem": "根據對聯「上下兩句平仄相反、詞性相同」的格律來判斷，「一盞寒泉薦秋菊，三更畫舫穿藕花」中的「寒泉」，可用下列何者替代？", "options": {"A": "醇酒", "B": "瓊漿", "C": "玉液", "D": "新釀"}, "answer": "B", "explain": "下聯對應位置是「畫舫」（仄仄），上聯此處須平平，且為「形容詞＋名詞」的名詞語。「寒泉」平平，可替代的「瓊漿」也是平平，(B)正確。(A)醇酒、(D)新釀都是平仄；(C)玉液是仄仄，與下聯「畫舫」同聲調，都不合。", "skill": "先找出被替換詞在對句中的對應詞，判斷它的平仄，再選平仄相反、詞性相同的選項。"}], "difficulty": "難", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-1-44", "exam": "bc92-1", "nums": [44, 45, 46], "form": "題組", "img": "img/bc92-1-44.png", "source": "李白〈黃鶴樓送孟浩然之廣陵〉、張繼〈楓橋夜泊〉", "author": "李白、張繼", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "人物情感", "寫作手法"], "passage": "甲、故人西辭黃鶴樓，煙花三月下揚州。孤帆遠影碧山盡，唯見長江天際流。（李白〈黃鶴樓送孟浩然之廣陵〉）\n乙、月落烏啼霜滿天，江楓漁火對愁眠。姑蘇城外寒山寺，夜半鐘聲到客船。（張繼〈楓橋夜泊〉）", "translation": "甲：老朋友在黃鶴樓向西邊的我告別，在繁花似錦的三月順流東下揚州。孤船的遠影消失在碧山盡頭，只看見長江向天邊奔流。\n乙：月亮西落，烏鴉啼叫，寒霜布滿天地；江邊楓樹與漁船燈火，伴著滿懷愁緒的我難以入眠。姑蘇城外的寒山寺，半夜的鐘聲傳到了我的客船。", "keywords": [{"w": "故人", "m": "老朋友"}, {"w": "辭", "m": "告別"}, {"w": "煙花", "m": "春天繁花似錦的景色"}, {"w": "下", "m": "順流而下"}, {"w": "天際", "m": "天邊"}, {"w": "客船", "m": "旅人乘坐的船"}], "questions": [{"n": 44, "stem": "關於以上兩首詩的情境，下列敘述何者正確？", "options": {"A": "甲詩以「孤獨」為重點，乙詩以「離愁」為重點", "B": "甲詩寫出了年輕人的奔放，乙詩寫出了中年人的蕭瑟", "C": "甲詩寫出了離情依依的惆悵，乙詩寫出了思念故鄉的情懷", "D": "甲詩寫出了負笈他鄉的落寞，乙詩寫出了科舉失意的潦倒"}, "answer": "C", "explain": "甲詩李白送別孟浩然，目送孤帆直到消失，寫難分難捨的離情；乙詩張繼夜泊異鄉，「對愁眠」聽鐘聲，寫客居他鄉的旅愁鄉思，(C)正確。(A)甲詩重點是送別而非孤獨，乙詩不是寫與人分別的離愁；(B)詩中看不出年齡；(D)甲詩不是求學，乙詩也沒有寫科舉。", "skill": "先判斷每首詩的「事件」（送別、夜泊），再由事件推情感，避免選詩中沒有線索的推測（年齡、科舉）。"}, {"n": 45, "stem": "關於以上兩首詩的寫作手法，下列敘述何者正確？", "options": {"A": "甲乙兩詩的寫作季節相同", "B": "甲乙兩詩皆藉植物暗寓作者的境遇", "C": "甲詩空間發展是由遠到近，乙詩則由近到遠", "D": "甲詩以視覺描寫收尾，乙詩以聽覺描寫收尾"}, "answer": "D", "explain": "甲詩末句「唯見長江天際流」是眼睛所見（視覺），乙詩末句「夜半鐘聲到客船」是耳朵所聞（聽覺），(D)正確。(A)甲是春天（三月），乙是秋天（霜、江楓）；(B)兩詩沒有藉植物暗寓境遇；(C)甲詩是目送孤帆由近而遠，乙詩是由寺院鐘聲傳到客船，由遠而近，說法相反。", "skill": "比較寫作手法時逐項對照：季節找時間詞、感官找「見、聞、聲」、空間看視線移動方向。"}, {"n": 46, "stem": "根據甲詩的敘述，如果李白對孟浩然說了一段話，下列何者最有可能？", "options": {"A": "江南暮春，鶯啼柳長，願君遍遊名園，盡賞美景", "B": "時值盛夏，蜀中燠熱，請君避暑調息，善自珍重", "C": "蒙君不棄，東來相見，弟當避席倒屣，候君長亭", "D": "君將西行，塞外苦寒，容弟敬奉薄酒，以盡前歡"}, "answer": "A", "explain": "「煙花三月下揚州」，孟浩然在暮春三月前往江南揚州，李白祝他遍賞江南美景最合情境，(A)正確。(B)時間是春天不是盛夏，地點是揚州不是蜀中；(C)是歡迎對方來訪的話，不合送別情境；(D)孟浩然是往東去揚州，不是西行塞外。", "skill": "情境推論題先從詩中抓「時間、地點、方向、事件」四要素，再刪去任何一項不符的選項。"}], "difficulty": "中", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-1-47", "exam": "bc92-1", "nums": [47, 48], "form": "題組", "img": "img/bc92-1-47.png", "source": "《世說新語‧任誕》", "author": "劉義慶", "genre": "筆記小品", "types": ["人物情感", "句意理解", "文意推論"], "passage": "王子猷居山陰。夜大雪，眠覺，開室命酌酒，四望皎然；因起彷徨，詠左思〈招隱〉詩，忽憶戴安道。時戴在剡，即便夜乘小船就之，經宿方至，造門不前而返。人問其故，王曰：「吾本乘興而行，興盡而返，何必見戴！」", "translation": "王子猷住在山陰。一天夜裡下大雪，他睡醒後打開房門，叫人倒酒，四處望去一片潔白；於是起身徘徊，吟誦左思的〈招隱〉詩，忽然想起好友戴安道。當時戴安道住在剡縣，他就連夜坐小船去找他，經過一夜才到，到了門口卻不進去就回來了。有人問他原因，王子猷說：「我本來是趁著興致去的，興致沒了就回來，何必一定要見到戴安道！」", "keywords": [{"w": "眠覺", "m": "睡醒"}, {"w": "皎然", "m": "潔白明亮的樣子"}, {"w": "彷徨", "m": "徘徊"}, {"w": "就", "m": "前往、靠近"}, {"w": "經宿", "m": "經過一夜"}, {"w": "方", "m": "才"}, {"w": "造", "m": "到達"}, {"w": "乘興", "m": "趁著興致"}], "questions": [{"n": 47, "stem": "從王子猷的言行來看，下列何者最適合用來形容他的表現？", "options": {"A": "三心兩意", "B": "虎頭蛇尾", "C": "隨興自得", "D": "熱愛自然"}, "answer": "C", "explain": "王子猷雪夜興起就出發訪友，到了門口興致已盡就返回，自己說「乘興而行，興盡而返」，表現隨興而為、自得其樂的灑脫，(C)正確。(A)(B)都是貶義，指做事不專一或有始無終，不符合他從容自得的態度；(D)他雖欣賞雪景，但重點在「隨興」，不是熱愛自然。", "skill": "人物評價題以人物自己的說法（乘興而行，興盡而返）為準，再注意選項的褒貶色彩。"}, {"n": 48, "stem": "下列文句的解釋，何者正確？", "options": {"A": "「四望皎然」是因為大雪覆地，一片銀白", "B": "「因起彷徨」是因為思念友人戴安道", "C": "「經宿方至」是因為缺乏交通工具", "D": "「造門不前而返」是因為沒有人在家"}, "answer": "A", "explain": "夜裡下大雪，打開門四處望去潔白明亮，是雪覆蓋大地的景象，(A)正確。(B)起身徘徊是因為看到雪景、有了酒興，詠詩之後才「忽憶戴安道」；(C)他有坐小船，經過一夜才到是因為路途遠；(D)他是興致已盡才回去，文中沒說戴不在家。", "skill": "注意事件的先後順序（起彷徨→詠詩→忽憶戴），因果不能倒置；原因要以文中人物自己的說法為準。"}], "difficulty": "易", "label": "92年第一次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-4", "exam": "bc92-2", "nums": [4], "form": "單題", "img": "img/bc92-2-4.png", "source": "選項分別出自《論語‧子路》、中華民國國歌、白居易〈慈烏夜啼〉、周敦頤〈愛蓮說〉", "author": "孔子等", "genre": "經典語錄", "types": ["字詞解釋"], "passage": "(A)民安所錯其手足 (B)咨爾多士，為民前鋒 (C)夜夜夜半啼，聞者淚沾襟 (D)水陸草木之花，可愛者甚蕃", "translation": "(A)人民不知道手腳該放在哪裡（無所適從）。(B)啊！你們這些將士，要做人民的先鋒。(C)（烏鴉）每夜半夜啼叫，聽到的人淚水沾濕衣襟。(D)水上陸上草木的花，可愛的非常多。", "keywords": [{"w": "錯", "m": "通「措」，放置"}, {"w": "咨", "m": "感嘆詞，啊"}, {"w": "襟", "m": "衣襟，與「衿」同"}, {"w": "蕃", "m": "多，與「繁」同"}], "questions": [{"n": 4, "stem": "下列文句「」中的字，何者替換後意義改變？", "options": {"A": "民安所「錯」其手足──措", "B": "「咨」爾多士，為民前鋒──茲", "C": "夜夜夜半啼，聞者淚沾「襟」──衿", "D": "水陸草木之花，可愛者甚「蕃」──繁"}, "answer": "B", "explain": "(B)「咨」是感嘆詞「啊」，用來呼告；「茲」是「此、這」，換掉後意思就不同，所以選B。(A)「錯」通「措」，放置，替換後意思不變。(C)「襟」「衿」都指衣服前襟，意思相同。(D)「蕃」是多、茂盛，與「繁」同義。", "skill": "先把原句翻成白話，確認「」中字的意思，再看替換字是不是同義字或通假字；意思對不上的就是答案。"}], "difficulty": "中", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-5", "exam": "bc92-2", "nums": [5], "form": "單題", "img": "img/bc92-2-5.png", "source": "周邦彥〈浣溪沙〉、李煜〈清平樂〉", "author": "周邦彥、李煜", "genre": "古典詩詞曲", "types": ["詩詞賞析"], "passage": "周邦彥詞〈浣溪沙〉：「樓前芳草接天涯，勸君莫上最高梯。」李後主詞〈清平樂〉：「離恨恰如春草，更行更遠還生。」", "translation": "樓前的芳草一直延伸到天邊，勸你不要登上最高處（以免望見遠方更添愁）。離別的愁恨就像春天的草，走得越遠，它越是不斷生長。", "keywords": [{"w": "離恨", "m": "離別的愁恨"}, {"w": "更行更遠", "m": "越走越遠"}, {"w": "天涯", "m": "天邊，極遠處"}], "questions": [{"n": 5, "stem": "以上文句中的「草」，皆有何種象徵意義？", "options": {"A": "欣欣向榮的氣象", "B": "源源而來的挫折", "C": "綿綿不絕的鄉愁", "D": "默默省思的體悟"}, "answer": "C", "explain": "春草蔓延不斷、走到哪裡都長，詞人用它比喻離愁綿延不絕；李煜直接說「離恨恰如春草」，周邦彥說芳草連到天涯，登高望見只會更想念遠方，所以是「綿綿不絕的鄉愁」，選C。(A)草雖有生機，但兩句的情感是愁而非喜。(B)(D)句中沒有挫折、省思的意思。", "skill": "看「草」和哪種情緒連在一起（離恨、勸莫登高），再想草「連綿不斷」的特性，就能推出象徵的情感。"}], "difficulty": "易", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-9", "exam": "bc92-2", "nums": [9], "form": "單題", "img": "img/bc92-2-9.png", "source": "高適〈燕歌行〉", "author": "高適", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "戰士軍前半死生，美人帳下猶歌舞。", "translation": "前線的戰士死傷過半，將帥營帳中的美人卻還在唱歌跳舞。", "keywords": [{"w": "半死生", "m": "一半戰死；「死生」為偏義複詞，只取「死」義"}], "questions": [{"n": 9, "stem": "「戰士軍前半死生，美人帳下猶歌舞」詩句中的「死生」只有「死」的意思，下列文句「」中的語詞，何者用法與此相同？", "options": {"A": "他們的「恩怨」太深，所以常起衝突", "B": "你這樣的做法，未免太不知「好歹」", "C": "世態炎涼，如人飲水，「冷暖」自知", "D": "這件事的「是非」曲直，仍無人知曉"}, "answer": "A", "explain": "「死生」是偏義複詞：兩個意思相反的字合在一起，卻只用其中一個字的意思。(A)常起衝突是因為「怨」太深，「恩」沒有作用，是偏義複詞，選A。(B)「不知好歹」是分不清好壞，兩義都有。(C)「冷暖自知」冷和暖都要自己體會。(D)「是非曲直」對與錯都不清楚，兩義兼有。", "skill": "把相反的兩字分別代回句子：只有一個字說得通、另一個字沒作用，才是偏義複詞。"}], "difficulty": "中", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-11", "exam": "bc92-2", "nums": [11], "form": "單題", "img": "img/bc92-2-11.png", "source": "《三字經》", "author": "王應麟（相傳）", "genre": "經典語錄", "types": ["文意推論", "文化常識"], "passage": "高、曾、祖，父而身，身而子，子而孫，自子孫，至玄、曾，乃九族，人之倫。", "translation": "從高祖、曾祖、祖父，到父親再到自己，自己再到兒子，兒子再到孫子，從子孫再到曾孫、玄孫，這就是九族，是人倫的次序。", "keywords": [{"w": "身", "m": "自己"}, {"w": "玄、曾", "m": "玄孫、曾孫"}, {"w": "九族", "m": "從高祖到玄孫共九代"}, {"w": "倫", "m": "次序、輩分"}], "questions": [{"n": 11, "stem": "「高、曾、祖，父而身，身而子，子而孫，自子孫，至玄、曾，乃九族，人之倫。」由這段文字可推知「高祖父」是誰？", "options": {"A": "父親的父親", "B": "父親的祖父", "C": "祖父的父親", "D": "祖父的祖父"}, "answer": "D", "explain": "依文中順序往上排：自己→父→祖（祖父）→曾（曾祖父）→高（高祖父）。曾祖父是祖父的父親，高祖父再往上一代，就是祖父的祖父，選D。(A)是祖父，(B)(C)都是曾祖父。", "skill": "把文言中的輩分順序畫成一條直線，從「身」往上一代一代數，就能判斷稱謂。"}], "difficulty": "易", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-12", "exam": "bc92-2", "nums": [12], "form": "單題", "img": "img/bc92-2-12.png", "source": "《宋史‧蘇軾傳》", "author": "脫脫等", "genre": "史傳人物", "types": ["句意理解", "文意推論"], "passage": "軾以書見歐陽修，修語梅聖俞曰：「吾當避此人出一頭地。」", "translation": "蘇軾帶著文章去拜見歐陽修，歐陽修對梅聖俞說：「我應當避開這個人，讓他高出眾人一頭。」", "keywords": [{"w": "以書見", "m": "帶著文章去拜見"}, {"w": "語", "m": "告訴"}, {"w": "避", "m": "讓開"}, {"w": "出一頭地", "m": "高人一等"}], "questions": [{"n": 12, "stem": "《宋史》載：「軾以書見歐陽修，修語梅聖俞曰：『吾當避此人出一頭地。』」句中的「此人」指的是誰？", "options": {"A": "《宋史》的作者", "B": "蘇軾", "C": "歐陽修", "D": "梅聖俞"}, "answer": "B", "explain": "歐陽修是對梅聖俞說話，話中要讓路的「此人」就是剛來拜見他的蘇軾，選B。(C)歐陽修是說話者，自稱「吾」。(D)梅聖俞是聽話的人。(A)與句子無關。", "skill": "先分清楚誰在說話（主語）、對誰說（對象），句中的「此人」就是第三位被談論的人。"}], "difficulty": "易", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-16", "exam": "bc92-2", "nums": [16], "form": "單題", "img": "img/bc92-2-16.png", "source": "選項出自杜甫〈夢李白〉、蘇軾〈水調歌頭〉、庾信〈徵調曲〉、王維〈九月九日憶山東兄弟〉", "author": "杜甫、蘇軾、庾信、王維", "genre": "古典詩詞曲", "types": ["句意理解", "文化常識"], "passage": "(A)死別已吞聲，生別長惻惻 (B)但願人長久，千里共嬋娟 (C)落其實者思其樹，飲其流者懷其源 (D)獨在異鄉為異客，每逢佳節倍思親", "translation": "(A)死別已讓人忍聲哭泣，生離更讓人長久悲傷。(B)只願親人長久平安，相隔千里也能共賞明月。(C)吃果實的人想到結果的樹，喝流水的人懷念水的源頭。(D)獨自在外地作客，每逢節日更加思念親人。", "keywords": [{"w": "吞聲", "m": "不敢出聲地哭"}, {"w": "惻惻", "m": "悲傷的樣子"}, {"w": "嬋娟", "m": "指月亮"}, {"w": "實", "m": "果實"}], "questions": [{"n": 16, "stem": "春節祭祖，清明掃墓。這些習俗表達了何種意義？", "options": {"A": "死別已吞聲，生別長惻惻", "B": "但願人長久，千里共嬋娟", "C": "落其實者思其樹，飲其流者懷其源", "D": "獨在異鄉為異客，每逢佳節倍思親"}, "answer": "C", "explain": "祭祖、掃墓是追念祖先、感恩根源，和(C)「吃果子想到樹、喝水想到源頭」的飲水思源精神相同，選C。(A)寫生離死別的悲傷。(B)祝願遠方親人平安。(D)寫遊子佳節思親，都不是感念祖先。", "skill": "先說出習俗的核心意義（感恩祖先＝飲水思源），再逐一翻譯選項，找意思相同的一句。"}], "difficulty": "易", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-19", "exam": "bc92-2", "nums": [19], "form": "單題", "img": "img/bc92-2-19.png", "source": "選項(B)出自蘇軾〈次韻定慧欽長老見寄〉，(D)出自白居易〈望月有感〉，(A)(C)出處待查", "author": "蘇軾、白居易等", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)白髮悲花落，青雲羨鳥飛 (B)愛鼠常留飯，憐蛾不點燈 (C)薄命生遭風雨妒，多情枉受蝶蜂憐 (D)共看明月應垂淚，一夜鄉心五處同", "translation": "(A)白髮的人為花落而悲傷，羨慕鳥兒飛上青雲。(B)愛惜老鼠所以常留些飯，憐惜飛蛾所以夜裡不點燈。(C)命薄，生來就遭風雨嫉妒，空受蝴蝶蜜蜂的憐愛。(D)一同看著明月應該都會落淚，這一夜分散五地的親人有同樣的思鄉之心。", "keywords": [{"w": "憐", "m": "憐惜"}, {"w": "青雲", "m": "高空，也比喻高位"}, {"w": "五處", "m": "分散在五個地方的親人"}], "questions": [{"n": 19, "stem": "下列詩詞，何者最能表露出慈悲心腸？", "options": {"A": "白髮悲花落，青雲羨鳥飛", "B": "愛鼠常留飯，憐蛾不點燈", "C": "薄命生遭風雨妒，多情枉受蝶蜂憐", "D": "共看明月應垂淚，一夜鄉心五處同"}, "answer": "B", "explain": "(B)為老鼠留飯、怕飛蛾撲火而不點燈，對小動物都不忍傷害，最能表現慈悲心腸，選B。(A)是感傷年老、羨慕高飛。(C)感嘆薄命。(D)寫親人離散的思鄉之情。", "skill": "慈悲＝愛護、不忍傷害其他生命；把選項翻成白話，找出「對別的生命付出愛護行動」的那一句。"}], "difficulty": "易", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-22", "exam": "bc92-2", "nums": [22], "form": "單題", "img": "img/bc92-2-22.png", "source": "韋莊〈臺城〉；選項出自李白〈登金陵鳳凰臺〉、趙翼〈論詩〉、〈易水歌〉、文天祥〈過零丁洋〉", "author": "韋莊", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "江雨霏霏江草齊，六朝如夢鳥空啼。無情最是臺城柳，依舊煙籠十里堤。", "translation": "江上細雨綿綿，江邊青草長得整齊，六朝的繁華像一場夢，只剩鳥兒白白啼叫。最無情的是臺城的柳樹，依舊像煙霧般籠罩著十里長堤。", "keywords": [{"w": "霏霏", "m": "雨細密的樣子"}, {"w": "六朝", "m": "建都金陵的六個朝代"}, {"w": "空", "m": "徒然、白白地"}, {"w": "煙籠", "m": "如煙霧般籠罩"}], "questions": [{"n": 22, "stem": "「江雨霏霏江草齊，六朝如夢鳥空啼。無情最是臺城柳，依舊煙籠十里堤。」這是一首詠史詩，下列何者所抒發的情感與此詩相近？", "options": {"A": "吳宮花草埋幽徑，晉代衣冠成古丘", "B": "江山代有才人出，各領風騷數百年", "C": "風蕭蕭兮易水寒，壯士一去兮不復返", "D": "人生自古誰無死，留取丹心照汗青"}, "answer": "A", "explain": "〈臺城〉以景物依舊對比六朝繁華消逝，抒發「繁華如夢」的興亡感慨。(A)吳宮的花草埋沒在小路，晉代的名士都成了荒墳，同樣是憑弔古都、感嘆繁華消逝，選A。(B)讚嘆每個時代都有人才。(C)寫壯士赴死的悲壯。(D)表達以死明志的忠貞。", "skill": "先抓題幹詩的情感關鍵（今昔對比→興亡之嘆），再找選項中同樣「古今對照、繁華成空」的句子。"}], "difficulty": "中", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-24", "exam": "bc92-2", "nums": [24], "form": "單題", "img": "img/bc92-2-24.png", "source": "選項出自杜牧〈秋夕〉、黃庭堅〈鄂州南樓書事〉、陸游〈遊山西村〉、納蘭性德〈浣溪沙〉", "author": "杜牧、黃庭堅、陸游、納蘭性德", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "(A)天階月色涼如水，坐看牽牛織女星 (B)四顧山光接水光，憑欄十里芰荷香 (C)莫笑農家臘酒渾，豐年留客足雞豚 (D)誰念西風獨自涼，蕭蕭黃葉閉疏窗", "translation": "(A)石階上的月光清涼如水，坐著看牽牛星和織女星。(B)四面望去山色連著水光，倚著欄杆，十里荷花飄香。(C)別笑農家臘月釀的酒混濁，豐收年頭招待客人有足夠的雞和豬肉。(D)有誰在意西風吹來我獨自淒涼，黃葉蕭蕭飄落，我關上了窗。", "keywords": [{"w": "芰荷", "m": "菱葉與荷花"}, {"w": "臘酒", "m": "臘月（農曆十二月）釀的酒"}, {"w": "西風", "m": "秋風"}, {"w": "牽牛織女", "m": "七夕的星，點出秋季"}], "questions": [{"n": 24, "stem": "詩句往往透露季節線索，如「吹面不寒楊柳風」提供春季的線索。下列詩句與季節的配對，何者正確？", "options": {"A": "天階月色涼如水，坐看牽牛織女星──春", "B": "四顧山光接水光，憑欄十里芰荷香──夏", "C": "莫笑農家臘酒渾，豐年留客足雞豚──秋", "D": "誰念西風獨自涼，蕭蕭黃葉閉疏窗──冬"}, "answer": "B", "explain": "(B)「芰荷香」荷花盛開，是夏天，配對正確。(A)夜涼、看牛郎織女星（七夕），是秋天。(C)「臘酒」是臘月釀的酒，飲用多在歲暮新春，不是秋天。(D)「西風」「黃葉」是秋天。", "skill": "找出每句中的季節關鍵物（花、風、節日、農事），再對照季節，不要被「豐年」這類非季節詞誤導。"}], "difficulty": "中", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-28", "exam": "bc92-2", "nums": [28], "form": "單題", "img": "img/bc92-2-28.png", "source": "題幹出自陳之藩〈謝天〉；選項出自《史記‧商君列傳》、陶淵明〈五柳先生傳〉、《孟子‧告子下》、俗諺", "author": "陳之藩、陶淵明、孟子等", "genre": "經典語錄", "types": ["虛詞句式"], "passage": "(A)是法不信於民 (B)不戚戚於貧賤 (C)舜發於畎畝之中 (D)一生之計在於勤", "translation": "(A)這是法令不被人民信任。(B)不因貧賤而憂愁。(C)舜從田野之中被起用。(D)一生的計畫在於勤勞。", "keywords": [{"w": "於", "m": "介詞，可解作「從」「被」「對、因」「在」等"}, {"w": "戚戚", "m": "憂愁的樣子"}, {"w": "發", "m": "興起、被起用"}, {"w": "畎畝", "m": "田野"}], "questions": [{"n": 28, "stem": "「得之於人者太多」句中的「於」字和下列何者意思相同？", "options": {"A": "是法不信「於」民", "B": "不戚戚「於」貧賤", "C": "舜發「於」畎畝之中", "D": "一生之計在「於」勤"}, "answer": "C", "explain": "題幹「得之於人」是「從別人那裡得到」，「於」＝從。(C)舜從田野中被起用，「於」也是「從」，選C。(A)「不信於民」是不被人民信任，「於」表被動（被）。(B)「於」是「對於、因為」。(D)「在於」的「於」相當於「在」。", "skill": "把「於」分別代入「從、被、對、在」，看哪一個讓句子最通順，再比對題幹的用法。"}], "difficulty": "中", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-31", "exam": "bc92-2", "nums": [31], "form": "單題", "img": "img/bc92-2-31.png", "source": "《論語‧里仁》", "author": "孔子", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "子曰：「事父母，幾諫。」", "translation": "孔子說：「侍奉父母，（父母有過錯時）要委婉地勸諫。」", "keywords": [{"w": "事", "m": "侍奉"}, {"w": "幾", "m": "委婉"}, {"w": "諫", "m": "勸告長輩改正過錯"}], "questions": [{"n": 31, "stem": "子曰：「事父母，幾諫。」下列敘述何者符合這句話的精神？", "options": {"A": "並肩作戰，親子如友", "B": "互助合作，親子連心", "C": "當仁不讓，大義滅親", "D": "理直氣和，親子雙贏"}, "answer": "D", "explain": "「幾諫」是父母有過錯要勸，但態度要委婉溫和。(D)「理直氣和」：道理站得住，語氣仍然溫和，正是幾諫的精神，選D。(A)(B)講合作、親近，與「勸諫」無關。(C)「大義滅親」太過強硬，與「委婉」相反。", "skill": "先看注釋確認關鍵字「幾＝委婉」，把句意拆成「要勸」和「態度委婉」兩部分，選項要兩者都符合。"}], "difficulty": "易", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-34", "exam": "bc92-2", "nums": [34], "form": "單題", "img": "img/bc92-2-34.png", "source": "選項出自〈木蘭詩〉、沈復〈兒時記趣〉、《禮記‧檀弓上》、《論語‧八佾》", "author": "佚名、沈復等", "genre": "經典語錄", "types": ["字詞解釋", "虛詞句式"], "passage": "(A)願為市鞍馬，從此替爺征 (B)捉蝦蟆，鞭數十，驅之別院 (C)生，於我乎館；死，於我乎殯 (D)揖讓而升，下而飲，其爭也君子", "translation": "(A)願意為此去買鞍和馬，從此代替父親出征。(B)捉住蛤蟆，鞭打幾十下，把牠趕到別的院子。(C)（朋友）活著，就到我家住；死了，就由我來殯殮。(D)彼此作揖謙讓後上堂，比完下堂一起飲酒，這樣的競爭是君子之爭。", "keywords": [{"w": "市", "m": "買（名詞轉動詞）"}, {"w": "鞭", "m": "用鞭子打（名詞轉動詞）"}, {"w": "館", "m": "住宿（名詞轉動詞）"}, {"w": "飲", "m": "喝酒（本為動詞）"}], "questions": [{"n": 34, "stem": "「而今早已年過而立，自然不再是涎著臉要求母親摺紙船的年紀。」句中的「涎」字，由原來的名詞（口水）轉為動詞（流口水）使用。下列選項「」中的字，何者不屬於此類？", "options": {"A": "願為「市」鞍馬，從此替爺征", "B": "捉蝦蟆，「鞭」數十，驅之別院", "C": "生，於我乎「館」；死，於我乎殯", "D": "揖讓而升，下而「飲」，其爭也君子"}, "answer": "D", "explain": "(D)「飲」本來就是動詞「喝」，沒有詞性轉變，選D。(A)「市」本是市場（名詞），這裡當「購買」。(B)「鞭」本是鞭子（名詞），這裡當「鞭打」。(C)「館」本是館舍（名詞），這裡當「住宿」。", "skill": "先確定該字平常的詞性，再看它在句中是不是當動作用；原本是名詞卻當動作用，就是名詞轉動詞。"}], "difficulty": "中", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-45", "exam": "bc92-2", "nums": [45, 46], "form": "題組", "img": "img/bc92-2-45.png", "source": "魏學洢〈核舟記〉", "author": "魏學洢", "genre": "筆記小品", "types": ["句意理解", "寫作手法"], "passage": "船頭坐三人，中峨冠而多髯者為東坡，佛印居右，魯直居左。蘇、黃共閱一手卷；東坡右手執卷端，左手撫魯直背；魯直左手執卷末，右手指卷，如有所語。東坡現右足，魯直現左足，身各微側；其兩膝相比者，各隱卷底衣褶中。佛印絕類彌勒，袒胸露乳，矯首昂視，神情與蘇、黃不屬。臥右膝，詘右臂支船，而豎其左膝，左臂掛念珠倚之，珠可歷歷數也。", "translation": "船頭坐著三個人，中間戴高帽、鬍鬚濃密的是蘇東坡，佛印在右邊，黃魯直在左邊。蘇、黃一同看一卷字畫；東坡右手拿著卷頭，左手撫著魯直的背；魯直左手拿著卷尾，右手指著卷子，好像在說些什麼。東坡露出右腳，魯直露出左腳，身體都稍微側著；兩人相靠的膝蓋，都藏在卷子下的衣服皺褶裡。佛印很像彌勒佛，敞開胸懷，抬頭仰望，神情和蘇、黃不相關。他右膝平放，彎著右臂撐在船上，豎起左膝，左臂掛著念珠靠在膝上，念珠一顆一顆清清楚楚數得出來。", "keywords": [{"w": "峨冠", "m": "高帽"}, {"w": "髯", "m": "鬍鬚"}, {"w": "比", "m": "靠近"}, {"w": "絕類", "m": "非常像"}, {"w": "矯首", "m": "抬頭"}, {"w": "不屬", "m": "不相關連"}, {"w": "詘", "m": "同「屈」，彎曲"}, {"w": "歷歷", "m": "清楚分明的樣子"}], "questions": [{"n": 45, "stem": "本文是描繪王叔遠所雕刻的核舟，下列何者最適合用來形容王叔遠的技術？", "options": {"A": "出神入化", "B": "畫龍點睛", "C": "歷歷在目", "D": "游刃有餘"}, "answer": "A", "explain": "小小桃核上刻出三人的神情、動作，連念珠都能一顆顆數，技藝高超到神妙的境界，用「出神入化」最恰當，選A。(B)畫龍點睛指在關鍵處加一筆使全體生動，不是形容整體技藝。(C)歷歷在目是景象清楚浮現眼前，不是形容技術。(D)游刃有餘指做事熟練輕鬆，表現不出「神妙」的程度。", "skill": "先從細節（念珠可數、神情各異）判斷文章要表現「技藝神妙」，再選最能形容技藝最高境界的詞語。"}, {"n": 46, "stem": "下列何者是本文的特色？", "options": {"A": "分析事理，鞭辟入裡", "B": "抒情寫志，意味深永", "C": "鉤勒事物，細緻生動", "D": "品評人事，幽默風趣"}, "answer": "C", "explain": "全文依位置、動作、神情一一描寫船頭三人，連膝蓋、念珠都寫到，是細膩生動的描摹，選C。(A)沒有分析道理。(B)沒有抒發作者情志。(D)只描寫雕刻，沒有品評人物或幽默。", "skill": "判斷文體：文中多是「誰在哪裡、做什麼、長什麼樣」的句子，就是描寫文，特色在細膩刻畫。"}], "difficulty": "中", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc92-2-47", "exam": "bc92-2", "nums": [47, 48], "form": "題組", "img": "img/bc92-2-47.png", "source": "丘逢甲〈有感書贈義軍舊書記〉二首", "author": "丘逢甲", "genre": "古典詩詞曲", "types": ["人物情感", "詩詞賞析", "句意理解"], "passage": "拜將壇高卓義旗，五洲睽目屬雄師，當時力保危臺意，只有軍前壯士知。※※※宰相有權能割地，孤臣無力可回天，啼鵑喚起東都夢，沈鬱風雲已五年。", "translation": "高高的拜將壇上豎起義軍大旗，全世界都睜大眼睛注視這支雄師；當時拚力保衛危急臺灣的心意，只有軍中的壯士們了解。宰相有權力割讓土地，我這孤臣卻沒有力量挽回局勢；杜鵑的啼聲喚起我對東都（臺灣）的夢，鬱悶不得志已經五年了。", "keywords": [{"w": "卓", "m": "豎立"}, {"w": "睽目", "m": "睜大眼睛注視"}, {"w": "屬", "m": "注視、關注"}, {"w": "危臺", "m": "危急的臺灣"}, {"w": "孤臣", "m": "孤立無援的臣子，作者自稱"}, {"w": "回天", "m": "挽回局勢"}, {"w": "東都", "m": "指臺灣"}], "questions": [{"n": 47, "stem": "這兩首詩抒發了作者什麼情緒？", "options": {"A": "思念故國的愁緒", "B": "壯志難酬的慨嘆", "C": "年老力衰的無奈", "D": "同袍離散的遺憾"}, "answer": "B", "explain": "詩中回憶率義軍保臺的壯舉，接著說宰相割地、「孤臣無力可回天」，抒發想救臺灣卻無能為力的悲憤，是「壯志難酬」，選B。(A)雖有「東都夢」思念臺灣，但主軸是理想落空，不宜說「思念故國」。(C)詩中沒寫年老。(D)沒寫與同袍分離。", "skill": "抓詩中情緒最重的句子（孤臣無力可回天、沈鬱已五年），判斷是「有志卻做不到」，再對應選項。"}, {"n": 48, "stem": "下列詞語何者指的是作者本人？", "options": {"A": "五洲", "B": "壯士", "C": "孤臣", "D": "啼鵑"}, "answer": "C", "explain": "「孤臣無力可回天」是作者自稱孤立無援、無力挽回割臺的局面，選C。(A)五洲指世界各國。(B)壯士指軍中將士。(D)啼鵑是啼叫的杜鵑鳥，用來引出思鄉之夢。", "skill": "用作者背景（率義軍抗日失敗）對照詞語：誰「無力回天」？那就是作者自己。"}], "difficulty": "中", "label": "92年第二次基測", "year": 92, "kind": "基測"}, {"id": "bc93-1-2", "exam": "bc93-1", "nums": [2], "form": "單題", "img": "img/bc93-1-2.png", "source": "彭端淑〈為學一首示子姪〉", "author": "彭端淑", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "天下事有難易乎？為之，則難者亦易矣；不為，則易者亦難矣。人之為學有難易乎？學之，則難者亦易矣；不學，則易者亦難矣。", "translation": "天下的事情有困難和容易的分別嗎？只要肯去做，困難的也會變容易；不去做，容易的也會變困難。人們求學有困難和容易的分別嗎？只要肯學，困難的也會變容易；不學，容易的也會變困難。", "keywords": [{"w": "為之", "m": "去做它"}, {"w": "亦", "m": "也"}, {"w": "為學", "m": "求學、做學問"}], "questions": [{"n": 2, "stem": "「天下事有難易乎？為之，則難者亦易矣；不為，則易者亦難矣。人之為學有難易乎？學之，則難者亦易矣；不學，則易者亦難矣。」下列敘述，何者不符合這段話的觀點？", "options": {"A": "只要有心學習，天下無難事", "B": "倘若不肯用心，天下皆難事", "C": "不論用心與否，為學皆不易", "D": "為學並不困難，只怕無心學"}, "answer": "C", "explain": "本段強調難易不在事情本身，而在於肯不肯做、肯不肯學。(C)說「不論用心與否，為學皆不易」，否定了用心的作用，與原文相反，所以是不符合的選項，選C。(A)(D)對應「學之，則難者亦易矣」。(B)對應「不為／不學，則易者亦難矣」。", "skill": "抓出文中的條件句「為之則…；不為則…」，判斷作者認為決定難易的關鍵是什麼，再找與這個關鍵矛盾的選項。"}], "difficulty": "易", "label": "93年第一次基測", "year": 93, "kind": "基測"}, {"id": "bc93-1-3", "exam": "bc93-1", "nums": [3], "form": "單題", "img": "img/bc93-1-3.png", "source": "林瀚〈誡子弟〉", "author": "林瀚", "genre": "古典詩詞曲", "types": ["主旨寓意", "詩詞賞析"], "passage": "何事紛爭一角牆，讓他幾尺也無妨；長城萬里今猶在，不見當年秦始皇。", "translation": "為什麼要為了一角牆壁爭吵不休？讓給他幾尺也沒有關係；萬里長城到今天還在，可是當年修築它的秦始皇早已不見了。", "keywords": [{"w": "何事", "m": "為什麼"}, {"w": "紛爭", "m": "爭吵"}, {"w": "無妨", "m": "沒有妨礙、不要緊"}], "questions": [{"n": 3, "stem": "明朝林瀚〈誡子弟〉云：「何事紛爭一角牆，讓他幾尺也無妨；長城萬里今猶在，不見當年秦始皇。」這首詩最主要是在告誡子弟什麼道理？", "options": {"A": "勿逞強好勝，理性寬容萬事通", "B": "勿臨渴掘井，事未至而預先謀", "C": "勿好高騖遠，腳踏實地必有成", "D": "勿驕傲自負，聰明反被聰明誤"}, "answer": "A", "explain": "前兩句勸子弟不要為一點地界爭吵，讓一讓也無妨；後兩句以秦始皇為例，說明再大的土地也帶不走，何必計較。主旨是不要爭強好勝、要寬容退讓，選A。(B)講預先準備。(C)講踏實努力。(D)講不要自恃聰明，皆與詩意無關。", "skill": "先看詩題「誡子弟」與前兩句的勸告（讓他幾尺），後兩句是舉例佐證；主旨通常就在勸告句中。"}], "difficulty": "易", "label": "93年第一次基測", "year": 93, "kind": "基測"}, {"id": "bc93-1-8", "exam": "bc93-1", "nums": [8], "form": "單題", "img": "img/bc93-1-8.png", "source": "王維詩句：(A)〈過香積寺〉(B)〈終南別業〉(C)〈出塞作〉(D)〈積雨輞川莊作〉", "author": "王維", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "(A)泉聲咽危石，日色冷青松 (B)行到水窮處，坐看雲起時 (C)暮雲空磧時驅馬，秋日平原好射雕 (D)山中習靜觀朝槿，松下清齋折露葵", "translation": "(A)泉水流過亂石，聲音像在嗚咽；陽光照在青松上，顯得清冷。(B)走到溪水的盡頭，就坐下來看雲升起。(C)傍晚雲低、在沙漠上縱馬奔馳，秋天的平原正適合射鵰。(D)在山中靜修，觀賞早上開花的木槿；在松樹下吃素齋，摘取帶露的葵菜。", "keywords": [{"w": "咽", "m": "嗚咽，聲音低沉阻塞"}, {"w": "危石", "m": "亂石"}, {"w": "空磧", "m": "沙漠"}, {"w": "射雕", "m": "射鵰，形容勇武"}, {"w": "習靜", "m": "修習靜定"}, {"w": "清齋", "m": "素食"}], "questions": [{"n": 8, "stem": "王維早年詩風積極進取，雄渾豪邁；中年以後風格轉為清雅閑淡，意境悠遠。下列詩句，何者最可能是他早年的作品？", "options": {"A": "泉聲咽危石，日色冷青松", "B": "行到水窮處，坐看雲起時", "C": "暮雲空磧時驅馬，秋日平原好射雕", "D": "山中習靜觀朝槿，松下清齋折露葵"}, "answer": "C", "explain": "(C)在沙漠縱馬、在平原射鵰，畫面開闊、充滿豪氣，符合「雄渾豪邁」的早年詩風，選C。(A)寫幽寂清冷的山寺景色。(B)寫隨遇而安的閒適心境。(D)寫山居靜修、吃素的生活。三者都屬清雅閑淡的後期風格。", "skill": "先把題幹給的兩種風格變成判斷標準（豪邁 vs. 閑淡），再看每句的動作與景物是「激昂奔放」還是「安靜悠閒」。"}], "difficulty": "中", "label": "93年第一次基測", "year": 93, "kind": "基測"}, {"id": "bc93-1-9", "exam": "bc93-1", "nums": [9], "form": "單題", "img": "img/bc93-1-9.png", "source": "對聯（出處待查）", "author": "佚名", "genre": "其他", "types": ["文化常識", "句意理解"], "passage": "(A)門集春夏秋冬福，戶納東西南北財 (B)萬戶春風為子壽，半窗松雪論天倫 (C)春風得意千條綠，快馬加鞭萬里程 (D)立節可為千載道，成文自足一家言", "translation": "(A)門口聚集一年四季的福氣，家中收進四面八方的財富。(B)家家戶戶的春風為孩子祝壽，窗前松雪中談論天倫之樂。(C)春風得意、萬物翠綠，快馬加鞭奔向萬里前程。(D)建立節操可以成為千年傳頌的道理，寫成文章足以自成一家之言。", "keywords": [{"w": "立節", "m": "樹立節操"}, {"w": "成文", "m": "寫成文章"}, {"w": "一家言", "m": "自成一派的見解或著作"}, {"w": "天倫", "m": "家人親情"}], "questions": [{"n": 9, "stem": "下列對聯，何者最適合貼在書房門口？", "options": {"A": "門集春夏秋冬福，戶納東西南北財", "B": "萬戶春風為子壽，半窗松雪論天倫", "C": "春風得意千條綠，快馬加鞭萬里程", "D": "立節可為千載道，成文自足一家言"}, "answer": "D", "explain": "書房是讀書寫作的地方，(D)勉勵人樹立節操、寫出能自成一家的文章，與讀書著述相關，選D。(A)祈福求財，適合大門或商家。(B)祝壽、談天倫，適合壽宴或家庭。(C)春風得意、快馬加鞭，適合春聯或祝賀前程。", "skill": "先想場所的功能（書房＝讀書、著述），再從對聯中找與這個功能相關的關鍵詞（成文、一家言）。"}], "difficulty": "易", "label": "93年第一次基測", "year": 93, "kind": "基測"}, {"id": "bc93-1-12", "exam": "bc93-1", "nums": [12], "form": "單題", "img": "img/bc93-1-12.png", "source": "陳陶〈隴西行〉", "author": "陳陶", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "誓掃匈奴不顧身，五千貂錦喪胡塵。可憐無定河邊骨，猶是春閨夢裡人。", "translation": "將士們發誓掃平匈奴，奮不顧身，五千名精銳戰士戰死在胡地的沙塵中。可憐那無定河邊的白骨，還是家中妻子夢裡思念的人。", "keywords": [{"w": "貂錦", "m": "穿貂裘錦衣的精銳部隊"}, {"w": "胡塵", "m": "胡地的戰塵"}, {"w": "春閨", "m": "女子的閨房，指戰士的妻子"}], "questions": [{"n": 12, "stem": "李小明在書中看到一首詩：「誓掃匈奴不顧身，五千貂錦喪胡塵。可憐無定河邊骨，猶是春閨夢裡人。」他和幾位同學討論這首詩，下列哪一個人的說法正確？", "options": {"A": "陳大同：此詩是七言絕句", "B": "王一修：這是一首田園詩", "C": "趙向前：詩中有兩個韻腳", "D": "錢來也：詩中有一組對句"}, "answer": "A", "explain": "全詩四句、每句七字，是七言絕句，選A。(B)內容寫戰爭死亡與閨中思念，是邊塞詩，不是田園詩。(C)韻腳是「身、塵、人」三個（第一、二、四句押韻）。(D)四句之間沒有字數詞性相對的對句。", "skill": "判斷近體詩：先數句數與字數定體裁，再看一、二、四句末字找韻腳，最後看上下句詞性是否兩兩相對。"}], "difficulty": "易", "label": "93年第一次基測", "year": 93, "kind": "基測"}, {"id": "bc93-1-16", "exam": "bc93-1", "nums": [16], "form": "單題", "img": "img/bc93-1-16.png", "source": "洪應明《菜根譚》", "author": "洪應明", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "攻人之惡，毋太嚴，要思其堪受；教人以善，毋過高，當使其可從。", "translation": "批評別人的過錯，不要太嚴厲，要想想他能不能承受；教導別人行善，不要要求太高，應該讓他做得到。", "keywords": [{"w": "攻", "m": "指責、批評"}, {"w": "毋", "m": "不要"}, {"w": "堪", "m": "能夠承受"}, {"w": "從", "m": "依從、做到"}], "questions": [{"n": 16, "stem": "「攻人之惡，毋太嚴，要思其堪受；教人以善，毋過高，當使其可從。」這段話的含義，與下列哪一個選項最接近？", "options": {"A": "打人莫打膝，勝人莫以謀", "B": "勸善責過於人，宜適其性量其力", "C": "知過不難改過難，言善不難行善難", "D": "勿以惡小而為之，勿以善小而不為"}, "answer": "B", "explain": "原文說批評與教導別人都要考慮對方的承受力與能力。(B)勸人為善、責備過錯都要配合對方的個性、衡量他的能力，意思最接近，選B。(A)講待人留餘地、不用計謀取勝。(C)講知易行難。(D)講不可輕忽小善小惡，都不是在談「怎麼勸人」。", "skill": "把文言拆成兩組「做什麼（攻人之惡、教人以善）＋要注意什麼（堪受、可從）」，再找同時具備這兩點的選項。"}], "difficulty": "中", "label": "93年第一次基測", "year": 93, "kind": "基測"}, {"id": "bc93-1-27", "exam": "bc93-1", "nums": [27], "form": "單題", "img": "img/bc93-1-27.png", "source": "題幹出自《孟子‧離婁下》；選項出自《孟子‧告子下》、《孟子‧滕文公下》、俗語、《論語‧泰伯》", "author": "孟子、曾子等", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "君子有終身之憂，無一朝之患。(A)生於憂患，死於安樂 (B)入則孝，出則弟，守先待後 (C)頭可斷，血可流，身不可辱 (D)士不可不弘毅，任重而道遠", "translation": "君子有一輩子的憂慮（擔心自己德行不如聖賢），卻沒有一時的禍患。(A)憂患使人生存，安樂使人滅亡。(B)在家孝順父母，出外敬重兄長，守住先王之道以傳給後人。(C)頭可以斷、血可以流，人格卻不能受辱。(D)讀書人不能不心胸寬廣、意志堅毅，因為責任重大而路途遙遠。", "keywords": [{"w": "終身之憂", "m": "一輩子念念不忘的憂慮，指修養德行"}, {"w": "一朝之患", "m": "一時的禍患"}, {"w": "弘毅", "m": "寬廣而堅毅"}, {"w": "弟", "m": "同「悌」，敬愛兄長"}], "questions": [{"n": 27, "stem": "下列何者與「君子有終身之憂，無一朝之患」的「終身之憂」涵義相近？", "options": {"A": "生於憂患，死於安樂", "B": "入則孝，出則弟，守先待後", "C": "頭可斷，血可流，身不可辱", "D": "士不可不弘毅，任重而道遠"}, "answer": "D", "explain": "孟子說君子一輩子憂慮的是自己不能像舜一樣成為天下的典範，是對理想與責任的長久承擔。(D)讀書人擔負重任、路途遙遠，必須終身努力，涵義最接近，選D。(A)講憂患可使人奮發，重點不同。(B)講孝悌與傳承。(C)講氣節不可受辱。", "skill": "先弄清「終身之憂」憂的是什麼（追求德業理想、一生不懈），再找同樣強調「長期承擔責任」的句子。"}], "difficulty": "難", "label": "93年第一次基測", "year": 93, "kind": "基測"}, {"id": "bc93-1-41", "exam": "bc93-1", "nums": [41, 42], "form": "題組", "img": "img/bc93-1-41.png", "source": "劉義慶《世說新語‧德行》", "author": "劉義慶", "genre": "筆記小品", "types": ["人物情感", "句意理解", "文意推論"], "passage": "華歆、王朗俱乘船避難，有一人欲依附，歆輒難之。朗曰：「幸尚寬，何為不可？」後賊追至，王欲舍所攜人。歆曰：「本所以疑，正為此耳。既已納其自託，寧可以急相棄邪？」遂攜拯如初。世以此定華、王之優劣。", "translation": "華歆、王朗一起搭船避難，有一個人想搭船，華歆立刻表示為難。王朗說：「幸好船上還寬敞，為什麼不行呢？」後來賊兵追來，王朗想丟下那個帶上船的人。華歆說：「我當初猶豫，正是為了這種情況。既然已經接受他的請託，怎麼可以因為危急就拋棄他呢？」於是仍像當初一樣帶著、救助他。世人就以這件事來評定華歆、王朗的高下。", "keywords": [{"w": "俱", "m": "一起"}, {"w": "依附", "m": "搭船、投靠"}, {"w": "輒", "m": "立刻、就"}, {"w": "難之", "m": "感到為難"}, {"w": "舍", "m": "同「捨」，丟下"}, {"w": "納", "m": "接受"}, {"w": "自託", "m": "自己託付"}, {"w": "寧可", "m": "怎麼可以"}, {"w": "拯", "m": "救助"}], "questions": [{"n": 41, "stem": "根據本文，王朗在這個事件中的表現，用下列哪一個詞語來形容最恰當？", "options": {"A": "器量寬大", "B": "缺乏定見", "C": "當機立斷", "D": "思慮欠周"}, "answer": "D", "explain": "王朗一開始因船還寬就答應讓人上船，沒有想到危急時的後果；賊兵一來又想丟下對方，顯示他做決定只顧眼前、不考慮後果，是「思慮欠周」，選D。(A)他後來想拋棄別人，談不上器量寬大。(B)他能隨情勢立刻做決定，並非沒有主見。(C)當機立斷是褒義，不適合形容他的反覆。", "skill": "比較人物前後兩次的決定與華歆的回應（本所以疑，正為此耳），推出他的缺點在「沒有先想到後果」。"}, {"n": 42, "stem": "「既已納其自託，寧可以急相棄邪」的意思是什麼？", "options": {"A": "雖然已經接受他的請託，危急時刻我還是寧願拋棄他", "B": "既然已經接受他的請託，怎麼可以因為危急而拋棄他", "C": "既然是他自己前來投靠，危急時拋棄他也沒什麼關係", "D": "既然已把生命託付給他，他怎可在緊急時拋棄我們呢"}, "answer": "B", "explain": "「既已」＝既然已經；「納其自託」＝接受他的請託；「寧可…邪」是反問句「怎麼可以…呢」；「以急」＝因為危急；「相棄」＝拋棄他。合起來就是(B)。(A)把「寧可」誤解成現代的「寧願」。(C)與反問語氣相反。(D)把託付的主客顛倒了。", "skill": "注意文言反問句「寧可…邪／耶」表示「怎麼可以…呢」，不要用現代「寧可」的意思去解讀。"}], "difficulty": "中", "label": "93年第一次基測", "year": 93, "kind": "基測"}, {"id": "bc93-1-45", "exam": "bc93-1", "nums": [45, 46], "form": "題組", "img": "img/bc93-1-45.png", "source": "改寫自《藝文類聚‧卷九十五》引《列異傳》", "author": "佚名（《列異傳》相傳為曹丕撰）", "genre": "寓言故事", "types": ["主旨寓意", "虛詞句式", "句意理解"], "passage": "正始年間，周南為襄邑長。一日，有鼠著衣冠出廳堂，語周南曰：「爾某日當死。」周南不應。至其日復出，冠幘絳衣，又語周南曰：「爾日中當死。」復不應。鼠入。日適中，鼠又出曰：「周南！汝不應死，我復何道！」遂顛蹶而死，即失其衣冠。視之，則如常鼠也。", "translation": "正始年間，周南擔任襄邑縣長。有一天，一隻老鼠穿戴衣帽走出廳堂，對周南說：「你某天會死。」周南不理牠。到了那天，老鼠又出來，戴著頭巾、穿著紅衣，又對周南說：「你今天中午會死。」周南還是不理。老鼠進去了。到了正中午，老鼠又出來說：「周南！你不應驗死去，我還能說什麼呢！」就倒地死了，衣帽也立刻消失。仔細一看，原來只是一隻普通的老鼠。", "keywords": [{"w": "語", "m": "告訴"}, {"w": "爾、汝", "m": "你"}, {"w": "幘", "m": "頭巾"}, {"w": "絳衣", "m": "紅衣"}, {"w": "應", "m": "回應；「不應死」的「應」指應驗"}, {"w": "適", "m": "恰好"}, {"w": "顛蹶", "m": "跌倒"}, {"w": "常鼠", "m": "普通的老鼠"}], "questions": [{"n": 45, "stem": "下列哪一句話最能概括這則故事的寓意？", "options": {"A": "見怪不怪，其怪自敗", "B": "以逸待勞，相機出擊", "C": "明槍易躲，暗箭難防", "D": "將計就計，反敗為勝"}, "answer": "A", "explain": "老鼠一再預言周南會死，周南始終不理會，結果怪事自己失敗，老鼠反而死了，正是「見到怪事不驚慌，怪事自然消失」，選A。(B)(D)周南沒有出擊或用計。(C)故事中沒有暗中陷害的情節。", "skill": "看主角面對怪事的態度（不應、不應）和最後結果（怪物自敗），兩者連起來就是寓意。"}, {"n": 46, "stem": "下列哪一句所省略的主語是周南？", "options": {"A": "至其日復出", "B": "冠幘絳衣", "C": "復不應", "D": "遂顛蹶而死"}, "answer": "C", "explain": "(C)「復不應」接在老鼠說話之後，是周南「又不回應」，主語是周南，選C。(A)到那天「又出來」的是老鼠。(B)戴頭巾、穿紅衣的是老鼠。(D)倒地而死的是老鼠。", "skill": "文言常省略主語：逐句找出上一句的動作者，並判斷這個動作合理屬於誰（誰會出來、誰被問話）。"}], "difficulty": "中", "label": "93年第一次基測", "year": 93, "kind": "基測"}, {"id": "bc93-2-8", "exam": "bc93-2", "nums": [8], "form": "單題", "img": "img/bc93-2-8.png", "source": "王之渙〈登鸛雀樓〉、孟浩然〈過故人莊〉、〈木蘭詩〉、王維〈山居秋暝〉", "author": "王之渙、孟浩然、佚名、王維", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "(A)白日依山盡，黃河入海流 (B)開筵面場圃，把酒話桑麻 (C)策勳十二轉，賞賜百千強 (D)隨意春芳歇，王孫自可留", "translation": "(A)太陽靠著山落下，黃河向大海流去。(B)打開窗戶擺好酒席面對打穀場和菜園，端起酒杯閒談農事。(C)記功升了十二級，賞賜的財物超過百千。(D)任憑春天的花草凋謝，王孫公子自然可以留下來。", "keywords": [{"w": "流", "m": "流動（動詞）"}, {"w": "把", "m": "握、拿（動詞）"}, {"w": "策勳", "m": "記錄功勞；「勳」是功勞（名詞）"}, {"w": "轉", "m": "升一級官"}, {"w": "歇", "m": "凋謝、停止（動詞）"}], "questions": [{"n": 8, "stem": "下列詩句「」中的字，何者不是動詞？", "options": {"A": "白日依山盡，黃河入海「流」", "B": "開筵面場圃，「把」酒話桑麻", "C": "策「勳」十二轉，賞賜百千強", "D": "隨意春芳「歇」，王孫自可留"}, "answer": "C", "explain": "(C)「策勳」是記錄功勞，「策」才是動作，「勳」是被記錄的「功勞」，屬名詞，所以選C。(A)「流」是黃河向大海流去的動作。(B)「把」是拿著酒杯。(D)「歇」是花草凋謝、停止。", "skill": "先找出句子的主語，再問「主語在做什麼」；能回答這個問題的字是動詞，被做的對象則是名詞。"}], "difficulty": "中", "label": "93年第二次基測", "year": 93, "kind": "基測"}, {"id": "bc93-2-14", "exam": "bc93-2", "nums": [14], "form": "單題", "img": "img/bc93-2-14.png", "source": "選項出自《詩經‧大雅‧烝民》等古籍文句與成語", "author": "佚名等", "genre": "經典語錄", "types": ["字詞解釋"], "passage": "(A)夙夜匪懈 (B)無動於中 (C)街道巷術 (D)貪求無厭", "translation": "(A)從早到晚都不懈怠。(B)內心毫無觸動。(C)街道與巷弄。(D)貪心索求，沒有滿足的時候。", "keywords": [{"w": "匪", "m": "通「非」，不"}, {"w": "中", "m": "內心"}, {"w": "術", "m": "通「衖」，小巷，今作「弄」"}, {"w": "厭", "m": "通「饜」，滿足"}], "questions": [{"n": 14, "stem": "下列通同字的替換，何者意思改變？", "options": {"A": "夙夜「匪」懈──非", "B": "無動於「中」──忠", "C": "街道巷「術」──弄", "D": "貪求無「厭」──饜"}, "answer": "B", "explain": "(B)「無動於中」的「中」指內心，換成「忠」（忠誠）意思完全不同，選B。(A)「匪」通「非」，不。(C)「術」通「衖」，即今之「弄」，小巷。(D)「厭」通「饜」，滿足。這三個都是可互換的通同字。", "skill": "把「」中字的意思先說出來，再看替換字能不能表達同一個意思；能的是通同字，不能的就是答案。"}], "difficulty": "中", "label": "93年第二次基測", "year": 93, "kind": "基測"}, {"id": "bc93-2-17", "exam": "bc93-2", "nums": [17], "form": "單題", "img": "img/bc93-2-17.png", "source": "陸游詩句：(A)〈貧居〉(B)〈劍門道中遇微雨〉(C)出處待查 (D)〈書憤〉一類", "author": "陸游", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)數間茅屋鏡湖濱，萬卷藏書不救貧 (B)衣上征塵雜酒痕，遠遊無處不消魂 (C)躬耕本是英豪事，老死南陽未必非 (D)自笑滅胡心尚在，憑高慷慨欲忘身", "translation": "(A)鏡湖邊幾間茅屋，藏書萬卷也救不了貧窮。(B)衣服上沾滿旅途的塵土和酒漬，遠遊所到之處無不令人黯然神傷。(C)親自耕田本來也是英雄的事，老死在南陽（像隱居的諸葛亮那樣）未必不對。(D)自己笑自己消滅胡虜的心還在，登高時情緒激昂，想奮不顧身報國。", "keywords": [{"w": "滅胡", "m": "消滅外族（金人）"}, {"w": "憑高", "m": "登高"}, {"w": "慷慨", "m": "情緒激昂"}, {"w": "忘身", "m": "奮不顧身"}, {"w": "躬耕", "m": "親自耕種"}], "questions": [{"n": 17, "stem": "南宋文學家陸游是中國有名的愛國詩人，下列哪一詩句最能看出他報效朝廷的雄心壯志？", "options": {"A": "數間茅屋鏡湖濱，萬卷藏書不救貧", "B": "衣上征塵雜酒痕，遠遊無處不消魂", "C": "躬耕本是英豪事，老死南陽未必非", "D": "自笑滅胡心尚在，憑高慷慨欲忘身"}, "answer": "D", "explain": "(D)年紀雖老，「滅胡心尚在」，登高時仍激昂得想奮不顧身，最能看出報國雄心，選D。(A)寫家貧。(B)寫旅途的落寞感傷。(C)認為隱居耕田也不錯，是退隱的心情。", "skill": "找出含有「報國、殺敵、忘身」等關鍵詞的詩句；寫貧窮、旅愁、隱居的都不是「雄心壯志」。"}], "difficulty": "易", "label": "93年第二次基測", "year": 93, "kind": "基測"}, {"id": "bc93-2-26", "exam": "bc93-2", "nums": [26], "form": "單題", "img": "img/bc93-2-26.png", "source": "選項(A)出自朱熹語等、(B)崔瑗〈座右銘〉、(D)化用韓愈〈原毀〉", "author": "崔瑗、韓愈等", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "(A)喜聞己之過，樂道人之善 (B)施人慎勿念，受施慎勿忘 (C)處身不妨薄，待人不妨厚 (D)律己輕且約，責人重且周", "translation": "(A)喜歡聽到自己的過錯，樂於稱讚別人的優點。(B)給人恩惠不要老記著，受人恩惠千萬不要忘記。(C)對待自己不妨簡樸，對待別人不妨寬厚。(D)要求自己又輕又少，責備別人又重又周全。", "keywords": [{"w": "過", "m": "過錯"}, {"w": "道", "m": "稱說"}, {"w": "施", "m": "給予恩惠"}, {"w": "律己", "m": "約束自己"}, {"w": "約", "m": "簡少"}, {"w": "周", "m": "周全、詳盡"}], "questions": [{"n": 26, "stem": "「神創造了人類，給他們兩只口袋，一只裝別人的缺點，另一只裝自己的。人們把那只裝別人缺點的口袋掛在胸前，另一只掛在背後。因此，人們常能很快的看見別人的缺點，卻看不見自己的缺點。」這段文字的涵義最接近下列哪一句話？", "options": {"A": "喜聞己之過，樂道人之善", "B": "施人慎勿念，受施慎勿忘", "C": "處身不妨薄，待人不妨厚", "D": "律己輕且約，責人重且周"}, "answer": "D", "explain": "寓言說人只看見別人缺點、看不見自己缺點，也就是對自己寬鬆、對別人嚴苛。(D)「律己輕且約，責人重且周」正描述這種毛病，選D。(A)(B)(C)都是值得學習的美德，與寓言批評的現象相反。", "skill": "先把寓言的現象濃縮成一句話（嚴以待人、寬以律己），再找選項中描述同一現象的句子，注意不要選成「應該怎麼做」的勸勉句。"}], "difficulty": "中", "label": "93年第二次基測", "year": 93, "kind": "基測"}, {"id": "bc93-2-30", "exam": "bc93-2", "nums": [30], "form": "單題", "img": "img/bc93-2-30.png", "source": "《論語‧述而》、《孟子‧盡心下》、《論語‧衛靈公》、《孟子‧告子下》", "author": "孔子、孟子", "genre": "經典語錄", "types": ["句意理解"], "passage": "(A)三人行，必有我師焉 (B)盡信書不如無書 (C)君子不以人廢言 (D)徵於色，發於聲，而後喻", "translation": "(A)幾個人同行，其中一定有可以當我老師的人。(B)完全相信書，不如沒有書。(C)君子不因為一個人不好，就廢棄他說的好話。(D)（一個人的困苦）表現在臉色上、抒發在言語中，然後才能被人了解。", "keywords": [{"w": "焉", "m": "於此，在其中"}, {"w": "書", "m": "原指《尚書》，泛指書"}, {"w": "廢言", "m": "廢棄他的言論"}, {"w": "徵", "m": "表現、驗證"}, {"w": "喻", "m": "了解"}], "questions": [{"n": 30, "stem": "下列文句的文意說明，何者正確？", "options": {"A": "「三人行，必有我師焉」──強調人要慎擇良師", "B": "「盡信書不如無書」──強調讀書要做到「慎思」的功夫", "C": "「君子不以人廢言」──君子不會因為厭惡這個人，就拒絕與他交談", "D": "「徵於色，發於聲，而後喻」──一個人的表情比言語更易讓人明白他的心意"}, "answer": "B", "explain": "(B)讀書不能全盤相信，要自己思考判斷，就是「慎思」，說明正確，選B。(A)原意是處處都有值得學習的人，不是慎選老師。(C)是不因人廢棄他說的好話，不是拒絕交談。(D)是表現在臉色、言語上後才被人了解，並沒有比較表情和言語哪個更易懂。", "skill": "逐句直譯關鍵字（師、書、廢言、喻），再對照說明有沒有多加或扭曲原意。"}], "difficulty": "中", "label": "93年第二次基測", "year": 93, "kind": "基測"}, {"id": "bc93-2-41", "exam": "bc93-2", "nums": [41, 42], "form": "題組", "img": "img/bc93-2-41.png", "source": "洪應明《菜根譚》", "author": "洪應明", "genre": "經典語錄", "types": ["主旨寓意", "文意推論"], "passage": "人解讀有字書，不解讀無字書；知彈有弦琴，不知彈無弦琴。以跡用，不以神用，何以識琴書之趣？", "translation": "人們懂得讀有字的書，卻不懂得讀沒有字的書；知道彈有弦的琴，卻不知道彈無弦的琴。只從形跡上去運用，不用心神去體會，怎麼能領略琴與書的真正趣味呢？", "keywords": [{"w": "解", "m": "懂得"}, {"w": "無字書", "m": "指自然萬物、人生經驗等可供學習的事物"}, {"w": "跡", "m": "形跡、外在形式"}, {"w": "神", "m": "精神、心神"}, {"w": "識", "m": "了解、體會"}], "questions": [{"n": 41, "stem": "這段文字的寓意在說明什麼？", "options": {"A": "讀書、彈琴是生活的閒趣", "B": "只有詩書可以醫治胸中的俗氣", "C": "讀書、欣賞音樂重在領會其中意趣", "D": "真正有學問、懂音樂的人，不須讀書、彈琴"}, "answer": "C", "explain": "結尾「以跡用，不以神用，何以識琴書之趣」說明讀書彈琴不能只看形式，要用心領會其中的趣味，選C。(A)沒有談閒趣。(B)沒有說只有詩書能治俗氣。(D)作者沒有否定讀書彈琴，只是強調要用心神。", "skill": "文言短文的主旨常在最後的反問句；把反問改成肯定句（要以神用，才能識琴書之趣）就是答案。"}, {"n": 42, "stem": "下列敘述中所提及的書，何者屬於「無字書」？", "options": {"A": "吾初始之故鄉乃書也", "B": "書如藥也，善讀可醫愚", "C": "山水亦書也；棋酒亦書也", "D": "憂愁非書不釋，精神非書不振"}, "answer": "C", "explain": "「無字書」指書本以外、可供體會學習的事物。(C)把山水、下棋飲酒都當成書，正是沒有文字的書，選C。(A)(B)(D)所說的「書」都是指一般有文字的書本。", "skill": "先定義「無字書」＝不是書本、但能讓人學習的事物，再看選項中的「書」是否真的指書本。"}], "difficulty": "中", "label": "93年第二次基測", "year": 93, "kind": "基測"}, {"id": "bc93-2-45", "exam": "bc93-2", "nums": [45, 46], "form": "題組", "img": "img/bc93-2-45.png", "source": "李清照〈醉花陰〉", "author": "李清照", "genre": "古典詩詞曲", "types": ["人物情感", "詩詞賞析", "文化常識"], "passage": "薄霧濃雲愁永晝，瑞腦消金獸。佳節又重陽，玉枕紗廚，半夜涼初透。東籬把酒黃昏後，有暗香盈袖。莫道不消魂，簾捲西風，人比黃花瘦。", "translation": "薄霧濃雲籠罩，漫長的白天令人發愁，香料在獸形銅爐中漸漸燒完。又到了重陽佳節，枕著玉枕睡在紗帳中，半夜涼意剛剛透進來。黃昏後在東籬下飲酒賞菊，淡淡的花香沾滿衣袖。別說不令人神傷，西風捲起簾子，人比菊花還要消瘦。", "keywords": [{"w": "永晝", "m": "漫長的白天"}, {"w": "瑞腦", "m": "香料"}, {"w": "金獸", "m": "刻著金獸的銅香爐"}, {"w": "紗廚", "m": "蚊帳"}, {"w": "東籬", "m": "種菊之處，化用陶淵明「采菊東籬下」"}, {"w": "消魂", "m": "情緒低落"}, {"w": "黃花", "m": "菊花"}], "questions": [{"n": 45, "stem": "這首詞呈現了婦女怎樣的情態？", "options": {"A": "相思難解的情愁", "B": "酒後慵懶的嬌媚", "C": "奢華綺麗的浪漫", "D": "佳節賞花的悠閑"}, "answer": "A", "explain": "詞中「愁永晝」「莫道不消魂」「人比黃花瘦」，寫重陽佳節獨自一人，因思念遠方的丈夫而愁苦消瘦，是相思難解的情愁，選A。(B)飲酒賞菊只是場景，重點在愁。(C)香爐、玉枕是生活器物，並非寫奢華浪漫。(D)雖然賞花，心情卻不悠閒。", "skill": "找詞中直接寫情緒的字（愁、消魂、瘦），判斷主角的心情，再對照選項。"}, {"n": 46, "stem": "根據這首詞所描述的時間背景，如果李清照在此時出門散步，她最可能看到什麼景色？", "options": {"A": "競折團荷遮晚照", "B": "紫艷半開籬菊靜", "C": "晚風庭院落梅初", "D": "北風吹雁雪紛紛"}, "answer": "B", "explain": "詞中寫「佳節又重陽」（農曆九月九日），又有「東籬」「黃花」，正是秋天菊花開的時候，(B)籬邊菊花半開最符合，選B。(A)荷花是夏景。(C)梅花是冬末春初。(D)北風、大雪是冬景。", "skill": "抓時間線索（重陽、黃花、西風）定出季節，再找選項中屬於同一季節的景物。"}], "difficulty": "中", "label": "93年第二次基測", "year": 93, "kind": "基測"}, {"id": "bc93-2-47", "exam": "bc93-2", "nums": [47, 48], "form": "題組", "img": "img/bc93-2-47.png", "source": "蔡元培〈自由與放縱〉", "author": "蔡元培", "genre": "說理議論", "types": ["寫作手法", "文意推論", "句意理解"], "passage": "人之思想不縛於宗教，不牽於俗尚，而一以良心為準，此真自由也。若偶有惡劣之思想，為良心所不許，而我故縱容之，使積漸擴張，而勢力遂駕於良心之上，則放縱之思想而已。飢而食，渴而飲，倦而眠，衛生之自由也。然使飲食不節，興寢無常，養成不良之習慣，則因放縱而轉有害於衛生矣。喜而歌，悲而哭，感情之自由也；然而「里有殯，不巷歌」，「寡婦不夜哭」，不敢放縱也。言論可以自由也，而或乃訐發陰私，指揮盜淫；居處可以自由也，而或於其間為危險之製造，作長夜之喧囂；職業可以自由也，而或乃造作偽品，販賣毒物；集會可以自由也，而或以流布迷信，恣行奸邪；諸如此類，皆逞一方面之自由，而不以他人之自由為界，皆為放縱之咎也。", "translation": "人的思想不被宗教束縛、不被習俗牽制，完全以良心為標準，這才是真正的自由。如果偶爾有惡劣的念頭，良心不允許，我卻故意放任它，讓它逐漸擴大，力量超越良心，那就只是放縱的思想罷了。餓了吃、渴了喝、累了睡，是衛生方面的自由；但如果飲食沒有節制、作息不正常，養成壞習慣，就因放縱而反而傷害健康。高興就唱歌、悲傷就哭泣，是感情的自由；但「鄰里有喪事，不在巷中唱歌」、「寡婦不在夜裡哭」，就是不敢放縱。言論可以自由，有人卻揭發別人的隱私、教唆偷盜淫亂；居住可以自由，有人卻在住處製造危險、整夜喧鬧；職業可以自由，有人卻製造假貨、販賣毒品；集會可以自由，有人卻藉此散布迷信、放肆做壞事。這些都是只放縱自己一方面的自由，卻不以他人的自由為界限，都是放縱造成的過錯。", "keywords": [{"w": "縛", "m": "束縛"}, {"w": "俗尚", "m": "社會風俗習尚"}, {"w": "一以", "m": "完全以"}, {"w": "駕", "m": "凌駕、超越"}, {"w": "殯", "m": "停棺待葬，指喪事"}, {"w": "訐發陰私", "m": "揭發別人的隱私"}, {"w": "恣行", "m": "任意去做"}, {"w": "逞", "m": "放任、施展"}, {"w": "咎", "m": "過錯"}], "questions": [{"n": 47, "stem": "下列何者是本文的論述手法？", "options": {"A": "以正面刻畫種種放縱的行為", "B": "舉自身經驗歌頌自由的可貴", "C": "以言外寄寓的方式強調主題", "D": "從正反兩面對比來說明題旨"}, "answer": "D", "explain": "文章每一段都先說「…，自由也」（正面），再說「然而…則放縱」（反面），用正反對比說明自由與放縱的界線，選D。(A)不只寫放縱，也寫自由。(B)沒有舉作者自身經驗。(C)文章直接說理，不是寓言式的言外之意。", "skill": "觀察段落的固定句式（先說可以…，再說而或乃…），找出作者反覆使用的對照結構。"}, {"n": 48, "stem": "根據本文的說法，下列何人的行為屬於「放縱」的行為？", "options": {"A": "芳穗不顧朋友的勸告，執意選擇自己熱愛的新聞工作", "B": "瑋倫在得知榮獲世界美術首獎之後，高興得大呼小叫", "C": "彥均以正義使者自居，專愛揭發他人不可告人的隱私", "D": "仲平入主豪宅，刻意以華靡奢侈的裝潢凸顯個人地位"}, "answer": "C", "explain": "文中說「言論可以自由也，而或乃訐發陰私」，揭發別人隱私就是侵害他人自由的放縱，(C)正是如此，選C。(A)選擇職業是自己的自由，沒有妨害別人。(B)高興而喊叫是感情的自由。(D)奢華裝潢雖然炫耀，但沒有侵犯他人自由，文中也未列為放縱。", "skill": "抓住作者對放縱的定義：「不以他人之自由為界」，逐一檢查選項的行為是否傷害到別人。"}], "difficulty": "中", "label": "93年第二次基測", "year": 93, "kind": "基測"}, {"id": "bc94-1-9", "exam": "bc94-1", "nums": [9], "form": "單題", "img": "img/bc94-1-9.png", "source": "對聯（出處待查）", "author": "佚名", "genre": "其他", "types": ["寫作手法", "文化常識"], "passage": "(A)三光日月星，四始風雅頌 (B)日月明朝昏，山風嵐自起 (C)袖中有滄海，襟上多白雲 (D)遠水碧千里，夕陽紅半樓", "translation": "(A)天上的三光是日、月、星，《詩經》的四始是〈風〉、〈大雅〉、〈小雅〉、〈頌〉。(B)「日」「月」合成「明」，早晚交替；「山」「風」合成「嵐」，山中霧氣自然升起。(C)袖子裡好像裝著大海，衣襟上沾滿白雲（形容胸懷開闊、高潔）。(D)遠方的水碧綠千里，夕陽把半座樓染紅。", "keywords": [{"w": "析字", "m": "把字的形體拆開或合併來修辭"}, {"w": "嵐", "m": "山中霧氣，由「山」「風」組成"}, {"w": "四始", "m": "《詩經》風、大雅、小雅、頌"}], "questions": [{"n": 9, "stem": "在行文說話時，經常把文字的形體、意義加以分析，就形成了析字的藝術。如「愁」可拆為「心上秋」，「少女」可合為「妙」。下列聯語，何者是利用這種特質寫成的？", "options": {"A": "三光日月星，四始風雅頌", "B": "日月明朝昏，山風嵐自起", "C": "袖中有滄海，襟上多白雲", "D": "遠水碧千里，夕陽紅半樓"}, "answer": "B", "explain": "(B)上聯「日」＋「月」＝「明」，下聯「山」＋「風」＝「嵐」，正是把字合起來的析字手法，選B。(A)是列舉數目與名稱（三光、四始），不是析字。(C)(D)是寫景、抒懷的對句，沒有拆合字形。", "skill": "看聯語中有沒有「幾個字恰好拼成句中另一個字」的情形，逐字拆組檢查。"}], "difficulty": "易", "label": "94年第一次基測", "year": 94, "kind": "基測"}, {"id": "bc94-1-11", "exam": "bc94-1", "nums": [11], "form": "單題", "img": "img/bc94-1-11.png", "source": "選項(B)出自《論語‧述而》、(C)《論語‧為政》、(D)《論語‧顏淵》，(A)為常見文言俗語", "author": "孔子等", "genre": "經典語錄", "types": ["虛詞句式"], "passage": "(A)人非草木，孰能無情 (B)求仁得仁，又有何怨 (C)人而無信，不知其可 (D)死生有命，富貴在天", "translation": "(A)人不是草木，誰能沒有感情？(B)追求仁德就得到仁德，又有什麼好怨恨的？(C)人如果不講信用，不知道他還能做什麼。(D)死生由命運決定，富貴由上天安排。", "keywords": [{"w": "乃", "m": "是（判斷詞）"}, {"w": "非", "m": "不是（否定判斷）"}, {"w": "孰", "m": "誰"}, {"w": "而", "m": "如果"}], "questions": [{"n": 11, "stem": "從句型來看，「良將乃國之棟梁」是判斷句。下列選項「」中的句型，何者也屬於判斷句？", "options": {"A": "「人非草木」，孰能無情", "B": "「求仁得仁」，又有何怨", "C": "「人而無信」，不知其可", "D": "「死生有命」，富貴在天"}, "answer": "A", "explain": "判斷句是用「是／不是」去判定主語屬於什麼。(A)「人非草木」＝人不是草木，用「非」作否定判斷，選A。(B)是敘述「求而得到」的動作（敘事句）。(C)「而」是假設的「如果」，是條件句。(D)「有」表示存在或擁有（有無句）。", "skill": "把句子譯成白話，看能不能說成「A 是／不是 B」；可以的才是判斷句。"}], "difficulty": "中", "label": "94年第一次基測", "year": 94, "kind": "基測"}, {"id": "bc94-1-14", "exam": "bc94-1", "nums": [14], "form": "單題", "img": "img/bc94-1-14.png", "source": "題幹出自洪應明《菜根譚》；選項出處待查", "author": "洪應明等", "genre": "說理議論", "types": ["主旨寓意", "比較閱讀"], "passage": "花看半開，酒飲微醉，若至爛漫酩酊，便成惡境。(A)用智如水，水濫則溢；用勇如火，火烈則焚 (B)天地無全功，聖人無全能，萬物無全用 (C)雲厚者雨必猛，弓勁者箭必遠 (D)有興必有廢，有盛必有衰", "translation": "賞花要看半開的，喝酒只到微醉；如果到了花開得過盛、喝得大醉，就變成不好的境地了。(A)運用智慧像水，水太多就會氾濫；運用勇氣像火，火太猛就會燒毀東西。(B)天地沒有完美的功業，聖人沒有萬能的本事，萬物沒有全部的用處。(C)雲越厚雨越猛，弓越強箭射得越遠。(D)有興起必有廢棄，有興盛必有衰敗。", "keywords": [{"w": "爛漫", "m": "花開得極盛"}, {"w": "酩酊", "m": "大醉"}, {"w": "惡境", "m": "不好的境地"}, {"w": "濫", "m": "過多而氾濫"}, {"w": "焚", "m": "燒"}], "questions": [{"n": 14, "stem": "下列文句的寓意，何者與「花看半開，酒飲微醉，若至爛漫酩酊，便成惡境」最接近？", "options": {"A": "用智如水，水濫則溢；用勇如火，火烈則焚", "B": "天地無全功，聖人無全能，萬物無全用", "C": "雲厚者雨必猛，弓勁者箭必遠", "D": "有興必有廢，有盛必有衰"}, "answer": "A", "explain": "題幹說凡事適可而止，過了頭就變壞，也就是「過猶不及」。(A)智慧、勇氣用得過度，就像水氾濫、火燒毀，同樣強調不能過度，選A。(B)說萬物都不完美。(C)說條件越強效果越大，與題幹相反。(D)說盛衰循環，重點是變化而非節制。", "skill": "抓題幹的轉折句「若至…便成…」——強調「過度就壞」，再找選項中同樣有「過度→壞結果」的結構。"}], "difficulty": "中", "label": "94年第一次基測", "year": 94, "kind": "基測"}, {"id": "bc94-1-22", "exam": "bc94-1", "nums": [22], "form": "單題", "img": "img/bc94-1-22.png", "source": "王勃〈滕王閣詩〉", "author": "王勃", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "閒雲潭影日悠悠，物換星移幾度秋。閣中帝子今何在？檻外長江空自流。", "translation": "悠閒的白雲和潭中的倒影，一天天悠然自在；景物變換、星辰移轉，已經過了多少年。當年在閣中的滕王如今在哪裡呢？欄杆外的長江只是白白地自己流著。", "keywords": [{"w": "物換星移", "m": "景物變化，星辰移位，指時光流逝"}, {"w": "幾度秋", "m": "過了幾年"}, {"w": "帝子", "m": "指滕王，唐高祖之子"}, {"w": "檻", "m": "欄杆"}, {"w": "空", "m": "徒然、白白地"}], "questions": [{"n": 22, "stem": "王勃〈滕王閣〉：「閒雲潭影日悠悠，物換星移幾度秋。閣中帝子今何在？檻外長江空自流。」詩句中抒發了下列哪一種感慨？", "options": {"A": "相思悠悠，度日如年", "B": "年華老去，一事無成", "C": "壯志未酬，生活潦倒", "D": "景物依舊，人事全非"}, "answer": "D", "explain": "雲影、長江依舊，當年建閣的滕王卻已不在，用景物不變對比人事變遷，抒發「景物依舊，人事全非」的感慨，選D。(A)詩中沒有思念對象。(B)(C)詩中沒有寫作者自身的年老或困頓。", "skill": "找詩中「不變的」（雲、潭、長江）與「消失的」（帝子），兩者對照就是今昔之感。"}], "difficulty": "易", "label": "94年第一次基測", "year": 94, "kind": "基測"}, {"id": "bc94-1-30", "exam": "bc94-1", "nums": [30], "form": "單題", "img": "img/bc94-1-30.png", "source": "五言律詩（出處待查）", "author": "出處待查", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "沙岸殘春雨，茅簷古鎮官。一時花帶淚，萬里客憑欄。日晚薔薇重，樓高燕子寒。惜無陶謝手，盡日破憂端。", "translation": "沙岸邊下著殘春的雨，茅草屋簷下是古鎮的小官。花上的雨珠像一時帶著眼淚，遠行萬里的客人倚著欄杆。傍晚時薔薇被雨打得沉重，高樓上的燕子顯得寒冷。可惜我沒有陶淵明、謝靈運那樣的文筆，只能整天排解憂愁。", "keywords": [{"w": "頷聯、頸聯", "m": "律詩第二、三聯，必須對仗"}, {"w": "押韻", "m": "偶數句末字押韻，本詩押「官、欄、寒、端」"}, {"w": "陶謝", "m": "陶淵明、謝靈運"}, {"w": "憂端", "m": "憂愁的頭緒"}], "questions": [{"n": 30, "stem": "阿輝從網路下載一首五言律詩，在排版時不小心把中間四句打亂了，只知首末兩聯各是「沙岸殘春雨，茅簷古鎮官」、「惜無陶謝手，盡日破憂端」。下列是阿輝排列的四種組合，依律詩的相關常識，哪一種組合正確？", "options": {"A": "一時花帶淚，萬里客憑欄。日晚薔薇重，樓高燕子寒", "B": "樓高燕子寒，一時花帶淚。日晚薔薇重，萬里客憑欄", "C": "日晚薔薇重，萬里客憑欄。一時花帶淚，樓高燕子寒", "D": "萬里客憑欄，一時花帶淚。樓高燕子寒，日晚薔薇重"}, "answer": "A", "explain": "律詩兩條規則：偶數句押韻（官、端是 -an 韻，所以第4、6句要是「欄」「寒」）；中間兩聯要對仗。(A)「一時／萬里、花／客、帶淚／憑欄」，「日晚／樓高、薔薇／燕子、重／寒」都工整相對，且第4句「欄」、第6句「寒」押韻，選A。(B)(D)押韻字放在奇數句，錯誤。(C)雖押韻，但「日晚薔薇重」與「萬里客憑欄」對仗不工整。", "skill": "先用押韻排除（偶數句末字要和「官、端」同韻），再用對仗檢查上下句詞性是否兩兩相對。"}], "difficulty": "中", "label": "94年第一次基測", "year": 94, "kind": "基測"}, {"id": "bc94-1-35", "exam": "bc94-1", "nums": [35, 36], "form": "題組", "img": "img/bc94-1-35.png", "source": "胡澹菴輯《繪圖解人頤‧勤懶歌》", "author": "胡澹菴（輯）", "genre": "古典詩詞曲", "types": ["主旨寓意", "比較閱讀", "詩詞賞析"], "passage": "為人在世莫嗜懶，嗜懶之人才智短，臨老噬臍悲已晚。士而懶，終身布衣不能換；農而懶，食不充腸衣不暖；工而懶，積聚萬貫成星散。又不見，人生天地惟在勤，原勤之本在乎心。若要自強而不息，先須抖擻己精神。", "translation": "人活在世上不要貪懶，貪懶的人才智短淺，到老時後悔也來不及了。讀書人懶惰，一輩子當平民換不到官服；農人懶惰，吃不飽穿不暖；工匠懶惰，累積的萬貫家財也會四散。你沒看到嗎？人生在天地間只在於勤勞，而勤勞的根本在於自己的心。如果想要自強不息，必須先振作自己的精神。", "keywords": [{"w": "嗜", "m": "愛好、貪"}, {"w": "噬臍", "m": "咬自己的肚臍，咬不到，比喻後悔已遲"}, {"w": "布衣", "m": "平民"}, {"w": "星散", "m": "四散"}, {"w": "原", "m": "推究"}, {"w": "抖擻", "m": "振作"}], "questions": [{"n": 35, "stem": "下列敘述，何者與本詩的主旨最接近？", "options": {"A": "懶惰使靈魂虛弱，勤勞讓思緒靈敏", "B": "一生之計在於勤，勤勉立身全由己", "C": "一分辛勞一分財，唯有勤勞能致富", "D": "人生最困難的事，莫過於戰勝惰性"}, "answer": "B", "explain": "詩中說「人生天地惟在勤」，又說「原勤之本在乎心」，強調勤勞是立身根本，而且全靠自己的心志，(B)最接近，選B。(A)只談思緒，範圍太窄。(C)只談致富，但詩中士、農、工不只講錢。(D)詩中沒說戰勝惰性是最困難的事。", "skill": "主旨常在詩末的總結句（惟在勤、在乎心、抖擻己精神），找能同時涵蓋「勤」與「由己」的選項。"}, {"n": 36, "stem": "本詩中「臨老噬臍悲已晚」的諷勸意味，與下列何者相同？", "options": {"A": "往者不可見，來者猶可追", "B": "欲窮千里目，更上一層樓", "C": "花有重開日，人無再少年", "D": "生年不滿百，常懷千歲憂"}, "answer": "C", "explain": "「臨老噬臍悲已晚」是勸人趁早勤勉，否則老了後悔來不及。(C)花謝了還會再開，人卻不會再年輕，同樣勸人珍惜青春、及早努力，選C。(A)意思是過去的無法挽回，未來還來得及，語氣是鼓勵把握未來。(B)勸人更上層樓求進步。(D)嘆人憂慮太多。", "skill": "先把題句的「勸告方向」說清楚（及早努力，以免老來後悔），再找同樣用「時光一去不回」來勸人的句子。"}], "difficulty": "中", "label": "94年第一次基測", "year": 94, "kind": "基測"}, {"id": "bc94-1-42", "exam": "bc94-1", "nums": [42, 43], "form": "題組", "img": "img/bc94-1-42.png", "source": "短文出處未標；第43題選項(A)杜甫〈寄韓諫議注〉、(B)王維〈洛陽女兒行〉，(C)(D)出處待查", "author": "杜甫、王維等", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "(A)鴻飛冥冥日月白，青楓葉赤天雨霜 (B)畫閣朱樓盡相望，紅桃綠柳垂簷向 (C)不知十月江寒重，徒覺三更布被輕 (D)清暑簾開散異香，恩深咫尺對龍章", "translation": "(A)鴻雁飛向高遠的天空，日月明亮；青楓葉子轉紅，天降寒霜。(B)彩繪的樓閣、紅色的樓房一棟接一棟，紅桃綠柳垂到屋簷。(C)不知道十月江上寒氣這麼重，只覺得三更時布被太單薄。(D)清涼消暑的簾子打開，散出奇異的香氣，承蒙皇恩，近距離面對天子。", "keywords": [{"w": "冥冥", "m": "高遠的樣子"}, {"w": "雨霜", "m": "降霜（雨作動詞）"}, {"w": "清暑", "m": "消暑"}, {"w": "龍章", "m": "即龍顏，指天子"}], "questions": [{"n": 42, "stem": "這段文字描寫了許多景物，其中最主要是在描寫什麼？", "options": {"A": "院子裡遍布著搖曳生姿的瓜葉", "B": "花園裏的池塘長滿挺立的荷葉", "C": "布滿星星、螢火蟲的夏夜景致", "D": "颱風來襲，院子裏淹水的情景"}, "answer": "A", "explain": "短文先提星星、螢火蟲，接著大篇幅寫南瓜葉：像浪潮、交頭接耳、驕傲地揚頭、淹水後像荷葉池塘，主角是滿院子的瓜葉，選A。(B)「荷葉池塘」只是比喻。(C)星星螢火蟲只是開頭帶過。(D)颱風淹水是為了再寫瓜葉。", "skill": "看哪個景物被反覆描寫、用最多修辭，那就是描寫的重點。"}, {"n": 43, "stem": "這段文字所描寫的季節，與下列哪一組詩句相同？", "options": {"A": "鴻飛冥冥日月白，青楓葉赤天雨霜", "B": "畫閣朱樓盡相望，紅桃綠柳垂簷向", "C": "不知十月江寒重，徒覺三更布被輕", "D": "清暑簾開散異香，恩深咫尺對龍章"}, "answer": "D", "explain": "短文寫「夏天的晚上」、颱風天。(D)「清暑」是消除暑氣，點出夏天，選D。(A)楓葉轉紅、降霜，是秋天。(B)桃花紅、柳樹綠，是春天。(C)十月江寒，是秋冬。", "skill": "先從短文找季節線索（夏天、颱風），再找詩句中的季節關鍵詞（清暑、霜、桃柳、十月）。"}], "difficulty": "中", "label": "94年第一次基測", "year": 94, "kind": "基測"}, {"id": "bc94-1-44", "exam": "bc94-1", "nums": [44, 45, 46], "form": "題組", "img": "img/bc94-1-44.png", "source": "改寫自《搜神後記‧卷九》", "author": "陶潛（舊題）", "genre": "筆記小品", "types": ["字詞解釋", "文意推論", "文化常識"], "passage": "楊生養一狗，甚愛憐之，行止與俱。生因暗行，墮於空井中，狗呻吟徹曉。有人經過，怪此狗向井號，往視，見生。生曰：「君可出我，當有厚報。」人曰：「以此狗見與，便當相出。」生曰：「此狗不得相與。餘即無惜。」人曰：「若爾，便不相出。」狗遂低頭目井。生知其意，乃與路人云：「以狗相與。」人即出之，繫之而去。卻後五日，狗夜走歸。", "translation": "楊生養了一隻狗，非常疼愛牠，走到哪裡都帶著。楊生因為夜裡走路，掉進一口枯井，狗整夜哀鳴到天亮。有人經過，奇怪這隻狗為什麼對著井嚎叫，過去一看，看到楊生。楊生說：「你如果把我救出來，我會重重報答你。」那人說：「把這隻狗送給我，我就救你出來。」楊生說：「這隻狗不能給你，其他的東西都不吝惜。」那人說：「如果這樣，我就不救你。」狗於是低頭看著井。楊生明白牠的意思，就對路人說：「把狗送給你。」那人立刻把他救出來，綁著狗走了。過了五天，狗在夜裡跑回來了。", "keywords": [{"w": "行止與俱", "m": "走到哪裡都一起"}, {"w": "徹曉", "m": "直到天亮"}, {"w": "怪", "m": "對……感到奇怪"}, {"w": "號", "m": "嚎叫"}, {"w": "出我", "m": "把我救出來"}, {"w": "見與", "m": "給我"}, {"w": "若爾", "m": "如果這樣"}, {"w": "目", "m": "看（名詞轉動詞）"}, {"w": "卻後", "m": "過了"}, {"w": "走", "m": "跑"}], "questions": [{"n": 44, "stem": "「有人經過，怪此狗向井號。」句中「怪」字的字義，應是下列何者？", "options": {"A": "責難", "B": "驚訝", "C": "非常", "D": "妖魔"}, "answer": "B", "explain": "路人聽到狗對著井嚎叫，覺得奇怪、驚訝，才走過去看，「怪」是「對……感到奇怪、驚訝」，選B。(A)責難是責怪，但路人沒有罵狗。(C)「非常」是副詞用法（如「怪好看的」）。(D)「妖魔」是名詞用法。", "skill": "看「怪」後面接了什麼（此狗向井號）並和下文（往視）連起來：因為覺得奇怪才去看。"}, {"n": 45, "stem": "「狗遂低頭目井。生知其意」，句中「其意」的意思應是下列何者？", "options": {"A": "示意楊生答應此人要求無妨", "B": "請求楊生千萬不要將牠給人", "C": "感謝楊生多年來辛苦的照顧", "D": "表明信任楊生做的一切決定"}, "answer": "A", "explain": "路人堅持要狗才肯救人，狗低頭看井，楊生明白後立刻答應送狗，可見狗的意思是「答應他吧，先保住性命」，選A。(B)若是如此，楊生就不會答應。(C)(D)與當下情境無關。五天後狗自己跑回來，也印證牠是主動示意。", "skill": "用「後果」反推「意思」：楊生「知其意」之後做了什麼（答應送狗），狗的意思就是什麼。"}, {"n": 46, "stem": "下列各書中，何者最有可能收錄本文？", "options": {"A": "寵物食品介紹", "B": "生物百科圖鑑", "C": "愛犬飼養手冊", "D": "動物寰宇搜奇"}, "answer": "D", "explain": "本文是狗救主、自己逃回的奇異故事，出自志怪小說《搜神後記》，最適合收在記錄動物奇聞的書，選D。(A)(B)(C)都是知識性、實用性的書，不收故事。", "skill": "判斷文章性質（奇聞故事 vs. 知識說明），再對照書名的性質。"}], "difficulty": "易", "label": "94年第一次基測", "year": 94, "kind": "基測"}, {"id": "bc94-2-9", "exam": "bc94-2", "nums": [9], "form": "單題", "img": "img/bc94-2-9.png", "source": "(A)蘇軾〈永遇樂〉、(C)聶勝瓊〈鷓鴣天〉、(D)張養浩散曲；(B)出處待查", "author": "蘇軾、聶勝瓊、張養浩等", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)天涯倦客，山中歸路，望斷故園心眼 (B)不恨年華去也，只恐少年心事，強半為銷磨 (C)尋好夢，夢難成，有誰知我此時情？枕前淚共階前雨，隔個窗兒滴到明 (D)喜萬象春如故，恨流民尚在途。留不住都棄業拋家，當不的也離鄉背土", "translation": "(A)流浪天涯、疲倦的旅人，望著回山中的路，望穿了想念故鄉的眼睛。(B)不怨恨年華逝去，只怕少年時的志向，大半已被消磨掉。(C)想做個好夢，夢卻做不成，有誰知道我此時的心情？枕邊的淚和臺階前的雨，隔著一扇窗一直滴到天亮。(D)欣喜萬物春光依舊，可恨流亡的百姓還在路上。留不住的都拋棄家業，撐不下去的也只好離開故鄉。", "keywords": [{"w": "倦客", "m": "疲倦的旅人"}, {"w": "強半", "m": "大半"}, {"w": "銷磨", "m": "消磨"}, {"w": "流民", "m": "因災荒流離失所的百姓"}, {"w": "當不的", "m": "承受不住"}], "questions": [{"n": 9, "stem": "下列詩句所抒發的情感，何者是為了百姓疾苦而興發的悲嘆？", "options": {"A": "天涯倦客，山中歸路，望斷故園心眼", "B": "不恨年華去也，只恐少年心事，強半為銷磨", "C": "尋好夢，夢難成，有誰知我此時情？枕前淚共階前雨，隔個窗兒滴到明", "D": "喜萬象春如故，恨流民尚在途。留不住都棄業拋家，當不的也離鄉背土"}, "answer": "D", "explain": "(D)「恨流民尚在途」，寫百姓棄業拋家、離鄉背井的苦況，是為百姓疾苦而悲嘆，選D。(A)是遊子思鄉。(B)是感嘆自己壯志消磨。(C)是女子相思難眠。", "skill": "找出每句悲傷的「對象」是誰：自己（思鄉、壯志、相思）還是百姓；只有對象是百姓的才符合。"}], "difficulty": "易", "label": "94年第二次基測", "year": 94, "kind": "基測"}, {"id": "bc94-2-17", "exam": "bc94-2", "nums": [17], "form": "單題", "img": "img/bc94-2-17.png", "source": "對聯（出處待查）", "author": "佚名", "genre": "其他", "types": ["句意理解", "主旨寓意"], "passage": "心不齋，百跪百拜何益；意既誠，一杯一炷亦香。", "translation": "心意不虔誠，就算跪拜一百次又有什麼用；心意已經真誠，即使只有一杯酒、一炷香也是香的（神明也會接受）。", "keywords": [{"w": "齋", "m": "莊敬、虔誠"}, {"w": "何益", "m": "有什麼好處"}, {"w": "炷", "m": "計算香的單位"}], "questions": [{"n": 17, "stem": "下列何者與「心不齋，百跪百拜何益；意既誠，一杯一炷亦香」這副對聯的涵義最接近？", "options": {"A": "靠山山倒，靠人人跑，自己最可靠", "B": "真摯虔敬是君子處事的基石", "C": "未雨綢繆勝過臨渴掘井", "D": "臨陣磨槍，不亮也光"}, "answer": "B", "explain": "對聯強調重要的是內心的虔誠，而不是形式上跪拜多少、供品多少，(B)「真摯虔敬」最接近，選B。(A)講依靠自己。(C)講預先準備。(D)講臨時抱佛腳也有效，都與誠心無關。", "skill": "比較上下聯的對照（心不齋→無益；意既誠→亦香），找出決定結果的關鍵條件（誠心）。"}], "difficulty": "易", "label": "94年第二次基測", "year": 94, "kind": "基測"}, {"id": "bc94-2-18", "exam": "bc94-2", "nums": [18], "form": "單題", "img": "img/bc94-2-18.png", "source": "題幹出自王安石〈泊船瓜洲〉；選項(A)賈至〈早朝大明宮呈兩省僚友〉，其餘出處待查", "author": "王安石等", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "(A)銀燭朝天紫陌長，禁城春色曉蒼蒼 (B)最是秋風管閒事，紅他楓葉白人頭 (C)白髮悲花落，青雲羨鳥飛 (D)連山晚照紅，遠岸秋沙白", "translation": "(A)銀色的蠟燭照亮上朝的長長京城大道，宮城的春色在清晨一片青蒼。(B)最愛管閒事的就是秋風，把楓葉吹紅了，把人的頭髮吹白了。(C)白髮的人為花落而悲傷，羨慕鳥兒飛上青雲。(D)連綿的山在夕照下一片紅，遠方岸邊的秋沙一片白。", "keywords": [{"w": "綠", "m": "使……變綠（形容詞轉動詞）"}, {"w": "白人頭", "m": "使人頭髮變白"}, {"w": "紫陌", "m": "京城的道路"}, {"w": "晚照", "m": "夕陽"}], "questions": [{"n": 18, "stem": "「春風又綠江南岸」的「綠」字改變詞性為動詞之後，使得詩意更為生動活潑。下列詩句「」中的字，何者也改變詞性，當動詞使用？", "options": {"A": "「銀」燭朝天紫陌長，禁城春色曉蒼蒼", "B": "最是秋風管閒事，紅他楓葉「白」人頭", "C": "白髮悲花落，「青」雲羨鳥飛", "D": "連山晚照「紅」，遠岸秋沙白"}, "answer": "B", "explain": "(B)「白人頭」是讓人的頭髮變白，「白」由形容詞轉成動詞，和「綠江南岸」相同，選B（同句「紅他楓葉」的「紅」也是）。(A)「銀燭」的「銀」形容蠟燭，仍是形容詞。(C)「青雲」的「青」形容雲。(D)「晚照紅」的「紅」是說夕照的顏色，仍是形容詞作謂語。", "skill": "看顏色字後面有沒有接「受詞」：「白＋人頭」＝使人頭變白，後面帶受詞才是轉成動詞。"}], "difficulty": "中", "label": "94年第二次基測", "year": 94, "kind": "基測"}, {"id": "bc94-2-20", "exam": "bc94-2", "nums": [20], "form": "單題", "img": "img/bc94-2-20.png", "source": "題幹出自權德輿〈病中寓直代書題寄〉；選項(B)孟郊〈勸學〉，其餘出處待查", "author": "權德輿、孟郊等", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "千重江水萬重山，山裏青春度日閒。(A)白日莫空過，青春不再來 (B)青春須早為，豈能長少年 (C)青春留不住，白髮自然生 (D)年光何太急，倏忽又青春", "translation": "隔著千重江水萬重山，山中的春天日子過得悠閒。(A)白天不要白白度過，年輕的時光不會再來。(B)年輕時就要及早努力，怎能永遠是少年。(C)青春年華留不住，白髮自然就長出來。(D)時光過得多麼快，轉眼又是春天。", "keywords": [{"w": "青春", "m": "①春天 ②年輕時光"}, {"w": "倏忽", "m": "很快地、轉眼間"}, {"w": "年光", "m": "時光"}], "questions": [{"n": 20, "stem": "權德輿〈病中寓直代書題寄〉：「千重江水萬重山，山裏青春度日閒。」句中「青春」指的是春天的意思。下列詩句中「青春」的意義，何者與此相同？", "options": {"A": "白日莫空過，青春不再來", "B": "青春須早為，豈能長少年", "C": "青春留不住，白髮自然生", "D": "年光何太急，倏忽又青春"}, "answer": "D", "explain": "(D)感嘆時光飛快，轉眼「又」到了春天，「青春」指一年一度的春季，選D。(A)(B)(C)的「青春」都與「白髮」「少年」「不再來」相對，指人的年輕歲月。", "skill": "一詞多義時，看它和什麼詞搭配：和「白髮、少年、不再來」連用指年輕時光；和「又」「度日」連用、可以年年重來的，才是春天。"}], "difficulty": "中", "label": "94年第二次基測", "year": 94, "kind": "基測"}, {"id": "bc94-2-31", "exam": "bc94-2", "nums": [31], "form": "單題", "img": "img/bc94-2-31.png", "source": "王國維〈曉步〉", "author": "王國維", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "四時可愛唯春日，一事能狂便少年。", "translation": "四季中最可愛的只有春天；能為一件事全心投入、狂熱，就是年輕人的心。", "keywords": [{"w": "四時", "m": "四季"}, {"w": "唯", "m": "只有"}, {"w": "狂", "m": "狂熱、全心投入"}, {"w": "對句", "m": "字數相等、詞性相對、意思相關的兩句"}], "questions": [{"n": 31, "stem": "「對偶」的作用在使文章形式工整，音調和諧。下列選項，何者是「四時可愛唯春日」的對句？", "options": {"A": "一事能狂便少年", "B": "五陵無樹起秋風", "C": "九華帳裡夢魂驚", "D": "萬里歸心對月明"}, "answer": "A", "explain": "對句要詞性一一相對：「四時／一事」（數詞＋名詞）、「可愛／能狂」（助動詞＋形容詞）、「唯／便」（副詞）、「春日／少年」（名詞），(A)完全工整，選A。(B)「五陵／無樹」、(C)「九華帳裡」、(D)「萬里歸心」的結構都無法與上句逐字相對。", "skill": "把上句拆成「數詞名詞＋可愛＋唯＋名詞」，再逐字比對選項的詞性是否位置相同。"}], "difficulty": "中", "label": "94年第二次基測", "year": 94, "kind": "基測"}, {"id": "bc94-2-40", "exam": "bc94-2", "nums": [40, 41, 42], "form": "題組", "img": "img/bc94-2-40.png", "source": "京劇《鎖麟囊》唱詞（翁偶虹編劇）", "author": "翁偶虹", "genre": "古典詩詞曲", "types": ["人物情感", "文意推論"], "passage": "春秋亭外風雨暴，何處悲傷破寂寥？隔簾只見一花轎，想必是新婚渡鵲橋。吉日良辰當歡笑，為何鮫珠化淚拋？此時卻又明白了：世上何嘗盡富豪，也有飢寒悲懷抱，也有失意痛哭嚎。轎內的人兒彈別調，必有隱情在心梢。", "translation": "春秋亭外風雨猛烈，是哪裡傳來的悲傷哭聲打破寂靜？隔著簾子只看見一頂花轎，想必也是新婚出嫁的人。良辰吉日本該歡笑，為什麼卻淚珠拋落？這時我明白了：世上哪裡都是富豪，也有人飢寒交迫滿懷悲傷，也有人失意痛哭。轎裡的人唱的是悲調，心裡一定有說不出的苦衷。", "keywords": [{"w": "渡鵲橋", "m": "喻結婚，用牛郎織女典故"}, {"w": "鮫珠", "m": "傳說鮫人泣淚成珠，指眼淚"}, {"w": "何嘗", "m": "哪裡、何曾"}, {"w": "彈別調", "m": "唱出不同的（悲傷）調子"}, {"w": "心梢", "m": "心頭"}], "questions": [{"n": 40, "stem": "根據薛湘靈的揣測，另一頂花轎中的新娘應是何種心情？", "options": {"A": "嬌羞喜悅", "B": "憤恨不平", "C": "悽愴悲涼", "D": "意興闌珊"}, "answer": "C", "explain": "薛湘靈聽到哭聲，推想對方「也有飢寒悲懷抱，也有失意痛哭嚎」「必有隱情」，認為她是因貧寒困苦而悲傷，是悽愴悲涼，選C。(A)與哭泣相反。(B)唱詞沒有寫怨恨。(D)意興闌珊是提不起興致，程度不符。要注意：要依「薛湘靈的想法」判斷，而非個人經驗。", "skill": "題目問的是「誰的揣測」：只根據薛湘靈的唱詞（悲懷抱、痛哭嚎）判斷，不加入自己的想像。"}, {"n": 41, "stem": "下列成語，何者最適合用來形容薛湘靈與另一位新娘的相遇？", "options": {"A": "狹路相逢", "B": "同病相憐", "C": "兩情相悅", "D": "萍水相逢"}, "answer": "D", "explain": "兩人素不相識，只因避雨偶然在春秋亭相遇，像浮萍在水上偶然碰在一起，是「萍水相逢」，選D。(A)狹路相逢指仇人相遇。(B)同病相憐要兩人處境相同，但一富一貧。(C)兩情相悅指男女相愛。", "skill": "先確定兩人的關係（陌生、偶遇、處境不同），再逐一檢查成語的使用對象。"}, {"n": 42, "stem": "薛湘靈在春秋亭中的體悟與下列何者最為接近？", "options": {"A": "貧富貴賤各有命，並非人人皆幸福", "B": "同是遠嫁他方，應該互相安慰鼓勵", "C": "富貴福分是苦修而來，半點求不得", "D": "女子婚姻無法自主，只能逆來順受"}, "answer": "A", "explain": "「世上何嘗盡富豪，也有飢寒悲懷抱，也有失意痛哭嚎」，她體悟到世上不是人人都像自己一樣富貴幸福，選A。(B)唱詞沒有寫互相鼓勵。(C)沒有談苦修。(D)沒有談婚姻自主。", "skill": "找唱詞中的「此時卻又明白了」——轉折後的句子就是她的體悟。"}], "difficulty": "中", "label": "94年第二次基測", "year": 94, "kind": "基測"}, {"id": "bc94-2-43", "exam": "bc94-2", "nums": [43, 44, 45], "form": "題組", "img": "img/bc94-2-43.png", "source": "周容〈小港渡者〉", "author": "周容", "genre": "寓言故事", "types": ["字詞解釋", "人物情感", "主旨寓意"], "passage": "庚寅冬，予自小港欲入蛟川城，命小奚以木簡束書從。時西日沉山，晚煙縈樹，望程二里許。因問渡者尚可得南門開否。渡者熟視小奚，應曰：「徐行之，尚開也；速進則闔。」予慍為戲。趨行及半，小奚仆，束斷書崩，啼未即起。理書就束而前，門已牡下矣。予爽然，思渡者言近道。天下之以躁急自敗，窮暮而無所歸宿者，其猶是也夫！其猶是也夫！", "translation": "庚寅年冬天，我從小港要進蛟川城，叫小書僮用木板捆著書跟著我。當時夕陽西沉，傍晚的煙霧繚繞樹林，望去路程還有二里左右。我便問渡船的人還趕得上南門開著嗎。渡船人仔細看了看小書僮，回答說：「慢慢走，城門還開著；走得太快就要關了。」我生氣，以為他在開玩笑。快步走到一半，小書僮跌倒，捆書的繩子斷了，書散落一地，他哭著沒能馬上起來。等整理好書、重新捆好再往前走，城門已經上鎖了。我茫然若失，想到渡船人的話接近道理。天下那些因急躁而自取失敗、到了晚上無處可歸的人，大概就像這樣吧！大概就像這樣吧！", "keywords": [{"w": "小奚", "m": "小書僮"}, {"w": "從", "m": "ㄘㄨㄥˊ，跟隨"}, {"w": "熟視", "m": "仔細看"}, {"w": "闔", "m": "關閉"}, {"w": "慍", "m": "生氣"}, {"w": "為戲", "m": "認為是開玩笑"}, {"w": "趨", "m": "快步向前走"}, {"w": "仆", "m": "跌倒"}, {"w": "牡下", "m": "上鎖"}, {"w": "爽然", "m": "失意的樣子"}, {"w": "其猶是也夫", "m": "大概就像這樣吧"}], "questions": [{"n": 43, "stem": "在字典中找到下列四種「從」字的音義說明，何者適用於「命小奚以木簡束書從」句中的「從」字？", "options": {"A": "ㄘㄨㄥˊ，跟隨", "B": "ㄘㄨㄥˊ，向來", "C": "ㄘㄨㄥˊ，附屬的", "D": "ㄗㄨㄥˋ，隨侍的人"}, "answer": "A", "explain": "作者叫書僮捆好書「跟著」自己走，「從」是動詞「跟隨」，選A。(B)「向來」是副詞（如從來）。(C)「附屬的」如從犯。(D)「隨侍的人」是名詞（侍從），但句中是書僮的動作。", "skill": "先判斷「從」在句中是動作、名詞還是修飾語，再到字典義項中找相同詞性的解釋。"}, {"n": 44, "stem": "「渡者熟視小奚，應曰：『徐行之，尚開也；速進則闔。』予慍為戲。」從「予慍為戲」來看，下列何者最可能是作者的想法？", "options": {"A": "認為渡者答非所問，虛應了事", "B": "以為渡者戲弄自己，感到不悅", "C": "與渡者嬉謔，可為旅途添趣", "D": "以為渡者逗弄小奚、打啞謎"}, "answer": "B", "explain": "「慍」是生氣，「為戲」是認為（渡者）在開玩笑。慢走反而來得及、快走反而趕不上，聽來不合常理，作者以為被戲弄而不高興，選B。(A)作者沒有認為答非所問。(C)作者是生氣，不是覺得有趣。(D)渡者是回答作者的問題，看書僮只是在判斷趕路的條件，並非逗弄書僮。", "skill": "拆解「慍＋為戲」兩個關鍵字（生氣＋以為是開玩笑），再找兩者都符合的選項。"}, {"n": 45, "stem": "下列何者最貼近本文的寓意？", "options": {"A": "急欲求速，反而不達", "B": "問道於盲，易入歧途", "C": "日暮趕路，旅行大忌", "D": "前車之鑑，足以為訓"}, "answer": "A", "explain": "作者急著趕路，書僮跌倒、書散一地，反而趕不上城門關閉；作者最後說「天下之以躁急自敗」者都像這樣，寓意就是「欲速則不達」，選A。(B)渡者說的才是對的，不是問道於盲。(C)重點不在日暮趕路，而在急躁。(D)文中沒有拿別人的失敗當借鏡。", "skill": "寓言的寓意通常在結尾的議論句（以躁急自敗），把它換成成語即可。"}], "difficulty": "中", "label": "94年第二次基測", "year": 94, "kind": "基測"}, {"id": "bc95-1-15", "exam": "bc95-1", "nums": [15], "form": "單題", "img": "img/bc95-1-15.png", "source": "張潮《幽夢影》", "author": "張潮", "genre": "筆記小品", "types": ["文化常識", "字詞解釋"], "passage": "甲：中秋須酌淡友　乙：重九須酌逸友　丙：七夕須酌韻友　丁：上元須酌豪友　戊：端午須酌麗友", "translation": "中秋節適合和淡泊的朋友飲酒；重陽節適合和飄逸的朋友飲酒；七夕適合和有風雅韻致的朋友飲酒；元宵節適合和豪放的朋友飲酒；端午節適合和俊美亮麗的朋友飲酒。", "keywords": [{"w": "酌", "m": "飲酒、對飲"}, {"w": "上元", "m": "農曆正月十五元宵節"}, {"w": "重九", "m": "農曆九月九日重陽節"}], "questions": [{"n": 15, "stem": "甲：中秋須酌淡友　乙：重九須酌逸友　丙：七夕須酌韻友　丁：上元須酌豪友　戊：端午須酌麗友。以上文句出自張潮《幽夢影》，若依照民俗節慶先後順序排列，下列何者正確？", "options": {"A": "丁戊丙甲乙", "B": "丁戊乙丙甲", "C": "戊丙丁甲乙", "D": "戊丁丙乙甲"}, "answer": "A", "explain": "把五個節日換成農曆日期：上元（丁）正月十五 → 端午（戊）五月初五 → 七夕（丙）七月初七 → 中秋（甲）八月十五 → 重九（乙）九月初九，順序為丁戊丙甲乙，選(A)。(B)把重九放在七夕前；(C)(D)把端午放在上元（元宵）前，都不合一年節慶先後。", "skill": "先把每個節慶名稱換算成農曆月日，再依月份排序；「上元」＝元宵、「重九」＝重陽是常考別稱。"}], "difficulty": "易", "label": "95年第一次基測", "year": 95, "kind": "基測"}, {"id": "bc95-1-20", "exam": "bc95-1", "nums": [20], "form": "單題", "img": "img/bc95-1-20.png", "source": "出處待查", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "枝頭夜綻紫薇花，卻憶朝時抽綠芽。過客川流旋百代，心驚日去送生涯。", "translation": "枝頭上的紫薇花在夜裡盛開，卻想起早上它才剛抽出綠芽。時間像過客、像河水般流轉，轉眼已是百代；我驚覺日子一天天過去，也一點一點送走了人生。", "keywords": [{"w": "綻", "m": "花開"}, {"w": "過客", "m": "比喻光陰（化用李白「光陰者，百代之過客」）"}, {"w": "川流", "m": "像河水一樣流逝"}, {"w": "生涯", "m": "一生、生命"}], "questions": [{"n": 20, "stem": "「枝頭夜綻紫薇花，卻憶朝時抽綠芽。過客川流旋百代，心驚日去送生涯。」這是作者觀花有感的詩作，下列何者最能說明他的感受？", "options": {"A": "繁花似錦，人獨飄零", "B": "花前送別，離情依依", "C": "花開花落，時光匆匆", "D": "睹物思人，倍感惆悵"}, "answer": "C", "explain": "前兩句寫花從早上抽芽到夜裡盛開，變化極快；後兩句「過客川流」「心驚日去」直接感嘆時間流逝、人生短暫，所以是(C)花開花落，時光匆匆。(A)詩中沒有寫到自己孤單漂泊；(B)沒有送別的人與場景；(D)沒有思念某個人。", "skill": "抓詩中表達感受的關鍵詞（「心驚」「日去」「百代」），判斷作者感嘆的對象是時間，而不是人或離別。"}], "difficulty": "易", "label": "95年第一次基測", "year": 95, "kind": "基測"}, {"id": "bc95-1-22", "exam": "bc95-1", "nums": [22], "form": "單題", "img": "img/bc95-1-22.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "比較閱讀"], "passage": "德盛者，其心和平，見人皆可取，故口中所許可者多。德薄者，其心刻傲，見人皆可憎，故目中所鄙棄者眾。", "translation": "品德高尚的人，心地平和，看每個人都有可取的地方，所以嘴上稱讚、認可的人很多。品德淺薄的人，心地刻薄驕傲，看每個人都覺得可憎，所以眼中瞧不起的人很多。", "keywords": [{"w": "盛", "m": "深厚、高"}, {"w": "可取", "m": "值得肯定"}, {"w": "許可", "m": "稱許、認可"}, {"w": "刻傲", "m": "刻薄而驕傲"}, {"w": "鄙棄", "m": "看不起而厭棄"}], "questions": [{"n": 22, "stem": "「德盛者，其心和平，見人皆可取，故口中所許可者多。德薄者，其心刻傲，見人皆可憎，故目中所鄙棄者眾。」這段話的涵義，與下列何者最接近？", "options": {"A": "見人有善，如己有善；見人有過，如己有過", "B": "利人者，人必從而利之；惡人者，人必從而惡之", "C": "聖人見人，皆聖人也；不肖人見人，則皆不肖矣", "D": "眾惡必察，眾好必察，易；自惡必察，自好必察，難"}, "answer": "C", "explain": "題幹重點：自己的心是什麼樣子，看別人就是什麼樣子（德盛者看人都可取，德薄者看人都可憎）。(C)聖人看人都是聖人，不賢的人看人都不賢，同樣是「以己心看人」，最接近。(A)講看到別人的好壞要當作自己的事來反省；(B)講對人好、人也對你好的回報關係；(D)講判斷別人容易、檢討自己難，都和題旨不同。", "skill": "把題幹壓縮成一句規律（心態決定看人的眼光），再找選項中「同樣的對應關係」，不要被相似字詞（善、惡）誤導。"}], "difficulty": "中", "label": "95年第一次基測", "year": 95, "kind": "基測"}, {"id": "bc95-1-26", "exam": "bc95-1", "nums": [26], "form": "單題", "img": "img/bc95-1-26.png", "source": "張潮《幽夢影》", "author": "張潮", "genre": "筆記小品", "types": ["句意理解", "主旨寓意"], "passage": "寧為小人之所罵，毋為君子之所鄙。", "translation": "寧可被小人辱罵，也不要被君子看不起。", "keywords": [{"w": "寧……毋……", "m": "寧可……也不要……（表示取捨）"}, {"w": "為……之所……", "m": "被……所……（被動句）"}, {"w": "鄙", "m": "輕視、看不起"}], "questions": [{"n": 26, "stem": "「寧為小人之所罵，毋為君子之所鄙。」這句話的寓意，與下列何者最接近？", "options": {"A": "美德與羞辱是不能相容的", "B": "堅持正道，絕不從眾媚俗", "C": "凡事率性而為，毋須盡如人意", "D": "人有準繩規矩，才知平直方圓"}, "answer": "B", "explain": "「寧……毋……」是價值取捨：不怕得罪小人，也不能做讓君子瞧不起的事。不討好小人＝不從眾媚俗；不被君子鄙視＝堅持正道，所以選(B)。(A)題幹沒有談美德和羞辱能否並存；(C)率性而為、不在乎別人，忽略了「毋為君子之所鄙」仍有堅持的標準；(D)強調規矩的重要，與題旨無關。", "skill": "看到「寧A，毋B」就是取捨句，分別翻出「願意承受什麼」與「絕不做什麼」，再對應選項的兩個部分。"}], "difficulty": "中", "label": "95年第一次基測", "year": 95, "kind": "基測"}, {"id": "bc95-1-31", "exam": "bc95-1", "nums": [31], "form": "單題", "img": "img/bc95-1-31.png", "source": "《荀子‧勸學》", "author": "荀子", "genre": "經典語錄", "types": ["句意理解"], "passage": "終日而思，不如須臾之所學。", "translation": "整天空想，比不上片刻的學習。", "keywords": [{"w": "終日", "m": "整天"}, {"w": "須臾", "m": "片刻、一會兒"}, {"w": "不如", "m": "比不上"}], "questions": [{"n": 31, "stem": "「終日而思，不如須臾之所學。」這句話的涵義，與下列何者最相近？", "options": {"A": "思而後學", "B": "學而後思", "C": "思重於學", "D": "學重於思"}, "answer": "D", "explain": "「A不如B」表示B比A重要：整天思考比不上片刻學習，強調學習比空想更重要，所以是(D)學重於思。(C)正好相反；(A)(B)是講先後順序，題幹談的是輕重比較，不是先後。", "skill": "抓比較句型「A不如B」→ B勝過A，再分辨選項問的是「輕重」還是「先後」。"}], "difficulty": "易", "label": "95年第一次基測", "year": 95, "kind": "基測"}, {"id": "bc95-1-40", "exam": "bc95-1", "nums": [40, 41], "form": "題組", "img": "img/bc95-1-40.png", "source": "潘耒〈日知錄序〉", "author": "潘耒", "genre": "書信序跋", "types": ["文意推論", "字詞解釋"], "passage": "崑山顧寧人先生，生長世族，少負絕異之資，潛心古學，九經諸史，略能背誦。\n精力絕人，無他嗜好，自少至老，未嘗一日廢書。出必載書數簏自隨，旅店少休，披尋搜討，曾無倦色。（簏：竹子編成的箱子）", "translation": "崑山的顧寧人（顧炎武）先生，出生成長於世家大族，年少時就有非凡的天資，專心研究古代學問，九經和各部史書，大致都能背誦。他精力過人，沒有其他嗜好，從小到老，沒有一天停止讀書。出門一定用車載著好幾箱書跟著自己，在旅店稍作休息時，就翻書查找、探索研究，從來沒有疲倦的神色。", "keywords": [{"w": "世族", "m": "世代做官的大家族"}, {"w": "負", "m": "具有"}, {"w": "潛心", "m": "專心"}, {"w": "略", "m": "大致"}, {"w": "廢書", "m": "停止讀書"}, {"w": "少休", "m": "稍微休息"}, {"w": "披尋搜討", "m": "翻閱、尋找、搜求、探討"}, {"w": "曾無", "m": "從來沒有"}], "questions": [{"n": 40, "stem": "下列成語，何者最適合用來形容顧寧人先生的讀書態度？", "options": {"A": "旁徵博引", "B": "溫故知新", "C": "孳孳不倦", "D": "披星戴月"}, "answer": "C", "explain": "文中「自少至老，未嘗一日廢書」「旅店少休，披尋搜討，曾無倦色」寫他勤奮讀書、從不疲倦，正是(C)孳孳（孜孜）不倦。(A)旁徵博引是說話寫作廣泛引用資料；(B)溫故知新是複習舊知而有新體會，文中沒寫；(D)披星戴月形容早出晚歸、旅途辛勞，不是讀書態度。", "skill": "找文中描寫讀書行為的句子（未嘗一日廢書、曾無倦色），歸納成「勤奮不倦」，再逐一比對成語本義。"}, {"n": 41, "stem": "下列何者在本文中完全不曾被提及？", "options": {"A": "家世背景", "B": "興趣嗜好", "C": "資質稟賦", "D": "學術地位"}, "answer": "D", "explain": "(A)「生長世族」是家世背景；(B)「無他嗜好」提到嗜好（只愛讀書）；(C)「少負絕異之資」是資質稟賦。文中都沒有提到他在學術界的評價或地位，所以選(D)。", "skill": "「不曾提及」題要逐項回文中找對應句，有證據的刪掉，剩下的就是答案。"}], "difficulty": "易", "label": "95年第一次基測", "year": 95, "kind": "基測"}, {"id": "bc95-1-47", "exam": "bc95-1", "nums": [47, 48], "form": "題組", "img": "img/bc95-1-47.png", "source": "劉向《說苑‧卷八‧尊賢》", "author": "劉向", "genre": "史傳人物", "types": ["句意理解", "主旨寓意", "寫作手法"], "passage": "趙簡子游於西河而樂之，歎曰：「安得賢士而與處焉？」舟人古乘跪而對曰：「夫珠玉無足，去此數千里，而所以能來者，人好之也；今士有足而不來者，此是吾君不好之乎！」趙簡子曰：「吾門左右客千人，朝食不足，暮收市徵；暮食不足，朝收市徵，吾尚可謂不好士乎？」舟人古乘對曰：「鴻鵠高飛遠翔，其所恃者六翮也。背上之毛，腹下之毳，無尺寸之數。去之滿把，飛不能為之益卑；益之滿把，飛不能為之益高。不知門下左右客千人者，亦有六翮之用乎？將盡毛毳也？」（徵：徵收、課取；六翮：鳥的兩翼；毳：鳥獸的細毛）", "translation": "趙簡子在西河遊玩，非常快樂，感嘆說：「哪裡能得到賢士和我相處呢？」船夫古乘跪著回答：「珠玉沒有腳，離這裡幾千里，卻能來到這裡，是因為人們喜愛它；現在賢士有腳卻不來，這恐怕是您不真心喜愛賢士吧！」趙簡子說：「我門下左右的食客有上千人，早上糧食不夠，晚上就去市場徵稅；晚上糧食不夠，早上就去徵稅，我還能說是不喜愛賢士嗎？」古乘回答：「鴻鵠能高飛遠翔，靠的是兩隻翅膀。背上的毛、腹下的細毛，多得數不清；拔掉一大把，牠也不會因此飛得更低；加上一大把，也不會因此飛得更高。不知道您門下這上千位食客，有翅膀那樣的作用嗎？還是全都只是那些細毛呢？」", "keywords": [{"w": "安得", "m": "怎麼能得到"}, {"w": "所以", "m": "……的原因"}, {"w": "好", "m": "喜愛（動詞）"}, {"w": "恃", "m": "依靠"}, {"w": "去", "m": "除去"}, {"w": "益", "m": "增加；更加"}, {"w": "將", "m": "還是（表選擇）"}], "questions": [{"n": 47, "stem": "「夫珠玉無足，去此數千里，而所以能來者，人好之也；今士有足而不來者，此是吾君不好之乎！」這句話的意旨，與下列何者最接近？", "options": {"A": "黃金千兩不如一賢", "B": "君誠好賢，則人才自至", "C": "用人取其長而不問其短", "D": "用不才之士，則費日無功"}, "answer": "B", "explain": "古乘用「珠玉沒腳都能來，因為人喜愛它」對比「賢士有腳卻不來」，推出：只要君王真心愛才，人才自然會來，所以選(B)。(A)比較黃金與賢士的價值，題幹沒有；(C)談用人的方法；(D)談用錯人的後果，都不是這句話的意思。", "skill": "看懂對比論證：珠玉（無足而來）vs. 賢士（有足不來），原因都在「好不好」，結論就是「真心好賢，人才自至」。"}, {"n": 48, "stem": "「鴻鵠高飛遠翔，其所恃者六翮也。背上之毛，腹下之毳，無尺寸之數。去之滿把，飛不能為之益卑；益之滿把，飛不能為之益高。不知門下左右客千人者，亦有六翮之用乎？將盡毛毳也？」古乘這段話的用意為下列何者？", "options": {"A": "提醒趙簡子求賢在精不在多", "B": "鼓勵趙簡子廣納人才、任賢舉能", "C": "告誡趙簡子先高己志，則賢者歸附", "D": "規勸趙簡子用賢無須考慮其出身之貴賤"}, "answer": "A", "explain": "鴻鵠高飛靠的是「六翮」（翅膀），不是數不清的細毛；細毛多一把少一把都不影響飛行。古乘用這個比喻提醒趙簡子：門客上千人若都只是「毛毳」，也沒有用，求賢重在真正有才能的少數人，所以是(A)。(B)廣納人才正是趙簡子已在做、而古乘認為不夠的；(C)題文沒有談提高自己的志向；(D)題文沒有談出身貴賤。", "skill": "先找比喻的對應：六翮＝真正的賢才、毛毳＝充數的門客，再從「多少不影響飛行」推出「重質不重量」。"}], "difficulty": "中", "label": "95年第一次基測", "year": 95, "kind": "基測"}, {"id": "bc95-2-8", "exam": "bc95-2", "nums": [8], "form": "單題", "img": "img/bc95-2-8.png", "source": "袁枚〈遣興〉", "author": "袁枚", "genre": "古典詩詞曲", "types": ["詩詞賞析", "主旨寓意"], "passage": "但肯尋詩便有詩，靈犀一點是吾師。夕陽芳草尋常物，解用都為絕妙詞。", "translation": "只要肯用心去找詩意，就處處有詩；心中那一點靈敏的感受，就是我的老師。夕陽、芳草這些平常的景物，只要懂得運用，都能寫成絕妙的詩句。", "keywords": [{"w": "但", "m": "只要"}, {"w": "靈犀一點", "m": "比喻心靈敏銳的感悟"}, {"w": "尋常物", "m": "平常的東西"}, {"w": "解", "m": "懂得、會"}], "questions": [{"n": 8, "stem": "袁枚〈遣興〉：「但肯尋詩便有詩，靈犀一點是吾師。夕陽芳草尋常物，解用都為絕妙詞。」下列何者與這首詩的主旨最接近？", "options": {"A": "太過尋常的景物，難以成就傳世的佳作", "B": "寫詩是為了表達真正的情感，貴在真誠", "C": "寫詩題材俯拾皆是，有心便能構成詩趣", "D": "詩的優劣不在詩句本身，全看詮釋功夫"}, "answer": "C", "explain": "「但肯尋詩便有詩」＝有心就有詩；「夕陽芳草尋常物，解用都為絕妙詞」＝平常景物都能寫成好詩，所以是(C)題材俯拾皆是。(A)與「尋常物」也能成「絕妙詞」相反；(B)詩中沒有談情感真誠；(D)「解用」是指寫詩的人會運用素材，不是讀者的詮釋。", "skill": "抓住詩中的條件句「但肯……便……」與轉折「尋常物→絕妙詞」，主旨就是「用心則處處是詩材」。"}], "difficulty": "易", "label": "95年第二次基測", "year": 95, "kind": "基測"}, {"id": "bc95-2-11", "exam": "bc95-2", "nums": [11], "form": "單題", "img": "img/bc95-2-11.png", "source": "李白〈黃鶴樓送孟浩然之廣陵〉；選項為多首古典詩", "author": "李白等", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "故人西辭黃鶴樓，煙花三月下揚州。孤帆遠影碧山盡，唯見長江天際流。", "translation": "老朋友在西邊的黃鶴樓向我告別，在繁花如煙的三月順流東下揚州。孤單的船帆漸漸遠去，消失在青山盡頭，只看見長江向天邊奔流。", "keywords": [{"w": "煙花", "m": "春天繁花似錦、霧氣朦朧的景色"}, {"w": "三月", "m": "農曆三月，暮春"}, {"w": "芰荷", "m": "菱與荷，夏季植物"}, {"w": "征雁", "m": "遷徙的雁，秋季意象"}, {"w": "東風", "m": "春風"}], "questions": [{"n": 11, "stem": "「故人西辭黃鶴樓，煙花三月下揚州。孤帆遠影碧山盡，唯見長江天際流。」這首詩所描寫的季節與下列何者相同？", "options": {"A": "四顧山光接水光，憑欄十里芰荷香。清風明月無人管，並做南來一味涼", "B": "初聞征雁已無蟬，百尺樓高水接天。青女素娥俱耐冷，月中霜裏鬥嬋娟", "C": "細草鋪茵綠滿堤，燕飛晴日正遲遲。尋芳陌上花如錦，折得東風第一枝", "D": "隴水潺湲隴樹黃，征人隴上盡思鄉。馬嘶斜日朔風急，雁過寒雲邊思長"}, "answer": "C", "explain": "題幹「煙花三月」是春天。(C)細草、燕飛、花如錦、東風，都是春天景象。(A)「十里芰荷香」是夏天荷花盛開；(B)「征雁」「無蟬」「霜」是秋天；(D)「樹黃」「朔風」「雁過寒雲」是秋冬。", "skill": "找每首詩的季節關鍵意象（煙花、東風＝春；荷＝夏；雁、霜、樹黃＝秋；朔風、雪＝冬），再比對。"}], "difficulty": "易", "label": "95年第二次基測", "year": 95, "kind": "基測"}, {"id": "bc95-2-13", "exam": "bc95-2", "nums": [13], "form": "單題", "img": "img/bc95-2-13.png", "source": "選項為多首古典詩詞", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "字詞解釋"], "passage": "(A)朔風鳴淅淅，寒雨下霏霏　(B)江雨舊無時，天晴忽散絲　(C)枕前淚共階前雨，隔個窗兒滴到明　(D)雷霹老松疑虎怒，雨沖煙洞覺龍醒", "translation": "(A)北風淅淅作響，冷雨細細綿綿地落下。(B)江上的雨向來沒有定時，天晴時忽然飄下細絲般的雨。(C)枕上的眼淚和臺階前的雨，隔著一扇窗一起滴到天亮。(D)雷電劈打老松，聲響像老虎發怒；大雨沖進雲霧瀰漫的山洞，彷彿驚醒了沉睡的龍。", "keywords": [{"w": "霏霏", "m": "雨雪細密的樣子"}, {"w": "散絲", "m": "像散開的細絲，指細雨"}, {"w": "霹", "m": "雷擊"}, {"w": "磅礴", "m": "氣勢盛大"}], "questions": [{"n": 13, "stem": "下列詩句中所提及的雨勢，何者最為磅礴？", "options": {"A": "朔風鳴淅淅，寒雨下霏霏", "B": "江雨舊無時，天晴忽散絲", "C": "枕前淚共階前雨，隔個窗兒滴到明", "D": "雷霹老松疑虎怒，雨沖煙洞覺龍醒"}, "answer": "D", "explain": "(D)有雷劈老松、如虎怒吼，大雨猛沖山洞、像驚醒蛟龍，用猛獸比喻，雨勢最猛烈磅礴。(A)「霏霏」是細密的雨；(B)「散絲」是細雨；(C)雨一滴一滴落到天亮，是綿綿小雨，著重哀愁。", "skill": "看描寫雨的形容詞與比喻：霏霏、散絲、滴＝小雨；雷霹、虎怒、雨沖、龍醒＝大雨。"}], "difficulty": "易", "label": "95年第二次基測", "year": 95, "kind": "基測"}, {"id": "bc95-2-22", "exam": "bc95-2", "nums": [22], "form": "單題", "img": "img/bc95-2-22.png", "source": "題辭（典故：魯班；《莊子‧天道》輪扁）", "author": "", "genre": "其他", "types": ["典故出處", "文化常識"], "passage": "魯班藝巧動斧似無跡，輪扁技高運斤如有神。（斤：斧頭）", "translation": "像魯班一樣手藝精巧，用斧頭幾乎不留痕跡；像輪扁一樣技術高超，揮動斧頭如有神助。", "keywords": [{"w": "魯班", "m": "春秋時魯國巧匠，被尊為木匠祖師"}, {"w": "輪扁", "m": "《莊子》中製作車輪的工匠"}, {"w": "運斤", "m": "揮動斧頭"}], "questions": [{"n": 22, "stem": "我們常以「華佗再世，妙手回春」的題辭贈予醫生，因為華佗是東漢時期醫術精湛的醫生。那麼，「魯班藝巧動斧似無跡，輪扁技高運斤如有神」最適合用來贈予下列何者？", "options": {"A": "演員訓練班", "B": "書法才藝班", "C": "室內裝潢公司", "D": "貨車出租公司"}, "answer": "C", "explain": "魯班是木匠祖師，輪扁是做車輪的巧匠，「動斧」「運斤」都是用斧頭做木工，稱讚的是木作手藝，最適合送給(C)室內裝潢公司。(A)(B)與木工無關；(D)雖有「輪」字，但輪扁是做輪子的工匠，不是車輛出租。", "skill": "認出題辭中的人物典故（魯班、輪扁都是工匠）和動作（運斤＝用斧），推出對應行業，不要被「輪」字表面誤導。"}], "difficulty": "中", "label": "95年第二次基測", "year": 95, "kind": "基測"}, {"id": "bc95-2-29", "exam": "bc95-2", "nums": [29], "form": "單題", "img": "img/bc95-2-29.png", "source": "文言句式（馬首是瞻：《左傳‧襄公十四年》）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "馬首是瞻（＝瞻馬首）；惟力是視（＝惟視力）", "translation": "「馬首是瞻」：只看主帥的馬頭行動，比喻追隨某人。「惟力是視」：只看自己的能力去做。", "keywords": [{"w": "是", "m": "助詞，用在提前的賓語後，標示賓語提前"}, {"w": "瞻", "m": "看、望"}, {"w": "惟", "m": "只"}], "questions": [{"n": 29, "stem": "「馬首是瞻」就是「瞻馬首」的意思，「是」為助詞，它的作用是將「馬首」提前。下列文句中的「是」字，何者用法也相同？", "options": {"A": "眼見「是」實，千萬不要道聽塗說", "B": "做事當惟力「是」視，不要逞強稱能", "C": "小弟弟迷了路，一時之間不知如何「是」好", "D": "他所提出的計畫，被主管批評得一無「是」處"}, "answer": "B", "explain": "「惟力是視」就是「惟視力」：只看自己的能力，「是」把賓語「力」提到動詞「視」前，和「馬首是瞻」同樣是賓語提前，選(B)。(A)「是」為判斷動詞「才是」；(C)「如何是好」的「是」是「才是、才算」；(D)「一無是處」的「是」是「對的、正確」。", "skill": "把句子還原：若「A是B」能改成「B A」（動詞＋賓語）且意思不變，「是」就是賓語提前的助詞。"}], "difficulty": "中", "label": "95年第二次基測", "year": 95, "kind": "基測"}, {"id": "bc95-2-31", "exam": "bc95-2", "nums": [31], "form": "單題", "img": "img/bc95-2-31.png", "source": "選項為文言格言，出處待查", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "(A)執於一見之爭，百口難辯其理　(B)知不足者好學，恥下問者自滿　(C)不廣求，故得；不雜學，故明　(D)不學，則不成；不問，則不知", "translation": "(A)固執於自己一種見解去爭辯，就算有一百張嘴也說不清道理。(B)知道自己不足的人會好學，以向人請教為恥的人會自滿。(C)不貪多求廣，所以有收穫；不雜亂地學，所以能通透明白。(D)不學習就不能成功，不發問就不會知道。", "keywords": [{"w": "故", "m": "所以"}, {"w": "明", "m": "通曉、明白"}, {"w": "雜學", "m": "什麼都學、不專一"}], "questions": [{"n": 31, "stem": "「與其花許多時間和精力去鑿許多淺井，不如花同樣的時間和精力，去鑿一口深井。」這段話的涵義，與下列何者最接近？", "options": {"A": "執於一見之爭，百口難辯其理", "B": "知不足者好學，恥下問者自滿", "C": "不廣求，故得；不雜學，故明", "D": "不學，則不成；不問，則不知"}, "answer": "C", "explain": "題幹用「鑿深井」比喻專心深入一門，勝過淺嘗許多。(C)不貪多、不雜學，才能有所得、有所明，同樣強調專精，選(C)。(A)講固執爭辯；(B)講謙虛好學；(D)講學與問都重要，都沒有「專一深入」的意思。", "skill": "先把題幹比喻翻成道理（深井＝專精，淺井＝博而不精），再把文言選項逐一譯成白話比對。"}], "difficulty": "中", "label": "95年第二次基測", "year": 95, "kind": "基測"}, {"id": "bc95-2-34", "exam": "bc95-2", "nums": [34], "form": "單題", "img": "img/bc95-2-34.png", "source": "顧況〈宮詞〉", "author": "顧況", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "玉樓天半起笙歌，風□宮嬪笑語和。月殿影開聞夜漏，水精簾捲近秋□。", "translation": "高聳入天的玉樓上響起笙樂歌聲，風把宮女們和樂的笑語聲送了過來。月光照進宮殿，聽得見夜裡計時的漏壺滴聲；捲起水晶簾子，彷彿靠近了秋夜的銀河。", "keywords": [{"w": "天半", "m": "半空中，形容樓高"}, {"w": "宮嬪", "m": "宮女、嬪妃"}, {"w": "夜漏", "m": "夜間計時的漏壺"}, {"w": "秋河", "m": "秋夜的銀河"}], "questions": [{"n": 34, "stem": "根據近體詩的格律，下列這首七言絕句中的空格應填入哪些字？玉樓天半起笙歌，風□宮嬪笑語和。月殿影開聞夜漏，水精簾捲近秋□。", "options": {"A": "送，河", "B": "迎，波", "C": "拂，色", "D": "向，月"}, "answer": "A", "explain": "一、押韻：首句「歌」與第二句「和」同韻（ㄜ韻），第四句句尾也要押韻，只有「河」「波」合韻，刪去(C)(D)。二、平仄：七絕第二句的第二字要和第一句第二字（樓，平聲）相反，須用仄聲；「送」是仄聲，「迎」是平聲，所以選(A)。意思上「風送笑語」也最通順。", "skill": "填近體詩空格先看押韻（偶數句句尾同韻），再看平仄（一聯上下句第二字平仄相反），最後用文意檢查。"}], "difficulty": "難", "label": "95年第二次基測", "year": 95, "kind": "基測"}, {"id": "bc95-2-44", "exam": "bc95-2", "nums": [44, 45, 46], "form": "題組", "img": "img/bc95-2-44.png", "source": "干寶《搜神記》（改寫）", "author": "干寶", "genre": "筆記小品", "types": ["主旨寓意", "虛詞句式", "人物情感"], "passage": "漢董永，千乘人。少偏孤，與父居。肆力田畝，鹿車載自隨。父亡，無以葬之，乃自賣為奴，以供喪事。主人知其賢，與錢一萬，遣之。永行三年喪畢，欲還主人，供其奴職。道逢一婦人，曰：「願為子妻。」言訖，與之俱往。主人謂永曰：「以錢與君矣。」永曰：「蒙君之惠，父喪收藏。永雖小人，必欲服勤致力，以報厚德。」主曰：「婦人何能？」永曰：「能織。」主曰：「必爾者，但令君婦為我織縑百疋。」於是，永妻為主人家織，十日而畢。女出門，謂永曰：「我，天之織女也。緣君至孝，天帝令我助君償債耳。」語畢，離之而去，不知所在。", "translation": "漢朝的董永是千乘人。小時候母親過世，和父親一起生活。他在田裡努力耕作，用小車載著父親跟在身邊。父親死了，沒錢安葬，就把自己賣作奴僕來辦喪事。主人知道他賢德，給他一萬錢，讓他回去。董永守完三年喪，想回主人家盡奴僕的職責。路上遇到一位婦人，說：「我願意當你的妻子。」說完就和他一起去。主人對董永說：「錢是送給你的了。」董永說：「承蒙您的恩惠，父親才得以安葬。我雖是卑微的人，也一定要盡心出力，報答您的厚恩。」主人說：「你妻子會做什麼？」董永說：「會織布。」主人說：「一定要這樣的話，只要讓你妻子替我織一百匹細絹就好。」於是董永的妻子為主人家織布，十天就織完。她出門後對董永說：「我是天上的織女。因為你非常孝順，天帝命我幫你還債罷了。」說完就離開他，不知去了哪裡。", "keywords": [{"w": "偏孤", "m": "幼年喪失父母其中一人"}, {"w": "肆力", "m": "盡力"}, {"w": "無以", "m": "沒有辦法、沒有錢財可以"}, {"w": "遣", "m": "讓……離開"}, {"w": "訖", "m": "完畢"}, {"w": "必爾者", "m": "一定要這樣的話"}, {"w": "但", "m": "只"}, {"w": "緣", "m": "因為"}], "questions": [{"n": 44, "stem": "本文依內容旨趣，應屬下列哪一類故事？", "options": {"A": "愛情類", "B": "忠義類", "C": "俠客類", "D": "孝親類"}, "answer": "D", "explain": "故事從董永賣身葬父開始，主人「知其賢」而贈錢，織女自稱「緣君至孝，天帝令我助君償債」，一切情節都因董永的孝順而起，屬(D)孝親類。(A)織女只是奉命相助，最後離去，不是愛情主軸；(B)報答主人是情節的一部分，但起因仍是孝；(C)沒有行俠仗義的人物。", "skill": "看故事的起因與結尾點題句（緣君至孝），判斷全文主旨，不要被中段情節帶走。"}, {"n": 45, "stem": "根據本文，下列「之」字何者不是指董永？", "options": {"A": "父亡，無以葬之", "B": "與錢一萬，遣之", "C": "言訖，與之俱往", "D": "語畢，離之而去"}, "answer": "A", "explain": "(A)「無以葬之」：沒錢安葬他，「之」指董永的父親。(B)主人讓董永離開，「之」指董永；(C)婦人和董永一起去；(D)織女離開董永，「之」都指董永。", "skill": "代詞「之」要回到上下文找「被做這件事的人」：葬的是誰、遣的是誰、與誰同行、離開誰。"}, {"n": 46, "stem": "根據本文，下列各選項對人物的評述，何者無法確知？", "options": {"A": "董永重諾有擔當", "B": "主人施恩不望報", "C": "織女智勇雙全", "D": "天帝賞善濟弱"}, "answer": "C", "explain": "(A)董永守喪後主動回去當奴僕，信守承諾；(B)主人說「以錢與君矣」，表示錢是送的，不求回報；(D)天帝因董永至孝派織女幫他還債，是獎賞善行、幫助弱者。(C)文中只寫織女會織、十日而畢，看不出她「智勇雙全」，所以無法確知。", "skill": "「無法確知」題要逐一找文本證據，凡是只能憑想像、文中沒有對應句的就是答案。"}], "difficulty": "中", "label": "95年第二次基測", "year": 95, "kind": "基測"}, {"id": "bc95-2-47", "exam": "bc95-2", "nums": [47, 48], "form": "題組", "img": "img/bc95-2-47.png", "source": "沈括《夢溪筆談》（改寫）", "author": "沈括", "genre": "史傳人物", "types": ["句意理解", "人物情感", "文意推論"], "passage": "狄青為樞密副使，宣撫廣西。時儂智高據昆侖關。青至賓州，值上元節，遂張燈燭，令首夜讌將佐，次夜讌從軍官，三夜饗軍校。賊騎據以報。首夜樂飲徹曉，次夜二鼓時，青忽稱疾，暫起如內。久之，使人諭孫元規，令暫主席行酒，少服藥乃出。數使人勤勞座客，至曉，各未敢退。忽有馳報者云：是夜三鼓，青已奪昆侖矣。（讌：同「宴」）", "translation": "狄青擔任樞密副使，奉命去安撫廣西。當時儂智高佔據昆侖關。狄青到了賓州，正逢元宵節，就張燈結綵，下令第一夜宴請將領，第二夜宴請隨軍官員，第三夜犒賞軍校。敵方騎兵探子依此回報。第一夜大家歡飲到天亮；第二夜二更時，狄青忽然說生病，暫時起身到內室。過了很久，派人告訴孫元規，請他暫代主持宴席、敬酒，說自己稍微服藥後就出來。他多次派人殷勤慰勞在座賓客，到天亮，大家都不敢離開。忽然有人騎馬飛報：這天夜裡三更，狄青已經攻下昆侖關了。", "keywords": [{"w": "值", "m": "正逢"}, {"w": "讌／饗", "m": "宴請、犒賞"}, {"w": "徹曉", "m": "直到天亮"}, {"w": "如", "m": "往、到"}, {"w": "諭", "m": "告知"}, {"w": "數", "m": "屢次"}, {"w": "勤勞", "m": "殷勤慰勞（動詞）"}], "questions": [{"n": 47, "stem": "「數使人勤勞座客，至曉，各未敢退」的意思是下列何者？", "options": {"A": "數名使者勤奮地扮演賓客，到天亮都不敢退場", "B": "數次派人殷勤款待，到天亮賓客們都不敢離開", "C": "數名賓客殷勤互相勸飲，天亮以後宴會才結束", "D": "數次勞煩賓客易座交談，直到天亮都沒人離去"}, "answer": "B", "explain": "「數」讀ㄕㄨㄛˋ，是屢次；「使人」是派人；「勤勞座客」是殷勤慰勞在座客人；「各未敢退」是大家都不敢離席。合起來就是(B)。(A)(C)把「數」誤解成「數名」；(D)「易座交談」原文沒有。", "skill": "逐字對譯：先確定「數」是副詞「屢次」、「使」是動詞「派遣」，句子主幹就清楚了。"}, {"n": 48, "stem": "本文最能呈現狄青的哪一項特色？", "options": {"A": "體諒部屬，甘苦與共", "B": "個性隨和，與人同樂", "C": "執法不苟，令出如山", "D": "足智多謀，用兵神妙"}, "answer": "D", "explain": "狄青故意大張宴席讓敵人探子回報、以為他在過節，自己卻假裝生病離席，趁夜三更攻下昆侖關，是用計麻痺敵人、出奇制勝，選(D)。(A)(B)宴會只是計策的掩護，重點不在與部屬同樂；(C)文中沒有執法的情節。", "skill": "注意情節中的「反常」（主帥稱病離席、敵人據以報），推出這是計謀，人物特質就是智謀。"}], "difficulty": "中", "label": "95年第二次基測", "year": 95, "kind": "基測"}, {"id": "bc96-1-8", "exam": "bc96-1", "nums": [8], "form": "單題", "img": "img/bc96-1-8.png", "source": "出處待查（官方說明：古人論山水的畫法）", "author": "", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "山頭不得一樣，樹頭不得一般。山藉樹而為衣，樹藉山而為骨，樹不可繁，要見山之秀麗；山不可亂，須顯樹之精神。能如此者，可謂名手之畫山水也。", "translation": "山頭不能畫得都一樣，樹梢也不能畫得都相同。山靠樹當作衣裳，樹靠山當作骨架；樹不能畫得太繁密，要讓人看見山的秀麗；山不能畫得太雜亂，必須顯出樹的精神。能做到這樣，才稱得上是畫山水的高手。", "keywords": [{"w": "不得", "m": "不可以"}, {"w": "藉", "m": "憑藉、依靠"}, {"w": "見", "m": "同「現」，顯現"}, {"w": "名手", "m": "高明的畫家"}], "questions": [{"n": 8, "stem": "「山頭不得一樣，樹頭不得一般。山藉樹而為衣，樹藉山而為骨，樹不可繁，要見山之秀麗；山不可亂，須顯樹之精神。能如此者，可謂名手之畫山水也。」這段文字主要在說明下列何者？", "options": {"A": "欣賞山水的角度", "B": "繪畫山水的技巧", "C": "保護山水的重要", "D": "分析山水的形貌"}, "answer": "B", "explain": "文中「不得」「不可」「須」都是對作畫的要求，最後一句「可謂名手之畫山水也」點明是在講怎樣畫山水才高明，所以選(B)。(A)不是講觀賞者怎麼看；(C)沒談保護；(D)雖提到山與樹，但目的是指導畫法，不是分析山水本身的樣貌。", "skill": "找總結句（能如此者，可謂……）判斷全文在談什麼；連續出現「不得、不可、須」代表在說方法或規範。"}], "difficulty": "易", "label": "96年第一次基測", "year": 96, "kind": "基測"}, {"id": "bc96-1-12", "exam": "bc96-1", "nums": [12], "form": "單題", "img": "img/bc96-1-12.png", "source": "《禮記‧儒行》、《論語‧陽貨》、《論語‧衛靈公》等", "author": "", "genre": "經典語錄", "types": ["句意理解", "典故出處"], "passage": "(A)士可殺，不可辱　(B)殺雞焉用牛刀　(C)人無遠慮，必有近憂　(D)少年得志大不幸", "translation": "(A)讀書人可以被殺，卻不能受侮辱。(B)殺雞何必用宰牛的刀，比喻小事不必用大才。(C)人如果沒有長遠的考慮，憂患很快就會到來。(D)年紀輕輕就順利得志，反而是很大的不幸（容易驕傲而失敗）。", "keywords": [{"w": "士", "m": "讀書人、有氣節的人"}, {"w": "焉", "m": "何必、哪裡"}, {"w": "慮", "m": "考慮、打算"}, {"w": "得志", "m": "實現抱負、仕途順利"}], "questions": [{"n": 12, "stem": "下列文句的說明，何者最恰當？", "options": {"A": "「士可殺，不可辱」——生命非常寶貴，不可以輕易犧牲", "B": "「殺雞焉用牛刀」——想把工作做好，先要有萬全的準備", "C": "「人無遠慮，必有近憂」——人如果不做長遠的打算，將有憂患的事情發生", "D": "「少年得志大不幸」——太早決定自己人生的方向，長大之後必定一事無成"}, "answer": "C", "explain": "(C)說明正確：沒有長遠考慮，眼前就會有憂患。(A)原意是重視人格尊嚴，寧死也不受辱，與「生命寶貴、不可犧牲」相反；(B)原意是小事不必用大才或大陣仗，不是講充分準備；(D)「得志」是指年少就功成名就，容易驕傲，不是「決定人生方向」。", "skill": "把文言名句逐字翻譯（焉＝何必、得志＝成功），再比對說明是否扭曲原意。"}], "difficulty": "中", "label": "96年第一次基測", "year": 96, "kind": "基測"}, {"id": "bc96-1-18", "exam": "bc96-1", "nums": [18], "form": "單題", "img": "img/bc96-1-18.png", "source": "納蘭性德〈采桑子〉", "author": "納蘭性德", "genre": "古典詩詞曲", "types": ["詩詞賞析", "句意理解"], "passage": "涼生露氣湘絃潤，暗滴花梢。簾影誰搖，燕蹴風絲上柳條。", "translation": "夜涼露生，露氣潤濕了琴絃，露珠暗暗滴落在花梢上。是誰搖動了簾影？原來是燕子飛過，踢起一陣微風，拂動柳條。", "keywords": [{"w": "湘絃", "m": "琴絃（湘妃鼓瑟典故，泛指琴瑟）"}, {"w": "潤", "m": "沾濕"}, {"w": "蹴", "m": "踢、踏"}, {"w": "風絲", "m": "細微的風"}], "questions": [{"n": 18, "stem": "清代詞人納蘭性德的〈采桑子〉，描寫一位閨中女子清晨醒來的所見所思，以下為其譯文：「夜涼露生，使得露氣潤濕了琴絃，露珠暗暗滴落在花梢上。忽見簾外疏影輕搖，是誰？原來是燕子飛過，帶來一陣微風，拂動了柳條。」據此判斷，下列何者為正確的斷句？", "options": {"A": "涼生露氣湘，絃潤暗滴花梢。簾影誰搖燕，蹴風絲上柳條", "B": "涼生露氣湘絃，潤暗滴花梢。簾影誰搖燕蹴，風絲上柳條", "C": "涼生露氣湘絃潤，暗滴花梢。簾影誰搖，燕蹴風絲上柳條", "D": "涼生露氣湘絃潤暗，滴花梢。簾影誰搖燕蹴風絲，上柳條"}, "answer": "C", "explain": "對照譯文：「露氣潤濕了琴絃」＝「露氣湘絃潤」，主詞、名詞、動詞要在同一句；「露珠暗暗滴落在花梢」＝「暗滴花梢」；「是誰？」＝「簾影誰搖」；「燕子飛過帶來微風拂動柳條」＝「燕蹴風絲上柳條」。所以是(C)。(A)把「湘絃」拆開；(B)把「潤」和「湘絃」分開；(D)把「暗」接在「潤」後，又把「誰搖」與「燕蹴」連成一句，都與譯文不合。", "skill": "斷句先對照譯文找意義單位：詞語不可拆（湘絃）、動作要跟主體同句（湘絃潤），問句要獨立（簾影誰搖）。"}], "difficulty": "中", "label": "96年第一次基測", "year": 96, "kind": "基測"}, {"id": "bc96-1-21", "exam": "bc96-1", "nums": [21], "form": "單題", "img": "img/bc96-1-21.png", "source": "《韓非子‧說林上》", "author": "韓非", "genre": "寓言故事", "types": ["文意推論", "人物情感"], "passage": "孟孫獵得麑，使秦西巴持歸，其母隨而鳴，秦西巴不忍，縱而與之。孟孫怒逐秦西巴。居一年，召以為其子傅，左右曰：「秦西巴有罪於君，今召以為子傅，何也？」孟孫曰：「夫以一麑而不忍，又將能忍吾子乎？」（麑：音ㄋㄧˊ，小鹿）", "translation": "孟孫打獵捉到一隻小鹿，叫秦西巴帶回去，小鹿的母親跟在後面哀鳴，秦西巴不忍心，就放了小鹿還給母鹿。孟孫大怒，趕走秦西巴。過了一年，又把他召回來當兒子的老師。身邊的人問：「秦西巴得罪過您，現在卻召他當公子的老師，為什麼？」孟孫說：「他連一隻小鹿都不忍心傷害，又怎麼會忍心傷害我的兒子呢？」", "keywords": [{"w": "使", "m": "派、叫"}, {"w": "縱", "m": "放走"}, {"w": "逐", "m": "驅逐、趕走"}, {"w": "居一年", "m": "過了一年"}, {"w": "傅", "m": "老師"}, {"w": "忍", "m": "狠心"}], "questions": [{"n": 21, "stem": "孟孫獵得麑，使秦西巴持歸，其母隨而鳴，秦西巴不忍，縱而與之。孟孫怒逐秦西巴。居一年，召以為其子傅，左右曰：「秦西巴有罪於君，今召以為子傅，何也？」孟孫曰：「夫以一麑而不忍，又將能忍吾子乎？」根據這則故事，下列何者是秦西巴獲召而回的主要原因？", "options": {"A": "所犯之過甚微，不足為意", "B": "以仁存心，必能愛物惜人", "C": "世人皆毀之，孟孫獨憐才", "D": "孟孫之子驕橫，無人可忍"}, "answer": "B", "explain": "孟孫的回答「以一麑而不忍，又將能忍吾子乎」是關鍵：秦西巴對小鹿都有不忍之心，必定也會愛護自己的兒子，所以選(B)。(A)孟孫當時大怒驅逐他，可見不是小過；(C)文中沒有世人毀謗他；(D)誤解「忍」字，這裡的「忍」是狠心，不是忍受。", "skill": "找出故事中人物說明理由的那句話（夫以……又將……乎？），用「小推大」的邏輯判斷原因。"}], "difficulty": "易", "label": "96年第一次基測", "year": 96, "kind": "基測"}, {"id": "bc96-1-23", "exam": "bc96-1", "nums": [23], "form": "單題", "img": "img/bc96-1-23.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "事到全美處，怨我者不能開指摘之端；行到至汙處，愛我者不能施愛護之法。", "translation": "事情做到完美無缺，連怨恨我的人也找不到可以挑剔的地方；行為壞到極點，連愛我的人也沒有辦法維護我。", "keywords": [{"w": "全美", "m": "完美"}, {"w": "指摘", "m": "挑剔、指責"}, {"w": "端", "m": "開頭、把柄"}, {"w": "至汙", "m": "極為卑劣"}], "questions": [{"n": 23, "stem": "「事到全美處，怨我者不能開指摘之端；行到至汙處，愛我者不能施愛護之法。」這段話的旨意與下列何者最接近？", "options": {"A": "律己宜從嚴，待人宜從寬", "B": "不怕人不敬己，就怕己身不正", "C": "明者因時制宜，智者見機行事", "D": "一時強弱在於力，萬古勝負在於理"}, "answer": "B", "explain": "兩句對照：自己做得好，敵人也挑不出毛病；自己做得壞，親友也保不了你。重點是「關鍵在自己行為正不正」，與(B)相同。(A)談對己對人的寬嚴；(C)談隨機應變；(D)談力與理的長短久暫，都不合。", "skill": "對比句要抓兩句共同的變因（自己的作為），再推出結論「操之在己」。"}], "difficulty": "中", "label": "96年第一次基測", "year": 96, "kind": "基測"}, {"id": "bc96-1-24", "exam": "bc96-1", "nums": [24], "form": "單題", "img": "img/bc96-1-24.png", "source": "出處待查（古代笑話）", "author": "", "genre": "筆記小品", "types": ["人物情感", "文意推論"], "passage": "久雨屋漏，一夜數徙床，卒無乾處，妻兒交詬。公急呼匠者葺治，勞費良苦。工畢，天忽開霽，竟月晴朗。公日夕仰屋嘆曰：『命劣之人，才葺屋，便無雨，豈不白折了也！』（葺：音ㄑㄧˋ，修理）", "translation": "雨下了很久，屋子漏水，一夜搬了好幾次床，始終沒有乾的地方，妻子兒女輪番責罵。他急忙叫工匠來修理，花費了很多心力和錢財。修好後，天忽然放晴，整個月都晴朗無雨。他早晚望著屋頂嘆氣說：「命不好的人，才修好屋子，就不下雨了，豈不是白白損失了！」", "keywords": [{"w": "數", "m": "屢次"}, {"w": "徙", "m": "搬移"}, {"w": "卒", "m": "終究"}, {"w": "交詬", "m": "輪流責罵"}, {"w": "開霽", "m": "雨停天晴"}, {"w": "竟月", "m": "整整一個月"}, {"w": "白折", "m": "白白損失"}], "questions": [{"n": 24, "stem": "「久雨屋漏，一夜數徙床，卒無乾處，妻兒交詬。公急呼匠者葺治，勞費良苦。工畢，天忽開霽，竟月晴朗。公日夕仰屋嘆曰：『命劣之人，才葺屋，便無雨，豈不白折了也！』」下列何者最適合用來形容文中的主人翁？", "options": {"A": "目光短淺，缺乏遠慮", "B": "吝嗇成性，錙銖必較", "C": "偏執頑冥，不知變通", "D": "多此一舉，白費功夫"}, "answer": "A", "explain": "修屋是為了長久居住，以後一定還會下雨；主人翁卻因為修好後一個月沒下雨，就覺得錢白花了，只看眼前，所以是(A)目光短淺。(B)他肯急忙花大錢修屋，不算吝嗇；(C)他接受建議修屋，並非固執不變通；(D)修屋並不是白費，是主人翁自己誤以為白費。", "skill": "笑話題要找出人物「可笑的想法」（才葺屋便無雨，豈不白折），再判斷這種想法反映的性格缺點。"}], "difficulty": "中", "label": "96年第一次基測", "year": 96, "kind": "基測"}, {"id": "bc96-1-25", "exam": "bc96-1", "nums": [25], "form": "單題", "img": "img/bc96-1-25.png", "source": "王昌齡〈芙蓉樓送辛漸〉、無門慧開禪詩、李白〈越中覽古〉、高適〈塞上聽吹笛〉", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)洛陽親友如相問，一片冰心在玉壺　(B)春有百花秋有月，夏有涼風冬有雪　(C)宮女如花滿春殿，只今惟有鷓鴣飛　(D)借問梅花何處落，風吹一夜滿關山", "translation": "(A)洛陽的親友如果問起我，請告訴他們我的心像玉壺裡的冰一樣純潔。(B)春天有百花，秋天有明月，夏天有涼風，冬天有白雪（四季各有美好）。(C)當年如花的宮女擠滿春日的宮殿，如今只剩鷓鴣在這裡飛。(D)請問〈梅花落〉的笛聲飄到哪裡？一夜之間被風吹得布滿關山。", "keywords": [{"w": "懷古傷今", "m": "追念過去的繁華，感傷今日的衰落"}, {"w": "只今", "m": "如今"}, {"w": "冰心", "m": "純潔的心"}], "questions": [{"n": 25, "stem": "下列詩句，何者含有懷古傷今的情感？", "options": {"A": "洛陽親友如相問，一片冰心在玉壺", "B": "春有百花秋有月，夏有涼風冬有雪", "C": "宮女如花滿春殿，只今惟有鷓鴣飛", "D": "借問梅花何處落，風吹一夜滿關山"}, "answer": "C", "explain": "(C)上句寫昔日越王宮中宮女如花的繁華，下句寫「只今惟有鷓鴣飛」的荒涼，今昔對比，正是懷古傷今。(A)是送別時表明心志高潔；(B)是欣賞四季美好、隨遇而安；(D)是邊塞聽笛引起的思鄉之情。", "skill": "懷古傷今的辨認訊號：過去的繁華＋「只今／如今／唯有」引出的冷落景象，形成今昔對比。"}], "difficulty": "易", "label": "96年第一次基測", "year": 96, "kind": "基測"}, {"id": "bc96-1-30", "exam": "bc96-1", "nums": [30], "form": "單題", "img": "img/bc96-1-30.png", "source": "《論語‧里仁》", "author": "孔子", "genre": "經典語錄", "types": ["句意理解"], "passage": "君子欲訥於言，而敏於行。", "translation": "君子說話要謹慎遲緩，做事要勤快敏捷。", "keywords": [{"w": "訥", "m": "說話遲鈍、謹慎不輕易開口"}, {"w": "敏", "m": "勤勉、敏捷"}], "questions": [{"n": 30, "stem": "「君子欲訥於言，而敏於行。」這句話的意思與下列何者最接近？", "options": {"A": "沉默是金", "B": "言聽行從", "C": "三思而行", "D": "寡言力行"}, "answer": "D", "explain": "「訥於言」＝少說、謹慎說；「敏於行」＝努力去做，合起來就是(D)寡言力行。(A)只講少說話，漏了「行」；(B)是對別人言聽計從；(C)是行動前多考慮，沒有談說話。", "skill": "文言句兩半分別翻譯（言→寡言、行→力行），選項要兩部分都對應才是答案。"}], "difficulty": "易", "label": "96年第一次基測", "year": 96, "kind": "基測"}, {"id": "bc96-1-45", "exam": "bc96-1", "nums": [45, 46], "form": "題組", "img": "img/bc96-1-45.png", "source": "宋應星《天工開物‧舟》", "author": "宋應星", "genre": "說理議論", "types": ["文意推論", "字詞解釋"], "passage": "凡舟古名百千，今名亦百千。或以形名，或以量名，或以質名，不可殫述。遊海濱者得見洋船，居江湄者得見漕舫。若侷促山國之中，老死平原之地，所見者一葉扁舟、截流亂筏而已。（殫：音ㄉㄢ，盡；漕舫：運載米糧的船隻）", "translation": "船的名稱，古代有成百上千種，現在也有成百上千種。有的依形狀命名，有的依載重量命名，有的依材料命名，無法一一說盡。到海邊遊歷的人能看到航海的大船，住在江邊的人能看到運糧的漕船。如果侷限在山區，或一輩子住在平原，所看到的就只是小船和橫渡河流的簡陋竹筏而已。", "keywords": [{"w": "以形名", "m": "依照形狀命名"}, {"w": "量", "m": "載重量"}, {"w": "質", "m": "材質"}, {"w": "殫述", "m": "說盡"}, {"w": "江湄", "m": "江邊"}, {"w": "侷促", "m": "侷限、困在"}], "questions": [{"n": 45, "stem": "依據本文，下列何者無法確知與船隻的命名方法有關？", "options": {"A": "船隻形狀", "B": "承載重量", "C": "造船材料", "D": "年代先後"}, "answer": "D", "explain": "文中「或以形名，或以量名，或以質名」分別對應(A)形狀、(B)重量、(C)材料。「古名」「今名」只是說古今都有很多名稱，並沒有說依年代命名，所以(D)無法確知。", "skill": "把「或以……名」的排比逐一對應選項，「形、量、質」要譯成形狀、載重、材質。"}, {"n": 46, "stem": "根據本文的敘述，人所看到的船隻類型不同，主要是因為下列哪一個因素？", "options": {"A": "興趣嗜好各異", "B": "識見程度高低", "C": "所處區域有別", "D": "財富權勢多寡"}, "answer": "C", "explain": "文中說住海邊見洋船、住江邊見漕舫、住山區平原只見扁舟竹筏，差別在於居住地點，所以是(C)。(B)雖然有見識多寡的暗示，但文中直接的原因是所處地方不同。", "skill": "找文中造成差異的條件詞（遊海濱者、居江湄者、侷促山國），歸納出共同因素。"}], "difficulty": "易", "label": "96年第一次基測", "year": 96, "kind": "基測"}, {"id": "bc96-1-47", "exam": "bc96-1", "nums": [47, 48], "form": "題組", "img": "img/bc96-1-47.png", "source": "佚名", "author": "佚名", "genre": "山水遊記", "types": ["字詞解釋", "文意推論", "寫作手法"], "passage": "匹練抹林，輕綃蔽日。籠樓臺而隱隱，鎖洞壑以重重。潭影難窺，花枝半掩。樹若增密，山若增深，景若增幽，路若增遠，勝概之一助也。（綃：音ㄒㄧㄠ，生絲；勝概：美景）", "translation": "（霧）像一匹白絹塗抹在樹林上，像輕薄的生絲遮住太陽。它籠罩樓臺，使樓臺若隱若現；它把山洞山谷一層層鎖住。潭水的倒影難以看清，花枝也被遮去一半。樹好像變得更茂密，山好像變得更深，景色好像更幽靜，道路好像更遙遠，這是美景的一種助力啊。", "keywords": [{"w": "匹練", "m": "一匹白絹"}, {"w": "抹", "m": "塗抹、覆蓋"}, {"w": "籠", "m": "籠罩（動詞）"}, {"w": "鎖", "m": "封住"}, {"w": "窺", "m": "看"}, {"w": "若", "m": "好像"}], "questions": [{"n": 47, "stem": "下列文句「」中的字，何者作動詞使用？", "options": {"A": "匹「練」抹林", "B": "「籠」樓臺而隱隱", "C": "潭影「難」窺", "D": "勝概之一「助」"}, "answer": "B", "explain": "(B)「籠」是籠罩，後面接受詞「樓臺」，是動詞。(A)「練」是白絹，名詞；(C)「難」修飾「窺」，是副詞（難以）；(D)「一助」的「助」是「助力」，名詞。", "skill": "判斷詞性看位置：後面直接接受詞（籠＋樓臺）的通常是動詞；在「一」「之」後面的多是名詞。"}, {"n": 48, "stem": "根據本文所述，使「樹若增密，山若增深，景若增幽，路若增遠」的事物是下列何者？", "options": {"A": "林", "B": "泉", "C": "霧", "D": "山"}, "answer": "C", "explain": "能像白絹、薄紗一樣覆蓋樹林、遮住太陽、籠罩樓臺、鎖住山谷，讓潭影難見、花枝半掩的，是霧。霧使一切朦朧，所以樹、山、景、路都顯得更密、更深、更幽、更遠，選(C)。(A)(D)林、山是被霧遮蔽的對象；(B)文中沒提到泉。", "skill": "全文沒說出主角時，從「被它影響的東西」與「它的樣子」（像練、像綃、能籠能鎖）反推描寫對象。"}], "difficulty": "中", "label": "96年第一次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-1", "exam": "bc96-2", "nums": [1], "form": "單題", "img": "img/bc96-2-1.png", "source": "張潮《幽夢影》", "author": "張潮", "genre": "筆記小品", "types": ["句意理解", "主旨寓意"], "passage": "古今至文，皆血淚所成。", "translation": "古往今來最好的文章，都是用血和淚（真實深刻的生命情感）寫成的。", "keywords": [{"w": "至文", "m": "最好的文章"}, {"w": "血淚", "m": "比喻真摯深切的情感與生命經歷"}], "questions": [{"n": 1, "stem": "張潮《幽夢影》：「古今至文，皆血淚所成。」這句話的涵義與下列何者最接近？", "options": {"A": "愈能賺人熱淚愈是好文章", "B": "讀者想像空間愈大，作者愈成功", "C": "偉大的作品總是根源於真摯的情感", "D": "好文章的每個字都像利箭般直射讀者心坎"}, "answer": "C", "explain": "「血淚」是比喻作者付出的真情與生命體驗，意思是好文章源自作者真摯的情感，選(C)。(A)把「血淚」誤解為讀者流淚，重點錯置；(B)講讀者的想像空間；(D)講文字對讀者的感染力，都不是「文章怎麼產生」的重點。", "skill": "判斷「血淚」是誰的：句子說的是文章由什麼「所成」，主體是作者，不是讀者。"}], "difficulty": "易", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-2", "exam": "bc96-2", "nums": [2], "form": "單題", "img": "img/bc96-2-2.png", "source": "明代笑話（出處待查）", "author": "", "genre": "筆記小品", "types": ["人物情感", "文意推論"], "passage": "有自負棋名者，與人角，連負三局。他日，人問之曰：『前與某人較棋幾局？』曰：『三局。』又問：『勝負如何？』曰：『第一局我不曾贏，第二局他不曾輸，第三局我要和，他不肯罷了。』（角：音ㄐㄩㄝˊ，較量、比賽之意）", "translation": "有個自以為棋藝很有名的人，和別人比賽下棋，一連輸了三局。過幾天，有人問他：「上次和某人下了幾局？」他說：「三局。」又問：「勝負怎麼樣？」他說：「第一局我沒有贏，第二局他沒有輸，第三局我想要和局，他不肯就是了。」", "keywords": [{"w": "自負", "m": "自以為了不起"}, {"w": "角", "m": "較量"}, {"w": "負", "m": "輸"}, {"w": "和", "m": "平手、和局"}], "questions": [{"n": 2, "stem": "「有自負棋名者，與人角，連負三局。他日，人問之曰：『前與某人較棋幾局？』曰：『三局。』又問：『勝負如何？』曰：『第一局我不曾贏，第二局他不曾輸，第三局我要和，他不肯罷了。』」故事中的主角最可能犯了什麼毛病？", "options": {"A": "為顧顏面，不肯認輸", "B": "馬虎隨便，苟且草率", "C": "推諉過失，怨天尤人", "D": "巧言令色，信口開河"}, "answer": "A", "explain": "他其實連輸三局，卻換個說法：「我不曾贏」「他不曾輸」「我要和他不肯」，每一句都等於「我輸了」，只是不肯直說，可見是愛面子不肯認輸，選(A)。(B)文中沒有做事草率；(C)他沒有把錯推給別人或抱怨；(D)他說的其實都是事實，不是胡說八道，也不是討好別人。", "skill": "笑話題要把人物的話「翻成真相」（三句都是輸），再看他為什麼要繞圈子說，就是他的毛病。"}], "difficulty": "易", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-3", "exam": "bc96-2", "nums": [3], "form": "單題", "img": "img/bc96-2-3.png", "source": "《四十二章經》", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "惡人害賢者，猶仰天而唾，唾不至天，還從己墮；逆風揚塵，塵不至彼，還坌己身。（坌：音ㄅㄣˋ，塵土灑落在物體上）", "translation": "壞人陷害賢人，就像仰著頭向天吐口水，口水吐不到天上，反而從自己頭上掉下來；又像逆著風揚起塵土，塵土飛不到對方身上，反而落滿自己全身。", "keywords": [{"w": "猶", "m": "好像"}, {"w": "唾", "m": "吐口水"}, {"w": "還", "m": "反而、回過頭"}, {"w": "墮", "m": "落下"}, {"w": "彼", "m": "對方"}], "questions": [{"n": 3, "stem": "「惡人害賢者，猶仰天而唾，唾不至天，還從己墮；逆風揚塵，塵不至彼，還坌己身。」下列何者最適合用來形容文中的「惡人」？", "options": {"A": "成事不足，敗事有餘", "B": "殺雞儆猴，適得其反", "C": "害人反害己，咎由自取", "D": "自不量力，必遭他人唾棄"}, "answer": "C", "explain": "兩個比喻都在說：想傷害別人，結果傷到自己（唾還從己墮、塵還坌己身），正是(C)害人反害己。(A)指只會壞事；(B)殺雞儆猴是懲罰一人來警告眾人；(D)「唾棄」是表面字面相似的陷阱，文中的口水是落回自己身上，不是被別人唾棄。", "skill": "抓比喻的共同結果（還從己墮、還坌己身＝回到自己身上），不要被選項中相同的字（唾）誤導。"}], "difficulty": "易", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-4", "exam": "bc96-2", "nums": [4], "form": "單題", "img": "img/bc96-2-4.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["文意推論", "句意理解"], "passage": "治國如治病，善治病者，必醫其受病之處；善救弊者，必尋其起弊之源。弊除利興則國治。", "translation": "治理國家就像治病：善於治病的人，一定醫治生病的部位；善於革除弊端的人，一定找出弊端產生的根源。弊端除去、好處興起，國家就治理好了。", "keywords": [{"w": "善……者", "m": "擅長……的人"}, {"w": "弊", "m": "弊病、壞處"}, {"w": "救", "m": "補救、革除"}, {"w": "治", "m": "治理好、安定"}], "questions": [{"n": 4, "stem": "智恩無意間得到了幾片竹簡，但因中間連結的繩索斷裂而不知文句的先後次序：「治國如治病　甲、必尋其起弊之源　乙、善治病者　丙、善救弊者　丁、必醫其受病之處　弊除利興則國治」依照文意，下列何者為正確的順序？", "options": {"A": "乙丁丙甲", "B": "丙甲丁乙", "C": "乙丙丁甲", "D": "丙丁甲乙"}, "answer": "A", "explain": "開頭「治國如治病」先講「病」，再講「國（弊）」：乙「善治病者」配丁「必醫其受病之處」（病對病）；丙「善救弊者」配甲「必尋其起弊之源」（弊對弊），最後接「弊除利興則國治」。順序乙丁丙甲，選(A)。", "skill": "排序先把主語和述語配對（同一關鍵字：病—病、弊—弊），再依「先喻體後本體」與結尾句銜接排定先後。"}], "difficulty": "中", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-6", "exam": "bc96-2", "nums": [6], "form": "單題", "img": "img/bc96-2-6.png", "source": "韋應物〈滁州西澗〉等（其餘出處待查）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "(A)萬里飄搖空此身，十年征戰老胡塵。赤心報國無片賞，白首還家有幾人　(B)獨憐幽草澗邊生，上有黃鸝深樹鳴。春潮帶雨晚來急，野渡無人舟自橫　(C)五更初起覺風寒，香炷燒來夜已殘。欲卷珠簾驚雪滿，自將紅燭上樓看　(D)漢家宮殿含雲煙，兩宮十里相連延。晨霞出沒弄丹闕，春雨依微自甘泉", "translation": "(A)漂泊萬里只剩孤身，十年征戰在邊塞中老去；一片赤心報國卻沒得到半點獎賞，白髮回家的又有幾人？(B)我特別喜愛山澗邊生長的幽草，上方有黃鸝在深樹中啼叫；春潮夾著雨水傍晚來得急，荒野渡口沒有人，小船自己橫在水上。(C)五更起床覺得風寒，香已燒完、夜將盡；想捲起珠簾，驚見滿地白雪，便自己拿著紅燭上樓觀看。(D)漢朝宮殿籠罩在雲煙中，兩座宮殿綿延十里；晨霞在紅色宮門間時隱時現，春雨細細從甘泉宮飄來。", "keywords": [{"w": "胡塵", "m": "邊地的戰塵"}, {"w": "獨憐", "m": "特別喜愛"}, {"w": "野渡", "m": "荒野的渡口"}, {"w": "丹闕", "m": "紅色的宮門，指宮殿"}], "questions": [{"n": 6, "stem": "詩可以抒情、可以敘事、可以寫景，下列哪一組詩句是以自然景物為主要描寫對象？", "options": {"A": "萬里飄搖空此身，十年征戰老胡塵。赤心報國無片賞，白首還家有幾人", "B": "獨憐幽草澗邊生，上有黃鸝深樹鳴。春潮帶雨晚來急，野渡無人舟自橫", "C": "五更初起覺風寒，香炷燒來夜已殘。欲卷珠簾驚雪滿，自將紅燭上樓看", "D": "漢家宮殿含雲煙，兩宮十里相連延。晨霞出沒弄丹闕，春雨依微自甘泉"}, "answer": "B", "explain": "(B)幽草、黃鸝、深樹、春潮、雨、野渡、小舟，全是自然景物，以寫景為主。(A)寫征人報國無賞的感慨，是抒情敘事；(C)寫人五更起床、上樓賞雪的過程，以人的動作為主；(D)寫的是宮殿建築，屬人為景物。", "skill": "把詩中名詞分類：自然（草木鳥獸山水天氣）vs. 人事（征戰、宮殿、人的動作），看哪一類佔主要篇幅。"}], "difficulty": "中", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-11", "exam": "bc96-2", "nums": [11], "form": "單題", "img": "img/bc96-2-11.png", "source": "白居易〈楊柳枝詞〉", "author": "白居易", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "葉含濃露如啼眼，枝嫋輕風似舞腰。（嫋：音ㄋㄧㄠˇ，擺動）", "translation": "柳葉含著濃重的露水，像哭泣時含淚的眼睛；柳枝在輕風中搖擺，像舞者擺動的腰肢。", "keywords": [{"w": "啼眼", "m": "哭泣的眼睛"}, {"w": "嫋", "m": "擺動"}, {"w": "舞腰", "m": "跳舞時柔軟的腰"}], "questions": [{"n": 11, "stem": "「葉含濃露如啼眼，枝嫋輕風似舞腰」這兩句詩在描寫楊柳。下列詞語，何者與「枝嫋輕風似舞腰」所刻畫的柳姿最相近？", "options": {"A": "枝葉扶疏", "B": "婀娜纖柔", "C": "亭亭玉立", "D": "落絮紛飛"}, "answer": "B", "explain": "柳枝在風中擺動，比喻成舞者的腰，強調柔軟細長、姿態優美，就是(B)婀娜纖柔。(A)扶疏是枝葉茂密分披；(C)亭亭玉立是挺直秀美，不是擺動之姿；(D)落絮是柳花飄落，不是枝條。", "skill": "從比喻的喻體（舞腰）抓特徵：柔、細、搖擺，再找最貼近的形容詞語。"}], "difficulty": "易", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-15", "exam": "bc96-2", "nums": [15], "form": "單題", "img": "img/bc96-2-15.png", "source": "選項為文言格言（(C)化用《後漢書‧馬援傳》）", "author": "", "genre": "經典語錄", "types": ["主旨寓意", "比較閱讀"], "passage": "(A)囚鳥不忘飛，繫馬常念馳　(B)自敬則人敬之，自慢則人慢之　(C)學者立身，窮當益堅，老當益壯　(D)立志堅者，則邪說不能移，異端不能惑", "translation": "(A)被關的鳥不忘飛翔，被拴的馬常想奔馳。(B)自己尊重自己，別人就尊重你；自己輕慢自己，別人也輕慢你。(C)讀書人立身處世，越窮困越要堅定，越老越要雄壯。(D)立志堅定的人，邪僻的言論不能動搖他，不正的學說不能迷惑他。", "keywords": [{"w": "慢", "m": "輕視、怠慢"}, {"w": "窮", "m": "困頓不得志"}, {"w": "益", "m": "更加"}, {"w": "移", "m": "動搖、改變"}, {"w": "異端", "m": "不正當的學說"}], "questions": [{"n": 15, "stem": "潭水羨慕地問山泉：「為什麼你永遠那麼明亮，那麼清澈？」山泉笑著說：「因為我總是不停地朝前走，不貪圖一時的熱鬧與歡樂，不受輕浮的柳條糾纏，也不受嬌媚的小花誘惑。我只記住奔向水田，奔向寨子，奔向人們需要我的地方。」這則故事的寓意與下列何者最接近？", "options": {"A": "囚鳥不忘飛，繫馬常念馳", "B": "自敬則人敬之，自慢則人慢之", "C": "學者立身，窮當益堅，老當益壯", "D": "立志堅者，則邪說不能移，異端不能惑"}, "answer": "D", "explain": "山泉清澈，是因為目標明確（奔向需要我的地方），不受柳條、小花的糾纏誘惑，也就是志向堅定、不被外物動搖，與(D)相同。(A)講受困者不忘理想；(B)講自重才受人尊重；(C)講困境與年老時更要堅強，都沒有「不受誘惑」的重點。", "skill": "先把寓言的象徵翻譯出來（柳條、小花＝誘惑；奔向需要之處＝志向），再找文言選項中「志堅＋不被動搖」的對應。"}], "difficulty": "中", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-26", "exam": "bc96-2", "nums": [26], "form": "單題", "img": "img/bc96-2-26.png", "source": "選項為對聯（出處待查）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "(A)青春一去不復來，事業一縱永無成　(B)兩字聽人呼不肖，一生誤我是聰明　(C)知足使窮人變富，不知足富人變窮　(D)開口能談天下事，讀書要讀古人心", "translation": "(A)青春一旦過去就不再回來，事業一旦放任就永遠不會成功。(B)常聽別人叫我「不肖」兩個字，耽誤我一生的正是「聰明」。(C)知足能讓窮人變富有，不知足會讓富人變貧窮。(D)開口能談論天下大事，讀書要讀懂古人的用心。", "keywords": [{"w": "倒裝", "m": "改變主語、述語、賓語的正常順序"}, {"w": "不肖", "m": "不成材、不賢"}, {"w": "縱", "m": "放任"}], "questions": [{"n": 26, "stem": "平常說話用語，在主語、述語、賓語之間，有一定的順序，我們稱之為正常語序。下列何者改變了正常語序，形成倒裝句型？", "options": {"A": "青春一去不復來，事業一縱永無成", "B": "兩字聽人呼不肖，一生誤我是聰明", "C": "知足使窮人變富，不知足富人變窮", "D": "開口能談天下事，讀書要讀古人心"}, "answer": "B", "explain": "(B)「一生誤我是聰明」的正常語序是「聰明誤我一生」，主語「聰明」被放到句末，形成倒裝。(A)(C)(D)都是主語在前、述語賓語在後的正常順序。", "skill": "把句子還原成「誰＋做什麼＋對誰」，若主語或賓語被移到別處才通順，就是倒裝。"}], "difficulty": "中", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-29", "exam": "bc96-2", "nums": [29], "form": "單題", "img": "img/bc96-2-29.png", "source": "溫庭筠〈湖陰詞〉等（其餘出處待查）", "author": "", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "(A)白玉闌干金作柱，樓上朝朝學歌舞　(B)吳波不動楚山晚，花壓闌干春晝長　(C)若傍闌干千里望，北風驅馬雨蕭蕭　(D)今日片帆城下去，秋風回首淚闌干", "translation": "(A)白玉做的欄杆、黃金做的柱子，人們天天在樓上學習歌舞。(B)吳地的水波平靜，楚山已近黃昏，花枝壓在欄杆上，春日白晝顯得漫長。(C)如果靠著欄杆向千里外眺望，只見北風驅趕著馬，雨聲蕭蕭。(D)今天一片帆船從城下離去，秋風中回頭一望，淚水縱橫。", "keywords": [{"w": "闌干①", "m": "欄杆、柵欄（名詞）"}, {"w": "闌干②", "m": "縱橫散亂的樣子，常形容眼淚、星斗"}, {"w": "傍", "m": "靠著"}], "questions": [{"n": 29, "stem": "「闌干」一詞，有時可以解釋成「縱橫散亂的樣子」，有時可以解釋成「柵欄」。下列詩句中的「闌干」，何者當作「縱橫散亂的樣子」解釋？", "options": {"A": "白玉「闌干」金作柱，樓上朝朝學歌舞", "B": "吳波不動楚山晚，花壓「闌干」春晝長", "C": "若傍「闌干」千里望，北風驅馬雨蕭蕭", "D": "今日片帆城下去，秋風回首淚「闌干」"}, "answer": "D", "explain": "(D)「淚闌干」形容淚水縱橫流下，是「縱橫散亂」義。(A)白玉闌干與金柱並列，是建築的欄杆；(B)花枝壓在欄杆上；(C)「傍闌干」是倚靠欄杆，都是「柵欄」義。", "skill": "一詞多義看搭配：能被「倚、傍、壓」、能用「白玉」做的是實物欄杆；接在「淚」後面描寫樣子的是形容詞。"}], "difficulty": "中", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-41", "exam": "bc96-2", "nums": [41, 42], "form": "題組", "img": "img/bc96-2-41.png", "source": "《東坡詩注》（改寫）", "author": "", "genre": "寓言故事", "types": ["字詞解釋", "主旨寓意"], "passage": "有一貧士，家惟一甕，夜則守之以寢。一夕，心自惟念：苟得富貴，當以錢若干，營田宅，蓄聲妓，而高車大蓋，無不備置。往來於懷，不覺歡適起舞，誤破其甕。（蓋：車的頂蓋）", "translation": "有一個窮書生，家裡只有一個甕，晚上就守著它睡覺。有一天晚上，他心裡暗自想著：如果能得到富貴，就要用若干錢買田地蓋房子，養歌女舞妓，高大的車子、華麗的車蓋，全都準備齊全。這些念頭在心裡翻來覆去，不知不覺高興得手舞足蹈，結果不小心打破了那唯一的甕。", "keywords": [{"w": "惟", "m": "只（家惟一甕）；思考（心自惟念）"}, {"w": "以", "m": "而、來（守之以寢）；用（以錢若干）"}, {"w": "苟", "m": "如果"}, {"w": "營", "m": "經營、建造"}, {"w": "懷", "m": "心中（名詞）"}, {"w": "適", "m": "舒服、自得"}], "questions": [{"n": 41, "stem": "下列字詞解釋的說明，何者正確？", "options": {"A": "「家惟一甕」、「心自惟念」兩句中的「惟」字，意思相同", "B": "「守之以寢」、「以錢若干」兩句中的「以」字，意思相同", "C": "「往來於懷」的「懷」字，在此當動詞用，是「思念」的意思", "D": "「不覺歡適起舞」的「適」字，在此是「舒服、自得」的意思"}, "answer": "D", "explain": "(D)「歡適」是心中歡喜舒暢，「適」為舒服、自得，正確。(A)「家惟一甕」的惟是「只」；「心自惟念」的惟是「思考」，不同。(B)「守之以寢」的以是連接詞「而」；「以錢若干」的以是「用」，不同。(C)「往來於懷」是念頭在心中來回，「懷」是名詞「心中」，不是動詞。", "skill": "同字異義題要把字放回句子翻譯，再判斷詞性：介詞「於」後面接的多半是名詞。"}, {"n": 42, "stem": "下列哪個詞語最適合用來形容故事中貧士的下場？", "options": {"A": "碩果僅存", "B": "否極泰來", "C": "樂極生悲", "D": "玉石俱焚"}, "answer": "C", "explain": "貧士想像富貴「歡適起舞」，高興過頭卻打破了唯一的甕，正是(C)樂極生悲。(A)碩果僅存是僅剩的珍貴之物，他的甕已破；(B)否極泰來是壞運到底轉好，方向相反；(D)玉石俱焚是好壞一起毀滅，與故事不合。", "skill": "看情節的轉折方向：由「樂」轉「悲」，再找成語中同樣方向的。"}], "difficulty": "中", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc96-2-43", "exam": "bc96-2", "nums": [43, 44], "form": "題組", "img": "img/bc96-2-43.png", "source": "《西京雜記‧婁敬不易旃衣》（改寫）", "author": "葛洪（舊題劉歆）", "genre": "史傳人物", "types": ["人物情感", "字詞解釋"], "passage": "婁敬始因虞將軍請見高祖，衣旃衣，披羊裘。虞將軍脫其身上衣以衣之。敬曰：「敬本衣帛，則衣帛見；敬本衣旃，則衣旃見。今捨旃褐，假鮮華，是矯常也。」不敢脫羊裘，而衣旃衣以見高祖。（旃衣：旃，音ㄓㄢ，粗毛織的衣服；矯常：掩飾本來面貌）", "translation": "婁敬起初經由虞將軍引薦去拜見漢高祖，他穿著粗毛衣，披著羊皮襖。虞將軍脫下自己身上的衣服要給他穿。婁敬說：「我本來穿絲綢，就穿絲綢去見；我本來穿粗毛衣，就穿粗毛衣去見。現在拋開粗毛衣，借穿鮮豔華麗的衣服，這是掩飾本來面貌。」他不肯脫下羊皮襖，就穿著粗毛衣去見高祖。", "keywords": [{"w": "因", "m": "經由、透過"}, {"w": "衣（ㄧˋ）", "m": "穿（動詞）"}, {"w": "衣（ㄧ）", "m": "衣服（名詞）"}, {"w": "帛", "m": "絲織品"}, {"w": "假", "m": "借"}, {"w": "易", "m": "更換"}], "questions": [{"n": 43, "stem": "根據本文，婁敬為什麼不換穿虞將軍的衣服？", "options": {"A": "尊卑有別，不敢逾矩", "B": "自視非凡，不識抬舉", "C": "質性真率，不喜造作", "D": "特立獨行，不修邊幅"}, "answer": "C", "explain": "婁敬說本來穿什麼就穿什麼去見，換上華服是「矯常」（掩飾本來面貌），可見他個性真誠率直，不願矯飾，選(C)。(A)他不是因為身分不敢穿；(B)他沒有自大，也不是不懂好意；(D)他堅持的是不造假，不是故意標新立異或邋遢。", "skill": "直接引用人物說明理由的話（是矯常也），再轉換成性格詞語。"}, {"n": 44, "stem": "「婁敬不易旃衣」的「衣」字作名詞用，下列文句「」中的「衣」字，何者也是名詞？", "options": {"A": "「衣」旃衣，披羊裘", "B": "虞將軍脫其身上「衣」以衣之", "C": "敬本「衣」帛，則衣帛見", "D": "敬本衣旃，則「衣」旃見"}, "answer": "B", "explain": "(B)「脫其身上衣」：脫下身上的衣服，「衣」被「脫」，是名詞。(A)「衣旃衣」第一個衣是「穿」；(C)「本衣帛」是本來穿絲綢；(D)「衣旃見」是穿粗毛衣去見，都是動詞。", "skill": "「衣」後面若直接接衣料或衣物（衣旃、衣帛），通常是動詞「穿」；若前面有動詞或修飾語（脫……衣、身上衣），就是名詞。"}], "difficulty": "中", "label": "96年第二次基測", "year": 96, "kind": "基測"}, {"id": "bc97-1-10", "exam": "bc97-1", "nums": [10], "form": "單題", "img": "img/bc97-1-10.png", "source": "沈復〈兒時記趣〉、劉禹錫〈陋室銘〉、〈木蘭詩〉；(C)出處待查", "author": "", "genre": "古典詩詞曲", "types": ["寫作手法", "句意理解"], "passage": "(A)張目對日，明察秋毫　(B)斯是陋室，惟吾德馨　(C)行行鄙夫志，悠悠故難量　(D)朔氣傳金柝，寒光照鐵衣", "translation": "(A)睜大眼睛對著太陽，能看清極細微的東西。(B)這雖是簡陋的屋子，只因我的品德美好而散發芬芳。(C)一般淺陋之人的志向，紛紛擾擾本來就難以衡量。(D)北方的寒氣傳來打更的刁斗聲，清冷的月光照在戰士的鐵甲上。", "keywords": [{"w": "對偶", "m": "上下兩句字數相等、詞性相對、句法相同"}, {"w": "秋毫", "m": "秋天鳥獸新長的細毛，比喻極細微的東西"}, {"w": "馨", "m": "香氣，比喻美德"}, {"w": "金柝", "m": "軍中打更用的刁斗"}], "questions": [{"n": 10, "stem": "下列文句，何者屬於對偶句？", "options": {"A": "張目對日，明察秋毫", "B": "斯是陋室，惟吾德馨", "C": "行行鄙夫志，悠悠故難量", "D": "朔氣傳金柝，寒光照鐵衣"}, "answer": "D", "explain": "(D)「朔氣／寒光」（名詞）、「傳／照」（動詞）、「金柝／鐵衣」（名詞），上下句字數相同、詞性一一相對，是對偶。(A)「張目對日」是動作，「明察秋毫」是結果，結構不同；(B)「斯是陋室」是判斷句，「惟吾德馨」是主謂句，不相對；(C)「行行鄙夫志」與「悠悠故難量」詞性、結構都不對稱。", "skill": "判斷對偶：把上下句逐字對齊，檢查每個位置的詞性是否相同（名對名、動對動），結構一致才算。"}], "difficulty": "中", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-16", "exam": "bc97-1", "nums": [16], "form": "單題", "img": "img/bc97-1-16.png", "source": "文言句式（選項為淺近文言）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "(A)名利之於小人，一如道德之於君子　(B)楚敗於漢，楚王項羽自刎身亡　(C)吾師學問淵博，尤精於醫學　(D)贈人以言，勝於黃金美玉", "translation": "(A)名利對小人的意義，就像道德對君子一樣。(B)楚國被漢打敗，楚王項羽自殺身亡。(C)我的老師學問淵博，尤其精通醫學。(D)送人有益的話，勝過送黃金美玉。", "keywords": [{"w": "於（被動）", "m": "被"}, {"w": "於（對象）", "m": "對於"}, {"w": "於（範圍）", "m": "在……方面"}, {"w": "於（比較）", "m": "比"}], "questions": [{"n": 16, "stem": "下列文句中的「於」字，何者表示被動的意思？", "options": {"A": "名利之於小人，一如道德之於君子", "B": "楚敗於漢，楚王項羽自刎身亡", "C": "吾師學問淵博，尤精於醫學", "D": "贈人以言，勝於黃金美玉"}, "answer": "B", "explain": "(B)「楚敗於漢」＝楚被漢打敗，「於」引出動作的發出者，表被動。(A)「之於」是「對於」；(C)「精於醫學」是「在醫學方面」；(D)「勝於」是「比……更好」，表比較。", "skill": "「動詞＋於＋某人」若可改成「被某人＋動詞」而意思不變，「於」就是被動。"}], "difficulty": "中", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-17", "exam": "bc97-1", "nums": [17], "form": "單題", "img": "img/bc97-1-17.png", "source": "《晏子春秋‧內篇雜下》", "author": "", "genre": "史傳人物", "types": ["典故出處", "文意推論"], "passage": "橘生淮南則為橘，生於淮北則為枳，葉徒相似，其實味不同。所以然者何？水土異也。", "translation": "橘樹生長在淮河以南就是橘，生長在淮河以北就變成枳，只有葉子相似，果實的味道卻不同。為什麼會這樣？是因為水土不同啊。", "keywords": [{"w": "枳", "m": "一種果實酸苦的植物"}, {"w": "徒", "m": "只、僅"}, {"w": "其實", "m": "它的果實"}, {"w": "所以然者何", "m": "這樣的原因是什麼"}], "questions": [{"n": 17, "stem": "「橘生淮南則為橘，生於淮北則為枳，葉徒相似，其實味不同。所以然者何？水土異也。」這是成語「橘化為枳」的典故由來。下列事例，何者最適合用這個成語來形容？", "options": {"A": "臺灣如遇颱風常有土石流，為減少土石流的發生，平日應盡力做好水土保持", "B": "做任何事情都要適當地拿捏分寸、權衡利弊，才不致於破壞原本良善的立意", "C": "中外民情不同，在西方某些實施成功的制度，在國內卻未必能達到相同的效果", "D": "臺灣南北所產的水果滋味各擅勝場，就如粽子南北製作方式不同，然俱為美味"}, "answer": "C", "explain": "「橘化為枳」比喻同一樣東西換了環境，性質或效果就改變（變差）。(C)制度在西方成功，搬到國內因民情不同而效果不同，最貼切。(A)只是字面上的「水土」；(B)講拿捏分寸；(D)南北都美味，沒有「變質」的意思。", "skill": "先抽出典故的核心（同一物＋環境改變→結果改變），再找選項中同時具備「同一物」「換環境」「效果變差」三要素的。"}], "difficulty": "易", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-21", "exam": "bc97-1", "nums": [21], "form": "單題", "img": "img/bc97-1-21.png", "source": "杜甫〈丹青引〉、〈哀江頭〉、〈登高〉、〈蠶穀行〉", "author": "杜甫", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)良相頭上進賢冠，猛將腰間大羽箭　(B)翻身向天仰射雲，一箭正墜雙飛翼　(C)萬里悲秋常作客，百年多病獨登臺　(D)焉得鑄甲作農器，一寸荒田牛得耕", "translation": "(A)賢良宰相頭戴進賢冠，勇猛將軍腰插大羽箭（描寫功臣畫像）。(B)翻身仰天射向雲中，一箭射落兩隻並飛的鳥。(C)遠離家鄉萬里，在悲涼的秋天長年作客；一生多病，獨自登上高臺。(D)怎樣才能把鎧甲熔鑄成農具，讓每一寸荒廢的田地都有牛去耕種？", "keywords": [{"w": "焉得", "m": "怎麼能夠"}, {"w": "鑄甲作農器", "m": "把盔甲熔掉改造成農具，表示不再打仗"}, {"w": "作客", "m": "客居他鄉"}], "questions": [{"n": 21, "stem": "杜甫歷經安史之亂，對戰爭多有感觸。下列詩句，何者最能反映出他期待戰爭停止的心情？", "options": {"A": "良相頭上進賢冠，猛將腰間大羽箭", "B": "翻身向天仰射雲，一箭正墜雙飛翼", "C": "萬里悲秋常作客，百年多病獨登臺", "D": "焉得鑄甲作農器，一寸荒田牛得耕"}, "answer": "D", "explain": "(D)「焉得」表示盼望；把盔甲改鑄成農具、讓荒田重新耕種，就是希望戰爭結束、恢復和平生活。(A)描寫文臣武將的畫像；(B)描寫射獵的高超技藝；(C)抒發漂泊多病的悲哀，沒有直接期盼停戰。", "skill": "找表達願望的字眼（焉得、安得、何時），再看願望的內容是否與「止戰」有關（甲→農器）。"}], "difficulty": "易", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-22", "exam": "bc97-1", "nums": [22], "form": "單題", "img": "img/bc97-1-22.png", "source": "古代笑話（出處待查，或出《笑林廣記》）", "author": "", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "一秀才買柴，曰：「荷薪者過來。」賣柴者因「過來」二字明白，擔到面前。問曰：「其價幾何？」因「價」字明白，說了價錢。秀才曰：「外實而內虛，煙多而焰少，請損之。」賣柴者不知說啥，荷著去了。後來這秀才做了官，下鄉，問父老曰：「近年黎庶何如？」父老曰：「今年梨樹好，只是蟲吃了些。」（黎庶：人民）", "translation": "有個秀才買柴，說：「挑柴的過來。」賣柴的人只聽懂「過來」兩個字，就挑到他面前。秀才問：「它的價錢多少？」賣柴的聽懂「價」字，說了價錢。秀才說：「你的柴外面乾實、裡面空虛，燒起來煙多火少，請減價吧。」賣柴的聽不懂他在說什麼，挑著柴走了。後來這秀才做了官，到鄉下問老人家：「近年百姓過得怎樣？」老人說：「今年梨樹長得好，只是被蟲吃了一些。」", "keywords": [{"w": "荷薪者", "m": "挑柴的人"}, {"w": "幾何", "m": "多少"}, {"w": "損", "m": "減少"}, {"w": "黎庶", "m": "百姓（老人誤聽成「梨樹」）"}], "questions": [{"n": 22, "stem": "一秀才買柴，曰：「荷薪者過來。」……後來這秀才做了官，下鄉，問父老曰：「近年黎庶何如？」父老曰：「今年梨樹好，只是蟲吃了些。」根據這則故事，下列敘述何者正確？", "options": {"A": "秀才批評柴質差，賣柴者悻然而去", "B": "秀才說話咬文嚼字，一般人聽不懂", "C": "秀才體弱無法負重，想少買一些柴", "D": "秀才為官關心百姓，但父老不領情"}, "answer": "B", "explain": "賣柴者只聽懂「過來」「價」，後面「外實而內虛……請損之」完全聽不懂；父老把「黎庶」聽成「梨樹」，可見秀才說話太文謅謅，一般人聽不懂，選(B)。(A)賣柴者是「不知說啥」才走，不是生氣；(C)「請損之」是要求減價，不是少買；(D)父老是誤聽，不是不領情。", "skill": "笑話的笑點常在「誤會」：找出別人聽錯／聽不懂的地方（黎庶→梨樹），推出原因。"}], "difficulty": "易", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-23", "exam": "bc97-1", "nums": [23], "form": "單題", "img": "img/bc97-1-23.png", "source": "《孟子‧盡心上》、《漢書‧疏廣傳》、《論語‧里仁》、《荀子‧榮辱》", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "(A)君子窮則獨善其身，達則兼善天下　(B)賢者多財則損其志，愚者多財則益其過　(C)富與貴，是人之所欲也，不以其道，得之不處也　(D)先義後利者榮，先利後義者辱；榮者常通，辱者常窮", "translation": "(A)君子不得志時就修養好自己，得志時就讓天下人都受益。(B)賢能的人錢多了會削弱志向，愚笨的人錢多了會增加過錯。(C)富有和尊貴是人人想要的，但不用正當方法得到，就不接受。(D)先講道義後講利益的人光榮，先講利益後講道義的人受辱；光榮的人常常順利，受辱的人常常困窘。", "keywords": [{"w": "窮／達", "m": "不得志／得志"}, {"w": "其道", "m": "正當的方法"}, {"w": "處", "m": "接受、安處"}], "questions": [{"n": 23, "stem": "「計程車司機小王，將客人不慎遺留在車上的現金一百萬元送至警察局，留待失主領回。」小王這種行為最符合下列哪一句話的精神？", "options": {"A": "君子窮則獨善其身，達則兼善天下", "B": "賢者多財則損其志，愚者多財則益其過", "C": "富與貴，是人之所欲也，不以其道，得之不處也", "D": "先義後利者榮，先利後義者辱；榮者常通，辱者常窮"}, "answer": "C", "explain": "小王面對一百萬元不據為己有，正是「錢雖人人想要，但不是正當得來的就不接受」，與(C)相符。(A)講窮達時的處世態度；(B)講錢財對人的影響；(D)雖談義利，但重點在「先後順序」與榮辱結果，不如(C)直接對應「不義之財不取」。", "skill": "把事例的關鍵行為（拾金不昧＝不取不該得的錢）與文言句的核心（不以其道，得之不處）對應。"}], "difficulty": "中", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-24", "exam": "bc97-1", "nums": [24], "form": "單題", "img": "img/bc97-1-24.png", "source": "杜牧〈贈別〉、蘇武〈留別妻〉、李益〈喜見外弟又言別〉、杜甫〈登岳陽樓〉、李白〈子夜吳歌〉", "author": "", "genre": "古典詩詞曲", "types": ["虛詞句式", "詩詞賞析"], "passage": "紅燭自憐無好計，夜寒空替人垂淚。(A)結髮為夫妻，恩愛兩不移　(B)十年離亂後，長大一相逢　(C)昔聞洞庭水，今上岳陽樓　(D)秋風吹不盡，總是玉關情", "translation": "(A)成年結婚做了夫妻，恩愛彼此不變。(B)經過十年戰亂分離，長大後才相逢。(C)從前就聽說洞庭湖，今天登上了岳陽樓。(D)秋風吹個不停，吹不盡的都是對玉門關外征人的思念。", "keywords": [{"w": "主語", "m": "句子的主體，被說明的對象（誰／什麼＋做什麼）"}, {"w": "結髮", "m": "古代成年束髮，指結婚"}, {"w": "玉關", "m": "玉門關，指邊塞"}], "questions": [{"n": 24, "stem": "主語是句子的主體，作為被說明的對象，以「紅燭自憐無好計，夜寒空替人垂淚」為例，「紅燭」一詞即為句中的主語。下列詩句「」中的語詞，何者也是主語？", "options": {"A": "結髮為「夫妻」，恩愛兩不移", "B": "「十年」離亂後，長大一相逢", "C": "昔聞「洞庭水」，今上岳陽樓", "D": "「秋風」吹不盡，總是玉關情"}, "answer": "D", "explain": "(D)「秋風吹不盡」：是秋風在「吹」，「秋風」是動作的發出者，為主語。(A)「為夫妻」的「夫妻」是判斷的結果（表語）；(B)「十年」是時間修飾語；(C)「聞洞庭水」的「洞庭水」是「聞」的賓語。", "skill": "問「誰在做這個動作？」找到的就是主語；接在動詞後面被動作影響的是賓語。"}], "difficulty": "中", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-26", "exam": "bc97-1", "nums": [26], "form": "單題", "img": "img/bc97-1-26.png", "source": "蕭統〈陶淵明傳〉", "author": "", "genre": "史傳人物", "types": ["句意理解", "主旨寓意"], "passage": "此亦人子也，可善遇之。", "translation": "他也是別人家的孩子啊，你要好好對待他。", "keywords": [{"w": "亦", "m": "也"}, {"w": "人子", "m": "別人的兒子"}, {"w": "善遇", "m": "好好對待"}], "questions": [{"n": 26, "stem": "陶潛送給兒子一個僕役，並且寫了一封信給他，信上有句話說：「此亦人子也，可善遇之。」陶潛講這句話的用意是在勉勵兒子遵循下列哪一項做人處世的道理？", "options": {"A": "俯仰無愧", "B": "推己及人", "C": "潔身自愛", "D": "成人之美"}, "answer": "B", "explain": "陶潛提醒兒子：僕役也是別人的孩子，就像你是我的孩子一樣，應該將心比心好好對待他，這就是(B)推己及人。(A)是行為光明、無愧天地；(C)是保持自身清白；(D)是幫助別人完成好事，都不合。", "skill": "抓「亦」字：「此亦人子」暗示「你也是人子」，把自己和別人放在同一位置，就是將心比心。"}], "difficulty": "易", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-28", "exam": "bc97-1", "nums": [28], "form": "單題", "img": "img/bc97-1-28.png", "source": "選項：(C)《莊子‧知北遊》；其餘出處待查", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "(A)明者遠見於未萌，智者避危於無形　(B)量不寬不能容眾，識不明不堪大用　(C)天地有大美而不言，萬物有成理而不說　(D)激湍之下必有深潭，高丘之下必有浚谷", "translation": "(A)明智的人在事情還沒發生前就看得到，聰明的人在危險還沒顯現時就避開。(B)度量不寬就不能容納眾人，見識不明就不能擔當大任。(C)天地有偉大的美卻不說話，萬物有既定的道理卻不說出來。(D)急流下面一定有深潭，高山下面一定有深谷。", "keywords": [{"w": "未萌", "m": "還沒發生"}, {"w": "成理", "m": "既定的規律"}, {"w": "激湍", "m": "湍急的水流"}], "questions": [{"n": 28, "stem": "「勺子裡的水閃光，海水卻是深暗的。渺小的道理可以明言，偉大的真理只有偉大的緘默。」這句話的涵義與下列何者最接近？", "options": {"A": "明者遠見於未萌，智者避危於無形", "B": "量不寬不能容眾，識不明不堪大用", "C": "天地有大美而不言，萬物有成理而不說", "D": "激湍之下必有深潭，高丘之下必有浚谷"}, "answer": "C", "explain": "題幹說：小道理可以說清楚，偉大的真理反而是沉默的。(C)天地的大美、萬物的道理都「不言」「不說」，同樣是「最偉大的東西不用言語表達」。(A)講先見之明；(B)講度量與見識；(D)講事物相伴而生，都不相關。", "skill": "抓題幹的關鍵對比（明言 vs. 緘默），再找選項中同樣出現「大＋不言」的句子。"}], "difficulty": "中", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-33", "exam": "bc97-1", "nums": [33], "form": "單題", "img": "img/bc97-1-33.png", "source": "出處待查", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析"], "passage": "(A)淨掃黃金階，飛霜皎如雪　(B)鏡湖三百里，菡萏發荷花　(C)山樹落梅花，飛落野人家　(D)薰風自南來，殿閣生微涼", "translation": "(A)把黃金般的臺階掃乾淨，飄落的霜潔白得像雪。(B)鏡湖廣闊三百里，荷花盛開。(C)山上的梅花凋落，飄到鄉野人家。(D)和暖的南風吹來，宮殿樓閣生出一絲涼意。", "keywords": [{"w": "飛霜", "m": "秋天的霜"}, {"w": "菡萏", "m": "荷花，夏季"}, {"w": "梅花", "m": "冬末春初"}, {"w": "薰風", "m": "夏天的南風"}], "questions": [{"n": 33, "stem": "下列詩句，何者是在描寫秋景？", "options": {"A": "淨掃黃金階，飛霜皎如雪", "B": "鏡湖三百里，菡萏發荷花", "C": "山樹落梅花，飛落野人家", "D": "薰風自南來，殿閣生微涼"}, "answer": "A", "explain": "(A)「飛霜」是秋天的景物（霜降在秋季），描寫秋景。(B)荷花盛開是夏天；(C)梅花開落在冬末春初；(D)「薰風」是初夏的南風。", "skill": "背熟季節意象：霜、雁、菊、楓＝秋；荷、薰風、蟬＝夏；梅、雪＝冬；柳、燕、桃杏＝春。"}], "difficulty": "易", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-34", "exam": "bc97-1", "nums": [34], "form": "單題", "img": "img/bc97-1-34.png", "source": "沈括《夢溪筆談‧書畫》", "author": "沈括", "genre": "筆記小品", "types": ["句意理解", "字詞解釋"], "passage": "藏書畫者，多取空名。偶傳為鍾王顧陸之筆，見者爭購，此所謂『耳鑒』。（鍾王顧陸：指鍾繇、王羲之、顧愷之、陸探微等四人，皆為魏晉南北朝書畫名家）", "translation": "收藏書畫的人，大多只看重空洞的名聲。偶然有作品傳說是鍾繇、王羲之、顧愷之、陸探微的手筆，看到的人就爭相購買，這就是所謂「用耳朵鑑賞」。", "keywords": [{"w": "空名", "m": "虛名"}, {"w": "偶", "m": "偶然"}, {"w": "筆", "m": "手筆、作品"}, {"w": "耳鑒", "m": "靠聽來的名聲而非親眼判斷來鑑賞"}], "questions": [{"n": 34, "stem": "「藏書畫者，多取空名。偶傳為鍾王顧陸之筆，見者爭購，此所謂『耳鑒』。」這段文字在說明書畫收藏家的哪一種情形？", "options": {"A": "喜歡爭相收購鍾王顧陸等名家用過的毛筆", "B": "好為收藏品掛上名家字號以抬高作品身價", "C": "在耳濡目染之下也具備了極高的鑑賞能力", "D": "收藏作品與否僅考量書畫作者本身的名氣"}, "answer": "D", "explain": "「多取空名」「偶傳為……之筆，見者爭購」：只要聽說是名家作品就搶著買，不管作品好壞，所以是(D)只看作者名氣。(A)「筆」是指作品，不是毛筆；(B)文中是收藏者被名氣吸引，不是收藏者自己冒用名號；(C)「耳鑒」是諷刺不會鑑賞，與「鑑賞能力極高」相反。", "skill": "注意一詞多義（筆＝作品）與諷刺性詞語（耳鑒＝只用耳朵聽，不用眼睛看）。"}], "difficulty": "中", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-42", "exam": "bc97-1", "nums": [42, 43], "form": "題組", "img": "img/bc97-1-42.png", "source": "張岱〈柳敬亭說書〉（改寫，出自《陶庵夢憶》）", "author": "張岱", "genre": "筆記小品", "types": ["文意推論", "寫作手法"], "passage": "余聽柳敬亭說景陽崗武松打虎，白文與本傳大異。其描寫刻畫，微入毫髮；然又找截乾淨，並不嘮叨。聲如巨鐘，說至筋節處，叱吒叫喊，洶洶崩屋。武松到店沽酒，店內無人，驀地一吼，店中空缸空甓皆甕甕有聲。閑中著色，細微至此。（找截乾淨：該補敘或該停止之處都很恰當；筋節：關鍵；甓：音ㄆㄧˋ，陶製容器；閑中著色：在非緊要處加以渲染）", "translation": "我聽柳敬亭說景陽崗武松打虎的故事，他說的內容和原書大不相同。他描寫刻畫，細緻到連毛髮都不放過；但該補充、該收住的地方又處理得乾淨俐落，一點也不囉嗦。他的聲音像大鐘，說到關鍵處，大聲吆喝叫喊，聲勢洶洶像要把屋子震垮。說到武松到店裡買酒，店裡沒人，武松突然大吼一聲，店中空缸空罈都嗡嗡作響。在不重要的地方也加以渲染，竟細膩到這種程度。", "keywords": [{"w": "白文", "m": "說書時的說白、內容"}, {"w": "本傳", "m": "原本的小說（《水滸傳》）"}, {"w": "微入毫髮", "m": "細緻入微"}, {"w": "叱吒", "m": "大聲怒喝"}, {"w": "沽", "m": "買"}, {"w": "驀地", "m": "突然"}], "questions": [{"n": 42, "stem": "這段文字對柳敬亭說書的特色多所讚譽，然下列何者並未被提及？", "options": {"A": "描述繁簡得宜", "B": "刻畫生動細膩", "C": "聲音洪亮", "D": "嫻熟史書"}, "answer": "D", "explain": "(A)「找截乾淨，並不嘮叨」＝繁簡得宜；(B)「描寫刻畫，微入毫髮」「細微至此」＝生動細膩；(C)「聲如巨鐘」「洶洶崩屋」＝聲音洪亮。文中的「本傳」是指《水滸傳》原著，而且說他的內容「與本傳大異」，並沒有稱讚他熟讀史書，所以選(D)。", "skill": "「並未提及」題逐項找證據；小心「本傳」不是史書，而是原著小說。"}, {"n": 43, "stem": "下列文句，何者是針對柳敬亭所說故事內容的具體描述？", "options": {"A": "余聽柳敬亭說景陽崗武松打虎，白文與本傳大異", "B": "聲如巨鐘，說至筋節處，叱吒叫喊，洶洶崩屋", "C": "武松到店沽酒，店內無人，驀地一吼，店中空缸空甓皆甕甕有聲", "D": "閑中著色，細微至此"}, "answer": "C", "explain": "(C)是柳敬亭所說的故事情節（武松在店裡大吼、缸甓作響），屬於故事內容的具體描寫。(A)是作者聽書的總體說明；(B)描寫柳敬亭說書時的聲音表現；(D)是作者的評論。", "skill": "分清楚三個層次：作者的評論、說書人的表演方式、說書的故事內容。"}], "difficulty": "中", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-1-46", "exam": "bc97-1", "nums": [46, 47, 48], "form": "題組", "img": "img/bc97-1-46.png", "source": "《莊子‧讓王》", "author": "莊子", "genre": "經典語錄", "types": ["字詞解釋", "人物情感", "主旨寓意"], "passage": "孔子謂顏回曰：「回，來！家貧居卑，胡不仕乎？」顏回對曰：「不願仕。回有郭外之田五十畝，足以給飦粥；郭內之田十畝，足以為絲麻；鼓琴足以自娛；所學夫子之道者足以自樂也。回不願仕。」孔子愀然變容曰：「善哉回之意！丘聞之，『知足者不以利自累也，審自得者失之而不懼，行修於內者無位而不怍。』丘誦之久矣，今於回而後見之，是丘之得也。」（飦粥：飦，音ㄍㄢ，濃粥；愀然：愀，音ㄑㄧㄠˇ，容色驟變貌；怍：音ㄗㄨㄛˋ，慚愧）", "translation": "孔子對顏回說：「回啊，過來！你家境貧窮、地位低下，為什麼不去做官呢？」顏回回答：「我不想做官。我在城外有五十畝田，足夠供應稀飯；城內有十畝田，足夠種桑麻做衣服；彈琴足以自我娛樂；從老師這裡學到的道理足以讓自己快樂。我不想做官。」孔子神情一變說：「回的想法真好啊！我聽說：『知足的人不會因為追求利益而勞累自己；明白自得之樂的人失去外物也不害怕；在內心修養品德的人沒有官位也不覺得羞愧。』這話我誦讀很久了，今天才在你身上看到，這是我的收穫啊。」", "keywords": [{"w": "胡", "m": "為什麼"}, {"w": "仕", "m": "做官"}, {"w": "郭", "m": "外城"}, {"w": "給", "m": "供給"}, {"w": "夫子", "m": "老師（指孔子）"}, {"w": "累", "m": "使……勞累"}, {"w": "審", "m": "明白、清楚"}, {"w": "怍", "m": "慚愧"}], "questions": [{"n": 46, "stem": "下列語句的解釋，何者最恰當？", "options": {"A": "胡不仕乎：難道在胡人轄區不能作官嗎", "B": "夫子之道：敬師事親的處世之道", "C": "以利自累：因為求取利祿勞苦自己", "D": "行修於內：私底下能仔細調養自己"}, "answer": "C", "explain": "(C)「以利自累」：因為追求利益而讓自己勞累，正確。(A)「胡」是疑問詞「為什麼」，不是胡人；(B)「夫子之道」是孔子所教的道理，不限於敬師事親；(D)「行修於內」是在內心修養品德，不是調養身體。", "skill": "文言常見疑問詞「胡、何、奚、曷」都是「為什麼／什麼」，不要望文生義。"}, {"n": 47, "stem": "根據本文，孔子對顏回的應答所抱持的態度為下列何者？", "options": {"A": "悲憫其身分處境", "B": "認同其心意作為", "C": "惋惜其懷才不遇", "D": "讚賞其奮發積極"}, "answer": "B", "explain": "孔子說「善哉回之意」，並說顏回實踐了自己誦讀已久的道理，「是丘之得也」，可見他認同顏回的想法與作法，選(B)。(A)(C)孔子並無憐憫或惋惜；(D)顏回是安貧知足，不是奮發積極求取功名。", "skill": "人物態度看評價語（善哉）＋後續說法（是丘之得也），不要只看表情（愀然變容）就判斷為悲傷。"}, {"n": 48, "stem": "本文旨趣，與下列何者最接近？", "options": {"A": "心存良善的動機，快樂便可如影隨形", "B": "想要達成期盼的目標，必須知所忍耐", "C": "若要出仕為政，當先求衣食無憂", "D": "學道有得，則處處皆能知足自適"}, "answer": "D", "explain": "顏回有田可食、可衣，鼓琴自娛，「所學夫子之道者足以自樂」，因學道有得而知足，不需做官，孔子也讚許「知足者不以利自累」，所以是(D)。(A)文中沒談動機；(B)沒談忍耐達成目標；(C)顏回不願出仕，與「先求衣食再做官」不合。", "skill": "主旨題找文中反覆出現的關鍵字（足以、知足、自樂、自得），歸納成一句話。"}], "difficulty": "中", "label": "97年第一次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-5", "exam": "bc97-2", "nums": [5], "form": "單題", "img": "img/bc97-2-5.png", "source": "《菜根譚》", "author": "洪應明", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "人之過誤宜恕，而在己則不可恕；己之困辱宜忍，而在人則不可忍。", "translation": "別人的過錯應該寬恕，但如果是自己犯的錯就不可以原諒；自己遭受的困苦屈辱應該忍受，但如果是別人遭受困辱，就不能袖手旁觀、默默忍受。", "keywords": [{"w": "宜", "m": "應該"}, {"w": "過誤", "m": "過錯"}, {"w": "困辱", "m": "困苦與屈辱"}, {"w": "在己", "m": "發生在自己身上"}], "questions": [{"n": 5, "stem": "「人之過誤宜恕，而在己則不可恕；己之困辱宜忍，而在人則不可忍。」這段話最主要的意思是什麼？", "options": {"A": "己所不欲，勿施於人", "B": "律己宜嚴，待人宜寬", "C": "樂聞人過，不道己非", "D": "對己能真，對人不虛"}, "answer": "B", "explain": "這段話把「人」和「己」對照：別人的錯要寬恕、自己的錯不可原諒；自己的苦要忍、別人的苦不能忍。總之就是對自己嚴格、對別人寬厚，所以選(B)。(A)講不把自己不要的強加給別人，與寬嚴無關；(C)喜歡聽別人的過錯、不說自己的錯，正好與原文相反；(D)講真誠不虛偽，原文沒有談到。", "skill": "把句中「人」與「己」兩組對照找出來，分別歸納對自己、對別人的態度，再找同時涵蓋兩面的選項"}], "difficulty": "易", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-6", "exam": "bc97-2", "nums": [6], "form": "單題", "img": "img/bc97-2-6.png", "source": "艾子故事（出處待查）", "author": "", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "穰侯與綱壽接壤。魏冉，將以廣其封也，乃伐綱壽而取之。兵回，而范雎代其相矣。艾子聞而笑曰：「真所謂外頭趕兔，屋裡失獐也。」", "translation": "穰侯的封地和綱壽相鄰。魏冉（穰侯）想擴大自己的封地，就出兵攻打綱壽並佔領了它。等到軍隊回來，范雎已經取代他當上宰相了。艾子聽了笑說：「這真是所謂在外面追兔子，屋裡卻丟了獐子啊。」", "keywords": [{"w": "接壤", "m": "土地相連"}, {"w": "廣其封", "m": "擴大他的封地"}, {"w": "乃", "m": "於是、就"}, {"w": "代其相", "m": "取代他的宰相職位"}, {"w": "獐", "m": "一種鹿類動物，比兔子更有價值"}], "questions": [{"n": 6, "stem": "「穰侯與綱壽接壤。魏冉，將以廣其封也，乃伐綱壽而取之。兵回，而范雎代其相矣。艾子聞而笑曰：『真所謂外頭趕兔，屋裡失獐也。』」這則故事的寓意，與下列哪一句話最接近？", "options": {"A": "前門打虎，後門進狼", "B": "蛇入竹桶，曲性不改", "C": "正離狼窩，又逢虎口", "D": "狐狸看雞，愈看愈稀"}, "answer": "A", "explain": "魏冉在外忙著搶小利（綱壽），家裡卻丟了更重要的相位，比喻只顧一頭、疏忽另一頭而因小失大。(A)只顧在前門打虎，狼卻從後門溜進來，最接近。(B)比喻本性難改；(C)比喻剛脫離險境又遇災難；(D)比喻所託非人，越管越少。(A)「只專注一方，卻未顧及另一方」最接近。", "skill": "先看清「外頭得到什麼、屋裡失去什麼」，抓出「顧此失彼、因小失大」的結構，再比對俗語的結構"}], "difficulty": "中", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-9", "exam": "bc97-2", "nums": [9], "form": "單題", "img": "img/bc97-2-9.png", "source": "古典詩句（選項）", "author": "", "genre": "古典詩詞曲", "types": ["寫作手法", "字詞解釋"], "passage": "孤帆遠影碧山盡／奈何軒冕貴，不與布衣言／舉杯邀明月，對影成三人／古調雖自愛，今人多不彈／路遙知馬力，日久見人心", "translation": "題幹「孤帆」用船的一部分「帆」代稱船。(A)無奈那些坐車戴冠的顯貴，不肯和平民百姓說話。(B)舉起酒杯邀請明月，加上我的影子成了三個人。(C)古老的曲調雖然自己喜愛，現在的人卻大多不彈了。(D)路途遙遠才知道馬的力氣，時間久了才看得出人心。", "keywords": [{"w": "軒冕", "m": "古代大夫的車子和禮帽，借代官位、顯貴"}, {"w": "布衣", "m": "平民穿的布衣，借代平民"}, {"w": "借代", "m": "用相關的事物代替本名"}], "questions": [{"n": 9, "stem": "「孤帆遠影碧山盡」句中以「帆」來代稱船，這樣的修辭法叫做「借代」。下列句子「　」中的語詞，何者也屬於這種修辭法？", "options": {"A": "奈何「軒冕」貴，不與布衣言", "B": "舉杯邀「明月」，對影成三人", "C": "「古調」雖自愛，今人多不彈", "D": "路遙知「馬力」，日久見人心"}, "answer": "A", "explain": "「軒冕」本指大夫坐的車和戴的冠，用來代稱做官的顯貴，是借代，選(A)。(B)「明月」就是真的月亮（整句是擬人）；(C)「古調」就是古代曲調，是本義；(D)「馬力」就是馬的力氣，是本義，都沒有用別的東西代替。", "skill": "把括號詞換回「它真正指的東西」：如果所指與字面不同、而是用相關的物件代稱，就是借代"}], "difficulty": "中", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-14", "exam": "bc97-2", "nums": [14], "form": "單題", "img": "img/bc97-2-14.png", "source": "選項為古典詩句（題幹為林雄新詩〈手〉）", "author": "", "genre": "其他", "types": ["人物情感", "比較閱讀"], "passage": "(A)下布骨肉恩，上報父母慈／(B)悔痛親不在，孝心無所施／(C)豈無父母在高堂，亦有親情滿故鄉／(D)當家才知柴米貴，養子方知父母恩", "translation": "(A)對下施予骨肉恩情，對上報答父母的慈愛。(B)後悔痛心父母已經不在，孝心再也沒有地方可以表達。(C)難道沒有父母在家中，故鄉也有滿滿的親情。(D)自己當家才知道柴米昂貴，自己養孩子才明白父母的恩情。", "keywords": [{"w": "親", "m": "父母"}, {"w": "施", "m": "施行、表達"}, {"w": "高堂", "m": "指父母"}], "questions": [{"n": 14, "stem": "（林雄〈手〉：緊握著臨終父親的手／並以狂烈的注視企圖挽回／他那逐漸沒入陰影的面顏／突然意識到——從未如此面對／他臉上的皺紋與深藏在皺紋間的一切；／意識到——這是（或許是過了孩提以來）第一次／握著他的手。而這時，他的手／已經在我炙熱的掌心轉為冰冷。）這首詩中「我」的心境，與下列何者最接近？", "options": {"A": "下布骨肉恩，上報父母慈", "B": "悔痛親不在，孝心無所施", "C": "豈無父母在高堂，亦有親情滿故鄉", "D": "當家才知柴米貴，養子方知父母恩"}, "answer": "B", "explain": "詩中「我」在父親臨終時才第一次握他的手，而父親的手已經變冷，充滿「來不及」的悔恨，正是(B)「父母已不在，孝心無處表達」。(A)是報答父母恩情的平常心意；(C)講思念故鄉親人；(D)講自己成家後才體會父母辛勞，都沒有「親人已逝的悔恨」。", "skill": "先抓新詩的情感關鍵（臨終、第一次、轉為冰冷→悔恨來不及），再逐句翻譯文言選項，找情境相同者"}], "difficulty": "易", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-16", "exam": "bc97-2", "nums": [16], "form": "單題", "img": "img/bc97-2-16.png", "source": "〈渡荊門送別〉", "author": "李白", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "渡遠荊門外，來從楚國遊。山隨平野盡，江入大荒流。月下飛天鏡，雲生結海樓。仍連故鄉水，萬里送行舟。", "translation": "我渡江遠行到荊門山外，來到古楚國一帶遊歷。山勢隨著平原展開而漸漸消失，江水流入遼闊無邊的原野。月影映在水中像從天上飛下的明鏡，雲霞升起凝結成海市蜃樓。我仍然愛著這來自故鄉的江水，它不遠萬里送我的船遠行。", "keywords": [{"w": "荊門", "m": "荊門山，在今湖北"}, {"w": "大荒", "m": "廣闊無邊的原野"}, {"w": "天鏡", "m": "比喻月亮"}, {"w": "海樓", "m": "海市蜃樓"}, {"w": "對仗", "m": "上下句字數相同、詞性相對"}], "questions": [{"n": 16, "stem": "「渡遠荊門外，來從楚國遊。山隨平野盡，＿＿＿。＿＿＿，＿＿＿。＿＿＿，萬里送行舟。」這是李白的〈渡荊門送別〉，依律詩中間兩聯必須對仗、偶數句必須押韻的格律，下列何者是正確的排序？", "options": {"A": "月下飛天鏡／江入大荒流／雲生結海樓／仍連故鄉水", "B": "江入大荒流／雲生結海樓／仍連故鄉水／月下飛天鏡", "C": "江入大荒流／月下飛天鏡／雲生結海樓／仍連故鄉水", "D": "月下飛天鏡／雲生結海樓／仍連故鄉水／江入大荒流"}, "answer": "C", "explain": "第四句是偶數句要押韻（遊、舟押ㄡ韻），又要與「山隨平野盡」對仗：「江入大荒流」的江／山、入／隨、大荒／平野、流／盡正好相對，且「流」押韻。第五、六句是頸聯也要對仗：「月下飛天鏡」對「雲生結海樓」，第六句「樓」押韻。剩下「仍連故鄉水」放第七句（奇數句不押韻）。所以是(C)。其他選項會讓偶數句落在「鏡」「水」等不押韻的字上，或破壞對仗。", "skill": "先找偶數句：句尾必須押韻；再把可以兩兩對仗的句子配對，放進第3、4句與第5、6句"}], "difficulty": "中", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-17", "exam": "bc97-2", "nums": [17], "form": "單題", "img": "img/bc97-2-17.png", "source": "〈愛蓮說〉", "author": "周敦頤", "genre": "說理議論", "types": ["文意推論", "寫作手法"], "passage": "出淤泥而不染，濯清漣而不妖；中通外直，不蔓不枝；香遠益清，亭亭淨植……", "translation": "蓮花從汙泥中長出卻不被沾染，在清水中洗滌過卻不顯得妖豔；莖內部貫通、外形挺直，不生藤蔓也不長枝節；香氣傳得越遠越清幽，筆直潔淨地立在水中。", "keywords": [{"w": "濯", "m": "洗滌"}, {"w": "漣", "m": "水波"}, {"w": "妖", "m": "豔麗而不莊重"}, {"w": "蔓", "m": "生藤蔓（比喻攀附）"}, {"w": "益", "m": "更加"}, {"w": "植", "m": "豎立"}], "questions": [{"n": 17, "stem": "周敦頤〈愛蓮說〉細數蓮的特質，如：「出淤泥而不染，濯清漣而不妖；中通外直，不蔓不枝；香遠益清，亭亭淨植……」這些都象徵著君子的德行，其中不包含下列何者？", "options": {"A": "博施濟眾，仁民愛物", "B": "鄙夷富貴，不阿權勢", "C": "潔身自好，不隨流俗", "D": "高風亮節，清譽遠播"}, "answer": "A", "explain": "「出淤泥而不染」象徵潔身自好、不隨流俗(C)；「中通外直、不蔓不枝」象徵正直不攀附，可對應不阿權勢(B)；「香遠益清、亭亭淨植」象徵品德高潔、名聲遠揚(D)。原文沒有任何描寫談到廣施恩惠、愛護人民，所以不包含(A)。", "skill": "把每一句蓮的特質一一對應到選項，剩下對不上的就是答案（注意題目問「不包含」）"}], "difficulty": "易", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-21", "exam": "bc97-2", "nums": [21], "form": "單題", "img": "img/bc97-2-21.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "上苟好奢，則天下貪冒之吏將肆心焉；上苟好利，則天下聚斂之臣將置力焉。", "translation": "在上位的君主如果喜好奢侈，天下貪婪的官吏就會放縱私心；君主如果喜好財利，天下搜刮民財的臣子就會盡力去做。", "keywords": [{"w": "上", "m": "在上位的人、君主"}, {"w": "苟", "m": "如果"}, {"w": "貪冒", "m": "貪求財利"}, {"w": "肆心", "m": "放縱心意"}, {"w": "聚斂", "m": "搜刮（題目注釋）"}, {"w": "置力", "m": "盡力（題目注釋）"}], "questions": [{"n": 21, "stem": "「上苟好奢，則天下貪冒之吏將肆心焉；上苟好利，則天下聚斂之臣將置力焉。」這段話的涵義，與下列何者最接近？", "options": {"A": "志高品高，志下品下", "B": "上者作惡，下民遭殃", "C": "上之為政，得下之情則治", "D": "君好則臣為，上行則下效"}, "answer": "D", "explain": "兩句都是「上面喜歡什麼，下面的臣子就跟著做什麼」，強調上行下效，選(D)。(A)講志向高低決定品格；(B)重點在百姓受害，原文說的是官吏跟著做；(C)講了解民情才能治理，都不合。", "skill": "找出「上苟好○，則下之臣將○」的重複句式，歸納出「上影響下」的因果關係"}], "difficulty": "易", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-22", "exam": "bc97-2", "nums": [22], "form": "單題", "img": "img/bc97-2-22.png", "source": "出處待查（句意近《呂氏春秋‧誠廉》「石可破也，而不可奪堅；丹可磨也，而不可奪赤」）", "author": "", "genre": "說理議論", "types": ["句意理解", "文意推論"], "passage": "丹可磨而不可奪其色，蘭可燔而不可滅其馨，玉可碎而不可改其白，金可銷而不可易其剛。", "translation": "丹砂可以磨碎，卻不能改變它的紅色；蘭草可以焚燒，卻不能消滅它的香氣；玉可以打碎，卻不能改變它的潔白；金屬可以熔化，卻不能改變它的剛硬。", "keywords": [{"w": "奪", "m": "改變、去除"}, {"w": "燔", "m": "焚燒（題目注釋）"}, {"w": "馨", "m": "香氣"}, {"w": "銷", "m": "熔化"}, {"w": "易", "m": "改變"}], "questions": [{"n": 22, "stem": "「丹可磨而不可奪其色，蘭可燔而不可滅其馨，玉可碎而不可改其白，金可銷而不可易其剛。」這段話最適合用來糾正下列哪一個人的處世態度？", "options": {"A": "阿東：「我已經是泥菩薩過江，哪有能力去幫他啊！」", "B": "阿西：「人不為己，天誅地滅，先顧好自己再說吧！」", "C": "阿南：「不管別人怎麼說，我都把它當作是耳邊風！」", "D": "阿北：「別怪我沒原則，人在屋簷下，不得不低頭！」"}, "answer": "D", "explain": "四個比喻都說：外形可以被毀壞，本質卻不會改變，勉勵人在壓力下也要堅守原則、保持氣節。阿北因為環境壓力就放棄原則，正好可用這段話糾正，選(D)。(A)自身難保；(B)自私自利；(C)不聽別人意見，都與「堅守本質」無關。", "skill": "先從連續的比喻歸納共同點（外形可毀、本質不變），再找選項中「本質被外力改變」的人"}], "difficulty": "易", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-23", "exam": "bc97-2", "nums": [23], "form": "單題", "img": "img/bc97-2-23.png", "source": "出處待查", "author": "", "genre": "古典詩詞曲", "types": ["人物情感", "詩詞賞析"], "passage": "月宮秋冷桂團欒，歲歲花開只自攀；共在人間說天上，不知天上憶人間。", "translation": "月宮裡秋夜清冷，桂樹圓圓地圍繞著，每年花開了也只能自己攀折欣賞；人間的人都在談論天上多好，卻不知道天上的人反而懷念著人間。", "keywords": [{"w": "團欒", "m": "圓的樣子、團聚"}, {"w": "自攀", "m": "獨自攀折（無人相伴）"}, {"w": "憶", "m": "想念"}], "questions": [{"n": 23, "stem": "「月宮秋冷桂團欒，歲歲花開只自攀；共在人間說天上，不知天上憶人間。」詩中主角的情懷與下列何者最接近？", "options": {"A": "清心寡慾", "B": "清寂落寞", "C": "孤芳自賞", "D": "樂不思蜀"}, "answer": "B", "explain": "主角是月宮中的人（嫦娥）：月宮「秋冷」，花開「只自攀」，沒人陪伴，還懷念人間，表現冷清寂寞的心情，選(B)。(A)清心寡慾是欲望少、心境平淡，詩中卻有思念；(C)孤芳自賞是自命清高、自我欣賞；(D)樂不思蜀是樂而忘返，與「憶人間」相反。", "skill": "抓情緒線索詞：「冷」「只自」「憶」→ 孤單、思念，再刪掉方向相反的選項"}], "difficulty": "易", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-29", "exam": "bc97-2", "nums": [29], "form": "單題", "img": "img/bc97-2-29.png", "source": "選項出自東方朔〈答客難〉、《戰國策》、《老子》第六十六章等", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "(A)尊之則為將，卑之則為虜／(B)前事之不忘，後事之師也／(C)江海所以能為百谷王者，以其善下之／(D)和羹之美，在於合異；上下之益，在能相濟", "translation": "(A)重用他就能當將軍，輕視他就淪為俘虜。(B)不忘記過去的事，可以作為以後做事的借鏡。(C)江海之所以能成為百川匯聚之處，是因為它善於處在低下的位置。(D)羹湯的美味在於調和各種不同的材料；上下之間的好處在於能互相補足。", "keywords": [{"w": "百谷王", "m": "百川所歸往的地方"}, {"w": "善下", "m": "善於居於低處，比喻謙虛"}, {"w": "和羹", "m": "調味均勻的湯"}, {"w": "相濟", "m": "互相補助"}], "questions": [{"n": 29, "stem": "下列文句，何者意在勉人謙讓？", "options": {"A": "尊之則為將，卑之則為虜", "B": "前事之不忘，後事之師也", "C": "江海所以能為百谷王者，以其善下之", "D": "和羹之美，在於合異；上下之益，在能相濟"}, "answer": "C", "explain": "(C)出自《老子》，以江海處在低處才能匯聚百川，比喻人要謙虛處下，才能得到眾人歸附，是勉人謙讓。(A)說人的地位取決於是否被重用；(B)勉人記取教訓；(D)強調包容不同、互相補足，都不是謙讓。", "skill": "把每句翻成白話後找關鍵動作：「善下」＝放低自己＝謙讓"}], "difficulty": "中", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-30", "exam": "bc97-2", "nums": [30], "form": "單題", "img": "img/bc97-2-30.png", "source": "《紅樓夢》第七十回 薛寶釵〈臨江仙‧柳絮〉", "author": "曹雪芹", "genre": "古典詩詞曲", "types": ["詩詞賞析", "虛詞句式"], "passage": "白玉堂前春解舞，東風捲得均勻。蜂團蝶陣亂紛紛，幾曾隨逝水，豈必委芳塵。萬縷千絲終不改，任他隨聚隨分。韶華休笑本無根，好風頻借力，送我上青雲。", "translation": "白玉堂前的春天柳絮懂得飛舞，被東風吹捲得均勻。蜂蝶成群亂紛紛地飛著，柳絮何曾隨著流水漂去，又哪裡一定要落入塵土？千絲萬縷始終不改，任它聚合或分散。春光啊，不要笑我本來沒有根，好風不斷借我力量，把我送上青雲。", "keywords": [{"w": "解", "m": "懂得"}, {"w": "幾曾", "m": "何曾、哪裡曾經（反問）"}, {"w": "豈必", "m": "哪裡一定（反問）"}, {"w": "委", "m": "落、棄置"}, {"w": "韶華", "m": "美好的春光"}, {"w": "休", "m": "不要"}], "questions": [{"n": 30, "stem": "《紅樓夢》中，寶釵以〈臨江仙〉賦詠柳絮，其詞曰：「白玉堂前春解舞，東風捲得均勻。蜂團蝶陣亂紛紛，幾曾隨逝水，豈必委芳塵。萬縷千絲終不改，任他隨聚隨分。韶華休笑本無根，好風頻借力，送我上青雲。」下列選項，何者含有反詰語氣？", "options": {"A": "白玉堂前春解舞，東風捲得均勻", "B": "蜂團蝶陣亂紛紛，幾曾隨逝水，豈必委芳塵", "C": "萬縷千絲終不改，任他隨聚隨分", "D": "韶華休笑本無根，好風頻借力，送我上青雲"}, "answer": "B", "explain": "反詰是「用問句表達肯定的意思、答案就在問題反面」。(B)「幾曾隨逝水，豈必委芳塵」意思是「哪裡曾隨水漂走？哪裡一定要落入塵土？」其實是說柳絮不會隨水流走、不必落入塵土，是反詰。(A)是直接描寫；(C)是直述；(D)「休笑」是勸阻的祈使語氣，不是反問。", "skill": "圈出「豈、何、幾曾、安、焉」等反問詞，再確認句子用問的形式表達相反的肯定意思"}], "difficulty": "中", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-32", "exam": "bc97-2", "nums": [32], "form": "單題", "img": "img/bc97-2-32.png", "source": "成語（「夙夜匪懈」出自《詩經‧大雅‧烝民》）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "否極泰來／莫測高深／無遠弗屆／夙夜匪懈", "translation": "(A)壞運到了極點，好運就會來臨。(B)高深得沒有人能測量。(C)再遠的地方也沒有到不了的。(D)從早到晚都不懈怠。", "keywords": [{"w": "否", "m": "音ㄆㄧˇ，《易經》卦名，指閉塞、厄運"}, {"w": "莫", "m": "不、沒有人"}, {"w": "弗", "m": "不"}, {"w": "匪", "m": "通「非」，不"}, {"w": "夙夜", "m": "早晚"}], "questions": [{"n": 32, "stem": "下列詞語「　」中的字，何者不是表達否定的副詞用語？", "options": {"A": "「否」極泰來", "B": "「莫」測高深", "C": "無遠「弗」屆", "D": "夙夜「匪」懈"}, "answer": "A", "explain": "「否極泰來」的「否」讀ㄆㄧˇ，是《易經》的卦名，指壞運、困境，是名詞，不是否定副詞，所以選(A)。(B)「莫」＝不能、沒有人；(C)「弗」＝不；(D)「匪」通「非」＝不，都是表示否定的副詞。", "skill": "把字代入「不」試讀：讀得通的是否定副詞；讀不通、且是事物名稱的就不是"}], "difficulty": "中", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-40", "exam": "bc97-2", "nums": [40, 41, 42], "form": "題組", "img": "img/bc97-2-40.png", "source": "〈却要〉（《三水小牘》）", "author": "皇甫枚", "genre": "筆記小品", "types": ["字詞解釋", "句意理解", "人物情感"], "passage": "却要，美容止，善辭令，巧媚才捷，能承順顏色，姻黨亦多憐之。嘗遇清明節，時纖月娟娟，庭花爛發，中堂垂繡幕，背銀釭。而却要遇大郎於櫻桃花影中，大郎乃持之求偶。却要取茵席授之，曰：「可於廳中東南隅，佇立相待；候堂前眠熟，當至。」大郎既去，至廊下，又逢二郎調之。却要復取茵席授之，曰：「可於廳中東北隅相待。」二郎既去，又遇三郎束之，却要復取茵席授之，曰：「可於廳中西南隅相待。」三郎既去，又五郎遇著，握手不可解，却要亦取茵席授之，曰：「可於廳中西北隅相待。」四郎皆去。大郎於廳角中屏息以待。廳門斜閉，見其三弟比比而至，各趨一隅，心雖訝之，而不敢發。少頃，却要突燃炬，疾向廳事，豁雙扉而照之，謂大郎輩曰：「阿堵貧兒，爭敢向這裡覓宿處！」皆棄所攜，掩面而走。自是諸子懷慚，不敢失敬。", "translation": "却要容貌舉止美好，擅長言辭，聰明伶俐、反應快，能順著主人的臉色心意做事，親戚們也都疼愛她。有一年清明節，彎彎的新月明亮美好，庭院裡花朵盛開，中堂垂掛著繡花帷幕，背對著銀燈。却要在櫻桃花影中遇到大郎，大郎就抱住她要求親熱。却要拿了墊褥給他，說：「你可以到廳中東南角站著等我；等堂前的人睡熟了，我就會來。」大郎走後，却要到了走廊下，又碰到二郎調戲她。却要又拿墊褥給他，說：「可以到廳中東北角等我。」二郎走後，又遇到三郎抱住她，却要又拿墊褥給他，說：「可以到廳中西南角等我。」三郎走後，又碰到五郎，握著她的手不放，却要也拿墊褥給他，說：「可以到廳中西北角等我。」四位公子都去了。大郎在廳角屏住呼吸等待，廳門半掩，只見三個弟弟一個接一個來到，各自走向一個角落，心裡雖然驚訝，卻不敢出聲。過了一會兒，却要突然點燃火把，快步走向大廳，打開兩扇門照著他們，對大郎等人說：「這些窮小子，怎麼敢到這裡找地方睡覺！」他們都丟下帶來的墊褥，遮著臉逃走。從此這幾位公子心懷慚愧，再也不敢對她無禮。", "keywords": [{"w": "容止", "m": "容貌舉止"}, {"w": "承順顏色", "m": "順著別人的臉色心意"}, {"w": "姻黨", "m": "親戚"}, {"w": "銀釭", "m": "銀燈（題目注釋）"}, {"w": "持", "m": "抱住"}, {"w": "茵席", "m": "墊褥（題目注釋）"}, {"w": "調", "m": "調戲"}, {"w": "束", "m": "抱住"}, {"w": "解", "m": "放開"}, {"w": "比比", "m": "一個接一個"}, {"w": "發", "m": "出聲"}, {"w": "豁", "m": "打開"}, {"w": "阿堵", "m": "這些、這個"}, {"w": "爭", "m": "怎麼"}, {"w": "自是", "m": "從此"}], "questions": [{"n": 40, "stem": "下列語句的說明，何者正確？", "options": {"A": "美容止：指却要從不打扮裝飾", "B": "候堂前眠熟：指却要請大郎先在前廳睡一覺", "C": "比比而至：指兄弟們一個接一個到來", "D": "皆棄所攜：指兄弟們都不再牽却要的手"}, "answer": "C", "explain": "「比比而至」是大郎看見三個弟弟一個接一個走進大廳，(C)正確。(A)「美容止」是容貌舉止美好，不是不打扮；(B)是「等堂前的人睡熟了（我就來）」，不是請大郎去睡；(D)「所攜」指他們帶來的茵席，是丟下墊褥逃走，不是不牽手。", "skill": "把詞句放回上下文：先看主詞是誰、動作的對象是什麼（所攜＝手上帶的東西＝茵席）"}, {"n": 41, "stem": "下列文句所描述的動作，何者是男人對女子輕薄調戲的舉動？", "options": {"A": "垂繡幕，背銀釭", "B": "取茵席授之", "C": "握手不可解", "D": "於廳中西北隅相待"}, "answer": "C", "explain": "「握手不可解」是五郎握住却要的手不肯放開，是男子輕薄的舉動，選(C)。(A)是描寫中堂的環境；(B)是却要拿墊褥給公子們，是却要的動作；(D)是却要叫五郎去等的話，也不是調戲動作。", "skill": "先分清每個動作是誰做的：題目要「男人對女子」的動作，就刪掉環境描寫和却要自己的動作"}, {"n": 42, "stem": "對於這則故事中的女主角却要，下面的評述何者最恰當？", "options": {"A": "不苟言笑又莊重", "B": "含蓄內斂且寡言", "C": "年輕貌美又羞澀", "D": "才貌兼備且機智"}, "answer": "D", "explain": "開頭說却要「美容止」（貌美）、「善辭令，巧媚才捷」（有才、口才好），後來用計讓四位公子在大廳相遇而自取其辱，展現機智，所以是(D)。她能說會道，不是寡言(B)；面對調戲不慌不忙，並不羞澀(C)；也看不出不苟言笑(A)。", "skill": "人物評述題：開頭的形容詞給「先天條件」，情節中的作為給「性格證據」，兩者都要對得上"}], "difficulty": "中", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc97-2-45", "exam": "bc97-2", "nums": [45, 46], "form": "題組", "img": "img/bc97-2-45.png", "source": "《荀子‧天論》", "author": "荀子", "genre": "說理議論", "types": ["主旨寓意", "寫作手法"], "passage": "在天者莫明於日月，在地者莫明於水火，在物者莫明於珠玉，在人者莫明於禮義。故日月不高，則光暉不赫；水火不積，則暉潤不博；珠玉不睹乎外，則王公不以為寶；禮義不加於國家，則功名不白。", "translation": "在天上的東西沒有比日月更明亮的，在地上的東西沒有比水火更明顯的，在物品中沒有比珠玉更光亮的，在人身上沒有比禮義更顯明的。所以日月如果不高掛天上，光輝就不顯赫；水火如果不積聚，光亮與潤澤就不廣大；珠玉如果不顯露在外，王公就不會把它當作寶物；禮義如果不施行於國家，功業和名聲就不能顯揚。", "keywords": [{"w": "莫", "m": "沒有什麼"}, {"w": "明", "m": "明亮、顯明"}, {"w": "赫", "m": "顯著、盛大"}, {"w": "暉潤", "m": "火的光輝與水的潤澤"}, {"w": "博", "m": "廣大"}, {"w": "睹", "m": "顯露被看見"}, {"w": "白", "m": "顯明、彰顯"}], "questions": [{"n": 45, "stem": "下列何者與本文的主旨無關？", "options": {"A": "修身、治國之道，莫善於禮義", "B": "禮義過盛者，其情必疏，其誠難信", "C": "人之所以貴，國之所以強，惟禮與義", "D": "人無禮義則無以立身，國無禮義則不能平治"}, "answer": "B", "explain": "本文主旨是：禮義對人和國家最重要，國家施行禮義才能功名顯揚。(A)(C)(D)都在強調禮義對修身治國的重要，與主旨相合。(B)說禮義太多反而讓感情疏遠、誠意難信，是批評禮義過頭，與本文推崇禮義的主旨無關。", "skill": "先用一句話寫出主旨（禮義最重要），再找立場相反或方向不同的選項"}, {"n": 46, "stem": "關於本文的寫作手法，下列何者正確？", "options": {"A": "利用了大量的典故，增加文章立論的根據", "B": "文中聲調鏗鏘，一韻到底，讀之餘味無窮", "C": "以日月、水火、珠玉和禮義形成正反對比", "D": "藉用多種事物，烘托凸顯整段文句的意旨"}, "answer": "D", "explain": "作者先舉日月、水火、珠玉都要「高、積、顯露」才能發揮光彩，再帶出禮義要施行於國家才能功名顯揚，是用多種事物來烘托凸顯主旨，選(D)。(A)文中沒有引用典故；(B)沒有一韻到底；(C)日月、水火、珠玉與禮義是同類相比（類比），不是正反對比。", "skill": "看作者怎麼舉例：多個例子方向一致、最後帶出主角，就是類比烘托；方向相反才是對比"}], "difficulty": "中", "label": "97年第二次基測", "year": 97, "kind": "基測"}, {"id": "bc98-1-6", "exam": "bc98-1", "nums": [6], "form": "單題", "img": "img/bc98-1-6.png", "source": "命題者自撰便條", "author": "", "genre": "書信序跋", "types": ["句意理解", "文化常識"], "passage": "聽聞吾兄日內將有臺北之行，擬託代購臺灣出版社之《中臺灣旅遊叢書》一套，書款請先代墊，日後當面奉還！此上　大發學長　弟莊有為敬上　六月二十一日", "translation": "聽說學長這幾天要去臺北，想拜託您幫我買一套臺灣出版社出的《中臺灣旅遊叢書》，書錢請先幫我墊付，以後當面還給您！以上，敬呈大發學長。學弟莊有為敬上，六月二十一日。", "keywords": [{"w": "吾兄", "m": "對平輩的敬稱"}, {"w": "日內", "m": "近幾天之內"}, {"w": "擬", "m": "打算"}, {"w": "代墊", "m": "代為先付錢"}, {"w": "奉還", "m": "歸還（敬辭）"}, {"w": "此上", "m": "便條結尾用語，表示以上"}], "questions": [{"n": 6, "stem": "（便條內容見上）關於這則便條的內容，下列敘述何者正確？", "options": {"A": "請託對方購買《中臺灣旅遊叢書》", "B": "感謝對方致贈《中臺灣旅遊叢書》", "C": "託對方轉交購買《中臺灣旅遊叢書》的款項", "D": "向對方借錢以便自行購買《中臺灣旅遊叢書》"}, "answer": "A", "explain": "「擬託代購」就是想拜託對方代為購買，「書款請先代墊，日後當面奉還」是請對方先付錢、之後再還，所以是請託對方買書，選(A)。(B)便條沒有感謝贈書；(C)不是託對方轉交錢；(D)不是借錢自己買，而是請對方代買並先墊錢。", "skill": "抓便條的關鍵動詞「託」「代購」「代墊」「奉還」，弄清楚誰做什麼、錢由誰出"}], "difficulty": "易", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-7", "exam": "bc98-1", "nums": [7], "form": "單題", "img": "img/bc98-1-7.png", "source": "《大學》", "author": "", "genre": "經典語錄", "types": ["句意理解", "文意推論"], "passage": "古之欲明明德於天下者，先治其國；欲治其國者，先齊其家；欲齊其家者，先脩其身。", "translation": "古代想要讓光明的德行彰顯於天下的人，必須先治理好自己的國家；想治理好國家，必須先整頓好自己的家；想整頓好家，必須先修養好自身。", "keywords": [{"w": "明明德", "m": "彰顯光明的德行（第一個明是動詞）"}, {"w": "齊", "m": "整頓、使和睦"}, {"w": "脩", "m": "同「修」，修養"}, {"w": "先", "m": "先做到（表示前提）"}], "questions": [{"n": 7, "stem": "周老師教到《大學》中的這段話：「古之欲明明德於天下者，先治其國；欲治其國者，先齊其家；欲齊其家者，先脩其身。」她請四位學生根據文意，以圖形來表示脩身和治國之間的關係，下列哪張圖形最恰當？", "options": {"A": "脩身、治國呈反比的直線圖", "B": "由「脩身」一階一階往上走到「治國」的階梯圖", "C": "脩身、治國放在天平兩端的平衡圖", "D": "脩身、治國呈反比的曲線圖"}, "answer": "B", "explain": "原文是層層推進的關係：先修身→才能齊家→才能治國→才能平天下，修身是基礎、治國在更高一層，像爬樓梯一樣，所以是階梯圖(B)。(A)(D)表示一方增加另一方就減少，與原文相反；(C)天平表示兩者對等、互相抗衡，也不合「由近及遠、循序漸進」的意思。", "skill": "找出「欲A者，先B」的句式，把條件一層層排出先後順序，再判斷圖形是遞進還是對立"}], "difficulty": "易", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-12", "exam": "bc98-1", "nums": [12], "form": "單題", "img": "img/bc98-1-12.png", "source": "命題自撰文言句", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "(A)功成身退，君子行也／(B)事端紛紜，唯君察之／(C)區區小事，豈足道哉／(D)此珍物也，安能棄之", "translation": "(A)功業成就後就退隱，這是君子的作為。(B)事情頭緒紛亂繁多，希望您明察。(C)小小的事情，哪裡值得說呢？(D)這是珍貴的東西，怎麼能丟掉呢？", "keywords": [{"w": "唯", "m": "希望（表期望、請求）"}, {"w": "察", "m": "明察、詳細審查"}, {"w": "豈", "m": "哪裡、難道（反問）"}, {"w": "安", "m": "怎麼（反問）"}, {"w": "也", "m": "句末表判斷"}], "questions": [{"n": 12, "stem": "下列文句，何者帶有期望語氣？", "options": {"A": "功成身退，君子行也", "B": "事端紛紜，唯君察之", "C": "區區小事，豈足道哉", "D": "此珍物也，安能棄之"}, "answer": "B", "explain": "(B)「唯君察之」的「唯」表示希望，意思是「希望您明察」，帶有期望語氣。(A)「……也」是判斷句；(C)「豈足道哉」是反問，意思是不值得一提；(D)「安能棄之」也是反問，意思是不能丟掉。", "skill": "先找句中虛詞：「唯、願、幸、請」多表期望；「豈、安、何」多表反問；「也」多表判斷"}], "difficulty": "中", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-13", "exam": "bc98-1", "nums": [13], "form": "單題", "img": "img/bc98-1-13.png", "source": "出處待查", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "奢者心常貧，儉者心常富。", "translation": "奢侈的人心裡常常覺得不夠（貧乏），節儉的人心裡常常覺得滿足（富足）。", "keywords": [{"w": "奢者", "m": "奢侈的人"}, {"w": "心常貧", "m": "心裡常覺得不足"}, {"w": "儉者", "m": "節儉的人"}], "questions": [{"n": 13, "stem": "「奢者心常貧，儉者心常富。」這句話的涵義，與下列何者最接近？", "options": {"A": "奢華常導致貧窮，儉樸才可以致富", "B": "財富滿足不了欲望，知足則心靈愉悅", "C": "妄求財富未必有所得，不求未必無所獲", "D": "合義則千金不為妄用，妄用雖一錢亦為奢侈"}, "answer": "B", "explain": "關鍵在「心」：說的是心裡的貧富感受，而不是實際的財產。奢侈的人欲望無窮，再多錢也覺得不夠；節儉的人知足，心裡就覺得富足，選(B)。(A)講實際的貧富，忽略了「心」；(C)講求與得的關係；(D)講花錢是否合理，都不合。", "skill": "注意句中限定詞「心」：判斷講的是物質層面還是心理層面，再找同一層面的選項"}], "difficulty": "易", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-18", "exam": "bc98-1", "nums": [18], "form": "單題", "img": "img/bc98-1-18.png", "source": "《弟子規》", "author": "李毓秀", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "見人善，即思齊，縱去遠，以漸躋；見人惡，即內省，有則改，無加警。", "translation": "看到別人的優點，就想著向他看齊，即使相差很遠，也要慢慢趕上；看到別人的缺點，就反省自己，如果自己也有就改正，沒有就更加警惕。", "keywords": [{"w": "齊", "m": "看齊、達到同等"}, {"w": "縱", "m": "即使"}, {"w": "去", "m": "距離"}, {"w": "躋", "m": "登、升（題目注釋）"}, {"w": "內省", "m": "自我反省"}, {"w": "警", "m": "警惕"}], "questions": [{"n": 18, "stem": "「見人善，即思齊，縱去遠，以漸躋；見人惡，即內省，有則改，無加警。」這段話的涵義，與下列何者最接近？", "options": {"A": "君子之善德，其道行中庸", "B": "見善如不及，見不善如探湯", "C": "責人惡宜寬諒，責己善宜苛謹", "D": "欲人勿惡先自美，欲人勿疑先自信"}, "answer": "B", "explain": "原文分兩面：見到善要努力追上，見到惡要反省警惕。(B)出自《論語》，「看到善行就像怕追不上一樣努力，看到不善就像手碰到滾燙的水一樣趕快避開」，同樣是見善學習、見惡警惕，最接近。(A)講君子行中庸之道；(C)講責備別人要寬、要求自己要嚴；(D)講要別人不厭惡、不懷疑，先要自己做好，都沒有「見善、見惡」的兩面對照。", "skill": "把原文拆成「見善→怎麼做」「見惡→怎麼做」兩個條件，找也具備同樣兩組對應的選項"}], "difficulty": "中", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-19", "exam": "bc98-1", "nums": [19], "form": "單題", "img": "img/bc98-1-19.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "夫民之生也，德慧有別，未有無益於世者。", "translation": "人生在世，品德和智慧各有不同，但沒有一個人是對世界沒有用處的。", "keywords": [{"w": "夫", "m": "發語詞，無義"}, {"w": "德慧", "m": "品德與智慧"}, {"w": "別", "m": "差別"}, {"w": "未有", "m": "沒有"}, {"w": "益", "m": "好處、幫助"}], "questions": [{"n": 19, "stem": "「夫民之生也，德慧有別，未有無益於世者。」這句話的涵義，與下列何者最接近？", "options": {"A": "夫天生一人，自有一人之用", "B": "聖賢之所以為聖，只是好學下問", "C": "聰明才智愈大者，當服千萬人之務", "D": "人一能之己百之；人十能之己千之"}, "answer": "A", "explain": "原文重點：人的才德雖有差別，但每個人都對社會有用。(A)「上天生下一個人，自然有這個人的用處」，意思相同。(B)講聖賢因好學而成聖；(C)講能力越大責任越大；(D)出自《中庸》，講別人努力一分自己就努力百分，都不合。", "skill": "抓句子的轉折：前半「有別」是讓步，後半「未有無益」才是重點，用重點去比對選項"}], "difficulty": "易", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-22", "exam": "bc98-1", "nums": [22], "form": "單題", "img": "img/bc98-1-22.png", "source": "除夕詩句（出處待查）", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "詩詞賞析"], "passage": "吟罷明朝贈知己，便須題作去年詩。", "translation": "今晚吟完這首詩，明天早上要送給知己時，就得標題為「去年的詩」了。（因為今晚是除夕，一過午夜就是新年）", "keywords": [{"w": "罷", "m": "完畢"}, {"w": "明朝", "m": "明天早上"}, {"w": "知己", "m": "好朋友"}, {"w": "去年", "m": "已過去的那一年"}, {"w": "殘臘", "m": "農曆年底十二月將盡"}], "questions": [{"n": 22, "stem": "「吟罷明朝贈知己，便須題作去年詩。」根據詩意，作者寫下這兩句詩的節日，與下列何者相同？", "options": {"A": "千門開鎖萬燈明，正月中旬動帝京", "B": "七夕今宵看碧霄，牽牛織女渡河橋", "C": "平分秋色一輪滿，長伴雲衢千里明", "D": "殘臘已隨梅雪盡，一夜春隨爆竹來"}, "answer": "D", "explain": "今晚寫的詩，到明早就成了「去年詩」，表示今晚是一年的最後一夜——除夕。(D)「殘臘已盡」「一夜春隨爆竹來」寫舊年結束、新春隨爆竹到來，也是除夕。(A)正月中旬、萬燈齊明是元宵節；(B)牛郎織女是七夕；(C)平分秋色、一輪滿月是中秋節。", "skill": "從「時間跨年」的線索推出節日，再找各選項的節日關鍵詞（燈、牛女、滿月、爆竹）"}], "difficulty": "易", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-23", "exam": "bc98-1", "nums": [23], "form": "單題", "img": "img/bc98-1-23.png", "source": "《孝經‧紀孝行章》", "author": "", "genre": "經典語錄", "types": ["句意理解", "字詞解釋"], "passage": "事親者，居上不驕，為下不亂，在醜不爭。居上而驕則亡，為下而亂則刑，在醜而爭則兵。三者不除，雖日用三牲之養，猶為不孝也。", "translation": "侍奉父母的人，身居高位不驕傲，身居下位不作亂，在同輩之中不爭鬥。居高位而驕傲就會敗亡，居下位而作亂就會受刑罰，在同輩中爭鬥就會引起兵刃相殺。這三種行為不去除，即使每天用牛、羊、豬三牲奉養父母，仍然是不孝。", "keywords": [{"w": "事親", "m": "侍奉父母"}, {"w": "醜", "m": "通「儔」，同輩（題目注釋）"}, {"w": "亡", "m": "敗亡"}, {"w": "刑", "m": "受刑罰"}, {"w": "兵", "m": "兵刃相加、爭鬥"}, {"w": "三牲", "m": "牛、羊、豬"}], "questions": [{"n": 23, "stem": "「事親者，居上不驕，為下不亂，在醜不爭。居上而驕則亡，為下而亂則刑，在醜而爭則兵。三者不除，雖日用三牲之養，猶為不孝也。」關於這段文字的說明，下列何者錯誤？", "options": {"A": "居上位而驕縱，就會招來禍患以致敗亡", "B": "居下位而違法亂紀，必定會觸法而受制裁", "C": "在同儕中若是爭強鬥狠，必定會引起對立衝突", "D": "「三者不除」句中「三者」指不驕、不亂、不爭"}, "answer": "D", "explain": "「三者不除」是說這三種毛病不去除，要去除的當然是壞行為，所以「三者」指驕、亂、爭，而不是不驕、不亂、不爭，(D)錯誤。(A)對應「居上而驕則亡」；(B)對應「為下而亂則刑」；(C)對應「在醜而爭則兵」，都正確。", "skill": "代名詞題：把「三者」代回句子（三者不除＝不去除○○），看代入「不驕」是否說得通"}], "difficulty": "中", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-25", "exam": "bc98-1", "nums": [25], "form": "單題", "img": "img/bc98-1-25.png", "source": "書論（出處待查）", "author": "", "genre": "說理議論", "types": ["句意理解", "寫作手法"], "passage": "臨帖如驟遇異人，不必相其耳目手足頭面，當觀其舉止笑語精神流露處。", "translation": "臨摹字帖就像突然遇到一位不平凡的人，不必仔細端詳他的耳朵眼睛手腳頭臉，而應該觀察他舉止談笑之間流露出來的精神。", "keywords": [{"w": "臨帖", "m": "照著字帖練字"}, {"w": "驟", "m": "突然"}, {"w": "異人", "m": "不平凡的人"}, {"w": "相", "m": "仔細看、端詳"}, {"w": "當", "m": "應該"}], "questions": [{"n": 25, "stem": "「臨帖如驟遇異人，不必相其耳目手足頭面，當觀其舉止笑語精神流露處。」這句話的涵義，與下列何者最接近？", "options": {"A": "好字帖如世外異人，可遇而不可求", "B": "善於察言觀色的人，則必善於臨摹字帖", "C": "用心臨摹各家字帖，即可領悟書法之神髓", "D": "臨帖重在字的精神意趣，而非專注筆畫架構"}, "answer": "D", "explain": "這是比喻：看人不只看五官外貌（＝字的筆畫結構），而要看神情氣質（＝字的精神意趣）。所以臨帖重在精神，選(D)。(A)誤把重點放在字帖難得；(B)把比喻當真，扯到察言觀色；(C)只說用心臨摹就能領悟，沒有抓到「重神不重形」。", "skill": "比喻句要做「對應翻譯」：耳目手足頭面→筆畫結構；精神流露→字的神韻"}], "difficulty": "中", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-29", "exam": "bc98-1", "nums": [29], "form": "單題", "img": "img/bc98-1-29.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "在古人之後，議古人之失，易；處古人之位，為古人之事，則難。", "translation": "生在古人之後，議論古人的過失很容易；如果身處古人的地位，去做古人當時的事，就很困難了。", "keywords": [{"w": "議", "m": "議論、批評"}, {"w": "失", "m": "過失"}, {"w": "處", "m": "處在"}, {"w": "為", "m": "做"}], "questions": [{"n": 29, "stem": "「在古人之後，議古人之失，易；處古人之位，為古人之事，則難。」這句話的涵義，與下列何者最接近？", "options": {"A": "事非經過不知難", "B": "當局者迷，旁觀者清", "C": "不可以律己之律律人", "D": "今之視古，亦猶後之視今"}, "answer": "A", "explain": "這句話對比「說（批評）」與「做」：批評很容易，真正去做才知道困難，正是(A)「事情沒有親身經歷，就不知道它的困難」。(B)強調「看得清不清楚」，不是做事的難易；(C)講不要用要求自己的標準要求別人；(D)講後人看今人就像今人看古人，都不合。(B)重點在「迷」與「清」，而非「難」與「易」。", "skill": "抓出題幹的對照軸（議＝易 vs. 為＝難），再找同一對照軸的選項，不被「古今」「旁觀」等表面字眼帶走"}], "difficulty": "中", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-31", "exam": "bc98-1", "nums": [31], "form": "單題", "img": "img/bc98-1-31.png", "source": "詠諸葛亮聯語（出處待查）", "author": "", "genre": "其他", "types": ["典故出處", "人物情感"], "passage": "已知天定三分國，猶竭人謀六出師。", "translation": "已經知道天命注定天下三分，仍然竭盡人的智謀六次出兵北伐。", "keywords": [{"w": "天定", "m": "天命注定"}, {"w": "三分國", "m": "天下分為魏、蜀、吳三國"}, {"w": "猶", "m": "仍然"}, {"w": "竭", "m": "用盡"}, {"w": "六出師", "m": "指諸葛亮多次出兵北伐（傳統說法六出祁山）"}], "questions": [{"n": 31, "stem": "「已知天定三分國，猶竭人謀六出師。」根據句意，這句話主要在呈現哪一種人格特質？", "options": {"A": "明知難成，勉力為之", "B": "權宜變通，能屈能伸", "C": "能識時務，果決英明", "D": "博古通今，謹行慎謀"}, "answer": "A", "explain": "上句「已知天定三分國」是明知統一天下很難成功；下句「猶竭人謀六出師」是仍然盡全力出兵，表現「明知不可為而為之」的精神，選(A)。(B)能屈能伸是懂得退讓變通；(C)識時務是順應時勢，與「明知天定仍盡力」相反；(D)講學問廣博、行事謹慎，句中未提。", "skill": "注意「已知……猶……」的轉折句式：前面是困難的事實，後面是仍然堅持的行動"}], "difficulty": "易", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-45", "exam": "bc98-1", "nums": [45, 46], "form": "題組", "img": "img/bc98-1-45.png", "source": "《新百喻經》", "author": "", "genre": "寓言故事", "types": ["人物情感", "寫作手法", "文意推論"], "passage": "魯公治園，欲鑿池，父曰：「無地置土。」公遂止。或曰：「土可疊山。」公善之，欲行。妻曰：「不畏小兒女顛躓耶？」公復止。或曰：「築徑通之，設欄護之，又何憂焉？」公從之，又欲行。家人有止之者：「園成，必添僕婦，下房不足，甚可慮也。」公猶疑不能決，事又寢。", "translation": "魯公整修庭園，想挖一座水池。父親說：「挖出來的土沒地方放。」魯公就停止了。有人說：「土可以堆成假山。」魯公認為很好，又想動工。妻子說：「不怕小孩子跌進池裡嗎？」魯公又停止了。有人說：「修條小路通過去，再裝欄杆保護，還擔心什麼呢？」魯公聽從了，又想動工。家人中又有勸阻的：「園子完成後，一定要增加僕人，下人住的房間不夠，很值得擔心啊。」魯公猶豫不決，這件事又停下來了。", "keywords": [{"w": "治", "m": "整修"}, {"w": "鑿", "m": "挖"}, {"w": "遂", "m": "就"}, {"w": "或", "m": "有人"}, {"w": "善之", "m": "認為它很好"}, {"w": "顛躓", "m": "跌倒（題目注釋：躓，音ㄓˋ）"}, {"w": "復", "m": "又"}, {"w": "寢", "m": "停止（題目注釋）"}], "questions": [{"n": 45, "stem": "根據這則故事，下列何者不適合用來形容魯公治園的態度？", "options": {"A": "躊躇游移", "B": "舉棋不定", "C": "口不應心", "D": "優柔寡斷"}, "answer": "C", "explain": "魯公一聽反對就停、一聽建議又想做，反覆不定，最後還是「猶疑不能決」，所以(A)躊躇游移、(B)舉棋不定、(D)優柔寡斷都很適合。(C)「口不應心」是嘴上說的和心裡想的不一樣，文中魯公並沒有表裡不一，不適合。", "skill": "先歸納人物的一貫行為模式（止→欲行→止→欲行→寢），再逐一檢查成語是否符合，注意題目問「不適合」"}, {"n": 46, "stem": "關於這則故事的寫作手法，下列敘述何者正確？", "options": {"A": "藉由景物的描寫來寄託人生的哲理", "B": "運用故事情節諷刺奢華的生活態度", "C": "通過他人的批判來說明事物的道理", "D": "透過人物舉止對話來凸顯人物性格"}, "answer": "D", "explain": "文中透過眾人的對話（父、或、妻、家人）與魯公的反應（遂止、善之、復止、從之）來呈現他優柔寡斷的性格，選(D)。(A)文中沒有景物描寫；(B)諷刺的是猶豫不決，不是奢華；(C)他人的話是勸阻或建議，不是批判，重點也不是說明事物道理。雖未寫出魯公的言詞，從「遂止」「善之」「復止」可知他確有回應，仍以(D)為最佳答案。", "skill": "寫作手法題：先確認文章主要由什麼構成（對話＋動作），再看它服務什麼目的（凸顯性格）"}], "difficulty": "易", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-1-47", "exam": "bc98-1", "nums": [47, 48], "form": "題組", "img": "img/bc98-1-47.png", "source": "敦煌曲子詞〈鵲踏枝〉", "author": "唐代無名氏", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感", "文意推論"], "passage": "叵耐靈鵲多謾語，送喜何曾有憑據？幾度飛來活捉取，鎖上金籠休共語。比擬好心來送喜，誰知鎖我在金籠裡。欲他征夫早歸來，騰身卻放我向青雲裡。", "translation": "（思婦說：）真受不了這靈鵲老是說謊，送來的喜訊何曾有過根據？牠幾次飛來，我就把牠活捉，鎖進金籠裡不再和牠說話。（靈鵲說：）我本來好心來報喜，誰知道她把我鎖在金籠裡。但願她出征的丈夫早點回來，她就會把我放出來，讓我騰身飛向青雲裡。", "keywords": [{"w": "叵耐", "m": "不能忍耐（題目注釋）"}, {"w": "謾語", "m": "謊話（題目注釋）"}, {"w": "何曾", "m": "哪裡曾經（反問）"}, {"w": "休", "m": "不要"}, {"w": "比擬", "m": "本來打算（題目注釋）"}, {"w": "征夫", "m": "出征在外的丈夫"}], "questions": [{"n": 47, "stem": "這闋詞是透過靈鵲和思婦的對話來表達「閨怨」的主題。思婦將靈鵲鎖在金籠裡的原因最可能是下列何者？", "options": {"A": "報喜總是無憑據", "B": "捉取安慰寂寞人", "C": "萬里傳信予征夫", "D": "靈鵲乃是吉祥物"}, "answer": "A", "explain": "思婦說「叵耐靈鵲多謾語，送喜何曾有憑據」——喜鵲一再報喜，丈夫卻始終沒回來，她氣喜鵲說謊，才把牠鎖起來，選(A)。(B)不是為了安慰自己；(C)詞中沒有託牠傳信；(D)吉祥物不是鎖牠的原因。", "skill": "找因果：鎖籠（結果）前面一句通常就是原因，先翻譯「何曾有憑據」"}, {"n": 48, "stem": "詞中思婦的心情與下列何者最接近？", "options": {"A": "無辜遭殃，氣憤難平", "B": "期待落空，鬱悶惱怒", "C": "物是人非，不堪回首", "D": "睹物思人，悲從中來"}, "answer": "B", "explain": "思婦一次次期待丈夫歸來（喜鵲報喜），卻一次次落空，於是遷怒喜鵲、把牠鎖起來，心情是期待落空後的鬱悶與惱怒，選(B)。(A)「無辜遭殃」說的是喜鵲的處境，不是思婦；(C)「物是人非」是景物依舊、人事已變；(D)「睹物思人」是看到舊物想念人而悲傷，詞中重點是氣喜鵲說謊。", "skill": "分清楚說話者：上片是思婦、下片是喜鵲，問誰的心情就只看誰的話"}], "difficulty": "中", "label": "98年第一次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-2", "exam": "bc98-2", "nums": [2], "form": "單題", "img": "img/bc98-2-2.png", "source": "《韓非子‧說林上》", "author": "韓非", "genre": "史傳人物", "types": ["文意推論", "句意理解"], "passage": "公子糾將為亂，桓公使使者視之，使者報曰：「笑不樂，視不見，必為亂。」乃使魯人殺之。", "translation": "公子糾將要作亂，齊桓公派使者去觀察他。使者回來報告說：「他笑的時候並不快樂，看東西的時候視而不見（心不在焉），一定會作亂。」桓公就讓魯國人殺了他。", "keywords": [{"w": "將", "m": "將要"}, {"w": "使", "m": "派遣（第一個「使」）"}, {"w": "視", "m": "觀察；看"}, {"w": "報", "m": "回報"}, {"w": "乃", "m": "於是"}], "questions": [{"n": 2, "stem": "「公子糾將為亂，桓公使使者視之，使者報曰：『笑不樂，視不見，必為亂。』乃使魯人殺之。」這則故事中，使者是根據公子糾哪一方面的表現來判斷他必定作亂？", "options": {"A": "生活作息", "B": "胸襟氣量", "C": "行為舉止", "D": "學識才能"}, "answer": "C", "explain": "使者的根據是「笑不樂，視不見」：笑起來不像真的快樂，看東西心不在焉，這些都是外在的神情動作，屬於行為舉止，選(C)。文中沒有提到他的作息(A)、器量(B)或學問能力(D)。", "skill": "找出使者「報曰」的內容當證據，再判斷這些證據屬於哪一類（表情動作＝行為舉止）"}], "difficulty": "易", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-3", "exam": "bc98-2", "nums": [3], "form": "單題", "img": "img/bc98-2-3.png", "source": "《中說》（文中子）", "author": "王通", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "君子不責人所不及，不強人所不能。", "translation": "君子不會責怪別人做不到的事，也不會勉強別人做能力以外的事。", "keywords": [{"w": "責", "m": "要求、責備"}, {"w": "不及", "m": "達不到"}, {"w": "強", "m": "音ㄑㄧㄤˇ，勉強"}], "questions": [{"n": 3, "stem": "「君子不責人所不及，不強人所不能。」這句話的涵義，與下列何者最接近？", "options": {"A": "對待眾人應當一視同仁", "B": "對自己嚴格，待他人寬厚", "C": "自己能做到，才能要求別人", "D": "要求別人時須考量他的能力"}, "answer": "D", "explain": "「所不及」「所不能」都是指別人能力達不到的地方，君子不去責備、不去勉強，也就是要求別人時要考慮對方的能力，選(D)。(A)講公平對待；(B)講嚴以律己、寬以待人，原文沒談對自己的要求；(C)講以身作則，也不合。", "skill": "抓住「所不及、所不能」這兩個名詞片語的共同指向（能力的極限），再找扣住「能力」的選項"}], "difficulty": "易", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-7", "exam": "bc98-2", "nums": [7], "form": "單題", "img": "img/bc98-2-7.png", "source": "出處待查", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "終日抄藥方，不能療一疾；終日寫路程，不能行一步。", "translation": "整天抄寫藥方，也治不好一種病；整天寫路程，也不能真的往前走一步。", "keywords": [{"w": "終日", "m": "整天"}, {"w": "療", "m": "治療"}, {"w": "疾", "m": "疾病"}], "questions": [{"n": 7, "stem": "「終日抄藥方，不能療一疾；終日寫路程，不能行一步。」這句話的涵義與下列何者最接近？", "options": {"A": "身無斬龍刀，也敢下東海", "B": "在河灘上沉思，永遠得不到珍珠", "C": "浪再高也在船底，山再高也在腳底", "D": "驢子就算出去旅行，回家仍變不成駿馬"}, "answer": "B", "explain": "抄藥方、寫路程都只是紙上作業，不去實際做就沒有效果，強調要付諸行動。(B)只在河灘上想，不下水去找，永遠得不到珍珠，同樣強調空想無用、要行動。(A)說沒有本事卻膽子大（不自量力）；(C)說困難終究可以克服；(D)說本質難以改變，都不合。", "skill": "找兩組例子的共同結構（只做準備、不實際行動→沒結果），再用同樣結構去比對選項"}], "difficulty": "易", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-8", "exam": "bc98-2", "nums": [8], "form": "單題", "img": "img/bc98-2-8.png", "source": "出處待查", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "言語簡寡，在我可以少悔，在人可以少怨。", "translation": "說話簡短少量，對自己來說可以減少後悔，對別人來說可以減少怨恨。", "keywords": [{"w": "簡寡", "m": "簡短而少"}, {"w": "在我", "m": "對自己來說"}, {"w": "在人", "m": "對別人來說"}, {"w": "約", "m": "簡約、少（選項A）"}], "questions": [{"n": 8, "stem": "「言語簡寡，在我可以少悔，在人可以少怨。」這句話的涵義，與下列何者最接近？", "options": {"A": "多言則必失，不如其約也", "B": "君子言有信，而行之有恆", "C": "辭有所未盡，意有所未竭", "D": "好論人長短，學者之大病"}, "answer": "A", "explain": "題幹主張說話要少，才能少後悔、少招怨。(A)「話說多了一定會有過失，不如說得簡約」，同樣主張少說話，最接近。(B)講說話守信、做事有恆；(C)講文辭沒說完、意思還沒窮盡（含蓄）；(D)講喜歡議論別人長短是讀書人的大毛病，只談到「說什麼」而不是「說多少」。", "skill": "先抓主張（言語要少），再比對選項是否同樣主張「少說」，注意(D)只是部分相關"}], "difficulty": "中", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-9", "exam": "bc98-2", "nums": [9], "form": "單題", "img": "img/bc98-2-9.png", "source": "〈賦得暮雨送李胄〉", "author": "韋應物", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "楚江微雨裡，建業暮鐘時。漠漠帆來重，冥冥鳥去遲。海門深不見，浦樹遠含滋。相送情無限，沾襟比散絲。", "translation": "楚地的長江籠罩在微雨中，正是建業城傍晚鐘聲響起的時候。雨中的船帆沉沉地駛來，昏暗的天空中鳥兒緩緩飛去。長江入海口深遠看不見，岸邊的樹在遠處浸潤著水氣。送別的情意無窮無盡，淚水沾濕衣襟就像飄散的雨絲。", "keywords": [{"w": "漠漠", "m": "迷濛的樣子"}, {"w": "冥冥", "m": "昏暗的樣子"}, {"w": "海門", "m": "長江入海口"}, {"w": "浦", "m": "水邊"}, {"w": "含滋", "m": "含著水氣"}, {"w": "沾襟", "m": "淚水沾濕衣襟"}, {"w": "散絲", "m": "飄散的雨絲"}], "questions": [{"n": 9, "stem": "以下是一首送別的五言律詩，大意是說：「在建業的長江渡口，此刻微雨飄灑江面，附近寺廟傳來淒涼的晚鐘聲，目送你的船隻伴著天空的飛鳥，緩緩前行。遙望長江入海處，一片煙雨迷濛，遠山近樹都浸潤在無邊的雨霧中，滿懷深情送別的我，淚水如無盡的雨絲，沾濕了衣襟。」根據詩意，下列畫線處依序應填入何者？　楚江微雨裡，＿＿＿。漠漠帆來重，冥冥鳥去遲。＿＿＿，＿＿＿。＿＿＿，沾襟比散絲。　甲、浦樹遠含滋　乙、建業暮鐘時　丙、相送情無限　丁、海門深不見", "options": {"A": "甲、丙、丁、乙", "B": "甲、乙、丙、丁", "C": "乙、丁、甲、丙", "D": "乙、甲、丁、丙"}, "answer": "C", "explain": "依大意順序：先交代地點時間「建業」「晚鐘」→乙接在「楚江微雨裡」後，「時」也押韻。中間「遙望長江入海處……遠山近樹浸潤雨霧」→先丁「海門深不見」再甲「浦樹遠含滋」（滋押韻，且丁、甲對仗：海門／浦樹、深／遠、不見／含滋）。最後「滿懷深情送別」→丙「相送情無限」接「沾襟比散絲」。所以是乙、丁、甲、丙，選(C)。", "skill": "三管齊下：照白話大意排順序、偶數句要押韻（時、遲、滋、絲）、中間兩聯要對仗"}], "difficulty": "中", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-10", "exam": "bc98-2", "nums": [10], "form": "單題", "img": "img/bc98-2-10.png", "source": "古典詩句（選項）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "(A)暮春還舊嶺，徙倚玩年華。芳草無行逕，空山正落花。(B)芳草五陵道，美人金犢車。綠奔穿內水，紅落過牆花。(C)芳草和煙暖更青，閒門要路一時生。年年點檢人間事，惟有春風不世情。(D)啼鵑聲聲喚春去，離心催掛天邊樹。垂楊密密拂行裝，芳草萋萋礙行路。", "translation": "(A)暮春回到舊日山嶺，徘徊欣賞春光；芳草長滿看不到小路，空山裡花正凋落。(B)五陵大道長滿芳草，美人坐著金飾牛車；綠水奔流穿過宮內，紅花落下越過牆頭。(C)芳草在煙霧中暖得更青，冷清的門前和熱鬧的大路同時長出；年年檢點人間的事，只有春風不懂人情冷暖。(D)杜鵑聲聲把春天喚走，離別的心像掛在天邊的樹上；密密的垂柳拂過行裝，茂盛的芳草阻礙遠行的路。", "keywords": [{"w": "徙倚", "m": "徘徊"}, {"w": "萋萋", "m": "草木茂盛的樣子"}, {"w": "離心", "m": "離別的心情"}, {"w": "礙", "m": "阻礙"}, {"w": "世情", "m": "世俗人情（勢利）"}], "questions": [{"n": 10, "stem": "詩詞中常以「草」象徵離情別緒。下列詩句中的「芳草」，何者可用以象徵離情？", "options": {"A": "暮春還舊嶺，徙倚玩年華。芳草無行逕，空山正落花", "B": "芳草五陵道，美人金犢車。綠奔穿內水，紅落過牆花", "C": "芳草和煙暖更青，閒門要路一時生。年年點檢人間事，惟有春風不世情", "D": "啼鵑聲聲喚春去，離心催掛天邊樹。垂楊密密拂行裝，芳草萋萋礙行路"}, "answer": "D", "explain": "(D)有「離心」「行裝」「行路」，是送行、離別的情境，「芳草萋萋礙行路」好像芳草不捨行人離開，象徵離情，選(D)。(A)寫暮春山中景色；(B)寫繁華熱鬧的春遊；(C)藉芳草在冷門、熱路一樣生長，說春風不勢利，都與離別無關。", "skill": "找全句中的「離別線索詞」（離、行、送、別），確認芳草出現在離別情境裡"}], "difficulty": "中", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-17", "exam": "bc98-2", "nums": [17], "form": "單題", "img": "img/bc98-2-17.png", "source": "《世說新語‧德行》", "author": "劉義慶", "genre": "筆記小品", "types": ["句意理解", "主旨寓意"], "passage": "王朗每以識度推華歆。歆蜡日，嘗集子姪燕飲，王亦學之。有人向張華說此事，張曰：「王之學華，皆是形骸之外，去之所以更遠。」", "translation": "王朗常常因為華歆的見識和度量而推崇他。華歆曾在年終蜡祭那天召集子姪們宴飲，王朗也跟著學。有人把這件事告訴張華，張華說：「王朗學華歆，學的都只是外在的形式，所以離華歆反而更遠了。」", "keywords": [{"w": "識度", "m": "見識與度量（題目注釋）"}, {"w": "推", "m": "推崇"}, {"w": "蜡", "m": "音ㄓㄚˋ，年終祭禮（題目注釋）"}, {"w": "燕", "m": "通「宴」（題目注釋）"}, {"w": "形骸之外", "m": "外在形跡"}, {"w": "去", "m": "距離"}], "questions": [{"n": 17, "stem": "「王朗每以識度推華歆。歆蜡日，嘗集子姪燕飲，王亦學之。有人向張華說此事，張曰：『王之學華，皆是形骸之外，去之所以更遠。』」故事裡張華話語的涵義，與下列何者最接近？", "options": {"A": "徒然模仿外在行止而不事內在修為，難得神髓", "B": "具備良好的外在行為，是涵養心性的基礎工夫", "C": "適度的效法賢者，可以修正自我行為的缺失", "D": "虛心的學習態度，可以超越預先期待的成效"}, "answer": "A", "explain": "王朗佩服的是華歆的「識度」（內在），卻只模仿請子姪宴飲這種外在活動，張華批評他只學到「形骸之外」，反而離得更遠，正是(A)只模仿外表、不修內在，學不到精髓。(B)(C)(D)都是肯定學習的效果，與張華的批評相反。", "skill": "對照「王朗佩服什麼（識度）」與「王朗學了什麼（宴飲形式）」的落差，就能讀出批評"}], "difficulty": "中", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-19", "exam": "bc98-2", "nums": [19], "form": "單題", "img": "img/bc98-2-19.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "文意推論"], "passage": "人性有變與不變之異。其不變者，歷艱難險阻不改其志。變者有二，其一雖變，尚能復其本性；其一則變而日趨下流，終不能復其性矣。", "translation": "人的本性有改變與不改變的差別。不改變的人，經歷艱難險阻也不改變志向。改變的人有兩種：一種雖然改變了，還能恢復原本的善良本性；另一種則是改變後一天天往下墮落，終究無法恢復本性了。", "keywords": [{"w": "異", "m": "不同"}, {"w": "歷", "m": "經歷"}, {"w": "尚", "m": "還"}, {"w": "復", "m": "恢復"}, {"w": "日趨下流", "m": "一天天趨向卑下"}], "questions": [{"n": 19, "stem": "「人性有變與不變之異。其不變者，歷艱難險阻不改其志。變者有二，其一雖變，尚能復其本性；其一則變而日趨下流，終不能復其性矣。」根據這段文字，下列哪一個人的行為符合「雖變，尚能復其本性」？", "options": {"A": "小敏天資聰穎，在某次考試作弊得逞後，從此食髓知味，養成作弊的壞習慣", "B": "小明一向倔強頑固，但在面臨校規記過處分的壓力下，也向對方低頭認錯了", "C": "小薇一直熱心助人，在接受校長的公開表揚後，更加積極投入社區公益活動", "D": "小華因誤交損友而經常蹺課，在老師耐心開導後，終於幡然悔悟，專心向學"}, "answer": "D", "explain": "「雖變，尚能復其本性」要有兩個階段：先變壞，再恢復原本的好。(D)小華因損友變壞蹺課，後來悔悟回到專心向學，符合。(A)變壞後越來越糟，是「日趨下流」；(B)是在壓力下低頭，不是恢復本性；(C)一直熱心助人，沒有變壞，是「不變」的一類。", "skill": "把文句拆成「變（變壞）→復（回到原本的好）」兩步驟，檢查選項是否兩步都有"}], "difficulty": "易", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-24", "exam": "bc98-2", "nums": [24], "form": "單題", "img": "img/bc98-2-24.png", "source": "命題自撰文言札記", "author": "", "genre": "筆記小品", "types": ["文化常識", "文意推論"], "passage": "時值新正，鳥鳴鶯啼，楊柳依依，好風拂面。向晚，至市遊逛，見眾孺子持燈把玩，驚覺佳節又居，遂歸，命奴僕入廚備應時之品。", "translation": "時間正值新年正月，鳥兒鳴叫、黃鶯啼唱，楊柳輕柔飄揚，和風吹在臉上。傍晚，到市集閒逛，看見許多小孩拿著燈籠玩耍，才驚覺佳節又到了，於是回家，吩咐僕人到廚房準備應景的食品。", "keywords": [{"w": "新正", "m": "農曆新年正月"}, {"w": "向晚", "m": "傍晚"}, {"w": "孺子", "m": "小孩"}, {"w": "居", "m": "到、處於"}, {"w": "遂", "m": "於是"}, {"w": "應時之品", "m": "應景的食品"}], "questions": [{"n": 24, "stem": "黃員外於晚間將當日所見寫成札記一則：「時值新正，鳥鳴鶯啼，楊柳依依，好風拂面。向晚，至市遊逛，見眾孺子持燈把玩，驚覺佳節又居，遂歸，命奴僕入廚備應時之品。」根據這段文字，下列敘述何者錯誤？", "options": {"A": "這篇生活札記寫於春天", "B": "員外黃昏時至市集遊逛", "C": "文中「佳節」應為中元節", "D": "奴僕所備之品可能是湯圓"}, "answer": "C", "explain": "「新正」是正月，「孺子持燈」是提燈籠，可知佳節是元宵節，不是中元節，(C)錯誤。(A)正月屬春天，又有鶯啼柳綠，正確；(B)「向晚」就是黃昏，正確；(D)元宵節應景食品是湯圓（元宵），正確。", "skill": "從時間詞（新正）和習俗線索（持燈）鎖定節日，再逐一檢查選項"}], "difficulty": "易", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-27", "exam": "bc98-2", "nums": [27], "form": "單題", "img": "img/bc98-2-27.png", "source": "古代笑話（出處待查）", "author": "", "genre": "寓言故事", "types": ["文意推論", "主旨寓意"], "passage": "一官至其轄地，百廢未舉，先行要錢，乃張告示曰：「為民父母，視爾如子。勤治精訓，安居樂業；阿堵物出，庶業其繁。」眾見而紛議，某老曰：「所謂父母者，都要人孝敬。」", "translation": "有位官員到他管轄的地方上任，各種荒廢的事務都還沒興辦，就先向百姓要錢，於是貼出告示說：「我是百姓的父母官，把你們看作自己的孩子。我會勤加治理、用心教導，讓你們安居樂業；只要把錢拿出來，各行各業就會興盛。」大家看了議論紛紛，有位老人說：「所謂的父母，都是要人孝敬的。」", "keywords": [{"w": "百廢未舉", "m": "各種荒廢的事都還沒興辦"}, {"w": "張", "m": "張貼"}, {"w": "爾", "m": "你們"}, {"w": "阿堵物", "m": "錢（題目注釋）"}, {"w": "庶", "m": "眾多；或解為「希望、或許」"}, {"w": "孝敬", "m": "雙關：孝順父母／送錢財給人"}], "questions": [{"n": 27, "stem": "「一官至其轄地，百廢未舉，先行要錢，乃張告示曰：『為民父母，視爾如子。勤治精訓，安居樂業；阿堵物出，庶業其繁。』眾見而紛議，某老曰：『所謂父母者，都要人孝敬。』」故事中「所謂父母者，都要人孝敬。」這句話的用意是下列何者？", "options": {"A": "諷刺為官者的厚顏貪婪", "B": "規勸為人子女者當行孝", "C": "表明父母皆盼子女孝順", "D": "說明好官必受人民愛戴"}, "answer": "A", "explain": "官員還沒做事就先要錢，還自稱「為民父母」。老人順著「父母」一詞說「都要人孝敬」，「孝敬」暗指送錢，是用雙關語挖苦這位官員貪財又厚臉皮，選(A)。(B)(C)只看字面；(D)故事中的官員並不是好官。", "skill": "讀笑話要找「雙關」：把老人的話放回情境，看「父母」「孝敬」在這裡實際指什麼"}], "difficulty": "中", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-30", "exam": "bc98-2", "nums": [30], "form": "單題", "img": "img/bc98-2-30.png", "source": "〈又答王庠書〉", "author": "蘇軾", "genre": "書信序跋", "types": ["句意理解", "比較閱讀"], "passage": "書富如入海，百貨皆有。人之精力不能兼收盡取，但得其所欲求者爾！", "translation": "書籍豐富就像進入大海，各種貨物都有。人的精力不可能全部收取，只能取得自己想要追求的部分罷了！", "keywords": [{"w": "富", "m": "豐富"}, {"w": "兼收盡取", "m": "全部收下取盡"}, {"w": "但", "m": "只"}, {"w": "爾", "m": "罷了"}, {"w": "約取", "m": "有選擇地精要擷取（選項D）"}], "questions": [{"n": 30, "stem": "蘇軾〈又答王庠書〉：「書富如入海，百貨皆有。人之精力不能兼收盡取，但得其所欲求者爾！」這句話的主要涵義，與下列何者最接近？", "options": {"A": "盡信書，則不如無書", "B": "讀書百遍，則其義自見", "C": "好高求速，學者之通患", "D": "學貴約取，不以泛濫為高"}, "answer": "D", "explain": "書海無邊，精力有限，所以要選擇自己需要的去讀，正是(D)「學習貴在精要選取，不以廣泛雜讀為高明」。(A)講讀書不可全信，要有判斷；(B)講反覆熟讀就能理解；(C)講好高騖遠、求快是讀書人的通病，都不合。", "skill": "抓轉折後的結論句「但得其所欲求者」＝有選擇地讀，再找講「選擇、精取」的選項"}], "difficulty": "易", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-31", "exam": "bc98-2", "nums": [31], "form": "單題", "img": "img/bc98-2-31.png", "source": "《孔子家語‧致思》", "author": "", "genre": "經典語錄", "types": ["句意理解", "字詞解釋"], "passage": "孔子將行，雨而無蓋。門人曰：「商也有之。」孔子曰：「商之為人也，甚吝於財，吾聞與人交，推其長者，違其短者，故能久也。」", "translation": "孔子要出門，下雨了卻沒有傘。學生說：「子夏有傘。」孔子說：「子夏的為人，對財物很吝嗇。我聽說和人交往，要推崇他的長處，避開他的短處，所以友誼才能長久。」", "keywords": [{"w": "蓋", "m": "雨傘（題目注釋）"}, {"w": "商", "m": "子夏的名（題目注釋）"}, {"w": "吝", "m": "吝嗇"}, {"w": "推", "m": "推崇、推許"}, {"w": "違", "m": "避開"}], "questions": [{"n": 31, "stem": "「孔子將行，雨而無蓋。門人曰：『商也有之。』孔子曰：『商之為人也，甚吝於財，吾聞與人交，推其長者，違其短者，故能久也。』」根據本文，「推其長者，違其短者」這句話的涵義與下列何者最接近？", "options": {"A": "多推許對方的長處，避開對方介意的事情", "B": "彼此以誠心相待，不計較對方的優劣長短", "C": "多多學習對方的優點，以改正自己的缺點", "D": "儘量宣揚對方的長處，誠懇規勸對方過失"}, "answer": "A", "explain": "孔子知道子夏吝於財物，所以不去向他借傘，避免觸碰他的短處，這就是「推其長、違其短」：推崇對方的優點，避開對方在意的缺點，選(A)。(B)說不計較長短，但孔子其實清楚對方的短處；(C)講自我改進，不是交友態度；(D)「規勸過失」與「違其短」（避開）相反。", "skill": "用故事情境驗證詞義：孔子「不借傘」就是「違其短」的具體表現，「違」＝避開"}], "difficulty": "中", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-40", "exam": "bc98-2", "nums": [40, 41], "form": "題組", "img": "img/bc98-2-40.png", "source": "《雞肋編》卷上", "author": "莊綽", "genre": "筆記小品", "types": ["文意推論", "句意理解", "文化常識"], "passage": "成都自上元至四月十八日，遊賞幾無虛辰。使宅後圃名西園，春時縱人行樂。初開園日，酒坊兩戶各求優人之善者，較藝於府會，以骰子置於合子中撼之，視數多者得先，謂之「撼雷」。自旦至暮，唯雜戲一色。坐於閱武場，環庭皆府官宅看棚。棚外始作高凳，庶民男左女右，立於其上如山。每諢一笑，須筵中鬨堂，眾庶皆噱者，始以青紅小旗各插於墊上為記，至晚較旗多者為勝。若上下不同笑者，不以為數也。", "translation": "成都從元宵節到四月十八日，遊樂賞玩幾乎沒有空閒的時候。官署後面的園子叫西園，春天時開放讓人遊樂。剛開園那天，兩家酒坊各自請來最好的演員，在府中比賽技藝。他們把骰子放在盒子裡搖，看點數多的先表演，稱為「撼雷」。從早到晚，只演雜戲一種。表演在閱武場舉行，場子四周都是官員家眷的看棚。看棚外面才搭高凳，百姓男的在左、女的在右，站在上面像山一樣。每次逗笑一回，必須筵席中的官員哄堂大笑，百姓也都笑了，才各插一面青色或紅色小旗在墊子上作記號，到晚上比較誰的旗子多就獲勝。如果上面（官眷）和下面（百姓）不是一起笑，就不算數。", "keywords": [{"w": "上元", "m": "元宵節"}, {"w": "虛辰", "m": "空閒的時刻"}, {"w": "縱", "m": "任憑、開放"}, {"w": "優人", "m": "演戲的人（題目注釋）"}, {"w": "合子", "m": "盒子"}, {"w": "一色", "m": "一種（題目注釋）"}, {"w": "諢", "m": "音ㄏㄨㄣˋ，戲謔、逗趣（題目注釋）"}, {"w": "鬨堂", "m": "滿堂大笑"}, {"w": "噱", "m": "音ㄐㄩㄝˊ，笑（題目注釋）"}], "questions": [{"n": 40, "stem": "文中觀眾的座位配置，最可能是下列何者？", "options": {"A": "舞臺在中央；內圈為看棚區（官眷），外圈為高凳區，庶民男左女右", "B": "內圈看棚區官眷分男左女右，外圈高凳區庶民不分男女", "C": "內圈為高凳區（庶民男左女右），外圈為看棚區（官眷）", "D": "內圈為高凳區庶民不分男女，外圈看棚區官眷分男左女右"}, "answer": "A", "explain": "「環庭皆府官宅看棚」：舞臺周圍一圈是官員家眷的看棚；「棚外始作高凳，庶民男左女右」：看棚外面才是高凳，百姓男左女右。所以內圈看棚（官眷）、外圈高凳（庶民男左、女右），是(A)。(B)把男左女右放到官眷；(C)(D)內外圈顛倒。", "skill": "圖表題：把方位詞（環、外、左、右）逐一圈出來，按「由內而外」畫出配置再對照"}, {"n": 41, "stem": "兩戶酒坊所請優人較藝的過程，下列何者可從本文中明確得知？", "options": {"A": "「撼雷」次數較多者優先表演", "B": "雜戲從上元節演到四月十八日", "C": "棚內棚外若未同笑則無法得旗", "D": "最後獲勝者可得青紅錦旗一面"}, "answer": "C", "explain": "「若上下不同笑者，不以為數也」：棚內官眷和棚外百姓沒有一起笑，就不能插旗計分，(C)正確。(A)「撼雷」是搖骰子，「數多者」指骰子點數多，不是撼雷次數多；(B)上元到四月十八日是遊賞期間，雜戲是在開園那天從早演到晚；(D)青紅小旗是計分用的，比的是旗子多寡，並沒有頒發錦旗。", "skill": "「明確得知」題：每個選項都要回原文找對應句，注意偷換的關鍵詞（點數→次數、計分小旗→錦旗）"}], "difficulty": "中", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-44", "exam": "bc98-2", "nums": [44, 45], "form": "題組", "img": "img/bc98-2-44.png", "source": "《說苑‧貴德》（改寫）", "author": "劉向", "genre": "史傳人物", "types": ["虛詞句式", "字詞解釋", "主旨寓意"], "passage": "晏子飲景公酒，命器必新。家老曰：「財不足，請斂於民。」晏子曰：「止！夫樂者，上下同之，無有獨樂。今上樂其樂，下傷其費，是獨樂者也。不可。」", "translation": "晏子請齊景公喝酒，吩咐器具一定要用新的。家臣說：「錢財不夠，請向百姓徵收。」晏子說：「停止！快樂這件事，應該上下共同享有，不能一個人獨享。如今在上位的人享受他的快樂，在下的百姓卻被這筆花費所傷害，這就是獨自享樂。不可以這樣做。」", "keywords": [{"w": "飲", "m": "音ㄧㄣˋ，請……喝"}, {"w": "命", "m": "命令、吩咐"}, {"w": "家老", "m": "家臣之長"}, {"w": "斂", "m": "徵收、搜刮"}, {"w": "樂其樂", "m": "以其樂為樂、享受他的快樂（前一個樂是動詞）"}, {"w": "費", "m": "花費、費用（名詞）"}], "questions": [{"n": 44, "stem": "下列「　」中的字，何者不是作動詞用？", "options": {"A": "「命」器必新", "B": "請「斂」於民", "C": "今上「樂」其樂", "D": "下傷其「費」"}, "answer": "D", "explain": "(D)「下傷其費」的「費」是「花費、費用」，前面有「其」修飾，是名詞，不是動詞。(A)「命」＝吩咐，動詞；(B)「斂」＝徵收，動詞；(C)「樂其樂」第一個「樂」＝享受（以……為樂），動詞，第二個樂才是名詞。", "skill": "判斷詞性看位置：「其＋○」多半是名詞；主語後、賓語前的字多半是動詞"}, {"n": 45, "stem": "根據本文，下列何者最可能是晏子的想法？", "options": {"A": "快樂是心靈的滿足，而不是物質上的享受", "B": "要有一顆能容納快樂的心，快樂才會降臨", "C": "快樂應同享，莫圖一己之樂而使他人痛苦", "D": "能為別人謀福利，是最富有、最快樂的人"}, "answer": "C", "explain": "晏子說「樂者，上下同之，無有獨樂」，又反對「上樂其樂，下傷其費」，主張快樂要上下共享，不能為了自己的快樂讓百姓受苦，選(C)。(A)講心靈與物質；(B)講心態；(D)講為人謀福最富有，都不是文中的重點。", "skill": "找人物直接說出的主張句（夫樂者……），並對照他反對的情況（獨樂、傷民）"}], "difficulty": "中", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc98-2-46", "exam": "bc98-2", "nums": [46, 47, 48], "form": "題組", "img": "img/bc98-2-46.png", "source": "葉國良〈李沆話中的弦外之音〉（引司馬光〈訓儉示康〉、《宋史‧選舉志》）", "author": "葉國良", "genre": "其他", "types": ["句意理解", "文化常識", "寫作手法"], "passage": "李文靖公為相，治居第於封丘門內，廳事前僅容旋馬。或言其太隘，公笑曰：「居第當傳子孫，此為宰相廳事誠隘，為太祝、奉禮廳事已寬矣。」／補蔭之制：……凡文臣，三公、宰相子，為諸寺丞；……。使相、參知政事、樞密院使、副使、宣徽使子，為太祝、奉禮郎。", "translation": "李沆當宰相時，在封丘門內建造住宅，廳堂前面只容得下一匹馬轉身。有人說太狹窄了，李沆笑著說：「住宅是要傳給子孫的，這作為宰相的廳堂確實狹窄，但作為太祝、奉禮郎（小官）的廳堂已經夠寬了。」／（《宋史》）補蔭的制度：凡是文官，三公、宰相的兒子，補任各寺的寺丞；……使相、參知政事、樞密院使、副使、宣徽使的兒子，補任太祝、奉禮郎。", "keywords": [{"w": "治", "m": "建造"}, {"w": "居第", "m": "住宅"}, {"w": "廳事", "m": "廳堂"}, {"w": "旋馬", "m": "讓馬轉身"}, {"w": "隘", "m": "狹窄"}, {"w": "誠", "m": "確實"}, {"w": "補蔭", "m": "憑父祖功勞，子孫免試補官"}], "questions": [{"n": 46, "stem": "李沆說：「居第當傳子孫，此為宰相廳事誠隘，為太祝、奉禮廳事已寬矣。」這句話的用意，應該是下列何者？", "options": {"A": "官場無常，若自己被貶為小官，廳堂大小已足夠", "B": "太祝、奉禮郎等小官，沒有能力將廳堂建得寬廣", "C": "子孫若只當上小官，現在留給他們的廳堂已夠寬", "D": "宰相留給子孫的居所宜寬，太祝、奉禮郎則相反"}, "answer": "C", "explain": "依宋代補蔭制度，李沆的子孫可以「補」太祝或奉禮郎這類小官。他說住宅要傳給子孫，子孫將來的身分是太祝、奉禮郎，那這廳堂對他們來說已經夠寬了，選(C)。(A)他講的是子孫，不是自己被貶；(B)不是說小官沒能力蓋大廳；(D)意思相反，他並不認為要留寬大的居所。", "skill": "代入背景知識：先查出「太祝、奉禮郎」和李沆子孫的關係，再解讀話中的弦外之音"}, {"n": 47, "stem": "本文引用《宋史‧選舉志》，最主要的目的是什麼？", "options": {"A": "彰顯李沆的說法有所依據", "B": "提升司馬光文章中的氣勢", "C": "分析宋代任官制度的得失", "D": "探討歷代宰相制度的演變"}, "answer": "A", "explain": "作者引《宋史‧選舉志》，是為了證明宰相等高官的兒子確實可補太祝、奉禮郎，讓李沆「為太祝、奉禮廳事已寬矣」這句話有制度上的根據，選(A)。文中沒有評論制度得失(C)或歷代演變(D)，也與司馬光文章的氣勢無關(B)。", "skill": "問「引用目的」：看引文前後在證明哪一句話"}, {"n": 48, "stem": "根據本文，下列何者最可能是作者所要傳達給讀者的主要訊息？", "options": {"A": "鼓勵人人立志建功業，因為子孫可以獲得庇蔭", "B": "了解各代的制度，有助於深入解讀當時的文章", "C": "為官當不忘節儉，美德傳家有益後人立身處世", "D": "建築私宅應考慮實際的需求，不可只講究排場"}, "answer": "B", "explain": "作者說「閱讀時，要掌握文章的涵義，必須清楚作品的時代背景及制度」，結尾也說懂得宋代補蔭制度就能理解李沆的語意，主旨是(B)。(C)是司馬光〈訓儉示康〉引此事的用意，不是本文作者的重點；(A)(D)文中沒有這樣的主張。", "skill": "找作者自己的議論句（閱讀時，要……），區分「引文作者的用意」與「本文作者的主旨」"}], "difficulty": "難", "label": "98年第二次基測", "year": 98, "kind": "基測"}, {"id": "bc99-1-3", "exam": "bc99-1", "nums": [3], "form": "單題", "img": "img/bc99-1-3.png", "source": "前半出自《呂氏春秋‧察今》（「嘗一脟肉，而知一鑊之味」），後半出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "比較閱讀"], "passage": "嘗一臠肉，知一鑊之味；見一飛羽，識風之所向。", "translation": "嘗一小塊肉，就知道整鍋的味道；看見一根飄飛的羽毛，就知道風吹的方向。", "keywords": [{"w": "臠", "m": "音ㄌㄨㄢˊ，小肉塊（題目注釋）"}, {"w": "鑊", "m": "音ㄏㄨㄛˋ，烹煮食物的器具（題目注釋）"}, {"w": "識", "m": "知道、辨認"}], "questions": [{"n": 3, "stem": "「嘗一臠肉，知一鑊之味；見一飛羽，識風之所向。」這句話的涵義，與下列哪一個成語最接近？", "options": {"A": "一得之見", "B": "一語中的", "C": "一葉知秋", "D": "一鱗半爪"}, "answer": "C", "explain": "兩句都是由一個小現象推知整體或趨勢：一塊肉→整鍋味道、一根羽毛→風向。(C)「一葉知秋」看到一片落葉就知道秋天來了，同樣是見微知著。(A)一得之見是自謙見解淺薄；(B)一語中的是一句話說中要點；(D)一鱗半爪比喻零碎片段，沒有「由小推大」的意思。", "skill": "找出兩組例子的共同結構「由小見大」，再挑出同樣結構的成語，不要被都有「一」字干擾"}], "difficulty": "易", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-9", "exam": "bc99-1", "nums": [9], "form": "單題", "img": "img/bc99-1-9.png", "source": "命題自撰邀約函", "author": "", "genre": "書信序跋", "types": ["文化常識", "字詞解釋"], "passage": "前日到貴府一敘，您的風範令我欽慕不已。明晚六時，特在寒舍敬備薄酒，與拙荊、小女恭候光臨，幸勿推卻。此請　王文龍先生　弟莊明智敬上　九月一日", "translation": "前天到您家聊天，您的風度令我非常敬佩仰慕。明天晚上六點，特別在我家準備了簡單的酒菜，和我的妻子、女兒恭敬地等候您光臨，希望不要推辭。敬請王文龍先生。弟莊明智敬上，九月一日。", "keywords": [{"w": "貴府", "m": "敬稱對方的家"}, {"w": "寒舍", "m": "謙稱自己的家"}, {"w": "薄酒", "m": "謙稱自己準備的酒菜"}, {"w": "拙荊", "m": "謙稱自己的妻子"}, {"w": "小女", "m": "謙稱自己的女兒"}, {"w": "幸勿", "m": "希望不要"}], "questions": [{"n": 9, "stem": "（邀約函見上）上面這封邀約函畫線部分，何者不是自謙之詞？", "options": {"A": "貴府", "B": "寒舍", "C": "薄酒", "D": "小女"}, "answer": "A", "explain": "「貴府」是稱呼對方的家，屬於敬稱，不是自謙，選(A)。「寒舍」謙稱自己的家、「薄酒」謙稱自己準備的酒菜、「小女」謙稱自己的女兒，都是自謙之詞。", "skill": "分清楚「稱對方用敬詞（貴、令、尊、高）」「稱自己用謙詞（寒、薄、拙、小、家、舍）」"}], "difficulty": "易", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-10", "exam": "bc99-1", "nums": [10], "form": "單題", "img": "img/bc99-1-10.png", "source": "命題自撰文言句", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "(A)臣與人寡合，不為當權所容／(B)苟不為叛臣，則可謂良將矣／(C)豈有食君祿而不為國致死耶／(D)安祿山若不為亂，唐豈中衰", "translation": "(A)我和人很少合得來，不被當權的人所容納。(B)如果不當叛臣，就可以說是好將領了。(C)哪有吃國君的俸祿卻不替國家效死的呢？(D)安祿山如果不作亂，唐朝哪會中途衰落？", "keywords": [{"w": "為……所", "m": "被……（被動句式）"}, {"w": "寡合", "m": "很少與人合得來"}, {"w": "苟", "m": "如果"}, {"w": "祿", "m": "俸祿"}, {"w": "致死", "m": "獻出生命"}], "questions": [{"n": 10, "stem": "「不為利誘」的「為」字是「被」的意思，下列文句中的「為」字，何者也是相同的意思？", "options": {"A": "臣與人寡合，不「為」當權所容", "B": "苟不「為」叛臣，則可謂良將矣", "C": "豈有食君祿而不「為」國致死耶", "D": "安祿山若不「為」亂，唐豈中衰"}, "answer": "A", "explain": "(A)「為當權所容」是「為……所……」的被動句，「為」＝被，不被當權者容納，選(A)。(B)「為叛臣」的「為」是「當、成為」；(C)「為國致死」的「為」讀ㄨㄟˋ，是「替」；(D)「為亂」的「為」是「作、做」。", "skill": "看到「為……所……」優先判斷為被動；其餘把「被、當、替、做」逐一代入試讀"}], "difficulty": "中", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-15", "exam": "bc99-1", "nums": [15], "form": "單題", "img": "img/bc99-1-15.png", "source": "選項出自蘇軾〈記承天寺夜遊〉、陶淵明〈五柳先生傳〉、周敦頤〈愛蓮說〉、劉禹錫〈陋室銘〉", "author": "", "genre": "其他", "types": ["字詞解釋", "典故出處"], "passage": "(A)但少閑人如吾兩人耳／(B)每有會意，便欣然忘食／(C)予獨愛蓮之出淤泥而不染／(D)無絲竹之亂耳，無案牘之勞形", "translation": "(A)只是缺少像我們兩個這樣的閒人罷了。(B)每當對書中道理有所領會，就高興得忘了吃飯。(C)我唯獨喜愛蓮花從汙泥中長出卻不被沾染。(D)沒有音樂擾亂耳朵，沒有公文使身體勞累。", "keywords": [{"w": "閑人", "m": "清閒的人（偏正：閑修飾人）"}, {"w": "會意", "m": "領會意旨（動賓）"}, {"w": "淤泥", "m": "汙泥（偏正：淤修飾泥）"}, {"w": "絲竹", "m": "絲（弦樂器）與竹（管樂器），代指音樂（並列）"}, {"w": "案牘", "m": "公文"}], "questions": [{"n": 15, "stem": "「化干戈為玉帛」句中「干戈」一詞，是由可各自獨立的「干」與「戈」兩個詞以並列的方式結合而成，兩者之間不互相修飾。下列文句「　」中的詞彙，何者也是同樣的構成方式？", "options": {"A": "但少「閑人」如吾兩人耳", "B": "每有「會意」，便欣然忘食", "C": "予獨愛蓮之出「淤泥」而不染", "D": "無「絲竹」之亂耳，無案牘之勞形"}, "answer": "D", "explain": "「絲竹」的「絲」指弦樂器、「竹」指管樂器，兩者地位相等、各自獨立，是並列結構，選(D)。(A)「閑人」是「清閒的人」，閑修飾人；(C)「淤泥」是淤積的泥，淤修飾泥，都是偏正結構；(B)「會意」是「領會（動詞）＋意旨（受詞）」，是動賓結構。", "skill": "把詞拆成兩字，問「前一字是在形容後一字嗎？」是→偏正；是動作加對象→動賓；兩者平等→並列"}], "difficulty": "中", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-16", "exam": "bc99-1", "nums": [16], "form": "單題", "img": "img/bc99-1-16.png", "source": "張潮語（出處待查，或出《幽夢影》）", "author": "張潮", "genre": "經典語錄", "types": ["句意理解", "文意推論"], "passage": "不治生產，其後必致累人；專務交遊，其後必致累己。", "translation": "不經營產業謀生，將來一定會拖累別人；一心只忙著交朋友應酬，將來一定會拖累自己。", "keywords": [{"w": "治", "m": "經營"}, {"w": "生產", "m": "產業、謀生的事業"}, {"w": "致", "m": "導致"}, {"w": "累", "m": "拖累"}, {"w": "務", "m": "致力於"}], "questions": [{"n": 16, "stem": "張潮說：「不治生產，其後必致累人；專務交遊，其後必致累己。」根據這句話，下列哪種人最可能累人累己？", "options": {"A": "仰賴祖產度日，又好交友嬉遊的富家子弟", "B": "不懂農業生產之道，只管業務行銷的商人", "C": "不計旅費是多是少，都堅持要行萬里路的人", "D": "冷落待產的妻子，只管在外交際應酬的丈夫"}, "answer": "A", "explain": "要「累人累己」必須同時具備兩個條件：不治生產（累人）＋專務交遊（累己）。(A)靠祖產過日子（不經營產業）又愛交友玩樂，兩項都符合。(B)「生產」被誤解為農業生產，且商人有在工作；(C)講旅行；(D)「待產」是生小孩，把「生產」的意思偷換了。", "skill": "注意古今詞義差異：「生產」在這裡是謀生的產業，不是生小孩或農業；再確認兩個條件都要符合"}], "difficulty": "中", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-17", "exam": "bc99-1", "nums": [17], "form": "單題", "img": "img/bc99-1-17.png", "source": "〈送隱者一絕〉", "author": "杜牧", "genre": "古典詩詞曲", "types": ["詩詞賞析", "句意理解"], "passage": "公道世間唯白髮，貴人頭上不曾饒。", "translation": "世間最公平的只有白髮，就算是富貴的人，它也從不放過，照樣長在他們頭上。", "keywords": [{"w": "公道", "m": "公平"}, {"w": "唯", "m": "只有"}, {"w": "饒", "m": "饒恕、放過"}], "questions": [{"n": 17, "stem": "「公道世間唯白髮，貴人頭上不曾饒。」詩句中的涵義與下列何者最接近？", "options": {"A": "達官貴人心裡的皺紋，遠比他們臉上的皺紋多", "B": "時間是公正的法官，他一視同仁地對待所有人", "C": "歲月絕對是公平的，他給你一些，也帶走一些", "D": "頂上白髮催人老，極易引發內心的憂懼與徬徨"}, "answer": "B", "explain": "白髮代表時間、衰老，不管貴賤都會降臨，強調時間對每個人一視同仁，選(B)。(A)講貴人憂愁多；(C)講歲月有得有失；(D)講白髮引起憂愁，都沒有扣住「公平對待所有人、貴人也不例外」。", "skill": "先找象徵（白髮＝時光老去），再抓關鍵詞「公道」「不曾饒」＝對誰都一樣"}], "difficulty": "易", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-20", "exam": "bc99-1", "nums": [20], "form": "單題", "img": "img/bc99-1-20.png", "source": "畫論（出處待查）", "author": "", "genre": "說理議論", "types": ["句意理解", "文意推論"], "passage": "凡畫梅意在筆先，伸紙熟視，隱隱間若有枝幹橫斜，花蕊蕭疏之意，或正或欹，或濃或淡，形象神理，宛在目前，然後舉筆落墨，自有佳境。", "translation": "凡是畫梅花，構想要在下筆之前。攤開紙仔細看，隱隱約約好像看到枝幹橫斜、花蕊疏落的樣子，有正有斜，有濃有淡，形狀和神韻好像就在眼前，然後才提筆落墨，自然能畫出好作品。", "keywords": [{"w": "意在筆先", "m": "構思在下筆之前"}, {"w": "熟視", "m": "仔細看"}, {"w": "蕭疏", "m": "稀疏"}, {"w": "欹", "m": "音ㄑㄧ，傾斜（題目注釋）"}, {"w": "宛", "m": "好像"}], "questions": [{"n": 20, "stem": "「凡畫梅意在筆先，伸紙熟視，隱隱間若有枝幹橫斜，花蕊蕭疏之意，或正或欹，或濃或淡，形象神理，宛在目前，然後舉筆落墨，自有佳境。」根據這段文字所述，畫梅的最佳方法是下列何者？", "options": {"A": "細細點畫，著意求工", "B": "臨花描摹，務求神似", "C": "構思於胸，振筆從之", "D": "先繪草圖，依圖設色"}, "answer": "C", "explain": "「意在筆先」「形象神理，宛在目前，然後舉筆落墨」：先在心中構思好梅花的樣子，再一揮而就，正是(C)「胸中先構思，再提筆照著畫」（胸有成竹）。(A)講細細琢磨；(B)講對著真花描摹，文中是看著白紙想像；(D)文中沒有先畫草圖。", "skill": "抓首句總綱「意在筆先」，再確認過程：想像在前、下筆在後，且是在腦中而非紙上打草稿"}], "difficulty": "中", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-27", "exam": "bc99-1", "nums": [27], "form": "單題", "img": "img/bc99-1-27.png", "source": "《墨子‧修身》", "author": "墨子", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "士雖有學，而行為本焉。", "translation": "讀書人雖然有學問，但品行才是根本。", "keywords": [{"w": "士", "m": "讀書人"}, {"w": "行", "m": "音ㄒㄧㄥˋ，品行（題目注釋）"}, {"w": "本", "m": "根本"}, {"w": "崇", "m": "高"}], "questions": [{"n": 27, "stem": "墨子云：「士雖有學，而行為本焉。」這句話的涵義與下列何者最接近？", "options": {"A": "人不學則無以有懿德", "B": "善學者，假人之長以補其短", "C": "君子不患知之不博，而患德之不崇", "D": "業精於勤，荒於嬉；行成於思，毀於隨"}, "answer": "C", "explain": "墨子強調學問之外，品德才是根本。(C)「君子不擔心知識不夠廣博，而擔心品德不夠崇高」，同樣把德行放在學問之上，最接近。(A)講學習才能有美德，重點在「學」；(B)講善於學習的人借別人長處補自己短處；(D)出自韓愈〈進學解〉，講學業靠勤奮、德行靠思考，沒有比較學與德的輕重。", "skill": "題幹是「學」與「行」的輕重比較，選項也要有同樣的比較並把德行放在前面"}], "difficulty": "中", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-28", "exam": "bc99-1", "nums": [28], "form": "單題", "img": "img/bc99-1-28.png", "source": "書法家書信（出處待查）", "author": "", "genre": "書信序跋", "types": ["人物情感", "文意推論"], "passage": "兄屢言吾書玄妙，冠絕當世，他人多以為過譽；惟君慧眼，相知甚深，難卻爾。得此知己，夫復何求？今奉數字，祈觀。", "translation": "老兄常說我的字玄妙，當代第一，別人大多認為誇獎過頭了；只有您眼光獨到，對我了解很深，我也就難以推辭了。得到這樣的知己，還有什麼好要求的呢？現在奉上幾幅字，請您觀賞。", "keywords": [{"w": "書", "m": "書法"}, {"w": "冠絕", "m": "超出眾人，居第一"}, {"w": "過譽", "m": "誇獎過頭"}, {"w": "惟", "m": "只有"}, {"w": "卻", "m": "推辭"}, {"w": "爾", "m": "罷了、而已"}, {"w": "夫復何求", "m": "還有什麼要求呢"}, {"w": "祈", "m": "請求"}], "questions": [{"n": 28, "stem": "某書法家在給朋友的信中說：「兄屢言吾書玄妙，冠絕當世，他人多以為過譽；惟君慧眼，相知甚深，難卻爾。得此知己，夫復何求？今奉數字，祈觀。」這位書法家對朋友的讚賞抱持何種態度？", "options": {"A": "摯友過譽，難以領受", "B": "欲迎還拒，謙虛推辭", "C": "深得我心，感念相知", "D": "受寵若驚，無法置信"}, "answer": "C", "explain": "書法家說別人認為是過譽，但只有朋友慧眼識才、了解很深，所以「難卻」（不好推辭，就接受了），又說「得此知己，夫復何求」，可見他欣然接受並感激朋友的知遇，選(C)。(A)(B)說他推辭，與「難卻」相反；(D)他並沒有不敢相信。", "skill": "注意轉折詞「惟」後面才是書法家真正的態度，並把「難卻」「夫復何求」翻譯正確"}], "difficulty": "中", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-31", "exam": "bc99-1", "nums": [31], "form": "單題", "img": "img/bc99-1-31.png", "source": "〈五柳先生傳〉", "author": "陶淵明", "genre": "史傳人物", "types": ["人物情感", "比較閱讀"], "passage": "不戚戚於貧賤，不汲汲於富貴。", "translation": "不為貧窮卑賤而憂愁，不急切地追求富貴。", "keywords": [{"w": "戚戚", "m": "憂愁的樣子"}, {"w": "汲汲", "m": "急切追求的樣子"}, {"w": "簞食瓢飲", "m": "一竹筐飯、一瓢水，指生活簡樸"}, {"w": "鳶飛戾天", "m": "老鷹飛到天上，比喻追求高位"}], "questions": [{"n": 31, "stem": "「不戚戚於貧賤，不汲汲於富貴。」這句話所呈現的精神，與下列何者最接近？", "options": {"A": "蓬門敝戶可安居，簞食瓢飲亦怡然", "B": "奢者富而不足，何如儉者貧而有餘", "C": "君子之道，居勞苦則能忍，處富樂則能謙", "D": "鳶飛戾天者，望峰息心；經綸世務者，窺谷忘返"}, "answer": "A", "explain": "題幹表現安貧樂道、不求富貴的精神。(A)住破屋也能安居，粗茶淡飯也很快樂，最接近。(B)比較奢與儉的心理，重點在節儉；(C)講處勞苦能忍、處富樂能謙，是面對境遇的修養，沒有「不求富貴」；(D)出自吳均〈與宋元思書〉，講美景使人忘卻名利，重點在山水的感染力。", "skill": "抓題幹兩面：對貧賤不憂、對富貴不求，再找「安於貧窮且自得其樂」的選項"}], "difficulty": "中", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-32", "exam": "bc99-1", "nums": [32], "form": "單題", "img": "img/bc99-1-32.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "比較閱讀"], "passage": "小人亦有所長，不可惡其人而忽其是；君子亦有所失，不可好其人而飾其非。", "translation": "小人也有長處，不可以因為討厭他這個人就忽略他對的地方；君子也有過失，不可以因為喜歡他這個人就掩飾他錯的地方。", "keywords": [{"w": "惡", "m": "音ㄨˋ，討厭"}, {"w": "是", "m": "對的地方"}, {"w": "好", "m": "音ㄏㄠˋ，喜歡"}, {"w": "飾", "m": "掩飾"}, {"w": "非", "m": "錯誤"}], "questions": [{"n": 32, "stem": "「小人亦有所長，不可惡其人而忽其是；君子亦有所失，不可好其人而飾其非。」這句話的涵義，與下列何者最接近？", "options": {"A": "小人好惡以己，君子好惡以道", "B": "君子揚人之善，小人揚人之惡", "C": "好君子而知其過，惡小人而知其美", "D": "待小人投其所好，待君子責其所非"}, "answer": "C", "explain": "題幹要人客觀評價：不因厭惡而忽略小人的優點，不因喜愛而掩飾君子的缺點。(C)「喜歡君子也知道他的過錯，討厭小人也知道他的優點」，意思相同。(A)(B)比較君子與小人的不同作為；(D)教人迎合小人、苛責君子，與原文相反。", "skill": "題幹是「好惡不影響判斷」的對稱句，找同樣兼顧「好其人知其過、惡其人知其美」的選項"}], "difficulty": "中", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-33", "exam": "bc99-1", "nums": [33], "form": "單題", "img": "img/bc99-1-33.png", "source": "命題自撰七言絕句", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "〈臨別〉：暮雨初晴月上軒，丹楓蕭瑟滿山院。憑欄無語癡相牽，百感中來不忍言。", "translation": "傍晚的雨剛停，月亮升上窗前，紅楓蕭瑟地落滿山中庭院。靠著欄杆默默無語，癡癡地拉著彼此的手，種種感觸湧上心頭，卻不忍心說出口。", "keywords": [{"w": "軒", "m": "窗、長廊"}, {"w": "蕭瑟", "m": "秋風吹拂、草木凋零的樣子"}, {"w": "憑欄", "m": "靠著欄杆"}, {"w": "中來", "m": "從心中湧起"}, {"w": "平聲韻", "m": "押平聲字的韻（如軒、園、言）"}], "questions": [{"n": 33, "stem": "張生以平聲韻習作七言絕句一首，詩題〈臨別〉：「暮雨初晴月上軒，丹楓蕭瑟滿山院。憑欄無語癡相牽，百感中來不忍言。」關於這首詩的說明，下列何者錯誤？", "options": {"A": "前兩句詩著重景物的描寫，呈現出黃昏入夜的秋景", "B": "後兩句詩著重情感的抒發，表達出久別重逢的心情", "C": "因本詩為平聲韻，第二句末字改為「園」字才合律", "D": "本詩第三句末字不須押韻，改為「對」字即可合律"}, "answer": "B", "explain": "詩題是〈臨別〉，「無語癡相牽」「不忍言」是離別前的不捨，不是久別重逢，(B)錯誤。(A)暮雨、月上、丹楓是黃昏入夜的秋景，正確；(C)七絕首句與偶數句要押韻，「院」是仄聲，改成平聲的「園」才和軒、言押韻，正確；(D)第三句不押韻，句尾宜用仄聲，「牽」是平聲，改為仄聲的「對」才合律，正確。", "skill": "近體詩格律：一、二、四句押韻（平聲），第三句不押韻（仄聲收尾）；情感判斷別忘了看詩題"}], "difficulty": "難", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-45", "exam": "bc99-1", "nums": [45, 46], "form": "題組", "img": "img/bc99-1-45.png", "source": "《述異記》（改寫）", "author": "任昉", "genre": "筆記小品", "types": ["句意理解", "文意推論", "字詞解釋"], "passage": "陸機少時，頗好遊獵。在吳豪盛，客獻快犬名曰黃耳。機後仕洛，常將自隨。此犬黠慧，能解人語。又嘗借人三百里外，犬識路自還，一日至家。機羈旅京師，久無家問，因戲語犬曰：「我家絕無書信，汝能齎書馳取消息不？」犬喜搖尾作聲應之。機試為書，盛以竹筒，繫之犬頸。犬出驛路，疾走向吳，飢則入草噬肉取飽。每經大水，輒依渡者，弭耳掉尾向之，其人憐愛，因呼上船。纔近岸，犬即騰上，速去如飛。徑至機家，口銜筒作聲示之。機家開筒取書，看畢，犬又向人作聲，如有所求；其家作答書內筒，復繫犬頸。犬既得答，仍馳還洛。計人程五旬，而犬往還纔半月。", "translation": "陸機年輕時很喜歡打獵。他在吳地時家世豪盛，有客人送他一隻跑得很快的狗，名叫黃耳。陸機後來到洛陽做官，常帶著牠。這隻狗聰明伶俐，能聽懂人話。有一次牠被借到三百里外，竟能自己認路回家，一天就到了。陸機客居京城，很久沒有家裡的消息，就開玩笑地對狗說：「我家一直沒有信來，你能帶著信跑回去打聽消息嗎？」狗高興地搖尾巴叫著回應。陸機就試著寫了信，裝進竹筒，綁在狗的脖子上。狗沿著驛道，快速奔向吳地，餓了就到草叢裡吃肉吃飽。每次經過大河，就靠近渡河的人，垂著耳朵、搖著尾巴向他們示好，那些人覺得可憐可愛，就叫牠上船。船剛靠岸，牠就跳上岸，飛快地離開。牠直接跑到陸機家，用嘴銜著竹筒叫，讓家人看。陸家打開竹筒拿出信看完，狗又對人叫，好像在要求什麼；家人就寫了回信放進竹筒，再綁回牠的脖子上。狗拿到回信後，又跑回洛陽。算起來人走要五十天的路程，狗來回才花半個月。", "keywords": [{"w": "將", "m": "帶著"}, {"w": "黠慧", "m": "聰明伶俐"}, {"w": "羈旅", "m": "寄居他鄉"}, {"w": "家問", "m": "家中的音訊"}, {"w": "齎", "m": "音ㄐㄧ，拿、持（題目注釋）"}, {"w": "不", "m": "同「否」，句末表疑問"}, {"w": "輒", "m": "就、總是"}, {"w": "弭耳", "m": "貼垂雙耳（題目注釋）"}, {"w": "纔", "m": "才、剛"}, {"w": "旬", "m": "十天"}], "questions": [{"n": 45, "stem": "根據上下文判斷，文中「我家絕無書信」的意思與下列何者最接近？", "options": {"A": "無人可以幫忙送信回家", "B": "很久沒有收到家中音訊", "C": "斷絕了寫信回家的念頭", "D": "家人絕對沒有寫信給我"}, "answer": "B", "explain": "前一句「機羈旅京師，久無家問」，說陸機在京城很久沒有家裡的消息，所以「我家絕無書信」是說一直沒收到家裡來信，選(B)。(A)他後來就叫狗送信，不是沒人送；(C)他並沒有斷絕寫信念頭；(D)「絕對沒有寫」是把「絕」誤解成絕對，他只是沒收到，不知家人寫沒寫。", "skill": "用上文「久無家問」來解釋下文；「絕無」在這裡是「完全沒有（收到）」"}, {"n": 46, "stem": "下列何者無法看出此犬具備對人示意的能力？", "options": {"A": "嘗借人三百里外，犬識路自還，一日至家", "B": "犬喜搖尾作聲應之", "C": "每經大水，輒依渡者，弭耳掉尾向之", "D": "犬又向人作聲，如有所求"}, "answer": "A", "explain": "(A)只說明狗會認路、跑得快，沒有對人表達意思。(B)搖尾叫聲回應陸機；(C)垂耳搖尾向渡河的人示好求助；(D)對陸家人叫，好像有所要求，都是對人示意。", "skill": "「示意」要有「對象（人）＋表達動作（搖尾、作聲）」，逐項檢查是否兩者都有"}], "difficulty": "中", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-1-47", "exam": "bc99-1", "nums": [47, 48], "form": "題組", "img": "img/bc99-1-47.png", "source": "無名氏筆記", "author": "", "genre": "筆記小品", "types": ["虛詞句式", "文意推論", "人物情感"], "passage": "袁海叟避禍時，佯狂自辱，令家人以糖拌米，潛置籬落間，公匍匐食之。時，上命公為本府教授，使者見取食不潔，遂奏為真病，得免。", "translation": "袁海叟為了躲避災禍，假裝發瘋來羞辱自己。他叫家人用糖拌米，偷偷放在籬笆邊，他就趴在地上爬過去吃。當時皇帝任命他擔任本府的教授，使者看見他撿髒東西吃，就回奏說他真的瘋了，袁海叟因此免去了任命。", "keywords": [{"w": "佯狂", "m": "假裝發瘋"}, {"w": "潛", "m": "偷偷地"}, {"w": "籬落", "m": "籬笆"}, {"w": "匍匐", "m": "趴在地上爬行"}, {"w": "上", "m": "皇帝"}, {"w": "遂", "m": "於是"}, {"w": "奏", "m": "向皇帝報告"}, {"w": "免", "m": "免除（任命）"}], "questions": [{"n": 47, "stem": "下列文句中的主語，何者不是指袁海叟？", "options": {"A": "佯狂自辱", "B": "取食不潔", "C": "遂奏為真病", "D": "得免"}, "answer": "C", "explain": "「遂奏為真病」是使者回去向皇帝報告，主語是使者，選(C)。(A)假裝發瘋的是袁海叟；(B)「使者見（袁海叟）取食不潔」，撿髒東西吃的是袁海叟；(D)免除任命的也是袁海叟。", "skill": "文言常省略主語：每個動作都問「誰做的？」，從前後文補回來"}, {"n": 48, "stem": "根據本文，下列關於袁海叟的敘述，何者正確？", "options": {"A": "家境清貧，只能以糖拌米為食", "B": "精神狀況時好時壞，不太穩定", "C": "不懂用餐禮儀，難以擔任朝廷官職", "D": "不願意接受朝廷的任命，擔任教授"}, "answer": "D", "explain": "他是「避禍」而「佯狂」（假裝瘋），故意讓使者看到他爬在地上吃東西，結果「得免」，可見他不想接受任命，選(D)。(A)糖拌米是裝瘋的道具，不是因為窮；(B)他是假裝的，精神並沒有問題；(C)不是不懂禮儀，而是故意表演。", "skill": "抓住關鍵字「佯」（假裝）與「避禍」，推出行為背後的真正目的"}], "difficulty": "中", "label": "99年第一次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-8", "exam": "bc99-2", "nums": [8], "form": "單題", "img": "img/bc99-2-8.png", "source": "出處待查", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "世上憐才休恨少，平生失學古來多；天公有意君知否？大器還須小折磨。", "translation": "世上愛惜人才的人不多，不必怨恨；一生中失意落第的人，自古以來就很多。你知道老天爺的用意嗎？成大器的人，還是需要經過一些小小的磨練。", "keywords": [{"w": "憐才", "m": "愛惜人才"}, {"w": "休", "m": "不要"}, {"w": "失學", "m": "此指考試失利、求取功名不順"}, {"w": "大器", "m": "大才、能成大事的人"}, {"w": "折磨", "m": "磨練"}], "questions": [{"n": 8, "stem": "「世上憐才休恨少，平生失學古來多；天公有意君知否？大器還須小折磨。」這首詩最適合用在下列哪一個情境中？", "options": {"A": "安慰考場失利的考生", "B": "送給出國留學的朋友", "C": "祝福資賦優異的學生", "D": "讚許努力不懈的同學"}, "answer": "A", "explain": "詩中說懷才不遇、失意的人自古就多，老天是要用小挫折磨練大才，是在安慰受挫的人，最適合送給考試失利的考生，選(A)。(B)留學送別、(C)祝福資優、(D)讚許努力，都沒有「受挫需要安慰」的情境。", "skill": "找詩中情境線索（休恨、失學、折磨）判斷對象正在受挫，再找需要「安慰」的情境"}], "difficulty": "易", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-10", "exam": "bc99-2", "nums": [10], "form": "單題", "img": "img/bc99-2-10.png", "source": "出處待查", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "士君子碌碌一生，百事無成，只因無志。", "translation": "讀書人庸庸碌碌過一輩子，什麼事都做不成，只因為沒有立下志向。", "keywords": [{"w": "士君子", "m": "讀書人、有德行的人"}, {"w": "碌碌", "m": "平庸無所作為"}, {"w": "志", "m": "志向"}], "questions": [{"n": 10, "stem": "「士君子碌碌一生，百事無成，只因無志。」句中的涵義，與下列何者最接近？", "options": {"A": "有志向的人，從不期待他人的讚美", "B": "處身安樂環境中的人往往立志不廣", "C": "心志愈高，愈容易在小地方犯錯", "D": "沒有不立志而可以成就事業的人"}, "answer": "D", "explain": "原文說一事無成的原因是沒有志向，反過來說就是：要成就事業一定要先立志，選(D)。(A)講不求讚美；(B)講環境影響志向；(C)講志高易犯小錯，都與「無志則無成」無關。", "skill": "把「無成，只因無志」轉成同義的雙重否定「沒有不立志而能成功的」"}], "difficulty": "易", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-16", "exam": "bc99-2", "nums": [16], "form": "單題", "img": "img/bc99-2-16.png", "source": "選項為文言格言（(D)出自《菜根譚》）", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "(A)處富貴而知好禮，則不驕不淫／(B)揚之過高易落，屈尊方能求榮／(C)處事不必邀功，無過便是有功／(D)君子之才玉韞珠藏，不須張揚", "translation": "(A)身處富貴而懂得喜好禮節，就不會驕傲放縱。(B)捧得太高容易跌落，放低身段才能求得榮耀。(C)做事不必搶功勞，沒有過錯就是功勞。(D)君子的才華像美玉藏在匣中、珍珠藏在深處，不必向外張揚。", "keywords": [{"w": "淫", "m": "放縱過度"}, {"w": "邀功", "m": "求取功勞"}, {"w": "韞", "m": "音ㄩㄣˋ，收藏"}, {"w": "張揚", "m": "宣揚炫耀"}], "questions": [{"n": 16, "stem": "「真正的貴族從不談家世，有才氣的人從不談自己作品。」這句話的涵義與下列何者最接近？", "options": {"A": "處富貴而知好禮，則不驕不淫", "B": "揚之過高易落，屈尊方能求榮", "C": "處事不必邀功，無過便是有功", "D": "君子之才玉韞珠藏，不須張揚"}, "answer": "D", "explain": "題幹說真正有身分、有才華的人不會到處炫耀。(D)君子的才華像藏起來的美玉明珠，不需要張揚，意思相同。(A)講富貴者要守禮；(B)講要放低身段才能得到榮耀；(C)講不要搶功，都不是「有才而不炫耀」。", "skill": "抓題幹的核心動作「不談」＝不炫耀，再找有「藏、不張揚」意思的選項"}], "difficulty": "易", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-21", "exam": "bc99-2", "nums": [21], "form": "單題", "img": "img/bc99-2-21.png", "source": "選項為文言格言（(C)出自《禮記‧學記》）", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "(A)積學於己，以待用之也／(B)知己之不足，則學有進／(C)時過然後學，則勤苦而難成／(D)志趣不遠，心不在焉，雖學無成", "translation": "(A)在自己身上累積學問，等待將來使用。(B)知道自己的不足，學問就會進步。(C)錯過了學習的時機才去學，就會辛苦又難有成就。(D)志向不遠大，心思不專注，即使學習也不會有成就。", "keywords": [{"w": "積學", "m": "累積學問"}, {"w": "待", "m": "等待"}, {"w": "進", "m": "進步"}, {"w": "時過", "m": "錯過時機"}], "questions": [{"n": 21, "stem": "「學習的首要條件，在於承認自己不懂；若你自認什麼都懂，勢必無法聽進任何新知識。」這句話的涵義與下列何者最接近？", "options": {"A": "積學於己，以待用之也", "B": "知己之不足，則學有進", "C": "時過然後學，則勤苦而難成", "D": "志趣不遠，心不在焉，雖學無成"}, "answer": "B", "explain": "題幹強調要先承認自己不懂，才能學到新東西。(B)「知道自己的不足，學問才會進步」，意思最接近。(A)講累積學問以備將來；(C)講學習要把握時機；(D)講志向與專心，都沒提到「承認不足」。", "skill": "抓題幹關鍵條件「承認自己不懂」，找含「知己之不足」的選項"}], "difficulty": "易", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-25", "exam": "bc99-2", "nums": [25], "form": "單題", "img": "img/bc99-2-25.png", "source": "唐代筆記（事見《唐朝名畫錄》等，出處待查）", "author": "", "genre": "筆記小品", "types": ["文意推論", "句意理解"], "passage": "唐裴將軍旻，居喪，請吳道子畫天宮壁度亡母。道子曰：「將軍為我舞劍一回，庶因猛厲以通幽冥。」旻脫縗衣，纏結，上馬馳驟，揮劍入雲，高十數丈，若電光下射，執鞘承之，劍透室而入，觀者驚慄。道子援筆奮袂如風，畫壁立就。", "translation": "唐朝的裴旻將軍在為母親守喪，請吳道子在天宮寺牆上作畫，超度他過世的母親。吳道子說：「請將軍為我舞一回劍，希望藉著那股猛烈的氣勢，讓我的畫能通達陰間。」裴旻脫下喪服，綁好衣服，騎上馬奔馳，把劍拋向雲端，高達十幾丈，像閃電一樣落下，他拿著劍鞘去接，劍穿進劍鞘裡，觀看的人都驚嚇得發抖。吳道子拿起筆，揮動衣袖像一陣風，壁畫立刻完成了。", "keywords": [{"w": "居喪", "m": "守喪"}, {"w": "度", "m": "超度"}, {"w": "庶", "m": "希望"}, {"w": "幽冥", "m": "陰間"}, {"w": "縗衣", "m": "喪服（題目注釋）"}, {"w": "馳驟", "m": "奔馳"}, {"w": "室", "m": "劍鞘（題目注釋）"}, {"w": "驚慄", "m": "驚恐發抖"}, {"w": "援筆", "m": "拿起筆"}, {"w": "奮袂", "m": "揮動衣袖"}, {"w": "立就", "m": "立刻完成"}], "questions": [{"n": 25, "stem": "「唐裴將軍旻，居喪，請吳道子畫天宮壁度亡母。道子曰：『將軍為我舞劍一回，庶因猛厲以通幽冥。』旻脫縗衣，纏結，上馬馳驟，揮劍入雲，高十數丈，若電光下射，執鞘承之，劍透室而入，觀者驚慄。道子援筆奮袂如風，畫壁立就。」根據本文，下列敘述何者正確？", "options": {"A": "裴旻舞劍上馬，再躍至空中", "B": "觀者因怕被電光所傷而驚慄", "C": "吳道子用力以衣袖揮灑作畫", "D": "裴旻舞劍有助於吳道子作畫"}, "answer": "D", "explain": "吳道子請裴旻舞劍，希望藉猛烈的氣勢幫助作畫；看完舞劍後，他揮筆如風，壁畫立刻完成，可見舞劍有助於作畫，選(D)。(A)是劍「入雲」，裴旻並沒有躍到空中；(B)「若電光下射」是比喻劍落下的樣子，觀者是被驚險的接劍場面嚇到；(C)「援筆奮袂」是拿筆作畫、衣袖揮動，不是用衣袖作畫。", "skill": "分清楚比喻（若電光）與實際動作，並把動作的主語（劍、裴旻、吳道子）一一對清楚"}], "difficulty": "中", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-26", "exam": "bc99-2", "nums": [26], "form": "單題", "img": "img/bc99-2-26.png", "source": "詩句引用（甲出自李煜〈望江南〉、乙出自王勃〈送杜少府之任蜀州〉，丙丁出處待查）", "author": "", "genre": "古典詩詞曲", "types": ["典故出處", "詩詞賞析"], "passage": "甲、車如流水馬如龍　乙、天涯若比鄰　丙、客愁鄉夢亂如絲　丁、家山萬里夢依稀", "translation": "甲：車子像流水一樣接連不斷，馬匹像游龍一樣絡繹不絕（形容熱鬧繁華）。乙：即使遠在天涯，也像近鄰一樣。丙：客居他鄉的愁緒和思鄉的夢紛亂如絲。丁：故鄉遠在萬里之外，連夢裡都模糊不清。", "keywords": [{"w": "車如流水馬如龍", "m": "形容車馬往來不絕、繁華熱鬧"}, {"w": "比鄰", "m": "近鄰"}, {"w": "家山", "m": "故鄉"}, {"w": "依稀", "m": "模糊不清"}], "questions": [{"n": 26, "stem": "「現代科技發達，交通工具速度迅捷，可用『車如流水馬如龍』（甲）來形容，世界已成『天涯若比鄰』（乙）的地球村。離鄉遊子在『客愁鄉夢亂如絲』（丙）之際，只要一張小小的票卡，就能實現返鄉的心願，再也不必慨嘆『家山萬里夢依稀』（丁）了。」這段文字畫線處的詩句，何者引用不恰當？", "options": {"A": "甲", "B": "乙", "C": "丙", "D": "丁"}, "answer": "A", "explain": "「車如流水馬如龍」出自李煜〈望江南〉，形容車馬眾多、往來不絕的熱鬧繁華，不是形容速度快，用來說「交通工具速度迅捷」不恰當，選(A)。乙形容距離感縮短，丙形容遊子愁思，丁形容故鄉遙遠，都用得恰當。", "skill": "引用題要回到詩句原意：先確認詩句本來形容什麼（熱鬧？速度？），再看文中用來形容什麼"}], "difficulty": "中", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-27", "exam": "bc99-2", "nums": [27], "form": "單題", "img": "img/bc99-2-27.png", "source": "出處待查", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "識得一字行一字，方是善學；終日讀書而所行不逮一村農野夫，乃能言之鸚鵡乎？", "translation": "認識一個字，就實踐一個字的道理，這才是真正善於學習；整天讀書，行為卻比不上一個鄉下農夫，那不就只是會說話的鸚鵡嗎？", "keywords": [{"w": "行", "m": "實踐"}, {"w": "方", "m": "才"}, {"w": "逮", "m": "及、比得上"}, {"w": "乃", "m": "就是、不就是"}, {"w": "能言之鸚鵡", "m": "只會學舌、不能實踐的人"}], "questions": [{"n": 27, "stem": "「識得一字行一字，方是善學；終日讀書而所行不逮一村農野夫，乃能言之鸚鵡乎？」這句話的涵義與下列何者最接近？", "options": {"A": "多言而不當，不如其寡也", "B": "學者如禾如稻，不學者如草如蒿", "C": "學習者貴於能行之，不貴於能知之", "D": "能自苦中求，譬如披沙獲金，才得真學問"}, "answer": "C", "explain": "原文強調讀書要能實踐，只會讀不會做就像學舌的鸚鵡。(C)「學習可貴在能實行，而不只是知道」，意思最接近。(A)講話多不如話少；(B)比較學與不學的差別；(D)講學問要從苦中求得，都沒有扣住「知而能行」。", "skill": "抓題幹的對比：「識」與「行」、「讀書」與「所行」，重點落在「行」"}], "difficulty": "易", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-28", "exam": "bc99-2", "nums": [28], "form": "單題", "img": "img/bc99-2-28.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "文意推論"], "passage": "凡有一言一行，取於人者，皆顯稱之，不可竊人之美，以為己力；雖輕雖賤者，必歸功焉。竊人之財，刑辟之所處；竊人之美，鬼神之所責。", "translation": "凡是有一句話、一件事是從別人那裡得來的，都要公開說明出處，不可以偷取別人的長處，當成自己的功勞；即使對方身分卑微低賤，也一定要把功勞歸給他。偷別人的財物，會受到刑罰的處置；偷別人的美善（言論、功勞），會受到鬼神的責罰。", "keywords": [{"w": "取於人", "m": "從別人那裡取得"}, {"w": "顯稱", "m": "公開說明、稱揚"}, {"w": "竊", "m": "偷"}, {"w": "美", "m": "美善、好的言行"}, {"w": "歸功", "m": "把功勞歸給"}, {"w": "刑辟", "m": "刑法"}], "questions": [{"n": 28, "stem": "「凡有一言一行，取於人者，皆顯稱之，不可竊人之美，以為己力；雖輕雖賤者，必歸功焉。竊人之財，刑辟之所處；竊人之美，鬼神之所責。」根據這段話，下列哪一種行為是作者最主要的批判對象？", "options": {"A": "盲目跟從他人，自己毫無主見", "B": "自視甚高，不願與輕賤者為伍", "C": "剽竊他人言論，搶占他人功勞", "D": "竊取他人財物，又不願意認錯"}, "answer": "C", "explain": "全文重點在「不可竊人之美，以為己力」，批判把別人的言行、功勞占為己有，選(C)。(A)文中沒談主見；(B)「雖輕雖賤者」是說即使對方卑賤也要歸功，不是批評不與賤者往來；(D)「竊人之財」只是用來對照「竊人之美」，不是主要批判對象。", "skill": "區分「主要論點」與「對照陪襯」：竊財是陪襯，竊美才是重點"}], "difficulty": "中", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-32", "exam": "bc99-2", "nums": [32], "form": "單題", "img": "img/bc99-2-32.png", "source": "古代格言（出處待查）", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "(A)隱心而後動，謗議庸何傷／行事但求無愧我心，不求盡如人意(B)施人慎勿念，受施慎勿忘／人有恩於我不可忘，而怨則不可不忘(C)無道人之短，無說己之長／毋以己長訐人之短，毋以己拙忌人之長(D)在涅貴不緇，曖曖內含光／君子有含垢納汙之量，無好潔獨行之癖", "translation": "(A)先審度內心（無愧）再行動，別人的毀謗議論又有什麼傷害呢／做事只求問心無愧，不求人人滿意。(B)給人恩惠不要記在心上，受人恩惠不要忘記／別人對我有恩不可忘，對我的怨卻不可不忘。(C)不要說別人的短處，不要誇自己的長處／不要用自己的長處揭發別人的短處，不要因為自己笨拙而嫉妒別人的長處。(D)處在黑泥中貴在不被染黑，光彩含藏於內／君子要有包容汙垢的度量，不可有只求自身清白的怪癖。", "keywords": [{"w": "隱心", "m": "審度內心"}, {"w": "庸", "m": "豈、哪裡"}, {"w": "道", "m": "說"}, {"w": "訐", "m": "揭發別人隱私或短處"}, {"w": "涅", "m": "黑泥、黑色染料"}, {"w": "緇", "m": "黑色，此指染黑"}, {"w": "曖曖", "m": "昏暗不明的樣子"}], "questions": [{"n": 32, "stem": "下列各組文句的涵義，何者最接近？", "options": {"A": "隱心而後動，謗議庸何傷／行事但求無愧我心，不求盡如人意", "B": "施人慎勿念，受施慎勿忘／人有恩於我不可忘，而怨則不可不忘", "C": "無道人之短，無說己之長／毋以己長訐人之短，毋以己拙忌人之長", "D": "在涅貴不緇，曖曖內含光／君子有含垢納汙之量，無好潔獨行之癖"}, "answer": "A", "explain": "(A)兩句都說：只要自己問心無愧地行事，就不必在意別人的毀謗或看法，意思最接近。(B)前句講施恩與受恩，後句講記恩與忘怨，重點不同；(C)前句講不說人短、不誇己長，後句講不以長攻短、不以拙忌長，角度不同；(D)前句講身處汙濁而保持清白、才德內斂，後句講要能包容汙濁、不可獨自潔身，方向幾乎相反。", "skill": "每組先各用一句白話寫出重點，再比較兩句的「主題」與「態度」是否都一致"}], "difficulty": "難", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-34", "exam": "bc99-2", "nums": [34], "form": "單題", "img": "img/bc99-2-34.png", "source": "選項(D)出自《荀子‧天論》", "author": "", "genre": "說理議論", "types": ["句意理解", "比較閱讀"], "passage": "(A)天地之道，極則反，滿則損／(B)天之所覆，地之所載，莫不盡其美，致其用／(C)天之所能者，生萬物也；人之所能者，治萬物也／(D)天不為人之惡寒也輟冬，地不為人之惡遼遠也輟廣", "translation": "(A)天地的規律是：到了極點就會反轉，太滿就會減損。(B)天所覆蓋、地所承載的萬物，沒有不充分發揮它的美好與作用的。(C)天能做的是生養萬物，人能做的是治理萬物。(D)天不會因為人討厭寒冷就停止冬天，地不會因為人討厭遙遠就縮小它的廣大。", "keywords": [{"w": "極", "m": "到了極點"}, {"w": "反", "m": "返回、反轉"}, {"w": "覆", "m": "覆蓋"}, {"w": "載", "m": "承載"}, {"w": "惡", "m": "音ㄨˋ，厭惡"}, {"w": "輟", "m": "停止"}], "questions": [{"n": 34, "stem": "「對於大自然，人的態度往往很曖昧：既欣賞，又畏懼；既崇敬，卻又要加以征服。其實，自然世界只是一個無所感的存在罷了，對人類的苦樂永遠保持中立。」下列何者最能詮釋本文「自然世界只是一個無所感的存在」的說法？", "options": {"A": "天地之道，極則反，滿則損", "B": "天之所覆，地之所載，莫不盡其美，致其用", "C": "天之所能者，生萬物也；人之所能者，治萬物也", "D": "天不為人之惡寒也輟冬，地不為人之惡遼遠也輟廣"}, "answer": "D", "explain": "「無所感、保持中立」是說自然不會因人的感受而改變。(D)天不因人怕冷而停止冬天，地不因人嫌遠而縮小，正說明自然對人的好惡無動於衷，選(D)。(A)講物極必反的規律；(B)講萬物各盡其用；(C)講天與人的分工，都沒有「不受人的好惡影響」的意思。", "skill": "把「無所感」具體化為「不因人的喜怒而改變」，再找有「不為人之○而○」句式的選項"}], "difficulty": "中", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-35", "exam": "bc99-2", "nums": [35], "form": "單題", "img": "img/bc99-2-35.png", "source": "《左傳‧桓公十年》（選項A出自《左傳‧襄公二十四年》）", "author": "", "genre": "經典語錄", "types": ["句意理解", "典故出處"], "passage": "匹夫無罪，懷璧其罪。", "translation": "一般百姓本來沒有罪，只因為身上懷藏著美玉（招人覬覦），這就成了他的罪過。", "keywords": [{"w": "匹夫", "m": "平民百姓"}, {"w": "懷", "m": "懷藏"}, {"w": "璧", "m": "美玉"}, {"w": "象以齒焚身", "m": "大象因為珍貴的象牙而被殺"}, {"w": "蚌以珠剖體", "m": "蚌因體內的珍珠而被剖開"}], "questions": [{"n": 35, "stem": "「匹夫無罪，懷璧其罪。」這句話的涵義，與下列何者最接近？", "options": {"A": "象以齒焚身，蚌以珠剖體", "B": "狼無狽不立，狽無狼不行", "C": "老虎嘴裡敢拔牙，青龍頭上敢採珠", "D": "飛蛾撲火自焚身，游魚為食入網綸"}, "answer": "A", "explain": "題幹是說因擁有珍貴的東西而招來災禍。(A)大象因象牙被殺，蚌因珍珠被剖開，同樣是「因寶招禍」。(B)比喻互相勾結；(C)比喻膽大包天；(D)比喻貪圖或自投羅網而自取滅亡，禍因是自己的貪念，不是擁有寶物。", "skill": "抓因果結構「因為擁有寶物→招來禍害」，排除「因為貪求」而受害的選項"}], "difficulty": "中", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-44", "exam": "bc99-2", "nums": [44, 45, 46], "form": "題組", "img": "img/bc99-2-44.png", "source": "《賢奕編》（改寫）", "author": "劉元卿", "genre": "寓言故事", "types": ["虛詞句式", "主旨寓意", "文意推論"], "passage": "齊奄家畜一貓，自奇之，號於人曰「虎貓」。客說之曰：「虎誠猛，不如龍之神也，請更名曰『龍貓』。」又客說之曰：「龍固神於虎也，龍升天，須浮雲，龍豈尚於雲乎？不如名曰『雲』。」又客說之曰：「雲靄蔽天，風倏散之，雲故不敵風也，請更名曰『風』。」又客說之曰：「大風飆起，維屏以牆，斯足蔽矣。風其如牆何？名之『牆貓』可。」又客說之曰：「維牆雖固，維鼠穴之，牆斯圮矣。牆又鼠何？即名曰『鼠貓』可也。」東里丈人嗤之曰：「噫嘻！捕鼠者固貓也，貓即貓耳，故為自失本真哉？」", "translation": "齊奄家裡養了一隻貓，自己覺得牠很特別，對人稱牠為「虎貓」。有客人勸他說：「老虎確實兇猛，但不如龍神奇，請改名叫『龍貓』。」又有客人勸他說：「龍確實比老虎神奇，但龍升天必須靠浮雲，龍難道比雲更高明嗎？不如叫『雲』。」又有客人說：「雲氣遮蔽天空，風一下子就把它吹散，可見雲敵不過風，請改名叫『風』。」又有客人說：「大風颳起，只要用牆來屏障，就足以擋住了。風能拿牆怎麼樣呢？叫牠『牆貓』好了。」又有客人說：「牆雖然堅固，老鼠在牆上打洞，牆就倒塌了。牆又能拿老鼠怎麼樣呢？就叫『鼠貓』吧。」東里的一位老人譏笑他們說：「唉！捕捉老鼠的本來就是貓，貓就是貓罷了，為什麼要讓牠失去本來的面目呢？」", "keywords": [{"w": "畜", "m": "音ㄒㄩˋ，飼養"}, {"w": "奇", "m": "認為……特別"}, {"w": "號", "m": "稱呼"}, {"w": "說", "m": "音ㄕㄨㄟˋ，勸說"}, {"w": "誠", "m": "確實"}, {"w": "固", "m": "本來、確實"}, {"w": "尚", "m": "超過、高於"}, {"w": "倏", "m": "忽然、很快"}, {"w": "維", "m": "句首語助詞／只"}, {"w": "屏", "m": "屏障、遮擋"}, {"w": "如……何", "m": "能拿……怎麼樣"}, {"w": "圮", "m": "音ㄆㄧˇ，倒塌"}, {"w": "嗤", "m": "譏笑"}], "questions": [{"n": 44, "stem": "根據本文的結語，齊奄所養的這隻貓，最適當的稱呼為下列何者？", "options": {"A": "雲", "B": "貓", "C": "鼠貓", "D": "龍貓"}, "answer": "B", "explain": "結語東里丈人說「貓即貓耳」，貓就是貓，不必加上各種名號而失去本真，所以最適當的稱呼就是「貓」，選(B)。", "skill": "寓言的道理通常在最後一個人物的話裡，直接找結語"}, {"n": 45, "stem": "下列文句，何者最不可能含有反詰的語氣？", "options": {"A": "龍豈尚於雲乎", "B": "風其如牆何", "C": "牆又鼠何", "D": "故為自失本真哉"}, "answer": "D", "explain": "反詰是用問句表達相反的肯定意思。(A)「龍難道比雲高明嗎？」意思是龍不如雲；(B)「風能拿牆怎麼樣？」意思是風奈何不了牆；(C)「牆又能拿老鼠怎麼樣？」意思是牆敵不過鼠，三者都是反問。(D)是老人質問「為什麼要讓貓失去本來面目呢」，重點在追問原因、表達感嘆與責備，不是用反問句表達相反的意思，最不可能是反詰，選(D)。", "skill": "反詰的檢驗法：把問句改成相反的直述句，如果意思通順且就是說話者的本意，就是反詰"}, {"n": 46, "stem": "下列何者最可能是本文所要諷諭的社會現象？", "options": {"A": "追逐流行，崇尚新穎", "B": "虛有其表，游談無根", "C": "豪奢相競，愛慕虛榮", "D": "徒事巧飾，忘忽其本"}, "answer": "D", "explain": "客人們一個比一個想出更厲害的名字，越改越離譜，最後連「捕鼠」這個貓的本質都被忽略了，諷刺只在表面上巧加修飾、卻忘記事物本質的現象，選(D)。(A)不是在追逐流行；(B)「游談無根」是空談沒有根據，文中客人各有一套推論；(C)與奢華無關。", "skill": "從結局「自失本真」反推寓意：被批評的是「過度修飾」而「失去根本」"}], "difficulty": "中", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc99-2-47", "exam": "bc99-2", "nums": [47, 48], "form": "題組", "img": "img/bc99-2-47.png", "source": "《閑情偶寄》", "author": "李漁", "genre": "說理議論", "types": ["字詞解釋", "文意推論", "比較閱讀"], "passage": "讀書，最樂之事，而懶人常以為苦；清閑，最樂之事，而有人病其寂寞。就樂去苦，避寂寞而享安閑，莫若與高士盤桓、文人講論。何也？「與君一夕話，勝讀十年書。」既受一夕之樂，又省十年之苦，便宜不亦多乎？「因過竹院逢僧話，又得浮生半日閑。」既得半日之閑，又免多時之寂，快樂可勝道乎？", "translation": "讀書是最快樂的事，但懶惰的人常把它當成苦事；清閒是最快樂的事，但有人嫌它寂寞。想要得到快樂、去除痛苦，避開寂寞、享受安閒，不如和品德高尚的人往來、和文人談論學問。為什麼呢？「和您談一個晚上的話，勝過讀十年的書。」既享受了一晚的快樂，又省去十年讀書的辛苦，好處不是很多嗎？「因為經過竹林寺院和僧人談話，又得到浮生中半天的清閒。」既得到半天的清閒，又免去長時間的寂寞，這種快樂哪裡說得完呢？", "keywords": [{"w": "病", "m": "擔憂、嫌棄"}, {"w": "就", "m": "接近、趨向"}, {"w": "去", "m": "除去"}, {"w": "莫若", "m": "不如"}, {"w": "高士", "m": "品德高尚的人"}, {"w": "盤桓", "m": "往來、相處"}, {"w": "勝", "m": "勝過（ㄕㄥˋ）；盡（ㄕㄥ）"}, {"w": "便宜", "m": "音ㄅㄧㄢˋ ㄧˊ，好處、利益（題目注釋）"}, {"w": "既", "m": "已經"}], "questions": [{"n": 47, "stem": "根據本文，下列「　」中字詞的意義，何者兩兩相異？", "options": {"A": "常以為「苦」／就樂去「苦」", "B": "病其「寂寞」／避「寂寞」而享安閑", "C": "「勝」讀十年書／快樂可「勝」道乎", "D": "「既」受一夕之樂／「既」得半日之閑"}, "answer": "C", "explain": "(C)「勝讀十年書」的「勝」是「勝過」；「快樂可勝道乎」的「勝」讀ㄕㄥ，是「盡、完」，意思是快樂哪裡說得完，兩者不同，選(C)。(A)兩個「苦」都是痛苦；(B)兩個「寂寞」都是孤單冷清；(D)兩個「既」都是「已經」（既……又……），意思相同。", "skill": "把字義代回句中翻譯；「可勝道（數、言）」是固定用法，勝＝盡"}, {"n": 48, "stem": "關於如何「就樂去苦」，下列何者最貼近本文作者的看法？", "options": {"A": "結交權貴之士，以求飛黃騰達", "B": "欲與古人神交，莫若遍讀群書", "C": "親近賢雅君子，互相切磋啟發", "D": "結交方外僧道，探索生命奧祕"}, "answer": "C", "explain": "作者明說「就樂去苦……莫若與高士盤桓、文人講論」，就是親近品德高尚、有學問的人，彼此交流討論，選(C)。(A)作者說的是高士、文人，不是權貴；(B)作者認為與人談話勝過讀十年書，不是遍讀群書；(D)「逢僧話」只是引詩舉例，重點是與人交談得閑，不是探索生命奧祕。", "skill": "找作者明確提出方法的句子（莫若……），再排除只是舉例或偷換對象的選項"}], "difficulty": "中", "label": "99年第二次基測", "year": 99, "kind": "基測"}, {"id": "bc100-1-9", "exam": "bc100-1", "nums": [9], "form": "單題", "img": "img/bc100-1-9.png", "source": "選項化用《論語‧微子》、陶淵明〈歸去來辭〉等古語", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "(A)逝者已逝矣，來者猶可追　(B)迷途而知反，得道其未遠　(C)事未到手且莫急，功已成就且莫驕　(D)昔日舊染能洗滌，不害今日為君子", "translation": "(A)過去的已經過去了，未來的還來得及把握。(B)走錯路而知道回頭，離正道就不遠了。(C)事情還沒到手不要著急，功業已經成就不要驕傲。(D)過去沾染的壞習氣若能洗乾淨，不妨礙今天成為君子。", "keywords": [{"w": "逝者", "m": "過去的事物"}, {"w": "猶", "m": "還、仍然"}, {"w": "反", "m": "同「返」，回頭"}, {"w": "舊染", "m": "從前沾染的不良習氣"}, {"w": "不害", "m": "不妨礙"}], "questions": [{"n": 9, "stem": "「無論多麼傷心，多麼艱難的事情，都會隨時間消失的。拘泥於過往的時光，將會遺失新的時光。」這句話的涵義，與下列何者最接近？", "options": {"A": "逝者已逝矣，來者猶可追", "B": "迷途而知反，得道其未遠", "C": "事未到手且莫急，功已成就且莫驕", "D": "昔日舊染能洗滌，不害今日為君子"}, "answer": "A", "explain": "題幹說：過去的傷心事會隨時間消失，若一直執著過去，就會錯失新的時光——重點是「放下過去、把握未來」。(A)「逝者已逝矣，來者猶可追」：過去的已經過去，未來還能追得上，正是放下過去、把握將來，最接近。(B)講「犯錯後及時回頭」，重點在改過，不是放下過去。(C)講做事不急不驕的態度，與時光無關。(D)講洗去舊習、改過成為君子，重點在修身改過。", "skill": "先把題幹白話句濃縮成一句主旨（放下過去、把握未來），再把每個文言選項翻成白話比對關鍵詞「過去／未來」。"}], "difficulty": "易", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-10", "exam": "bc100-1", "nums": [10], "form": "單題", "img": "img/bc100-1-10.png", "source": "(B)李白〈越女詞〉；(D)張九齡〈秋夕望月〉；(A)(C)出處待查", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)日暮登春山，山鮮雲復輕。遠近看春色，踟躕新月明　(B)長干吳兒女，眉目豔新月。屐上足如霜，不著鴉頭襪　(C)虜騎三秋入，關雲萬里平。雪似胡沙暗，冰如漢月明　(D)清迥江城月，流光萬里同。所思如夢裡，相望在庭中", "translation": "(A)傍晚登上春山，山色鮮明雲朵輕盈；遠近觀看春景，徘徊間新月已明亮。(B)長干一帶吳地的女孩，眉目比新月還美；木屐上的腳白如霜，不穿鴉頭襪。(C)敵人的騎兵在秋天入侵，邊關的雲綿延萬里；雪像胡地的沙一樣昏暗，冰像漢家的月一樣明亮。(D)江城的月亮清朗高遠，月光照遍萬里都相同；思念的人像在夢裡，我們隔著遠方一同在庭中望月。", "keywords": [{"w": "踟躕", "m": "徘徊不前"}, {"w": "豔", "m": "美麗勝過"}, {"w": "虜騎", "m": "敵人的騎兵"}, {"w": "清迥", "m": "清朗高遠"}, {"w": "流光", "m": "流瀉的月光"}], "questions": [{"n": 10, "stem": "下列詩句，何者是透過月亮來傳達想念之情？", "options": {"A": "日暮登春山，山鮮雲復輕。遠近看春色，踟躕新月明", "B": "長干 吳兒女，眉目豔新月。屐上足如霜，不著鴉頭襪", "C": "虜騎三秋入，關雲萬里平。雪似胡沙暗，冰如漢月明", "D": "清迥江城月，流光萬里同。所思如夢裡，相望在庭中"}, "answer": "D", "explain": "(D)月光照遍萬里，兩地共有同一輪月；「所思」指思念的人，「相望在庭中」是兩人各在庭中望月，藉月寄託相思，正確。(A)月亮只是春日黃昏景色的一部分，寫賞春，沒有思念對象。(B)用「新月」比喻女子眉目之美，是寫人的外貌。(C)用月光形容冰的明亮，寫邊塞戰地的景象，不是思念。", "skill": "找「月」在句中的作用：是寫景、比喻外貌，還是搭配「所思、相望」這類思念詞語來寄情。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-12", "exam": "bc100-1", "nums": [12], "form": "單題", "img": "img/bc100-1-12.png", "source": "呂坤《呻吟語》", "author": "呂坤", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "子弟者，大人之胚胎；秀才者，士夫之胚胎；此時若火力不到，陶鑄不純，他日涉世立朝，終難成個令器。", "translation": "年輕子弟，是將來成為大人物的雛形；讀書的秀才，是將來成為士大夫的雛形。這個時候如果磨鍊的火候不夠、陶冶鑄造得不純熟，將來進入社會、在朝為官，終究難以成為好的人才。", "keywords": [{"w": "胚胎", "m": "雛形、尚未成形的開端"}, {"w": "陶鑄", "m": "燒製陶器、鑄造金屬，比喻培養造就"}, {"w": "涉世立朝", "m": "進入社會、在朝廷任官"}, {"w": "令器", "m": "美材，優秀的人才"}], "questions": [{"n": 12, "stem": "「子弟者，大人之胚胎；秀才者，士夫之胚胎；此時若火力不到，陶鑄不純，他日涉世立朝，終難成個令器。」這段話的涵義，與下列何者最接近？", "options": {"A": "學習不在貪多，但貴精與熟", "B": "君子之學貴專，專一乃能有功", "C": "璞玉琢磨不精，則瓊彩難以盡顯", "D": "文章不以德性陶鎔，終為技能之末"}, "answer": "C", "explain": "原文用燒陶鑄器比喻：年輕時若磨鍊不足，將來難成大器。(C)未雕琢的玉若琢磨不精，光彩就無法完全顯現，同樣是「年輕時培養不足，日後難成材」，最接近。(A)講學習求精不求多，(B)講學習要專一，兩者談學習方法，沒有「及早陶冶才能成材」的意思。(D)講文章要以品德為根本，與培養人才無關。", "skill": "抓住原文的比喻（胚胎→陶鑄→令器），找出同樣用「加工不足→無法成材」來比喻的選項。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-13", "exam": "bc100-1", "nums": [13], "form": "單題", "img": "img/bc100-1-13.png", "source": "改寫自侯白《啟顏錄》", "author": "侯白", "genre": "筆記小品", "types": ["文意推論", "寫作手法"], "passage": "隋人張生敏慧，楊素每閑悶，即召與戲談。嘗歲暮無事對坐，素戲之云：『計公多能，無惑不解。今日家中有人蛇咬足，若為醫治？』張生云：『取五月五日南牆下雪塗即治。』素云：『五月何處得有雪？』答云：『五月無雪，臘月何處有蛇咬？』素笑而遣之。", "translation": "隋朝人張生聰明機敏，楊素每次閒得發悶，就找他來開玩笑聊天。有一次年底沒事兩人對坐，楊素逗他說：「我想您多才多藝，沒有什麼疑難解不開。今天家裡有人被蛇咬了腳，要怎麼醫治？」張生說：「拿五月五日南牆下的雪塗上就好了。」楊素說：「五月哪裡有雪？」張生回答：「五月沒有雪，那臘月（年底寒冬）哪裡會有蛇咬人？」楊素笑著讓他回去。", "keywords": [{"w": "敏慧", "m": "聰明機靈"}, {"w": "計", "m": "料想、估計"}, {"w": "若為", "m": "如何、怎麼"}, {"w": "臘月", "m": "農曆十二月"}, {"w": "遣", "m": "使離開、打發"}], "questions": [{"n": 13, "stem": "「隋人張生敏慧，楊素每閑悶，即召與戲談。嘗歲暮無事對坐，素戲之云：『計公多能，無惑不解。今日家中有人蛇咬足，若為醫治？』張生云：『取五月五日南牆下雪塗即治。』素云：『五月何處得有雪？』答云：『五月無雪，臘月何處有蛇咬？』素笑而遣之。」文中張生回話的技巧，可用下列何者來形容？", "options": {"A": "虛應故事且答非所問", "B": "委婉含蓄並旁敲側擊", "C": "巧言令色以投其所好", "D": "以其人之道還治其人"}, "answer": "D", "explain": "楊素在寒冬臘月出了一個不可能的題目（冬天蛇冬眠不會咬人），張生就回敬一個同樣不可能的藥方（五月沒有雪），用對方出難題的方法反過來回擊，正是「以其人之道，還治其人之身」。(A)張生有針對問題回答，且是故意設計，不是敷衍。(B)他的反問直接點破對方的荒謬，並不委婉含蓄。(C)「巧言令色」指討好諂媚，張生是機智反擊，不是討好。", "skill": "先看出楊素題目的破綻（臘月無蛇），再對照張生答案的破綻（五月無雪），兩者手法相同，就是「以彼之道還彼之身」。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-16", "exam": "bc100-1", "nums": [16], "form": "單題", "img": "img/bc100-1-16.png", "source": "選項為古語、俗諺（(B)《禮記‧大學》）", "author": "", "genre": "經典語錄", "types": ["虛詞句式", "字詞解釋"], "passage": "卿須憐我我憐卿／(A)唯你「是」問　(B)有土「斯」有財　(C)有道者聽「其」毀譽　(D)害人「之」心不可有", "translation": "你應該憐惜我，我也憐惜你。(A)只問你（只找你負責）。(B)有了土地就有財富。(C)有道德修養的人聽憑別人對他毀謗或稱讚。(D)害人的心不可以有。", "keywords": [{"w": "卿", "m": "你（第二人稱代詞）"}, {"w": "是", "m": "賓語提前的助詞，無義"}, {"w": "斯", "m": "就、則"}, {"w": "其", "m": "他的"}, {"w": "之", "m": "的"}], "questions": [{"n": 16, "stem": "「卿須憐我我憐卿」句中的「卿」是代詞（也稱代名詞）。下列文句「」中的字，何者也是代詞？", "options": {"A": "唯你「是」問", "B": "有土「斯」有財", "C": "有道者聽「其」毀譽", "D": "害人「之」心不可有"}, "answer": "C", "explain": "(C)「其」指「有道者自己」，意思是「他的」毀譽，是代詞。(A)「唯你是問」原為「唯問你」，「是」用來把賓語「你」提前，是助詞，不代替任何人事物。(B)「斯」是「就、則」，連接前後兩件事，是連詞。(D)「之」是「的」，是助詞。", "skill": "把「」中的字換成白話，看能不能換成「你、我、他、他的、這」這類指稱人事物的詞；能換的才是代詞。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-18", "exam": "bc100-1", "nums": [18], "form": "單題", "img": "img/bc100-1-18.png", "source": "王國維《人間詞話》", "author": "王國維", "genre": "說理議論", "types": ["句意理解", "字詞解釋"], "passage": "詩人對宇宙人生，須入乎其內，又須出乎其外。入乎其內，故能寫之；出乎其外，故能觀之。入乎其內，故有生氣；出乎其外，故有高致。", "translation": "詩人面對宇宙人生，必須深入其中，又必須跳脫到外面。深入其中，所以能描寫它；跳出其外，所以能觀照它。深入其中，所以作品有生命力；跳出其外，所以作品有高遠的情致。", "keywords": [{"w": "入乎其內", "m": "深入其中去體會"}, {"w": "出乎其外", "m": "跳出來客觀地觀照"}, {"w": "生氣", "m": "生動的氣息、生命力"}, {"w": "高致", "m": "高遠的情趣、境界"}], "questions": [{"n": 18, "stem": "「詩人對宇宙人生，須入乎其內，又須出乎其外。入乎其內，故能寫之；出乎其外，故能觀之。入乎其內，故有生氣；出乎其外，故有高致。」關於這段文句的句意，下列說明何者正確？", "options": {"A": "入乎其內，故能寫之——深入體察萬物，方能細膩描寫", "B": "出乎其外，故能觀之——描摹宇宙人生，應出外實地觀察", "C": "入乎其內，故有生氣——作家有內在修養，才能寫出深入淺出的好作品", "D": "出乎其外，故有高致——好作品須跳脫成規之外，形式創新，內涵高雅"}, "answer": "A", "explain": "(A)深入宇宙人生之中體會，才能把它寫出來，說明正確。(B)「出乎其外」是心理上跳脫出來、客觀觀照，不是「出門到外面實地觀察」，望文生義。(C)「入乎其內」指深入體察對象，不是作家的內在修養；「生氣」是生動活潑，不是「深入淺出」。(D)「出乎其外」是跳脫出來觀照，不是跳脫寫作成規、形式創新。", "skill": "先確定「其」指「宇宙人生」，再把「內、外」理解成「投入其中／抽離觀照」的態度，逐項檢查解釋有沒有望文生義。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-20", "exam": "bc100-1", "nums": [20], "form": "單題", "img": "img/bc100-1-20.png", "source": "顏之推《顏氏家訓‧文章》", "author": "顏之推", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "凡為文章，猶人乘騏驥，雖有逸氣，當以銜勒制之，勿使流亂軌躅，放意填坑岸也。", "translation": "寫文章就像人騎駿馬，馬雖然有奔放的氣勢，仍應該用馬嚼子和韁繩控制牠，不要讓牠亂了行進的軌跡，任意奔跑而掉進坑谷、撞上河岸。", "keywords": [{"w": "騏驥", "m": "駿馬"}, {"w": "逸氣", "m": "奔放超逸的氣勢"}, {"w": "銜勒", "m": "駕馭馬匹的器具"}, {"w": "軌躅", "m": "軌跡"}, {"w": "放意", "m": "任意、隨心所欲"}], "questions": [{"n": 20, "stem": "「凡為文章，猶人乘騏驥，雖有逸氣，當以銜勒制之，勿使流亂軌躅，放意填坑岸也。」根據這句話，作者對於寫作文章的看法，與下列何者最接近？", "options": {"A": "文章當自出新意，成一家風骨", "B": "為文當求「語不驚人死不休」", "C": "文章若是氣韻不足，則非佳作", "D": "為文不可筆隨意走，漫無節度"}, "answer": "D", "explain": "作者把寫文章比作騎駿馬：文思再奔放，也要加以節制，不能任意亂跑。(D)「不可筆隨意走，漫無節度」正是這個意思。(A)強調創新與個人風格，原文沒談。(B)強調追求驚人的語句，與「節制」相反。(C)談氣韻不足的問題，但原文擔心的是氣勢太放而不受控制，不是不足。", "skill": "抓比喻對應：騏驥＝文思、銜勒＝節制，主旨就是「有才氣也要有節度」。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-24", "exam": "bc100-1", "nums": [24], "form": "單題", "img": "img/bc100-1-24.png", "source": "(A)俗語；(B)溫庭筠〈菩薩蠻〉；(D)改寫自《論語‧憲問》", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "兩人相視而笑，莫逆於心。／(A)「相」君之面，可知吉凶禍福　(B)照花前後鏡，花面交「相」映　(C)君持鞍下馬「相」迎，以禮賢士　(D)管仲，齊大夫，「相」桓公，霸諸侯", "translation": "兩人互相看著而笑，心意相通沒有違逆。(A)看您的面相，可以知道吉凶禍福。(B)前後鏡子照著花飾，花與臉互相映照。(C)您拿著馬鞍下馬來迎接（我），以禮對待賢士。(D)管仲是齊國大夫，輔佐齊桓公稱霸諸侯。", "keywords": [{"w": "相視", "m": "互相看"}, {"w": "莫逆", "m": "沒有違背，心意相投"}, {"w": "相（A）", "m": "觀察、看相"}, {"w": "相（C）", "m": "偏指一方，指「我」"}, {"w": "相（D）", "m": "輔佐"}], "questions": [{"n": 24, "stem": "「兩人相視而笑，莫逆於心。」句中「相」字的意義，與下列何者相同？", "options": {"A": "「相」君之面，可知吉凶禍福", "B": "照花前後鏡，花面交「相」映", "C": "君持鞍下馬「相」迎，以禮賢士", "D": "管仲，齊大夫，「相」桓公，霸諸侯"}, "answer": "B", "explain": "題幹「相視」是兩人「互相」看。(B)「交相映」是花與臉「互相」映照，相同。(A)「相君之面」的「相」是動詞，觀察、看相。(C)「相迎」是「迎接我」，動作只由一方發出，是偏指一方的用法，不是「互相」。(D)「相桓公」的「相」是輔佐。", "skill": "判斷「相」是不是雙方互動：兩方都在做同一動作才是「互相」；若後面接受詞或只有一方動作，就要另解。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-26", "exam": "bc100-1", "nums": [26], "form": "單題", "img": "img/bc100-1-26.png", "source": "《貞觀政要‧孝友》", "author": "吳兢", "genre": "史傳人物", "types": ["句意理解", "主旨寓意"], "passage": "貞觀中，突厥人史行昌值守玄武門，食而捨肉，人問其故，曰：『歸以奉母。』太宗聞而嘆曰：『仁、孝之性，豈隔華夷？』賜馬一匹，詔令供其母肉食。", "translation": "唐太宗貞觀年間，突厥人史行昌在玄武門值勤守衛，吃飯時把肉留下來不吃，別人問他原因，他說：「要帶回去奉養母親。」太宗聽了感嘆說：「仁愛孝順的天性，哪裡會因為是中原人或外族而有所不同呢？」就賞賜他一匹馬，並下詔供給他母親肉食。", "keywords": [{"w": "值守", "m": "值班守衛"}, {"w": "捨", "m": "放下、留下不吃"}, {"w": "奉", "m": "奉養"}, {"w": "豈", "m": "難道、哪裡"}, {"w": "華夷", "m": "中原人與外族"}], "questions": [{"n": 26, "stem": "「貞觀中，突厥人史行昌值守玄武門，食而捨肉，人問其故，曰：『歸以奉母。』太宗聞而嘆曰：『仁、孝之性，豈隔華夷？』賜馬一匹，詔令供其母肉食。」根據這段文字，下列敘述何者正確？", "options": {"A": "太宗讚許史行昌的孝行，詔令歸家奉母", "B": "史行昌到中原任職後，方知仁、孝之義", "C": "突厥人不重視人倫孝道，太宗深為惋嘆", "D": "仁、孝乃人之本性，不因種族而有不同"}, "answer": "D", "explain": "太宗說「仁、孝之性，豈隔華夷」，意思是仁孝是天性，不會因為是華人或外族而不同，(D)正確。(A)太宗是下詔「供其母肉食」，不是叫史行昌回家奉母。(B)原文沒說他到中原才懂仁孝，反而太宗認為這是天性。(C)太宗是「讚嘆」而非「惋嘆」，也沒說突厥人不重孝道。", "skill": "抓住關鍵句「豈隔華夷」的反問語氣——反問＝強烈否定，意思是「不會因種族而隔開」。"}], "difficulty": "易", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-28", "exam": "bc100-1", "nums": [28], "form": "單題", "img": "img/bc100-1-28.png", "source": "《荀子‧宥坐》", "author": "荀子", "genre": "經典語錄", "types": ["主旨寓意", "句意理解"], "passage": "芷蘭生於深林，非以無人而不芳。君子之學，非為通也，為窮而不困，憂而意不衰也，知禍福終始而心不惑也。", "translation": "芷草和蘭花生長在深林中，不會因為沒有人欣賞就不散發香氣。君子求學，不是為了顯達，而是為了在困窮時不被困住，憂患時意志不衰退，明白禍福的起因與結果而內心不迷惑。", "keywords": [{"w": "芷蘭", "m": "芷草和蘭花，皆為香草"}, {"w": "通", "m": "顯達"}, {"w": "窮", "m": "困窘不得志"}, {"w": "惑", "m": "迷惑"}], "questions": [{"n": 28, "stem": "「芷蘭生於深林，非以無人而不芳。君子之學，非為通也，為窮而不困，憂而意不衰也，知禍福終始而心不惑也。」這句話的涵義，與下列何者最接近？", "options": {"A": "學問無所遺，功夫老始成；紙上得來淺，事事要躬行", "B": "學雖有聰明之資，須做遲鈍工夫；學而不化，非學也", "C": "君子行義，不以人莫知而止休；學則意正心誠，知所立命", "D": "君子食無求飽，居無求安；敏於事而慎於言，就有道而正焉"}, "answer": "C", "explain": "原文兩層意思：①芷蘭不因沒人看就不香——君子行善不因無人知道而停止；②求學不是為了顯達，而是為了修養心志、安身立命。(C)「不以人莫知而止休」對應①，「意正心誠，知所立命」對應②，最接近。(A)講學問要全面、要親身實踐。(B)講學習要下苦功、要融會貫通。(D)講君子不求物質享受、做事勤快說話謹慎、向有德者學習，都與原文重點不同。", "skill": "把原文拆成兩個重點（無人知也不停、求學為修身不為顯達），找能同時對應兩個重點的選項。"}], "difficulty": "難", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-31", "exam": "bc100-1", "nums": [31], "form": "單題", "img": "img/bc100-1-31.png", "source": "程登吉《幼學瓊林‧宮室》", "author": "程登吉", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "賀人有喜，曰門闌藹瑞；謝人訪過，曰蓬蓽生輝。美輪美奐，《禮》稱屋宇之高華；肯構肯堂，《書》言父子之同志。土木方興曰經始，創造已畢曰落成。", "translation": "祝賀別人家有喜事，說「門闌藹瑞」；感謝別人來訪，說「蓬蓽生輝」。「美輪美奐」，是《禮記》稱讚房屋高大華美；「肯構肯堂」，是《尚書》說兒子能繼承父親的志業。建築工程剛開始叫「經始」，建造完成叫「落成」。", "keywords": [{"w": "門闌藹瑞", "m": "家門充滿祥瑞之氣，賀人有喜"}, {"w": "蓬蓽生輝", "m": "謙稱客人來訪使寒舍增光"}, {"w": "美輪美奐", "m": "形容建築物高大華美"}, {"w": "肯構肯堂", "m": "子承父業"}, {"w": "經始", "m": "開始營建"}], "questions": [{"n": 31, "stem": "「賀人有喜，曰門闌藹瑞；謝人訪過，曰蓬蓽生輝。美輪美奐，《禮》稱屋宇之高華；肯構肯堂，《書》言父子之同志。土木方興曰經始，創造已畢曰落成。」根據這段文字的敘述，下列文句的詞語何者運用正確？", "options": {"A": "小美參加豪宅建案的破土儀式，當場讚歎說：「這真是美輪美奐啊！」", "B": "老李到友人家作客，離去前對主人說：「感謝招待，令我蓬蓽生輝。」", "C": "王家父子木雕展開幕，朋友的祝賀詞寫道：「技藝傳家，肯構肯堂。」", "D": "跨海大橋的完工典禮上，來賓對著縣長說：「經始大業，造福鄉里。」"}, "answer": "C", "explain": "(C)「肯構肯堂」指父子同心、兒子繼承父業，用來祝賀王家父子傳承木雕技藝，正確。(A)「美輪美奐」形容已建成的房屋華美，破土時房子還沒蓋，不能用。(B)「蓬蓽生輝」是主人謙稱客人來訪使寒舍增光，客人不能自己這樣說。(D)「經始」是工程剛開始，完工典禮應用「落成」。", "skill": "先從原文找出每個詞語的使用時機（誰說、什麼時候說），再檢查選項的情境是否吻合。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-33", "exam": "bc100-1", "nums": [33], "form": "單題", "img": "img/bc100-1-33.png", "source": "于鵠〈巴女謠〉", "author": "于鵠", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "巴女騎牛唱『竹枝』，藕絲菱葉傍江時。不愁日暮還家錯，記得芭蕉出槿籬。", "translation": "巴地的女孩騎在牛背上唱著竹枝歌，正是荷花、菱葉沿江生長的時節。她不擔心天晚了會走錯回家的路，因為記得家門口有芭蕉從木槿籬笆中伸出來。", "keywords": [{"w": "竹枝", "m": "竹枝詞，巴蜀一帶民歌"}, {"w": "藕絲", "m": "此處代指荷花"}, {"w": "傍", "m": "靠近、沿著"}, {"w": "槿籬", "m": "木槿編成的籬笆"}], "questions": [{"n": 33, "stem": "「巴女騎牛唱『竹枝』，藕絲菱葉傍江時。不愁日暮還家錯，記得芭蕉出槿籬。」關於本詩的解析，下列敘述何者正確？", "options": {"A": "詩中描述的是春天傍晚時分恬靜閒雅的田園景致", "B": "末句使用「出」字，呈現動態的美感，增添詩趣", "C": "此詩藉由巴女放牛的辛勞來暗示農村生活的貧困", "D": "詩末描述巴女晚歸，因天色昏暗而不識回家之路"}, "answer": "B", "explain": "(B)芭蕉本是靜物，用「出」字寫它從籬笆中伸出來，彷彿會動，畫面活潑生動，正確。(A)荷花、菱葉生長在夏天，不是春天。(C)巴女一邊騎牛一邊唱歌，十分悠閒快樂，沒有辛勞貧困的意思。(D)「不愁日暮還家錯」是不擔心走錯，因為記得芭蕉的位置，並非不識回家路。", "skill": "抓季節線索（藕、菱→夏）、情緒線索（唱歌、不愁→愉快），再看動詞「出」如何化靜為動。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-35", "exam": "bc100-1", "nums": [35], "form": "單題", "img": "img/bc100-1-35.png", "source": "戲臺對聯（出處待查）", "author": "", "genre": "其他", "types": ["句意理解", "主旨寓意"], "passage": "此所謂現身說法，且看那善惡貞淫胥教誨；雖然是逢場作戲，難得他嬉笑怒罵皆文章。", "translation": "這就是所謂的現身說法，看那戲中善與惡、貞節與淫邪的角色，都是在教導勸誡觀眾；雖然只是逢場作戲，難得的是他的嬉笑怒罵都蘊含深意。", "keywords": [{"w": "胥", "m": "皆、都"}, {"w": "文章", "m": "隱微的含義"}, {"w": "現身說法", "m": "以自身經歷為例來說明勸導"}], "questions": [{"n": 35, "stem": "某戲臺有一副對聯：「此所謂現身說法，且看那善惡貞淫胥教誨；雖然是逢場作戲，難得他嬉笑怒罵皆文章。」這副對聯與下列何者的涵義最接近？", "options": {"A": "傀儡登場，須知這臺上衣冠是假；痴人說夢，休認作眼前富貴為真", "B": "君子小人，才子佳人，登場便見；歡天喜地，驚天動地，落幕即空", "C": "假面登場有孝子忠臣，莫輕看過；新腔協律是晨鐘暮鼓，只管聽來", "D": "戲愈好，人愈多，看他抒意表情；曲彌高，和彌寡，聽我長腔短調"}, "answer": "C", "explain": "題幹對聯的重點是：戲雖是演出來的，但其中善惡角色都在教化人心，嬉笑怒罵皆有深意。(C)說戲中孝子忠臣不要輕易看過，唱腔是警醒人心的晨鐘暮鼓——同樣強調戲劇的教化作用，最接近。(A)強調戲是假的、富貴如夢，重點在看破虛幻。(B)強調戲散一切成空，也是人生如夢。(D)講戲好看、曲高和寡，談的是表演技藝與知音。", "skill": "找出對聯關鍵詞「教誨」「皆文章」，判斷主旨是「戲劇有教化意義」，再排除講「人生如夢」的選項。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-38", "exam": "bc100-1", "nums": [38, 39], "form": "題組", "img": "img/bc100-1-38.png", "source": "改寫自王韜《瓮牖餘談》", "author": "王韜", "genre": "筆記小品", "types": ["句意理解", "文意推論"], "passage": "《漢書‧東方朔傳》云：「長安水多蛙，貧者得以家給人足。」則古昔關中已常食之如魚，不獨南人也。今粵東極嗜此，供諸盤飧，出以享客，奉為珍味。江浙雖有食者，然率賤品視之，縉紳家以登庖為戒。每歲四五月間，青蛙生發之際，官府多出示禁捕，以其能啄蟲保禾，大有益於農田也，故青蛙一名「護穀蟲」。其有捉取籠以入市者，有罰。蛙性熱，甚補，然人多食，小便若淋；妊娠食蛙，令子多病。", "translation": "《漢書‧東方朔傳》說：「長安水裡有很多青蛙，窮人因此能家家豐足。」可見古時候關中一帶就已經常像吃魚一樣吃青蛙，不只南方人吃。現在粵東（廣東）的人非常喜愛吃蛙，把牠放在餐盤裡，拿出來招待客人，視為珍貴美味。江浙一帶雖然也有人吃，但大都把牠看成低賤的食物，官宦人家把蛙端上廚房當成禁忌。每年四、五月青蛙繁殖的時候，官府多會公告禁止捕捉，因為青蛙能吃蟲保護稻禾，對農田大有好處，所以青蛙又叫「護穀蟲」。有人捉了青蛙裝在籠子裡拿到市場賣，就要受罰。蛙肉性熱，很滋補，但吃太多，小便會淋漓不暢；孕婦吃蛙，會使孩子多病。", "keywords": [{"w": "家給人足", "m": "家家富裕、人人豐足"}, {"w": "嗜", "m": "特別喜愛"}, {"w": "盤飧", "m": "盤中的飯菜"}, {"w": "率", "m": "大都、一概"}, {"w": "縉紳", "m": "官宦、士紳"}, {"w": "登庖", "m": "送進廚房（烹煮）"}, {"w": "出示", "m": "張貼公告"}, {"w": "妊娠", "m": "懷孕"}], "questions": [{"n": 38, "stem": "根據本文，下列哪一地區的人最愛食蛙？", "options": {"A": "長安", "B": "關中", "C": "粵東", "D": "江浙"}, "answer": "C", "explain": "文中說「今粵東極嗜此……奉為珍味」，「極嗜」就是非常喜愛，所以(C)粵東正確。(A)(B)長安、關中是古時候「常食之如魚」，只是常吃，而且是古代情形。(D)江浙「率賤品視之」，看不起蛙肉，不是最愛。", "skill": "在文中圈出各地區後面的態度詞（常食、極嗜、賤品視之），比較程度最強的「極嗜」。"}, {"n": 39, "stem": "根據本文，官府禁止捕蛙的主要原因為下列何者？", "options": {"A": "以免縉紳之家賤視蛙", "B": "蛙為滋補之珍貴藥材", "C": "孕婦食蛙，有傷胎兒", "D": "蛙喜食蟲，有益農作"}, "answer": "D", "explain": "文中說官府禁捕「以其能啄蟲保禾，大有益於農田也」，「以」是「因為」，所以原因是(D)蛙能吃蟲保護農作物。(A)縉紳賤視蛙是江浙的風氣，與禁捕無關。(B)(C)蛙性熱甚補、孕婦食蛙令子多病，是文末談食蛙的影響，不是官府禁捕的理由。", "skill": "找到「禁捕」那句，緊接著的「以……也」就是原因句。"}], "difficulty": "易", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-1-47", "exam": "bc100-1", "nums": [47, 48], "form": "題組", "img": "img/bc100-1-47.png", "source": "改寫自《西京雜記‧曹敞收葬》", "author": "葛洪（舊題劉歆）", "genre": "史傳人物", "types": ["句意理解", "人物情感", "虛詞句式"], "passage": "余少時，聞曹敞在吳章門下，往往好斥人過，或以為輕薄，世人皆以為然。章後為王莽所殺，人無有敢收葬者。弟子皆更易姓名，以從他師。敞時為司徒掾，獨稱吳門弟子，收葬其尸，方知亮直者不見容於冗輩中矣。", "translation": "我年輕時，聽說曹敞在吳章門下求學，常常喜歡指責別人的過錯，有人認為他輕浮刻薄，世人也都認同這種看法。後來吳章被王莽殺了，沒有人敢替他收屍安葬。他的弟子都改名換姓，去跟隨別的老師。曹敞當時擔任司徒的屬官，唯獨他自稱是吳章的弟子，替老師收屍安葬，（我）這才明白正直的人不被平庸之輩所容納啊。", "keywords": [{"w": "斥", "m": "指責"}, {"w": "或", "m": "有人"}, {"w": "輕薄", "m": "輕浮刻薄"}, {"w": "更易", "m": "改換"}, {"w": "司徒掾", "m": "司徒的屬官"}, {"w": "亮直", "m": "光明正直"}, {"w": "冗輩", "m": "平庸之人"}], "questions": [{"n": 47, "stem": "下列文句所省略的主語，何者說明正確？", "options": {"A": "聞曹敞在吳章門下——曹敞", "B": "往往好斥人過——曹敞", "C": "獨稱吳門弟子——吳章", "D": "方知亮直者不見容於冗輩中矣——吳章"}, "answer": "B", "explain": "(B)「往往好斥人過」是在說曹敞常指責別人，主語是曹敞，正確。(A)「聞」的是作者「余」，作者年輕時聽說曹敞的事。(C)自稱吳門弟子、收葬老師的是曹敞，不是吳章。(D)「方知」是作者看到這件事後才明白，主語是「余」。", "skill": "文言常省略主語：先找全文的敘述者「余」，再一句句問「是誰在做這個動作」，用前後文接回主語。"}, {"n": 48, "stem": "根據本文，下列何者最適合用來形容曹敞為吳章收葬的行為？", "options": {"A": "萍水相逢，拔刀相助", "B": "竭盡己能，大公無私", "C": "慮周行果，善為長久之計", "D": "當理不避其難，義無反顧"}, "answer": "D", "explain": "吳章被王莽所殺，眾人怕受牽連不敢收葬，弟子都改名換姓；曹敞卻在危險中挺身而出為老師收屍，是合於道義就不逃避危難，(D)正確。(A)曹敞是吳章的學生，不是萍水相逢。(B)「大公無私」指處事公正不偏私，與冒險盡師生之義不合。(C)「慮周行果、長久之計」指思慮周密、為長遠打算，曹敞的行為正好是不顧自身安危，並非精打細算。", "skill": "把曹敞的行為放回「人無有敢收葬者」的危險背景中，就能看出重點是「冒險行義」。"}], "difficulty": "中", "label": "100年第一次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-8", "exam": "bc100-2", "nums": [8], "form": "單題", "img": "img/bc100-2-8.png", "source": "出處待查（五代筆記故事）", "author": "", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "趙王李德誠鎮江西，有術士自稱：『世人賤貴，一見輒分。』王使女妓數人，與妻滕國君同妝梳服飾，偕立庭中，請辨良賤。客俯躬而進曰：『國君頭上有黃雲。』群妓不覺皆仰首，術士曰：『此是國君也。』王悅而遣之。", "translation": "趙王李德誠鎮守江西時，有個術士自稱：「世人的貴賤，我看一眼就能分辨。」趙王讓幾名歌妓和妻子滕國君打扮得一模一樣，一起站在庭院中，請他分辨誰尊誰卑。術士彎著身子上前說：「國君頭上有黃色的雲氣。」歌妓們不知不覺都抬頭去看（滕國君頭上），術士說：「這位就是國君。」趙王很高興，打賞後讓他離開。", "keywords": [{"w": "鎮", "m": "鎮守"}, {"w": "輒", "m": "就"}, {"w": "偕", "m": "一起"}, {"w": "良賤", "m": "尊貴與卑賤"}, {"w": "不覺", "m": "不知不覺"}, {"w": "遣", "m": "使離開"}], "questions": [{"n": 8, "stem": "「趙王李德誠鎮江西，有術士自稱：『世人賤貴，一見輒分。』王使女妓數人，與妻滕國君同妝梳服飾，偕立庭中，請辨良賤。客俯躬而進曰：『國君頭上有黃雲。』群妓不覺皆仰首，術士曰：『此是國君也。』王悅而遣之。」下列何者最適合用來形容文中的術士？", "options": {"A": "目有神力，貴賤立判", "B": "信口雌黃，誤打誤撞", "C": "機智靈活，巧工心計", "D": "透析陰陽，能施法術"}, "answer": "C", "explain": "術士其實看不出誰是國君，就故意說「國君頭上有黃雲」，歌妓們不自覺都抬頭看向國君，他便從眾人的視線認出國君——是靠觀察與心計，(C)正確。(A)(D)他並沒有真的神力或法術，只是用計。(B)「信口雌黃」是亂說話，「誤打誤撞」是碰巧猜中，但他的話是有計畫設下的圈套，並非碰運氣。", "skill": "追問「術士怎麼知道答案」：找出他說話後眾人的反應（皆仰首），就能看出他是用計而非真本事。"}], "difficulty": "易", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-9", "exam": "bc100-2", "nums": [9], "form": "單題", "img": "img/bc100-2-9.png", "source": "(B)梅堯臣〈陶者〉；(D)劉長卿〈新年作〉；(A)(C)出處待查", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "(A)蕙風入懷抱，聞君此夜琴　(B)陶盡門前土，屋上無片瓦　(C)俯仰歲將暮，榮耀難久恃　(D)嶺猿同旦暮，江柳共風煙", "translation": "(A)帶著蕙草香氣的風吹入懷中，聽到你今夜彈的琴。(B)燒陶的人把門前的泥土都挖光燒成瓦，自己屋頂上卻沒有一片瓦。(C)一俯一仰之間一年將盡，榮華難以長久依靠。(D)山嶺的猿猴與我共度早晚，江邊的柳樹與我同受風煙。", "keywords": [{"w": "對仗", "m": "上下句字數相同、詞性相對、結構相同"}, {"w": "旦暮", "m": "早晚"}, {"w": "恃", "m": "依靠"}], "questions": [{"n": 9, "stem": "下列詩句，何者屬於對仗句？", "options": {"A": "蕙風入懷抱，聞君此夜琴", "B": "陶盡門前土，屋上無片瓦", "C": "俯仰歲將暮，榮耀難久恃", "D": "嶺猿同旦暮，江柳共風煙"}, "answer": "D", "explain": "(D)「嶺猿／江柳」都是地點＋生物（名詞），「同／共」都是副詞，「旦暮／風煙」都是兩個名詞並列，上下句結構與詞性一一相對，是對仗句。(A)「蕙風入懷抱」是主語＋動詞＋受詞，「聞君此夜琴」是動詞開頭，結構不同。(B)「陶盡門前土」是動作，「屋上無片瓦」是存在句，詞性不相對。(C)「俯仰歲將暮」與「榮耀難久恃」結構不同，不相對。", "skill": "把上下句逐字（逐詞）對齊，檢查同位置的詞性是否相同（名對名、動對動、副對副）。"}], "difficulty": "中", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-10", "exam": "bc100-2", "nums": [10], "form": "單題", "img": "img/bc100-2-10.png", "source": "洪應明《菜根譚》", "author": "洪應明", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "天薄我福，吾厚吾德以迎之；天勞我形，吾逸吾心以補之；天厄我遇，吾亨吾道以通之。", "translation": "上天給我的福分淡薄，我就加厚自己的德行來迎接它；上天使我身體勞累，我就讓心情安閒來彌補；上天使我的境遇困頓，我就讓自己的道理通達來突破它。", "keywords": [{"w": "薄", "m": "使……淡薄"}, {"w": "厚", "m": "使……加厚"}, {"w": "逸", "m": "使……安閒"}, {"w": "厄", "m": "使……困窘"}, {"w": "亨", "m": "通達"}], "questions": [{"n": 10, "stem": "「天薄我福，吾厚吾德以迎之；天勞我形，吾逸吾心以補之；天厄我遇，吾亨吾道以通之。」這句話所透露的處世態度，與下列何者最接近？", "options": {"A": "人愛我，我必愛之；人惡我，我必惡之", "B": "君子恥食其食而無其功，恥服其服而不知其事", "C": "人之生於世也，為其所可為，不為其所不可為", "D": "正己而不求人，修德以應世；上不怨天，下不尤人"}, "answer": "D", "explain": "原文的態度是：遭遇不順時，不抱怨上天，而是從自己身上下功夫（厚德、逸心、亨道）。(D)「正己不求人、修德應世、不怨天不尤人」完全相合。(A)是以牙還牙的對等回應，與修養自己無關。(B)講不勞而獲是可恥的。(C)講做該做的事、不做不該做的事，沒有面對逆境反求諸己的意思。", "skill": "抓住句型「天……我，吾……以……之」：外在給我困境，我以修己回應——找「反求諸己、不怨天」的選項。"}], "difficulty": "中", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-14", "exam": "bc100-2", "nums": [14], "form": "單題", "img": "img/bc100-2-14.png", "source": "學生習作（仿元曲〈一半兒〉）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "草堂獨坐誦文章，生長閨閣鐵漢腸，心高志潔堪傲霜。逸興揚，一半兒風流，一半兒狂。", "translation": "獨自坐在草堂中誦讀文章，雖生長在閨房之中卻有鐵漢般的心腸，心志高潔足以傲視風霜。豪放的興致飛揚，一半是風流瀟灑，一半是狂放不羈。", "keywords": [{"w": "閨閣", "m": "女子的居室"}, {"w": "傲霜", "m": "不畏風霜，比喻品格堅貞"}, {"w": "逸興", "m": "超逸豪放的興致"}, {"w": "一半兒", "m": "元曲曲牌名"}], "questions": [{"n": 14, "stem": "「草堂獨坐誦文章，生長閨閣鐵漢腸，心高志潔堪傲霜。逸興揚，一半兒風流，一半兒狂。」這是一首學生的習作，關於這首作品，下列敘述何者正確？", "options": {"A": "句句押韻，共有六個韻腳", "B": "主題在抒寫文中人的心志懷抱", "C": "體裁屬於韻文中的「近體詩」", "D": "描寫的主人翁應是一位落第秀才"}, "answer": "B", "explain": "作品寫主人翁「心高志潔堪傲霜」「逸興揚」，抒發的是心志與懷抱，(B)正確。(A)韻腳為章、腸、霜、揚、狂，「一半兒風流」不押韻，只有五個韻腳。(C)句子長短不一，又有襯字般的「一半兒」，是仿元曲〈一半兒〉的曲，不是字數整齊的近體詩。(D)「生長閨閣」可知主人翁是女子，不是落第秀才。", "skill": "從體式（長短句＝詞曲）、關鍵詞（閨閣＝女子）、內容（心高志潔＝心志）逐一驗證選項。"}], "difficulty": "中", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-18", "exam": "bc100-2", "nums": [18], "form": "單題", "img": "img/bc100-2-18.png", "source": "《孫子兵法‧虛實》", "author": "孫武", "genre": "說理議論", "types": ["句意理解", "字詞解釋"], "passage": "凡先處戰地而待敵者逸，後處戰地而趨戰者勞。故善戰者，致人而不致於人。", "translation": "凡是先到達戰場等待敵人的，就從容安逸；後到達戰場而匆忙應戰的，就疲憊勞累。所以善於作戰的人，能調動敵人，而不被敵人調動。", "keywords": [{"w": "處", "m": "占據、到達"}, {"w": "逸", "m": "安逸、從容"}, {"w": "趨", "m": "快步奔赴"}, {"w": "致人", "m": "調動、支配敵人"}, {"w": "致於人", "m": "被敵人支配"}], "questions": [{"n": 18, "stem": "「凡先處戰地而待敵者逸，後處戰地而趨戰者勞。故善戰者，致人而不致於人。」句中善戰者應敵的方式，與下列何者最接近？", "options": {"A": "以退為進，先逸後勞", "B": "慰勞軍士，求致人和", "C": "一鼓作氣，以勢懾人", "D": "掌握先機，以逸待勞"}, "answer": "D", "explain": "善戰者「先處戰地」就是搶先占據戰場、掌握先機；「待敵者逸」就是養精蓄銳等待疲累的敵人，正是(D)「掌握先機，以逸待勞」。(A)原文是先到而「逸」，不是以退為進，「先逸後勞」也和原文主張相反。(B)講安撫軍心，原文沒提。(C)講憑氣勢壓倒敵人，原文重點在搶占先機與主動權。", "skill": "把「先處／後處」「逸／勞」兩組對比找出來，結論句「致人而不致於人」就是要掌握主動。"}], "difficulty": "易", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-21", "exam": "bc100-2", "nums": [21], "form": "單題", "img": "img/bc100-2-21.png", "source": "(A)後句出自《老子》第六十三章；(C)後句化用歐陽修〈畫眉鳥〉；(D)前句出自《三國演義》", "author": "", "genre": "其他", "types": ["比較閱讀", "句意理解"], "passage": "(A)天下難事必作於易，天下大事必作於細　(B)削足適履，愚不可及　(C)始知鎖向金籠裡，不及雲間自在飛　(D)此人料吾平生謹慎，必不弄險；見如此模樣，疑有伏兵，所以退去／愚者千慮，必有一得", "translation": "(A)天下的難事必定從容易處做起，天下的大事必定從細微處做起。(B)削小腳去配合鞋子，愚蠢到了極點。(C)這才知道被鎖在金籠裡，比不上在雲間自由自在地飛翔。(D)這人料定我一生謹慎，必定不會冒險；看到這種情形，懷疑有埋伏，所以退走了。／愚笨的人考慮千次，也必定有一次想對。", "keywords": [{"w": "作", "m": "起始、做起"}, {"w": "削足適履", "m": "比喻勉強遷就、不知變通"}, {"w": "弄險", "m": "冒險"}, {"w": "千慮一得", "m": "多次思慮總有一點收穫"}], "questions": [{"n": 21, "stem": "下列各組文句的涵義，何者前後最相近？", "options": {"A": "即使細細一線，也要與整座天空拔河／天下難事必作於易，天下大事必作於細", "B": "無論怎麼難看的鞋子，還是有人喜歡，所以不怕賣不出去／削足適履，愚不可及", "C": "籠中鳥的苦悶，大概是僅次於黏在膠紙上的蒼蠅／始知鎖向金籠裡，不及雲間自在飛", "D": "此人料吾平生謹慎，必不弄險；見如此模樣，疑有伏兵，所以退去／愚者千慮，必有一得"}, "answer": "C", "explain": "(C)前句說籠中鳥極其苦悶，後句說鎖在金籠不如在雲間自由，兩者都表達「失去自由的痛苦、嚮往自由」，最相近。(A)前句寫渺小也要奮力抗衡的氣概，後句講做事要從易處、細處著手，不同。(B)前句講各有所好，後句講勉強遷就、不知變通，不同。(D)前句是諸葛亮說司馬懿因料定他謹慎而中空城計，是「智者反被聰明誤」，後句講愚者偶有所得，不同。", "skill": "先把每組的文言部分翻成白話，再各用一句話寫出前後句的重點，比對是否同一主旨。"}], "difficulty": "中", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-25", "exam": "bc100-2", "nums": [25], "form": "單題", "img": "img/bc100-2-25.png", "source": "《呂氏春秋‧聽言》", "author": "呂不韋門客", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "聽言不可不察，不察則善不善不分。善不善不分，亂莫大焉。", "translation": "聽別人的話不可以不仔細考察，不考察就分不清好壞。好壞分不清，沒有比這更大的禍亂了。", "keywords": [{"w": "察", "m": "仔細考察、辨明"}, {"w": "善不善", "m": "好的與不好的"}, {"w": "莫大焉", "m": "沒有比這更大的"}, {"w": "貽", "m": "遺留"}], "questions": [{"n": 25, "stem": "「聽言不可不察，不察則善不善不分。善不善不分，亂莫大焉。」這句話的涵義，與下列何者最接近？", "options": {"A": "知之愈明則行愈篤，行之愈篤則知愈明", "B": "聽聞不加審辨，將貽四海之憂、百年之患", "C": "直言者，國之良藥也；直言之臣，國之良醫也", "D": "君之所以明者，兼聽也；君之所以暗者，偏信也"}, "answer": "B", "explain": "原文重點：聽到的話若不仔細分辨，就會好壞不分而造成大亂。(B)聽聞不加審辨，會留下天下的憂患、長久的禍害，意思最接近。(A)講知與行互相促進。(C)講直言對國家的好處。(D)講君主要多方聽取意見才能英明，重點在「兼聽」與「偏信」，而不是「聽了要審辨」。", "skill": "抓「不察→不分→亂」的因果鏈，找同樣是「不辨明→招致禍患」的選項；小心(D)談的是聽的範圍而非辨別。"}], "difficulty": "中", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-26", "exam": "bc100-2", "nums": [26], "form": "單題", "img": "img/bc100-2-26.png", "source": "行業對聯", "author": "", "genre": "其他", "types": ["文化常識", "句意理解"], "passage": "(A)往來盡是紅顏客，穿梭應無藍褸人　(B)鐵剪裁來誇手段，金針度處費工夫　(C)寸鐵削裁宇內豪傑，雙手平撫天下英雄　(D)舉手處隨時消酷暑，動搖間常伴有清風", "translation": "(A)來往的都是容顏美好的客人，穿梭其中應該沒有衣衫破爛的人。(B)用剪刀裁剪誇耀手藝，用金針縫製費盡功夫。(C)用小小的刀剃修天下的豪傑，用雙手撫平天下英雄的頭髮。(D)一舉手就能隨時消除酷暑，搖動之間總有清風相伴。", "keywords": [{"w": "寸鐵", "m": "短小的刀具，指剃刀"}, {"w": "宇內", "m": "天下"}, {"w": "金針度", "m": "以針縫紉"}], "questions": [{"n": 26, "stem": "家齊所開設的男士理髮店即將開幕，下列哪一副對聯最適合送給他以示祝賀？", "options": {"A": "往來盡是紅顏客，穿梭應無藍褸人", "B": "鐵剪裁來誇手段，金針度處費工夫", "C": "寸鐵削裁宇內豪傑，雙手平撫天下英雄", "D": "舉手處隨時消酷暑，動搖間常伴有清風"}, "answer": "C", "explain": "(C)「寸鐵削裁」指剃刀修剪，「雙手平撫」指理順頭髮，對象是「豪傑、英雄」，正合男士理髮店。(A)「紅顏客」指女子，用於美容院、女裝店較合適。(B)剪刀與金針縫紉，是裁縫店（服裝店）。(D)舉手搖動能生清風、消暑，是扇子店。", "skill": "從對聯的工具與動作（剪、針、扇、剃刀）判斷行業，再看對象（紅顏／豪傑）是否符合男士。"}], "difficulty": "易", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-30", "exam": "bc100-2", "nums": [30], "form": "單題", "img": "img/bc100-2-30.png", "source": "李贄評何心隱之語（出處待查）", "author": "李贄", "genre": "說理議論", "types": ["句意理解", "寫作手法"], "passage": "其文章高妙，略無一字襲前人，亦未見從前有此文字，但見其一瀉千里，委曲詳盡，觀者不知感動，吾不知之矣。", "translation": "他的文章高明巧妙，幾乎沒有一個字抄襲前人，也從沒見過以前有這樣的文字；只見他文思如江河一瀉千里，曲折周到、詳細完整，讀的人如果不受感動，那我就不明白了。", "keywords": [{"w": "略無", "m": "幾乎沒有"}, {"w": "襲", "m": "沿用、抄襲"}, {"w": "一瀉千里", "m": "比喻文筆奔放流暢"}, {"w": "委曲", "m": "曲折周到"}], "questions": [{"n": 30, "stem": "李贄推崇何心隱說：「其文章高妙，略無一字襲前人，亦未見從前有此文字，但見其一瀉千里，委曲詳盡，觀者不知感動，吾不知之矣。」由此可知何心隱文章的高妙處為下列何者？", "options": {"A": "深入淺出，雅俗共賞", "B": "旁徵博引，內容豐碩", "C": "委婉含蓄，遣詞典麗", "D": "立意用語，新穎暢達"}, "answer": "D", "explain": "「略無一字襲前人，亦未見從前有此文字」表示新穎、有創意；「一瀉千里」表示流暢通達，合起來就是(D)「新穎暢達」。(A)原文沒提淺顯易懂、雅俗共賞。(B)「旁徵博引」是大量引用前人，與「無一字襲前人」相反。(C)「一瀉千里」是奔放直達，不是含蓄；也沒提到詞藻華麗。", "skill": "把評語拆成兩段：「不襲前人」＝新，「一瀉千里」＝暢，再找同時包含兩點的選項。"}], "difficulty": "中", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-31", "exam": "bc100-2", "nums": [31], "form": "單題", "img": "img/bc100-2-31.png", "source": "《列子‧說符》", "author": "列子", "genre": "史傳人物", "types": ["文意推論", "主旨寓意"], "passage": "狐丘丈人謂孫叔敖曰：「人有三怨，子知之乎？」孫叔敖曰：「何謂也？」對曰：「爵高者，人妒之；官大者，主惡之；祿厚者，怨逮之。」孫叔敖曰：「吾爵益高，吾志益下；吾官益大，吾心益小；吾祿益厚，吾施益博，以是可免於三怨。」", "translation": "狐丘的一位老人對孫叔敖說：「人有三種招怨的事，你知道嗎？」孫叔敖說：「是什麼呢？」老人說：「爵位高的人，別人會嫉妒他；官職大的人，君主會厭惡他；俸祿多的人，怨恨會找上他。」孫叔敖說：「我的爵位越高，我的心志越謙下；官職越大，我的心越謹慎；俸祿越多，我施捨給別人的越廣，用這種方法就可以避免三種怨恨。」", "keywords": [{"w": "丈人", "m": "老人"}, {"w": "惡", "m": "厭惡"}, {"w": "逮", "m": "及、到"}, {"w": "益", "m": "更加"}, {"w": "下", "m": "謙下"}, {"w": "施", "m": "施捨"}], "questions": [{"n": 31, "stem": "依據這則短文的內容，下列推論何者正確？", "options": {"A": "處富貴而能自我約束者，未必招致譏讒", "B": "孫叔敖接受丈人的諷勸，打算辭官歸隱", "C": "以不如人之念存心者，乃能得高爵厚祿", "D": "孫叔敖自恃爵高祿厚，不在意他人眼光"}, "answer": "A", "explain": "孫叔敖認為只要越富貴越謙下、謹慎、樂施，就能免於三怨——可見身處富貴而能自我約束，不一定會招來毀謗，(A)正確。(B)他提出的是自處之道，沒有要辭官。(C)原文講如何「保住」富貴而不招怨，不是說謙卑才能「得到」高爵厚祿，因果倒置。(D)他正是很在意別人的怨恨，才提出應對方法。", "skill": "找出三組「越……越……」的對應，歸納孫叔敖的方法是「自我約束」，再檢查選項的因果方向。"}], "difficulty": "中", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-32", "exam": "bc100-2", "nums": [32], "form": "單題", "img": "img/bc100-2-32.png", "source": "盧照鄰〈長安古意〉；(D)李白〈憶舊遊寄譙郡元參軍〉；其餘出處待查", "author": "盧照鄰", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "昔時金階白玉堂，即今唯見青松在。／(A)萬戶樓臺臨渭水，五陵花柳滿秦川　(B)野花黃葉舊吳宮，六代豪華燭散風　(C)曙煙已別黃金殿，晚照重登白玉筵　(D)黃金白璧買歌笑，一醉累月輕王侯", "translation": "從前是黃金臺階、白玉廳堂，如今只看見青松還在。(A)千家萬戶的樓臺靠近渭水，五陵一帶的花柳布滿秦川。(B)舊日吳國宮殿只剩野花黃葉，六朝的豪華像風中的燭火一樣消散。(C)清晨的煙霧中告別黃金殿，傍晚的夕照下又登上白玉宴席。(D)用黃金白璧買來歌舞歡笑，一醉就是數月，看輕王侯。", "keywords": [{"w": "金階白玉堂", "m": "華麗的宮殿"}, {"w": "唯", "m": "只"}, {"w": "六代", "m": "六朝，指建都金陵的六個朝代"}, {"w": "燭散風", "m": "像風中燭火般消散"}], "questions": [{"n": 32, "stem": "盧照鄰〈長安古意〉云：「昔時金階白玉堂，即今唯見青松在。」其中抒發的感慨與下列何者最接近？", "options": {"A": "萬戶樓臺臨渭水，五陵花柳滿秦川", "B": "野花黃葉舊吳宮，六代豪華燭散風", "C": "曙煙已別黃金殿，晚照重登白玉筵", "D": "黃金白璧買歌笑，一醉累月輕王侯"}, "answer": "B", "explain": "題幹用「昔時」的華麗宮殿對比「即今」只剩青松，感嘆繁華易逝、盛衰無常。(B)舊吳宮只剩野花黃葉，六朝豪華如風中燭火消散，同樣是今昔盛衰之感，正確。(A)寫長安眼前的繁華景象，沒有今昔對比。(C)寫由早到晚享樂不停，是寫奢華生活。(D)寫揮金買笑、縱情飲酒的豪放，也不是盛衰之嘆。", "skill": "找「昔／今」對比的線索（舊、已、散），判斷是不是「繁華消逝」的感慨。"}], "difficulty": "中", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-33", "exam": "bc100-2", "nums": [33], "form": "單題", "img": "img/bc100-2-33.png", "source": "出處待查（科舉笑話）", "author": "", "genre": "筆記小品", "types": ["文意推論", "句意理解"], "passage": "至矣盡矣，方知小子之名；顛之倒之，反在諸公之上。", "translation": "看到最後、看到盡頭，才看到我的名字；如果把榜單顛倒過來看，我反而排在各位之上。", "keywords": [{"w": "至矣盡矣", "m": "到了盡頭、最後"}, {"w": "小子", "m": "自己的謙稱"}, {"w": "顛之倒之", "m": "把它顛倒過來"}, {"w": "諸公", "m": "各位（其他考生）"}], "questions": [{"n": 33, "stem": "「從前有個叫崔永齡的人參加科舉考試，看榜之後，寫了一封家書報告參加這次科考的結果：『至矣盡矣，方知小子之名；顛之倒之，反在諸公之上。』」由此推測，崔永齡考試的結果最可能是下列何者？", "options": {"A": "高中狀元", "B": "名列前茅", "C": "位居榜末", "D": "名落孫山"}, "answer": "C", "explain": "「至矣盡矣，方知小子之名」：看到榜單最後才找到自己的名字，表示有上榜但排在最後；「顛之倒之，反在諸公之上」：把榜單倒過來，自己就變成第一，是幽默自嘲。所以是(C)位居榜末。(A)(B)名次在前，與「至矣盡矣」矛盾。(D)名落孫山是沒考上，但他的名字在榜上。", "skill": "抓「方知小子之名」——有名字＝有上榜；「至矣盡矣」＋「顛倒後在上」＝最後一名。"}], "difficulty": "易", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-45", "exam": "bc100-2", "nums": [45, 46], "form": "題組", "img": "img/bc100-2-45.png", "source": "劉基《郁離子‧食鮐》", "author": "劉基", "genre": "寓言故事", "types": ["句意理解", "主旨寓意"], "passage": "司城子之圉人之子，食鯸鮐而死，弗哭。司城子問之曰：「父與子有愛乎？」曰：「何為其無愛也？」司城子曰：「然則爾之子死而弗哭，何也？」對曰：「臣聞之：死生有命，知命者不苟死。鯸鮐，毒魚也。食之者死，夫人莫不知也。而必食以死，是為口腹而輕其生，非人子也。是以弗哭。」", "translation": "司城子家養馬人的兒子，吃河豚死了，養馬人卻不哭。司城子問他：「父親和兒子之間有愛嗎？」他說：「怎麼會沒有愛呢？」司城子說：「那麼你兒子死了你卻不哭，為什麼？」他回答：「我聽說：生死有命，懂得天命的人不會隨便送死。河豚是有毒的魚，吃了就會死，人人都知道。他卻偏要吃而死，這是為了口腹之欲而輕視自己的生命，不配做人子。所以我不哭。」", "keywords": [{"w": "圉人", "m": "養馬的人"}, {"w": "鯸鮐", "m": "河豚"}, {"w": "弗", "m": "不"}, {"w": "何為", "m": "為什麼、怎麼"}, {"w": "苟", "m": "隨便、輕率"}, {"w": "夫人", "m": "人人、大家"}, {"w": "是以", "m": "因此"}], "questions": [{"n": 45, "stem": "根據本文，圉人死了兒子卻不哭的原因是下列何者？", "options": {"A": "圉人因其子貪圖不義之物致死而氣憤至極", "B": "圉人之子徒逞口腹之欲，不愛惜生命", "C": "父子之間因疏於溝通，情感淡薄", "D": "圉人內心過於哀傷而欲哭無淚"}, "answer": "B", "explain": "圉人說兒子明知河豚有毒還非吃不可，「是為口腹而輕其生」，為了滿足口腹之欲而輕視生命，所以不哭，(B)正確。(A)河豚不是「不義之物」，問題在於有毒而他偏要吃。(C)圉人明說「何為其無愛也」，父子是有愛的。(D)他不哭是因為不認同兒子的行為，不是哀傷過度。", "skill": "直接找圉人自己說的理由句「是為口腹而輕其生……是以弗哭」，「是以」前面就是原因。"}, {"n": 46, "stem": "這則故事所寄託的涵義，與下列何者最接近？", "options": {"A": "廉者足而不憂，貪者憂而不足", "B": "能安於清澹，則不為富貴所淫", "C": "少慾則易足，易足則心靜智明", "D": "一念之慾倘不能制，恐致大禍"}, "answer": "D", "explain": "兒子因為管不住想吃河豚的慾望而喪命，寓意是：一時的慾望若不能克制，可能招來大禍，(D)正確。(A)講廉潔與貪心的心境差異。(B)講安於清淡就不被富貴迷惑。(C)講少慾使心靈平靜聰明。三者都談慾望少的好處，但沒有「放縱慾望→招致災禍」的警示。", "skill": "把故事濃縮成「因為什麼→導致什麼」（貪口腹→喪命），再找有同樣因果警示的選項。"}], "difficulty": "易", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-2-47", "exam": "bc100-2", "nums": [47, 48], "form": "題組", "img": "img/bc100-2-47.png", "source": "《列子‧湯問》", "author": "列子", "genre": "寓言故事", "types": ["句意理解", "文意推論"], "passage": "周穆王大征西戎，西戎獻錕鋙之劍，火浣之布。其劍長尺有咫，練鋼赤刃；用之切玉如切泥焉。火浣之布，浣之必投於火，布則火色，垢則布色；出火而振之，皓然疑乎雪。皇子以為無此物，傳之者妄。蕭叔曰：「皇子果於自信，果於誣理哉！」", "translation": "周穆王大舉征討西戎，西戎獻上錕鋙寶劍和火浣布。那把劍長一尺八寸，用精煉的鋼鑄成，刀刃是紅色的；用它切玉就像切泥一樣。火浣布要洗時一定要投進火裡，布會變成火的顏色，污垢則現出布原本的顏色；從火中取出抖一抖，潔白得像雪一樣。皇子認為沒有這種東西，是傳話的人亂說。蕭叔說：「皇子太過相信自己，太過武斷地否定事理了！」", "keywords": [{"w": "錕鋙之劍", "m": "寶劍名"}, {"w": "火浣之布", "m": "以石綿織成，能耐火去汙的布"}, {"w": "尺有咫", "m": "一尺八寸"}, {"w": "浣", "m": "洗"}, {"w": "振", "m": "抖動"}, {"w": "皓然", "m": "潔白的樣子"}, {"w": "果", "m": "果斷、武斷"}, {"w": "誣", "m": "歪曲、否定"}], "questions": [{"n": 47, "stem": "根據本文，下列關於火浣之布的敘述何者正確？", "options": {"A": "初洗淨時布色極為潔白", "B": "以雪冷卻之後才能使用", "C": "投入火中，無垢處呈現原色", "D": "用熱水沖洗，才能滌淨髒汙"}, "answer": "A", "explain": "「出火而振之，皓然疑乎雪」：從火中拿出抖一抖，白得像雪，所以剛洗淨時極為潔白，(A)正確。(B)「疑乎雪」是比喻像雪一樣白，不是用雪冷卻。(C)投入火中時「布則火色」，無垢的布呈現火的顏色，「垢則布色」才是污垢處呈現布色，說反了。(D)是投入火中洗，不是用熱水。", "skill": "注意「布則火色，垢則布色」兩句的主語各是誰，以及「疑乎雪」是比喻不是事實。"}, {"n": 48, "stem": "根據本文敘述，無法得知下列何者？", "options": {"A": "周穆王出征威懾西戎", "B": "錕鋙劍劍刃是紅色的", "C": "皇子曾經遣人尋覓寶物", "D": "蕭叔認為皇子過於武斷"}, "answer": "C", "explain": "本文只說皇子「以為無此物，傳之者妄」，並沒有提到他派人去找寶物，(C)無法得知，是答案。(A)「大征西戎，西戎獻……」可知西戎因畏懼而獻寶。(B)「練鋼赤刃」說明劍刃是紅色。(D)蕭叔說「皇子果於自信，果於誣理哉」，即認為他太武斷。", "skill": "「無法得知」題：每個選項都回原文找證據，找得到的刪掉，找不到的就是答案。"}], "difficulty": "中", "label": "100年第二次基測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-2", "exam": "bc100-nbk", "nums": [2], "form": "單題", "img": "img/bc100-nbk-2.png", "source": "選項為古語、成語（(B)化用《孫子兵法‧九地》）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "(A)一「而」再，再「而」三　(B)置之死地「而」後生　(C)從今「而」後，不得再犯　(D)知其然「而」不知其所以然", "translation": "(A)一次又一次，一再發生。(B)把軍隊放在無路可退的絕境，然後才能求得生存。(C)從今以後，不可以再犯。(D)知道事情是這樣，卻不知道為什麼會這樣。", "keywords": [{"w": "而（順接）", "m": "然後、就"}, {"w": "而（逆接）", "m": "卻、但是"}, {"w": "所以然", "m": "之所以這樣的原因"}], "questions": [{"n": 2, "stem": "下列文句中的「而」字，何者可用「卻」字代換？", "options": {"A": "一「而」再，再「而」三", "B": "置之死地「而」後生", "C": "從今「而」後，不得再犯", "D": "知其然「而」不知其所以然"}, "answer": "D", "explain": "「卻」表示前後語意相反的轉折。(D)「知其然」與「不知其所以然」意思相反，「而」等於「卻」，正確。(A)「一而再」是一次接著一次，「而」表示順接、遞進。(B)「置之死地而後生」是先陷入絕境「然後」才能求生，表示先後順承。(C)「從今而後」即從今以後，「而」連接時間起點與往後，也是順接。", "skill": "看「而」前後兩部分的意思是相同方向（順接）還是相反（逆接），相反的才能換成「卻」。"}], "difficulty": "易", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-9", "exam": "bc100-nbk", "nums": [9], "form": "單題", "img": "img/bc100-nbk-9.png", "source": "白居易〈問友〉", "author": "白居易", "genre": "古典詩詞曲", "types": ["文意推論", "詩詞賞析"], "passage": "種蘭不種艾，蘭生艾亦生。根荄相交長，莖葉相附榮。香莖與臭葉，日夜俱長大。鋤艾恐傷蘭，溉蘭恐滋艾。蘭亦未能溉，艾亦未能除。沉吟意不決，問君合何如？", "translation": "我只種蘭草不種艾草，可是蘭草長出來，艾草也跟著長出來。兩者的根糾纏著一起生長，莖葉互相依附而繁茂。香的莖和臭的葉，日夜一起長大。想鋤掉艾草，又怕傷了蘭草；想澆灌蘭草，又怕滋養了艾草。結果蘭草也沒能澆，艾草也沒能除。我沉思猶豫拿不定主意，請問你該怎麼辦才好？", "keywords": [{"w": "荄", "m": "草根"}, {"w": "附榮", "m": "互相依附而茂盛"}, {"w": "溉", "m": "灌溉、澆水"}, {"w": "滋", "m": "滋養、使生長"}, {"w": "合", "m": "應該"}], "questions": [{"n": 9, "stem": "白居易〈問友〉一詩，藉由種植蘭草（香草）土裡卻跟著長出艾草（臭草），寫出世間的兩難情境。其詩為：「種蘭不種艾，蘭生艾亦生。根荄相交長，莖葉相附榮。香莖與臭葉，日夜俱長大。鋤□恐傷□，溉□恐滋□。□亦未能溉，□亦未能除。沉吟意不決，問君合何如？」根據文意，□處依序應填入下列何者最恰當？", "options": {"A": "艾／蘭／蘭／艾／艾／蘭", "B": "艾／蘭／蘭／艾／蘭／艾", "C": "蘭／艾／艾／蘭／艾／蘭", "D": "蘭／艾／艾／蘭／蘭／艾"}, "answer": "B", "explain": "作者想要的是蘭草、不要的是艾草。「鋤」是除掉，要除的當然是艾，怕傷到的是蘭：鋤艾恐傷蘭。「溉」是澆水，要澆的是蘭，怕順便滋養了艾：溉蘭恐滋艾。最後兩者都做不成：蘭亦未能溉，艾亦未能除。依序為艾、蘭、蘭、艾、蘭、艾，(B)正確。其他選項把要除的、要澆的對象弄反了。", "skill": "先確定「好的」（蘭）與「壞的」（艾），再依動詞性質填空：鋤→壞的、溉→好的。"}], "difficulty": "易", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-16", "exam": "bc100-nbk", "nums": [16], "form": "單題", "img": "img/bc100-nbk-16.png", "source": "選項為古語（出處待查）", "author": "", "genre": "經典語錄", "types": ["主旨寓意", "句意理解"], "passage": "(A)肚量當如海涵春育，操守應如青天白日　(B)大其心以容天下之物，虛其心以受天下之善　(C)智者知其一亦知其二，見其所見亦見其所不見　(D)君子不謗議他人以成己善，不掩沒天理以護己過", "translation": "(A)氣量應該像大海包容、春天孕育萬物，操守應該像青天白日般光明。(B)放寬心胸來容納天下萬物，虛心來接受天下的好意見。(C)有智慧的人知道一面也知道另一面，看見表面看得見的，也看見表面看不見的。(D)君子不毀謗別人來成全自己的好名聲，不掩蓋天理來袒護自己的過錯。", "keywords": [{"w": "海涵", "m": "像大海般包容"}, {"w": "虛其心", "m": "使心謙虛"}, {"w": "謗議", "m": "毀謗非議"}], "questions": [{"n": 16, "stem": "「真正的慧眼，是遼闊的，是包含一切的；它看了綠葉，還看見葉背後暗藏的軟蟲；它看見滿溪清水，也知道那水會暴漲變黃。」這段文字的涵義，與下列何者最接近？", "options": {"A": "肚量當如海涵春育，操守應如青天白日", "B": "大其心以容天下之物，虛其心以受天下之善", "C": "智者知其一亦知其二，見其所見亦見其所不見", "D": "君子不謗議他人以成己善，不掩沒天理以護己過"}, "answer": "C", "explain": "題幹說真正的慧眼看到綠葉也看到葉背的蟲，看到清水也知道它會變黃——能看到表面之外、隱藏的一面。(C)「知其一亦知其二，見其所見亦見其所不見」正是如此。(A)談氣量與操守。(B)談心胸寬大、虛心受教，重點是「包容」，題幹的「包含一切」指看得全面而非包容別人。(D)談不毀謗他人、不掩飾過錯。", "skill": "找出題幹的例子共同點（表面＋隱藏面），再找講「看得全面、看見看不見的」的選項；小心「遼闊、包含」字面誘答(B)。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-19", "exam": "bc100-nbk", "nums": [19], "form": "單題", "img": "img/bc100-nbk-19.png", "source": "出處待查（文意近蔡邕〈筆論〉）", "author": "", "genre": "說理議論", "types": ["句意理解", "文化常識"], "passage": "夫欲書先須凝神靜思，懷抱蕭散，陶寫性情，預想字形偃仰平直，然後書之。若迫於時，屈於勢，雖鍾、王不能佳也。", "translation": "想要寫字，必須先集中精神、安靜思考，讓胸懷閒適放鬆，抒發陶冶自己的性情，預先在心中構想字形的俯仰、平正與挺直，然後再下筆。如果被時間逼迫、受情勢壓迫，即使是鍾繇、王羲之也寫不好。", "keywords": [{"w": "夫", "m": "發語詞，無義"}, {"w": "蕭散", "m": "閒適放鬆"}, {"w": "偃仰", "m": "俯仰，指字的傾斜起伏"}, {"w": "迫於時", "m": "被時間逼迫"}, {"w": "屈於勢", "m": "受情勢所迫"}, {"w": "鍾、王", "m": "鍾繇、王羲之，魏晉書法名家"}], "questions": [{"n": 19, "stem": "「夫欲書先須凝神靜思，懷抱蕭散，陶寫性情，預想字形偃仰平直，然後書之。若迫於時，屈於勢，雖鍾、王不能佳也。」根據這段文字，下列敘述何者正確？", "options": {"A": "不屈迫於時勢者，達到的境界連鍾、王都不能超越", "B": "落筆之時須從容放鬆，但仍應在心中預擬字形架構", "C": "鍾、王能成為書法名家，是因運筆時會隨字形伸展肢體", "D": "學習書法乃為怡情養性，所以必須讓周邊環境保持寧靜"}, "answer": "B", "explain": "原文說寫字前要「懷抱蕭散」（放鬆）並「預想字形偃仰平直」（心中先構思字形），然後再寫，(B)正確。(A)原文是說受時勢逼迫時「連鍾、王都寫不好」，不是不受逼迫就能超越鍾、王。(C)「偃仰平直」是字形的樣子，不是伸展肢體。(D)「凝神靜思」是內心安靜，原文沒說要環境寧靜，也沒說學書法的目的是怡情養性。", "skill": "抓先後順序：凝神→放鬆→預想字形→然後書之；再注意「雖鍾、王不能佳」是讓步句。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-21", "exam": "bc100-nbk", "nums": [21], "form": "單題", "img": "img/bc100-nbk-21.png", "source": "《三國志‧吳書》裴松之注引《搜神記》（待查證）", "author": "", "genre": "史傳人物", "types": ["文化常識", "句意理解"], "passage": "孫堅夫人吳氏，孕而夢月入懷，已而生策。及權在孕，又夢日入懷。以告堅曰：『妾昔懷策，夢月入懷。今又夢日，何也？』堅曰：『日月者，陰陽之精，極貴之象。吾子孫其興乎？』", "translation": "孫堅的夫人吳氏，懷孕時夢見月亮進入懷中，不久生下孫策。等到懷孫權時，又夢見太陽進入懷中。她告訴孫堅說：「我從前懷孫策時，夢見月亮入懷。現在又夢見太陽，這是為什麼呢？」孫堅說：「太陽和月亮是陰陽的精華，是極為尊貴的徵兆。我的子孫大概要興盛了吧！」", "keywords": [{"w": "已而", "m": "不久"}, {"w": "及", "m": "等到"}, {"w": "妾", "m": "古代婦女的謙稱"}, {"w": "精", "m": "精華"}, {"w": "其", "m": "大概、應該（表推測）"}], "questions": [{"n": 21, "stem": "「孫堅夫人吳氏，孕而夢月入懷，已而生策。及權在孕，又夢日入懷。以告堅曰：『妾昔懷策，夢月入懷。今又夢日，何也？』堅曰：『日月者，陰陽之精，極貴之象。吾子孫其興乎？』」根據文中人物的關係，下列說明何者正確？", "options": {"A": "孫堅對孫策自稱「尊翁」", "B": "孫權對孫策自稱為「愚兄」", "C": "孫策對他人稱吳氏為「家母」", "D": "他人稱孫策與孫權為「賢喬梓」"}, "answer": "C", "explain": "吳氏是孫策的母親，孫策對別人稱自己的母親用謙稱「家母」，(C)正確。(A)「尊翁」是敬稱別人的父親，孫堅不能對兒子這樣自稱。(B)孫策先出生，是哥哥；孫權是弟弟，應自稱「愚弟」或「舍弟」，不是「愚兄」。(D)「喬梓」比喻父子，「賢喬梓」用來稱別人父子，孫策與孫權是兄弟，應稱「賢昆仲」。", "skill": "先從文中排出人物關係（孫堅夫婦→長子策、次子權），再用「稱己家用謙（家、舍、愚），稱人家用敬（令、尊、賢）」檢查。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-23", "exam": "bc100-nbk", "nums": [23], "form": "單題", "img": "img/bc100-nbk-23.png", "source": "選項：(B)《禮記‧儒行》；(A)《荀子‧勸學》；(C)《易經‧繫辭下》；(D)《荀子‧榮辱》", "author": "", "genre": "經典語錄", "types": ["主旨寓意", "比較閱讀"], "passage": "(A)鍥而不捨，金石可鏤　(B)身可危也，而志不可奪也　(C)安而不忘危，存而不忘亡　(D)自知者不怨人，知命者不怨天", "translation": "(A)不停地雕刻，金屬石頭也能刻穿。(B)身體可以遭遇危險，但志向不可以被改變。(C)安定時不忘記危險，生存時不忘記滅亡。(D)了解自己的人不埋怨別人，懂得天命的人不埋怨上天。", "keywords": [{"w": "鍥", "m": "雕刻"}, {"w": "鏤", "m": "雕刻"}, {"w": "奪", "m": "強行改變"}, {"w": "存", "m": "存在、生存"}], "questions": [{"n": 23, "stem": "（甲）即使最冷的朝代／你仍然筆直堅持／站在雨裡／父母兄弟都是／這樣的個性／永遠硬著頭顱而／不肯破裂　（乙）只要我們有根，／縱然沒有一片葉子遮身，／仍舊是一株頂天立地的樹。　下列何者最可能是這兩段詩句共同呈現的態度？", "options": {"A": "鍥而不捨，金石可鏤", "B": "身可危也，而志不可奪也", "C": "安而不忘危，存而不忘亡", "D": "自知者不怨人，知命者不怨天"}, "answer": "B", "explain": "甲詩寫在最冷的時代、雨中仍筆直堅持、硬著頭不肯破裂；乙詩寫即使沒有葉子遮身，只要有根仍頂天立地——兩者都是「外在環境再惡劣，也堅守氣節不改」。(B)身體可以受危害，志向卻不能被改變，最符合。(A)強調持續努力就能成功，重點在恆心。(C)強調居安思危。(D)強調不怨天尤人。", "skill": "先找兩首詩共同的「逆境＋堅持不變」結構，再把文言選項翻成白話比對，留意「志不可奪」對應「不肯破裂」。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-26", "exam": "bc100-nbk", "nums": [26], "form": "單題", "img": "img/bc100-nbk-26.png", "source": "對聯", "author": "", "genre": "其他", "types": ["文化常識", "寫作手法"], "passage": "(A)雲天有路月先到，忠孝傳家春早現　(B)竹因伴水情尤暢，蘭以當風氣自和　(C)花開春富貴，竹報歲平安　(D)綠共山中採，香宜竹裡煎", "translation": "(A)雲天有路，月亮先到；以忠孝傳家，春天早早出現。(B)竹子因為與水相伴而情致更舒暢，蘭花因為迎著風而香氣自然和美。(C)花開帶來春天的富貴，竹子報告一年的平安。(D)綠茶一同在山中採摘，茶香適合在竹林中烹煮。", "keywords": [{"w": "對仗", "m": "上下聯詞性、結構相對"}, {"w": "平仄", "m": "字音聲調的高低搭配"}], "questions": [{"n": 26, "stem": "一副工整的對聯必須「上下兩句字數相等，句法相似，平仄相對」。下列何者不符合這個原則？", "options": {"A": "雲天有路月先到，忠孝傳家春早現", "B": "竹因伴水情尤暢，蘭以當風氣自和", "C": "花開春富貴，竹報歲平安", "D": "綠共山中採，香宜竹裡煎"}, "answer": "A", "explain": "(A)上下聯字數相等，結構也大致相似（雲天／忠孝、有路／傳家、月先到／春早現），但上聯末字「到」、下聯末字「現」都是仄聲，違反對聯「上聯末字仄、下聯末字平」的平仄相對原則；且「雲天有路」與「忠孝傳家」詞意上也不相稱，所以不符合。(B)竹／蘭、因／以、伴水／當風、情尤暢／氣自和，字字相對，末字「暢」仄、「和」平。(C)花開／竹報、春富貴／歲平安，相對工整，「貴」仄「安」平。(D)綠／香、共／宜、山中採／竹裡煎，相對，「採」仄「煎」平。", "skill": "最快的檢查法：看上聯末字是否仄聲、下聯末字是否平聲，再逐詞比對詞性結構。"}], "difficulty": "難", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-27", "exam": "bc100-nbk", "nums": [27], "form": "單題", "img": "img/bc100-nbk-27.png", "source": "改寫自《百喻經》", "author": "僧伽斯那（求那毘地譯）", "genre": "寓言故事", "types": ["主旨寓意", "人物情感"], "passage": "昔有野人至田里，見麥苗鬱茂，問麥主：『何能令是麥茂好？』其主答：『平治其地，兼加糞水，故得如是！』彼人即依法用之。及至播種，畏其足踏田土，致使地堅而麥不生。曰：『我當坐一床上，使人輿之，於上播種，豈不甚好。』遂使四人，各擎一隅，至田播種，地堅愈甚，為人嗤笑。", "translation": "從前有個鄉下人到田裡，看見麥苗長得茂盛，問麥田主人：「怎樣能讓這麥子長得這麼好？」主人回答：「把土地整平，再加上糞水施肥，所以能這樣！」那人就照這個方法做。等到播種時，他怕自己的腳踩踏田土，會使地變硬而麥子長不出來。他說：「我應該坐在一張坐榻上，叫人抬著，在上面播種，豈不是很好。」於是叫四個人，各舉起坐榻的一角，到田裡播種，結果土地被踩得更硬，被人嘲笑。", "keywords": [{"w": "野人", "m": "鄉下人"}, {"w": "鬱茂", "m": "茂盛"}, {"w": "平治", "m": "整平"}, {"w": "畏", "m": "害怕"}, {"w": "床", "m": "坐榻"}, {"w": "輿", "m": "扛抬"}, {"w": "擎", "m": "舉"}, {"w": "嗤笑", "m": "譏笑"}], "questions": [{"n": 27, "stem": "「昔有野人至田里，見麥苗鬱茂，問麥主：『何能令是麥茂好？』其主答：『平治其地，兼加糞水，故得如是！』彼人即依法用之。及至播種，畏其足踏田土，致使地堅而麥不生。曰：『我當坐一床上，使人輿之，於上播種，豈不甚好。』遂使四人，各擎一隅，至田播種，地堅愈甚，為人嗤笑。」下列何者最適合用來形容故事中的野人？", "options": {"A": "自作聰明，弄巧成拙", "B": "不聽人言，一意孤行", "C": "所用非人，淪為笑柄", "D": "揠苗助長，反受其害"}, "answer": "A", "explain": "野人怕自己一雙腳踩硬土地，自以為聰明地叫四個人抬他播種，結果八隻腳踩得土地更硬——想得巧反而弄得更糟，(A)正確。(B)他一開始還虛心請教、照方法做，不是不聽人言。(C)問題不在用錯人，而在他的方法本身荒謬。(D)「揠苗助長」是急於求成而違反自然，野人是怕踩地，並非急著讓麥子長大。", "skill": "算一算後果：一人兩腳→四人八腳，就能看出「想出妙招反而更糟」的諷刺點。"}], "difficulty": "易", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-29", "exam": "bc100-nbk", "nums": [29], "form": "單題", "img": "img/bc100-nbk-29.png", "source": "葛洪《抱朴子‧勖學》", "author": "葛洪", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "不飽食以終日，不棄功於寸陰。", "translation": "不整天吃飽飯而無所事事，不浪費一寸光陰的功夫。", "keywords": [{"w": "飽食以終日", "m": "整天吃飽了沒事做"}, {"w": "寸陰", "m": "極短的時間"}, {"w": "韶華", "m": "美好的青春時光"}, {"w": "暫輟", "m": "暫時停止"}], "questions": [{"n": 29, "stem": "「不飽食以終日，不棄功於寸陰。」這句話的涵義與下列何者最接近？", "options": {"A": "時不可以坐待，道不可以虛言", "B": "智者當知乘時趨勢，不可忽失", "C": "韶華不為少年留，志士勤力無暫輟", "D": "歲晚而橙橘芳馨，君子晚年精神倍出"}, "answer": "C", "explain": "原句強調珍惜光陰、勤奮不懈。(C)青春不會為少年停留，有志之士勤奮努力不曾暫停，同樣是惜時勤勉，正確。(A)講時機不能坐等、道理不能空談，重點在實踐。(B)講聰明人要把握時機、順應趨勢。(D)講君子到晚年精神更好，與惜時無關。", "skill": "抓關鍵詞「寸陰」＝時間、「不棄功」＝不停努力，找同時有「時間」與「勤奮」的選項。"}], "difficulty": "易", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-30", "exam": "bc100-nbk", "nums": [30], "form": "單題", "img": "img/bc100-nbk-30.png", "source": "袁宏道〈徐文長傳〉", "author": "袁宏道", "genre": "史傳人物", "types": ["句意理解", "人物情感"], "passage": "文長既已不得志於有司，遂乃放浪麴櫱，恣情山水，走齊、魯、燕、趙之地，窮覽朔漠。其所見山奔海立，沙起雷行，雨鳴樹偃，幽谷大都，人物魚馬，一切可驚可愕之狀，一一皆達之於詩。", "translation": "徐文長在官場（科舉）上不得志之後，就放縱自己沉迷於酒，縱情於山水之間，走遍齊、魯、燕、趙各地，遍覽北方沙漠。他所看到的山勢奔騰、海浪聳立，風沙揚起、雷聲滾動，雨聲轟鳴、樹木倒伏，幽深的山谷與繁華的都市，人物、魚、馬，一切令人驚訝的景象，都一一表達在詩中。", "keywords": [{"w": "有司", "m": "職有專司，此指官場"}, {"w": "麴櫱", "m": "酒的代稱"}, {"w": "放浪", "m": "放縱不受拘束"}, {"w": "恣情", "m": "縱情"}, {"w": "窮覽", "m": "遍覽"}, {"w": "朔漠", "m": "北方沙漠"}, {"w": "達", "m": "表達"}], "questions": [{"n": 30, "stem": "袁宏道〈徐文長傳〉：「文長既已不得志於有司，遂乃放浪麴櫱，恣情山水，走齊、魯、燕、趙之地，窮覽朔漠。其所見山奔海立，沙起雷行，雨鳴樹偃，幽谷大都，人物魚馬，一切可驚可愕之狀，一一皆達之於詩。」根據上文，徐文長「不得志於有司」後所表現出的行為，與下列何者最接近？", "options": {"A": "醉心風月，流連歌樓舞榭", "B": "標新立異，勇於引領風潮", "C": "躬耕田園，不再追求仕進功名", "D": "別寄所託，尋求不同生命體驗"}, "answer": "D", "explain": "徐文長仕途失意後，轉而飲酒、遊歷山水、走遍各地，並把所見寫入詩中——把心力寄託在其他地方，追求不一樣的人生經驗，(D)正確。(A)他是縱情山水，不是流連歌樓舞榭。(B)原文沒提到他標新立異或引領風潮。(C)他是四處遊歷，不是在田園耕種。", "skill": "列出失意後的具體行為（喝酒、遊山水、寫詩），再找能概括這些行為的選項。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-33", "exam": "bc100-nbk", "nums": [33], "form": "單題", "img": "img/bc100-nbk-33.png", "source": "出處待查（諷刺詩）", "author": "", "genre": "古典詩詞曲", "types": ["文意推論", "詩詞賞析"], "passage": "欲作驚人詩萬首，朝吟暮詠總無成。日前示我以佳句：『仄仄平平仄仄平』。", "translation": "想要寫出上萬首驚人的詩，從早到晚吟詠卻總是寫不成。前幾天拿他的佳句給我看：「仄仄平平仄仄平」。", "keywords": [{"w": "朝吟暮詠", "m": "從早到晚吟詩"}, {"w": "示", "m": "給……看"}, {"w": "仄仄平平仄仄平", "m": "七言律句的平仄格式"}], "questions": [{"n": 33, "stem": "某詩人寫下鄰人欲學作詩的情況：「欲作驚人詩萬首，朝吟暮詠總無成。日前示我以佳句：『仄仄平平仄仄平』。」根據上述，下列何者最可能是鄰人的創作情形？", "options": {"A": "靈光乍現，語出驚人", "B": "詩興大發，出口成章", "C": "千篇一律，了無新意", "D": "絞盡腦汁，難以成篇"}, "answer": "D", "explain": "鄰人「朝吟暮詠總無成」，可見苦思而寫不出來；拿出的「佳句」竟只是平仄格式「仄仄平平仄仄平」，沒有任何內容，詩人藉此諷刺他費盡心思仍寫不出詩，(D)正確。(A)(B)與「總無成」矛盾。(C)「千篇一律」表示寫了很多但都一樣，鄰人連一首都寫不成。引號標示表示「仄仄平平仄仄平」是直接引用鄰人自認的佳句，只是基本格律，毫無內容，所以答案是(D)。", "skill": "抓「總無成」＋「佳句只剩平仄符號」兩個證據，推出「寫不出來」。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-34", "exam": "bc100-nbk", "nums": [34], "form": "單題", "img": "img/bc100-nbk-34.png", "source": "《淮南子‧人間訓》", "author": "劉安", "genre": "寓言故事", "types": ["主旨寓意", "句意理解"], "passage": "夫鵲先識歲之多風也，去高木而巢扶枝。大人過之則探鷇，嬰兒過之則挑其卵。知備遠難而忘近患。", "translation": "喜鵲事先知道這一年風大，就離開高樹，把巢築在低矮的樹枝上。結果大人經過就伸手掏取雛鳥，小孩經過就挑弄牠的蛋。喜鵲知道防備遠處的災難，卻忘了身邊的禍患。", "keywords": [{"w": "識", "m": "知道"}, {"w": "巢", "m": "築巢（名詞作動詞）"}, {"w": "扶枝", "m": "低矮的樹枝"}, {"w": "鷇", "m": "初生幼鳥"}, {"w": "挑", "m": "挑弄、掏取"}], "questions": [{"n": 34, "stem": "「夫鵲先識歲之多風也，去高木而巢扶枝。大人過之則探鷇，嬰兒過之則挑其卵。知備遠難而忘近患。」這則故事所要警惕世人的道理，與下列何者最接近？", "options": {"A": "防微杜漸，則災患不至", "B": "人無遠慮，則必有近憂", "C": "行事當按部就班，不可躁進", "D": "慮事須周延，切勿顧此失彼"}, "answer": "D", "explain": "喜鵲為了躲避強風（遠難）把巢移低，卻招來人類掏鳥取蛋（近患），顧了這頭卻失了那頭，(D)正確。(A)講在禍患剛萌芽時就防止，喜鵲的問題不是防得太晚。(B)講沒有長遠考慮會有眼前憂患，但喜鵲恰恰「有遠慮」，問題是忘了近患。(C)講循序漸進，與故事無關。", "skill": "抓結論句「知備遠難而忘近患」，再小心(B)：喜鵲不是沒有遠慮，而是只顧遠不顧近。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-35", "exam": "bc100-nbk", "nums": [35], "form": "單題", "img": "img/bc100-nbk-35.png", "source": "朱用純《朱子治家格言》", "author": "朱用純（朱柏廬）", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "輕聽發言，安知非人之譖愬？當忍耐三思！因事相爭，焉知非我之不是？須平心再想！", "translation": "輕易聽信別人的話，怎麼知道那不是別人的毀謗誣陷？應該忍耐並再三思考！因為事情和人爭執，怎麼知道不是自己的錯？必須平心靜氣再想一想！", "keywords": [{"w": "輕聽", "m": "輕易聽信"}, {"w": "安知、焉知", "m": "怎麼知道"}, {"w": "譖愬", "m": "詆毀、誣陷"}, {"w": "不是", "m": "過錯"}, {"w": "剛愎", "m": "固執己見"}, {"w": "反求諸己", "m": "反過來要求自己、檢討自己"}], "questions": [{"n": 35, "stem": "「輕聽發言，安知非人之譖愬？當忍耐三思！因事相爭，焉知非我之不是？須平心再想！」這段話的涵義與下列何者最接近？", "options": {"A": "妄聽生奸，剛愎自敗；行有不得，反求諸己", "B": "與人善言，暖於布帛；傷人之言，深於矛戟", "C": "見異思遷，土坡難翻；專心致志，高峰能攀", "D": "揚人之善，隱人之過；讓人一寸，人讓一尺"}, "answer": "A", "explain": "原文兩層：①不要輕信別人的話，以免中了讒言；②與人爭執時，先想想是不是自己的錯。(A)「妄聽生奸」對應①，「行有不得，反求諸己」對應②，最接近。(B)講說話的影響力，好話溫暖、惡言傷人。(C)講做事要專心。(D)講稱揚別人優點、忍讓待人，沒有「不輕信」與「自我檢討」。", "skill": "把原文拆成兩句重點，找能前後各自對應的選項。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-36", "exam": "bc100-nbk", "nums": [36, 37], "form": "題組", "img": "img/bc100-nbk-36.png", "source": "改寫自段成式《酉陽雜俎‧語資》", "author": "段成式", "genre": "筆記小品", "types": ["字詞解釋", "文意推論", "文化常識"], "passage": "明皇封禪泰山，張說為封禪使，說女婿鄭鎰，本九品官，舊例封禪後，自三公以下皆遷轉一級，惟鄭鎰因說驟遷五品，兼賜緋服。元宗見鎰官位騰躍，怪而問之，鎰無詞以對，黃旛綽曰：「此泰山之力也。」", "translation": "唐明皇到泰山舉行封禪大典，張說擔任封禪使。張說的女婿鄭鎰本來是九品小官，依照舊例，封禪之後從三公以下的官員都升官一級，只有鄭鎰因為張說的關係，一下子升到五品，還被賜予紅色官服。玄宗看到鄭鎰官位飛升，覺得奇怪而問他，鄭鎰答不出話來，黃旛綽說：「這是泰山的力量啊。」（泰山也是岳父的別稱，語帶雙關）", "keywords": [{"w": "封禪", "m": "帝王祭祀天地的大典"}, {"w": "遷轉", "m": "升官"}, {"w": "驟", "m": "突然、急速"}, {"w": "緋服", "m": "紅色官服，高品級官員所穿"}, {"w": "騰躍", "m": "飛升"}, {"w": "泰山", "m": "岳父的別稱（雙關）"}], "questions": [{"n": 36, "stem": "根據前後文意判別，文中「遷轉」一詞的涵義為下列何者？", "options": {"A": "貶官", "B": "升官", "C": "賞賜財物", "D": "轉任地方官"}, "answer": "B", "explain": "後文說鄭鎰「驟遷五品」、「官位騰躍」，從九品一下子到五品，可見「遷」在這裡是升官；同樣封禪後的情境，其他官員「遷轉一級」也是升一級，(B)正確。(A)與「騰躍」相反。(C)賞賜是「賜緋服」，與「遷轉」分開敘述。(D)文中沒有轉任地方的訊息。「惟」表示鄭鎰的情況（連升數級）與舊例（升一級）不協調，兩者都是升官。", "skill": "用同一段裡相同的字「遷」（驟遷五品）來反推「遷轉」的意思。"}, {"n": 37, "stem": "根據本文，黃旛綽說：「此泰山之力也。」此話道出鄭鎰驟遷五品的原因是下列何者？", "options": {"A": "鄭鎰曾參與泰山封禪有功", "B": "憑藉黃旛綽而在泰山建功", "C": "明皇賞識鄭鎰的文采學識", "D": "依靠與張說的關係而得利"}, "answer": "D", "explain": "「泰山」既指封禪的泰山，也是「岳父」的別稱。鄭鎰是張說的女婿，文中明說他「因說驟遷五品」，黃旛綽用雙關語暗諷他是靠岳父張說才升官，(D)正確。(A)表面上像是封禪之功，但其他官員只升一級，鄭鎰卻連升數級，原因在張說。(B)黃旛綽只是說話的人，與升官無關。(C)文中沒提鄭鎰的文采。", "skill": "注意「泰山」的雙關（山名／岳父），再對照前文「說女婿」「因說驟遷」。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-38", "exam": "bc100-nbk", "nums": [38, 39], "form": "題組", "img": "img/bc100-nbk-38.png", "source": "紀昀《閱微草堂筆記》", "author": "紀昀", "genre": "筆記小品", "types": ["句意理解", "主旨寓意", "虛詞句式"], "passage": "有疫死還魂者，在冥司遇其故人，襤褸荷校。相見悲喜，不覺握手太息曰：「君一生富貴，竟不能帶至此耶？」其人蹙然曰：「富貴皆可帶至此，但人不肯帶耳。生前有功德者，至此何嘗不富貴耶？寄語世人，早作帶來計可也。」李南澗曰：「善哉斯言，勝於謂富貴皆空也。」", "translation": "有個得瘟疫死去又復活的人，在陰間遇到他的老朋友，衣衫破爛，扛著刑具。兩人相見又悲又喜，（還魂者）不自覺握著他的手嘆氣說：「你一生富貴，竟然不能帶到這裡來嗎？」那人憂愁地說：「富貴都可以帶到這裡，只是人們不肯帶罷了。生前有功德的人，到了這裡何嘗不富貴呢？請轉告世人，早點做好把富貴帶來的打算吧。」李南澗說：「這話說得真好，勝過說富貴都是空的。」", "keywords": [{"w": "冥司", "m": "陰間"}, {"w": "故人", "m": "老朋友"}, {"w": "襤褸", "m": "衣服破爛"}, {"w": "荷校", "m": "扛著刑具（校：古代刑具）"}, {"w": "太息", "m": "嘆氣"}, {"w": "蹙然", "m": "憂愁貌"}, {"w": "寄語", "m": "傳話、轉告"}], "questions": [{"n": 38, "stem": "下列文句，何者主語是文中的還魂者？", "options": {"A": "襤褸荷校", "B": "不覺握手太息曰", "C": "至此何嘗不富貴耶", "D": "早作帶來計可也"}, "answer": "B", "explain": "(B)還魂者見到老友，不自覺握著他的手嘆氣，並問「君一生富貴，竟不能帶至此耶」，說話的是還魂者，正確。(A)衣衫破爛、扛著刑具的是在陰間受罰的老朋友。(C)「至此何嘗不富貴」的主語是「生前有功德者」。(D)「早作帶來計」是老朋友要世人做的事，主語是「世人」。", "skill": "先確認全文兩個角色（還魂者、故人）分別說了什麼話、處在什麼狀態，再把每個句子歸給正確的人。"}, {"n": 39, "stem": "本文主旨在說明下列何者？", "options": {"A": "人生如曇花一現，轉眼成空", "B": "不義而富且貴，於我如浮雲", "C": "勿謀求名利富貴，宜多行善事", "D": "賢而多財損志，愚而多財增過"}, "answer": "C", "explain": "故人說真正能帶到陰間的「富貴」是生前的功德，勸世人早做打算——也就是不要汲汲於追求名利，而要多做善事、累積功德，(C)正確。(A)李南澗特別說這話「勝於謂富貴皆空」，可見主旨不是人生成空。(B)講不用不正當手段求富貴，文中沒提不義。(D)講錢多對賢者、愚者的害處，與功德無關。", "skill": "注意文末評論「勝於謂富貴皆空」，排除「一切皆空」的選項，主旨落在「功德才是帶得走的富貴」。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc100-nbk-40", "exam": "bc100-nbk", "nums": [40, 41], "form": "題組", "img": "img/bc100-nbk-40.png", "source": "改寫自梁啟超《飲冰室文集‧養心語錄》", "author": "梁啟超", "genre": "說理議論", "types": ["句意理解", "文意推論", "主旨寓意"], "passage": "人之生也，與憂患俱來。種種煩惱皆為我練心之助，種種危險皆為我練膽之助，隨處皆我之學校也。我正患無就學之地，而時時有此天造地設之學堂以餉之，不亦幸乎！我輩遇煩惱、遇危險時，作如是觀，未有不灑脫自得者。凡辦事必有阻力。其事小者，其阻力亦小；其事愈大，其阻力亦愈大；故我輩惟當察阻力之來而排之，不可畏阻力之來而避之。譬之江河，千里入海，曲折奔赴，遇有沙石則挾之而下，遇有山陵則繞越而行。要之，必以至海為究竟。辦事遇阻力者當作如是觀。至誠所感，金石為開，何阻力之有焉。苟畏而避之，則終無一事可辦而已。何也？天下固無無阻力之事也。", "translation": "人一出生，就和憂患一起到來。各種煩惱都是幫我磨練心志的助力，各種危險都是幫我鍛鍊膽量的助力，到處都是我的學校。我正擔心沒有求學的地方，卻時時有這天然形成的學堂贈送給我，不也很幸運嗎！我們遇到煩惱、危險時，如果這樣看待，沒有不灑脫自在的。凡是做事一定有阻力。事情小，阻力也小；事情越大，阻力也越大；所以我們只應該察看阻力的來由而排除它，不可以害怕阻力而逃避它。就像江河奔流千里入海，曲折前進，遇到沙石就挾帶著沖下去，遇到山陵就繞過去，總之一定以到達大海為最終目標。做事遇到阻力的人應該這樣看待。真誠所到之處，連金石都能被打開，還有什麼阻力呢？如果害怕而逃避，那就終究一件事也辦不成。為什麼呢？因為天下本來就沒有沒有阻力的事啊。", "keywords": [{"w": "俱", "m": "一起"}, {"w": "患", "m": "擔心"}, {"w": "餉", "m": "贈送"}, {"w": "作如是觀", "m": "這樣看待"}, {"w": "挾", "m": "夾帶"}, {"w": "要之", "m": "總之"}, {"w": "究竟", "m": "最終目標"}, {"w": "固", "m": "本來"}], "questions": [{"n": 40, "stem": "根據本文，下列句意說明何者正確？", "options": {"A": "「時時有此天造地設之學堂以餉之」，意謂大自然中蟲魚鳥獸皆可為學習的對象", "B": "「作如是觀，未有不灑脫自得者」，句中「如是觀」是指把生命中的憂患視為鍛鍊", "C": "「遇有沙石則挾之而下，遇有山陵則繞越而行」，意謂處事當循序而行，勿貿然躁進", "D": "「天下固無無阻力之事也」，可見天下事本無阻力，凡阻力皆為我輩自尋"}, "answer": "B", "explain": "(B)「如是觀」承接前文「種種煩惱皆為我練心之助，種種危險皆為我練膽之助」，就是把憂患當成鍛鍊的機會，正確。(A)「天造地設之學堂」指生活中的煩惱與危險，不是大自然的蟲魚鳥獸。(C)江河遇沙石就挾帶、遇山就繞行，意思是遇到阻力要設法排除或繞過，堅持到達目標，不是循序漸進。(D)「固無無阻力之事」是雙重否定，意思是「天下本來就沒有不遇阻力的事」，選項解釋反了。", "skill": "「如是」「此」等指代詞要回前文找所指；遇到「無無」雙重否定要轉成肯定句。"}, {"n": 41, "stem": "根據本文，作者認為面對阻力時人們該抱持的心態，不包含下列何者？", "options": {"A": "把煩惱視為磨練心性的助力", "B": "細察阻力之由來而設法排除", "C": "無畏無懼，秉持至誠之心為之", "D": "權衡局勢，見阻力之來而退卻"}, "answer": "D", "explain": "作者明說「不可畏阻力之來而避之」「苟畏而避之，則終無一事可辦」，所以見阻力就退卻正是作者反對的，(D)不包含，是答案。(A)對應「種種煩惱皆為我練心之助」。(B)對應「察阻力之來而排之」。(C)對應「至誠所感，金石為開」與不可畏避。", "skill": "「不包含」題：逐一回文找對應句，找不到或與原文相反的就是答案。"}], "difficulty": "中", "label": "100年北北基聯測", "year": 100, "kind": "基測"}, {"id": "bc101-1-3", "exam": "bc101-1", "nums": [3], "form": "單題", "img": "img/bc101-1-3.png", "source": "張潮《幽夢影》", "author": "張潮", "genre": "筆記小品", "types": ["句意理解", "字詞解釋"], "passage": "對淵博友，如讀異書；對風雅友，如讀名人詩文；對謹飭友，如讀聖賢經傳；對滑稽友，如閱傳奇小說。", "translation": "和學問淵博的朋友相處，就像讀奇特少見的書；和風雅的朋友相處，就像讀名人的詩文；和謹慎端正的朋友相處，就像讀聖賢的經典；和幽默詼諧的朋友相處，就像看傳奇小說。", "keywords": [{"w": "淵博", "m": "學識深廣"}, {"w": "異書", "m": "奇特少見的書"}, {"w": "謹飭", "m": "謹慎端正、嚴守規矩"}, {"w": "滑稽", "m": "言語詼諧有趣"}, {"w": "經傳", "m": "經典及其注解"}], "questions": [{"n": 3, "stem": "張潮《幽夢影》說：「對淵博友，如讀異書；對風雅友，如讀名人詩文；對謹飭友，如讀聖賢經傳；對滑稽友，如閱傳奇小說。」某君講信用，重然諾，行事穩健，工作負責。根據這些特質判別，與某君交往如同閱讀下列何種書籍？", "options": {"A": "異書", "B": "名人詩文", "C": "聖賢經傳", "D": "傳奇小說"}, "answer": "C", "explain": "某君講信用、重承諾、行事穩健、工作負責，是謹慎端正、守規矩的人，屬於「謹飭友」，與他交往如讀「聖賢經傳」，(C)正確。(A)對應淵博（學問廣博）的朋友。(B)對應風雅（有藝術品味）的朋友。(D)對應滑稽（幽默有趣）的朋友，都不符合某君的特質。", "skill": "先把某君的特質歸納成一個詞（謹慎守信＝謹飭），再到原文找對應的書。"}], "difficulty": "易", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-13", "exam": "bc101-1", "nums": [13], "form": "單題", "img": "img/bc101-1-13.png", "source": "(A)王安石〈登飛來峰〉；(B)杜牧〈清明〉；(C)李白〈贈汪倫〉；(D)杜甫〈江畔獨步尋花〉", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "虛詞句式"], "passage": "行到水窮處，坐看雲起時。／(A)不畏浮雲遮望眼，只緣身在最高層　(B)借問酒家何處有，牧童遙指杏花村　(C)桃花潭水深千尺，不及汪倫送我情　(D)留連戲蝶時時舞，自在嬌鶯恰恰啼", "translation": "走到溪水的盡頭，就坐下來看雲升起。(A)不怕浮雲遮住遠望的視線，只因為自己站在最高處。(B)請問哪裡有酒家？牧童遠遠指向杏花村。(C)桃花潭的水深達千尺，也比不上汪倫送我的情意。(D)流連花間的蝴蝶不時飛舞，自由自在的黃鶯恰好啼叫。", "keywords": [{"w": "順接", "m": "兩句依時間或事件先後排列"}, {"w": "緣", "m": "因為"}, {"w": "借問", "m": "請問"}, {"w": "不及", "m": "比不上"}], "questions": [{"n": 13, "stem": "兩句之間，依照動作發生時間的順序，或事件發展次序的先後排列，彼此就有「順接」關係，如：「行到水窮處，坐看雲起時」。下列詩句，何者也屬於順接關係？", "options": {"A": "不畏浮雲遮望眼，只緣身在最高層", "B": "借問酒家何處有，牧童遙指杏花村", "C": "桃花潭水深千尺，不及汪倫送我情", "D": "留連戲蝶時時舞，自在嬌鶯恰恰啼"}, "answer": "B", "explain": "(B)先有人發問「酒家何處有」，接著牧童才遙指杏花村，一問一答依事件先後發生，是順接關係，正確。(A)「只緣」表示原因，後句說明前句的原因，是因果關係。(C)用潭水之深和汪倫的情意相比較，是比較（遞進）關係。(D)蝴蝶飛舞與黃鶯啼叫同時發生，是並列關係。", "skill": "判斷兩句能不能互換順序：不能換、而且有先後時間的，就是順接；有「緣、因」是因果，同時發生是並列。"}], "difficulty": "中", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-16", "exam": "bc101-1", "nums": [16], "form": "單題", "img": "img/bc101-1-16.png", "source": "袁枚《隨園詩話》", "author": "袁枚", "genre": "說理議論", "types": ["句意理解", "寫作手法"], "passage": "《漫齋語錄》曰：『詩用意要精深，下語要平淡。』余愛其言，每作一詩，往往改至三五日，或過時而又改，何也？求其精深，是一半工夫；求其平淡，又是一半工夫，非精深不能超超獨先，非平淡不能人人領解。", "translation": "《漫齋語錄》說：「寫詩，立意要精深，用語要平淡。」我很喜愛這句話，每寫一首詩，常常要修改三五天，或過了一段時間又再修改，為什麼呢？追求精深，是一半的功夫；追求平淡，又是另一半的功夫。不精深就不能超群出眾、獨占鰲頭，不平淡就不能讓每個人都讀得懂。", "keywords": [{"w": "用意", "m": "立意、構思"}, {"w": "下語", "m": "用字遣詞"}, {"w": "超超獨先", "m": "超群出眾，遙遙領先"}, {"w": "領解", "m": "領會理解"}], "questions": [{"n": 16, "stem": "袁枚說：「《漫齋語錄》曰：『詩用意要精深，下語要平淡。』余愛其言，每作一詩，往往改至三五日，或過時而又改，何也？求其精深，是一半工夫；求其平淡，又是一半工夫，非精深不能超超獨先，非平淡不能人人領解。」根據這段文字，可知他的文學創作主張為下列何者？", "options": {"A": "辭主達意，不論繁簡", "B": "文之為物，貴有靈氣", "C": "意中有景，景中有意", "D": "鍊意鍊辭，深入淺出"}, "answer": "D", "explain": "袁枚反覆修改詩作，一半功夫求「用意精深」（鍊意），一半功夫求「下語平淡」（鍊辭），讓深刻的意思用淺白的話說出來、人人都懂，即(D)「鍊意鍊辭，深入淺出」。(A)「不論繁簡」與他刻意追求平淡的用語不符。(B)談文章的靈氣，原文沒提。(C)談情景交融，原文沒提。", "skill": "抓原文兩組關鍵詞「用意精深」與「下語平淡」，找能同時涵蓋「意」與「辭」的選項。"}], "difficulty": "中", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-17", "exam": "bc101-1", "nums": [17], "form": "單題", "img": "img/bc101-1-17.png", "source": "選項：(A)《戰國策‧秦策》；(B)《老子》第六十四章；(C)(D)俗諺", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "(A)行百里者半於九十　(B)千里之行始於足下", "translation": "(A)要走一百里路的人，走了九十里只能算走了一半（越接近終點越艱難，要堅持到底）。(B)千里遠的路程，是從腳下第一步開始的。", "keywords": [{"w": "半於九十", "m": "走到九十里才算一半"}, {"w": "始於足下", "m": "從腳下第一步開始"}], "questions": [{"n": 17, "stem": "「真正的考驗，並不是第一里路，而是旅程最後一里路。」這句話的涵義，與下列何者最接近？", "options": {"A": "行百里者半於九十", "B": "千里之行始於足下", "C": "不走萬里路，哪來鐵腳板", "D": "謹慎走天下，魯莽步難行"}, "answer": "A", "explain": "題幹說最難的是最後一里路，強調越接近終點越要堅持。(A)走一百里的人走到九十里才算一半，意思是最後一段最艱難，要堅持到底，最接近。(B)強調從第一步做起，重點在開始，與題幹相反。(C)強調多歷練才能練出本事。(D)強調做事要謹慎。", "skill": "把題幹重點定為「最後階段最難」，再判斷文言選項說的是開始、過程還是結尾。"}], "difficulty": "易", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-18", "exam": "bc101-1", "nums": [18], "form": "單題", "img": "img/bc101-1-18.png", "source": "賀新居聯語（典出陶淵明〈歸去來辭〉、孟母三遷故事）", "author": "", "genre": "其他", "types": ["典故出處", "文化常識"], "passage": "松菊陶潛宅，詩書孟子鄰。", "translation": "住宅像陶淵明的家一樣有松樹菊花，鄰居像孟子一家一樣是讀詩書的人。", "keywords": [{"w": "松菊陶潛宅", "m": "陶淵明〈歸去來辭〉「三徑就荒，松菊猶存」，指隱居的宅第"}, {"w": "孟子鄰", "m": "孟母三遷，擇鄰而居，指好鄰居"}], "questions": [{"n": 18, "stem": "「松菊陶潛宅，詩書孟子鄰」這副聯語最適合用於祝賀下列哪一件事？", "options": {"A": "金榜題名", "B": "職場升遷", "C": "搬遷新居", "D": "書店開張"}, "answer": "C", "explain": "上聯用陶淵明宅院有松菊的典故，稱讚住宅清雅；下聯用孟母三遷、選擇好鄰居的典故，稱讚鄰居有書香。一講住宅、一講鄰居，最適合祝賀搬遷新居，(C)正確。(A)金榜題名應用科舉、登科相關語。(B)升遷應用高升、鵬程類語句。(D)聯中「詩書」只是形容鄰居，不是賣書。", "skill": "找出聯語中的關鍵詞「宅」「鄰」，再聯想典故（陶潛的家、孟母擇鄰）指向「住處」。"}], "difficulty": "中", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-21", "exam": "bc101-1", "nums": [21], "form": "單題", "img": "img/bc101-1-21.png", "source": "(A)杜甫〈江村〉；其餘出處待查", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "詩詞賞析"], "passage": "(A)老妻畫紙為棋局，稚子敲針作釣鉤　(B)正抽碧線繡紅羅，忽聽黃鶯斂翠蛾　(C)欲教針線嬌難解，暫弄琴書性已便　(D)家人競喜開妝鏡，月下穿針拜九霄", "translation": "(A)老妻在紙上畫棋盤，小兒子把針敲彎做成釣鉤。(B)正抽著綠線在紅綢上刺繡，忽然聽到黃鶯啼叫而皺起眉頭。(C)想教她針線活，她卻嬌憨學不會；暫且讓她玩琴讀書，她倒很順手。(D)家人都高興地打開妝鏡，在月下穿針、祭拜天上的神明。", "keywords": [{"w": "乞巧", "m": "七夕婦女對月穿針，乞求手巧"}, {"w": "斂翠蛾", "m": "皺起眉頭"}, {"w": "九霄", "m": "天空極高處，指天上的神（織女）"}], "questions": [{"n": 21, "stem": "相傳陰曆七月七日為天上牛郎、織女相會之期，此日婦女往往會對月引線穿針，在庭院中祭拜，以乞求雙手靈巧，長於刺繡，此稱為「乞巧」。下列詩句何者是在描述這項習俗？", "options": {"A": "老妻畫紙為棋局，稚子敲針作釣鉤", "B": "正抽碧線繡紅羅，忽聽黃鶯斂翠蛾", "C": "欲教針線嬌難解，暫弄琴書性已便", "D": "家人競喜開妝鏡，月下穿針拜九霄"}, "answer": "D", "explain": "題幹指出乞巧的特徵是「對月引線穿針」「祭拜」。(D)「月下穿針拜九霄」三個特徵都有，正確。(A)寫家人下棋、做釣鉤的閒適生活，雖有「針」但不是穿針乞巧。(B)寫女子刺繡時聽到鶯啼而皺眉，是一般刺繡情景。(C)寫女孩學不會針線而改玩琴書，與節日習俗無關。", "skill": "把題幹習俗拆成關鍵動作（月下、穿針、祭拜），逐一比對選項，全部符合才是答案。"}], "difficulty": "易", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-25", "exam": "bc101-1", "nums": [25], "form": "單題", "img": "img/bc101-1-25.png", "source": "洪應明《菜根譚》", "author": "洪應明", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "魚網之設，鴻則罹其中；螳螂之貪，雀又乘其後。機裡藏機，變外生變，智巧何足恃哉！", "translation": "張設魚網（本想捕魚），鴻雁卻落入網中；螳螂貪心捕蟬，黃雀又趁機在牠後面（要吃牠）。計謀之中還藏著計謀，變化之外又生出變化，聰明巧詐哪裡值得依靠呢！", "keywords": [{"w": "罹", "m": "遭受、陷入"}, {"w": "乘", "m": "趁機"}, {"w": "機", "m": "機關、計謀"}, {"w": "恃", "m": "依靠"}], "questions": [{"n": 25, "stem": "「魚網之設，鴻則罹其中；螳螂之貪，雀又乘其後。機裡藏機，變外生變，智巧何足恃哉！」這段文字的主旨，與下列何者最接近？", "options": {"A": "智者遠見於未萌，而避危於未形", "B": "天機不可洩，睿智者能察而不言", "C": "巧智多謀者，常因好涉險而招難", "D": "世事變數之多，非巧計者可盡謀"}, "answer": "D", "explain": "網子本為捕魚卻捕到鴻雁，螳螂捕蟬卻被黃雀盯上——世事充滿意想不到的變化，再聰明的計謀也算不盡，所以「智巧何足恃」。(D)「世事變數多，不是巧於計謀的人能完全算計」，最接近。(A)講智者有遠見能預先避禍，與「智巧不足恃」相反。(B)講天機不可洩漏。(C)講聰明人因愛冒險而招災，原文重點是變化難料，不是冒險。", "skill": "兩個例子共同點是「結果出乎意料」，再配合結論句「智巧何足恃」，主旨即「變數多，計算不盡」。"}], "difficulty": "中", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-27", "exam": "bc101-1", "nums": [27], "form": "單題", "img": "img/bc101-1-27.png", "source": "出處待查（明清寓言）", "author": "", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "張生惡鼠，傾財求良貓。饜以腥膏，眠以氈罽。貓既飽且安，率不捕鼠，甚者與鼠遊戲，鼠以故益暴。張生怒，遂不復畜貓。", "translation": "張生厭惡老鼠，花光錢財求得一隻好貓。他用肥美的魚肉餵飽牠，讓牠睡在毯子上。貓吃飽了又過得安逸，大都不去捕老鼠，甚至和老鼠一起玩耍，老鼠因此更加猖狂。張生很生氣，從此不再養貓。", "keywords": [{"w": "惡", "m": "厭惡"}, {"w": "傾財", "m": "花盡錢財"}, {"w": "饜", "m": "使吃飽"}, {"w": "腥膏", "m": "肥美的魚鮮"}, {"w": "氈罽", "m": "毯子"}, {"w": "率", "m": "大都、一概"}, {"w": "益暴", "m": "更加猖狂"}, {"w": "畜", "m": "養"}], "questions": [{"n": 27, "stem": "「張生惡鼠，傾財求良貓。饜以腥膏，眠以氈罽。貓既飽且安，率不捕鼠，甚者與鼠遊戲，鼠以故益暴。張生怒，遂不復畜貓。」這則故事的寓意最可能是下列何者？", "options": {"A": "緊要關頭應當機立斷，快刀斬亂麻", "B": "取暖莫靠別人的火，要自己動手砍柴", "C": "掌握正確的做事方法，才能解決問題", "D": "人們應把抱怨環境的心情，化為上進的力量"}, "answer": "C", "explain": "張生想用貓解決鼠患，方向沒錯，但他把貓餵得太飽、養得太舒服，貓就懶得捕鼠，反而讓鼠患更嚴重——問題出在方法錯誤，(C)正確。(A)故事不涉及關鍵時刻的決斷。(B)張生求貓本來就是在設法解決問題，故事大半篇幅在寫他養貓方法失當，不是在強調要親力親為。(D)故事沒有抱怨環境轉為上進的情節。", "skill": "看故事用最多篇幅寫什麼（飽食安眠→不捕鼠），那就是寓意的焦點：方法錯了。"}], "difficulty": "中", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-29", "exam": "bc101-1", "nums": [29], "form": "單題", "img": "img/bc101-1-29.png", "source": "題幹出處待查；(A)白居易〈新製布裘〉", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "不憂一家寒，所憂四海飢。／(A)丈夫貴兼濟，豈獨善一身　(B)君子固安分，毋聽勞者譏　(C)仁者恥貪冒，受祿量所宜　(D)良馬不念秣，烈士不苟營", "translation": "不擔心自己一家受凍，所擔心的是天下人挨餓。(A)大丈夫貴在兼善天下，怎能只顧自己一身。(B)君子本來就安守本分，不必理會勞苦者的譏諷。(C)仁者以貪求為恥，接受俸祿只取適當的量。(D)好馬不惦記草料，有志之士不苟且謀求私利。", "keywords": [{"w": "四海", "m": "天下"}, {"w": "兼濟", "m": "兼善天下，幫助眾人"}, {"w": "獨善一身", "m": "只顧自己"}, {"w": "貪冒", "m": "貪求"}, {"w": "秣", "m": "餵馬的草料"}, {"w": "苟營", "m": "苟且謀求"}], "questions": [{"n": 29, "stem": "「不憂一家寒，所憂四海飢。」這句話展現的胸襟，與下列何者最接近？", "options": {"A": "丈夫貴兼濟，豈獨善一身", "B": "君子固安分，毋聽勞者譏", "C": "仁者恥貪冒，受祿量所宜", "D": "良馬不念秣，烈士不苟營"}, "answer": "A", "explain": "題幹不擔心自家而擔心天下人，是心懷天下、推己及人的胸襟。(A)大丈夫貴在兼善天下，不能只顧自己，最接近。(B)講安守本分、不理他人譏諷。(C)講不貪求、取祿適量。(D)講不圖私利。(C)(D)都是個人操守，沒有「以天下為念」的意思。", "skill": "抓「一家」對「四海」的對比，找同樣是「自己」對「天下」對比的選項（獨善一身／兼濟）。"}], "difficulty": "中", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-31", "exam": "bc101-1", "nums": [31], "form": "單題", "img": "img/bc101-1-31.png", "source": "出處待查（先秦兩漢史事）", "author": "", "genre": "史傳人物", "types": ["主旨寓意", "人物情感"], "passage": "晉中行寅將亡，召其太祝簡欲加罪。曰：『子為我祝，齋戒不敬，使吾國亡。』太祝簡對曰：『今舟車飾，賦斂厚，民怨謗詛多矣。苟以為祝有益於國，則詛亦將為損。一人祝之，一國詛之，一祝不勝萬詛，國亡不亦宜乎，祝其何罪？』", "translation": "晉國的中行寅快要滅亡時，召來他的太祝簡，想要加罪於他，說：「你替我祈禱，齋戒不恭敬，使我的封國滅亡。」太祝簡回答說：「如今您的船車裝飾華麗，賦稅徵收沉重，百姓怨恨、毀謗、詛咒的已經很多了。如果認為祈禱對國家有益，那麼詛咒也會對國家有害。一個人為您祈禱，全國人詛咒您，一次祈禱勝不過萬人的詛咒，國家滅亡不也是應該的嗎？祈禱的人有什麼罪呢？」", "keywords": [{"w": "太祝", "m": "主管祭祀祈禱的官吏"}, {"w": "祝", "m": "祈禱"}, {"w": "齋戒", "m": "祭祀前潔身靜心"}, {"w": "飾", "m": "裝飾華麗"}, {"w": "賦斂", "m": "賦稅"}, {"w": "詛", "m": "詛咒"}, {"w": "苟", "m": "如果"}, {"w": "宜", "m": "應當、合理"}], "questions": [{"n": 31, "stem": "「晉中行寅將亡，召其太祝簡欲加罪。曰：『子為我祝，齋戒不敬，使吾國亡。』太祝簡對曰：『今舟車飾，賦斂厚，民怨謗詛多矣。苟以為祝有益於國，則詛亦將為損。一人祝之，一國詛之，一祝不勝萬詛，國亡不亦宜乎，祝其何罪？』」文中太祝簡所言的主要涵義應為下列何者？", "options": {"A": "表達國之存亡繫於施政，非關祝者", "B": "辯解祝者力寡，禱詞難以上達天聽", "C": "批評主政者只重視享受，疏於齋敬", "D": "說明亡國乃因上位者迷信怪力亂神"}, "answer": "A", "explain": "太祝簡指出：中行寅奢侈（舟車飾）又重稅（賦斂厚），百姓怨恨詛咒，國家滅亡是施政造成的，不是祈禱的人不夠恭敬，(A)正確。(B)「一祝不勝萬詛」只是用來說明民怨之深，重點不在祝者力量小、禱詞上不達天。(C)他批評的是奢侈與重稅，不是不齋敬。(D)他沒有指責中行寅迷信。", "skill": "找太祝反駁的核心：把亡國原因從「祝不敬」轉到「舟車飾、賦斂厚」，主旨就是「亡國在於施政」。"}], "difficulty": "中", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-32", "exam": "bc101-1", "nums": [32], "form": "單題", "img": "img/bc101-1-32.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "閒暇時，不曾留心；倉卒時，措手不及。胡亂支吾，任其成敗，或悔或不悔，事過後依然如昨。世之人如此者多矣。", "translation": "空閒的時候，不曾用心準備；事情倉促到來時，就手忙腳亂應付不及。只好胡亂敷衍，任由事情成功或失敗；事後或許後悔或許不後悔，但過後依然和從前一樣（不改）。世上像這樣的人很多啊。", "keywords": [{"w": "倉卒", "m": "匆忙、急迫"}, {"w": "支吾", "m": "敷衍應付"}, {"w": "如昨", "m": "和以前一樣"}, {"w": "未雨綢繆", "m": "事先做好準備"}, {"w": "因循苟且", "m": "守舊敷衍、得過且過"}], "questions": [{"n": 32, "stem": "「閒暇時，不曾留心；倉卒時，措手不及。胡亂支吾，任其成敗，或悔或不悔，事過後依然如昨。世之人如此者多矣。」這句話的用意，在提醒世人行事之際應注意下列何者？", "options": {"A": "宜未雨綢繆，勿因循苟且", "B": "接受失敗，後悔無濟於事", "C": "能當機立斷，可少怨寡悔", "D": "隨機應變，成敗無需掛懷"}, "answer": "A", "explain": "原文批評兩種毛病：①平時不準備，事到臨頭措手不及；②事後不改，依然如昨。(A)「未雨綢繆」對應①，「勿因循苟且」對應②，正確。(B)原文沒有勸人接受失敗。(C)原文的問題在平時沒準備，不在臨事不果斷。(D)原文正是批評「任其成敗」的態度，不是要人不在意成敗。", "skill": "文中描述的是「反面例子」，把它倒過來就是作者的提醒：平時要準備、事後要改。"}], "difficulty": "易", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-34", "exam": "bc101-1", "nums": [34], "form": "單題", "img": "img/bc101-1-34.png", "source": "《山海經‧南山經》", "author": "", "genre": "其他", "types": ["句意理解", "字詞解釋"], "passage": "招搖之山，臨於西海之上，多桂，多金玉。有草焉，其狀如韭而青華，其名曰祝餘，食之不飢。有木焉，其狀如穀而黑理，其華四照，其名曰迷穀，佩之不迷。有獸焉，其狀如禺而白耳，伏行人走，其名曰猩猩，食之善走。", "translation": "招搖山，靠近西海邊，山上有很多桂樹，很多金屬和玉石。山上有一種草，形狀像韭菜，開青色的花，名叫祝餘，吃了不會飢餓。有一種樹，形狀像穀樹而有黑色紋理，花的光芒照耀四方，名叫迷穀，佩帶它就不會迷路。有一種野獸，形狀像長尾猿，耳朵是白色的，能伏地爬行也能像人一樣走路，名叫猩猩，吃了牠能跑得快。", "keywords": [{"w": "臨", "m": "靠近"}, {"w": "華", "m": "同「花」"}, {"w": "理", "m": "紋理"}, {"w": "四照", "m": "光照四方"}, {"w": "禺", "m": "一種長尾猿"}, {"w": "善走", "m": "擅長奔跑"}], "questions": [{"n": 34, "stem": "《山海經》：「招搖之山，臨於西海之上，多桂，多金玉。有草焉，其狀如韭而青華，其名曰祝餘，食之不飢。有木焉，其狀如穀而黑理，其華四照，其名曰迷穀，佩之不迷。有獸焉，其狀如禺而白耳，伏行人走，其名曰猩猩，食之善走。」假如夢蝶來到了招搖山，晚上找不到路，下列何物最能幫她解決這個問題？", "options": {"A": "金玉", "B": "祝餘", "C": "迷穀", "D": "猩猩"}, "answer": "C", "explain": "迷穀「其華四照」（花能照亮四周）又「佩之不迷」（佩帶就不會迷路），晚上找不到路時最有幫助，(C)正確。(A)金玉只是山中出產的礦物，沒有特殊功能。(B)祝餘「食之不飢」，解決的是飢餓。(D)猩猩「食之善走」，讓人跑得快，但不能指路。", "skill": "把每樣東西的功效句（食之／佩之……）圈出來，對照題目需要的功能（不迷路）。"}], "difficulty": "易", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-45", "exam": "bc101-1", "nums": [45, 46], "form": "題組", "img": "img/bc101-1-45.png", "source": "改寫自宋濂〈書鬥魚〉", "author": "宋濂", "genre": "說理議論", "types": ["句意理解", "主旨寓意", "寫作手法"], "passage": "予客建業，見有畜波斯魚者，俗訛為師婆魚。其大如指，鰭鬣具五采，兩鰓有小黑點如黛，性矯悍善鬥。人以二缶畜之，折藕葉覆水面，飼以蚓或蠅，魚吐泡葉畔，知其勇可用。乃貯水大缶，合之。各揚鰭鬣相鼓視，怒氣所乘，體拳曲如弓，鱗甲變黑。久之，忽作秋隼擊，水砰然鳴，濺珠上人衣。連數合，復分。當合，如矢激弦，絕不可遏。已而相糾纏，盤旋弗解。其一或負，勝者奮威逐之，負者自擲缶外，視其身純白云。予聞有血氣者必有爭心。然則斯魚者，其亦有爭心否歟？抑冥頑不靈而至於是歟？然予所哀者，豈獨魚也歟？", "translation": "我客居建業時，看到有人養波斯魚，俗稱訛傳為師婆魚。魚只有手指大，鰭上有五彩顏色，兩鰓有黛色的小黑點，性情強悍好鬥。人們用兩個瓦缶分開養，折藕葉蓋在水面，餵牠們蚯蚓或蒼蠅，看到魚在葉邊吐泡，就知道牠的勇猛可以用來打鬥了。於是在大缶裡裝水，把兩條魚放在一起。牠們各自張開魚鰭互相怒視，怒氣上衝，身體彎曲得像弓，鱗片變黑。過了很久，忽然像秋天的獵鷹出擊，水砰地響，水珠濺到人的衣服上。交鋒幾回合，又分開。交鋒時像箭離弦，絕對擋不住。不久互相糾纏，盤旋不分。其中一條若輸了，勝的就奮起威風追趕，輸的自己跳到缶外，看牠的身體已經變成純白色。我聽說有血氣的動物必定有爭鬥之心。那麼這種魚也有爭鬥之心嗎？還是愚昧頑固不開竅，才到這種地步呢？然而我所哀憐的，難道只是魚嗎？", "keywords": [{"w": "客", "m": "客居"}, {"w": "訛", "m": "錯誤流傳"}, {"w": "鰭鬣", "m": "魚的腹鰭和背鰭"}, {"w": "矯悍", "m": "強健兇猛"}, {"w": "缶", "m": "口大腹小的瓦器"}, {"w": "隼", "m": "獵鷹"}, {"w": "遏", "m": "阻止"}, {"w": "抑", "m": "還是"}, {"w": "冥頑不靈", "m": "愚昧頑固"}], "questions": [{"n": 45, "stem": "根據本文，兩魚相鬥的順序，下列何者正確？", "options": {"A": "盤旋纏鬥→張鰭曲身→體色改變→勝負始分", "B": "盤旋纏鬥→體色改變→張鰭曲身→勝負始分", "C": "張鰭曲身→體色改變→盤旋纏鬥→勝負始分", "D": "張鰭曲身→盤旋纏鬥→體色改變→勝負始分"}, "answer": "C", "explain": "依原文順序：「各揚鰭鬣相鼓視……體拳曲如弓」（張鰭曲身）→「鱗甲變黑」（體色改變）→「已而相糾纏，盤旋弗解」（盤旋纏鬥）→「其一或負……負者自擲缶外」（勝負始分），(C)正確。", "skill": "在原文中依序圈出每個階段的關鍵句，再對照選項的排列。"}, {"n": 46, "stem": "作者所惋惜的對象，最不可能是下列何者？", "options": {"A": "同類相殘的鬥魚", "B": "好勇鬥狠的世人", "C": "愚昧頑固的眾生", "D": "懾於威勢的弱者"}, "answer": "D", "explain": "作者感嘆鬥魚是因爭心還是「冥頑不靈」而同類相鬥，最後說「予所哀者，豈獨魚也歟」，表示他也哀憐像鬥魚一樣好鬥、愚頑的人。所以(A)同類相殘的鬥魚、(B)好勇鬥狠的世人、(C)愚昧頑固的眾生都可能是他惋惜的對象。(D)文中的魚是主動爭鬥，並非因畏懼威勢而屈服的弱者，最不可能，是答案。", "skill": "從「冥頑不靈」「豈獨魚也歟」推出作者由魚及人的感嘆，再找與「好鬥、愚頑」無關的選項。"}], "difficulty": "中", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc101-1-47", "exam": "bc101-1", "nums": [47, 48], "form": "題組", "img": "img/bc101-1-47.png", "source": "改寫自《莊子‧列禦寇》", "author": "莊子", "genre": "寓言故事", "types": ["文意推論", "虛詞句式"], "passage": "河上有翁，家貧，織蘆蒿為簾，賣以供食。其子沒於淵，得千金之珠。其父謂其子曰：「取石槌破之。夫千金之珠，必在九重之淵而驪龍頷下。子能得珠者，必值其睡也。使驪龍而寤，子當為齏粉，何珠之有哉？」", "translation": "河邊有個老翁，家裡貧窮，靠編織蘆葦蒿草做成簾子賣錢過活。他的兒子潛入深淵，得到一顆價值千金的寶珠。父親對兒子說：「拿石頭把它砸碎。價值千金的寶珠，一定在極深的深淵裡、黑龍的下巴底下。你能得到寶珠，一定是剛好碰上牠在睡覺。假如黑龍醒了，你早就粉身碎骨了，哪裡還有什麼寶珠呢？」", "keywords": [{"w": "沒", "m": "潛入水中"}, {"w": "九重之淵", "m": "極深的深淵"}, {"w": "驪龍", "m": "黑龍"}, {"w": "頷", "m": "下巴"}, {"w": "值", "m": "正好碰上"}, {"w": "使", "m": "假如"}, {"w": "寤", "m": "睡醒"}, {"w": "齏粉", "m": "粉屑"}], "questions": [{"n": 47, "stem": "根據這則故事，父親在兒子得到寶珠之後的想法或作為，以下詮釋何者最恰當？", "options": {"A": "自傷教子無方，兒子竟然做出盜取寶珠的行為", "B": "認為兒子冒險取得的寶珠非真品，故以石槌擊破", "C": "以為兒子是僥倖得到寶珠，卻不知背後隱藏的危機", "D": "提醒兒子取珠時若驚醒驪龍，當藏珠於頷下迅速逃脫"}, "answer": "C", "explain": "父親認為兒子「必值其睡」才得到寶珠，是僥倖；若驪龍醒來就會粉身碎骨，所以要他砸碎寶珠，免得再冒險，可見兒子只看到得寶之喜、不知背後危機，(C)最恰當。(A)父親沒有責備兒子盜竊。(B)父親並未懷疑寶珠是假的，砸碎是為了斷絕再去冒險的念頭。(D)父親說的是假如龍醒了你就沒命了，不是教他如何逃脫。", "skill": "抓父親說話的邏輯：寶珠在龍頷下→能得到是運氣→龍醒就沒命，由此推出「僥倖、危機」。"}, {"n": 48, "stem": "下列文句，何者運用假設語氣？", "options": {"A": "其子沒於淵，得千金之珠", "B": "夫千金之珠，必在九重之淵而驪龍頷下", "C": "子能得珠者，必值其睡也", "D": "使驪龍而寤，子當為齏粉，何珠之有哉"}, "answer": "D", "explain": "(D)「使」是「假如」，「使驪龍而寤」就是「假如黑龍醒來」，是假設語氣，正確。(A)是敘述已發生的事實。(B)是判斷、說明寶珠所在之處。(C)是推論語氣，由「得珠」推斷「必值其睡」，不是假設尚未發生的情況。", "skill": "找文言表假設的字：使、若、苟、如、倘，並確認後面接的是尚未發生的情況。"}], "difficulty": "中", "label": "101年基測", "year": 101, "kind": "基測"}, {"id": "bc102-1-8", "exam": "bc102-1", "nums": [8], "form": "單題", "img": "img/bc102-1-8.png", "source": "柳宗元〈與浩初上人同看山寄京華親故〉", "author": "柳宗元", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "海畔尖山似劍鋩，秋來處處割愁腸。若為化得身千億，散上峰頭望故鄉。", "translation": "海邊尖尖的山峰像劍鋒一樣，秋天到了，處處都割痛我憂愁的心腸。如果能把自己化成千萬個身體，就散到每座山頭上去眺望故鄉。", "keywords": [{"w": "劍鋩", "m": "劍鋒"}, {"w": "愁腸", "m": "憂愁的心"}, {"w": "若為", "m": "如何能夠、假如能"}, {"w": "化得身千億", "m": "化成千萬個身體"}], "questions": [{"n": 8, "stem": "「海畔尖山似劍鋩，秋來處處割愁腸。若為化得身千億，散上峰頭望故鄉。」關於這首詩的分析，下列敘述何者最不恰當？", "options": {"A": "以即景生情之法，先述景觀，再寫個人情志", "B": "首二句將尖銳峰頂擬為劍鋒，割傷遊子愁腸", "C": "作者欲化身千億以望鄉，表達思鄉情切之意", "D": "山勢尖峭險峻，因而阻絕了作者回鄉的念頭"}, "answer": "D", "explain": "題目問「最不恰當」。(D)作者不但沒有放棄回鄉的念頭，反而想化身千億登上每座山頭望故鄉，思鄉之情更強烈，所以「阻絕回鄉念頭」錯誤，是答案。(A)前兩句寫海邊尖山（景），後兩句寫望鄉之情（情），是即景生情，正確。(B)把山峰比作劍鋒，割著遊子的愁腸，正確。(C)化身千億上峰頭望鄉，表達思鄉急切，正確。", "skill": "「最不恰當」題：逐項回詩句找證據；尤其注意作者的情感方向——想更多地望鄉，而不是放棄。"}], "difficulty": "易", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-9", "exam": "bc102-1", "nums": [9], "form": "單題", "img": "img/bc102-1-9.png", "source": "選項為古語（(A)蘇軾〈和董傳留別〉；(D)俗諺）", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "(A)腹有詩書氣自華　(B)書卷乃養智養德第一妙物　(C)勤讀書可治俗氣、拓眼界　(D)讀萬卷書，不如行萬里路", "translation": "(A)肚子裡有詩書學問，氣質自然光采煥發。(B)書本是培養智慧和德行最好的東西。(C)勤奮讀書可以去除俗氣、開拓眼界。(D)讀一萬卷書，比不上走一萬里路（親身經歷更重要）。", "keywords": [{"w": "華", "m": "光彩、有光華"}, {"w": "妙物", "m": "美好的東西"}, {"w": "俗氣", "m": "庸俗的氣息"}], "questions": [{"n": 9, "stem": "「多讀書可以增廣一個人的見聞和智慧，亦可使人充實內涵，更有氣質；而在行文言語上，則能字字珠璣，耐人尋味。所謂：＿＿＿＿＿＿，即是此理。」這段文字畫線處填入下列哪一句話最不恰當？", "options": {"A": "腹有詩書氣自華", "B": "書卷乃養智養德第一妙物", "C": "勤讀書可治俗氣、拓眼界", "D": "讀萬卷書，不如行萬里路"}, "answer": "D", "explain": "題幹在強調「多讀書」的好處。(A)(B)(C)都在稱讚讀書能增氣質、養智德、拓眼界，都能填入。(D)「讀萬卷書不如行萬里路」意思是親身經歷比讀書更重要，與題幹讚美讀書的方向相反，最不恰當，是答案。", "skill": "先確定空格要支持的主張（讀書好），再找方向相反（貶低讀書）的選項。"}], "difficulty": "易", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-11", "exam": "bc102-1", "nums": [11], "form": "單題", "img": "img/bc102-1-11.png", "source": "孟元老《東京夢華錄‧魚行》", "author": "孟元老", "genre": "筆記小品", "types": ["句意理解", "主旨寓意"], "passage": "京城賣生魚用淺桶，以柳葉間串清水中浸，或循街出賣。每日早惟新鄭門、西水門、萬勝門，如此生魚有數千擔入門。冬月即黃河諸遠處客魚來，謂之『車魚』。", "translation": "京城裡賣活魚用淺桶裝，用柳枝穿著魚泡在清水中，或者沿著街道叫賣。每天早上只有新鄭門、西水門、萬勝門這幾個城門，像這樣的活魚就有好幾千擔運進城。冬天則有黃河等遠處運來的外地魚，叫做「車魚」。", "keywords": [{"w": "間串", "m": "穿插串起"}, {"w": "循街", "m": "沿著街道"}, {"w": "惟", "m": "只有"}, {"w": "擔", "m": "挑、量詞"}, {"w": "客魚", "m": "外地來的魚"}], "questions": [{"n": 11, "stem": "「京城賣生魚用淺桶，以柳葉間串清水中浸，或循街出賣。每日早惟新鄭門、西水門、萬勝門，如此生魚有數千擔入門。冬月即黃河諸遠處客魚來，謂之『車魚』。」這段文字的內容，主要是在說明京城內的哪一種狀況？", "options": {"A": "居民買魚的喜好", "B": "魚販生活的艱辛", "C": "保存魚貨的方式", "D": "魚貨販售的情形"}, "answer": "D", "explain": "文中寫賣魚的器具（淺桶、柳枝串魚）、賣法（沿街叫賣）、進城的數量（數千擔）、冬天的貨源（車魚），整體在說明京城魚貨的販售情形，(D)正確。(A)沒有提到居民偏好哪種魚。(B)沒有寫魚販的辛苦。(C)「清水中浸」只是其中一個細節，不是全段主旨。", "skill": "主旨題要「全面涵蓋」：把每句的內容各標一個小標題，再找能統括全部的選項，小心只抓到一個細節的選項。"}], "difficulty": "易", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-15", "exam": "bc102-1", "nums": [15], "form": "單題", "img": "img/bc102-1-15.png", "source": "題幹：宋祁〈玉樓春〉；(C)李商隱〈嫦娥〉；其餘出處待查", "author": "", "genre": "古典詩詞曲", "types": ["寫作手法", "詩詞賞析"], "passage": "綠楊煙外曉寒輕／(A)水清石出魚可數　(B)馳道楊花滿御溝　(C)雲母屏風燭影深　(D)日暖花明梁燕歸", "translation": "綠色楊柳像煙霧一般，清晨的寒意很輕微。(A)水清澈，石頭露出，魚可以一條條數清楚。(B)大道上的楊花飄滿了皇宮的水溝。(C)雲母屏風上燭影深沉。(D)陽光溫暖，花朵明豔，屋梁上的燕子飛回來了。", "keywords": [{"w": "摹寫", "m": "把感官感受具體描寫出來"}, {"w": "視覺", "m": "看到的顏色、光影"}, {"w": "觸覺", "m": "身體感受到的冷暖、軟硬"}], "questions": [{"n": 15, "stem": "「綠楊煙外曉寒輕」句中兼具視覺及觸覺兩種摹寫效果。下列詩句何者也具備同樣的手法？", "options": {"A": "水清石出魚可數", "B": "馳道楊花滿御溝", "C": "雲母屏風燭影深", "D": "日暖花明梁燕歸"}, "answer": "D", "explain": "題幹「綠楊煙外」是視覺，「曉寒輕」是觸覺（感覺寒冷）。(D)「日暖」是觸覺（感受到溫暖），「花明」「梁燕歸」是視覺，兩者兼具，正確。(A)水清、石出、魚可數，都是眼睛看到的，只有視覺。(B)楊花飄滿御溝，只有視覺。(C)屏風、燭影，只有視覺。", "skill": "把每句拆成詞，標出屬於哪種感官；找「冷、暖、寒、熱」等觸覺詞是最快的辨識法。"}], "difficulty": "易", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-20", "exam": "bc102-1", "nums": [20], "form": "單題", "img": "img/bc102-1-20.png", "source": "(A)陶淵明〈五柳先生傳〉；(B)杜甫〈徒步歸行〉；(C)周敦頤〈愛蓮說〉；(D)出處待查", "author": "", "genre": "經典語錄", "types": ["句意理解", "人物情感"], "passage": "(A)無懷氏之民歟！葛天氏之民歟　(B)人生交契無老少，論交何必先同調　(C)蓮之愛，同予者何人？牡丹之愛，宜乎眾矣　(D)行合趨同，千里相從。行不合，趨不同，對門不通", "translation": "(A)是無懷氏時代的百姓吧！是葛天氏時代的百姓吧！(B)人生結交朋友不分年老年少，交朋友何必先要志趣相同。(C)對蓮花的喜愛，和我一樣的還有誰呢？對牡丹的喜愛，人數應該很多了。(D)行為志趣相合，即使相隔千里也會相從；行為志趣不合，即使住對門也不往來。", "keywords": [{"w": "交契", "m": "交情、結交"}, {"w": "同調", "m": "志趣相同"}, {"w": "予", "m": "我"}, {"w": "宜乎", "m": "應當、難怪"}, {"w": "趨", "m": "志趣、取向"}], "questions": [{"n": 20, "stem": "下列文句，何者含有「知音難尋」的喟嘆？", "options": {"A": "無懷氏之民歟！葛天氏之民歟", "B": "人生交契無老少，論交何必先同調", "C": "蓮之愛，同予者何人？牡丹之愛，宜乎眾矣", "D": "行合趨同，千里相從。行不合，趨不同，對門不通"}, "answer": "C", "explain": "(C)周敦頤感嘆：像我一樣愛蓮（追求君子品格）的還有誰呢？愛牡丹（追求富貴）的人倒是很多——表達同道者少、知音難尋的感慨，正確。(A)讚嘆五柳先生像上古淳樸時代的人。(B)講交朋友不分年紀、不必志同道合，是豁達的交友觀。(D)講志趣相同才會往來，是陳述道理，沒有感嘆知音難得。", "skill": "找帶有「感嘆語氣＋同好很少」的句子，如「同予者何人」的反問。"}], "difficulty": "中", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-21", "exam": "bc102-1", "nums": [21], "form": "單題", "img": "img/bc102-1-21.png", "source": "出處待查（唐詩）", "author": "", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "(A)可憐地僻無人賞，拋擲深山亂木中　(B)長安道上春可憐，搖風蕩日曲河邊　(C)越國山川看漸無，可憐愁思江南樹　(D)獨倚破簾閒悵望，可憐虛度好春朝", "translation": "(A)可惜（這花）生長在偏僻的地方沒有人欣賞，被丟在深山雜亂的樹木中。(B)長安大道上的春色真惹人喜愛，在彎曲的河邊隨風搖曳、在陽光下擺盪。(C)越地的山川漸漸看不見了，江南的樹令人憐憫地引發愁思。(D)獨自靠著破簾子無聊地惆悵遠望，可惜白白浪費了美好的春日早晨。", "keywords": [{"w": "可憐", "m": "惹人憐愛／令人憐憫／令人惋惜，依上下文判斷"}, {"w": "地僻", "m": "地方偏僻"}, {"w": "虛度", "m": "白白度過"}], "questions": [{"n": 21, "stem": "「可憐」一詞，在詩詞中可以解釋成「惹人憐愛」、「令人憐憫」、「令人惋惜」等義。下列詩句中的「可憐」，何者當「惹人憐愛」解釋？", "options": {"A": "可憐地僻無人賞，拋擲深山亂木中", "B": "長安道上春可憐，搖風蕩日曲河邊", "C": "越國山川看漸無，可憐愁思江南樹", "D": "獨倚破簾閒悵望，可憐虛度好春朝"}, "answer": "B", "explain": "(B)長安道上的春景在風中日下搖曳，美好動人，「春可憐」是春色惹人喜愛，正確。(A)花長在偏僻處無人欣賞、被丟在亂木中，是「令人惋惜」。(C)離開越地、看著江南樹而生愁思，是「令人憐憫、感傷」。(D)白白虛度了美好春朝，是「令人惋惜」。", "skill": "看「可憐」前後是美好的畫面（→憐愛）還是失落、浪費、被冷落（→惋惜、憐憫）。"}], "difficulty": "中", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-23", "exam": "bc102-1", "nums": [23], "form": "單題", "img": "img/bc102-1-23.png", "source": "典出《論語‧為政》", "author": "", "genre": "經典語錄", "types": ["文化常識", "典故出處"], "passage": "吾十有五而志於學，三十而立，四十而不惑，五十而知天命，六十而耳順，七十而從心所欲，不踰矩。（題目所用典故）", "translation": "孔子說：我十五歲立志求學，三十歲能自立，四十歲不再迷惑，五十歲知道天命，六十歲聽到什麼都能明白通達，七十歲隨心所欲也不會越出規矩。", "keywords": [{"w": "志學", "m": "十五歲"}, {"w": "而立", "m": "三十歲"}, {"w": "不惑", "m": "四十歲"}, {"w": "知命", "m": "五十歲"}, {"w": "耳順", "m": "六十歲"}, {"w": "甫屆", "m": "剛剛到達"}], "questions": [{"n": 23, "stem": "小康正值志學之年，而他的父親甫屆耳順之年。由此可知小康與父親相差幾歲？", "options": {"A": "三十五歲", "B": "四十歲", "C": "四十五歲", "D": "五十歲"}, "answer": "C", "explain": "「志學」出自《論語》「吾十有五而志於學」，指十五歲；「耳順」出自「六十而耳順」，指六十歲。60－15＝45，相差四十五歲，(C)正確。", "skill": "背熟《論語‧為政》的年齡代稱（志學15、而立30、不惑40、知命50、耳順60、從心70），換算即可。"}], "difficulty": "易", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-26", "exam": "bc102-1", "nums": [26], "form": "單題", "img": "img/bc102-1-26.png", "source": "(A)《荀子‧儒效》；(C)蘇軾〈又答王庠書〉；(D)劉勰《文心雕龍‧知音》；(B)出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "比較閱讀"], "passage": "(A)聞之而不見，雖博必謬；見之而不知，雖識必妄　(B)讀書不能無疑。讀書而無所疑，乃心無所得故也　(C)書富如海，百貨皆有。人之精力不能盡取，但得其所欲者爾　(D)操千曲而後曉聲，觀千劍而後識器；故通達之道，務先博觀", "translation": "(A)聽到了卻沒親眼看見，即使知道得多也必有錯誤；看見了卻不明白道理，即使認識了也必然虛妄。(B)讀書不能沒有疑問；讀書而沒有疑問，是因為心中沒有收穫。(C)書多得像大海，什麼東西都有；人的精力不能全部取盡，只要得到自己想要的就好。(D)彈過上千首曲子之後才懂得音樂，看過上千把劍之後才能鑑別兵器；所以要通達事理，一定要先廣泛觀覽。", "keywords": [{"w": "謬", "m": "錯誤"}, {"w": "妄", "m": "虛妄、不實"}, {"w": "操", "m": "彈奏"}, {"w": "曉聲", "m": "懂得音樂"}, {"w": "識器", "m": "鑑別器物"}, {"w": "博觀", "m": "廣泛觀覽"}], "questions": [{"n": 26, "stem": "「你玩索的作品愈多，種類愈複雜，風格愈分歧，你的比較資料愈豐富，則對作品的透視愈正確，你的鑑別力也就愈可靠。」這段文字所強調的文學研究方法，與下列何者最接近？", "options": {"A": "聞之而不見，雖博必謬；見之而不知，雖識必妄", "B": "讀書不能無疑。讀書而無所疑，乃心無所得故也", "C": "書富如海，百貨皆有。人之精力不能盡取，但得其所欲者爾", "D": "操千曲而後曉聲，觀千劍而後識器；故通達之道，務先博觀"}, "answer": "D", "explain": "題幹強調：多讀、廣讀各種作品，比較資料越豐富，鑑別力就越可靠。(D)彈過千曲才懂音樂、看過千劍才識兵器，所以要「務先博觀」，正與題幹相同。(A)強調親眼見、真正理解，重點在實證。(B)強調讀書要有疑問。(C)強調書太多讀不完，只取所需——與「廣泛閱讀」的方向相反。", "skill": "題幹關鍵是「量多→比較→鑑別力」，找講「博觀而後能鑑別」的選項。"}], "difficulty": "中", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-28", "exam": "bc102-1", "nums": [28], "form": "單題", "img": "img/bc102-1-28.png", "source": "呂坤《呻吟語》", "author": "呂坤", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "士大夫一身，斯世之俸弘矣。不蠶織而文繡，不耕畜而膏粱，不雇貸而車馬，不商販而積蓄。此何故也？乃於世人分毫無補，又以大官誇市井兒，蓋棺有餘愧矣！", "translation": "士大夫這一個人，從這個社會得到的俸祿供養很多啊。不養蠶織布卻穿著華麗的衣服，不耕田畜牧卻吃著精美的飯菜，不租不借卻有車馬可乘，不做買賣卻有積蓄。這是什麼原因呢？（是百姓供養的。）如果對世人一點貢獻也沒有，又拿大官的身分向市井小民誇耀，那麼到死蓋上棺材時都會有很多的慚愧啊！", "keywords": [{"w": "斯世", "m": "這個社會"}, {"w": "俸", "m": "俸祿"}, {"w": "弘", "m": "大、多"}, {"w": "文繡", "m": "華麗的衣服"}, {"w": "膏粱", "m": "精美的食物"}, {"w": "市井兒", "m": "平民百姓"}, {"w": "蓋棺", "m": "死後"}], "questions": [{"n": 28, "stem": "「士大夫一身，斯世之俸弘矣。不蠶織而文繡，不耕畜而膏粱，不雇貸而車馬，不商販而積蓄。此何故也？乃於世人分毫無補，又以大官誇市井兒，蓋棺有餘愧矣！」這段話的用意，與下列何者最接近？", "options": {"A": "說明士大夫職責所在，任重道遠", "B": "強調士大夫治理百姓，首重民生", "C": "斥責為官者貪汙瀆職，魚肉鄉民", "D": "諷刺為官者坐領乾薪，無所作為"}, "answer": "D", "explain": "作者列出士大夫不勞動卻享受衣食車馬，再批評他們「於世人分毫無補」，還向百姓炫耀，是諷刺當官的人只領俸祿卻毫無作為，(D)正確。(A)(B)原文是批評，不是正面說明職責或施政重點。(C)原文沒有說他們貪汙、欺壓百姓，重點是「無補於世」而非「害民」。", "skill": "抓轉折後的批評句「於世人分毫無補」，判斷是「不作為」而不是「亂作為」。"}], "difficulty": "中", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-30", "exam": "bc102-1", "nums": [30], "form": "單題", "img": "img/bc102-1-30.png", "source": "出處待查（富弼使契丹事，見《宋史‧富弼傳》等）", "author": "", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "富弼奉使契丹，王言欲舉兵。富弼曰：『北朝與中國通好，則人主專其利，而臣下無所獲。若用兵則利歸臣下，而人主任其禍。故北朝群臣爭勸舉兵者，此皆其自謀，非國計也。勝負未可知，就使其勝，所亡士馬，群臣當之歟？抑人主當之歟？』", "translation": "富弼奉命出使契丹，契丹王說想要出兵。富弼說：「北朝（契丹）和中國友好往來，好處由君主獨享，臣子們卻得不到什麼；如果打仗，好處就歸臣子，而禍害由君主承擔。所以北朝的群臣爭著勸您出兵，這都是為他們自己打算，不是為國家著想。勝負還不知道，就算打贏了，所損失的士兵馬匹，是群臣承擔呢？還是君主承擔呢？」", "keywords": [{"w": "通好", "m": "友好往來"}, {"w": "專", "m": "獨占"}, {"w": "任", "m": "承擔"}, {"w": "自謀", "m": "為自己打算"}, {"w": "就使", "m": "即使、就算"}, {"w": "亡", "m": "損失"}, {"w": "抑", "m": "還是"}], "questions": [{"n": 30, "stem": "「富弼奉使契丹，王言欲舉兵。富弼曰：『北朝與中國通好，則人主專其利，而臣下無所獲。若用兵則利歸臣下，而人主任其禍。故北朝群臣爭勸舉兵者，此皆其自謀，非國計也。勝負未可知，就使其勝，所亡士馬，群臣當之歟？抑人主當之歟？』」根據這段文字，可知富弼勸契丹王不要舉兵的主要論點為何？", "options": {"A": "表示中國已有萬全準備，契丹未必能勝", "B": "暗示契丹君臣不合，貿然舉兵恐生內亂", "C": "分析君臣立場不同，舉兵不利於契丹王", "D": "告知戰爭必致生靈塗炭，陷百姓於水火"}, "answer": "C", "explain": "富弼指出：和好時利益歸君主，打仗時利益歸臣子、禍害歸君主，群臣勸戰是為自己打算，所以打仗對契丹王不利——他從君臣利益立場不同來分析，(C)正確。(A)富弼只說「勝負未可知」，沒說中國已有萬全準備。(B)他說的是利益分配不同，不是君臣不合會引發內亂。(D)他沒有從百姓受苦的角度勸說。", "skill": "整理富弼的對比：通好→利歸君、用兵→利歸臣禍歸君，論點核心就是「對你（君主）不利」。"}], "difficulty": "中", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-31", "exam": "bc102-1", "nums": [31], "form": "單題", "img": "img/bc102-1-31.png", "source": "《荀子‧大略》", "author": "荀子", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "是非疑，則度之以遠事，驗之以近物，參之以平心，流言止焉。", "translation": "是非有疑問時，就用過去的事來衡量它，用眼前的事物來驗證它，用公正平和的心來參酌它，那麼沒有根據的傳言就會止息了。", "keywords": [{"w": "度", "m": "衡量、推測"}, {"w": "遠事", "m": "過去的事"}, {"w": "驗", "m": "驗證"}, {"w": "參", "m": "參酌、考察"}, {"w": "平心", "m": "公正平和的心"}, {"w": "流言", "m": "沒有根據的傳言"}], "questions": [{"n": 31, "stem": "「是非疑，則度之以遠事，驗之以近物，參之以平心，流言止焉。」這句話的涵義，與下列何者最接近？", "options": {"A": "是非對錯存乎一心，但求仰不愧於天，俯不怍於人", "B": "是非審之於己，毀譽聽之於人，榮辱功過無須掛懷", "C": "遇疑應多方求證，冷靜察驗，流言虛實即昭然可辨", "D": "清者自清，濁者自濁，流言止於智者，何須多爭辯"}, "answer": "C", "explain": "原文說遇到是非疑問，要用遠事、近物來衡量驗證，再以平和的心參酌，流言就會止息。(C)「多方求證、冷靜察驗，流言虛實自然可辨」完全對應，正確。(A)講問心無愧，不涉及查證。(B)講自己判斷是非、不在意別人的評價。(D)講不必爭辯、聰明人自然不信流言，重點是「不理會」而非「查證」。", "skill": "抓三個動作「度、驗、參」——都是查證的方法，主旨就是「多方求證」。"}], "difficulty": "易", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-32", "exam": "bc102-1", "nums": [32], "form": "單題", "img": "img/bc102-1-32.png", "source": "出處待查（戒酒打油詩）", "author": "", "genre": "古典詩詞曲", "types": ["文意推論", "人物情感"], "passage": "老夫性與命，全靠水邊酉。寧可不喫飯，不可日無酒。今聽汝忠言，節飲知謹守。每常十遍飲，今番一加九。每常飲十升，今番只一斗。每常一氣吞，今番分兩口。每常床上飲，今番下地有。每常到三更，今番二更後。再要裁減時，性命不值狗！", "translation": "我這老頭子的性情和生命，全靠「水」旁加個「酉」（酒）。寧可不吃飯，也不能一天沒有酒。如今聽了你的忠告，懂得節制飲酒並謹慎遵守。平常喝十遍，這次「一加九」（還是十遍）；平常喝十升，這次「只一斗」（一斗就是十升）；平常一口氣吞下，這次分兩口；平常在床上喝，這次下床喝；平常喝到三更，這次喝到二更以後。如果還要再減少，我的命就連狗都不如了！", "keywords": [{"w": "水邊酉", "m": "拆字，合為「酒」"}, {"w": "節飲", "m": "節制飲酒"}, {"w": "每常", "m": "平常"}, {"w": "今番", "m": "這一次"}, {"w": "一斗", "m": "十升"}, {"w": "更", "m": "古代夜間計時單位"}], "questions": [{"n": 32, "stem": "「老夫性與命，全靠水邊酉。寧可不喫飯，不可日無酒。今聽汝忠言，節飲知謹守。每常十遍飲，今番一加九。每常飲十升，今番只一斗。每常一氣吞，今番分兩口。每常床上飲，今番下地有。每常到三更，今番二更後。再要裁減時，性命不值狗！」詩中「老夫」的情況最可能是下列何者？", "options": {"A": "雖言戒酒，卻毫不見誠意", "B": "謹守節飲，故得減量飲酒", "C": "酒癮難戒，戒而變本加厲", "D": "對酒立誓，再飲命不值狗"}, "answer": "A", "explain": "老夫說要「節飲」，但「一加九」還是十遍、「一斗」就是十升，分兩口喝、下床喝、喝到二更後，其實酒量完全沒減，只是換個說法敷衍，可見口頭說戒酒卻毫無誠意，(A)正確。(B)他並沒有真的減量。(C)他的酒量與以前相同，沒有「變本加厲」。(D)「性命不值狗」是說如果再要他減少就活不下去，不是發誓再喝就命不值狗。", "skill": "把每組「每常／今番」換算比較（十遍＝一加九、十升＝一斗），就能看出數量根本沒變。"}], "difficulty": "中", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-33", "exam": "bc102-1", "nums": [33], "form": "單題", "img": "img/bc102-1-33.png", "source": "康有為遊記（瑞典遊記，篇名待查）", "author": "康有為", "genre": "山水遊記", "types": ["句意理解", "文意推論"], "passage": "七月八日晚七時，汽車自挪威行，九日晨抵瑞典京士多貢。始以為瑞、挪同，國小民貧，必不足觀。驗行李訖，甫出汽車場，流觀道路之廣潔，仰視樓閣之崇麗，周遭邂逅士女之昌豐妙麗，與挪威幾有仙鬼之判。豈止挪威不及，乃可稱為冠冕歐洲，雖英、法亦遠遜焉。", "translation": "七月八日晚上七點，火車從挪威出發，九日早上抵達瑞典首都斯德哥爾摩。起初以為瑞典和挪威一樣，國家小、人民窮，一定沒什麼可看的。檢查完行李，剛走出火車站，四處觀看道路寬廣潔淨，抬頭看樓閣高大華麗，周圍遇到的男女都健康豐美、美好秀麗，和挪威相比幾乎有仙界和鬼域的差別。哪裡只是挪威比不上，簡直可以稱為歐洲第一，即使英國、法國也遠遠不如。", "keywords": [{"w": "汽車", "m": "此指火車"}, {"w": "京士多貢", "m": "瑞典首都，今譯斯德哥爾摩"}, {"w": "訖", "m": "完畢"}, {"w": "甫", "m": "剛剛"}, {"w": "流觀", "m": "四處觀看"}, {"w": "邂逅", "m": "不期而遇"}, {"w": "冠冕", "m": "居首位"}, {"w": "遜", "m": "不如"}], "questions": [{"n": 33, "stem": "康有為在其遊記中寫著：「七月八日晚七時，汽車自挪威行，九日晨抵瑞典京士多貢。始以為瑞、挪同，國小民貧，必不足觀。驗行李訖，甫出汽車場，流觀道路之廣潔，仰視樓閣之崇麗，周遭邂逅士女之昌豐妙麗，與挪威幾有仙鬼之判。豈止挪威不及，乃可稱為冠冕歐洲，雖英、法亦遠遜焉。」根據這段文字，下列有關康有為遊歐的敘述何者正確？", "options": {"A": "先遊瑞典後至挪威，相較之下以為挪威不足觀", "B": "認為瑞典較挪威進步，而英、法又遠勝於瑞典", "C": "到瑞典首都後的第一印象是國小民貧，無甚可觀", "D": "由道路、建築、人民三方面認定瑞典是進步的國家"}, "answer": "D", "explain": "康有為從「道路之廣潔」（道路）、「樓閣之崇麗」（建築）、「士女之昌豐妙麗」（人民）三方面，認為瑞典遠勝挪威、冠冕歐洲，(D)正確。(A)他是從挪威出發到瑞典，順序相反。(B)原文說「雖英、法亦遠遜焉」，是英、法不如瑞典。(C)「國小民貧，必不足觀」是他到之前的想像，到了之後的印象正好相反。", "skill": "分清「始以為」（到之前的預想）與實際所見；注意「遜」是「不如」，判斷誰勝誰。"}], "difficulty": "中", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-44", "exam": "bc102-1", "nums": [44, 45], "form": "題組", "img": "img/bc102-1-44.png", "source": "改寫自孫思邈〈攝養枕中方〉", "author": "孫思邈", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "凡夏至後迄秋分，勿食肥膩餅臛之屬，此與酒漿、果瓜相妨。或當時不覺即病，入秋節變，諸症橫生，皆由涉夏取冷太過，飲食不節故也。而或者以病至之日便為得病之初，不知其所由來者漸矣。故自慎者，當去之於微也。", "translation": "從夏至以後到秋分，不要吃肥膩的餅和肉羹這類食物，這些和酒、水果瓜類互相妨害。有時當下不覺得生病，到了秋天節氣轉變，各種病症就紛紛出現，都是因為夏天貪涼太過、飲食不節制的緣故。有人以為發病那天就是得病的開始，卻不知道病是逐漸累積而來的。所以懂得自我謹慎的人，應該在病因還很微小時就把它除去。", "keywords": [{"w": "迄", "m": "到"}, {"w": "臛", "m": "肉羹"}, {"w": "相妨", "m": "互相妨害"}, {"w": "橫生", "m": "紛紛出現"}, {"w": "涉夏", "m": "經過夏天"}, {"w": "或者", "m": "有的人"}, {"w": "漸", "m": "逐漸累積"}, {"w": "微", "m": "細微、初起時"}], "questions": [{"n": 44, "stem": "本文所討論的主題應是下列何者？", "options": {"A": "食物屬性相互沖剋的原理", "B": "改變飲食習慣的正確步驟", "C": "節氣變化對於人體的影響", "D": "夏秋之際正確的飲食之道"}, "answer": "D", "explain": "本文從「夏至後迄秋分，勿食肥膩餅臛」談起，說明夏天飲食不節、貪涼太過會在秋天引發疾病，提醒要謹慎飲食，主題是夏秋之際的飲食之道，(D)正確。(A)「相妨」只是其中一句，文章沒有解釋食物沖剋的原理。(B)沒有講改變習慣的步驟。(C)節氣變化只是發病的時間點，病因是飲食不節。", "skill": "主題題看開頭與結論：開頭限定時間（夏至到秋分）與對象（飲食），結論是要謹慎。"}, {"n": 45, "stem": "這段文字闡述的養生之法，其所蘊含的道理與下列何者最接近？", "options": {"A": "勞其形者長年，安其樂者短命", "B": "禍常積於所忽，患每消於所慎", "C": "無病之身，不知其樂也，病生，始知無病之樂", "D": "見兔而顧犬，未為晚也；亡羊而補牢，未為遲也"}, "answer": "B", "explain": "文中說病是「所由來者漸」，因平時不注意而逐漸累積，所以要「去之於微」，謹慎防範。(B)災禍常累積在被忽略的地方，憂患常在謹慎中消除，最接近。(A)講勞動身體能長壽、安逸享樂會短命。(C)講生病後才知道健康的快樂。(D)講出了問題再補救也不晚，與「事先防範於微小」的重點相反。", "skill": "抓結論「所由來者漸」「去之於微」——禍患漸積、要早防，找「忽→積禍、慎→消患」的選項。"}], "difficulty": "中", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "bc102-1-46", "exam": "bc102-1", "nums": [46, 47, 48], "form": "題組", "img": "img/bc102-1-46.png", "source": "改寫自干寶《搜神記‧李寄》", "author": "干寶", "genre": "筆記小品", "types": ["文意推論", "人物情感", "寫作手法"], "passage": "東越閩中，有庸嶺，高數十里，其西北濕地有大蛇，長七八丈，大十餘圍，土俗常懼。東冶都尉及屬城長吏，多有死者。祭以牛羊，故不得福，或與人夢，或下諭巫祝，欲得啖童女年十二三者。都尉、令、長，並共患之，然氣厲不息，乃請求人家婢子，或有罪家女養之，至八月朝，祭送蛇穴口，蛇出吞囓之。累年如此，已用九女。爾時預復募索，未得其女，將樂縣李誕，家有六女，無男。其小女名寄，應募欲行。父母不聽。寄曰：「父母無德，惟生六女，無有一男，雖有如無。女無緹縈濟父母之功，既不能供養，徒費衣食，生無所益，不如早死。賣寄之身，可得少錢，以供父母，豈不善耶？」父母慈憐，終不聽去。寄自潛行，不可禁止。寄乃告請好劍及咋蛇犬。至八月朝，便詣廟中坐，懷劍，攜犬。先將數石糕餅，用蜜漿灌之，以置穴口。蛇便出。頭大如穀倉，目如二尺鏡，聞餅香氣，先啖食之。寄便放犬，犬就囓咋，寄從後斫得數創。創痛急，蛇因躍出，至庭而死。寄入視穴，得其九女骷髏，悉舉出，吒言曰：「汝輩怯弱，為蛇所食，甚可哀憐！」於是寄緩步而歸。越王聞之，聘寄為后，拜其父為將樂令，母及姊皆有賞賜。自是東冶無復妖邪之物。", "translation": "東越閩中有座庸嶺，高達數十里，西北方的濕地有一條大蛇，長七八丈，粗十多圍，當地人常常害怕牠。東冶都尉和所屬各城的官員，有很多被牠害死。用牛羊祭祀，仍然得不到保佑。大蛇有時託夢給人，有時指示巫祝，說想吃十二三歲的少女。都尉和縣令、縣長都為此憂愁，但妖氣災禍不停，就去尋求人家的婢女，或犯罪人家的女兒來養著，到八月初一，送到蛇洞口祭祀，蛇出來就把她吞吃。好幾年都是這樣，已經用了九個女孩。這時又預先招募，還沒找到女孩。將樂縣的李誕家有六個女兒，沒有兒子。最小的女兒叫李寄，想要應募前往，父母不答應。李寄說：「父母沒有福分，只生了六個女兒，沒有一個兒子，有了等於沒有。女兒沒有像緹縈救父母那樣的功勞，既然不能奉養父母，只是白白耗費衣食，活著沒有好處，不如早點死。賣了我，可以得到一點錢來供養父母，難道不好嗎？」父母慈愛憐惜她，始終不讓她去。李寄自己偷偷前往，無法阻止。李寄於是請求給她好劍和會咬蛇的狗。到了八月初一，就到廟裡坐著，懷裡藏劍，帶著狗。先把好幾石的米糕用蜜汁澆灌，放在蛇洞口。蛇就出來了，頭大得像穀倉，眼睛像二尺寬的鏡子，聞到糕餅香味，先吃了起來。李寄就放狗，狗上前咬牠，李寄從後面砍了好幾刀。傷口劇痛，蛇跳出來，到了庭院就死了。李寄進洞察看，找到那九個女孩的骷髏，全部拿出來，嘆息說：「你們膽怯軟弱，被蛇吃掉，真令人哀憐！」於是李寄慢慢走回家。越王聽說這件事，聘娶李寄為王后，任命她父親為將樂縣令，母親和姊姊都有賞賜。從此東冶再也沒有妖邪之物了。", "keywords": [{"w": "圍", "m": "兩手合抱的粗細"}, {"w": "土俗", "m": "當地人"}, {"w": "巫祝", "m": "巫師"}, {"w": "啖", "m": "吃"}, {"w": "患", "m": "憂慮"}, {"w": "朝", "m": "初一"}, {"w": "緹縈", "m": "漢代孝女，上書救父"}, {"w": "徒", "m": "白白地"}, {"w": "詣", "m": "前往"}, {"w": "斫", "m": "砍"}, {"w": "創", "m": "傷口"}, {"w": "吒", "m": "嘆息"}], "questions": [{"n": 46, "stem": "下列文句，何者最能顯示出古代女性不受重視的意識？", "options": {"A": "欲得啖童女年十二三者", "B": "父母無德，惟生六女，無有一男", "C": "汝輩怯弱，為蛇所食，甚可哀憐", "D": "越王聞之，聘寄為后"}, "answer": "B", "explain": "(B)李寄說父母「無德」，因為只生了六個女兒，沒有一個兒子，「雖有如無」——生女兒等於沒生，明顯反映重男輕女、女性不受重視的觀念，正確。(A)是大蛇想吃少女，屬於故事情節。(C)是李寄哀憐九個女孩的軟弱。(D)是越王表彰李寄，反而是重視她。", "skill": "找出把「女兒」與「沒有價值」直接連在一起的句子（無德、雖有如無）。"}, {"n": 47, "stem": "根據這篇小說的內容，下列敘述何者正確？", "options": {"A": "最先被地方官員送入蛇口的，皆為罪有應得之人", "B": "李寄應募之時，已抱定死裡求生、為民除害之心", "C": "大蛇長年為患，東冶已無牛羊可供祭祀，遂以童女代之", "D": "李寄以「徒費衣食，生無所益」，成功說服父母允其應募祭蛇"}, "answer": "B", "explain": "李寄應募後請求好劍和咬蛇犬，又準備蜜糕引蛇，可見她不是去送死，而是早已打算冒死除蛇，(B)正確。(A)送去的是「人家婢子，或有罪家女」，婢女並非罪人，有罪人家的女兒也不是自己犯罪。(C)是因為祭牛羊得不到福、蛇指名要童女，不是沒有牛羊。(D)父母「終不聽去」，李寄是偷偷前往，沒有說服父母。", "skill": "回到原文核對每個細節（送誰、為何改用童女、父母是否同意），再從李寄的準備動作推論她的心意。"}, {"n": 48, "stem": "關於這篇小說的寫作手法，下列敘述何者錯誤？", "options": {"A": "藉送女祭蛇之事，揭露官吏裝神弄鬼、欺壓百姓的惡行", "B": "以巨大的外貌與食人的習性，凸顯大蛇令人驚懼的形象", "C": "依時間先後描述李寄誘以蜜餅，繼之放犬，從而斫蛇的除害經過", "D": "以都尉、令、長等成年男性的束手無策，襯托少女李寄的勇敢聰慧"}, "answer": "A", "explain": "(A)文中官吏也深受蛇害（「多有死者」「並共患之」），是無計可施才送女祭蛇，並沒有寫他們裝神弄鬼、欺壓百姓，敘述錯誤，是答案。(B)「長七八丈，大十餘圍」「頭大如穀倉，目如二尺鏡」寫外貌，「欲得啖童女」寫食人，正確。(C)先放蜜糕、再放犬、最後砍蛇，按時間順序，正確。(D)官員束手無策，反襯少女李寄的智勇，正確。", "skill": "「錯誤」題：檢查選項是否加入原文沒有的評價（如「裝神弄鬼、欺壓」）。"}], "difficulty": "中", "label": "102年基測", "year": 102, "kind": "基測"}, {"id": "hk102-10", "exam": "hk102", "nums": [10], "form": "單題", "img": "img/hk102-10.png", "source": "杜甫〈送路六侍御入朝〉", "author": "杜甫", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "童稚情親四十年，中間消息兩茫然。更為後會知何地？忽漫相逢是別筵。不忿桃花紅勝錦，生憎柳絮白於綿。劍南春色還無賴，觸忤愁人到酒邊。", "translation": "我們從小就感情親密，算來已經四十年了，可是中間這些年彼此音訊全無。這次分別之後，又不知道哪裡才能再相會？沒想到忽然相逢，竟然就在送別的酒席上。我討厭桃花紅得勝過錦緞，憎恨柳絮白得勝過棉絮。劍南的春色真是不懂事，偏偏在酒席邊撩撥我這個滿懷愁緒的人。", "keywords": [{"w": "童稚", "m": "小時候"}, {"w": "茫然", "m": "模糊不清，指音訊全無"}, {"w": "忽漫", "m": "忽然、偶然"}, {"w": "別筵", "m": "送別的酒席"}, {"w": "不忿", "m": "不滿、嫌惡"}, {"w": "生憎", "m": "最恨、偏恨"}, {"w": "無賴", "m": "可愛得惱人、不懂事地撩人"}, {"w": "觸忤", "m": "觸犯、招惹"}], "questions": [{"n": 10, "stem": "杜甫〈送路六侍御入朝〉：「童稚情親四十年，中間消息兩茫然。更為後會知何地？忽漫相逢是別筵。不忿桃花紅勝錦，生憎柳絮白於綿。劍南春色還無賴，觸忤愁人到酒邊。」關於這首詩的內容，下列敘述何者正確？", "options": {"A": "作者與友人相處四十年，從今之後要分隔兩地", "B": "作者友人將赴劍南，送別之際，兩人離情依依", "C": "劍南景觀蕭索枯寂，使兩人倍加懷念故鄉春景", "D": "自此一別，重逢難期，使得作者更添離情愁緒"}, "answer": "D", "explain": "「更為後會知何地？」意思是這次分手後，不知何時何地才能再見，所以作者看到美好春景反而更添愁緒，(D)正確。(A)錯：「童稚情親四十年」是說從小認識到現在已四十年，但「中間消息兩茫然」，中間其實長期沒有聯絡，並非一直相處。(B)錯：題目說友人是「入朝」（到京城），劍南是兩人相逢、送別的地方，不是友人要去的地方。(C)錯：桃花紅、柳絮白、「春色還無賴」，可見劍南春景很美，並不蕭索；作者是因離別心情不好，才嫌春色惱人。", "skill": "先抓時間線（四十年、中間斷訊、忽然相逢又分別），再注意「不忿、生憎、無賴」是以樂景寫哀情——景越美越襯出愁。"}], "difficulty": "中", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-11", "exam": "hk102", "nums": [11], "form": "單題", "img": "img/hk102-11.png", "source": "李煜〈子夜歌〉等詞句", "author": "李煜等", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)重到故鄉交舊少，淒涼，卻恐他鄉是故鄉　(B)寂寞古豪華，烏衣日又斜。說興亡，燕入誰家　(C)扁舟去作江南客，旅雁孤雲，萬里煙塵，回首中原淚滿襟　(D)人生愁恨何能免？銷魂獨我情何限！故國夢重歸，覺來雙淚垂", "translation": "(A)重回故鄉，老朋友已所剩無幾，心中淒涼，反而覺得他鄉像故鄉。(B)昔日繁華已成寂寞，烏衣巷又是夕陽西斜，說起興亡，燕子不知飛進了誰家。(C)乘著小船南下當江南的過客，像孤雁孤雲；萬里戰火煙塵，回頭望向中原，淚濕衣襟。(D)人生的愁恨哪能避免？為什麼只有我傷心得沒有盡頭！夢裡又回到故國，醒來時雙眼垂淚。", "keywords": [{"w": "銷魂", "m": "極度悲傷，像失了魂"}, {"w": "故國", "m": "已滅亡的祖國"}, {"w": "覺", "m": "睡醒"}, {"w": "烏衣", "m": "烏衣巷，金陵（南京）古地名，詠懷古蹟常用"}], "questions": [{"n": 11, "stem": "南唐覆亡，後主李煜被俘至北方，遠離家園，詞作中常流露對故國的思念。據此判斷，下列詞句何者最可能是李煜書寫這類主題的作品？", "options": {"A": "重到故鄉交舊少，淒涼，卻恐他鄉是故鄉", "B": "寂寞古豪華，烏衣日又斜。說興亡，燕入誰家", "C": "扁舟去作江南客，旅雁孤雲，萬里煙塵，回首中原淚滿襟", "D": "人生愁恨何能免？銷魂獨我情何限！故國夢重歸，覺來雙淚垂"}, "answer": "D", "explain": "題幹給了兩個條件：身在北方遠離家園、思念「故國」。(D)「故國夢重歸，覺來雙淚垂」——夢中回到故國，醒來淚流，正是亡國之君的思念，出自李煜〈子夜歌〉。(A)是「重到故鄉」，人已回到故鄉，與被俘在外不合。(B)是登臨古蹟、感嘆歷史興亡的懷古之作，並非思念自己的故國家園。(C)「扁舟去作江南客」「回首中原」是從北方中原往南逃到江南，方向與「被俘至北方」相反（此為朱敦儒南渡時的作品）。", "skill": "把題幹條件化成檢查清單（人在何處、往哪個方向、思念對象），逐一刪去方向或身分不符的選項。"}], "difficulty": "中", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-19", "exam": "hk102", "nums": [19], "form": "單題", "img": "img/hk102-19.png", "source": "顏真卿與子孫書", "author": "顏真卿", "genre": "書信序跋", "types": ["人物情感", "主旨寓意"], "passage": "顏真卿謫居時，與其子孫書云：「政可守，不可不守。吾去歲中言事得罪，又不能逆道苟時為千古罪人也，雖貶居遠方，終身不恥。汝輩當須謂吾之志不可不守也。」", "translation": "顏真卿被貶官居住在外時，寫信給子孫說：「正道是可以堅守的，就不能不堅守。我去年因為上書議論政事而得罪，但我也不能違背正道、苟且迎合時勢，成為千古罪人。所以即使被貶到遠方，我一輩子也不覺得羞恥。你們應當明白：我的志節是不能不堅守的。」", "keywords": [{"w": "謫居", "m": "被貶官後居住在外地"}, {"w": "政", "m": "通「正」，正道"}, {"w": "言事", "m": "上書議論政事"}, {"w": "逆道", "m": "違背正道"}, {"w": "苟時", "m": "苟且迎合時勢"}, {"w": "汝輩", "m": "你們"}], "questions": [{"n": 19, "stem": "顏真卿謫居時，與其子孫書云：「政可守，不可不守。吾去歲中言事得罪，又不能逆道苟時為千古罪人也，雖貶居遠方，終身不恥。汝輩當須謂吾之志不可不守也。」顏真卿在信中所顯現的處世態度，與下列哪一句話最接近？", "options": {"A": "信用是一切價值的根基，誰能堅守不移，誰就可以成功", "B": "無論處在如何險惡的境地，都應秉持著豁達樂觀的態度", "C": "為了捍衛國家政策，不得不付出沉重的代價，但我們仍應積極付出", "D": "一個人立身行事都應本其良心，在任何場合都不該放棄自己的信念"}, "answer": "D", "explain": "信中重點是「不能逆道苟時」「雖貶居遠方，終身不恥」「吾之志不可不守」：寧可被貶，也不放棄正道與志節，與(D)「本其良心，不放棄信念」相符。(A)談信用與成功，信中沒有提到守信，也不是為了成功。(B)重點在豁達樂觀，但顏真卿強調的是堅守原則，而非心情調適。(C)「捍衛國家政策」誤解了「政可守」——「政」是正道，不是政策。", "skill": "找出文中反覆出現的關鍵字（守、不可不守、志），歸納成一個態度詞（堅守原則），再比對選項的核心詞。"}], "difficulty": "易", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-22", "exam": "hk102", "nums": [22], "form": "單題", "img": "img/hk102-22.png", "source": "出處待查", "author": "", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "一人覆屋以瓦，一人覆屋以茅，謂覆瓦者曰：「子之費十倍予，然而蔽風雨一也。」覆瓦者曰：「茅十年腐，而瓦百年不碎。子百年十更，而多以工力之費，屢變之勞也。」", "translation": "有一個人用瓦片蓋屋頂，另一個人用茅草蓋屋頂。用茅草的人對用瓦的人說：「你花的錢是我的十倍，可是遮風擋雨的效果是一樣的。」用瓦的人說：「茅草十年就腐爛了，瓦片一百年也不會碎。你一百年要換十次，反而多花了工錢力氣，還得一再更換的辛勞。」", "keywords": [{"w": "覆", "m": "覆蓋"}, {"w": "子", "m": "你"}, {"w": "予", "m": "我"}, {"w": "一", "m": "相同"}, {"w": "更", "m": "更換"}, {"w": "屢", "m": "多次"}], "questions": [{"n": 22, "stem": "「一人覆屋以瓦，一人覆屋以茅，謂覆瓦者曰：『子之費十倍予，然而蔽風雨一也。』覆瓦者曰：『茅十年腐，而瓦百年不碎。子百年十更，而多以工力之費，屢變之勞也。』」這則故事中覆瓦者的觀點，與下列何者最接近？", "options": {"A": "宅第所用建材應採價格高者，方能遮風蔽雨", "B": "建屋為求堅固，應不計工力之費，屢變之勞", "C": "成事之道在能深謀遠慮，不計眼前之所費", "D": "能盡人一己百的努力，才能建立不朽之功"}, "answer": "C", "explain": "覆瓦者認為：瓦雖然一開始貴，但百年不壞；茅草便宜卻要一再更換，長期算下來更費工。也就是眼光要放遠，不要只計較眼前的花費，(C)正確。(A)錯：兩人都承認遮風雨效果「一也」，重點不在價格高才能遮雨。(B)錯：「工力之費，屢變之勞」正是覆瓦者用來批評用茅草的缺點，他是想省下這些，不是不計較。(D)談加倍努力建功，與文意無關。", "skill": "比較雙方各自計算的是「眼前花費」還是「長期成本」，就能看出覆瓦者的思考層次。"}], "difficulty": "易", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-23", "exam": "hk102", "nums": [23], "form": "單題", "img": "img/hk102-23.png", "source": "古典詩文名句（陶淵明〈飲酒〉、蘇軾〈記承天寺夜遊〉等）", "author": "陶淵明等", "genre": "古典詩詞曲", "types": ["寫作手法", "句意理解"], "passage": "(A)風裡落花誰是主？思悠悠　(B)問君何能爾？心遠地自偏　(C)同來望月人何處？風景依稀似去年　(D)何夜無月？何處無竹柏？但少閑人如吾兩人耳", "translation": "(A)風中飄落的花誰是它的主人呢？思緒綿長。(B)問我為什麼能做到這樣？因為心境遠離塵俗，住處自然顯得偏僻安靜。(C)一起來賞月的人在哪裡呢？風景卻好像和去年差不多。(D)哪一個夜晚沒有月光？哪裡沒有竹子柏樹？只是缺少像我們兩人這樣的閒人罷了。", "keywords": [{"w": "爾", "m": "如此、這樣"}, {"w": "偏", "m": "偏僻、安靜"}, {"w": "依稀", "m": "好像、隱約"}, {"w": "但", "m": "只"}, {"w": "耳", "m": "罷了"}], "questions": [{"n": 23, "stem": "下列文句，何者屬於先提出問題，再針對問題回答？", "options": {"A": "風裡落花誰是主？思悠悠", "B": "問君何能爾？心遠地自偏", "C": "同來望月人何處？風景依稀似去年", "D": "何夜無月？何處無竹柏？但少閑人如吾兩人耳"}, "answer": "B", "explain": "(B)出自陶淵明〈飲酒〉：先問「為什麼你能做到（住在人間卻不覺車馬喧鬧）？」再答「心遠地自偏」，是典型的「設問中的提問」——自問自答。(A)問「誰是主」後接「思悠悠」，並沒有回答是誰，屬於懸問。(C)問「人何處」，後句寫風景似去年，沒有回答人在哪裡。(D)「何夜無月？何處無竹柏？」是答案在問題反面的激問（意思是每晚都有月、處處有竹柏），後面「但少閑人」是另起的感慨，不是回答前面的問題。", "skill": "檢查問句後面那句是否「直接回答了問句問的東西」——問原因就要答原因，問人在哪就要答地點。"}], "difficulty": "中", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-28", "exam": "hk102", "nums": [28], "form": "單題", "img": "img/hk102-28.png", "source": "《世說新語‧文學》", "author": "劉義慶", "genre": "筆記小品", "types": ["人物情感", "文意推論"], "passage": "人有問殷中軍：「何以將得位而夢棺器，將得財而夢矢穢？」殷曰：「官本是臭腐，所以將得而夢棺屍；財本是糞土，所以將得而夢穢汙。」時人以為名通。", "translation": "有人問殷浩：「為什麼快要得到官位時會夢見棺材，快要得到錢財時會夢見糞便？」殷浩說：「官位本來就是腐臭的東西，所以快得到時會夢到棺材屍體；錢財本來就是糞土，所以快得到時會夢到髒汙。」當時的人認為這是很高明的名言。", "keywords": [{"w": "殷中軍", "m": "東晉殷浩，曾任中軍將軍"}, {"w": "棺器", "m": "棺材"}, {"w": "矢穢", "m": "屎尿等髒東西（矢通「屎」）"}, {"w": "名通", "m": "名言、名論"}], "questions": [{"n": 28, "stem": "「人有問殷中軍：『何以將得位而夢棺器，將得財而夢矢穢？』殷曰：『官本是臭腐，所以將得而夢棺屍；財本是糞土，所以將得而夢穢汙。』時人以為名通。」下列何者最適合用來形容這段文字所呈現的殷中軍？", "options": {"A": "恃才傲物", "B": "洩露天機", "C": "感時憂國", "D": "善於譬解"}, "answer": "D", "explain": "殷浩把「官位」比喻成腐臭的屍體、把「錢財」比喻成糞土，用巧妙的比喻解釋了奇怪的夢，當時人稱讚為名言，可見他「善於譬解」（擅長用比喻解說）。(A)恃才傲物是仗著才能看不起人，文中他只是回答問題，沒有傲慢表現。(B)洩露天機指透露不該說的秘密，與文意無關。(C)感時憂國是憂心國家時局，文中沒有談國事。", "skill": "看人物「怎麼回答」：把夢中物與現實物一一對應（棺屍↔官、穢汙↔財），就能看出他用的是比喻解釋。"}], "difficulty": "易", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-30", "exam": "hk102", "nums": [30], "form": "單題", "img": "img/hk102-30.png", "source": "禪宗語錄（臨濟義玄與洛浦元安的對話）", "author": "", "genre": "經典語錄", "types": ["主旨寓意", "文意推論"], "passage": "元安辭臨濟去。濟曰：「門下有隻赤梢鯉魚，搖頭擺尾向南方去，不知向誰家虀甕裡淹殺？」", "translation": "元安向臨濟禪師告辭要離開。臨濟說：「我門下有一條紅尾巴的鯉魚，搖頭擺尾地往南方游去，不知道會在誰家的醃菜缸裡被醃死？」", "keywords": [{"w": "辭", "m": "告別"}, {"w": "赤梢", "m": "紅色的尾巴，形容顯眼"}, {"w": "搖頭擺尾", "m": "得意招搖的樣子"}, {"w": "虀甕", "m": "醃菜缸"}, {"w": "淹殺", "m": "醃死"}], "questions": [{"n": 30, "stem": "「元安辭臨濟去。濟曰：『門下有隻赤梢鯉魚，搖頭擺尾向南方去，不知向誰家虀甕裡淹殺？』」臨濟以魚為喻，話中的涵義與下列何者最接近？", "options": {"A": "不知變通者經常落入陷阱", "B": "個性猶疑者難以選擇去向", "C": "善於奉承者往往遭受批評", "D": "炫耀招搖者容易惹禍上身"}, "answer": "D", "explain": "臨濟把元安比成「赤梢鯉魚」，又說牠「搖頭擺尾」——顏色顯眼、姿態得意，結果恐怕會被人抓去醃菜缸醃死，暗示太過招搖容易招來禍患，(D)正確。(A)文中沒有提到不知變通。(B)鯉魚明確「向南方去」，並非猶豫不決。(C)「搖頭擺尾」是得意招搖，不是奉承討好。", "skill": "拆解比喻：先找喻體的特徵（赤梢＝顯眼、搖頭擺尾＝得意），再看結局（被淹殺），特徵＋結局＝寓意。"}], "difficulty": "中", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-33", "exam": "hk102", "nums": [33], "form": "單題", "img": "img/hk102-33.png", "source": "鄭燮〈濰縣署中寄舍弟墨第二書〉", "author": "鄭燮（鄭板橋）", "genre": "書信序跋", "types": ["主旨寓意", "句意理解"], "passage": "讀書以過目成誦為能，最是不濟事。眼中了了，心下匆匆，方寸無多，往來應接不暇，如看場中美色，一眼即過，與我何與也？", "translation": "讀書把看一遍就能背誦當作本事，這是最沒用的。眼睛看得清清楚楚，心裡卻匆匆忙忙，心中容納的東西不多，來來往往應付不過來，就像看戲場中的美女，看一眼就過去了，和我又有什麼關係呢？", "keywords": [{"w": "過目成誦", "m": "看過一遍就能背出來"}, {"w": "不濟事", "m": "沒有用"}, {"w": "了了", "m": "清楚"}, {"w": "方寸", "m": "指內心"}, {"w": "與我何與", "m": "跟我有什麼關係（後一「與」是相關）"}], "questions": [{"n": 33, "stem": "「讀書以過目成誦為能，最是不濟事。眼中了了，心下匆匆，方寸無多，往來應接不暇，如看場中美色，一眼即過，與我何與也？」根據這段文字，作者對讀書的看法與下列何者最接近？", "options": {"A": "讀書當咀嚼深思，不宜淺嘗輒止", "B": "為學當專心致志，不為外物所惑", "C": "能讀無字之書，方能領悟知識的奧妙", "D": "讀書過目成誦，方可收事半功倍之效"}, "answer": "A", "explain": "作者批評「過目成誦」只是眼睛看清、心裡匆匆，像看美女一眼就過，沒有真正吸收；言下之意，讀書要用心體會、反覆思考，(A)正確。(B)文中的「美色」是比喻讀書一眼即過，不是說要抵抗外物誘惑。(C)「無字之書」指生活經驗，文中沒有提到。(D)與作者看法相反，作者認為過目成誦「最是不濟事」。", "skill": "先找作者的評價詞（最是不濟事）確定他反對什麼，再把反面推出來就是他主張的。注意比喻（看場中美色）是在形容讀書方式，不要當成字面意思。"}], "difficulty": "易", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-34", "exam": "hk102", "nums": [34], "form": "單題", "img": "img/hk102-34.png", "source": "出處待查（論山水畫與遊記之文）", "author": "", "genre": "說理議論", "types": ["文意推論", "比較閱讀"], "passage": "余觀古之登山者，皆有遊名山記，縱其文筆高妙，善於摹寫，極力形容，處處精到，然於語言文字之間，使人想像，終不得其面目。不若圖之縑素，則其山水之幽深，煙雲之吞吐，一舉目皆在，而吾得以神遊其間，顧不勝於文章萬萬耶。", "translation": "我看古代登山的人，都寫有遊覽名山的記，即使文筆高明巧妙，擅長描寫，盡力形容，處處精細到位，但透過語言文字，只能讓人去想像，終究看不到山的真面目。不如把山畫在絹布上，那麼山水的幽深、雲煙的吞吐變化，一抬眼就全都在眼前，我能夠讓心神在其中遨遊，這豈不是比文章勝過千萬倍嗎？", "keywords": [{"w": "摹寫", "m": "描寫"}, {"w": "面目", "m": "真實樣貌"}, {"w": "圖", "m": "畫（動詞）"}, {"w": "縑素", "m": "作畫用的白色細絹"}, {"w": "神遊", "m": "心神在其中遊覽"}, {"w": "顧", "m": "豈、難道"}], "questions": [{"n": 34, "stem": "「余觀古之登山者，皆有遊名山記，縱其文筆高妙，善於摹寫，極力形容，處處精到，然於語言文字之間，使人想像，終不得其面目。不若圖之縑素，則其山水之幽深，煙雲之吞吐，一舉目皆在，而吾得以神遊其間，顧不勝於文章萬萬耶。」根據這段文字，下列何者最可能是作者想要表達的看法？", "options": {"A": "山水的美麗透過繪畫技巧表現，比實景更佳妙", "B": "山水畫使閱覽者如臨其境，樂趣更甚於閱讀遊記", "C": "若只有欣賞山水畫而沒有親臨實境，終究隔了一層", "D": "欣賞山水畫之前先閱覽相關遊記，更能領略畫中意境"}, "answer": "B", "explain": "文章先說遊記文字再好，也只能讓人想像、「終不得其面目」；接著用「不若」轉折，說畫在絹上則「一舉目皆在」，能「神遊其間」，「顧不勝於文章萬萬耶」——畫比文章好得多，(B)正確。(A)作者比較的是「畫」與「文章」，不是畫與實景。(C)說畫隔了一層，正好與作者讚美畫相反。(D)作者並未主張先讀遊記再看畫。", "skill": "抓轉折詞「然」「不若」：轉折後才是作者真正的主張；再確認比較的雙方是誰（遊記 vs. 山水畫）。"}], "difficulty": "難", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-40", "exam": "hk102", "nums": [40], "form": "單題", "img": "img/hk102-40.png", "source": "陶淵明〈飲酒〉等古詩（題幹引自羅蘭〈聲音的聯想〉）", "author": "陶淵明等", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "(A)強欲登高去，無人送酒來。遙憐故園菊，應傍戰場開　(B)視人當如子，愛人亦如傷。講學試通論，阡陌勸耕桑　(C)父耕原上田，子鋤山下荒。六月禾未秀，官家已修倉　(D)日入群動息，歸鳥趨林鳴。嘯傲東軒下，陶然得此生", "translation": "(A)勉強想在重陽登高，卻沒有人送酒來；遠遠憐惜故鄉的菊花，大概正開在戰場旁邊吧。(B)看待百姓要像對自己的孩子，愛護百姓要像照顧傷患；講授學問、討論道理，到田間勸人耕田養蠶。(C)父親在原野上耕田，兒子在山下開墾荒地；六月稻禾還沒開花結穗，官府已經修好糧倉等著收稅。(D)太陽下山，萬物都休息了，歸巢的鳥兒鳴叫著飛向樹林；我在東窗下自在長嘯，快樂地過著這樣的生活。", "keywords": [{"w": "強欲", "m": "勉強想要"}, {"w": "秀", "m": "吐穗開花"}, {"w": "群動", "m": "各種活動的生物"}, {"w": "嘯傲", "m": "放聲長嘯、自在不受拘束"}, {"w": "陶然", "m": "快樂自得的樣子"}], "questions": [{"n": 40, "stem": "「在那樣的生活裡，人是屬於自然。在那樣的生活裡，才能觸摸到生命的真諦。」文句中所表現的生活態度，與下列何者最接近？", "options": {"A": "強欲登高去，無人送酒來。遙憐故園菊，應傍戰場開", "B": "視人當如子，愛人亦如傷。講學試通論，阡陌勸耕桑", "C": "父耕原上田，子鋤山下荒。六月禾未秀，官家已修倉", "D": "日入群動息，歸鳥趨林鳴。嘯傲東軒下，陶然得此生"}, "answer": "D", "explain": "題幹強調「人屬於自然」並在其中體會生命真諦。(D)陶淵明隨著日落鳥歸作息，在東軒下自在快樂，覺得這樣的人生最好，正是融入自然、怡然自得的生活態度。(A)是岑參在戰亂中思念故鄉的詩，情感是憂傷懷鄉。(B)講的是為官愛民、勸農講學，是治理百姓的態度。(C)是聶夷中〈田家〉，批判官府急著徵稅、農民辛苦，屬社會寫實。", "skill": "先把題幹濃縮成關鍵態度（親近自然、自得），再看每首詩的情緒基調：懷鄉、愛民、控訴，還是悠然自得。"}], "difficulty": "中", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-44", "exam": "hk102", "nums": [44, 45], "form": "題組", "img": "img/hk102-44.png", "source": "封演《封氏聞見記‧奇政》", "author": "封演", "genre": "筆記小品", "types": ["文意推論", "句意理解", "比較閱讀"], "passage": "李封為延陵令，吏人有罪，不加杖罰，但令裹碧頭巾以辱之。隨所犯輕重，以日數為等級，日滿乃釋。吳人著此服，出入州鄉，以為大恥，皆相勸勵，無敢僭違。賦稅常先諸縣，既去官，竟不捶一人。", "translation": "李封擔任延陵縣令時，官吏百姓犯了罪，他不用棍杖處罰，只叫犯人包上綠色頭巾來羞辱他。依照所犯罪的輕重，以戴頭巾的天數作為等級，天數滿了才放過他。吳地的人戴著這種頭巾，進出州里鄉里，認為是極大的恥辱，於是大家互相勸勉，沒有人敢越分違法。延陵縣繳納賦稅常常比其他各縣早；直到李封離任，竟然沒有用杖打過一個人。", "keywords": [{"w": "令", "m": "縣令（名詞）；使、讓（動詞）"}, {"w": "杖罰", "m": "用棍杖打的刑罰"}, {"w": "但", "m": "只"}, {"w": "釋", "m": "釋放、放過"}, {"w": "僭違", "m": "越分違法"}, {"w": "捶", "m": "以杖擊打"}, {"w": "既", "m": "已經、等到"}], "questions": [{"n": 44, "stem": "文中李封的治理之道，與下列何者最接近？", "options": {"A": "賞不勸謂之止善，罰不懲謂之縱惡", "B": "刑罰不可弛於國，鞭捶不得廢於家", "C": "政治之基必本於心，苟人民有恥，則刑罰無可施也", "D": "賞莫如厚而信，使民利之；罰莫如重而必，使民畏之"}, "answer": "C", "explain": "李封不打人，只用綠頭巾讓人覺得羞恥，結果人人自我約束、不敢犯法，離任時沒打過一個人——這是用「羞恥心」代替刑罰，與(C)「人民有恥，則刑罰無可施」完全相合。(A)強調賞罰要有效果，重點在賞罰本身。(B)主張刑罰鞭打不能廢，與李封「不加杖罰」相反。(D)主張重罰使民畏懼，是法家嚴刑思想，與李封以恥辱教化不同。", "skill": "先歸納李封的方法核心（不用刑、用羞恥），再刪去主張「重刑、不可廢刑」的選項。"}, {"n": 45, "stem": "下列文句，何者是延陵百姓盡皆守法的具體表現？", "options": {"A": "吏人有罪，不加杖罰", "B": "以日數為等級，日滿乃釋", "C": "吳人著此服，出入州鄉", "D": "賦稅常先諸縣"}, "answer": "D", "explain": "「賦稅常先諸縣」——延陵百姓繳稅總比其他縣早，是人民守法的具體結果，(D)正確。(A)(B)是李封處罰的方法，屬於官員的作為，不是百姓的表現。(C)是犯了罪的人戴頭巾受罰的情形，說明他們曾經犯法，不能證明百姓守法。", "skill": "先分清句子的主詞是「官（李封）」還是「民」，再分辨是「手段」還是「結果」——題目要的是百姓守法的結果。"}], "difficulty": "中", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk102-46", "exam": "hk102", "nums": [46, 47, 48], "form": "題組", "img": "img/hk102-46.png", "source": "皮日休《皮子文藪‧悲摯獸》", "author": "皮日休", "genre": "寓言故事", "types": ["虛詞句式", "主旨寓意", "文意推論"], "passage": "江澤之埸，農夫持弓矢，行其稼穡之側，有蘆葦傾焉，農夫息其傍。未久，蘆花紛然，不吹而飛，若有物嬉。視之，虎也，跳踉哮闞，視其狀，若有所獲，不勝其喜之態也。農夫謂虎見己，將遇食而喜者，乃挺矢匿形，伺其重嬉。發，貫其腋，雷然而踣。乃視之，枕死麏而斃矣。論者謂獲其麏，將食而嬉，將嬉而害。日休曰：「噫！古之士，獲一名，受一位，則懼己不稱其名位，豈有喜於富貴，嬉於權勢哉？然反是者，獲一名，不勝其驕也；受一位，不勝其傲也。驕傲未足於心，而刑禍已滅其身。其不勝任，與夫獲死麏者幾希！悲夫！吾以名位為死麏，以刑禍為農夫，庶乎免於今世矣。」", "translation": "在江河湖澤的邊界，有個農夫拿著弓箭走在田邊，那裡有一片傾倒的蘆葦，農夫就在旁邊休息。不久，蘆花紛紛揚起，沒有風卻飛了起來，好像有東西在裡面嬉戲。一看，原來是老虎，牠跳躍吼叫，看牠的樣子，好像得到了什麼，一副高興得不得了的模樣。農夫以為老虎看見了自己，是因為要得到食物才高興，於是拉弓搭箭、藏好身子，等牠再次嬉鬧。一箭射出，貫穿老虎的腋下，老虎轟然倒地。農夫過去一看，老虎是枕著一隻死麏而死的。評論的人說：老虎獲得了麏，將要吃牠就嬉鬧起來，一嬉鬧就招來殺身之禍。皮日休說：「唉！古代的讀書人，得到一個名聲、接受一個官位，就擔心自己配不上這名聲官位，哪裡會因富貴而歡喜、因權勢而嬉戲呢？然而和這相反的人，得到一個名聲，就驕縱得不得了；接受一個官位，就傲慢得不得了。驕傲還沒滿足，刑罰災禍已經毀滅了他。他們不能勝任名位，和那隻得到死麏的老虎相差無幾啊！可悲啊！我把名位看作死麏，把刑罰災禍看作農夫，或許就能在當今世上免於禍患了吧。」", "keywords": [{"w": "埸", "m": "邊界"}, {"w": "稼穡", "m": "農作，指田地"}, {"w": "嬉", "m": "嬉戲、玩樂"}, {"w": "哮闞", "m": "吼叫"}, {"w": "不勝", "m": "禁不住、非常"}, {"w": "伺", "m": "等待、窺伺"}, {"w": "踣", "m": "跌倒"}, {"w": "麏", "m": "獸名，似鹿而小"}, {"w": "稱", "m": "相稱、配得上"}, {"w": "幾希", "m": "相差很少"}, {"w": "庶乎", "m": "或許、差不多可以"}], "questions": [{"n": 46, "stem": "下列「」中的文句，何者是以農夫為主語？", "options": {"A": "「視其狀」，若有所獲", "B": "發，貫其腋，「雷然而踣」", "C": "乃視之，「枕死麏而斃矣」", "D": "「將食而嬉」，將嬉而害"}, "answer": "A", "explain": "「視之，虎也，跳踉哮闞，視其狀」——是農夫去看老虎的樣子，主語是農夫，(A)正確。(B)「雷然而踣」是老虎中箭轟然倒地。(C)「枕死麏而斃」是老虎枕著死麏死去。(D)「將食而嬉」是老虎要吃麏而嬉鬧。", "skill": "文言常省略主語；遇到動作句就問「誰做的？」，從前後文的動作連貫（農夫看→老虎跳）補回主語。"}, {"n": 47, "stem": "下列何者最適合用來說明文中老虎的遭遇？", "options": {"A": "避坑落井，雪上加霜", "B": "鳥盡弓藏，兔死狗烹", "C": "得意忘形，樂極生悲", "D": "鷸蚌相爭，漁翁得利"}, "answer": "C", "explain": "老虎得到獵物後高興得跳躍吼叫，暴露了行蹤，結果被農夫射死——正是「得意忘形，樂極生悲」。(A)指躲過一災又遇另一災、禍上加禍，老虎並沒有先避開什麼災難。(B)指事成之後有功者被拋棄，與老虎無關。(D)指兩方相爭讓第三者得利，文中老虎並沒有和誰相爭。", "skill": "把故事濃縮成「原因→結果」（因狂喜而暴露→被射死），再找同樣因果結構的成語。"}, {"n": 48, "stem": "文末作者對「士」的評論，何者不是對應故事中老虎的行為而發？", "options": {"A": "懼己不稱其名位", "B": "喜於富貴，嬉於權勢", "C": "獲一名，不勝其驕也；受一位，不勝其傲也", "D": "驕傲未足於心，而刑禍已滅其身"}, "answer": "A", "explain": "(A)「懼己不稱其名位」是在描寫「古之士」——得到名位反而戒慎恐懼，正好與老虎得意忘形相反，所以不是對應老虎而發。(B)「喜、嬉」對應老虎得到獵物後的喜與嬉。(C)「不勝其驕、不勝其傲」對應老虎「不勝其喜之態」。(D)「刑禍已滅其身」對應老虎還沒吃到獵物就被射死。", "skill": "把評論句和故事句做「字詞對照」（嬉↔嬉、不勝其～↔不勝其喜、滅其身↔斃），找出唯一對照不到、甚至意思相反的那一句。"}], "difficulty": "中", "label": "102年試辦會考", "year": 102, "kind": "會考"}, {"id": "hk103-16", "exam": "hk103", "nums": [16], "form": "單題", "img": "img/hk103-16.png", "source": "吳均〈與宋元思書〉、李白〈蜀道難〉、沈復〈兒時記趣〉、歐陽脩〈賣油翁〉、《論語‧述而》等", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)蟬則「千轉」不絕／劍門「千轉」，入蜀之道難似登天　(B)明初與燕王「為難」的那位鐵鉉／眾議紛紜，教我好生「為難」　(C)使之沖煙飛鳴，作青雲白鶴「觀」／帝令廣建園林池臺，多營宮「觀」樓閣　(D)康肅忿然曰：「爾」安敢輕吾射／子謂顏淵曰：用舍行藏，唯我與「爾」有是夫", "translation": "(A)蟬聲婉轉鳴叫不停／劍門道路曲折千回，進入蜀地的路難如登天。(B)明初和燕王作對的那位鐵鉉／眾人議論紛紛，讓我十分為難。(C)讓蚊子衝著煙飛鳴，當作青雲白鶴的景象來看／皇帝下令廣建園林池臺，多建宮殿樓觀。(D)陳康肅生氣地說：「你怎麼敢輕視我的射箭技術！」／孔子對顏淵說：「被任用就施展抱負，不被任用就隱藏起來，只有我和你能做到吧！」", "keywords": [{"w": "千轉", "m": "(蟬聲)婉轉多變／(道路)曲折迴環"}, {"w": "為難", "m": "作對／感到困難"}, {"w": "觀", "m": "ㄍㄨㄢ，景象／ㄍㄨㄢˋ，樓臺建築"}, {"w": "爾", "m": "你"}], "questions": [{"n": 16, "stem": "下列文句「」中的字詞，何者意義前後相同？", "options": {"A": "蟬則「千轉」不絕／劍門「千轉」，入蜀之道難似登天", "B": "明初與燕王「為難」的那位鐵鉉／眾議紛紜，教我好生「為難」", "C": "使之沖煙飛鳴，作青雲白鶴「觀」／帝令廣建園林池臺，多營宮「觀」樓閣", "D": "康肅忿然曰：「爾」安敢輕吾射／子謂顏淵曰：用舍行藏，唯我與「爾」有是夫"}, "answer": "D", "explain": "(D)兩個「爾」都是第二人稱「你」：陳康肅罵賣油翁「你怎敢輕視我的射術」；孔子對顏淵說「只有我和你做得到」。(A)前者形容蟬聲婉轉多變，後者形容道路曲折迴環。(B)前者是「作對、對抗」，後者是「感到困難」。(C)前者是「景象」（讀ㄍㄨㄢ），後者是道教宮殿樓臺「宮觀」（讀ㄍㄨㄢˋ）。", "skill": "把兩個詞各自放回句子，用白話代換試試看：能用同一個白話詞代換而句意通順，才是意義相同。"}], "difficulty": "中", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-17", "exam": "hk103", "nums": [17], "form": "單題", "img": "img/hk103-17.png", "source": "出處待查（清人筆記）", "author": "", "genre": "筆記小品", "types": ["主旨寓意", "文意推論"], "passage": "某相國之孫，乞米於人，歸途無力自負，覓一市傭代之，嗔其行遲，曰：「吾生相門，不能肩負，固也；汝傭也，胡為亦爾？」對曰：「吾亦某尚書孫也。」此事聞之於董蒼水。貴人子孫，不可不知。", "translation": "某位宰相的孫子，向人討米，回家路上沒力氣自己背，就找了一個市集上的挑夫代背，又嫌挑夫走得慢，說：「我生在宰相家，不會挑擔，本來就是這樣；你是個挑夫，為什麼也這樣？」挑夫回答：「我也是某位尚書的孫子啊。」這件事是從董蒼水那裡聽來的。富貴人家的子孫，不能不知道這個道理。", "keywords": [{"w": "相國", "m": "宰相"}, {"w": "乞", "m": "討、求"}, {"w": "自負", "m": "自己背"}, {"w": "市傭", "m": "市集上受雇做工的人"}, {"w": "嗔", "m": "生氣、責怪"}, {"w": "固", "m": "本來"}, {"w": "胡為", "m": "為什麼"}, {"w": "爾", "m": "如此"}], "questions": [{"n": 17, "stem": "「某相國之孫，乞米於人，歸途無力自負，覓一市傭代之，嗔其行遲，曰：『吾生相門，不能肩負，固也；汝傭也，胡為亦爾？』對曰：『吾亦某尚書孫也。』此事聞之於董蒼水。貴人子孫，不可不知。」這則故事所要告誡世人的道理，與下列何者最接近？", "options": {"A": "能勤小物，故無大患", "B": "家必自毀，而後人毀之", "C": "祖蔭不可圖，唯己力可恃", "D": "但存方寸地，留與子孫耕"}, "answer": "C", "explain": "宰相的孫子淪落到討米，連米都背不動；挑夫竟也是尚書的孫子，同樣淪為苦力——祖上再顯赫也靠不住，只有自己的能力才可依靠，所以告誡「貴人子孫」，(C)正確。(A)強調勤於小事可免大禍，故事重點不在小事。(B)說家族敗亡是自己先毀壞，雖有關聯，但故事核心是「不能依賴祖先餘蔭」。(D)勸人存好心留給子孫，與故事無關。", "skill": "注意故事的反轉（挑夫也是尚書孫），再看結論對象（貴人子孫），推出要他們警惕的是「別靠祖蔭」。"}], "difficulty": "易", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-19", "exam": "hk103", "nums": [19], "form": "單題", "img": "img/hk103-19.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "人無定珍，器無常道。能者以適世為奇，才人以合時為妙。故干戈興則武夫奮，《韶》、《夏》作則文儒起。", "translation": "人才沒有固定的標準，器物也沒有不變的用途。有能力的人以適應時代為難得，有才華的人以符合時勢為高明。所以戰爭興起時，武將就奮起；禮樂興盛時，文人儒士就出頭。", "keywords": [{"w": "人無定珍", "m": "人才沒有固定的標準"}, {"w": "適世", "m": "適應時代"}, {"w": "合時", "m": "符合時勢"}, {"w": "干戈", "m": "兵器，借指戰爭"}, {"w": "《韶》、《夏》", "m": "聖人之樂，借指禮樂文治"}], "questions": [{"n": 19, "stem": "「人無定珍，器無常道。能者以適世為奇，才人以合時為妙。故干戈興則武夫奮，《韶》、《夏》作則文儒起。」這句話的涵義，與下列何者最接近？", "options": {"A": "時勢造英雄", "B": "慧眼識英雄", "C": "不以成敗論英雄", "D": "英雄不怕出身低"}, "answer": "A", "explain": "文中說人才的價值看是否「適世、合時」：亂世需要武將，太平需要文人——是時代需要決定了誰能出頭，也就是「時勢造英雄」，(A)正確。(B)強調有眼光的人能發掘人才，文中沒有提到識才的人。(C)強調不以成敗評價人，文中未談成敗。(D)強調出身，文中未提到出身高低。", "skill": "抓反覆出現的關鍵概念（適世、合時、干戈興／韶夏作），歸納為「時代決定人才」，再比對選項。"}], "difficulty": "易", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-20", "exam": "hk103", "nums": [20], "form": "單題", "img": "img/hk103-20.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "人生最不幸處，是偶一失言而禍不及，偶一失謀而事倖成，偶一恣行而獲小利，後乃視為故常，而恬不為意。則莫大之患，由此生矣。", "translation": "人生最不幸的地方，是偶然說錯一次話卻沒招來災禍，偶然計謀失當一次事情卻僥倖成功，偶然任性放縱一次卻得到小小好處，之後就把這些當成常態，安然不放在心上。那麼最大的禍患，就是從這裡產生的。", "keywords": [{"w": "失言", "m": "說錯話"}, {"w": "倖", "m": "僥倖"}, {"w": "恣行", "m": "任意放縱地做事"}, {"w": "故常", "m": "常態、慣例"}, {"w": "恬不為意", "m": "安然不在意"}, {"w": "莫大", "m": "沒有比這更大的"}], "questions": [{"n": 20, "stem": "「人生最不幸處，是偶一失言而禍不及，偶一失謀而事倖成，偶一恣行而獲小利，後乃視為故常，而恬不為意。則莫大之患，由此生矣。」這段話的涵義，與下列何者最接近？", "options": {"A": "口不出是非之言，手不取非禮之物", "B": "君子改過以全其名，小人文過以益其恥", "C": "人之犯小過，悔恨如犯大惡，夫然後能改過", "D": "若以小惡為無傷而弗去，終致罪大而不可解"}, "answer": "D", "explain": "文意是：小錯僥倖沒出事，就習以為常、不在意，最後釀成大禍。(D)「把小惡當作無傷而不去除，終究會罪大到無法收拾」與此最接近。(A)講言行謹慎、不取非分之物，沒有「小錯變大禍」的因果。(B)比較君子與小人面對過錯的態度。(C)強調犯小錯也要深切悔恨才能改，著重「改過的方法」，而原文著重「輕忽小錯的後果」。", "skill": "把原文整理成因果鏈「小錯→僥倖→習慣→大禍」，選項也要有相同的因果鏈才算最接近。"}], "difficulty": "中", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-23", "exam": "hk103", "nums": [23], "form": "單題", "img": "img/hk103-23.png", "source": "出處待查（明人寓言）", "author": "", "genre": "寓言故事", "types": ["主旨寓意"], "passage": "鄭人有愛惜魚者，計無從得魚，或汕，或網，或設餌鉤之，列三盆庭中，且實水焉。人曰：「魚以江為命，今處一勺之水，日玩弄之，而曰：『我愛魚，我愛魚』，魚不腐者，寡矣！」不聽，未三日，魚皆鱗敗以死。鄭人始悔不用或人之言。", "translation": "鄭國有個愛惜魚的人，想盡辦法弄到魚，有的用竹器抓，有的用網撈，有的放餌釣，在庭院裡擺了三個盆，並裝滿水。有人說：「魚是靠江河活命的，現在把牠放在一小勺水裡，每天把玩牠，還說『我愛魚，我愛魚』，魚不腐爛的很少啊！」他不聽，不到三天，魚全都鱗片腐爛死了。鄭人這才後悔沒聽那個人的話。", "keywords": [{"w": "計", "m": "設法、想辦法"}, {"w": "汕", "m": "用竹編的器具抓魚"}, {"w": "實", "m": "裝滿"}, {"w": "一勺之水", "m": "極少的水"}, {"w": "寡", "m": "少"}, {"w": "或人", "m": "某人"}], "questions": [{"n": 23, "stem": "這則故事所說明的道理，與下列何者最接近？", "options": {"A": "凡事適可而止，貪多無益", "B": "取物宜依道義，不可強奪", "C": "玩物容易喪志，宜加以節制", "D": "待物順應自然，不妄加干預"}, "answer": "D", "explain": "魚本來生活在江河，鄭人卻把牠抓來養在小盆裡每天玩弄，自以為是愛，結果魚全死了——愛護萬物要順應牠的天性，不能用自己的方式強加干預，(D)正確。(A)故事重點不是魚抓太多。(B)抓魚並無是否合乎道義的問題。(C)「玩物喪志」是說人沉迷而荒廢志向，故事的受害者是魚，不是鄭人的志向。", "skill": "比較兩種處境：「魚以江為命」（自然）vs.「處一勺之水，日玩弄之」（人為），對比點就是寓意。"}], "difficulty": "易", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-26", "exam": "hk103", "nums": [26], "form": "單題", "img": "img/hk103-26.png", "source": "古典詩句（〈勵學篇〉等）", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "字詞解釋"], "passage": "(A)誰將五「斗」米，擬換北窗風　(B)同歡萬「斛」酒，未足解相思　(C)昨日鴻毛萬「鈞」重，今朝山岳一朝輕　(D)書中自有千「鍾」粟，書中自有黃金屋", "translation": "(A)誰願拿五斗米的官俸，來換北窗下的清風（閒適生活）？(B)一起暢飲萬斛的酒，也不足以解除相思。(C)昨天輕如鴻毛的東西重如萬鈞，今天重如山岳的卻一下子變輕了。(D)讀書自然能得到千鍾的糧食俸祿，也能得到黃金屋（富貴）。", "keywords": [{"w": "斗", "m": "容量單位，十升為一斗"}, {"w": "斛", "m": "容量單位，古代十斗（後為五斗）為一斛"}, {"w": "鈞", "m": "重量單位，三十斤為一鈞"}, {"w": "鍾", "m": "容量單位，六斛四斗為一鍾"}], "questions": [{"n": 26, "stem": "度量衡是用來衡量長度、容積、重量的標準。下列詩句「」中的字詞，何者不是用來衡量容積的單位詞？", "options": {"A": "誰將五「斗」米，擬換北窗風", "B": "同歡萬「斛」酒，未足解相思", "C": "昨日鴻毛萬「鈞」重，今朝山岳一朝輕", "D": "書中自有千「鍾」粟，書中自有黃金屋"}, "answer": "C", "explain": "「鈞」是重量單位（三十斤為一鈞），詩句也用「重」「輕」來呼應，所以不是容積單位，(C)正確。(A)「斗」、(B)「斛」、(D)「鍾」都是量米糧、酒的容量單位，用來盛裝的東西（米、酒、粟）也提示它們是容積。", "skill": "看單位後面搭配的東西：量米酒穀物的多半是容量（斗、斛、鍾）；和「輕重」搭配的是重量（鈞、斤、兩）。"}], "difficulty": "易", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-29", "exam": "hk103", "nums": [29], "form": "單題", "img": "img/hk103-29.png", "source": "《墨子‧非樂上》", "author": "墨子", "genre": "經典語錄", "types": ["主旨寓意", "句意理解"], "passage": "民有三患：飢者不得食，寒者不得衣，勞者不得息。三者民之巨患也。", "translation": "百姓有三種憂患：飢餓的人得不到食物，寒冷的人得不到衣服，勞累的人得不到休息。這三件事是百姓最大的憂患。", "keywords": [{"w": "患", "m": "憂患、禍害"}, {"w": "息", "m": "休息"}, {"w": "巨", "m": "大"}], "questions": [{"n": 29, "stem": "「民有三患：飢者不得食，寒者不得衣，勞者不得息。三者民之巨患也。」這段文字的觀點，與下列何者最接近？", "options": {"A": "飢寒勞三者極易引發重大疫情", "B": "追求物欲的滿足是人類的大敵", "C": "民生問題應是為政者關注的焦點", "D": "無法安居樂業的人民必為禍作亂"}, "answer": "C", "explain": "文中把吃不飽、穿不暖、累了不能休息列為百姓「巨患」，都是最基本的民生需求，言下之意是執政者應優先解決這些問題，(C)正確。(A)文中沒有提到疫情。(B)吃飯、穿衣、休息是基本需求，不是「物欲」。(D)原文只說這是百姓的憂患，沒有推論到人民必定作亂，「必」字太絕對。", "skill": "先判斷「食、衣、息」的性質是基本民生需求，再刪去離題（疫情）、曲解（物欲）、過度推論（必作亂）的選項。"}], "difficulty": "易", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-30", "exam": "hk103", "nums": [30], "form": "單題", "img": "img/hk103-30.png", "source": "出處待查（宋人筆記，記白居易事）", "author": "", "genre": "筆記小品", "types": ["文意推論", "句意理解"], "passage": "今人富貴中作不如意語，少壯時作衰病語，詩家往往以為讖。白公十八歲，病中作詩云：「久為勞生事，不學攝生道。少年已多病，此身豈堪老？」然白公壽七十五。", "translation": "現在的人在富貴時寫失意的話，年輕力壯時寫衰老生病的話，詩人們常認為這會成為不祥的預言。白居易十八歲時，生病中寫詩說：「長久為勞碌的生活奔忙，沒有學習養生之道。年少就已經多病，這身體哪能活到老呢？」然而白居易活到了七十五歲。", "keywords": [{"w": "讖", "m": "預言將來吉凶的話，多指不祥的應驗"}, {"w": "白公", "m": "白居易"}, {"w": "勞生", "m": "勞碌的人生"}, {"w": "攝生", "m": "養生"}, {"w": "堪", "m": "能夠、禁得起"}], "questions": [{"n": 30, "stem": "「今人富貴中作不如意語，少壯時作衰病語，詩家往往以為讖。白公十八歲，病中作詩云：『久為勞生事，不學攝生道。少年已多病，此身豈堪老？』然白公壽七十五。」根據這段文字，下列敘述何者正確？", "options": {"A": "勞動為最佳攝生之道，可免老來多病", "B": "富貴中人作不如意語，乃為躲避凶災", "C": "身體孱弱的詩人，多因常作衰病之語", "D": "世人以為不祥之語易應驗，其實未必"}, "answer": "D", "explain": "前半說詩人常認為寫衰病的話會成讖（應驗）；後半舉白居易十八歲寫「此身豈堪老」卻活到七十五歲為反例，用「然」轉折——可見不祥之語未必應驗，(D)正確。(A)白居易說自己「不學攝生道」，文中並未說勞動是養生之道。(B)文中沒說作不如意語是為了避災。(C)倒果為因，文中沒有說身體弱是因為寫衰病語。", "skill": "注意「然」字前後：前面是一般人的說法，後面舉反例推翻它，作者的觀點就在反例裡。"}], "difficulty": "中", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-31", "exam": "hk103", "nums": [31], "form": "單題", "img": "img/hk103-31.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["主旨寓意", "比較閱讀"], "passage": "士之處世，見紛華盛麗，當如老人之度節慶。以上元、清明言之，方少年壯盛，晝夜出遊，若恐不暇，燈收花暮，輒悵然移日不能忘。老人則不然，未嘗置欣戚於胸中也。", "translation": "讀書人立身處世，看到繁華熱鬧的事物，應當像老人過節日一樣。拿元宵、清明來說，正當年輕力壯的時候，日夜出遊，好像怕時間不夠；等到花燈收起、花季結束，就悵然若失，好幾天都忘不了。老人就不是這樣，從來不把歡喜或悲傷放在心上。", "keywords": [{"w": "紛華盛麗", "m": "繁華熱鬧、榮華富貴"}, {"w": "度", "m": "過（節日）"}, {"w": "上元", "m": "元宵節"}, {"w": "方", "m": "正當"}, {"w": "不暇", "m": "來不及"}, {"w": "移日", "m": "經過好幾天"}, {"w": "欣戚", "m": "歡喜與憂傷"}], "questions": [{"n": 31, "stem": "「士之處世，見紛華盛麗，當如老人之度節慶。以上元、清明言之，方少年壯盛，晝夜出遊，若恐不暇，燈收花暮，輒悵然移日不能忘。老人則不然，未嘗置欣戚於胸中也。」這段文句的主旨，與下列何者最接近？", "options": {"A": "應學習老人不輕易顯露好惡的處世態度", "B": "少年老年的人生滋味，都應該細細體會", "C": "慶祝節日宜尚簡樸，不應追求紛華盛麗", "D": "對於名利繁華，宜淡然處之，無須掛懷"}, "answer": "D", "explain": "作者以少年與老人過節做對比：少年追逐熱鬧，結束後悵然不忘；老人則心中不留喜悲。開頭點明「見紛華盛麗，當如老人」——面對繁華名利要淡然、不掛心，(D)正確。(A)老人是「心中」不放欣戚，不是「不顯露」好惡，選項把內在淡然誤成外在隱藏。(B)作者明顯肯定老人、否定少年，不是兩者都要體會。(C)過節只是比喻，主旨不在慶祝節日的方式。", "skill": "先辨認「過節」是比喻，真正的主題在首句「士之處世，見紛華盛麗」；再看對比雙方中作者肯定哪一方。"}], "difficulty": "中", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-33", "exam": "hk103", "nums": [33], "form": "單題", "img": "img/hk103-33.png", "source": "蘇軾〈答李端叔書〉", "author": "蘇軾", "genre": "書信序跋", "types": ["人物情感", "文意推論"], "passage": "得罪以來，深自閉塞，扁舟草屨，放浪山水間，與漁樵雜處，往往為醉人所推罵，則自喜漸不為人識。", "translation": "獲罪被貶以來，我深深地把自己封閉起來，乘著小船、穿著草鞋，在山水之間自在遊蕩，和漁夫樵夫混在一起，常常被喝醉的人推擠責罵，我反而暗自高興漸漸不再被人認出來。", "keywords": [{"w": "閉塞", "m": "封閉，指不與官場人士往來"}, {"w": "草屨", "m": "草鞋"}, {"w": "放浪", "m": "放縱自在，不受拘束"}, {"w": "漁樵", "m": "漁夫和樵夫"}, {"w": "推罵", "m": "推擠責罵"}, {"w": "自喜", "m": "自己感到高興"}], "questions": [{"n": 33, "stem": "某文人因罪被貶後，寫道：「得罪以來，深自閉塞，扁舟草屨，放浪山水間，與漁樵雜處，往往為醉人所推罵，則自喜漸不為人識。」根據這段文字，下列對於此文人境況的描述，何者正確？", "options": {"A": "因罪人身分為人所不齒，屢受責罵", "B": "擺脫聲名之累，心情趨向適意豁達", "C": "獲罪之後，心情憂懼，經常閉門不出", "D": "對仕途絕望，決意漁樵於江湖，隱逸終老"}, "answer": "B", "explain": "被醉漢推罵，他反而「自喜漸不為人識」——高興自己不再被認出是名人，擺脫了名聲的包袱；又「放浪山水間」，心情是自在豁達的，(B)正確。(A)被推罵是因為醉漢不認識他，不是因為罪人身分。(C)「深自閉塞」指與外界隔絕，但他仍乘船遊山水，並非閉門不出，也看不出憂懼。(D)與漁樵相處不等於決意隱居終老，文中沒有提到對仕途絕望。", "skill": "找出最能透露心情的字（自喜），再判斷他「喜」的原因（不為人識），就能推出他擺脫名聲之累的心境。"}], "difficulty": "中", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-34", "exam": "hk103", "nums": [34], "form": "單題", "img": "img/hk103-34.png", "source": "出處待查（唐人軼事，記杜黃裳事）", "author": "", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "李師古跋扈，憚杜黃裳為相，未敢失禮，乃寄錢物百萬，並氈車一乘。使者未敢進，乃於宅門伺候。有肩輿自宅出，從婢二人，青衣襤褸。問：「何人？」曰：「相公夫人。」使者遽歸以告，師古乃止。", "translation": "李師古專橫霸道，但畏懼杜黃裳當宰相，不敢失禮，於是派人送去錢財百萬，還有一輛氈車。使者不敢直接進門，就在宅門外守候。這時有一頂轎子從宅中出來，跟著兩個婢女，穿著破舊的青衣。使者問：「這是誰？」回答說：「是宰相夫人。」使者急忙回去報告，李師古就打消了送禮的念頭。", "keywords": [{"w": "跋扈", "m": "專橫霸道"}, {"w": "憚", "m": "畏懼"}, {"w": "乘", "m": "量詞，一輛"}, {"w": "伺候", "m": "守候、等待"}, {"w": "肩輿", "m": "轎子"}, {"w": "襤褸", "m": "衣服破爛"}, {"w": "遽", "m": "急忙"}, {"w": "止", "m": "停止、作罷"}], "questions": [{"n": 34, "stem": "「李師古跋扈，憚杜黃裳為相，未敢失禮，乃寄錢物百萬，並氈車一乘。使者未敢進，乃於宅門伺候。有肩輿自宅出，從婢二人，青衣襤褸。問：『何人？』曰：『相公夫人。』使者遽歸以告，師古乃止。」根據本文，「師古乃止」的原因，最可能是下列何者？", "options": {"A": "由杜夫人行事知杜府儉樸，不宜致贈厚禮", "B": "使者見杜相威儀可畏，不敢貿然呈上禮物", "C": "杜夫人治家有方，遣女婢婉拒李師古之禮", "D": "得知杜相府當時僅有女眷，不敢隨意過訪"}, "answer": "A", "explain": "宰相夫人出門只帶兩個婢女，而且婢女穿著破舊的青衣，可見杜家非常儉樸清廉；使者回報後，李師古明白送厚禮只會碰釘子（甚至冒犯），就作罷了，(A)正確。(B)使者根本沒見到杜黃裳本人。(C)杜夫人和婢女只是路過，並沒有出面拒絕。(D)文中沒有說府中只有女眷，李師古作罷也不是因為不便拜訪。", "skill": "從人物的「外在細節」（從婢二人、青衣襤褸）推論家風，再連結到結果（乃止），找出因果關係。"}], "difficulty": "中", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-45", "exam": "hk103", "nums": [45, 46], "form": "題組", "img": "img/hk103-45.png", "source": "吳兢《貞觀政要》", "author": "吳兢", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "貞觀初，太宗謂蕭瑀曰：「朕少好弓矢，自謂能盡其妙。近得良弓十數，以示弓工，乃曰：『皆非良材也。』朕問其故，工曰：『木心不正，則脈理皆邪；弓雖剛勁，而遣箭不直，非良弓也。』朕始悟焉。朕以弧矢定四方，用弓多矣，而猶不得其理。況朕有天下之日淺，得為理之意固未及於弓，弓猶失之，而況於天下乎？」自是詔京官五品以上，更宿內省。每召見，皆賜坐與語，詢訪外事，務知百姓利害、政教得失焉。", "translation": "貞觀初年，唐太宗對蕭瑀說：「我年輕時喜愛弓箭，自認為完全懂得其中奧妙。最近得到十幾把好弓，拿給弓匠看，弓匠卻說：『都不是好材料。』我問原因，弓匠說：『木材中心不正，紋理就都是斜的；弓雖然剛硬有力，射出的箭卻不直，所以不是好弓。』我這才領悟。我靠弓箭平定天下，用過的弓很多，卻還沒懂得其中的道理。何況我擁有天下的時間還短，對治理國家的體會本來就比不上對弓的了解，連弓都會看錯，更何況治理天下呢？」從此太宗下令京城五品以上的官員輪流在宮中值宿。每次召見，都賜座和他們談話，詢問宮外的事情，一定要了解百姓的利弊、政治教化的得失。", "keywords": [{"w": "朕", "m": "皇帝自稱"}, {"w": "盡其妙", "m": "完全掌握其中奧妙"}, {"w": "示", "m": "給……看"}, {"w": "脈理", "m": "木材的紋理"}, {"w": "邪", "m": "通「斜」，不正"}, {"w": "遣", "m": "發射"}, {"w": "弧矢", "m": "弓箭"}, {"w": "為理", "m": "治理（唐避高宗諱，以「理」代「治」）"}, {"w": "更", "m": "輪流"}, {"w": "內省", "m": "宮中"}, {"w": "務", "m": "一定、務必"}], "questions": [{"n": 45, "stem": "根據太宗對蕭瑀所言，下列敘述何者正確？", "options": {"A": "太宗在年少時即能體悟弓矢的妙理", "B": "太宗悟得弓矢之理，故能平定天下", "C": "太宗稱許的良弓並未得到弓工的認同", "D": "太宗嫻熟治國之道，更勝於運用弓矢"}, "answer": "C", "explain": "太宗自認得到「良弓十數」，弓工卻說「皆非良材也」，可見太宗眼中的良弓，弓工並不認同，(C)正確。(A)太宗年少只是「自謂」能盡其妙，後來才發現「猶不得其理」。(B)太宗靠弓矢平定天下，但他說自己「猶不得其理」，不是悟了才平定天下。(D)太宗說自己對治國的體會「固未及於弓」，比對弓的了解還少，與選項相反。", "skill": "留意「自謂」「始悟」「猶不得」這類表示認知轉變的詞，分清楚太宗「以為的」和「實際的」。"}, {"n": 46, "stem": "根據本文末段，太宗在領悟弓矢之理後，所表現的作為是下列何者？", "options": {"A": "虛心請益，察納雅言", "B": "賞善罰惡，立法公正", "C": "親入民間，體察民情", "D": "以德教化，導正民心"}, "answer": "A", "explain": "末段說太宗讓五品以上官員輪流值宿宮中，召見時賜座談話，「詢訪外事，務知百姓利害、政教得失」——主動向臣子請教、聽取意見，(A)正確。(B)文中沒有提到賞罰或立法。(C)太宗是透過詢問官員了解民情，並沒有親自到民間。(D)文中沒有提到教化百姓。", "skill": "只看題目指定的段落（末段），找出太宗實際的動作（召見、賜坐與語、詢訪），再對應選項。注意「親自去」和「問別人」的差別。"}], "difficulty": "中", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk103-47", "exam": "hk103", "nums": [47, 48], "form": "題組", "img": "img/hk103-47.png", "source": "袁宏道〈虎丘記〉", "author": "袁宏道", "genre": "山水遊記", "types": ["文意推論", "寫作手法"], "passage": "虎丘去城可六七里，其山無高岩深壑，獨以近城，故簫鼓樓船，無日無之。凡月之夜，花之晨，雪之夕，遊人往來，紛錯如織，而中秋為尤勝。每至是日，傾城闔戶，連臂而至。衣冠仕女，下至蔀屋，莫不靚妝麗服，重茵累席，置酒交衢間。從千人石上至山門，櫛比如鱗，檀板丘積，樽罍雲瀉。遠而望之，如雁落平沙，霞鋪江上，無得而狀。", "translation": "虎丘離蘇州城大約六七里，這座山沒有高峻的岩石、深邃的山谷，只因為靠近城市，所以吹簫打鼓、遊樂的樓船，沒有一天沒有。凡是有月亮的夜晚、花開的早晨、下雪的傍晚，遊人來來往往，交錯如織布，而中秋節尤其熱鬧。每到這一天，全城的人家都關上門，手挽著手來到這裡。上自官紳仕女，下到貧苦人家，沒有不濃妝打扮、穿上華服的，鋪上一層層的墊褥坐席，在四通八達的路口擺酒。從千人石上一直到山門，人群像魚鱗、梳齒般緊密排列，拍板堆得像小山，酒像雲中降雨般傾瀉。從遠處望去，就像大雁落在平坦的沙灘上，彩霞鋪在江面上，無法形容。", "keywords": [{"w": "去", "m": "距離"}, {"w": "可", "m": "大約"}, {"w": "獨", "m": "只"}, {"w": "無日無之", "m": "沒有一天沒有（雙重否定＝天天都有）"}, {"w": "勝", "m": "盛、熱鬧"}, {"w": "傾城闔戶", "m": "全城的人家都關門出遊"}, {"w": "蔀屋", "m": "貧苦人家"}, {"w": "靚妝", "m": "豔麗的妝扮"}, {"w": "重茵累席", "m": "層層鋪設墊褥坐席"}, {"w": "交衢", "m": "四通八達的道路"}, {"w": "櫛比如鱗", "m": "像梳齒、魚鱗般緊密排列"}, {"w": "檀板", "m": "檀木製的拍板"}, {"w": "樽罍", "m": "酒器"}, {"w": "無得而狀", "m": "無法形容"}], "questions": [{"n": 47, "stem": "根據本文，下列敘述何者正確？", "options": {"A": "虎丘因為自然景觀奇險，故成為遊覽勝地", "B": "虎丘白天僅樓船往來，入夜後才遊人如織", "C": "從千人石上至山門，是虎丘遊宴最盛之處", "D": "作者認為虎丘最美之時是夕霞雁落的江景"}, "answer": "C", "explain": "文中說「從千人石上至山門，櫛比如鱗，檀板丘積，樽罍雲瀉」，人群密集、樂器酒器堆積，是遊宴最熱鬧的地方，(C)正確。(A)原文說虎丘「無高岩深壑，獨以近城」，熱鬧是因為靠近城市，不是景觀奇險。(B)「月之夜，花之晨，雪之夕」早晚都有遊人，並非只有入夜才多。(D)「如雁落平沙，霞鋪江上」是比喻遠望人群的樣子，不是真的江景。", "skill": "逐一回原文找對應句，特別注意哪些是「比喻」（雁落平沙、霞鋪江上）而不是實景。"}, {"n": 48, "stem": "關於本文的寫作方式，下列敘述何者錯誤？", "options": {"A": "多處使用譬喻手法，擬寫人群聚集虎丘的宴遊盛況", "B": "以細膩筆觸描摹虎丘的自然美景，與遊人盛況相互呼應", "C": "以層層遞進筆法，從平日寫起，再敘良辰，最後寫至佳節盛景", "D": "採用「無日無之」、「莫不」等雙重否定寫法以加強肯定的語氣"}, "answer": "B", "explain": "本文幾乎都在寫「人」的熱鬧，開頭甚至說虎丘「無高岩深壑」，並沒有細膩描寫自然美景，(B)錯誤，為正解。(A)正確：「紛錯如織」「櫛比如鱗」「如雁落平沙，霞鋪江上」都是譬喻。(C)正確：從「無日無之」（平日），到「月之夜，花之晨，雪之夕」（良辰），再到「中秋為尤勝」（佳節），層層推進。(D)正確：「無日無之」「莫不靚妝麗服」都是雙重否定，加強肯定。", "skill": "「何者錯誤」題要逐項回原文驗證；先問「本文寫的主角是什麼」（人潮而非風景），就能快速抓出錯的那一項。"}], "difficulty": "難", "label": "103年會考", "year": 103, "kind": "會考"}, {"id": "hk104-5", "exam": "hk104", "nums": [5], "form": "單題", "img": "img/hk104-5.png", "source": "《論語‧憲問》", "author": "孔子弟子及再傳弟子", "genre": "經典語錄", "types": ["句意理解"], "passage": "時然後言，人不厭其言。", "translation": "到了該說話的時候才說話，所以別人不會討厭他說的話。", "keywords": [{"w": "時", "m": "適當的時機"}, {"w": "然後", "m": "才"}, {"w": "厭", "m": "厭惡、討厭"}], "questions": [{"n": 5, "stem": "「時然後言，人不厭其言。」這句話的涵義，與下列何者最接近？", "options": {"A": "沉默是金，可免禍從口出", "B": "善傾聽者，聞言必加審查", "C": "適時發言，方為人所接受", "D": "經常練習，言語方能動聽"}, "answer": "C", "explain": "「時然後言」是看準時機才開口，結果是「人不厭其言」——別人願意接受他的話，(C)正確。(A)強調少說話以免惹禍，但原句並不是要人沉默，而是要說得適時。(B)談的是傾聽別人說話，方向相反。(D)談說話技巧的練習，原句重點是時機而不是口才。", "skill": "文言短句先逐字翻譯（時＝適當時機，然後＝才），再看前後的因果：適時說→人不厭。"}], "difficulty": "易", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-11", "exam": "hk104", "nums": [11], "form": "單題", "img": "img/hk104-11.png", "source": "出處待查（古代笑話）", "author": "", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "有農夫種茄不活，求計於農務司，司吏曰：「此不難，每茄根下埋一文即活。」問其何故，答曰：「有錢者生，無錢者死。」", "translation": "有個農夫種茄子種不活，去向管農事的官署請教辦法。官吏說：「這不難，每棵茄子的根下埋一文錢就能活。」農夫問為什麼，官吏回答：「有錢的就能活，沒錢的就會死。」", "keywords": [{"w": "求計", "m": "請教辦法"}, {"w": "司吏", "m": "官署裡的小官吏"}, {"w": "文", "m": "量詞，一文錢"}], "questions": [{"n": 11, "stem": "「有農夫種茄不活，求計於農務司，司吏曰：『此不難，每茄根下埋一文即活。』問其何故，答曰：『有錢者生，無錢者死。』」這段文字主要在揭露世間哪一種醜態？", "options": {"A": "貪官好賄，索求無度", "B": "官商勾結，欺瞞大眾", "C": "不務正道，盡信偏方", "D": "鑽營旁門，好走捷徑"}, "answer": "A", "explain": "「有錢者生，無錢者死」表面說茄子，其實是官吏藉機說出官場的真相：有錢行賄就能活命（打贏官司、辦成事），沒錢就死路一條，諷刺官員貪財好賄，(A)正確。(B)文中沒有商人，也沒有勾結。(C)埋錢不是真的偏方，而是笑話中的諷刺。(D)農夫是正常求教，並沒有走旁門捷徑。", "skill": "笑話題要找「雙關」：表面說的對象（茄子）和實際暗指的對象（人、官場）不同，把話套回人身上就是諷刺點。"}], "difficulty": "易", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-12", "exam": "hk104", "nums": [12], "form": "單題", "img": "img/hk104-12.png", "source": "白居易〈錢塘湖春行〉等古典詩句", "author": "白居易等", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "題幹：亂花漸欲迷人眼，淺草纔能沒馬蹄。　(A)金風扇微涼，遠煙凝翠晶　(B)樓倚霜樹外，鏡天無一毫　(C)隨風柳絮輕，映日杏花明　(D)黃葉覆溪橋，荒村惟古木", "translation": "題幹：繁多的花漸漸讓人看得眼花撩亂，淺淺的春草才剛能遮住馬蹄。(A)秋風吹來微微涼意，遠方的煙靄凝成翠綠晶瑩。(B)樓閣倚靠在經霜的樹木之外，天空像鏡子一樣沒有一絲雲。(C)柳絮隨風輕輕飄揚，杏花在陽光下明亮鮮豔。(D)黃葉覆蓋著溪上的小橋，荒涼的村落只剩古老的樹木。", "keywords": [{"w": "亂花", "m": "繁多、紛雜的花"}, {"w": "沒", "m": "淹沒、遮住"}, {"w": "金風", "m": "秋風（五行中秋屬金）"}, {"w": "霜樹", "m": "經霜的樹"}, {"w": "柳絮、杏花", "m": "春天的景物"}], "questions": [{"n": 12, "stem": "下列詩句，何者與「亂花漸欲迷人眼，淺草纔能沒馬蹄」所描述的季節相同？", "options": {"A": "金風扇微涼，遠煙凝翠晶", "B": "樓倚霜樹外，鏡天無一毫", "C": "隨風柳絮輕，映日杏花明", "D": "黃葉覆溪橋，荒村惟古木"}, "answer": "C", "explain": "題幹花開繁盛、草剛長出，是春天（白居易〈錢塘湖春行〉）。(C)柳絮飛、杏花開，都是春天的景物，正確。(A)「金風」是秋風。(B)「霜樹」是經霜的樹，屬秋天。(D)「黃葉」覆橋是秋天落葉。", "skill": "找出每句詩中的「季節標記詞」（花草初生、柳絮杏花＝春；金風、霜、黃葉＝秋），比對即可。"}], "difficulty": "易", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-16", "exam": "hk104", "nums": [16], "form": "單題", "img": "img/hk104-16.png", "source": "陳壽《三國志‧諸葛亮傳》評語", "author": "陳壽", "genre": "史傳人物", "types": ["句意理解", "比較閱讀"], "passage": "盡忠益時者雖仇必賞，犯法怠慢者雖親必罰。", "translation": "對國家盡忠、有益於時局的人，即使是仇人也一定獎賞；觸犯法令、怠惰散漫的人，即使是親人也一定處罰。", "keywords": [{"w": "益時", "m": "有益於當時的國家"}, {"w": "雖", "m": "即使"}, {"w": "怠慢", "m": "懈怠散漫"}], "questions": [{"n": 16, "stem": "「盡忠益時者雖仇必賞，犯法怠慢者雖親必罰。」這句話所強調的執法原則，與下列何者相去最遠？", "options": {"A": "恩必加於有功，刑必斷於有罪", "B": "不因喜以加賞，不因怒以加罰", "C": "勝法之務莫急於去奸，去奸之本莫深於嚴刑", "D": "衡之於左右，繩之於內外，無私輕重是為公正"}, "answer": "C", "explain": "題幹強調賞罰「公正無私」：只看功過，不論親疏仇怨。(A)有功才賞、有罪才罰；(B)不憑個人喜怒賞罰；(D)對左右親近與內外之人都用同一標準，無私——三者都在講公正。(C)主張以「嚴刑」除奸，重點在刑罰要重，而非公正，所以相去最遠。", "skill": "先把題幹濃縮成一個關鍵詞（公正無私），再看哪個選項的關鍵詞換成了別的概念（嚴刑）。"}], "difficulty": "中", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-18", "exam": "hk104", "nums": [18], "form": "單題", "img": "img/hk104-18.png", "source": "袁宏道與友人書（〈李子髯〉）", "author": "袁宏道", "genre": "書信序跋", "types": ["主旨寓意", "句意理解"], "passage": "人情必有所寄，然後能樂。故有以弈為寄，有以色為寄，有以技為寄，有以文為寄。古之達人，高人一層，只是他情有所寄，不肯浮泛虛度光景。", "translation": "人的情感一定要有所寄託，然後才能快樂。所以有人寄託在下棋上，有人寄託在美色上，有人寄託在技藝上，有人寄託在文章上。古代通達的人之所以高人一等，只是因為他的情感有所寄託，不肯隨隨便便、空虛地虛度時光。", "keywords": [{"w": "寄", "m": "寄託"}, {"w": "弈", "m": "下棋"}, {"w": "達人", "m": "通達事理的人"}, {"w": "浮泛", "m": "隨便、不踏實"}, {"w": "光景", "m": "時光"}], "questions": [{"n": 18, "stem": "袁宏道與友人書云：「人情必有所寄，然後能樂。故有以弈為寄，有以色為寄，有以技為寄，有以文為寄。古之達人，高人一層，只是他情有所寄，不肯浮泛虛度光景。」這段文字的主要涵義，與下列何者最接近？", "options": {"A": "以物為寄應該有所節制，不可浮濫", "B": "古之達人寄懷於民，不求一己之樂", "C": "情感有所依託，生命方能愉悅自適", "D": "習得多種才藝，方能晉身達人之列"}, "answer": "C", "explain": "首句就是主旨：「人情必有所寄，然後能樂」——情感有寄託，人生才快樂、不虛度，(C)正確。(A)文中沒有談寄託要節制。(B)達人是「情有所寄」於弈、技、文等，並非寄懷於民，也沒有說不求自己快樂。(D)作者列舉各種寄託是說「有一項」即可，不是要學會多種才藝。", "skill": "主旨常在首句或結論句；把首句「必有所寄，然後能樂」翻成白話，直接比對選項。"}], "difficulty": "易", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-20", "exam": "hk104", "nums": [20], "form": "單題", "img": "img/hk104-20.png", "source": "王守仁〈與楊仕德薛尚謙書〉（選項C）等", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "(A)剃一人之髮，易；剃萬人之髮，難　(B)復舊時之制，易；立今世之制，難　(C)破山中之賊，易；破心中之賊，難　(D)察小人之過，易；知君子之過，難", "translation": "(A)剃一個人的頭髮容易，剃一萬人的頭髮困難。(B)恢復舊時的制度容易，建立當今的制度困難。(C)打敗山中的盜賊容易，打敗心中的私欲雜念困難。(D)察覺小人的過錯容易，看出君子的過錯困難。", "keywords": [{"w": "易", "m": "容易"}, {"w": "制", "m": "制度"}, {"w": "心中之賊", "m": "內心的私欲、成見"}, {"w": "察", "m": "察覺"}], "questions": [{"n": 20, "stem": "民初某學者仍留著前朝的舊髮式，拖著一條辮子去北大授課，學生哄堂大笑，他說：「我的辮子一剪就沒有了，但你們心中的辮子恐怕就沒有那麼容易剪掉了。」他話中的涵義，與下列何者最接近？", "options": {"A": "剃一人之髮，易；剃萬人之髮，難", "B": "復舊時之制，易；立今世之制，難", "C": "破山中之賊，易；破心中之賊，難", "D": "察小人之過，易；知君子之過，難"}, "answer": "C", "explain": "學者的意思是：頭上「有形」的辮子很容易剪，但心裡「無形」的成見、舊觀念很難去除。(C)「山中之賊」是有形的外在敵人，容易打敗；「心中之賊」是無形的內心問題，難以克服——同樣是「外在有形易除，內在無形難改」。(A)比較的是人數多寡。(B)比較恢復舊制與建立新制。(D)比較小人與君子的過錯，都不是外在／內心的對比。", "skill": "找出原句的對比軸（頭上 vs. 心中＝有形 vs. 無形），再找對比軸相同的選項，而不是找字面相同（髮）的選項。"}], "difficulty": "中", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-23", "exam": "hk104", "nums": [23], "form": "單題", "img": "img/hk104-23.png", "source": "尤袤語（見《宋史》等）", "author": "尤袤", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "書，飢讀之以當肉；寒讀之以當裘；孤寂而讀之，以當友朋；幽憂而讀之，以當金石琴瑟也。", "translation": "書，飢餓時讀它可以當作肉；寒冷時讀它可以當作皮衣；孤單寂寞時讀它，可以當作朋友；憂愁苦悶時讀它，可以當作音樂。", "keywords": [{"w": "當", "m": "當作、抵得上"}, {"w": "裘", "m": "皮衣"}, {"w": "幽憂", "m": "憂愁苦悶"}, {"w": "金石琴瑟", "m": "樂器，借指音樂"}], "questions": [{"n": 23, "stem": "「書，飢讀之以當肉；寒讀之以當裘；孤寂而讀之，以當友朋；幽憂而讀之，以當金石琴瑟也。」這句話的涵義，與下列何者最接近？", "options": {"A": "讀書百遍義自現，尋根求源探其妙", "B": "處逆何妨將書讀，興味來時百憂除", "C": "紙上得來終覺淺，方知此事要躬行", "D": "求學當如飢索食，問道應似寒需衣"}, "answer": "B", "explain": "原句列舉飢、寒、孤寂、幽憂四種困境，讀書都能帶來安慰與滿足——身處逆境時讀書可以排解憂愁，(B)正確。(A)強調反覆閱讀才能理解。(C)強調實踐比書本重要。(D)雖然也用了飢、寒，但說的是求學要像飢寒的人一樣急切，是「求學態度」，不是「讀書的慰藉」。", "skill": "小心「字面相同」的陷阱（D也有飢、寒）；要比較的是句子的功能：原句是「讀書能補足困境中的缺乏」。"}], "difficulty": "中", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-24", "exam": "hk104", "nums": [24], "form": "單題", "img": "img/hk104-24.png", "source": "白居易〈題山石榴花〉", "author": "白居易", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "一叢千朵壓闌干，剪碎紅綃卻作團。風嫋舞腰香不盡，露銷妝臉淚新乾。薔薇帶刺攀應懶，菡萏生泥玩亦難。爭及此花檐戶下，任人採弄盡人看。", "translation": "一叢山石榴開了上千朵，壓在欄杆上，像把紅色薄綢剪碎後又團成一團。微風吹拂，花枝像舞女的腰般擺動，香氣不斷；露水消散，花朵像美人的臉上淚痕剛乾。薔薇有刺，大概懶得攀折；荷花長在泥中，也難以賞玩。哪裡比得上這種花就開在屋簷門前，任人採摘、讓人盡情觀賞。", "keywords": [{"w": "闌干", "m": "欄杆"}, {"w": "紅綃", "m": "紅色薄綢"}, {"w": "嫋", "m": "輕柔擺動"}, {"w": "菡萏", "m": "荷花的別名"}, {"w": "爭及", "m": "哪裡比得上"}, {"w": "檐戶", "m": "屋簷門前"}], "questions": [{"n": 24, "stem": "白居易〈題山石榴花〉：「一叢千朵壓闌干，剪碎紅綃卻作團。風嫋舞腰香不盡，露銷妝臉淚新乾。薔薇帶刺攀應懶，菡萏生泥玩亦難。爭及此花檐戶下，任人採弄盡人看。」下列關於這首詩的說明，何者錯誤？", "options": {"A": "「剪碎紅綃卻作團」——描寫山石榴花的形態", "B": "「露銷妝臉淚新乾」——描寫賞花人心緒神態", "C": "「薔薇帶刺攀應懶」——意指薔薇有刺，使人懶於採摘", "D": "「菡萏生泥玩亦難」——意指荷花長於淤泥，不易親近"}, "answer": "B", "explain": "「露銷妝臉淚新乾」是把花朵擬人化：露水消散，花朵像女子的妝臉淚痕剛乾，描寫的是「花」帶露的樣子，不是賞花人的心情，(B)錯誤，為正解。(A)把一團團紅花比成剪碎的紅綢團，是寫花形，正確。(C)薔薇有刺不好攀折，正確。(D)荷花生在泥水中難以玩賞，正確。全詩用薔薇、荷花來襯托山石榴花「任人採弄盡人看」的親近可人。", "skill": "詠物詩中的人物比喻（舞腰、妝臉）通常是擬人寫「物」；先確認全詩描寫主體是花，再判斷每句在寫誰。"}], "difficulty": "中", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-26", "exam": "hk104", "nums": [26], "form": "單題", "img": "img/hk104-26.png", "source": "陶淵明〈五柳先生傳〉、《孟子‧告子下》、〈木蘭詩〉、歐陽脩〈賣油翁〉、蘇軾〈記承天寺夜遊〉、《世說新語》等", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)「曾」不吝情去留／「曾」益其所不能　(B)「安」能辨我是雄雌／爾「安」敢輕吾射　(C)「行」拂亂其所為／月色入戶，欣然起「行」　(D)「當」窗理雲鬢／使安期有此性，猶「當」無一豪可論", "translation": "(A)竟然不在意去或留／增加他原本做不到的能力。(B)怎麼能分辨我是男是女／你怎麼敢輕視我的射箭技術。(C)使他的作為受到阻撓擾亂／月光照進門裡，高興地起身走出去。(D)對著窗戶整理像雲一樣的鬢髮／假使王安期有這種脾氣，尚且沒有一點可取之處。", "keywords": [{"w": "曾", "m": "竟然／通「增」，增加"}, {"w": "安", "m": "怎麼、哪裡（兩者相同）"}, {"w": "行", "m": "行為、作為／行走"}, {"w": "當", "m": "對著／尚且、仍然"}], "questions": [{"n": 26, "stem": "下列文句「」中的字詞，何者意義前後相同？", "options": {"A": "「曾」不吝情去留／「曾」益其所不能", "B": "「安」能辨我是雄雌／爾「安」敢輕吾射", "C": "「行」拂亂其所為／月色入戶，欣然起「行」", "D": "「當」窗理雲鬢／使安期有此性，猶「當」無一豪可論"}, "answer": "B", "explain": "(B)兩個「安」都是疑問副詞「怎麼、哪裡」：〈木蘭詩〉「怎麼能分辨我是雄是雌」；〈賣油翁〉「你怎麼敢輕視我的射術」。(A)前者「曾」是「竟然」（〈五柳先生傳〉），後者通「增」，增加（《孟子》）。(C)前者「行」是行為、作為，後者是行走、出門（〈記承天寺夜遊〉）。(D)前者「當」是對著（〈木蘭詩〉），後者是尚且、仍然。", "skill": "一字多義題：先回想每句的出處與整句翻譯，再把字義代回另一句驗證。"}], "difficulty": "中", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-27", "exam": "hk104", "nums": [27], "form": "單題", "img": "img/hk104-27.png", "source": "蘇軾〈李氏山房藏書記〉", "author": "蘇軾", "genre": "書信序跋", "types": ["主旨寓意", "文意推論"], "passage": "余猶及見老儒先生，自言其少時，欲求《史記》、《漢書》而不可得，幸而得之，皆手自書，日夜誦讀，惟恐不及。近歲市人轉相摹刻諸子百家之書，日傳萬紙，學者之於書，多且易致如此，其文詞學術，當倍蓰於昔人，而後生科舉之士皆束書不觀，游談無根，此又何也？", "translation": "我還來得及見到老一輩的讀書人，他們說自己年少時，想找《史記》、《漢書》都找不到，幸運得到了，都親手抄寫，日夜誦讀，只怕來不及。近年來商人們競相翻刻諸子百家的書，每天印出上萬張，讀書人要得到書，既多又容易到這種地步，他們的文章學問，應當比古人高出好幾倍才對；可是後輩準備科舉考試的讀書人，卻都把書捆起來不讀，空談沒有根據，這又是為什麼呢？", "keywords": [{"w": "及見", "m": "來得及見到"}, {"w": "手自書", "m": "親手抄寫"}, {"w": "市人", "m": "商人"}, {"w": "摹刻", "m": "翻刻、刊印"}, {"w": "致", "m": "取得"}, {"w": "倍蓰", "m": "數倍（蓰，五倍）"}, {"w": "束書不觀", "m": "把書捆起來不讀"}, {"w": "游談無根", "m": "空談而沒有根據"}], "questions": [{"n": 27, "stem": "「余猶及見老儒先生，自言其少時，欲求《史記》、《漢書》而不可得，幸而得之，皆手自書，日夜誦讀，惟恐不及。近歲市人轉相摹刻諸子百家之書，日傳萬紙，學者之於書，多且易致如此，其文詞學術，當倍蓰於昔人，而後生科舉之士皆束書不觀，游談無根，此又何也？」下列敘述何者最符合這段文字的意旨？", "options": {"A": "喜見印刷術進步，學術創作大量增加", "B": "讚許後生可畏，高談闊論，縱橫無礙", "C": "自傷書本取得不易，學識難與後輩抗衡", "D": "感嘆讀書風氣日下，與書籍出版量不成正比"}, "answer": "D", "explain": "作者對比：以前書難得，老儒親手抄書、日夜苦讀；現在書多又容易買，照理學問該更好，後生卻「束書不觀，游談無根」，最後用「此又何也？」表達感嘆——書越多讀書風氣反而越差，(D)正確。(A)作者並不是在高興，學術也沒有增加。(B)「游談無根」是批評，不是讚許。(C)取得書不易的是老儒，不是作者自己，作者也沒有自嘆不如後輩。", "skill": "抓「應然 vs. 實然」的落差：「當倍蓰於昔人」（應該）與「束書不觀」（實際）相反，作者的感嘆就在這個落差裡。"}], "difficulty": "中", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-29", "exam": "hk104", "nums": [29], "form": "單題", "img": "img/hk104-29.png", "source": "出處待查（清人筆記，記年羹堯事）", "author": "", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "有盜年羹堯大將軍坐騎者，為岳鍾琪部所執，將科以刑。年知之即索此人，＿＿＿＿。年因語岳曰：「此人敢盜余坐騎，膽量可知，故吾宥其罪，用其所長，料必能達成此一使命也。」其識人、推恩也，悉類此。", "translation": "有人偷了年羹堯大將軍的坐騎，被岳鍾琪的部下抓到，要依法判刑。年羹堯知道後立刻把這個人要過來，＿＿＿＿。年羹堯於是對岳鍾琪說：「這個人敢偷我的坐騎，膽量可想而知，所以我寬恕他的罪，任用他的長處，料想他一定能完成這個任務。」年羹堯識別人才、施予恩惠，大都像這樣。", "keywords": [{"w": "執", "m": "抓住、逮捕"}, {"w": "科以刑", "m": "判處刑罰"}, {"w": "索", "m": "要求、討取"}, {"w": "宥", "m": "寬恕"}, {"w": "推恩", "m": "施予恩惠"}, {"w": "悉", "m": "都"}, {"w": "類", "m": "類似"}], "questions": [{"n": 29, "stem": "根據文意脈絡判斷，畫線處應填入下列何者最恰當？", "options": {"A": "命為車駕，兼飼坐騎，以折其罪", "B": "慎審之，憫其迫於饑寒，乃縱而歸之", "C": "令縛於地，縱馬往來其側以懾之，盜驚悸股慄", "D": "先釋其罪，並賞一官，飭其率兵往劫敵營，全勝而回"}, "answer": "D", "explain": "後文年羹堯說「宥其罪（寬恕他）」「用其所長（任用他的膽量）」「料必能達成此一使命」，可見空格要有：赦免罪過＋派他去執行一項需要膽量的任務＋結果成功。(D)「先釋其罪，並賞一官，飭其率兵往劫敵營，全勝而回」完全吻合。(A)只是讓他駕車養馬抵罪，沒有用到膽量，也不是「使命」。(B)是同情而放他回家，沒有「用其所長」。(C)是嚇唬他，與「宥其罪」不符。", "skill": "填空題要「看後文找條件」：把後文提到的每個要素（宥罪、用長、使命）列出來，選項必須全部符合。"}], "difficulty": "中", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-30", "exam": "hk104", "nums": [30], "form": "單題", "img": "img/hk104-30.png", "source": "出處待查（唐代文人軼事筆記）", "author": "", "genre": "筆記小品", "types": ["人物情感", "文意推論"], "passage": "吳興僧皎然，工律詩。嘗謁韋蘇州，恐詩體不合，乃於舟中抒思，作古體十數篇為贄。韋公全不稱賞，皎然極失望。明日寫其舊製獻之，韋公吟誦，大加歎詠。因語皎然云：「師幾失聲名。何不但以所工見投，而猥希老夫之意。人各有所得，非猝能致。」皎然大服其鑒別之精。", "translation": "吳興的和尚皎然，擅長寫律詩。他曾去拜見韋應物，擔心自己的詩體不合韋應物的喜好，就在船上構思，寫了十幾篇古體詩當作見面禮。韋應物完全不稱讚，皎然非常失望。第二天，他抄了自己以前寫的作品獻上，韋應物一邊吟誦一邊大加讚歎。於是對皎然說：「大師差點失去了聲名。為什麼不直接拿你擅長的作品給我看，卻委屈自己去迎合老夫的心意呢？每個人各有自己的專長，不是倉促之間就能做到的。」皎然非常佩服韋應物鑑別詩作的精準。", "keywords": [{"w": "工", "m": "擅長"}, {"w": "謁", "m": "拜見"}, {"w": "贄", "m": "初次拜見尊長時所送之禮"}, {"w": "舊製", "m": "以前的作品"}, {"w": "幾", "m": "幾乎、差點"}, {"w": "但", "m": "只"}, {"w": "見投", "m": "投給我（見，指我）"}, {"w": "猥希", "m": "委屈自己以迎合"}, {"w": "猝", "m": "倉促"}], "questions": [{"n": 30, "stem": "根據這段文字，關於皎然與韋蘇州的敘述，下列何者正確？", "options": {"A": "韋蘇州覺得皎然名不符實", "B": "皎然臆測韋蘇州偏好古體", "C": "韋蘇州與皎然談論如何鑑賞詩作", "D": "皎然依從韋蘇州修改舊作，終獲讚賞"}, "answer": "B", "explain": "皎然擅長律詩，卻「恐詩體不合」，特地在船上寫古體詩去拜見——可見他自己猜想韋應物喜歡古體，(B)正確。(A)韋應物讀了舊作「大加歎詠」，說皎然差點「失聲名」，是肯定他的實力，並不認為他名不符實。(C)韋應物談的是「人各有所得」，勸他發揮所長，不是在討論鑑賞方法。(D)皎然獻上的是原本的「舊製」，並沒有依照韋應物的意見修改。", "skill": "注意表示心理的詞（恐、失望、大服），推出人物「以為」什麼；再對照實際結果，分辨猜測與事實。"}], "difficulty": "難", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-31", "exam": "hk104", "nums": [31], "form": "單題", "img": "img/hk104-31.png", "source": "沈括《夢溪筆談》", "author": "沈括", "genre": "筆記小品", "types": ["文意推論", "句意理解"], "passage": "世人以竹、木、牙、骨之類為「叫子」，置人喉中吹之，能作人言，謂之「嗓叫子」。嘗有病瘖者，為人所誣，煩冤無以自言。聽訟者試取叫子，令嗓之，作聲如傀儡子，粗能辨其一二，其冤獲伸。此亦可記也。", "translation": "世人用竹子、木頭、象牙、骨頭之類的材料做成「叫子」，放在人的喉嚨裡吹它，能發出像人說話的聲音，稱為「嗓叫子」。曾經有個生病啞了不能說話的人，被人誣告，滿腹冤屈卻沒辦法替自己辯白。審案的官員試著拿叫子讓他放在喉中吹，發出的聲音像木偶戲的聲音，大致能聽出一兩句意思，他的冤屈因此得到申雪。這件事也值得記下來。", "keywords": [{"w": "叫子", "m": "一種能吹出聲音的小器具"}, {"w": "瘖", "m": "嗓啞不能出聲"}, {"w": "誣", "m": "誣告、陷害"}, {"w": "聽訟者", "m": "審理案件的官員"}, {"w": "傀儡子", "m": "木偶"}, {"w": "粗", "m": "大略"}, {"w": "伸", "m": "申雪、洗清"}], "questions": [{"n": 31, "stem": "「世人以竹、木、牙、骨之類為『叫子』，置人喉中吹之，能作人言，謂之『嗓叫子』。嘗有病瘖者，為人所誣，煩冤無以自言。聽訟者試取叫子，令嗓之，作聲如傀儡子，粗能辨其一二，其冤獲伸。此亦可記也。」根據這段文字，下列有關「叫子」的敘述，何者無法明確得知？", "options": {"A": "能幫助因生病而不能說話的人發聲", "B": "製作叫子的材料有竹、木、牙、骨", "C": "古人製作叫子是為了協助聽訟者斷案", "D": "因置於喉部，能出人聲，故又稱嗓叫子"}, "answer": "C", "explain": "文中只說審案官員「試取叫子」幫啞巴發聲而破案，這是一次偶然的應用，並沒有說古人「製作叫子的目的」就是為了斷案，所以(C)無法得知。(A)病瘖者用叫子「粗能辨其一二」，可知。(B)「以竹、木、牙、骨之類為叫子」，可知。(D)「置人喉中吹之，能作人言，謂之嗓叫子」，可知。", "skill": "「無法得知」題要逐項回文中找證據；特別警覺選項把「一次用途」偷換成「製作目的」這類過度推論。"}], "difficulty": "中", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-45", "exam": "hk104", "nums": [45, 46], "form": "題組", "img": "img/hk104-45.png", "source": "《晏子春秋》", "author": "", "genre": "史傳人物", "types": ["人物情感", "文意推論"], "passage": "景公之時饑，晏子請為民發粟，公不許。當為路寢之臺，晏子令吏重其賃，遠其兆，徐其日而不趨。三年臺成而民振，故上悅乎遊，民足乎食。", "translation": "齊景公在位時發生饑荒，晏子請求開倉發放糧食救濟百姓，景公不答應。當時正要建造宮室的高臺，晏子就讓官吏提高工錢、延後完工期限，放慢工期而不催趕。三年後高臺完成，百姓也得到了救濟，所以國君滿意於遊樂，百姓也有足夠的糧食。", "keywords": [{"w": "饑", "m": "饑荒"}, {"w": "發粟", "m": "開倉發放糧食"}, {"w": "路寢", "m": "天子或諸侯的居室"}, {"w": "重其賃", "m": "提高工資"}, {"w": "遠其兆", "m": "延後完工期限"}, {"w": "徐", "m": "放慢"}, {"w": "趨", "m": "催促趕工"}, {"w": "振", "m": "通「賑」，得到救濟"}], "questions": [{"n": 45, "stem": "根據本文，景公的作為最適合以下列何者來形容？", "options": {"A": "短視近利，弄巧成拙", "B": "徵收重稅，與民爭利", "C": "誤信讒言，疏遠賢臣", "D": "圖己之樂，不恤民生"}, "answer": "D", "explain": "饑荒時景公不肯開倉救民，卻要蓋自己遊樂的高臺，只顧自己享樂、不體恤百姓，(D)正確。(A)景公並沒有因此弄巧成拙，臺最後也蓋成了。(B)文中沒有提到徵收重稅。(C)文中沒有讒言，晏子也沒有被疏遠。", "skill": "只看景公自己的作為（不許發粟、建臺），用對比（民饑 vs. 建臺享樂）歸納他的態度。"}, {"n": 46, "stem": "本文呈現了晏子在政治上的哪一種智慧？", "options": {"A": "無為而治，讓人民得以休養生息", "B": "知所變通，化解上下利益的衝突", "C": "能集眾智，不獨斷而行，致使政通人和", "D": "利用緩兵之計，導引君王注意民生需求"}, "answer": "B", "explain": "景公不肯直接發糧，晏子就換個方式：利用建臺工程提高工資、延長工期，讓百姓靠做工得到救濟；結果「上悅乎遊，民足乎食」，國君和百姓兩方的需求都滿足了——這是懂得變通、化解上下利益衝突的智慧，(B)正確。(A)晏子積極安排工程，不是無為。(C)文中沒有集合眾人意見。(D)晏子拖延工期是為了讓百姓多賺工錢，並不是要引導君王注意民生，景公的想法也沒有改變。", "skill": "看結果句「上悅乎遊，民足乎食」——兩方都滿意，就是「化解衝突」；再回推晏子用的是「轉個方式」而非正面對抗。"}], "difficulty": "中", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk104-47", "exam": "hk104", "nums": [47, 48], "form": "題組", "img": "img/hk104-47.png", "source": "司馬光《資治通鑑》", "author": "司馬光", "genre": "史傳人物", "types": ["字詞解釋", "文意推論", "人物情感"], "passage": "燕泰山太守賈堅屯山茌，荀羨引兵擊之，堅所將才七百餘人，羨兵十倍於堅。堅將出戰，諸將皆曰：「衆少，不如固守。」堅曰：「固守亦不能免，不如戰也。」遂出戰，身先士卒，殺羨兵千餘人，復還入城。羨進攻之，堅歎曰：「吾自結髮，志立功名，而每值窮阨，豈非命乎！與其屈辱而生，不若守節而死。」乃謂將士曰：「今危困，計無所設，卿等可去，吾將止死。」將士皆泣曰：「府君不出，衆亦俱死耳。」堅曰：「今當爲卿曹決鬥，若勢不能支，卿等可去，勿復顧我也！」乃開門直出。羨兵四集，堅立馬橋上，左右射之，皆應弦而倒。羨兵衆多，從塹下斫橋，堅人馬俱陷，生擒之，遂拔山茌。", "translation": "前燕的泰山太守賈堅駐守山茌，東晉的荀羨帶兵攻打他。賈堅率領的士兵只有七百多人，荀羨的兵力是他的十倍。賈堅準備出城作戰，將領們都說：「我們人少，不如堅守城池。」賈堅說：「堅守也免不了失敗，不如出戰。」於是出城作戰，親自衝在士兵前面，殺了荀羨的士兵一千多人，又回到城中。荀羨繼續進攻，賈堅嘆息說：「我從成年起就立志建立功名，卻總是遇到困境，難道不是命嗎！與其受辱而活，不如守住節操而死。」於是對將士們說：「現在處境危急，已經想不出辦法了，你們可以離開，我將留在這裡死守。」將士們都哭著說：「太守您不走，我們也一起死罷了。」賈堅說：「現在我要為你們決一死戰，如果情勢撐不住了，你們就離開，不要再顧念我！」於是打開城門直衝出去。荀羨的軍隊從四面聚集過來，賈堅騎馬站在橋上，向左右兩邊射箭，敵兵都隨著弓弦聲倒下。荀羨兵多，從壕溝下砍斷橋梁，賈堅連人帶馬一起陷落，被活捉，荀羨於是攻下山茌。", "keywords": [{"w": "屯", "m": "駐守"}, {"w": "所將", "m": "所率領的（士兵）"}, {"w": "固守", "m": "堅守"}, {"w": "身先士卒", "m": "親自衝在士兵前面"}, {"w": "結髮", "m": "古代男子成年束髮，指剛成年時"}, {"w": "窮阨", "m": "困境"}, {"w": "止死", "m": "留下來死守"}, {"w": "府君", "m": "對太守的尊稱，指賈堅"}, {"w": "卿曹", "m": "你們"}, {"w": "左右", "m": "向左右兩邊"}, {"w": "斫", "m": "砍"}, {"w": "拔", "m": "攻下"}], "questions": [{"n": 47, "stem": "下列文句「」中語詞的意義，何者說明正確？", "options": {"A": "吾自「結髮」，志立功名：襁褓", "B": "「府君」不出，衆亦俱死耳：荀羨", "C": "今當爲「卿曹」決鬥：你們", "D": "堅立馬橋上，「左右」射之：隨從"}, "answer": "C", "explain": "「卿曹」是賈堅對將士的稱呼，意思是「你們」，(C)正確。(A)「結髮」指男子成年束髮，即剛成年時，不是嬰兒時期的「襁褓」。(B)「府君」是將士對太守的尊稱，指賈堅，不是敵將荀羨（將士不會勸敵將）。(D)「左右射之」是賈堅自己向左右兩邊射箭，所以下文說敵兵「皆應弦而倒」，不是指隨從。", "skill": "判斷稱謂詞時先確認「誰在對誰說話」；判斷「左右」這類多義詞時，看後文的結果（應弦而倒）是誰造成的。"}, {"n": 48, "stem": "根據本文，關於賈堅與荀羨攻守的過程，下列敘述何者正確？", "options": {"A": "賈堅堅持為城守節，力勸眾將死守勿降", "B": "荀羨設法破壞橋梁，致使賈堅人馬墜落被擒", "C": "賈堅佯攻使諸將趁隙出城求援，自己固守城池以待", "D": "荀羨引兵攻擊，山茌將士畏怯，唯賈堅孤身出城迎戰"}, "answer": "B", "explain": "文末「羨兵衆多，從塹下斫橋，堅人馬俱陷，生擒之」——荀羨派兵從壕溝下砍斷橋梁，賈堅連人帶馬陷落被俘，(B)正確。(A)賈堅反而勸將士「可去」（可以離開），並沒有力勸眾將死守。(C)賈堅是真的出戰，也沒有派人出城求援。(D)將士們並不畏怯，還哭著說「府君不出，衆亦俱死耳」；第一次出戰時賈堅也是帶兵「身先士卒」。", "skill": "敘事題依時間順序整理事件（出戰→回城→勸將士離去→出門死戰→橋斷被擒），再逐項比對選項的人物與行為。"}], "difficulty": "難", "label": "104年會考", "year": 104, "kind": "會考"}, {"id": "hk105-10", "exam": "hk105", "nums": [10], "form": "單題", "img": "img/hk105-10.png", "source": "出處待查", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "君子如抱美玉而深藏不市，小人則以石為玉而又炫之。", "translation": "君子就像懷抱美玉卻深深收藏、不拿出去賣弄；小人卻把石頭當作美玉，還要四處炫耀。", "keywords": [{"w": "市", "m": "賣，引申為拿出來展示賣弄"}, {"w": "以石為玉", "m": "把石頭當成玉，指沒有真才實學卻自以為有"}, {"w": "炫", "m": "炫耀"}], "questions": [{"n": 10, "stem": "「君子如抱美玉而深藏不市，小人則以石為玉而又炫之。」根據這句話，君子不同於小人的特質是下列何者？", "options": {"A": "臨財不苟", "B": "真實坦率", "C": "見多識廣", "D": "沉潛含蓄"}, "answer": "D", "explain": "「美玉」比喻真才實學。君子有才華卻「深藏不市」，不愛表現；小人沒什麼本事卻「炫之」。兩者的差別在於是否含蓄內斂，(D)正確。(A)「市」雖有買賣義，但這裡不是在談錢財。(B)句中並未比較誠實與否。(C)句中沒有談見識多寡。", "skill": "先把比喻還原（美玉＝才德、市／炫＝展示炫耀），再找出君子與小人「相反」的那一點。"}], "difficulty": "易", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-19", "exam": "hk105", "nums": [19], "form": "單題", "img": "img/hk105-19.png", "source": "出處待查（古詩）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "北風吹，吹我庭前柏樹枝。樹堅不怕風吹動，節操稜稜還自持。冰霜歷盡心不移，況復陽和景漸宜。閒花野草尚葳蕤，風吹柏枝將何為？北風吹，能幾時！", "translation": "北風吹啊，吹動我庭院前的柏樹枝。柏樹堅強，不怕風吹搖動，節操威嚴耿直，依然自我持守。經歷了所有的冰霜，心志始終不變，何況溫暖的春天景色已漸漸變好。連閒花野草都還長得茂盛，北風吹柏樹枝又能怎樣呢？北風吹啊，又能吹多久！", "keywords": [{"w": "稜稜", "m": "威嚴耿直"}, {"w": "自持", "m": "自我約束、堅守"}, {"w": "況復", "m": "何況又"}, {"w": "陽和", "m": "溫暖的春天氣候"}, {"w": "葳蕤", "m": "草木茂盛的樣子"}, {"w": "將何為", "m": "又能怎麼樣"}], "questions": [{"n": 19, "stem": "「北風吹，吹我庭前柏樹枝。樹堅不怕風吹動，節操稜稜還自持。冰霜歷盡心不移，況復陽和景漸宜。閒花野草尚葳蕤，風吹柏枝將何為？北風吹，能幾時！」詩中事物所象徵的意涵，下列說明何者最恰當？", "options": {"A": "北風——心中的疑慮", "B": "柏樹——國家的運勢", "C": "冰霜——隱逸的心志", "D": "陽和——轉好的境況"}, "answer": "D", "explain": "柏樹歷盡冰霜而不變心，「況復陽和景漸宜」——溫暖的天氣漸漸來了，象徵困境將過、處境好轉，所以末句說「北風吹，能幾時！」，(D)正確。(A)北風是吹打柏樹的外在壓力、逆境，不是心中疑慮。(B)柏樹「節操稜稜還自持」，象徵堅守節操的人，不是國運。(C)冰霜是苦難磨練，不是隱逸之志。", "skill": "詠物詩先分「主角」（柏樹＝堅貞的人）與「環境」（北風、冰霜＝逆境；陽和＝順境），再判斷象徵。"}], "difficulty": "中", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-22", "exam": "hk105", "nums": [22], "form": "單題", "img": "img/hk105-22.png", "source": "朱熹〈大學章句序〉前引程子語", "author": "朱熹", "genre": "書信序跋", "types": ["文意推論", "文化常識"], "passage": "程子曰：「《大學》，孔氏之遺書，而初學入德之門也。」於今可見古人為學次第者，獨賴此篇之存，而《論》、《孟》次之。學者必由是而學焉，則庶乎其不差矣。", "translation": "程子說：「《大學》是孔子留下的書，是初學者進入德行修養的門徑。」到今天還能看出古人求學先後次序的，只靠這一篇保存下來，其次才是《論語》、《孟子》。學習的人一定要從這裡開始學，大概就不會出錯了。", "keywords": [{"w": "遺書", "m": "前人留下的著作"}, {"w": "入德之門", "m": "進入德行修養的門徑"}, {"w": "次第", "m": "次序、先後"}, {"w": "獨賴", "m": "只依靠"}, {"w": "由是", "m": "從這裡"}, {"w": "庶乎", "m": "大概、差不多"}], "questions": [{"n": 22, "stem": "朱熹云：「程子曰：『《大學》，孔氏之遺書，而初學入德之門也。』於今可見古人為學次第者，獨賴此篇之存，而《論》、《孟》次之。學者必由是而學焉，則庶乎其不差矣。」根據這段文字，下列何者最接近朱熹的看法？", "options": {"A": "《大學》的成書年代早於《論》、《孟》", "B": "《大學》的內容遠較《論》、《孟》來得深奧", "C": "儒家《論》、《孟》的思想，是以《大學》為本衍生而出", "D": "欲知古人為學修德的次第，首推《大學》，其次《論》、《孟》"}, "answer": "D", "explain": "文中說要看出古人「為學次第」，「獨賴此篇（大學）之存，而《論》、《孟》次之」——首推《大學》，其次《論語》《孟子》，(D)正確。(A)「次之」是重要性、學習順序上的其次，不是成書年代。(B)《大學》是「初學入德之門」，是入門書，不是更深奧。(C)文中沒說《論》《孟》是從《大學》衍生出來的。", "skill": "釐清「次之」比較的是什麼（學習次第的重要性），避免被偷換成年代、難度、源流。"}], "difficulty": "中", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-24", "exam": "hk105", "nums": [24], "form": "單題", "img": "img/hk105-24.png", "source": "《孝經‧諫諍章》；選項含《三國演義》、《世說新語》、《史記‧張釋之列傳》等", "author": "", "genre": "經典語錄", "types": ["字詞解釋"], "passage": "士有諍友，則身不離於令名；父有諍子，則身不陷於不義。　(A)賞罰可用，則禁「令」可立，而治道具矣　(B)孔明傳「令」：諸軍各守城鋪，如有妄行出入，立斬　(C)先生神情機警，詞藻遒逸，少有「令」望，為當世所推　(D)此人親驚吾馬，吾馬賴柔和，「令」他馬，固不敗傷我乎", "translation": "讀書人有敢直言勸諫的朋友，自身就不會失去美好的名聲；父親有敢直言勸諫的兒子，自身就不會陷入不義。(A)賞罰能夠運用，禁令就能建立，治國之道就完備了。(B)孔明傳下命令：各軍守住城上崗哨，如有擅自出入的，立刻斬首。(C)先生神情機警，文辭剛健飄逸，年少時就有美好的聲望，被當時的人推崇。(D)這個人驚了我的馬，幸好我的馬性情溫和，假使是別的馬，難道不會把我摔傷嗎？", "keywords": [{"w": "諍友", "m": "能直言勸諫的朋友"}, {"w": "令名", "m": "美好的名聲（令＝美好）"}, {"w": "禁令", "m": "禁止的命令"}, {"w": "令望", "m": "美好的聲望"}, {"w": "令（D）", "m": "假使"}], "questions": [{"n": 24, "stem": "「士有諍友，則身不離於令名；父有諍子，則身不陷於不義。」句中「令」字的意義，與下列哪一個「令」字相同？", "options": {"A": "賞罰可用，則禁「令」可立，而治道具矣", "B": "孔明傳「令」：諸軍各守城鋪，如有妄行出入，立斬", "C": "先生神情機警，詞藻遒逸，少有「令」望，為當世所推", "D": "此人親驚吾馬，吾馬賴柔和，「令」他馬，固不敗傷我乎"}, "answer": "C", "explain": "「令名」的「令」是形容詞「美好的」，「令名」＝好名聲。(C)「令望」＝美好的聲望，意思相同。(A)「禁令」、(B)「傳令」都是名詞「命令」。(D)「令他馬」是「假使是別的馬」，作連詞「假使」。", "skill": "看「令」後面接什麼：接名詞（名、望、聞、郎）多是「美好的」；單獨當動作對象多是「命令」；放在句首帶出假設的是「假使」。"}], "difficulty": "中", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-27", "exam": "hk105", "nums": [27], "form": "單題", "img": "img/hk105-27.png", "source": "蘇軾〈滿庭芳〉", "author": "蘇軾", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "思量、能幾許？憂愁風雨，一半相妨。又何須，抵死說短論長。幸對清風皓月，苔茵展、雲幕高張。江南好，千鍾美酒，一曲滿庭芳。", "translation": "仔細想想，人生能有多少時光？憂愁和風雨，就妨礙了一半。又何必拚命地議論是非長短呢？幸好面對清風明月，青苔像墊褥般鋪展，白雲像帳幕高高張開。江南真好，有千鍾美酒，再唱一曲〈滿庭芳〉。", "keywords": [{"w": "思量", "m": "仔細想想"}, {"w": "幾許", "m": "多少"}, {"w": "相妨", "m": "妨礙"}, {"w": "抵死", "m": "拚命、竭力"}, {"w": "說短論長", "m": "議論是非長短"}, {"w": "苔茵", "m": "如墊褥般的青苔"}, {"w": "千鍾", "m": "極多（鍾為容量單位）"}], "questions": [{"n": 27, "stem": "「思量、能幾許？憂愁風雨，一半相妨。又何須，抵死說短論長。幸對清風皓月，苔茵展、雲幕高張。江南好，千鍾美酒，一曲滿庭芳。」作者在這段文字中展現出的生命態度，與下列何者最接近？", "options": {"A": "生於憂患，死於安樂", "B": "隱遁出世，成道求仙", "C": "豁達自適，及時行樂", "D": "縱論時局，憂以天下"}, "answer": "C", "explain": "作者感嘆人生短暫、憂愁風雨又占去一半，何必拚命爭論是非；不如欣賞清風明月，飲酒唱歌——放下紛爭、享受眼前，是豁達自適、及時行樂的態度，(C)正確。(A)是要人在憂患中奮發，與詞意相反。(B)詞中享受山水美酒，並沒有求仙修道。(D)作者說「何須說短論長」，正是不想議論是非時局。", "skill": "抓住詞中的「否定」（何須說短論長）與「肯定」（幸對清風皓月、美酒一曲），兩者合起來就是作者的態度。"}], "difficulty": "中", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-30", "exam": "hk105", "nums": [30], "form": "單題", "img": "img/hk105-30.png", "source": "出處待查（清人論文之語）", "author": "", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "人之學文，其功力所能至者，陳理義必明當，布置取捨、繁簡廉肉不失法，吐辭雅馴不蕪而已。古今至此者，蓋不數數得。", "translation": "人們學習寫文章，靠功夫能做到的，就是陳述道理一定要清楚恰當，安排結構、取捨材料、詳略疏密不違背法度，用詞典雅通順而不雜亂罷了。從古到今能做到這樣的，大概並不常見。", "keywords": [{"w": "功力", "m": "努力的功夫"}, {"w": "明當", "m": "清楚恰當"}, {"w": "布置", "m": "安排結構"}, {"w": "廉肉", "m": "指文章之疏略與豐腴"}, {"w": "雅馴", "m": "典雅通順"}, {"w": "蕪", "m": "雜亂"}, {"w": "數數", "m": "常常"}], "questions": [{"n": 30, "stem": "「人之學文，其功力所能至者，陳理義必明當，布置取捨、繁簡廉肉不失法，吐辭雅馴不蕪而已。古今至此者，蓋不數數得。」這段話主要在說明下列何者？", "options": {"A": "好文章所需具備的條件", "B": "說理議論文的創作步驟", "C": "古今學文者的文章樣貌", "D": "文體形式的運用與取捨"}, "answer": "A", "explain": "文中列出寫文章應做到的三件事：說理明當、結構詳略合法度、用辭雅馴不蕪，並說古今能做到的人不多——這些是好文章的條件，(A)正確。(B)列舉的是標準而非先後步驟，也不限於議論文。(C)末句只說做到的人少，重點不是描述古今文章的樣貌。(D)「布置取捨」是指內容材料的安排，不是文體形式。", "skill": "遇到「A、B、C而已」的列舉句，先把列舉項目整理成清單，再問這份清單是「條件」「步驟」還是「現象」。"}], "difficulty": "中", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-31", "exam": "hk105", "nums": [31], "form": "單題", "img": "img/hk105-31.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "夫投膠以變濁，不如澄其源而濁變之愈也；揚湯以止沸，不如絕其薪而沸止之速也。是以勞心於服遠者，莫若修近而其遠自來；多方以救失者，莫若改行而其失自去。", "translation": "投放阿膠來使混濁的水變清，不如澄清水源，讓混濁自然消失來得好；把熱水舀起來再倒回去以制止沸騰，不如抽掉柴火，讓沸騰停止得更快。所以費盡心思去使遠方的人歸服，不如修治好身邊的事，遠方的人自然會來；用各種方法去補救過失，不如改正行為，過失自然就消除。", "keywords": [{"w": "膠", "m": "阿膠，據說可使濁水變清"}, {"w": "澄", "m": "使清澈"}, {"w": "愈", "m": "較好、勝過"}, {"w": "揚湯", "m": "舀起熱水再倒下"}, {"w": "薪", "m": "柴火"}, {"w": "服遠", "m": "使遠方的人歸服"}, {"w": "莫若", "m": "不如"}], "questions": [{"n": 31, "stem": "「夫投膠以變濁，不如澄其源而濁變之愈也；揚湯以止沸，不如絕其薪而沸止之速也。是以勞心於服遠者，莫若修近而其遠自來；多方以救失者，莫若改行而其失自去。」根據這段文字，下列何者最符合作者的觀點？", "options": {"A": "投膠變濁，勝於澄源", "B": "揚湯止沸，不如絕薪", "C": "勞心服遠，近者自來", "D": "多方救失，其失自去"}, "answer": "B", "explain": "作者主張解決問題要從根本著手：「揚湯以止沸，不如絕其薪」，(B)正確。(A)與原文相反，原文說投膠「不如」澄源。(C)原文是「修近」而「遠自來」，選項把「勞心服遠」當成方法，又說「近者自來」，都錯了。(D)原文是「改行」而「其失自去」，「多方救失」是作者否定的做法。", "skill": "「A不如B」句型中，B才是作者肯定的；逐項檢查選項把哪一半配上了哪個結果，常見陷阱是把被否定的做法接上好的結果。"}], "difficulty": "中", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-32", "exam": "hk105", "nums": [32], "form": "單題", "img": "img/hk105-32.png", "source": "歐陽脩〈歸田錄〉", "author": "歐陽脩", "genre": "筆記小品", "types": ["句意理解", "文化常識"], "passage": "蔡君謨既為余書〈集古錄目序〉刻石，其字尤精勁，為世所珍。今饋以鼠鬚栗尾筆、銅綠筆格、大小龍茶、惠山泉等物為潤筆。", "translation": "蔡襄替我書寫〈集古錄目序〉以便刻在石碑上，他的字特別精妙有力，被世人珍視。現在我送他鼠鬚栗尾筆、銅綠筆架、大小龍團茶、惠山泉水等東西作為酬謝。", "keywords": [{"w": "書", "m": "書寫"}, {"w": "精勁", "m": "精妙有力"}, {"w": "珍", "m": "珍視"}, {"w": "饋", "m": "贈送"}, {"w": "筆格", "m": "筆架"}, {"w": "潤筆", "m": "請人寫字作文的酬勞"}], "questions": [{"n": 32, "stem": "歐陽脩：「蔡君謨既為余書〈集古錄目序〉刻石，其字尤精勁，為世所珍。今饋以鼠鬚栗尾筆、銅綠筆格、大小龍茶、惠山泉等物為潤筆。」根據這段文字，下列敘述何者正確？", "options": {"A": "蔡君謨文筆已甚精勁，經歐陽脩稍加潤飾，即成世所稱道的佳文", "B": "蔡君謨為〈集古錄目序〉書刻石，歐陽脩贈予許多物品以為酬謝", "C": "為作〈集古錄目序〉，歐陽脩耗費財物蒐求蔡君謨珍奇稀有的刻石", "D": "刻寫〈集古錄目序〉需使用鼠鬚栗尾筆、銅綠筆格，方成上乘之作"}, "answer": "B", "explain": "蔡君謨替歐陽脩寫〈集古錄目序〉以便刻石，歐陽脩送上筆、筆架、茶、泉水作為「潤筆」（酬勞），(B)正確。(A)「精勁」指蔡君謨的字（書法），不是文筆；「潤筆」是酬勞，不是潤飾文章。(C)序是歐陽脩作的，是請蔡君謨寫字，不是蒐求刻石。(D)這些物品是酬禮，不是刻寫時必需的工具。", "skill": "留意容易望文生義的詞：「書」是寫字、「潤筆」是酬勞；先弄清楚「誰替誰做了什麼、誰送誰什麼」。"}], "difficulty": "中", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-34", "exam": "hk105", "nums": [34], "form": "單題", "img": "img/hk105-34.png", "source": "司馬遷《史記‧廉頗藺相如列傳》", "author": "司馬遷", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "趙以數困於秦兵，趙王思復得廉頗，廉頗亦思復用於趙。趙王使使者視廉頗尚可用否。廉頗之仇郭開多與使者金，令毀之。趙使者既見廉頗，廉頗為之一飯斗米，肉十斤，被甲上馬，以示尚可用。趙使還報王曰：「廉將軍雖老，尚善飯。然與臣坐，頃之三遺矢矣。」趙王以為老，遂不召。", "translation": "趙國因為屢次被秦兵圍困，趙王想再起用廉頗，廉頗也想再為趙國效力。趙王派使者去看廉頗還能不能任用。廉頗的仇人郭開給了使者很多錢，要他說廉頗的壞話。趙國使者見到廉頗後，廉頗當著他的面一頓飯吃了一斗米、十斤肉，又披上鎧甲上馬，表示自己還能任用。使者回去向趙王報告說：「廉將軍雖然老了，飯量還很好。但是和我坐在一起，一會兒就拉了三次屎。」趙王認為廉頗老了，就不召他回來。", "keywords": [{"w": "數", "m": "屢次"}, {"w": "困", "m": "圍困"}, {"w": "毀", "m": "說壞話、詆毀"}, {"w": "被", "m": "通「披」，穿上"}, {"w": "還報", "m": "回去報告"}, {"w": "頃之", "m": "一會兒"}, {"w": "遺矢", "m": "排便（矢通「屎」）"}], "questions": [{"n": 34, "stem": "根據這段文字，廉頗不復重用的原因，最可能是下列何者？", "options": {"A": "不知禮數，席間得罪使者", "B": "老態畢現，難以征戰沙場", "C": "趙王憫其年老，賜歸還鄉", "D": "郭開挾怨報復，陰謀陷害"}, "answer": "D", "explain": "廉頗的仇人郭開用重金收買使者「令毀之」；廉頗其實當面吃得多、披甲上馬，證明自己還能打仗，使者卻捏造「三遺矢」的說法，讓趙王誤以為廉頗老了——真正原因是郭開挾怨陷害，(D)正確。(A)文中沒有廉頗失禮的情節。(B)「老態」是使者編造的，廉頗實際表現很好。(C)趙王只是「不召」，沒有因憐憫而賜他還鄉。", "skill": "分清「真實表現」與「轉述的話」：使者已被收買，他的報告不可信；往前找埋下的伏筆（多與使者金，令毀之）。"}], "difficulty": "難", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-35", "exam": "hk105", "nums": [35], "form": "單題", "img": "img/hk105-35.png", "source": "出處待查（題畫詩）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "主旨寓意"], "passage": "呵凍提篙手未蘇，滿船涼月雪模糊。畫家不解漁家苦，好作寒江釣雪圖。", "translation": "漁夫對著凍僵的手呵氣，拿起船篙，雙手卻還沒暖和靈活；滿船清冷的月光，雪花飄得模模糊糊。畫家不懂漁家的辛苦，偏偏喜歡畫〈寒江釣雪圖〉。", "keywords": [{"w": "呵凍", "m": "對凍僵的手呵氣取暖"}, {"w": "篙", "m": "撐船的竹竿"}, {"w": "手未蘇", "m": "雙手尚未活絡"}, {"w": "不解", "m": "不了解"}, {"w": "好", "m": "喜歡"}], "questions": [{"n": 35, "stem": "「呵凍提篙手未蘇，滿船涼月雪模糊。畫家不解漁家苦，好作寒江釣雪圖。」本詩的主旨與下列何者最接近？", "options": {"A": "對於漁民生活的疾苦，作者寄予關切同情", "B": "漁民雖然生活艱辛，卻大多能夠苦中作樂", "C": "畫家擅於從藝術角度來捕捉漁民的閒情逸趣", "D": "畫家透過寫實的筆法來呈現漁民生活的甘苦"}, "answer": "A", "explain": "前兩句寫漁民在寒夜雪中手凍僵仍要撐船的辛苦；後兩句批評畫家「不解漁家苦」，只把寒江釣雪當成風雅畫題。作者是在同情漁民的疾苦，(A)正確。(B)詩中沒有寫漁民苦中作樂。(C)作者是在批評畫家把苦難美化，不是稱讚。(D)畫家「不解漁家苦」，並沒有寫實呈現甘苦。", "skill": "注意前後兩半的對比：前半是漁民的實況（苦），後半是畫家的想像（雅），作者站在哪一邊就是主旨。"}], "difficulty": "易", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-45", "exam": "hk105", "nums": [45, 46], "form": "題組", "img": "img/hk105-45.png", "source": "田汝成《西湖遊覽志餘》", "author": "田汝成", "genre": "筆記小品", "types": ["文意推論", "寫作手法"], "passage": "高宗嘗宴大臣，見張循王持扇，有玉孩兒扇墜，上識是舊物，昔往四明，誤墜於水，屢尋不獲，乃詢於張循王，對曰：「臣從清河坊鋪家買得。」召問鋪家，云：「得於提籃人。」復遣問，回奏云：「於候潮門外陳宅廚娘處買得。」又遣問廚娘，云：「破黃花魚腹中得之。」奏聞，上大悅，以為失物復還之兆。鋪家及提籃人補校尉，廚娘封孺人，張循王賞賜甚厚。", "translation": "宋高宗曾宴請大臣，看見張循王拿著扇子，扇上有個玉孩兒扇墜，高宗認出這是自己的舊物——從前到四明時，不小心掉進水裡，多次尋找都沒找到。於是詢問張循王，張循王回答：「我是從清河坊的店家買來的。」召店家來問，店家說：「是從提籃叫賣的小販那裡得到的。」又派人去問，回報說：「是在候潮門外陳家廚娘那裡買到的。」再派人去問廚娘，廚娘說：「是剖開黃花魚，在魚肚子裡得到的。」把這些上奏後，高宗非常高興，認為這是失去的東西（失去的國土）將要回來的吉兆。於是店家和小販都補授校尉官職，廚娘被封為孺人，張循王得到很豐厚的賞賜。", "keywords": [{"w": "嘗", "m": "曾經"}, {"w": "上", "m": "皇上，指宋高宗"}, {"w": "識", "m": "認出"}, {"w": "詢", "m": "詢問"}, {"w": "遣", "m": "派人"}, {"w": "奏聞", "m": "向皇帝報告"}, {"w": "兆", "m": "預兆"}, {"w": "孺人", "m": "古代婦女的封號"}], "questions": [{"n": 45, "stem": "根據本文的內容，下列敘述何者正確？", "options": {"A": "張循王尋回皇上舊物，特意奉還", "B": "高宗遣鋪家尋找失物，屢尋不獲", "C": "廚娘之語，可佐證扇墜曾落水中", "D": "廚娘得到扇墜，售予清河坊鋪家"}, "answer": "C", "explain": "扇墜當年「誤墜於水」，廚娘說是「破黃花魚腹中得之」——被魚吞下，正好證明扇墜確實曾落入水中，(C)正確。(A)張循王是自己買來使用，被高宗認出，並非特意奉還。(B)「屢尋不獲」是高宗當年自己找，不是派鋪家找。(D)廚娘賣給的是「提籃人」，提籃人再轉給鋪家。", "skill": "把物品流向畫成鏈條：水→魚→廚娘→提籃人→鋪家→張循王→被高宗認出，再逐項核對選項的環節。"}, {"n": 46, "stem": "關於本文的寫作方式，下列敘述何者正確？", "options": {"A": "藉對話凸顯故事中所有人物的個性", "B": "以諷喻手法，勸告世人當拾金不昧", "C": "以抽絲剝繭的方式，層層鋪敘情節", "D": "文末未提故事結局，製造懸疑效果"}, "answer": "C", "explain": "故事從張循王→鋪家→提籃人→廚娘一路追問，像剝繭抽絲般層層往前追溯，最後揭開扇墜在魚腹中的真相，(C)正確。(A)對話主要用來交代線索，並沒有凸顯每個人的個性。(B)文中沒有勸人拾金不昧，也無諷喻。(D)文末有明確結局：高宗大悅，眾人受賞。", "skill": "寫作手法題先看結構：連續出現「召問、復遣問、又遣問」，就是逐層追溯的敘事方式。"}], "difficulty": "中", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk105-47", "exam": "hk105", "nums": [47, 48], "form": "題組", "img": "img/hk105-47.png", "source": "《仙傳拾遺》、酈道元《水經注》（改寫）", "author": "", "genre": "筆記小品", "types": ["虛詞句式", "文意推論"], "passage": "王次仲者，以為世之篆文，工多而用寡，難以速就。四海多事，筆札為先，乃變篆籀之體為隸書。秦始皇以次仲所易文簡，其功利於人而召之，三徵入秦，不至。次仲履真懷道，窮數術之美。始皇怒其不恭，令檻車送之。次仲化為大鳥，翻飛出車外，落二翮於峰巒，故有大翮、小翮之名矣。", "translation": "王次仲認為世上通行的篆文，書寫費工卻不實用，很難快速寫成。天下事務繁多，公文書信最為優先，於是把篆籀的字體改成隸書。秦始皇因為王次仲改的字體簡便，功用有利於人，就召他前來，三次徵召他入秦，他都不去。王次仲修習道家之學，精通天文曆法占卜等學問的奧妙。秦始皇惱怒他不恭敬，下令用囚車押送他。王次仲變成一隻大鳥，飛出囚車外，在山峰上落下兩根羽毛，所以有大翮山、小翮山的名稱。", "keywords": [{"w": "工多而用寡", "m": "費工多而實用少"}, {"w": "就", "m": "完成"}, {"w": "筆札", "m": "公文書信"}, {"w": "篆籀", "m": "周、秦間通行之字體"}, {"w": "易", "m": "改變"}, {"w": "徵", "m": "徵召"}, {"w": "履真懷道", "m": "修習道家之學"}, {"w": "數術", "m": "天文、曆法、占卜等學問"}, {"w": "檻車", "m": "囚車"}, {"w": "翮", "m": "羽毛的莖，借指羽毛"}], "questions": [{"n": 47, "stem": "下列文句（　）中所應填入的主語，何者正確？", "options": {"A": "（　）工多而用寡——秦始皇", "B": "（　）乃變篆籀之體為隸書——筆札", "C": "（　）三徵入秦——王次仲", "D": "（　）落二翮於峰巒——大鳥"}, "answer": "D", "explain": "「次仲化為大鳥，翻飛出車外，落二翮於峰巒」——落下兩根羽毛的是王次仲變成的大鳥，(D)正確。(A)「工多而用寡」的主語是「篆文」。(B)改篆為隸的是王次仲，「筆札」是他重視的事務。(C)「三徵入秦」是秦始皇三次徵召，主語是秦始皇；王次仲是被徵召而「不至」的人。", "skill": "省略主語的句子，要往前找最近的動作者，並問「這個動作合理是誰做的」：徵召的一定是君主，被徵召的才是臣民。"}, {"n": 48, "stem": "根據本文內容，下列敘述何者正確？", "options": {"A": "次仲因擅自改革文字觸怒始皇，而遭逮捕", "B": "始皇過於急功好利，故次仲出走轉而修道", "C": "次仲將篆籀之體改為隸書，方便世人使用", "D": "仙鳥中始皇之箭，落羽成大翮、小翮二山"}, "answer": "C", "explain": "次仲認為篆文「工多而用寡，難以速就」，所以改為隸書，秦始皇也認為「其功利於人」——是為了方便世人使用，(C)正確。(A)始皇生氣是因為他三徵不至、「不恭」，不是因為改革文字（始皇反而肯定這件事）。(B)文中沒有說始皇急功好利，也沒說次仲因此出走。(D)文中沒有射箭情節，羽毛是大鳥飛出時自己落下的。", "skill": "找出事件的因果：改字的原因（篆文不便）、被召的原因（利於人）、被捕的原因（不恭），逐一核對選項的「因為」。"}], "difficulty": "中", "label": "105年會考", "year": 105, "kind": "會考"}, {"id": "hk106-5", "exam": "hk106", "nums": [5], "form": "單題", "img": "img/hk106-5.png", "source": "《論語‧學而》、彭端淑〈為學一首示子姪〉等", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "(A)學而時習之，不亦說乎　(B)凡事不宜刻，若讀書則不可不刻　(C)不自限其昏與庸而力學不倦，自立者也　(D)吾材之庸，不逮人也。旦旦而學之，久而不怠焉", "translation": "(A)學了之後按時溫習，不也是很快樂的事嗎？(B)凡事都不宜太苛刻，但讀書卻不能不嚴格要求自己。(C)不因自己的愚昧平庸而限制自己，努力學習不倦怠，這是能自我成就的人。(D)我的資質平庸，比不上別人；但每天不斷學習，長久下來也不懈怠。", "keywords": [{"w": "時習", "m": "按時溫習"}, {"w": "說", "m": "通「悅」，快樂"}, {"w": "刻", "m": "嚴格、苛求"}, {"w": "昏與庸", "m": "愚昧與平庸"}, {"w": "逮", "m": "及、比得上"}, {"w": "旦旦", "m": "天天"}, {"w": "怠", "m": "懈怠"}], "questions": [{"n": 5, "stem": "下列文句，何者旨在強調學習的樂趣？", "options": {"A": "學而時習之，不亦說乎", "B": "凡事不宜刻，若讀書則不可不刻", "C": "不自限其昏與庸而力學不倦，自立者也", "D": "吾材之庸，不逮人也。旦旦而學之，久而不怠焉"}, "answer": "A", "explain": "(A)「不亦說乎」的「說」通「悅」，學習並時常溫習是快樂的事，強調學習的樂趣，正確。(B)強調讀書要嚴格要求自己。(C)強調不自我設限、努力不倦才能自立。(D)強調資質平庸也要天天學、持之以恆。(B)(C)(D)都在講學習的態度或毅力，不是樂趣。", "skill": "找出每句的「情緒詞／評價詞」：說（悅）＝樂趣；刻、力學不倦、不怠＝態度與毅力。"}], "difficulty": "易", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-6", "exam": "hk106", "nums": [6], "form": "單題", "img": "img/hk106-6.png", "source": "出處待查（清代勸戒溺女之文）", "author": "", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "一般十月懷胎，吃盡辛苦，不論男女，總是骨血，何忍淹棄。為父者你自想，若不收女，你妻從何而來？為母者你自想，若不收女，你身從何而活？且生男未必孝順，生女未必忤逆。", "translation": "同樣是懷胎十個月、吃盡苦頭，不論生男生女，都是自己的親骨肉，怎麼忍心把女嬰淹死丟棄？當父親的你自己想想：如果不養女兒，你的妻子從哪裡來？當母親的你自己想想：如果不養女兒，你自己又怎麼能活下來？況且生兒子不一定孝順，生女兒也不一定忤逆。", "keywords": [{"w": "一般", "m": "同樣"}, {"w": "骨血", "m": "親生骨肉"}, {"w": "淹棄", "m": "淹死、丟棄（指溺女嬰）"}, {"w": "收", "m": "收養、養育"}, {"w": "忤逆", "m": "不孝順"}], "questions": [{"n": 6, "stem": "「一般十月懷胎，吃盡辛苦，不論男女，總是骨血，何忍淹棄。為父者你自想，若不收女，你妻從何而來？為母者你自想，若不收女，你身從何而活？且生男未必孝順，生女未必忤逆。」這段文字主要是說明下列何者？", "options": {"A": "父母養育子女的辛勞", "B": "婦女懷胎十月的辛苦", "C": "重男輕女乃不智之舉", "D": "養兒防老乃過時觀念"}, "answer": "C", "explain": "全文在勸人不要淹棄女嬰：男女都是骨肉；沒有女兒，哪來妻子、母親；生男未必孝、生女未必逆——論證重男輕女是不合理、不智的，(C)正確。(A)(B)懷胎辛苦只是開頭的論據，不是主旨。(D)文中只說生男未必孝順，並沒有否定「養兒防老」這個觀念本身。", "skill": "先找出作者反對的行為（淹棄女嬰），再看他舉的理由都指向同一個結論（男女同樣重要）。"}], "difficulty": "易", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-13", "exam": "hk106", "nums": [13], "form": "單題", "img": "img/hk106-13.png", "source": "曾國藩自述（家書／日記）", "author": "曾國藩", "genre": "書信序跋", "types": ["人物情感", "句意理解"], "passage": "早歲有志著述，自馳驅戎馬，此念久廢，然亦不敢遂置詩書於不問也。每日稍閑，則取班、馬、韓、歐諸家文，舊日所酷好者，一溫習之，用此以養吾心而凝吾神。", "translation": "我年輕時立志著書立說，自從帶兵打仗奔走以來，這個念頭早就荒廢了，但也不敢就此把詩書丟在一旁不管。每天稍有空閒，就拿出班固、司馬遷、韓愈、歐陽脩等人的文章，這些都是我從前非常喜愛的，一一溫習，用這來涵養我的心性、凝聚我的精神。", "keywords": [{"w": "早歲", "m": "年輕時"}, {"w": "馳驅戎馬", "m": "奔走於軍旅之中"}, {"w": "遂", "m": "就此"}, {"w": "置……於不問", "m": "擱置不管"}, {"w": "酷好", "m": "非常喜愛"}, {"w": "凝", "m": "凝聚、使專注"}], "questions": [{"n": 13, "stem": "曾國藩自述：「早歲有志著述，自馳驅戎馬，此念久廢，然亦不敢遂置詩書於不問也。每日稍閑，則取班、馬、韓、歐諸家文，舊日所酷好者，一溫習之，用此以養吾心而凝吾神。」根據這段話，下列關於曾國藩的說明何者最恰當？", "options": {"A": "認為養心凝神之道，就是與舊友切磋溫習詩文", "B": "每日仿效班、馬、韓、歐等名家的文章來寫作", "C": "在戎馬之際仍堅持創作，終於成就不朽的著作", "D": "即便工作繁忙，依舊趁暇閱覽詩書，修養心性"}, "answer": "D", "explain": "軍務繁忙，但「每日稍閑」就溫習喜愛的名家文章，「養吾心而凝吾神」，(D)正確。(A)「舊日所酷好者」指以前喜愛的文章，不是老朋友。(B)他是閱讀溫習，不是仿效寫作。(C)他說著述之念「久廢」，並沒有堅持創作。", "skill": "小心「舊日所酷好者」這類容易誤讀的修飾語——先找它修飾的名詞（諸家文），就不會誤為「舊友」。"}], "difficulty": "易", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-15", "exam": "hk106", "nums": [15], "form": "單題", "img": "img/hk106-15.png", "source": "出處待查（詠秋海棠詞）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "冷淡是秋花，更比秋花冷淡些。到處芙蓉供醉賞，從他。自有幽人處士誇。寂寞兩三葩，晝日無風也帶斜。一片西窗殘照裡，誰家。捲卻湘裙薄薄紗。", "translation": "秋天的花本就冷清淡雅，這花比一般秋花更加冷淡。到處都是供人醉飲欣賞的芙蓉，隨它們去吧；這花自有隱居的高人雅士來稱讚。寂寞地開了兩三朵，白天沒有風也斜斜地低垂著。在西窗一片夕陽餘暉裡，像是誰家的女子，捲起了湘裙的薄紗。", "keywords": [{"w": "冷淡", "m": "清冷淡雅"}, {"w": "芙蓉", "m": "木芙蓉，秋天盛開、受眾人喜愛的花"}, {"w": "從他", "m": "隨它去、任憑它"}, {"w": "幽人處士", "m": "隱居的高人雅士"}, {"w": "葩", "m": "花"}, {"w": "殘照", "m": "夕陽餘暉"}], "questions": [{"n": 15, "stem": "「①冷淡是秋花，更比秋花冷淡些。②到處芙蓉供醉賞，從他。自有幽人處士誇。③寂寞兩三葩，晝日無風也帶斜。④一片西窗殘照裡，誰家。捲卻湘裙薄薄紗。」詞中畫線處，何者最能表達作者不隨流俗、終能獲得賞識的想法？", "options": {"A": "①", "B": "②", "C": "③", "D": "④"}, "answer": "B", "explain": "②說芙蓉到處受人醉賞（流俗喜愛的），「從他」——隨它去，不必跟著；這花「自有幽人處士誇」，終會有懂得欣賞的人——兼具「不隨流俗」與「終獲賞識」兩層意思，(B)正確。①只寫花的冷淡氣質。③寫花的寂寞姿態。④以女子捲紗比喻花在夕照中的樣子。三者都沒有「獲得賞識」的意思。", "skill": "把題目要求拆成兩個條件（不隨流俗＋獲得賞識），逐句檢查哪一句同時符合兩個。"}], "difficulty": "中", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-17", "exam": "hk106", "nums": [17], "form": "單題", "img": "img/hk106-17.png", "source": "浮白齋主人《雅謔》（迂公故事）", "author": "", "genre": "寓言故事", "types": ["文意推論", "人物情感"], "passage": "有客語：「馬肝大毒，能殺人，故漢武帝云：『文成食馬肝而死。』」迂公適聞之，發笑曰：「客誑語耳，肝故在馬腹中，馬何以不死？」客戲曰：「馬無百年之壽，以有肝故也。」公大悟，家有畜馬，便刳其肝，馬立斃。公擲刀歎曰：「信哉，毒也。去之尚不可活，況留肝乎？」", "translation": "有個客人說：「馬肝有劇毒，能毒死人，所以漢武帝說：『文成將軍是吃了馬肝而死的。』」迂公剛好聽到，笑著說：「客人在騙人罷了。肝本來就在馬肚子裡，馬為什麼不會死？」客人開玩笑說：「馬活不到一百歲，就是因為有肝的緣故啊。」迂公恍然大悟，家裡養了馬，就把馬肝剖出來，馬立刻死了。迂公丟下刀嘆氣說：「果然啊，真毒！把肝拿掉都活不了，何況留著肝呢？」", "keywords": [{"w": "誑語", "m": "騙人的話"}, {"w": "故", "m": "本來"}, {"w": "戲", "m": "開玩笑"}, {"w": "刳", "m": "剖開挖出"}, {"w": "斃", "m": "死"}, {"w": "信", "m": "確實"}], "questions": [{"n": 17, "stem": "根據這則笑話，下列敘述何者正確？", "options": {"A": "漢武帝因食馬肝而死", "B": "馬肝很毒，所以馬不長壽", "C": "迂公原本不相信客人所說的話", "D": "從迂公殺馬的結果可知客人所言不虛"}, "answer": "C", "explain": "迂公一開始「發笑曰：客誑語耳」，認為客人在騙人，可見他原本不相信，(C)正確。(A)吃馬肝死的是「文成」（文成將軍），漢武帝只是說這句話的人。(B)「馬無百年之壽，以有肝故也」是客人開玩笑的話（客戲曰），不是事實。(D)馬死是因為被剖肝，不能證明馬肝有毒；迂公的結論正是笑話的可笑之處。", "skill": "笑話題要分辨「誰說的、是不是開玩笑（戲）」；再看主角的邏輯錯在哪（把剖肝致死當成肝有毒）。"}], "difficulty": "易", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-18", "exam": "hk106", "nums": [18], "form": "單題", "img": "img/hk106-18.png", "source": "唐傳奇（篇名待查）", "author": "", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "豔冶之貌，代有之矣；潔朗之操，則人鮮聞。故士矜才則德薄，女衒色則情私。若能如執盈，如臨深，則皆為端士淑女矣。", "translation": "美豔的容貌，每個時代都有；純潔明朗的節操，卻很少聽說。所以讀書人自誇才華，德行就淺薄；女子炫耀美色，情感就不端正。如果能像捧著盛滿的器物、像面臨深淵那樣小心謹慎，就都能成為端正的士人、賢淑的女子了。", "keywords": [{"w": "豔冶", "m": "美豔"}, {"w": "代", "m": "世代、每個時代"}, {"w": "操", "m": "節操"}, {"w": "鮮", "m": "少"}, {"w": "矜", "m": "自誇"}, {"w": "衒", "m": "炫示、誇耀"}, {"w": "執盈", "m": "捧著盛滿的器物，比喻小心謹慎"}, {"w": "臨深", "m": "面臨深淵，比喻戒慎恐懼"}], "questions": [{"n": 18, "stem": "「豔冶之貌，代有之矣；潔朗之操，則人鮮聞。故士矜才則德薄，女衒色則情私。若能如執盈，如臨深，則皆為端士淑女矣。」這段文字的觀點，與下列何者最接近？", "options": {"A": "端士淑女應才色兼備", "B": "人宜謹飭德操，莫炫耀才色", "C": "美貌女子與高潔端士均屬少見", "D": "端士不近美色，淑女不矜才德"}, "answer": "B", "explain": "文中批評「矜才」「衒色」會使德薄情私，主張像「執盈、臨深」般謹慎，才能成為端士淑女——要謹慎修養德操、不要炫耀才色，(B)正確。(A)作者重視的是德操而非才色。(C)原文說美貌「代有之」（常見），少見的是「潔朗之操」。(D)作者反對的是「炫耀」才色，不是不能接近美色；淑女要避免的是「衒色」，不是「矜才德」。", "skill": "注意關鍵動詞「矜、衒」（炫耀）——作者批評的是炫耀這個行為，不是才華或美貌本身。"}], "difficulty": "中", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-23", "exam": "hk106", "nums": [23], "form": "單題", "img": "img/hk106-23.png", "source": "出處待查（唐人軼事，記溫庭筠事）", "author": "", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "唐宣宗時，相國令狐綯以故事訪於溫岐，對以「其事出《南華》。」且曰：「非僻書也。或冀相公燮理之暇，時宜覽古。」綯怒。", "translation": "唐宣宗時，宰相令狐綯拿一個典故去請教溫庭筠，溫庭筠回答說：「這件事出自《莊子》。」並且說：「這不是什麼冷僻的書。希望宰相在治理國事的空閒，也該常常讀讀古書。」令狐綯聽了很生氣。", "keywords": [{"w": "相國", "m": "宰相"}, {"w": "故事", "m": "典故、舊事"}, {"w": "訪", "m": "詢問、請教"}, {"w": "《南華》", "m": "指《莊子》"}, {"w": "僻書", "m": "冷僻少見的書"}, {"w": "冀", "m": "希望"}, {"w": "燮理", "m": "治理國事"}, {"w": "覽古", "m": "閱讀古書"}], "questions": [{"n": 23, "stem": "根據這段文字，下列敘述何者正確？", "options": {"A": "令狐綯向溫岐求問無解，故勃然大怒", "B": "令狐綯因施政遇到困難，找溫岐商量", "C": "溫岐回答問題後，勸令狐綯要多讀書", "D": "溫岐以《南華》中的故事指正令狐綯"}, "answer": "C", "explain": "溫岐先回答典故出自《莊子》，又說這「非僻書」，希望宰相有空「時宜覽古」——回答後還勸宰相多讀書，(C)正確；言下之意是嘲諷宰相連常見的書都沒讀過，所以令狐綯生氣。(A)溫岐有回答，不是無解。(B)令狐綯問的是「故事」（典故），不是施政困難。(D)溫岐只說典故出處，並沒有用《莊子》的故事來指正他。", "skill": "「故事」在文言常是「典故、舊例」，不是今天的「故事」；再從「非僻書也」推出溫岐話中帶刺，解釋「綯怒」。"}], "difficulty": "中", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-25", "exam": "hk106", "nums": [25], "form": "單題", "img": "img/hk106-25.png", "source": "《史記‧項羽本紀》、《論語》、《史記‧張釋之列傳》等", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)坐須臾，沛公起「如」廁　(B)弗如也！吾與汝弗「如」也　(C)朝與下大夫言，侃侃「如」也　(D)有不「如」法者，以付廷尉，依律治之", "translation": "(A)坐了一會兒，劉邦起身去上廁所。(B)比不上啊！我和你都比不上他。(C)上朝時和下大夫說話，從容和樂的樣子。(D)有不依照法令的人，就交給廷尉，依照法律處置。", "keywords": [{"w": "如（A）", "m": "往、到"}, {"w": "如（B）", "m": "比得上"}, {"w": "如（C）", "m": "形容詞詞尾，……的樣子"}, {"w": "如（D）", "m": "依照、遵從"}], "questions": [{"n": 25, "stem": "下列文句中的「如」字，何者與「如期完成」的「如」字意思相同？", "options": {"A": "坐須臾，沛公起「如」廁", "B": "弗如也！吾與汝弗「如」也", "C": "朝與下大夫言，侃侃「如」也", "D": "有不「如」法者，以付廷尉，依律治之"}, "answer": "D", "explain": "「如期」是「依照期限」，「如」＝依照。(D)「不如法」＝不依照法令，相同。(A)「如廁」的「如」是「往、到」。(B)「弗如」是「比不上」。(C)「侃侃如」的「如」是形容詞詞尾，表示「……的樣子」。", "skill": "先把題幹詞換成白話（如期＝按照期限），再把「按照」代入每個選項，看哪一句說得通。"}], "difficulty": "中", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-26", "exam": "hk106", "nums": [26], "form": "單題", "img": "img/hk106-26.png", "source": "蘇軾〈節飲食說〉", "author": "蘇軾", "genre": "說理議論", "types": ["句意理解", "文意推論"], "passage": "自今日以往，不過一爵一肉。有尊客，盛饌則三之，可損不可增。有召我者，預以此先之，主人不從而過是者，乃止。一曰安分以養福，二曰寬胃以養氣，三曰省費以養財。", "translation": "從今天開始，每餐不超過一杯酒、一道肉。有貴客來，豐盛的飯菜最多三道，只可減少不可增加。有人請我吃飯，就事先把這個原則告訴對方；主人如果不聽而超過這個標準，我就不去。這樣做：一是安守本分來培養福氣，二是讓腸胃寬鬆來保養元氣，三是節省花費來積蓄財富。", "keywords": [{"w": "以往", "m": "以後"}, {"w": "爵", "m": "酒杯"}, {"w": "饌", "m": "飯菜"}, {"w": "三之", "m": "以三道為限"}, {"w": "損", "m": "減少"}, {"w": "召", "m": "邀請"}, {"w": "先之", "m": "事先告知"}, {"w": "過是", "m": "超過這個標準"}, {"w": "止", "m": "作罷、不去"}], "questions": [{"n": 26, "stem": "蘇東坡自述：「自今日以往，不過一爵一肉。有尊客，盛饌則三之，可損不可增。有召我者，預以此先之，主人不從而過是者，乃止。一曰安分以養福，二曰寬胃以養氣，三曰省費以養財。」根據這段文字，下列何者最符合東坡的飲食原則？", "options": {"A": "對己待客，飲食皆須有所節制", "B": "招待尊客，最少須準備三道盛饌", "C": "受邀作客時，抱持客隨主便的態度", "D": "宴請賓客前，必先告知自家飲食原則"}, "answer": "A", "explain": "自己吃飯「不過一爵一肉」，待客「盛饌則三之，可損不可增」——無論自己吃或請客都有限度，(A)正確。(B)「三之」是最多三道，且「可損不可增」，不是最少。(C)主人若超過標準，東坡就不去，並非客隨主便。(D)「預以此先之」是被人邀請時先告知對方，不是自己宴客前。", "skill": "注意限度用詞（不過、可損不可增）判斷是「最多」還是「最少」；再分清「有召我者」是別人請他。"}], "difficulty": "中", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-29", "exam": "hk106", "nums": [29], "form": "單題", "img": "img/hk106-29.png", "source": "邵雍〈安樂窩中吟〉、楊萬里〈閒居初夏午睡起〉、盧梅坡〈雪梅〉等", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "(A)美酒飲教微醉後，好花看到半開時　(B)戲掬清泉灑蕉葉，兒童誤認雨聲來　(C)書冊埋頭無了日，不如拋卻去尋春　(D)梅須遜雪三分白，雪卻輸梅一段香", "translation": "(A)好酒要喝到微醉為止，好花要欣賞它半開的時候。(B)玩耍地捧起清泉灑在芭蕉葉上，孩子們誤以為是下雨的聲音。(C)埋頭讀書永遠沒有讀完的一天，不如放下書本去尋訪春光。(D)梅花必須在潔白上輸給雪三分，雪卻在香氣上輸給梅花一段。", "keywords": [{"w": "教", "m": "使、讓"}, {"w": "掬", "m": "用雙手捧取"}, {"w": "無了日", "m": "沒有結束的一天"}, {"w": "拋卻", "m": "拋開"}, {"w": "遜", "m": "比不上"}], "questions": [{"n": 29, "stem": "下列詩句前後兩句的關係，何者說明正確？", "options": {"A": "美酒飲教微醉後，好花看到半開時——前句為因，後句為果", "B": "戲掬清泉灑蕉葉，兒童誤認雨聲來——前句泉灑蕉葉的假設引發後句的雨聲", "C": "書冊埋頭無了日，不如拋卻去尋春——將前句的讀書與後句的尋春互作比較", "D": "梅須遜雪三分白，雪卻輸梅一段香——前句由梅至雪，後句由雪至香，層層遞進"}, "answer": "C", "explain": "(C)用「不如」把埋頭讀書和外出尋春相比，認為尋春較好，是比較關係，正確。(A)兩句是並列的兩件事（飲酒適度、賞花適時），不是因果。(B)「戲掬清泉灑蕉葉」是實際發生的動作，不是假設；後句是孩子的誤會。(D)兩句是梅、雪互相比較長短（白／香），屬對比，不是層層遞進。", "skill": "找兩句之間的關聯詞或暗含的邏輯（不如＝比較；卻＝對比）；沒有關聯詞時，判斷兩句是並列還是先後因果。"}], "difficulty": "中", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-32", "exam": "hk106", "nums": [32], "form": "單題", "img": "img/hk106-32.png", "source": "蘇軾《東坡志林》（桃符艾人語）", "author": "蘇軾", "genre": "寓言故事", "types": ["文意推論", "文化常識"], "passage": "桃符仰視艾人而罵曰：「汝何等草芥，輒居我上？」艾人俯而應曰：「自元日至端午以來，汝已半截入土，猶爭高下乎？」桃符怒，往復紛然不已。門神解之曰：「吾輩不肖，方傍人門戶，何暇爭閒氣耶？」", "translation": "桃符抬頭看著艾人罵道：「你是什麼小草，竟敢在我上面？」艾人低頭回答說：「從元旦到端午，你已經半截身子入土了，還要爭高低嗎？」桃符大怒，兩方你來我往吵個不停。門神勸解他們說：「我們這些沒出息的，正依附在別人的門戶上，哪有空閒爭這種閒氣呢？」", "keywords": [{"w": "桃符", "m": "元旦掛在門上的桃木板，後演變為春聯"}, {"w": "艾人", "m": "端午節掛在門上的艾草人形"}, {"w": "草芥", "m": "小草，比喻微不足道"}, {"w": "輒", "m": "竟然、就"}, {"w": "半截入土", "m": "比喻年老、快要過時"}, {"w": "不肖", "m": "沒出息"}, {"w": "傍", "m": "依附"}], "questions": [{"n": 32, "stem": "「桃符仰視艾人而罵曰：『汝何等草芥，輒居我上？』艾人俯而應曰：『自元日至端午以來，汝已半截入土，猶爭高下乎？』桃符怒，往復紛然不已。門神解之曰：『吾輩不肖，方傍人門戶，何暇爭閒氣耶？』」根據這段文字，下列敘述何者正確？", "options": {"A": "艾人以「半截入土」暗譏桃符有過時之嫌", "B": "門神指責桃符愛爭閒氣，所以只能傍人門戶", "C": "三者位置由高而低依序是：門神、桃符、艾人", "D": "桃符與艾人為了元日、端午的重要性而爭吵不休"}, "answer": "A", "explain": "桃符是元旦掛的，到端午已經掛了大半年，艾人說它「半截入土」，是譏諷它已經過時了，(A)正確。(B)門神說「吾輩」，是連自己一起說，意思是大家都只是依附別人門戶，何必爭；並不是說因為愛爭閒氣才傍人門戶。(C)桃符「仰視」艾人，艾人「俯而應」，可見艾人在桃符上方；門神位置文中未說明。(D)他們爭的是位置的高下，不是節日的重要性。", "skill": "留意方位動詞（仰視、俯而應）判斷位置；結合文化常識（桃符元旦、艾人端午）理解「半截入土」的雙關。"}], "difficulty": "中", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-45", "exam": "hk106", "nums": [45, 46], "form": "題組", "img": "img/hk106-45.png", "source": "葛虛存《清代名人軼事》", "author": "葛虛存", "genre": "史傳人物", "types": ["虛詞句式", "人物情感"], "passage": "佟中丞鳳彩巡撫河南，年已老，每日五鼓，燃燭治文書，或坐倦假寐，少頃，輒矍然起，自呼其名曰：「佟某，汝為朝廷大臣，封疆之重，皆汝肩之，奈何不任事若此！」輒以手批頰數四。侍者為之悚慄。中丞在豫，恩澤普及，豫人感其德，猶繪像祀之。", "translation": "佟鳳彩以中丞身分巡撫河南，年紀已經老了，每天五更天就點燭處理公文。有時坐累了打個盹，一會兒就驚醒起身，叫著自己的名字說：「佟某，你身為朝廷大臣，一方疆土的重任都由你承擔，怎麼可以這樣不負責任！」就用手打自己的臉好幾下。侍從們都因此驚懼戰慄。佟中丞在河南，恩澤遍及百姓，河南人感念他的德政，至今還畫他的像來祭祀他。", "keywords": [{"w": "中丞", "m": "官名，清代巡撫的別稱"}, {"w": "巡撫", "m": "（動詞）巡察安撫、治理"}, {"w": "五鼓", "m": "五更，天快亮時"}, {"w": "假寐", "m": "打盹"}, {"w": "矍然", "m": "驚視貌"}, {"w": "封疆", "m": "一方疆土"}, {"w": "肩", "m": "（動詞）承擔"}, {"w": "批頰", "m": "打耳光"}, {"w": "悚慄", "m": "驚懼發抖"}, {"w": "豫", "m": "河南的簡稱"}], "questions": [{"n": 45, "stem": "「佟中丞鳳彩巡撫河南」句中「巡撫」二字的詞性，與下列何者相同？", "options": {"A": "燃「燭」治文書", "B": "皆汝「肩」之", "C": "輒以手批「頰」數四", "D": "侍者「為」之悚慄"}, "answer": "B", "explain": "「巡撫河南」的「巡撫」後面接受詞「河南」，是動詞（治理）。(B)「皆汝肩之」的「肩」本是名詞（肩膀），這裡作動詞「承擔」，後接「之」，詞性相同。(A)「燭」是名詞（蠟燭）。(C)「頰」是名詞（臉頰）。(D)「為」是介詞「因為」。", "skill": "判斷詞性看位置：後面直接接受詞（河南、之）的通常是動詞；名詞轉品作動詞（肩之）是常見考點。"}, {"n": 46, "stem": "根據本文的敘述，可推知佟中丞的為人如何？", "options": {"A": "自許甚高，治事嚴謹", "B": "嫉惡如仇，律下嚴厲", "C": "貧賤不移，威武不屈", "D": "豁達大度，不拘小節"}, "answer": "A", "explain": "他年老仍五更起來處理公文，打個盹都要罵自己「為朝廷大臣……奈何不任事若此」、打自己耳光——以大臣自我期許、要求很高，做事嚴謹，(A)正確。(B)他嚴厲的對象是自己，不是下屬；侍者害怕是被他的自責嚇到。(C)文中沒有面對貧賤或威武的情節。(D)他連打盹都不原諒自己，與「不拘小節」相反。", "skill": "看人物責備的對象是誰（自己），再判斷是「律己」還是「律人」。"}], "difficulty": "中", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk106-47", "exam": "hk106", "nums": [47, 48], "form": "題組", "img": "img/hk106-47.png", "source": "韋莊〈送日本國僧敬龍歸〉、鄭谷〈淮上與友人別〉", "author": "韋莊、鄭谷", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "寫作手法"], "passage": "甲：扶桑已在渺茫中，家在扶桑東更東。此去與師誰共到？一船明月一帆風。（韋莊〈送日本國僧敬龍歸〉）\n乙：揚子江頭楊柳春，楊花愁殺渡江人。數聲風笛離亭晚，君向瀟湘我向秦。（鄭谷〈淮上與友人別〉）", "translation": "甲：扶桑（日本）已經在遙遠渺茫的地方，你的家卻還在扶桑的更東邊。這一去，誰能陪大師一起到達呢？只有一船明月、一帆清風。\n乙：揚子江邊楊柳正逢春天，飄飛的楊花讓渡江的人愁苦極了。幾聲風中傳來的笛聲，離別的亭子已近黃昏，你要往瀟湘去，我要往秦地去。", "keywords": [{"w": "扶桑", "m": "相傳東海外的神木、日出之地，亦為日本別名"}, {"w": "渺茫", "m": "遙遠模糊"}, {"w": "師", "m": "對僧人的尊稱"}, {"w": "愁殺", "m": "愁極了"}, {"w": "離亭", "m": "送別的亭子"}, {"w": "瀟湘", "m": "今湖南一帶"}, {"w": "秦", "m": "今陝西一帶"}], "questions": [{"n": 47, "stem": "關於這兩首詩的內容，下列敘述何者正確？", "options": {"A": "甲詩描寫時間為晚上，乙詩描寫時間是清晨", "B": "甲詩送別地點在扶桑，乙詩分別地點在揚子江", "C": "甲詩作者將與友人同行，乙詩作者送友人獨往", "D": "甲詩友人以船為交通工具，乙詩友人亦是如此"}, "answer": "D", "explain": "甲詩「一船明月一帆風」，敬龍乘船回日本；乙詩「楊花愁殺渡江人」，在揚子江頭渡江，也是坐船，(D)正確。(A)乙詩「離亭晚」是傍晚，不是清晨；甲詩的「明月」是想像旅途，未必是送別當下。(B)甲詩的扶桑是友人要去的地方，不是送別地點。(C)甲詩「此去與師誰共到」——沒有人同行，只有明月清風；乙詩是「君向瀟湘我向秦」，兩人各奔東西，不是作者留下送行。", "skill": "從詩句中找具體證據（船、帆、渡江、晚），逐一檢驗選項的時間、地點、人物、交通工具。"}, {"n": 48, "stem": "關於這兩首詩的寫作手法，下列敘述何者正確？", "options": {"A": "甲乙兩詩皆遲至末句才點出友人前行的目的地", "B": "甲乙兩詩各自重複某些字詞，增添詩的節奏感", "C": "甲詩由眼前景寫到想像景，乙詩從想像景寫到眼前景", "D": "甲詩只有二、四句用韻，乙詩是一、二、四句皆用韻"}, "answer": "B", "explain": "甲詩重複「扶桑」「東」「一」（東更東、一船一帆），乙詩重複「楊」「江」「向」（楊柳、楊花；江頭、渡江；君向、我向），增添節奏感，(B)正確。(A)甲詩第一、二句就點出目的地扶桑。(C)甲詩開頭就寫遙遠的扶桑（想像），末句才寫船帆；乙詩全寫眼前送別的景，都不符合。(D)甲詩「中、東、風」一、二、四句都押韻；乙詩「春、人、秦」也是一、二、四句押韻。", "skill": "手法題要一項項實際檢查：數重複字、標韻腳、找目的地出現在哪一句，不要憑印象判斷。"}], "difficulty": "難", "label": "106年會考", "year": 106, "kind": "會考"}, {"id": "hk107-10", "exam": "hk107", "nums": [10], "form": "單題", "img": "img/hk107-10.png", "source": "出處待查（清代書法論著）", "author": "", "genre": "說理議論", "types": ["句意理解", "文意推論"], "passage": "九宮格內用細線界一井字，以均布字之點畫，凡字無論疏密斜正，必有精神挽結之處，是為字之中宮。然中宮有在實畫，有在虛白，必審其字之精神所注，而安置於格內之中宮。然後以其字之頭目手足分布於旁之八宮，則隨其長短虛實而上下左右皆相得矣。", "translation": "九宮格裡用細線劃出一個「井」字，用來平均安排字的點畫。每個字不論筆畫疏密、字形斜正，一定有精神凝聚收束的地方，這就是字的「中宮」。中宮有時落在實的筆畫上，有時落在空白處，必須仔細觀察這個字精神貫注在哪裡，把它安放在格子正中那一宮。然後把字的頭、眼、手、腳（各部分筆畫）分布到四周八宮，依照筆畫長短虛實去安排，上下左右就都能協調配合了。", "keywords": [{"w": "界", "m": "劃分"}, {"w": "均布", "m": "平均分布"}, {"w": "挽結", "m": "收束、凝聚"}, {"w": "審", "m": "仔細觀察"}, {"w": "所注", "m": "貫注之處"}, {"w": "相得", "m": "互相配合、協調"}], "questions": [{"n": 10, "stem": "「九宮格內用細線界一井字，以均布字之點畫，凡字無論疏密斜正，必有精神挽結之處，是為字之中宮。然中宮有在實畫，有在虛白，必審其字之精神所注，而安置於格內之中宮。然後以其字之頭目手足分布於旁之八宮，則隨其長短虛實而上下左右皆相得矣。」這段文字所要說明的內容不包含下列何者？", "options": {"A": "強調墨色的層次變化", "B": "精究字體精神之所在", "C": "重視字體的均衡美感", "D": "指出筆畫的布局原則"}, "answer": "A", "explain": "這段話談的是用九宮格安排字形：找出字的「中宮」（精神凝聚處），再把其餘筆畫分到旁邊八宮。(B)「必審其字之精神所注」就是在探究字的精神所在；(C)「上下左右皆相得」講的是整體均衡；(D)「均布字之點畫」「分布於旁之八宮」是在說筆畫布局。全文完全沒有提到墨色的濃淡、層次，所以「不包含」的是(A)。", "skill": "「不包含」題：把每個選項拿回原文找對應句，找不到依據的那一個就是答案。"}], "difficulty": "中", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-17", "exam": "hk107", "nums": [17], "form": "單題", "img": "img/hk107-17.png", "source": "出處待查（題幹與選項分屬不同古典詩作；(A)為李白〈秋浦歌〉）", "author": "", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "家國身猶負，星霜鬢已侵。\n(A)不知明鏡裡，何處得秋霜\n(B)遙夜一美人，羅衣霑秋霜\n(C)心隨朗日高，志與秋霜潔\n(D)五月思貂裘，謂言秋霜落", "translation": "題幹：對家國的責任仍背負在身上，鬢髮卻已像星霜般花白。\n(A)不知道鏡子裡的我，是從哪裡得來這滿頭秋霜（白髮）。(B)漫漫長夜裡一位美人，絲羅衣裳沾上了秋霜。(C)心志隨著明亮的太陽一樣高遠，節操像秋霜一樣潔白。(D)五月天卻想穿貂皮大衣，還以為是秋霜降下了（形容天氣寒冷）。", "keywords": [{"w": "星霜", "m": "比喻花白的頭髮"}, {"w": "侵", "m": "逐漸侵襲、蔓延"}, {"w": "霑", "m": "沾濕"}, {"w": "謂言", "m": "以為、認為"}], "questions": [{"n": 17, "stem": "「家國身猶負，星霜鬢已侵。」句中以「霜」來形容鬢髮變白。下列詩句中的「霜」字，何者也是指鬢髮變白？", "options": {"A": "不知明鏡裡，何處得秋霜", "B": "遙夜一美人，羅衣霑秋霜", "C": "心隨朗日高，志與秋霜潔", "D": "五月思貂裘，謂言秋霜落"}, "answer": "A", "explain": "(A)照鏡子才發現「秋霜」，鏡中看得到的是自己的頭髮，所以秋霜指白髮（李白〈秋浦歌〉上一句正是「白髮三千丈」）。(B)霜沾在羅衣上，是真正的霜露。(C)「志與秋霜潔」用秋霜比喻志節的潔白高尚，不是頭髮。(D)五月就想穿貂裘，以為秋霜降落，說的是天氣寒冷，霜是真實的天候。", "skill": "判斷借代／比喻：看「霜」出現在什麼情境（鏡子、衣服、志向、天氣），從上下文推出它指的是什麼。"}], "difficulty": "易", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-22", "exam": "hk107", "nums": [22], "form": "單題", "img": "img/hk107-22.png", "source": "鍾嶸《詩品‧序》（改寫）", "author": "鍾嶸", "genre": "說理議論", "types": ["主旨寓意", "文意推論"], "passage": "今之士俗，無不好詩，甫就小學，必甘心而馳騖焉。於是庸音雜體，人各為容。至使膏腴子弟，恥文不逮，終朝點綴，分夜呻吟。獨觀謂為警策，眾睹終淪平鈍。", "translation": "現在的士人風氣，沒有人不喜愛寫詩，小孩子才剛入小學讀書，就一心一意地奔向寫詩這件事。於是平庸的音調、雜亂的體裁，人人各自標榜一套。甚至使富貴人家的子弟，以文章比不上別人為恥，整天修飾字句，半夜還在苦苦吟哦。自己看時認為是精彩警策的好句子，大家一看，終究只是平庸遲鈍的作品。", "keywords": [{"w": "甫", "m": "剛剛、才"}, {"w": "馳騖", "m": "奔走追求"}, {"w": "庸音雜體", "m": "平庸的音調與雜亂的體裁"}, {"w": "膏腴子弟", "m": "富貴人家的子弟"}, {"w": "不逮", "m": "比不上"}, {"w": "警策", "m": "作品中精彩扼要、足以驚動讀者的部分"}, {"w": "淪", "m": "落入"}], "questions": [{"n": 22, "stem": "「今之士俗，無不好詩，甫就小學，必甘心而馳騖焉。於是庸音雜體，人各為容。至使膏腴子弟，恥文不逮，終朝點綴，分夜呻吟。獨觀謂為警策，眾睹終淪平鈍。」作者寫作這段文字的用意，最可能是下列何者？", "options": {"A": "歌頌詩風鼎盛，雅俗共賞", "B": "憂心以詩取士，難得真才", "C": "慨嘆詩風雖盛，但少有佳作", "D": "讚嘆各類詩體兼備，蔚為大觀"}, "answer": "C", "explain": "前半「無不好詩」「必甘心而馳騖焉」寫寫詩風氣很盛；後半「庸音雜體」「眾睹終淪平鈍」說大部分作品平庸。前盛後衰的對照，正是在慨嘆「詩風雖盛，但少有佳作」。(A)作者語帶批評，不是歌頌。(B)文中沒有提到考試取士。(D)「庸音雜體」是貶語，不是讚嘆體裁齊備。", "skill": "抓作者態度：先標出褒貶詞（好詩、馳騖 vs 庸音、平鈍），褒貶轉折處就是作者的用意。"}], "difficulty": "中", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-24", "exam": "hk107", "nums": [24], "form": "單題", "img": "img/hk107-24.png", "source": "《戰國策‧秦策五》", "author": "", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "秦王與中期爭論，不勝。秦王大怒，中期徐行而去。或為中期說秦王曰：「悍人也，中期！適遇明君故也。向者遇桀、紂，必殺之矣。」秦王因不罪。", "translation": "秦王和中期爭論，沒有辯贏。秦王非常生氣，中期卻慢慢地走開。有人替中期向秦王進言說：「中期真是個強悍的人啊！幸好他剛好遇上英明的君主。如果以前他遇到的是桀、紂，一定會被殺了。」秦王因此不怪罪中期。", "keywords": [{"w": "徐行", "m": "慢慢地走"}, {"w": "或", "m": "有人"}, {"w": "說", "m": "勸說，音ㄕㄨㄟˋ"}, {"w": "悍", "m": "強悍、剛直"}, {"w": "適", "m": "恰好"}, {"w": "向者", "m": "假使、從前"}, {"w": "罪", "m": "怪罪、處罰（動詞）"}], "questions": [{"n": 24, "stem": "「秦王與中期爭論，不勝。秦王大怒，中期徐行而去。或為中期說秦王曰：『悍人也，中期！適遇明君故也。向者遇桀、紂，必殺之矣。』秦王因不罪。」根據這段文字，下列敘述何者正確？", "options": {"A": "中期說服秦王不加罪於他", "B": "秦王因中期與人爭論不勝而大怒", "C": "中期徐行而去，表現其謙和的應對態度", "D": "秦王不怪罪中期的原因是不願被比做桀、紂"}, "answer": "D", "explain": "說客的話很巧妙：如果是桀、紂一定殺中期，而您是明君所以不會殺。秦王若處罰中期，就等於承認自己是桀、紂一類的暴君，所以「因不罪」。(A)替中期說話的是「或」（某人），不是中期本人。(B)是秦王自己和中期爭論輸了，不是中期與別人爭論。(C)辯贏了國君還慢慢走開，表現的是剛直不屈，所以說客稱他「悍人」，不是謙和。", "skill": "先確認每句的主語（誰爭論、誰說話），再推想說客話中的「圈套」：把對方放進『明君／暴君』二選一。"}], "difficulty": "中", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-25", "exam": "hk107", "nums": [25], "form": "單題", "img": "img/hk107-25.png", "source": "選項分別出自《孟子‧告子下》、吳均〈與宋元思書〉、沈復〈兒時記趣〉、〈木蘭詩〉等", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)舜「發」於畎畝之中／徵於色，「發」於聲，而後喻\n(B)奇山異水，天下獨「絕」／明山秀水，令人讚不「絕」口\n(C)心之所「向」，則或千或百，果然鶴也／大軍之至，所「向」披靡\n(D)爺孃聞女來，出郭相扶「將」／欲「將」此意與君論，復道秦關尚千里", "translation": "(A)舜從田野中被起用／（人的困苦）表現在臉色上，抒發在言語中，然後才被人了解。(B)奇特的山、特異的水，是天下獨一無二的／明媚的山水，讓人讚美個不停。(C)心裡想著（蚊子是鶴）的時候，眼前的成千上百隻蚊子果然都成了鶴／大軍所到之處，所朝向的敵人都潰散倒下。(D)爹娘聽說女兒回來，走出城外互相攙扶著迎接／想把這份心意和你談一談，又說秦關還遠在千里之外。", "keywords": [{"w": "發（舜發）", "m": "被起用、興起"}, {"w": "發（發於聲）", "m": "表現、抒發"}, {"w": "絕（獨絕）", "m": "獨一無二、極好"}, {"w": "絕（不絕）", "m": "停止、斷絕"}, {"w": "向", "m": "朝向、趨向"}, {"w": "將（扶將）", "m": "攙扶"}, {"w": "將（將此意）", "m": "拿、把"}], "questions": [{"n": 25, "stem": "下列文句「」中的字，何者意義前後相同？", "options": {"A": "舜「發」於畎畝之中／徵於色，「發」於聲，而後喻", "B": "奇山異水，天下獨「絕」／明山秀水，令人讚不「絕」口", "C": "心之所「向」，則或千或百，果然鶴也／大軍之至，所「向」披靡", "D": "爺孃聞女來，出郭相扶「將」／欲「將」此意與君論，復道秦關尚千里"}, "answer": "C", "explain": "(C)兩個「向」都是「朝向、趨向」：心思所朝向的地方／軍隊所朝向的地方，意義相同。(A)前者是「被起用」，後者是「表現、抒發」。(B)前者是「獨一無二、極好」，後者是「停止」。(D)前者是「攙扶」（扶將＝扶持），後者是介詞「拿、把」。", "skill": "一詞多義：把字代換成白話放回句中，兩句都通順且意思一致才是相同。"}], "difficulty": "中", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-28", "exam": "hk107", "nums": [28], "form": "單題", "img": "img/hk107-28.png", "source": "晁補之〈新城遊北山記〉", "author": "晁補之", "genre": "山水遊記", "types": ["寫作手法"], "passage": "去新城之北三十里，山漸深，草木泉石漸幽。初猶騎行石齒間，旁皆大松，曲者如蓋，直者如幢，立者如人，臥者如虯。松下草間有泉，沮洳伏見，墮石井，鏘然而鳴。松間藤數十尺，蜿蜒如大螈。其上有鳥，黑如鴝鵒，赤冠長喙，俯而啄，磔然有聲。", "translation": "離開新城往北走三十里，山越來越深，草木泉石越來越幽靜。起初還能騎馬走在像牙齒般參差的石頭間，兩旁都是大松樹，彎曲的像車蓋，挺直的像旗幢，站著的像人，橫臥的像虯龍。松樹下的草叢間有泉水，在草間時隱時現地滲流，落進石井裡，發出鏘鏘的聲響。松樹間的藤蔓長達數十尺，彎彎曲曲像大蠑螈。藤上有鳥，黑得像八哥，紅冠長嘴，低頭啄食，發出磔磔的聲音。", "keywords": [{"w": "去", "m": "離開"}, {"w": "幽", "m": "幽靜、幽深"}, {"w": "蓋", "m": "車蓋、傘蓋"}, {"w": "幢", "m": "旗幟一類的儀仗"}, {"w": "虯", "m": "傳說中有角的小龍"}, {"w": "沮洳伏見", "m": "泉水在草間時隱時現地滲流"}, {"w": "鏘然", "m": "形容清脆響亮的聲音"}, {"w": "鴝鵒", "m": "八哥鳥"}, {"w": "磔然", "m": "形容鳥啄的聲音"}], "questions": [{"n": 28, "stem": "「去新城之北三十里，山漸深，草木泉石漸幽。初猶騎行石齒間，旁皆大松，曲者如蓋，直者如幢，立者如人，臥者如虯。松下草間有泉，沮洳伏見，墮石井，鏘然而鳴。松間藤數十尺，蜿蜒如大螈。其上有鳥，黑如鴝鵒，赤冠長喙，俯而啄，磔然有聲。」關於這段文字的寫作手法，下列敘述何者正確？", "options": {"A": "文中寫松最為詳盡，有聲有色有形有狀", "B": "以譬喻的手法描繪山間林木泉石與鳥鳴", "C": "由小景寫至大景，層層推進，井然有序", "D": "藉鏘然泉聲、磔然鳥聲反襯山林的幽靜"}, "answer": "D", "explain": "文章開頭就點出「草木泉石漸幽」，後面特別寫泉水「鏘然而鳴」、鳥啄「磔然有聲」，在極安靜的山林裡，連這樣細小的聲音都聽得清楚，正是以聲襯靜。(A)寫松只寫形狀（如蓋、如幢、如人、如虯），沒有寫聲音與顏色；有聲有色的是泉與鳥。(B)譬喻用在松、藤、鳥的顏色，泉聲、鳥鳴是用狀聲詞摹寫，不是譬喻。(C)由「山漸深」的整體山景寫到松、泉、藤、鳥的細部，是由大景到小景。", "skill": "寫作手法題要逐項對證：找出「如」字（譬喻）、「然」字狀聲詞（摹聲），再看描寫順序與作者想營造的氣氛。"}], "difficulty": "中", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-29", "exam": "hk107", "nums": [29], "form": "單題", "img": "img/hk107-29.png", "source": "《古今詩話》（見胡仔《苕溪漁隱叢話》）", "author": "", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "有客謂子野曰：「人皆謂公張三中，即心中事、眼中淚、意中人也。」公曰：「何不目之為張三影？」客不曉，公曰：「雲破月來花弄影；嬌柔懶起，簾壓捲花影；柳徑無人，墜輕絮無影：此余平生所得意也」。", "translation": "有位客人對張先（字子野）說：「大家都稱您為『張三中』，因為您的詞裡有『心中事、眼中淚、意中人』。」張先說：「為什麼不稱我為『張三影』呢？」客人不明白，張先說：「『雲破月來花弄影』、『嬌柔懶起，簾壓捲花影』、『柳徑無人，墜輕絮無影』，這三句是我平生最得意的句子。」", "keywords": [{"w": "謂", "m": "對……說；稱呼"}, {"w": "目", "m": "稱呼、看作（動詞）"}, {"w": "曉", "m": "明白"}, {"w": "弄影", "m": "擺動自己的影子"}, {"w": "得意", "m": "滿意、自豪"}], "questions": [{"n": 29, "stem": "「有客謂子野曰：『人皆謂公張三中，即心中事、眼中淚、意中人也。』公曰：『何不目之為張三影？』客不曉，公曰：『雲破月來花弄影；嬌柔懶起，簾壓捲花影；柳徑無人，墜輕絮無影：此余平生所得意也』。」根據這段文字，下列敘述何者錯誤？", "options": {"A": "子野詞作風格以婉約、柔美為主", "B": "寫作用字，子野有其特殊的喜好", "C": "子野自認平生佳作無多，僅此三則", "D": "世人稱許之處，子野未必全盤同意"}, "answer": "C", "explain": "「此余平生所得意也」是說這三句是他最得意、最自豪的句子，並不是說他一生的好作品只有這三則，所以(C)錯誤。(A)「心中事、眼中淚、意中人」、月下花影、柳絮輕飄，都是細膩柔美的婉約風格。(B)三句都用「影」字，可見他偏愛這個字。(D)世人稱他「張三中」，他卻希望被稱為「張三影」，表示他並不完全認同世人的稱許重點。", "skill": "注意「最得意」和「只有」的差別：選項把程度詞換掉（最好→僅此），就是常見的錯誤陷阱。"}], "difficulty": "中", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-30", "exam": "hk107", "nums": [30], "form": "單題", "img": "img/hk107-30.png", "source": "王安石〈使醫〉", "author": "王安石", "genre": "說理議論", "types": ["主旨寓意", "文意推論"], "passage": "「一人疾焉而醫者十，並使之歟？」曰：「使其尤良者一人焉爾。」「烏知其尤良而使之？」曰：「眾人之所謂尤良者，而隱之以吾心，其可也。夫材不相逮，不相為謀，又相忌也。人之愚不能者常多，而智能者常少，醫者十，愚不能者烏知其不九邪？並使之，一日而病且亡，誰者任其咎邪？」", "translation": "「一個人生病而有十個醫生，要全部都用嗎？」回答：「只用其中特別好的一個人罷了。」「怎麼知道誰特別好而用他呢？」回答：「先參考大家所說特別好的人，再用自己的心詳細考量，這樣就可以了。才能高低不相當的人，不會一起好好商量，反而互相猜忌。世上愚笨無能的人常常多，聰明能幹的人常常少，十個醫生當中，怎麼知道愚笨無能的不會有九個呢？全部都用，病人一天之內就死了，誰來承擔這個罪責呢？」", "keywords": [{"w": "疾", "m": "生病"}, {"w": "並", "m": "全部、一起"}, {"w": "使", "m": "任用"}, {"w": "尤良", "m": "特別好的"}, {"w": "烏", "m": "怎麼、哪裡"}, {"w": "隱", "m": "詳細考量"}, {"w": "相逮", "m": "彼此相當、比得上"}, {"w": "任", "m": "擔當、承受"}, {"w": "咎", "m": "罪責、過失"}], "questions": [{"n": 30, "stem": "作者在這段文字中雖論使醫治病，但用意卻在談用人治國之理。據此，作者主張在上位者應該如何？", "options": {"A": "眾口交譽之人，直接任用", "B": "善於汰劣擢優，委賢重任", "C": "務求廣納眾議，興利除弊", "D": "使愚智不相忌，同心為國"}, "answer": "B", "explain": "作者主張十個醫生不要全用，只用「尤良者一人」，因為能力不齊的人會互相猜忌，而且庸才多於人才。比喻到治國，就是要淘汰差的、提拔好的，把重任交給賢能的人，所以選(B)。(A)作者說要參考眾人意見，還要「隱之以吾心」自己審慎考量，不是直接任用。(C)全部採用、人人參與正是作者反對的「並使之」。(D)作者認為才能不相當的人一定相忌，所以主張不要並用，而不是設法讓他們不相忌。", "skill": "寓言／類比說理題：先找出比喻的兩端（醫者→臣子、病人→國家），再把作者的做法（只用最好的一人）翻譯成治國原則。"}], "difficulty": "中", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-31", "exam": "hk107", "nums": [31], "form": "單題", "img": "img/hk107-31.png", "source": "【甲】東方虬〈春雪〉；【乙】王安石〈梅花〉", "author": "東方虬、王安石", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "【甲】春雪滿空來，觸處似花開。不知園裡樹，若個是真梅？\n【乙】牆角數枝梅，凌寒獨自開。遙知不是雪，為有暗香來。", "translation": "【甲】春天的雪漫天飄來，落到哪裡都像花開一樣。不知道園子裡的樹，哪一棵才是真正的梅花？\n【乙】牆角有幾枝梅花，冒著嚴寒獨自開放。遠遠就知道那不是雪，因為有淡淡的幽香飄過來。", "keywords": [{"w": "觸處", "m": "到處、所接觸的地方"}, {"w": "若個", "m": "哪個"}, {"w": "凌寒", "m": "冒著寒冷"}, {"w": "為", "m": "因為"}, {"w": "暗香", "m": "淡淡的清香"}], "questions": [{"n": 31, "stem": "【甲】春雪滿空來，觸處似花開。不知園裡樹，若個是真梅？【乙】牆角數枝梅，凌寒獨自開。遙知不是雪，為有暗香來。根據甲、乙兩詩的內涵，下列敘述何者最恰當？", "options": {"A": "甲詩以梅喻雪，乙詩以雪喻梅", "B": "甲詩主題是詠雪，乙詩主題是詠梅", "C": "兩詩所描繪的都是暮春夜晚的景致", "D": "兩詩作者都無法分辨眼前所見是雪還是梅"}, "answer": "B", "explain": "甲詩標題、首句都寫「春雪」，說雪落樹上像梅花盛開，主角是雪；乙詩寫牆角梅花凌寒獨開、以暗香辨認，主角是梅，所以(B)正確。(A)乙詩說「遙知不是雪」，是在說明梅白如雪卻能憑香氣分辨，重點不在用雪來比喻梅，敘述不夠恰當。(C)甲詩寫春雪，乙詩寫「凌寒」的冬梅，都沒有寫暮春夜晚。(D)乙詩作者「遙知不是雪」，能夠分辨。", "skill": "比較兩首詩：先各自找出「寫的主角是什麼」，再看詩人用什麼去襯托或比喻主角。"}], "difficulty": "易", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-32", "exam": "hk107", "nums": [32], "form": "單題", "img": "img/hk107-32.png", "source": "《韓非子‧說林上》", "author": "韓非", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "子胥出逃，邊候得之。子胥曰：「上索我者，以我有美珠也。今我已亡之矣，我將謂子取而吞之。」候因釋之。", "translation": "伍子胥出逃，被邊境的官吏抓到。子胥說：「君王要捉我，是因為我有一顆美珠。現在我已經把它弄丟了，（你如果把我交上去）我就說是你拿走吞下肚了。」邊吏因此放了他。", "keywords": [{"w": "邊候", "m": "邊境的官吏"}, {"w": "得", "m": "抓到"}, {"w": "上", "m": "君王"}, {"w": "索", "m": "搜捕、尋找"}, {"w": "亡", "m": "遺失"}, {"w": "謂", "m": "說"}, {"w": "釋", "m": "釋放"}], "questions": [{"n": 32, "stem": "「子胥出逃，邊候得之。子胥曰：『上索我者，以我有美珠也。今我已亡之矣，我將謂子取而吞之。』候因釋之。」根據這段文字，下列敘述何者正確？", "options": {"A": "子胥用言語威脅邊候以求自保", "B": "子胥以美珠賄賂邊候換取自由", "C": "邊候侵吞子胥的美珠又誣陷他", "D": "邊候相信子胥的清白而釋放他"}, "answer": "A", "explain": "子胥說要誣指邊候吞了美珠，君王為了找珠子就會剖開邊候的肚子，邊候害怕才放人，這是用言語威脅來自保，選(A)。(B)子胥說珠子已經遺失，沒有拿珠子賄賂。(C)「取而吞之」只是子胥準備說的假話，邊候並沒有侵吞。(D)邊候放人是因為害怕被誣陷，不是相信他清白。", "skill": "找出「將」字表示的是打算（還沒發生），分清楚真實事件和人物揚言要做的事。"}], "difficulty": "易", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-33", "exam": "hk107", "nums": [33], "form": "單題", "img": "img/hk107-33.png", "source": "劉餗《隋唐嘉話》", "author": "劉餗", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "隋煬帝善屬文，而不欲人出其右，司隸薛道衡由是得罪。後因事誅之，曰：「更能作『空梁落燕泥』否？」", "translation": "隋煬帝擅長寫文章，卻不希望有人勝過自己，司隸薛道衡因此得罪了他。後來找了個事由把薛道衡殺了，還說：「你還能再寫出『空梁落燕泥』這樣的句子嗎？」", "keywords": [{"w": "屬文", "m": "連綴字句成文，指寫文章"}, {"w": "出其右", "m": "勝過他（古代以右為尊）"}, {"w": "由是", "m": "因此"}, {"w": "誅", "m": "殺"}, {"w": "更", "m": "再、還"}], "questions": [{"n": 33, "stem": "「隋煬帝善屬文，而不欲人出其右，司隸薛道衡由是得罪。後因事誅之，曰：『更能作「空梁落燕泥」否？』」根據這段文字，可以推知下列何者？", "options": {"A": "煬帝命薛道衡作詩，薛因抗命而被殺", "B": "薛道衡死後，煬帝感嘆再也無人能出其右", "C": "薛道衡因事被誅，臨刑以「空梁」一詩明志", "D": "煬帝嫉妒薛道衡能有「空梁落燕泥」這等佳句"}, "answer": "D", "explain": "「不欲人出其右」說明煬帝不能容忍別人比他強，薛道衡「由是得罪」；殺了他之後還嘲諷「還能寫『空梁落燕泥』嗎？」可推知這句是薛道衡的佳句，煬帝因嫉妒而殺他，選(D)。(A)文中沒有命他作詩、抗命的情節。(B)「更能作……否」是幸災樂禍的嘲諷，不是感嘆。(C)「空梁」句是煬帝說的話，不是薛道衡臨刑明志。", "skill": "隱晦文本要「補空白」：把前因（不欲人出其右）和結尾的話連起來，推出沒有明說的動機。"}], "difficulty": "難", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-44", "exam": "hk107", "nums": [44, 45, 46], "form": "題組", "img": "img/hk107-44.png", "source": "《太平廣記‧青州客》（改寫）", "author": "李昉等編", "genre": "筆記小品", "types": ["虛詞句式", "句意理解", "寫作手法"], "passage": "朱梁時，青州有賈客泛海遇風，飄至一處，遠望有山川城郭。海師曰：「往昔遭風，未嘗至此。吾聞鬼國在是，莫非此耶？」頃之，舟至岸，因登岸，向城而去。其廬舍田畝，不殊中國。見人皆揖之，而人皆不見己。至城，有守門者，揖之，亦不應。入城，屋室人物甚殷，遂至王宮。正值大宴，群臣侍宴者數十，其器用絲竹陳設之類，多類中國。客因升殿，俯逼王座以窺之。俄而王有疾，左右扶還，亟召巫者視之。巫至，曰：「有陽地人至此，陽氣逼人，故王病。其人偶來爾，無心為祟，以飲食車馬謝遣之，可矣。」即具酒食，設座於別室，巫及其群臣皆來祀祝，客據案而食。俄有僕夫馭馬而至，客亦乘馬而歸，至岸登舟，國人竟不見己，復遇便風得歸。時賀德儉為青州節度，與魏博節度楊師厚有親，因遣此客使魏，其為師厚言之。魏人范宣古親聞其事，為余言。", "translation": "後梁時，青州有個商人出海遇到大風，漂到一個地方，遠遠望去有山川城郭。船師說：「以前遇到風暴，從沒到過這裡。我聽說鬼國就在這一帶，莫非就是這裡？」不久船靠岸，商人便上岸往城裡走去。那裡的房舍田地，和中原沒有兩樣。他看到人都向人作揖，可是別人都看不見他。到了城門，有守門的人，他作揖，守門人也沒有回應。進城後，房屋人物非常繁盛，於是走到王宮。正好遇上盛大宴會，陪宴的群臣有幾十人，器物、樂器、陳設等，大多和中原相似。商人就登上大殿，靠近王座窺看。不久國王生病，左右扶他回去，急忙召巫師來看。巫師到了說：「有陽間的人來到這裡，陽氣逼人，所以國王生病。這人只是偶然來到，並非有心作祟，用飲食車馬向他道謝並送他走就可以了。」於是準備酒食，在另一個房間設座，巫師和群臣都來祭拜祝禱，商人便靠著几案吃喝。不久有僕人駕馬而來，商人也就騎馬回去，到岸邊上船，那國的人始終看不見他，又遇到順風得以回家。當時賀德儉擔任青州節度使，和魏博節度使楊師厚是親戚，便派這個商人出使魏地，商人把這件事告訴楊師厚。魏人范宣古親耳聽到這件事，又告訴了我。", "keywords": [{"w": "賈客", "m": "商人"}, {"w": "泛海", "m": "航行海上"}, {"w": "海師", "m": "船師、掌舵的人"}, {"w": "頃之", "m": "不久"}, {"w": "不殊", "m": "沒有不同"}, {"w": "揖", "m": "拱手作揖行禮"}, {"w": "殷", "m": "眾多、繁盛"}, {"w": "俯逼", "m": "彎身靠近"}, {"w": "亟", "m": "急忙"}, {"w": "祟", "m": "鬼神作怪害人"}, {"w": "謝遣", "m": "道謝並送走"}, {"w": "據案", "m": "靠著几案"}, {"w": "便風", "m": "順風"}], "questions": [{"n": 44, "stem": "故事中雙底線處所省略的主詞，何者不是青州客？", "options": {"A": "向城而去", "B": "見人皆揖之", "C": "亦不應", "D": "復遇便風得歸"}, "answer": "C", "explain": "「至城，有守門者，揖之，亦不應」：作揖的是青州客，「亦不應」（也不回應）的是守門者，因為鬼國的人看不見青州客。(A)上岸往城裡走的是青州客。(B)看到人就作揖的是青州客，所以後面接「而人皆不見己」。(D)遇到順風回家的是青州客。", "skill": "省略主語題：在每個動作前補上「誰」，並用前後句的邏輯檢查（作揖的人和不回應的人必然不同）。"}, {"n": 45, "stem": "根據故事內容，下列敘述何者正確？", "options": {"A": "青州客登岸所見的房舍田畝，皆與中國不同", "B": "國王生病的原因是青州客接近王座窺探", "C": "巫師建議大肆祝祀並齋戒沐浴以接待青州客", "D": "青州客遠離時，王國中的人皆避而不見"}, "answer": "B", "explain": "青州客「俯逼王座以窺之」，接著王就生病，巫師說「陽氣逼人，故王病」，可知是青州客靠近王座造成的，選(B)。(A)原文是「不殊中國」，意思是和中原沒有不同。(C)巫師只建議「以飲食車馬謝遣之」，沒有齋戒沐浴。(D)「國人竟不見己」是始終看不見他，不是故意躲避。", "skill": "細節比對：留意否定詞（不殊＝相同）和「不見」的意思是『看不見』還是『不見面』。"}, {"n": 46, "stem": "文末「時賀德儉為青州節度，與魏博節度楊師厚有親，因遣此客使魏，其為師厚言之。魏人范宣古親聞其事，為余言。」這段文字的作用最可能是下列何者？", "options": {"A": "顯示作者的交遊廣闊", "B": "點出故事發生的地點", "C": "表明作者的身分、來歷", "D": "強調故事內容言而有據"}, "answer": "D", "explain": "這段交代故事的流傳過程：青州客告訴楊師厚，范宣古親耳聽到，再告訴作者。一層層說明消息來源，是要讓讀者相信這個奇遇是真的、有憑有據，選(D)。(A)只提到一位告訴他的人，不是炫耀交遊。(B)故事地點（鬼國）在前文已寫，這段寫的是後來的人事。(C)文中沒有交代作者的身分。", "skill": "筆記小說的結尾常交代「誰親眼見、誰親耳聞」，作用通常是增加可信度。"}], "difficulty": "中", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk107-47", "exam": "hk107", "nums": [47, 48], "form": "題組", "img": "img/hk107-47.png", "source": "蕭統〈陶淵明集序〉（改寫）", "author": "蕭統", "genre": "書信序跋", "types": ["句意理解", "文意推論"], "passage": "有疑陶淵明詩篇篇有酒，吾觀其意不在酒，亦寄酒為跡者也。其文章不群，辭采精拔，跌宕昭彰，獨超眾類，抑揚爽朗，莫之與京。橫素波而傍流，干青雲而直上。語時事則指而可想，論懷抱則曠而且真。加以貞志不休，安道苦節，不以躬耕為恥，不以無財為病。自非大賢篤志，孰能如此乎？余愛嗜其文，不能釋手，尚想其德，恨不同時。", "translation": "有人懷疑陶淵明的詩篇篇都有酒，我看他的用意並不在酒，也只是藉酒來寄託心跡罷了。他的文章不同流俗，辭采精妙出眾，起伏跌宕而鮮明，遠遠超越同類，抑揚頓挫、清朗通達，沒有人能和他相比。像白色的水波橫流而去，又像直上青雲。談論時事，能具體指陳而讓人想見；抒發懷抱，曠達而且真誠。再加上他堅守志節不懈，安於道義、刻苦守節，不以親自耕田為恥，不以沒有錢財為苦。如果不是大賢之人、志向堅定，誰能做到這樣呢？我非常喜愛他的文章，捨不得放手，想念他的德行，遺憾沒有和他生在同一個時代。", "keywords": [{"w": "寄酒為跡", "m": "藉酒寄託心跡"}, {"w": "不群", "m": "不同流俗、與眾不同"}, {"w": "精拔", "m": "精妙出眾"}, {"w": "京", "m": "齊等、相比"}, {"w": "干", "m": "沖上、觸及"}, {"w": "曠", "m": "曠達、開闊"}, {"w": "貞志不休", "m": "堅守志節不懈"}, {"w": "躬耕", "m": "親自耕種"}, {"w": "病", "m": "憂慮、苦惱"}, {"w": "自非", "m": "如果不是"}, {"w": "恨", "m": "遺憾"}], "questions": [{"n": 47, "stem": "根據本文，下列句意說明何者正確？", "options": {"A": "亦寄酒為跡者也——有酒之處必有陶淵明蹤跡", "B": "抑揚爽朗，莫之與京——文章起伏跌宕、清朗通達，無人能及", "C": "干青雲而直上——志向遠大，在仕途上也曾飛黃騰達", "D": "尚想其德，恨不同時——感嘆自己德行高潔卻生不逢時"}, "answer": "B", "explain": "「莫之與京」是「莫與之京」的倒裝，京＝齊等，意思是沒有人能和他相比；「抑揚爽朗」形容文章起伏有致、清朗通達，所以(B)正確。(A)「寄酒為跡」是藉酒寄託心志，不是到處都有他的蹤跡。(C)這句承接「其文章不群」，形容文章氣勢高遠，與仕途無關（陶淵明正是辭官歸隱）。(D)是作者懷想陶淵明的德行，遺憾沒和他同時代，不是說自己德行高潔。", "skill": "句意判斷先看「主語是誰」：(D)的「其」指陶淵明，不是作者自己；再注意否定句倒裝「莫之與京」。"}, {"n": 48, "stem": "根據本文，無法得知下列何者？", "options": {"A": "陶淵明詩多以酒為寫作題材", "B": "陶淵明詩文在當時獨樹一格", "C": "作者對陶淵明極為欣賞崇敬", "D": "後世文壇深受陶淵明的影響"}, "answer": "D", "explain": "全文只談陶淵明的作品與人品，以及作者的喜愛，沒有提到他對後世文壇的影響，所以選(D)。(A)「詩篇篇有酒」可知。(B)「其文章不群」「獨超眾類」可知。(C)「余愛嗜其文，不能釋手，尚想其德」可知。", "skill": "「無法得知」題：每個選項回原文找證據，找得到的刪去，剩下的就是答案。"}], "difficulty": "中", "label": "107年會考", "year": 107, "kind": "會考"}, {"id": "hk108-8", "exam": "hk108", "nums": [8], "form": "單題", "img": "img/hk108-8.png", "source": "出處待查", "author": "", "genre": "筆記小品", "types": ["句意理解"], "passage": "暇時引讀瑤篇，座前見水華木翠。夜裡趣摘章句，紙上有月白風清。", "translation": "閒暇時拿起美好的詩文來讀，座位前彷彿就看見清澈的水、盛開的花和青翠的樹木。夜裡興致一來摘錄文章中的好句子，紙上就有明月皎潔、清風徐來的景致。", "keywords": [{"w": "暇時", "m": "空閒的時候"}, {"w": "引", "m": "拿起、取來"}, {"w": "瑤篇", "m": "美好的詩文篇章"}, {"w": "水華木翠", "m": "水色清麗、樹木青翠"}, {"w": "趣", "m": "興致（一說通「促」，此取興致）"}, {"w": "摘章句", "m": "摘錄文章詞句"}], "questions": [{"n": 8, "stem": "「暇時引讀瑤篇，座前見水華木翠。夜裡趣摘章句，紙上有月白風清。」這段文字主要在描寫下列何種意趣？", "options": {"A": "跋涉山水，遍覽自然風光", "B": "閒暇遊逛園林，聆賞天籟之趣", "C": "開卷吟誦，書中自有雋雅美景", "D": "揮毫點染，筆下有無限清風明月"}, "answer": "C", "explain": "「引讀瑤篇」「摘章句」都在讀書，人坐在「座前」、對著「紙上」，卻看到水華木翠、月白風清，可見美景是從書中讀出來的，選(C)。(A)(B)作者並沒有真的出門遊山逛園，美景是想像中的。(D)「摘章句」是摘錄書中的句子，不是作畫揮毫。", "skill": "先找出人物實際在做什麼（讀、摘），再判斷那些景色是真實所見還是讀書所生的想像。"}], "difficulty": "易", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-15", "exam": "hk108", "nums": [15], "form": "單題", "img": "img/hk108-15.png", "source": "《論語》（選項分別出自〈學而〉、〈里仁〉、〈述而〉、〈學而〉）", "author": "孔子及其弟子", "genre": "經典語錄", "types": ["主旨寓意", "典故出處"], "passage": "(A)學而時習之，不亦說乎\n(B)人之過也，各於其黨。觀過，斯知仁矣\n(C)三人行，必有我師焉。擇其善者而從之，其不善者而改之\n(D)君子不重則不威，學則不固。主忠信。無友不如己者。過則勿憚改", "translation": "(A)學習之後時時溫習，不是很喜悅嗎？(B)人犯的過錯，各和他所屬的那類人有關；觀察一個人的過錯，就可以知道他是否有仁德。(C)幾個人一起走，其中一定有可以當我老師的人。選擇他們的優點來學習，看到他們的缺點就反省改正自己。(D)君子不莊重就沒有威嚴，所學也不穩固。要以忠誠信實為主，不和不如自己的人交朋友，有了過錯就不要怕改正。", "keywords": [{"w": "說", "m": "同「悅」，喜悅"}, {"w": "黨", "m": "類別、同類的人"}, {"w": "從", "m": "跟隨、學習"}, {"w": "重", "m": "莊重"}, {"w": "憚", "m": "害怕"}], "questions": [{"n": 15, "stem": "「我向默默耕耘者學習等待，也向堅持不懈者學習勇敢；我從高傲的人身上學會了彎腰，也從奢靡的人身上學到了簡樸。」這段文句最能呼應《論語》中的哪一段話？", "options": {"A": "學而時習之，不亦說乎", "B": "人之過也，各於其黨。觀過，斯知仁矣", "C": "三人行，必有我師焉。擇其善者而從之，其不善者而改之", "D": "君子不重則不威，學則不固。主忠信。無友不如己者。過則勿憚改"}, "answer": "C", "explain": "題幹前半向耕耘者、堅持者學習他們的優點（擇其善者而從之），後半從高傲、奢靡的人身上學到反面教訓、改正自己（其不善者而改之），正好對應(C)。(A)講學習後溫習的喜悅。(B)講從過錯觀察人的仁德。(D)講君子的莊重、忠信、交友與改過，都不是「向各種人學習」。", "skill": "把題幹拆成兩組（好榜樣／壞榜樣），找出同樣有『正面學、反面改』兩層結構的經典語句。"}], "difficulty": "易", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-17", "exam": "hk108", "nums": [17], "form": "單題", "img": "img/hk108-17.png", "source": "出處待查（傳統對聯）", "author": "", "genre": "其他", "types": ["文化常識", "寫作手法"], "passage": "若不撇開終是苦，各能捺住即成名。", "translation": "字面意思：「若」字如果不把撇畫撇出去，就終究是個「苦」字；「各」字如果能把捺畫收住，就成了「名」字。引申義：人如果不能把煩惱放開，終究痛苦；如果能按捺住自己、克制忍耐，就能成就名聲。", "keywords": [{"w": "撇", "m": "書法筆畫名；也指拋開、放下"}, {"w": "捺", "m": "書法筆畫名；也指按捺、克制"}, {"w": "終", "m": "終究"}, {"w": "即", "m": "就"}], "questions": [{"n": 17, "stem": "「若不撇開終是苦，各能捺住即成名。」關於這副對聯，下列說明何者正確？", "options": {"A": "上聯意謂人生苦短，應及時努力", "B": "下聯勉人要看破功名，隨遇而安", "C": "上、下聯的末字刻意不合平仄，以擴展意境", "D": "由「若」「苦」、「各」「名」的字形差異發想"}, "answer": "D", "explain": "「若」字下半部的撇不撇出去就像「苦」字；「各」字的捺收住不寫出就像「名」字，對聯正是由字形的筆畫差異發想，再借「撇開（放下）」「捺住（克制）」的雙關說道理，選(D)。(A)上聯說的是放不下就痛苦，不是人生苦短。(B)下聯說克制忍耐才能「成名」，不是看破功名。(C)對聯講究上聯末字仄聲、下聯末字平聲，「苦」仄、「名」平，正合規則。", "skill": "對聯題注意雙關：同一個詞（撇、捺）同時是書法筆畫和人生動作，兩層意思都要讀出來。"}], "difficulty": "中", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-19", "exam": "hk108", "nums": [19], "form": "單題", "img": "img/hk108-19.png", "source": "孫過庭《書譜》", "author": "孫過庭", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "學書之法，初學分布，但求平正；既知平正，務追險絕；既能險絕，復歸平正。初謂未及，中則過之，後乃通會。", "translation": "學習書法的方法：剛開始學字的結構布局，只求平穩端正；懂得平正之後，就一定要追求險峻奇絕的變化；能寫出險絕之後，再回到平正。最初是還沒達到，中間是做得太過，最後才能融會貫通。", "keywords": [{"w": "書", "m": "書法"}, {"w": "分布", "m": "字的結構布局"}, {"w": "但", "m": "只"}, {"w": "務", "m": "務必、一定要"}, {"w": "險絕", "m": "險峻奇絕的變化"}, {"w": "復", "m": "又、再"}, {"w": "通會", "m": "融會貫通"}], "questions": [{"n": 19, "stem": "「學書之法，初學分布，但求平正；既知平正，務追險絕；既能險絕，復歸平正。初謂未及，中則過之，後乃通會。」這段話的寫作用意，最可能是下列何者？", "options": {"A": "說明學習書法的不同階段與進境", "B": "強調練習書法時要有正確的心態", "C": "提醒常人不應追求艱難的書法技巧", "D": "指出書法的最高境界在於標新立異"}, "answer": "A", "explain": "「初學……既知……既能……」與「初……中……後……」都是按時間先後，說明學書法從平正到險絕再回到平正的三個階段，選(A)。(B)文中沒有談心態。(C)作者主張「務追險絕」，並不反對追求困難技巧。(D)最高境界是「復歸平正」「通會」，不是標新立異。", "skill": "看到「初、既、中、後、乃」這類表示順序的詞，文章多半在說明階段或過程。"}], "difficulty": "易", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-22", "exam": "hk108", "nums": [22], "form": "單題", "img": "img/hk108-22.png", "source": "真德秀〈跋祕閣太史范文公集〉（改寫）", "author": "真德秀", "genre": "書信序跋", "types": ["主旨寓意", "文意推論"], "passage": "諸葛武侯文采不豔，然其〈出師〉二表至今為學者膾炙，有志之士擊節讀之，有至於嗟嘆流涕者。六朝、隋、唐文人動輒百數十篇，穠華纖巧，極其雕飾，或卒無一語可傳。然則文之為文，豈必多且麗乎哉？", "translation": "諸葛亮的文章辭采並不華麗，但他的〈出師表〉前後兩篇到現在仍被讀書人傳誦稱讚，有志之士打著拍子誦讀，甚至有人感嘆流淚。六朝、隋、唐的文人動不動就寫上百篇，文辭濃豔纖巧、極力雕琢修飾，有的最後卻沒有一句話能流傳下來。這樣看來，文章之所以成為好文章，難道一定要寫得多而且華麗嗎？", "keywords": [{"w": "豔", "m": "華麗"}, {"w": "膾炙", "m": "比喻詩文受人稱讚傳誦"}, {"w": "擊節", "m": "打拍子，表示讚賞"}, {"w": "動輒", "m": "動不動就"}, {"w": "穠華纖巧", "m": "濃豔華麗、纖細精巧"}, {"w": "卒", "m": "最終"}, {"w": "然則", "m": "既然如此，那麼"}], "questions": [{"n": 22, "stem": "「諸葛武侯文采不豔，然其〈出師〉二表至今為學者膾炙，有志之士擊節讀之，有至於嗟嘆流涕者。六朝、隋、唐文人動輒百數十篇，穠華纖巧，極其雕飾，或卒無一語可傳。然則文之為文，豈必多且麗乎哉？」根據這段文字，下列何者最符合作者的觀點？", "options": {"A": "文章之優劣，取決於作者的學識修養與文采表現", "B": "寫作不宜過度雕章琢句，當以抒發情志、感動人心為佳", "C": "六朝文人多投注心力於雕飾辭藻，以致作品質精而量少", "D": "諸葛武侯文采不豔，唯〈出師〉二表典麗華美，膾炙人口"}, "answer": "B", "explain": "作者拿兩者對比：諸葛亮文采不華麗，卻能讓人嗟嘆流涕；六朝隋唐文人雕飾華麗、數量多，卻沒有一句流傳。結尾反問「豈必多且麗」，主張文章重在真情感人，不在華麗，選(B)。(A)作者正是認為文采不是關鍵。(C)原文說六朝文人「動輒百數十篇」，是量多質差。(D)〈出師表〉的特色是「文采不豔」，不是典麗華美。", "skill": "對比結構＋結尾反問：作者用反問句否定的東西（多且麗），就是他反對的；正面例子代表他的主張。"}], "difficulty": "中", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-23", "exam": "hk108", "nums": [23], "form": "單題", "img": "img/hk108-23.png", "source": "出處待查（南唐君臣軼事）", "author": "", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "金陵城北有湖，名園勝境，掩映如畫。一日，諸臣待漏朝堂，語及林泉之事，坐間馮謐舉唐玄宗賜賀知章三百里鏡湖，曰：「予非敢望此，但賜後湖，亦暢予平生也。」吏部徐鉉怡聲而對曰：「主上尊賢待士，常恐不及，豈惜一後湖？所乏者知章爾。」馮大有慚色。", "translation": "金陵城北邊有座湖，名園美景互相掩映，像圖畫一樣。有一天，大臣們在朝堂等候上朝，談到山林泉水的事，座中馮謐舉出唐玄宗把三百里鏡湖賞賜給賀知章的故事，說：「我不敢奢望這樣，只要能賞給我後湖，也就讓我這輩子心滿意足了。」吏部的徐鉉和顏悅色地回答：「皇上尊重賢才、禮待士人，常怕做得不夠，哪裡會捨不得一座後湖？缺少的只是賀知章那樣的人罷了。」馮謐聽了非常慚愧。", "keywords": [{"w": "待漏", "m": "古代群臣聽漏刻等候入朝"}, {"w": "坐間", "m": "在座之中"}, {"w": "望", "m": "奢望"}, {"w": "但", "m": "只要"}, {"w": "暢", "m": "使……舒暢、滿足"}, {"w": "怡聲", "m": "聲音和悅"}, {"w": "乏", "m": "缺少"}], "questions": [{"n": 23, "stem": "根據本文，下列敘述何者正確？", "options": {"A": "徐鉉覺得馮謐之才不及賀知章", "B": "徐鉉安慰馮謐他日終將獲得賞賜", "C": "徐鉉認為三百里鏡湖應賞賜給馮謐", "D": "徐鉉暗示馮謐應知所進退、歸隱山林"}, "answer": "A", "explain": "徐鉉說皇上不會捨不得一座湖，「所乏者知章爾」——缺的是像賀知章那樣的人才。言下之意是馮謐不是賀知章，配不上這樣的賞賜，所以馮謐「大有慚色」，選(A)。(B)(C)徐鉉是在諷刺，不是安慰或支持。(D)他沒有勸馮謐歸隱。", "skill": "聽懂「話中有話」：從聽者的反應（大有慚色）反推說話者其實是在委婉諷刺。"}], "difficulty": "中", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-27", "exam": "hk108", "nums": [27], "form": "單題", "img": "img/hk108-27.png", "source": "《國語‧晉語九》", "author": "", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "趙簡子問於壯馳茲曰：「東方之士孰為愈？」壯馳茲曰：「敢賀！」簡子曰：「未應吾問，何賀？」對曰：「臣聞之：國家將興也，君子自以為不足；其亡也，若有餘。今子任晉國之政，而問及小人，又求賢人，吾是以賀。」", "translation": "趙簡子問壯馳茲說：「東方的士人誰最高明？」壯馳茲說：「恭喜您！」趙簡子說：「你還沒回答我的問題，恭喜什麼？」壯馳茲回答：「我聽說：國家將要興盛時，君子總覺得自己不足；國家將要滅亡時，（在位者）好像覺得自己什麼都綽綽有餘。現在您主持晉國政事，卻向我這樣地位低微的人請教，又尋求賢人，所以我向您道賀。」", "keywords": [{"w": "孰", "m": "誰"}, {"w": "愈", "m": "高明、勝過"}, {"w": "敢賀", "m": "冒昧地祝賀（謙詞）"}, {"w": "任", "m": "擔任、主持"}, {"w": "小人", "m": "地位低微的人（壯馳茲自謙）"}, {"w": "是以", "m": "因此"}], "questions": [{"n": 27, "stem": "根據這段文字，趙簡子之所以得到壯馳茲的祝賀，其原因最可能是下列何者？", "options": {"A": "取得晉國執政權", "B": "能明辨小人與賢人", "C": "具備禮賢下士的態度", "D": "已找到東方最好的謀士"}, "answer": "C", "explain": "壯馳茲說國家將興時君子「自以為不足」，而趙簡子身居高位，還肯向地位低的人請教、又訪求賢人，正是謙虛求賢、禮賢下士，所以值得祝賀，選(C)。(A)祝賀的不是他掌權，而是他掌權後的態度。(B)「問及小人」的小人是壯馳茲自謙，不是在分辨小人賢人。(D)他還在詢問誰高明，並沒有找到謀士。", "skill": "看「是以」「故」前面的句子：『吾是以賀』之前就是祝賀的理由。"}], "difficulty": "中", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-28", "exam": "hk108", "nums": [28], "form": "單題", "img": "img/hk108-28.png", "source": "《禮記‧表記》", "author": "", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "君子不以口譽人，則民盡忠勸善。故君子問人之寒則衣之，問人之飢則食之，稱人之美則爵之。", "translation": "君子不只用嘴巴稱讚人，人民就會盡心忠誠、勉勵向善。所以君子問到別人寒冷，就給他衣服穿；問到別人飢餓，就給他東西吃；稱讚別人的美德，就給他官位。", "keywords": [{"w": "譽", "m": "稱讚"}, {"w": "勸", "m": "勉勵"}, {"w": "衣", "m": "給……衣服穿（名詞作動詞，音ㄧˋ）"}, {"w": "食", "m": "給……吃（音ㄙˋ）"}, {"w": "爵", "m": "予以官位"}], "questions": [{"n": 28, "stem": "「君子不以口譽人，則民盡忠勸善。故君子問人之寒則衣之，問人之飢則食之，稱人之美則爵之。」由這段話可知，為政者對待人民的原則應是下列何者？", "options": {"A": "循循善誘的教化", "B": "公平公正的賞罰", "C": "無微不至的關懷", "D": "具體實惠的行動"}, "answer": "D", "explain": "「不以口譽人」是不只說好聽話，後面三句都是「問了就做」：冷了給衣、餓了給食、稱讚就給官位，強調要有具體實惠的行動，選(D)。(A)文中沒有談教導。(B)只有給予，沒有談處罰與公平。(C)重點不在關懷問候本身，而在問候之後一定落實為行動。", "skill": "注意名詞當動詞（衣之、食之、爵之），三個動作的共同點就是文章要表達的原則。"}], "difficulty": "中", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-29", "exam": "hk108", "nums": [29], "form": "單題", "img": "img/hk108-29.png", "source": "《史記‧孝文本紀》", "author": "司馬遷", "genre": "史傳人物", "types": ["虛詞句式", "字詞解釋"], "passage": "古之治天下，朝有進善之旌，誹謗之木，所以通治道而來諫者。今法有誹謗妖言之罪，是使眾臣不敢盡情，而上無由聞過失也。將何以來遠方之賢良？其除之。", "translation": "古代治理天下，朝廷設有讓人進獻善言的旗幟、讓人書寫批評的木柱，用來暢通治國之道、招來進諫的人。現在法律有「誹謗妖言」的罪名，這使得群臣不敢說出真心話，君主也無從聽到自己的過失。這樣又要怎麼招來遠方的賢良之士呢？應該廢除這條法令。", "keywords": [{"w": "旌", "m": "旗幟"}, {"w": "誹謗之木", "m": "讓百姓書寫批評意見的木柱"}, {"w": "所以", "m": "用來"}, {"w": "來", "m": "使……前來、招來"}, {"w": "盡情", "m": "說出全部真心話"}, {"w": "無由", "m": "沒有途徑"}, {"w": "其", "m": "表示命令、期望的語氣，應該"}], "questions": [{"n": 29, "stem": "「古之治天下，朝有進善之旌，誹謗之木，所以通治道而來諫者。今法有誹謗妖言之罪，是使眾臣不敢盡情，而上無由聞過失也。將何以來遠方之賢良？其除之。」文中「其除之」的「之」字所代稱的對象為何？", "options": {"A": "進善之旌", "B": "誹謗之木", "C": "誹謗妖言之罪", "D": "遠方之賢良"}, "answer": "C", "explain": "文章批評「今法有誹謗妖言之罪」會讓臣子不敢說話、君主聽不到過失，所以要廢除的是這條罪名，選(C)。(A)(B)進善之旌、誹謗之木是古代的好制度，作者讚許，不會要廢除。(D)遠方賢良是要招來的人，不是要除去的。", "skill": "代詞指代題：先判斷作者對每個名詞的態度，『要去除的』一定是作者批評的那一項。"}], "difficulty": "易", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-32", "exam": "hk108", "nums": [32], "form": "單題", "img": "img/hk108-32.png", "source": "出處待查（蘇軾論歐陽脩語）", "author": "蘇軾", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "東坡云：「歐公喜古人『竹徑通幽處，禪房花木深』、『柳塘春水漫，花塢夕陽遲』，自言終身學不能到。此固佳句，特鳳凰一毛耳。公之才若垂天之雲，彼何足道？豈厭八珍乃喜螺蛤耶？」", "translation": "蘇東坡說：「歐陽脩喜愛古人『竹徑通幽處，禪房花木深』『柳塘春水漫，花塢夕陽遲』這些詩句，自己說一輩子都學不到這種程度。這些固然是好句子，但只是鳳凰身上的一根羽毛罷了。歐公的才華像垂掛天邊的大片雲彩，那些句子哪值得一提？難道是吃膩了山珍海味，反而喜歡起螺蛤這種小東西嗎？」", "keywords": [{"w": "固", "m": "固然、本來"}, {"w": "特", "m": "只是"}, {"w": "鳳凰一毛", "m": "比喻珍貴事物中極小的一部分"}, {"w": "垂天之雲", "m": "垂掛天際的大雲，比喻才華廣大"}, {"w": "何足道", "m": "哪裡值得一提"}, {"w": "八珍", "m": "珍貴的美食"}, {"w": "厭", "m": "吃膩、滿足"}], "questions": [{"n": 32, "stem": "根據這段文字，下列何者與東坡的看法最接近？", "options": {"A": "詩文創作應該力求質樸，不求精鍊", "B": "歐公謙沖為懷，其實才華洋溢，遠勝古人", "C": "前人「竹徑」、「柳塘」之句境界高雅，歐公不能及", "D": "由歐公喜「竹徑」、「柳塘」句可知，文人難免敝帚自珍"}, "answer": "B", "explain": "歐陽脩自謙學不到古人佳句，東坡卻說那些句子只是「鳳凰一毛」，歐公的才華「若垂天之雲」，喜歡那些句子就像吃膩八珍反愛螺蛤，可見東坡認為歐公是謙虛，才華遠勝古人，選(B)。(A)文中沒有談質樸與精鍊。(C)這是歐公自己的說法，東坡並不同意。(D)敝帚自珍是珍惜自己的東西，歐公喜歡的是古人的詩句。", "skill": "分清「誰的看法」：題目問東坡，就要找東坡反駁或評價的話，不能把引述的他人說法當成答案。"}], "difficulty": "中", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-33", "exam": "hk108", "nums": [33], "form": "單題", "img": "img/hk108-33.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["句意理解", "寫作手法"], "passage": "學不得法，猶願魚而無網，心雖勤而無獲；若得其要，猶順流馭舟，體不勞而致遠。", "translation": "學習不得方法，就像想要魚卻沒有網，心裡雖然勤奮卻沒有收穫；如果掌握了要領，就像順著水流駕船，身體不勞累卻能到達遠方。", "keywords": [{"w": "法", "m": "方法"}, {"w": "猶", "m": "好像"}, {"w": "願", "m": "想要"}, {"w": "要", "m": "要領、關鍵"}, {"w": "馭", "m": "駕駛"}, {"w": "致遠", "m": "到達遠方"}], "questions": [{"n": 33, "stem": "「學不得法，猶願魚而無網，心雖勤而無獲；若得其要，猶順流馭舟，＿＿＿＿。」根據文意，畫線處填入下列何者最恰當？", "options": {"A": "心不知其所往", "B": "氣不礙其暢達", "C": "意不盡而有餘", "D": "體不勞而致遠"}, "answer": "D", "explain": "前後兩句是對照：不得法→「心雖勤而無獲」（費力卻沒結果）；得法→應該是「不費力卻有成果」。順流駕船本來就是省力又走得遠，所以填「體不勞而致遠」，選(D)，與「心雖勤而無獲」字數、句式也對稱。(A)不知去向與「得其要」矛盾。(B)(C)談氣勢、意境，和比喻（駕舟）及前句的對照都接不上。", "skill": "填空題找對偶：上句「心雖勤而無獲」對應下句，挑一個意思相反、句式相同的選項。"}], "difficulty": "易", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-34", "exam": "hk108", "nums": [34], "form": "單題", "img": "img/hk108-34.png", "source": "梁啟超〈盆景〉（改寫，引王鏊《姑蘇志》、劉鑾《五石瓠》）", "author": "梁啟超", "genre": "筆記小品", "types": ["句意理解", "文意推論"], "passage": "據說盆景始於漢、唐，盛於兩宋。明朝吳縣人王鏊作《姑蘇志》有云：「虎丘人善於盆中植奇花異卉，盤松古梅，置之几案，清雅可愛，謂之盆景。」是姑蘇不僅擅園林之美，且以盆景之製作馳譽於一時。劉鑾《五石瓠》：「吾人以盆盎間樹石為玩，長者屈而短之，大者削而約之，或膚寸而結果實，或咫尺而蓄蟲魚，蓋稱盆景，元人謂之些子景。」些子大概是元人語，細小之意。", "translation": "據說盆景起源於漢、唐，興盛於兩宋。明朝吳縣人王鏊寫《姑蘇志》說：「虎丘人擅長在盆中種植奇花異草，盤曲的松樹、古老的梅樹，放在几案上，清雅可愛，稱為盆景。」可見姑蘇不只擅長園林之美，還以製作盆景聞名一時。劉鑾《五石瓠》說：「我們拿盆裡的樹石當作賞玩之物，長的就彎曲使它變短，大的就削減使它變小，有的只有幾寸大就能結果實，有的方寸之間就能養蟲魚，這就叫盆景，元朝人稱它為些子景。」「些子」大概是元朝人的用語，是細小的意思。", "keywords": [{"w": "几案", "m": "桌子"}, {"w": "是", "m": "這，指上述情形"}, {"w": "擅", "m": "擅長"}, {"w": "馳譽", "m": "名聲遠播"}, {"w": "盆盎", "m": "盆子"}, {"w": "屈", "m": "使彎曲"}, {"w": "約", "m": "使縮小"}, {"w": "膚寸", "m": "極短的長度"}, {"w": "咫尺", "m": "很近、很小的範圍"}, {"w": "蓋", "m": "大概（發語詞）"}], "questions": [{"n": 34, "stem": "根據這段文字，下列敘述何者正確？", "options": {"A": "王鏊始創盆景，虎丘人稱美其作品清雅可愛", "B": "元朝人劉鑾稱盆景為些子景，取其細小之意", "C": "姑蘇人不擅營造園林之美，但以製作盆景馳名", "D": "古人多以屈長削大的方式製作盆景，求其精巧"}, "answer": "D", "explain": "《五石瓠》說「長者屈而短之，大者削而約之」，在很小的空間結果實、養蟲魚，正是用屈長削大的方式追求精巧，選(D)。(A)盆景始於漢唐，王鏊只是在《姑蘇志》記載虎丘人的盆景，不是創始者。(B)稱「些子景」的是「元人」，劉鑾只是引述。(C)原文是「不僅擅園林之美」，可見姑蘇擅長園林。", "skill": "人名、朝代、地名多的文本：逐一確認「誰說的」「誰做的」，選項常把引述者和被引述者對調。"}], "difficulty": "難", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-39", "exam": "hk108", "nums": [39, 40], "form": "題組", "img": "img/hk108-39.png", "source": "謝邦振〈徐霞客 穿越古今五百年〉（改寫，引潘耒語、徐霞客語）", "author": "謝邦振", "genre": "山水遊記", "types": ["比較閱讀", "人物情感"], "passage": "清人潘耒形容徐霞客：「途窮不憂，行誤不悔，瞑則寢樹石之間，飢則啖草木之實，不避風雨，不憚虎狼，不計程期，不求伴侶，以性靈遊，以軀命遊，亙古以來，一人而已。」徐霞客曾在旅途中遭土匪洗劫一空，友死心慟，有人勸他返鄉，他仍堅定的說：「吾荷一鍤來，何處不可埋吾骨耶？」", "translation": "潘耒形容徐霞客：「路走到盡頭也不憂愁，走錯了路也不後悔，想睡就睡在樹下石間，餓了就吃草木的果實，不躲避風雨，不害怕虎狼，不計較路程時間，不尋求同伴，用整個心靈去旅遊，用生命去旅遊，從古到今，只有他一個人而已。」徐霞客說：「我扛著一把鏟子來，哪裡不能埋葬我的骨頭呢？」", "keywords": [{"w": "途窮", "m": "路走到盡頭"}, {"w": "瞑", "m": "通「眠」，睡覺"}, {"w": "啖", "m": "吃"}, {"w": "憚", "m": "害怕"}, {"w": "程期", "m": "路程與日期"}, {"w": "亙古", "m": "自古以來"}, {"w": "荷", "m": "扛、背負"}, {"w": "鍤", "m": "鍬、鏟子"}], "questions": [{"n": 39, "stem": "根據本文，關於《徐霞客遊記》與其他晚明文人遊記的比較，下列敘述何者錯誤？", "options": {"A": "二者皆有因景而生、繁華夢醒的末代感傷", "B": "二者皆為旅遊風氣之下的產物，遊必有記", "C": "前者為多方探遊的記錄，後者多為定點描述", "D": "前者主人翁常涉險阻，後者主人翁多就近尋訪"}, "answer": "A", "explain": "文中說「因景而生的末代感傷，恍惚驚愕，繁華夢醒」是張岱、袁宏道等小品的特色，接著說《徐霞客遊記》「很不一樣」，記錄的是人文風俗、地質奇貌等，所以說「二者皆有」末代感傷是錯的，選(A)。(B)都在晚明「旅遊風氣很盛，遊必有記」之下產生。(C)徐霞客足跡遍及大江南北，小品則是「短程定點旅遊」。(D)徐霞客翻山越嶺、遭遇土匪，小品作者則多短程就近遊覽。", "skill": "比較題先畫出對照表：A文特色／B文特色，再檢查選項是否把一方的特色套到雙方身上。"}, {"n": 40, "stem": "文中哪一句最可以看出徐霞客豁達的生命態度？", "options": {"A": "翻山越嶺、過河渡湍", "B": "瞑則寢樹石之間，飢則啖草木之實", "C": "不計程期，不求伴侶", "D": "吾荷一鍤來，何處不可埋吾骨耶"}, "answer": "D", "explain": "「我扛著鏟子來，哪裡不能埋我的骨頭」表示他早已把生死置之度外，即使死在旅途也無所謂，最能看出豁達的生命態度，選(D)。(A)表現勇氣與行動力。(B)表現吃苦耐勞、隨遇而安的生活方式。(C)表現獨立、不受時間拘束，都還沒有談到面對生死的態度。", "skill": "「生命態度」通常要看人物怎麼面對生死或重大挫折，找出談到生死的那一句。"}], "difficulty": "中", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-45", "exam": "hk108", "nums": [45, 46], "form": "題組", "img": "img/hk108-45.png", "source": "方回〈路傍草〉（改寫）", "author": "方回", "genre": "古典詩詞曲", "types": ["詩詞賞析", "主旨寓意", "寫作手法"], "passage": "野火燎荒原，霜雪日皜皜。牛羊無可噍，眾綠就枯槁。天地心不泯，根芽蟄深杳。春風一披拂，顏色還媚好。如何被兵地，黎庶不自保。高門先破碎，大屋例傾倒。間或遇茅舍，呻吟遺稚老。常恐馬蹄響，無罪被擒討。逃奔深谷中，又懼虎狼咬。一朝稍甦息，追胥復紛擾。人生值艱難，不如路傍草。", "translation": "野火焚燒荒原，霜雪一天比一天潔白。牛羊沒有東西可吃，所有綠草都枯萎了。但天地生養萬物的心意不會消失，草根新芽深深藏在地下。春風一吹拂，草色又恢復得美好。為什麼遭受兵禍的地方，百姓卻保不住自己？高大的門第先被破壞，大房子一概倒塌。偶爾遇到茅屋，只剩下呻吟的孩童和老人。常常害怕聽到馬蹄聲，無罪也會被抓走、被討伐。逃到深谷之中，又害怕被虎狼咬。好不容易稍微喘口氣，催討賦稅的小吏又來騷擾。人生碰上艱難的時代，還不如路旁的野草。", "keywords": [{"w": "燎", "m": "焚燒"}, {"w": "皜皜", "m": "潔白的樣子"}, {"w": "噍", "m": "嚼、吃"}, {"w": "就", "m": "趨向、變成"}, {"w": "泯", "m": "消滅"}, {"w": "蟄", "m": "伏藏"}, {"w": "披拂", "m": "吹拂"}, {"w": "被兵", "m": "遭受兵禍"}, {"w": "黎庶", "m": "百姓"}, {"w": "例", "m": "一概、照例"}, {"w": "遺", "m": "留下"}, {"w": "甦息", "m": "喘息、恢復元氣"}, {"w": "追胥", "m": "催徵賦稅的小吏"}], "questions": [{"n": 45, "stem": "關於本詩的分析，下列敘述何者錯誤？", "options": {"A": "是一韻到底的五言古詩", "B": "可歸類為社會寫實派的作品", "C": "通篇使用倒敘手法追述沿途所見", "D": "內容包含戰亂與官吏壓迫的描述"}, "answer": "C", "explain": "詩先寫野草被燒卻能春風再生，再寫戰亂地區百姓的苦難，最後以「不如路傍草」對照作結，是按順序鋪陳的對比寫法，沒有倒敘，選(C)。(A)每句五字、句數不限，偶數句押韻（皜、槁、杳、好、保、倒、老、討、咬、擾、草）一韻到底，是五言古詩。(B)描寫百姓在亂世中的真實苦難，屬社會寫實。(D)「被兵」「馬蹄響」是戰亂，「追胥復紛擾」是官吏壓迫。", "skill": "判斷倒敘要看有沒有「先寫結果或現在，再回頭寫過去」；只是先寫草、再寫人，是對比不是倒敘。"}, {"n": 46, "stem": "本詩的主旨最可能是下列何者？", "options": {"A": "與其羨慕路傍草，不如勇於面對人生困境", "B": "嚴冬野草尚有生機，人在亂世卻難以生存", "C": "人當學習野草深植其根、燎而復生的精神", "D": "讚賞路傍草隨遇而安，高門茅舍皆可生長"}, "answer": "B", "explain": "詩人拿野草和百姓對比：野草被火燒、霜雪摧殘，春風一吹又能復生；百姓在戰亂與苛吏之下卻「不自保」，結尾「人生值艱難，不如路傍草」，感嘆人在亂世連野草都不如，選(B)。(A)(C)詩中沒有勉勵人學習或面對困境，而是哀嘆。(D)「高門」「茅舍」寫的是人的居所遭破壞，不是野草生長的地方。", "skill": "詠物詩的主旨常在結尾：找出「物」與「人」的對比，再看最後一句的感嘆落在哪裡。"}], "difficulty": "中", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk108-47", "exam": "hk108", "nums": [47, 48], "form": "題組", "img": "img/hk108-47.png", "source": "【甲】《資治通鑑‧魏紀九》；【乙】《世說新語‧方正》（皆改寫）", "author": "司馬光；劉義慶", "genre": "史傳人物", "types": ["比較閱讀", "文意推論", "句意理解"], "passage": "【甲】司馬昭專權，帝欲殺之，反為賈充、成濟所害。昭入殿中，召群臣會議。尚書左僕射陳泰不至，昭使其舅尚書荀顗召之，泰曰：「世之論者以泰方於舅，今舅不如泰也。」子弟內外咸共逼之，乃入，見昭，悲慟，昭亦對之泣曰：「卿何以處我？」泰曰：「獨有斬賈充，少可以謝天下耳。」昭久之曰：「卿更思其次。」泰曰：「惟有進於此，不知其次。」昭乃不復更言。\n【乙】帝崩，內外喧譁。司馬昭問陳泰曰：「何以靜之？」泰云：「唯殺賈充以謝天下。」昭曰：「可復下此否？」對曰：「但見其上，未見其下。」", "translation": "【甲】司馬昭獨攬大權，魏帝想殺他，反而被賈充、成濟殺害。司馬昭進入殿中，召集群臣商議。尚書左僕射陳泰沒有來，司馬昭派陳泰的舅舅尚書荀顗去叫他，陳泰說：「世人議論都把我和舅舅相提並論，現在看來舅舅比不上我了。」家中子弟內外都一起逼他，他才入宮，見到司馬昭，非常悲痛，司馬昭也對著他哭，說：「你要怎麼處置我？」陳泰說：「只有斬了賈充，才稍微可以向天下謝罪。」司馬昭過了很久說：「你再想想次一等的辦法。」陳泰說：「我只想得到比這更重的，想不到更輕的。」司馬昭於是不再說話。\n【乙】魏帝死後，朝廷內外一片喧嘩。司馬昭問陳泰：「要怎麼平息？」陳泰說：「只有殺了賈充來向天下謝罪。」司馬昭說：「能不能比這輕一點？」陳泰回答：「我只看到比這更重的，沒看到比這更輕的。」", "keywords": [{"w": "方", "m": "比擬、相提並論"}, {"w": "咸", "m": "都"}, {"w": "悲慟", "m": "極為悲痛"}, {"w": "卿", "m": "君對臣的稱呼，你"}, {"w": "處", "m": "處置"}, {"w": "謝", "m": "謝罪"}, {"w": "更", "m": "再"}, {"w": "進於此", "m": "比這更進一步（更重）"}, {"w": "崩", "m": "帝王死亡"}, {"w": "下此", "m": "比這更輕"}], "questions": [{"n": 47, "stem": "關於甲篇中的人物，下列推論何者最恰當？", "options": {"A": "賈充是司馬昭陣營的人馬", "B": "陳泰為了救荀顗而見司馬昭", "C": "司馬昭與陳泰因權臣橫行而對泣", "D": "眾人認為陳泰應比荀顗早一步進宮"}, "answer": "A", "explain": "魏帝想殺司馬昭，卻「反為賈充、成濟所害」，賈充替司馬昭殺了皇帝；後來司馬昭不願斬賈充，一再要陳泰想「其次」的辦法，可見賈充是司馬昭的人，選(A)。(B)陳泰入宮是被子弟所逼，不是救荀顗。(C)兩人哭是因為皇帝被殺（悲慟），而權臣其實就是司馬昭自己。(D)「世之論者以泰方於舅」是把陳泰和荀顗相比，與進宮先後無關；陳泰說「今舅不如泰」是批評舅舅替司馬昭跑腿。", "skill": "人物關係題：從「誰替誰做事」「誰保護誰」推出陣營，不要只看表面的哭泣與客套。"}, {"n": 48, "stem": "根據甲篇內容，可推測乙篇陳泰所言「但見其上，未見其下」的涵義最可能是下列何者？", "options": {"A": "指出賈充屢獲晉升卻未曾被貶官", "B": "認為殺賈充是最起碼的處置方式", "C": "批評司馬昭遇事時未能顧及下屬", "D": "諷刺司馬昭只知媚上卻無法服眾"}, "answer": "B", "explain": "甲篇中司馬昭要陳泰「更思其次」（想個輕一點的辦法），陳泰答「惟有進於此，不知其次」——只有比殺賈充更重的，沒有更輕的。對照乙篇，「上」指更重的處置，「下」指更輕的處置，意思是殺賈充已是最低限度，選(B)。言下之意，更重的處置甚至會牽涉到司馬昭本人。(A)(C)(D)把「上、下」誤解為官位或上司下屬。", "skill": "兩篇對讀：用甲篇較清楚的句子（進於此／其次）去解釋乙篇較濃縮的句子（其上／其下）。"}], "difficulty": "難", "label": "108年會考", "year": 108, "kind": "會考"}, {"id": "hk109-11", "exam": "hk109", "nums": [11], "form": "單題", "img": "img/hk109-11.png", "source": "白居易〈負冬日〉", "author": "白居易", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "杲杲冬日出，照我屋南隅。負暄閉目坐，和氣生肌膚。初似飲醇醪，又如蟄者蘇。外融百骸暢，中適一念無。曠然忘所在，心與虛空俱。", "translation": "明亮的冬日升起，照在我屋子的南邊角落。我背對著太陽閉眼坐著，溫和的暖氣在肌膚間生起。起初像喝了美酒，又像冬眠的動物甦醒過來。身體外面暖融融的，全身骨骼都舒暢；心裡安適，一個雜念也沒有。心胸開闊得忘了自己身在何處，心靈和廣大的虛空融為一體。", "keywords": [{"w": "杲杲", "m": "日光明亮"}, {"w": "隅", "m": "角落"}, {"w": "負暄", "m": "背對太陽曬暖"}, {"w": "醇醪", "m": "美酒"}, {"w": "蟄者", "m": "冬眠的動物"}, {"w": "蘇", "m": "甦醒"}, {"w": "百骸", "m": "全身骨骼，指全身"}, {"w": "適", "m": "安適"}, {"w": "曠然", "m": "開闊的樣子"}, {"w": "俱", "m": "在一起"}], "questions": [{"n": 11, "stem": "「杲杲冬日出，照我屋南隅。負暄閉目坐，和氣生肌膚。初似飲醇醪，又如蟄者蘇。外融百骸暢，中適一念無。曠然忘所在，心與虛空俱。」關於這首詩的分析，下列敘述何者正確？", "options": {"A": "本詩為一韻到底的五言律詩", "B": "以飲美酒比喻午後昏昏欲睡的狀態", "C": "描寫層次由外而內，鋪陳歡聚之樂", "D": "呈現冬日曬太陽時，閒適自得的心境"}, "answer": "D", "explain": "全詩寫冬天坐著曬太陽，身體溫暖舒暢，心中無雜念，最後物我兩忘，呈現閒適自得的心境，選(D)。(A)全詩十句，律詩必為八句，所以是五言古詩。(B)「冬日出」是早上，而且飲醇醪比喻的是溫暖舒暢的感覺，不是昏昏欲睡。(C)由肌膚、百骸到內心，的確由外而內，但詩人是「閉目坐」獨自享受，沒有歡聚。", "skill": "詩體判斷先數句數（律詩八句、絕句四句）；再把選項拆成兩半逐一檢查，一半錯就整個錯。"}], "difficulty": "中", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-16", "exam": "hk109", "nums": [16], "form": "單題", "img": "img/hk109-16.png", "source": "段成式《酉陽雜俎》", "author": "段成式", "genre": "筆記小品", "types": ["句意理解", "文意推論"], "passage": "荊州街子葛清，自頸以下，遍刺白居易舍人詩。荊客陳至呼觀之，令其自解，背上亦能暗記。反手指其札處，至「不是花中偏愛菊」，則有一人持杯臨菊叢。又「黃夾纈林寒有葉」，則指一樹，樹上掛纈，纈上花紋極細。凡刻三十餘首，體無完膚，陳至贊為「白舍人行詩圖」也。", "translation": "荊州街頭的少年葛清，從脖子以下，全身都刺滿白居易的詩。荊州人陳至叫他來觀看，讓他自己解說，連背上的詩句他也能背出來。他反手指著刺青的地方，說到「不是花中偏愛菊」，就有一個人拿著酒杯靠近菊花叢的圖。又如「黃夾纈林寒有葉」，就指著一棵樹，樹上掛著印花絲織品，花紋極其細緻。總共刺了三十多首，全身沒有一塊完好的皮膚，陳至稱讚它是「白舍人行詩圖」。", "keywords": [{"w": "街子", "m": "街頭少年"}, {"w": "遍", "m": "全、到處"}, {"w": "刺", "m": "刺青"}, {"w": "呼", "m": "叫來"}, {"w": "自解", "m": "自己解說"}, {"w": "札", "m": "刺（指刺青處）"}, {"w": "纈", "m": "印染花紋的絲織品"}, {"w": "凡", "m": "總共"}, {"w": "贊", "m": "稱讚"}], "questions": [{"n": 16, "stem": "根據這段文字，下列關於葛清的敘述，何者正確？", "options": {"A": "刺青內容取自白詩", "B": "獲贈白舍人行詩圖", "C": "主動展示身上的圖文", "D": "詩句圖文皆刺在背部"}, "answer": "A", "explain": "「遍刺白居易舍人詩」，刺青內容就是白居易的詩，選(A)。(B)「白舍人行詩圖」是陳至稱讚葛清身上刺青的說法，不是一幅被送給他的畫。(C)是陳至「呼觀之」，叫他來看，不是葛清主動展示。(D)「自頸以下」「體無完膚」，全身都有，不只背部。", "skill": "留意動作是誰發起的（陳至呼、令），以及「贊為」是稱讚為，不是贈送。"}], "difficulty": "易", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-18", "exam": "hk109", "nums": [18], "form": "單題", "img": "img/hk109-18.png", "source": "出處待查（一般認為是曾國藩語）", "author": "", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "用兵久則驕惰自生，驕惰則未有不敗者。勤字所以醫惰，慎字所以醫驕，二字之先，須有一誠字以為本。立意要將此事知得透，辨得穿。精誠所至，金石為開，鬼神亦避，此在己之誠也。", "translation": "帶兵打仗久了，驕傲和懶惰就會自然產生；一旦驕傲懶惰，沒有不失敗的。「勤」字是用來醫治懶惰的，「慎」字是用來醫治驕傲的，在這兩個字之前，必須有一個「誠」字作為根本。下定決心要把這件事了解得透徹、分辨得清楚。真誠到了極點，連金石都能被打開，鬼神也會退避，這是在於自己內心的真誠。", "keywords": [{"w": "用兵", "m": "帶兵作戰"}, {"w": "所以", "m": "用來"}, {"w": "醫", "m": "醫治、矯正"}, {"w": "本", "m": "根本"}, {"w": "穿", "m": "透徹"}, {"w": "精誠所至，金石為開", "m": "真誠到極點，能感動、打開堅硬的金石"}], "questions": [{"n": 18, "stem": "「用兵久則驕惰自生，驕惰則未有不敗者。勤字所以醫惰，慎字所以醫驕，二字之先，須有一誠字以為本。立意要將此事知得透，辨得穿。精誠所至，金石為開，鬼神亦避，此在己之誠也。」根據這段文字，下列敘述何者正確？", "options": {"A": "祭祀鬼神，心誠則靈", "B": "勤慎用兵，以誠為本", "C": "慎可以醫惰，勤可以醫驕", "D": "修身首重勤，次為慎，終為誠"}, "answer": "B", "explain": "文章談用兵要防驕惰，用勤、慎來醫治，而勤、慎之前要先以「誠」為根本，選(B)。(A)「鬼神亦避」是形容誠的力量，不是談祭祀。(C)兩者對調了：勤醫惰、慎醫驕。(D)誠在「二字之先」，是最根本、最先的，不是最後。", "skill": "對應關係題：把原文的配對（勤→惰、慎→驕）畫線連起來，選項常把配對或順序對調。"}], "difficulty": "易", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-22", "exam": "hk109", "nums": [22], "form": "單題", "img": "img/hk109-22.png", "source": "慧皎《高僧傳‧鳩摩羅什傳》（改寫）", "author": "慧皎", "genre": "史傳人物", "types": ["文意推論", "句意理解"], "passage": "鳩摩羅什願凡所宣譯傳流後世，每云：「天竺國俗甚重文制，其宮商體韻以入弦為善，以歌嘆為貴。改梵為漢，失其藻蔚，雖得大意，殊隔文體。有似嚼飯與人，非徒失味，乃令嘔也。」", "translation": "鳩摩羅什希望他所翻譯的佛經能流傳後世，常常說：「天竺（印度）的風俗很重視文章的體制，文辭的音律韻調以能配上樂器演奏為好，以能吟唱詠嘆為可貴。把梵文改譯成漢文，就失去了原本華美的文采，雖然得到大意，卻和原文的文體差得很遠。這就像把飯嚼過再餵給別人，不只失去味道，還讓人想吐。」", "keywords": [{"w": "宣譯", "m": "翻譯並宣揚"}, {"w": "每", "m": "常常"}, {"w": "文制", "m": "文章的體制形式"}, {"w": "宮商體韻", "m": "音律韻調"}, {"w": "入弦", "m": "配上樂器演奏"}, {"w": "藻蔚", "m": "華美的文采"}, {"w": "殊", "m": "很、非常"}, {"w": "隔", "m": "差距、隔閡"}, {"w": "非徒", "m": "不只"}], "questions": [{"n": 22, "stem": "「鳩摩羅什願凡所宣譯傳流後世，每云：『天竺國俗甚重文制，其宮商體韻以入弦為善，以歌嘆為貴。改梵為漢，失其藻蔚，雖得大意，殊隔文體。有似嚼飯與人，非徒失味，乃令嘔也。』」根據這段文字，下列何者最符合鳩摩羅什對譯經的看法？", "options": {"A": "可因國情不同而修改內容", "B": "首要關鍵在於音律的和諧", "C": "應避免以華麗辭藻干擾文意", "D": "保留原文形式之美並不容易"}, "answer": "D", "explain": "鳩摩羅什說梵文改成漢文後「失其藻蔚」「殊隔文體」，就像嚼過的飯失去味道，意思是翻譯雖能保留大意，原文的形式之美卻很難保存，選(D)。(A)他沒有主張修改內容。(B)音律是天竺重視的特色之一，但他談的是翻譯會失去這些美，不是說音律是翻譯首要關鍵。(C)他惋惜失去華麗文采，與「避免華麗辭藻」相反。", "skill": "比喻題：把「嚼飯與人」拆成『飯＝原文、嚼過＝翻譯、失味＝失去文采』，就能讀出作者的態度。"}], "difficulty": "中", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-23", "exam": "hk109", "nums": [23], "form": "單題", "img": "img/hk109-23.png", "source": "出處待查（宋人詩話）", "author": "", "genre": "說理議論", "types": ["詩詞賞析", "字詞解釋"], "passage": "皮日休詠房、杜詩云：「黃閣三十年，清風一萬古。」凡言千古萬古者，皆是無窮之意，今下「一」字，便有所止矣。", "translation": "皮日休歌詠房玄齡、杜如晦的詩說：「在宰相之位三十年，清正的風範流傳一萬古。」凡是說「千古」「萬古」的，都是無窮無盡的意思，現在加上一個「一」字，就變成有了限度。", "keywords": [{"w": "黃閣", "m": "宰相（官署）"}, {"w": "清風", "m": "清正的風範"}, {"w": "凡", "m": "凡是"}, {"w": "下", "m": "用（字）、放入"}, {"w": "止", "m": "停止、限度"}], "questions": [{"n": 23, "stem": "根據這則詩評，下列關於皮日休詩的敘述何者最恰當？", "options": {"A": "用字遣詞多落入俗套", "B": "數字對仗工整，可稱佳作", "C": "詩句用字精確，傳誦千古", "D": "「一」字影響了詩句的意境"}, "answer": "D", "explain": "評論者認為「萬古」本來表示無窮，加上「一」字變成「一萬古」，反而像有了數量上限，削弱了永垂不朽的意境，選(D)。(A)評論只針對一個字，沒有說整體落入俗套。(B)(C)評論是在挑毛病，不是稱讚。", "skill": "詩評題先判斷評論者是褒還是貶（「便有所止矣」是負面），再找他評的是哪個字、哪個效果。"}], "difficulty": "中", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-25", "exam": "hk109", "nums": [25], "form": "單題", "img": "img/hk109-25.png", "source": "出處待查（清人筆記）", "author": "", "genre": "筆記小品", "types": ["文意推論", "文化常識"], "passage": "龍眼枝甚柔脆，熟時賃慣手登採，恐其恣食，與約曰：「唱勿輟，輟則無薪。」樹枝扶疏，人坐綠蔭中，高低斷續，喁喁弗已。遠聽之，頗足娛耳。土人謂之「唱龍眼」。", "translation": "龍眼樹的枝條很柔軟易斷，果實成熟時（主人）就雇用有經驗的人爬上去採摘，又怕他們任意偷吃，就和他們約定說：「唱歌不能停，停了就不給工錢。」樹枝茂密，人坐在綠蔭裡，歌聲高高低低、斷斷續續，一直不停。遠遠聽著，頗為悅耳。當地人稱這為「唱龍眼」。", "keywords": [{"w": "賃", "m": "雇用"}, {"w": "慣手", "m": "有經驗的人"}, {"w": "恣", "m": "任意、放縱"}, {"w": "輟", "m": "停止"}, {"w": "薪", "m": "工錢"}, {"w": "扶疏", "m": "枝葉繁茂"}, {"w": "喁喁", "m": "低語聲"}, {"w": "弗已", "m": "不停止"}, {"w": "土人", "m": "當地人"}], "questions": [{"n": 25, "stem": "根據這段文字，可明確得知下列何者？", "options": {"A": "主人肯錄用沒有經驗的人", "B": "不諳歌唱的工人不予工資", "C": "「唱龍眼」源自於主人防弊的手段", "D": "採龍眼的工人喜在工作時彼此唱和"}, "answer": "C", "explain": "主人「恐其恣食」，怕工人邊採邊偷吃，所以規定要一直唱歌（嘴巴在唱就不能吃），停了就扣工錢，「唱龍眼」就是這樣來的，選(C)。(A)雇的是「慣手」，有經驗的人。(B)規定的是唱歌不能停，不是會不會唱。(D)工人唱歌是約定的要求，文中看不出是他們喜歡。", "skill": "「可明確得知」題：只選原文直接支持的；找出規定背後的原因（恐其恣食）就是關鍵。"}], "difficulty": "易", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-27", "exam": "hk109", "nums": [27], "form": "單題", "img": "img/hk109-27.png", "source": "杜甫〈客夜〉", "author": "杜甫", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "客睡何曾著，秋天不肯明。入簾殘月影，高枕遠江聲。計拙無衣食，途窮仗友生。老妻書數紙，應悉未歸情。", "translation": "客居在外，何曾睡著過？秋夜漫長，天遲遲不肯亮。照進簾子的是殘月的影子，枕上聽到遠處的江水聲。我謀生的本事笨拙，沒有衣食；走投無路，只能依靠朋友接濟。老妻寫來好幾張信紙，她應該明白我無法回家的苦衷吧。", "keywords": [{"w": "著", "m": "睡著"}, {"w": "計拙", "m": "謀生能力笨拙"}, {"w": "途窮", "m": "走投無路"}, {"w": "仗", "m": "依靠"}, {"w": "友生", "m": "朋友"}, {"w": "書", "m": "信"}, {"w": "悉", "m": "知道、明白"}], "questions": [{"n": 27, "stem": "「客睡何曾著，秋天不肯明。入簾殘月影，高枕遠江聲。計拙無衣食，途窮仗友生。老妻書數紙，應悉未歸情。」根據本詩，關於詩中主人翁的敘述，下列何者不正確？", "options": {"A": "經濟拮据，生活困頓", "B": "親友疏離，借貸無門", "C": "生計無著，徹夜難眠", "D": "夫妻分離，兩地相思"}, "answer": "B", "explain": "「途窮仗友生」是走投無路時依靠朋友，可見朋友還能幫忙，不是疏離、借貸無門，所以(B)不正確。(A)(C)「計拙無衣食」是生活困頓；「客睡何曾著」「秋天不肯明」是徹夜失眠。(D)老妻寫信來，他客居在外未歸，夫妻分隔兩地。", "skill": "「不正確」題：每個選項找詩句對證，注意「仗」是依靠，代表有人可依。"}], "difficulty": "中", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-30", "exam": "hk109", "nums": [30], "form": "單題", "img": "img/hk109-30.png", "source": "魏禧〈大鐵椎傳〉", "author": "魏禧", "genre": "史傳人物", "types": ["句意理解", "虛詞句式"], "passage": "大鐵椎，不知何許人。北平陳子燦省兄河南，與遇宋將軍家。宋，懷慶青華鎮人，工技擊，七省好事者皆來學。人以其雄健，呼「宋將軍」云。", "translation": "大鐵椎，不知道是哪裡人。北平人陳子燦到河南探望哥哥，在宋將軍家和他相遇。宋將軍是懷慶青華鎮人，擅長武術，七個省分愛好武術的人都來向他學習。人們因為他雄壯勇健，稱他為「宋將軍」。", "keywords": [{"w": "何許人", "m": "哪裡人"}, {"w": "省", "m": "探望，音ㄒㄧㄥˇ"}, {"w": "與遇", "m": "與（他）相遇"}, {"w": "工", "m": "擅長"}, {"w": "技擊", "m": "武術"}, {"w": "好事者", "m": "愛好此事的人"}, {"w": "以", "m": "因為"}], "questions": [{"n": 30, "stem": "「大鐵椎，不知何許人。北平陳子燦省兄河南，與遇宋將軍家。宋，懷慶青華鎮人，工技擊，七省好事者皆來學。人以其雄健，呼『宋將軍』云。」根據這段文字，可明確得知下列何者？", "options": {"A": "大鐵椎是陳子燦的遠房兄長", "B": "陳子燦與大鐵椎在宋府相遇", "C": "宋將軍善使大鐵椎，故別名大鐵椎", "D": "大鐵椎久慕陳子燦之能，從之學藝"}, "answer": "B", "explain": "「與遇宋將軍家」省略了賓語，意思是陳子燦和大鐵椎在宋將軍家相遇，選(B)。(A)陳子燦去河南探望的是自己的哥哥，與大鐵椎無關。(C)大鐵椎和宋將軍是兩個人，宋將軍的稱號是因為他雄健。(D)七省好事者來學的是宋將軍的武藝，文中沒有大鐵椎向陳子燦學藝。", "skill": "人物多的開頭段：先列出出場人物（大鐵椎、陳子燦、宋將軍），再把省略的「與（之）遇」補完整。"}], "difficulty": "中", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-32", "exam": "hk109", "nums": [32], "form": "單題", "img": "img/hk109-32.png", "source": "宋徽宗《大觀茶論‧采擇》", "author": "趙佶（宋徽宗）", "genre": "其他", "types": ["句意理解", "文化常識"], "passage": "擷茶以黎明，見日則止。用爪斷芽，不以指揉，慮氣汗熏漬，茶不鮮潔，故茶工多以新汲水自隨，得芽則投諸水。凡芽如雀舌、穀粒者為鬥品，一槍一旗為揀芽，一槍二旗又次之，餘斯為下。茶之芽始萌則有白合，既擷則有烏蒂，白合不去害茶味，烏蒂不去害茶色。", "translation": "採茶要在黎明時分，太陽出來就停止。用指甲掐斷茶芽，不用手指去揉，因為擔心手上的氣息、汗水沾染浸漬，茶葉就不鮮潔，所以茶工多半隨身帶著剛打上來的水，採到芽就投入水中。凡是茶芽形狀像雀舌、穀粒的是最上等的「鬥品」，一芽一葉的是「揀芽」，一芽二葉又差一點，其餘的就是下等。茶芽剛萌發時有「白合」（包芽的小葉），採下後有「烏蒂」，白合不去掉會損害茶的味道，烏蒂不去掉會損害茶的顏色。", "keywords": [{"w": "擷", "m": "採摘"}, {"w": "爪", "m": "指甲"}, {"w": "慮", "m": "擔心"}, {"w": "熏漬", "m": "沾染浸漬"}, {"w": "新汲水", "m": "剛打上來的水"}, {"w": "自隨", "m": "隨身攜帶"}, {"w": "諸", "m": "之於"}, {"w": "鬥品", "m": "茶葉的精品"}, {"w": "一槍一旗", "m": "一芽一葉"}, {"w": "害", "m": "損害"}], "questions": [{"n": 32, "stem": "根據這段文字，下列關於茶葉的敘述何者正確？", "options": {"A": "在太陽剛升起時開始採茶", "B": "茶工要自備飲水現場試茶", "C": "一槍一旗為最上品的茶葉", "D": "烏蒂會影響泡出來的顏色"}, "answer": "D", "explain": "「烏蒂不去害茶色」，烏蒂不去掉會損害茶色，選(D)。(A)黎明開始採，「見日則止」，太陽出來就停了。(B)新汲水是用來浸泡剛採下的芽，保持鮮潔，不是飲用或試茶。(C)最上品是芽如雀舌、穀粒的「鬥品」，一槍一旗次一等。", "skill": "說明性文言：把等級與因果整理成表（鬥品＞揀芽＞一槍二旗；白合→味、烏蒂→色），再逐項核對。"}], "difficulty": "中", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-33", "exam": "hk109", "nums": [33], "form": "單題", "img": "img/hk109-33.png", "source": "出處待查（志怪筆記）", "author": "", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "有道士講經茅山，聽者數百人。有自外入者，大罵曰：「道士奴！天正熱，聚眾造妖何為？」道士起謝曰：「居山養徒，資用乏，不得不爾。」罵者怒少解，曰：「須錢不難，何至作此！」乃取釜灶杵臼之類，得百餘斤，以少藥鍛之，皆為銀，乃去。後數年，道士復見此人從一老道士，鬚髮如雪，騎白驢，此人腰插一驢鞭從其後。道士遙望叩頭，欲從之。此人指老道士，且搖手作驚畏狀，去如飛，少頃即不見。", "translation": "有個道士在茅山講經，聽講的有幾百人。有個從外面進來的人大罵說：「臭道士！天氣正熱，聚集這麼多人裝神弄鬼做什麼？」道士起身道歉說：「我住在山中養活徒弟，錢財不夠，不得不這樣。」罵人的人怒氣稍微消了，說：「要錢不難，何必做這種事！」就拿來鍋子、灶具、杵臼之類，有一百多斤，用一點藥去鍛燒，全都變成了銀子，然後離去。幾年後，道士又看見這個人跟在一位老道士後面，老道士鬚髮雪白，騎著白驢，這人腰插驢鞭跟在後頭。道士遠遠望見就叩頭，想跟隨他們。這人指著老道士，搖手做出驚恐害怕的樣子，飛快地離去，一會兒就不見了。", "keywords": [{"w": "造妖", "m": "裝神弄鬼、惑眾"}, {"w": "謝", "m": "道歉"}, {"w": "資用", "m": "錢財費用"}, {"w": "爾", "m": "如此"}, {"w": "少", "m": "稍微"}, {"w": "須", "m": "需要"}, {"w": "釜", "m": "鍋子"}, {"w": "杵臼", "m": "搗東西的棒與臼"}, {"w": "鍛", "m": "冶煉、鍛燒"}, {"w": "少頃", "m": "一會兒"}], "questions": [{"n": 33, "stem": "根據這則故事，下列關於「自外入者」的敘述何者正確？", "options": {"A": "責罵道士搶走自己的信徒", "B": "聽完道士說明後更加生氣", "C": "被道士收買，為道士斂財", "D": "擁有特殊藥物，鍛物成銀"}, "answer": "D", "explain": "他取來鍋灶杵臼，「以少藥鍛之，皆為銀」，可見他擁有能把器物煉成銀的特殊藥物，選(D)。(A)他罵的是道士聚眾惑人，沒說信徒是他的。(B)聽完說明後「怒少解」，怒氣變小了。(C)是他主動變銀子給道士，不是被收買替道士斂財。", "skill": "情緒變化題抓程度詞：「少解」是稍微消減，不是更生氣；動作的主語要跟著『罵者』走。"}], "difficulty": "中", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-34", "exam": "hk109", "nums": [34], "form": "單題", "img": "img/hk109-34.png", "source": "劉向《新序‧雜事》", "author": "劉向", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "楚莊王謀事而當，群臣莫能逮，退朝而有憂色。申公巫臣進曰：「君朝而有憂色，何也？」楚王曰：「吾聞之：諸侯自擇師者王，自擇友者霸，足於己而群臣莫若之者亡。今以不穀之不肖而議於朝，且群臣莫能逮，吾國其幾於亡矣，是以有憂色也。」", "translation": "楚莊王謀劃政事很得當，群臣都比不上他，可是退朝後卻面帶憂色。申公巫臣上前問：「您上朝後面有憂色，為什麼呢？」楚莊王說：「我聽說：諸侯能自己選擇老師的可以稱王，能自己選擇朋友的可以稱霸，自以為滿足而群臣都比不上他的就會滅亡。現在憑我這樣不賢能的人在朝中議事，群臣竟然都比不上我，我的國家恐怕接近滅亡了，所以我才面帶憂色。」", "keywords": [{"w": "當", "m": "恰當"}, {"w": "莫能逮", "m": "沒有人比得上"}, {"w": "進", "m": "上前"}, {"w": "王", "m": "稱王（動詞）"}, {"w": "霸", "m": "稱霸（動詞）"}, {"w": "莫若", "m": "比不上"}, {"w": "不穀", "m": "古代君王自稱的謙詞"}, {"w": "不肖", "m": "不賢能"}, {"w": "幾", "m": "接近、差不多"}], "questions": [{"n": 34, "stem": "根據這則故事，楚莊王有憂色的原因，最可能是下列何者？", "options": {"A": "缺乏優秀人才輔政", "B": "群臣不願追隨國君", "C": "朝中小人當道亂政", "D": "難以抉擇施政方向"}, "answer": "A", "explain": "楚莊王擔心的是「群臣莫能逮」——連他這個（自謙）不賢的人都比不上，表示朝中沒有能當老師、朋友的賢才，國家就危險了，選(A)。(B)群臣不是不追隨，而是能力不足。(C)文中沒有提到小人亂政。(D)他「謀事而當」，施政方向沒問題。", "skill": "找「是以」前的理由，並從楚王引用的原則（擇師者王、擇友者霸）推知他真正擔心的是缺人才。"}], "difficulty": "難", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-45", "exam": "hk109", "nums": [45, 46], "form": "題組", "img": "img/hk109-45.png", "source": "洪邁《容齋隨筆》（改寫）", "author": "洪邁", "genre": "筆記小品", "types": ["句意理解", "文化常識"], "passage": "雅志堂後小室，名之曰「更衣」，以為姻賓憩息地。稚子數請所出，因錄班固《漢書》語示之：\n《漢書》：「坐乃起更衣。」顏師古注：「坐，坐中之人。更，改也。凡久坐者皆起更衣，以其寒暖或變也。」\n《漢書》又載：「延年起，至更衣。」顏師古注：「古者延賓必有更衣之處。」", "translation": "雅志堂後面的小房間，取名為「更衣」，作為親戚賓客休息的地方。小兒子多次問這個名字的由來，我就抄錄班固《漢書》的話給他看：《漢書》說：「在座的人就起身去更衣。」顏師古注解：「坐，指座中的人。更，是改換。凡是坐久了的人都會起身去換衣服，因為天氣冷暖可能有變化。」《漢書》又記載：「田延年起身，到更衣的地方去。」顏師古注解：「古代邀請賓客，一定設有更衣的地方。」", "keywords": [{"w": "名", "m": "命名（動詞）"}, {"w": "姻賓", "m": "親戚與賓客"}, {"w": "憩息", "m": "休息"}, {"w": "稚子", "m": "年幼的兒子"}, {"w": "數", "m": "屢次，音ㄕㄨㄛˋ"}, {"w": "請", "m": "請問"}, {"w": "所出", "m": "出處、由來"}, {"w": "延", "m": "邀請"}], "questions": [{"n": 45, "stem": "根據本文，「稚子數請所出」句中「數請所出」的涵義最可能是下列何者？", "options": {"A": "再三懇請父親出來宴客", "B": "多次詢問小室命名由來", "C": "屢次延請賓客前往休憩", "D": "頻頻敦請姻賓離室用餐"}, "answer": "B", "explain": "「數」是屢次，「請」是請問，「所出」是出處、由來。下文作者「因錄班固《漢書》語示之」，抄錄「更衣」一詞的典故給孩子看，可知孩子問的是小室命名的由來，選(B)。(A)(C)(D)都把「出」理解成「出來、離開」，和下文抄錄典故接不上。", "skill": "詞義推論看下文的回應：作者用什麼回答（抄出處），就能反推孩子問了什麼。"}, {"n": 46, "stem": "根據本文，雅志堂後名為「更衣」的小室，其主要用途與現代哪一種場所最接近？", "options": {"A": "兒童遊戲場", "B": "商場試衣間", "C": "婚禮宴會廳", "D": "賓客休息室"}, "answer": "D", "explain": "首句就說「以為姻賓憩息地」，這間小室是給親戚賓客休息用的；顏師古注也說古代請客必有更衣之處，供久坐的賓客起身休息、換衣，最接近現代的賓客休息室，選(D)。(B)名稱雖叫更衣，但主要用途不是試衣服。", "skill": "不要被字面名稱騙了：找文中直接說明用途的句子（以為……地）。"}], "difficulty": "中", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk109-47", "exam": "hk109", "nums": [47, 48], "form": "題組", "img": "img/hk109-47.png", "source": "曾鞏〈論習〉（改寫）", "author": "曾鞏", "genre": "說理議論", "types": ["字詞解釋", "主旨寓意"], "passage": "治亂之本在君之好惡，好惡在所習。少習也正，其長也必賢；少習也不正，其長難與共為治矣。不幸而然，則將磨之。孰能磨之？擇人焉，朝夕相與俱，出入言動相綴接焉，是則可磨之也。主然而是者，助之；主然而違者，替之。不釋，則極論之。除其蔽慾而接之以道，不使其見邪者而變焉，其志素定矣，然後可與共為治。", "translation": "國家安定或混亂的根本，在於君主的喜好與厭惡；而喜好與厭惡，取決於他所習染的環境。從小習染的是正道，長大後一定賢明；從小習染的不正，長大後就難以和他一起治理國家了。如果不幸是這樣，就要磨練他。誰能磨練他呢？選擇適當的人，早晚和他在一起，出入言行都緊密相隨，這樣就可以磨練他了。君主認為如此而確實正確的，就輔助他；君主認為如此卻違背正理的，就改變它。君主不明白，就盡力和他論說。去除他被蒙蔽的私慾，用正道引導他，不讓他看到邪惡的東西而改變，他的志向向來就能堅定，這樣以後才可以和他一起治理國家。", "keywords": [{"w": "本", "m": "根本"}, {"w": "所習", "m": "所習染、接觸的"}, {"w": "磨", "m": "磨練、矯正"}, {"w": "孰", "m": "誰"}, {"w": "俱", "m": "在一起"}, {"w": "綴接", "m": "連結、緊密相隨"}, {"w": "然", "m": "如此"}, {"w": "是", "m": "正確"}, {"w": "替", "m": "更換、改變"}, {"w": "釋", "m": "了解"}, {"w": "極論", "m": "盡力論說"}, {"w": "接", "m": "引導、接引"}, {"w": "素", "m": "向來"}], "questions": [{"n": 47, "stem": "下列文句「」中的字，何者意義說明正確？", "options": {"A": "「孰」能磨之：難道", "B": "朝夕相與「俱」：具備", "C": "主然而違者，「替」之：改變", "D": "「接」之以道：招待"}, "answer": "C", "explain": "君主認為對、其實違背正理的，就要「替之」——更換、改變它，(C)正確。(A)「孰」是疑問代詞「誰」，下句「擇人焉」正是回答「誰」。(B)「俱」是在一起，朝夕相處。(D)「接之以道」是用正道引導他，不是招待。", "skill": "字義題放回句子看上下文：問句後面接答句（孰能磨之？擇人焉）就能確定是「誰」。"}, {"n": 48, "stem": "下列敘述何者最貼近本文的內容？", "options": {"A": "大臣輔政須能執行上意", "B": "大臣應經磨練方能輔政", "C": "國君擇臣宜摒除個人好惡", "D": "國君所習攸關天下之治亂"}, "answer": "D", "explain": "首句「治亂之本在君之好惡，好惡在所習」，國家治亂取決於君主的好惡，而好惡又取決於君主從小的習染，選(D)。(A)文中說君主錯了要「替之」「極論之」，不是一味執行上意。(B)需要被磨練的是君主，不是大臣。(C)文中說好惡是治亂根本，要靠習染導正，不是叫國君摒除好惡。", "skill": "論說文主旨常在首句：找出「A之本在B，B在C」的推論鏈。"}], "difficulty": "難", "label": "109年會考", "year": 109, "kind": "會考"}, {"id": "hk110-8", "exam": "hk110", "nums": [8], "form": "單題", "img": "img/hk110-8.png", "source": "出處待查", "author": "", "genre": "寓言故事", "types": ["文意推論", "寫作手法"], "passage": "昔人未見麟，問嘗見者：「麟何類乎？」見者曰：「麟如麟也。」問者曰：「若吾嘗見麟，則不問子矣。而云麟如麟，寧可解哉？」見者曰：「麟者，麇身牛尾，鹿蹄馬背。」問者豁然而解。", "translation": "從前有人沒見過麒麟，就去問見過的人：「麒麟像什麼呢？」見過的人說：「麒麟就像麒麟。」問的人說：「如果我見過麒麟，就不會來問你了。你卻說麒麟像麒麟，這怎麼能讓人明白呢？」見過的人說：「麒麟這種動物，有麇的身體、牛的尾巴、鹿的蹄子、馬的背。」問的人一下子就明白了。", "keywords": [{"w": "嘗", "m": "曾經"}, {"w": "類", "m": "像"}, {"w": "若", "m": "如果"}, {"w": "子", "m": "你"}, {"w": "寧", "m": "怎麼、難道"}, {"w": "麇", "m": "音ㄐㄩㄣ，形體似鹿的獸"}, {"w": "豁然", "m": "開通明白的樣子"}], "questions": [{"n": 8, "stem": "「昔人未見麟，問嘗見者：『麟何類乎？』見者曰：『麟如麟也。』問者曰：『若吾嘗見麟，則不問子矣。而云麟如麟，寧可解哉？』見者曰：『麟者，麇身牛尾，鹿蹄馬背。』問者豁然而解。」根據這則故事，下列敘述何者最恰當？", "options": {"A": "問者蓄意為難，明知故問", "B": "見者實未曾見麟，信口開河", "C": "問者終不得其解，寧可自尋答案", "D": "見者最後以具體事物為喻，輔助說明"}, "answer": "D", "explain": "用「麟」解釋「麟」等於沒說；見者改用對方熟悉的麇、牛、鹿、馬等具體動物來比方，問者就「豁然而解」，說明要用已知的事物來解釋未知，選(D)。(A)問者本來就「未見麟」，不是明知故問。(B)他是「嘗見者」，確實看過。(C)結局是「豁然而解」；句中「寧可解哉」的「寧」是「怎麼」，不是「寧可」。", "skill": "寓言題看前後對比：第一次說明為什麼失敗、第二次為什麼成功，差別就是寓意（以已知喻未知）。"}], "difficulty": "易", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-9", "exam": "hk110", "nums": [9], "form": "單題", "img": "img/hk110-9.png", "source": "韋應物〈夕次盱眙縣〉", "author": "韋應物", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "落帆逗淮鎮，停舫臨孤驛。浩浩風起波，冥冥日沉夕。人歸山郭暗，雁下蘆洲白。獨夜憶秦關，聽鐘未眠客。", "translation": "放下船帆停留在淮河邊的小鎮，船靠在孤零零的驛站旁。大風吹起浩浩蕩蕩的波浪，天色昏暗，太陽在傍晚沉落。行人歸去，山邊城郭漸漸暗了；大雁落在長滿蘆葦的沙洲上，蘆花一片白。孤獨的夜裡思念遠方的秦關（長安故鄉），我是那聽著鐘聲而無法入睡的旅客。", "keywords": [{"w": "逗", "m": "停留"}, {"w": "舫", "m": "船"}, {"w": "驛", "m": "驛站"}, {"w": "冥冥", "m": "昏暗的樣子"}, {"w": "山郭", "m": "山邊的城郭"}, {"w": "蘆洲", "m": "長滿蘆葦的沙洲"}, {"w": "秦關", "m": "指長安一帶，詩人的家鄉"}], "questions": [{"n": 9, "stem": "「落帆逗淮鎮，停舫臨孤驛。浩浩風起波，冥冥日沉夕。人歸山郭暗，雁下蘆洲白。獨夜憶秦關，聽鐘未眠客。」關於這首詩的分析，下列敘述何者最恰當？", "options": {"A": "首兩句寫出與友餞別的地點與時間", "B": "以「風起」、「日沉」自喻懷才不遇", "C": "以「雁下蘆洲白」表示太陽將升起", "D": "末兩句點出客因心有所思而不成眠"}, "answer": "D", "explain": "「獨夜憶秦關」說明詩人在孤獨夜裡思念家鄉，所以成了「聽鐘未眠客」，因思鄉而失眠，選(D)。(A)首兩句寫旅途中停船靠岸，沒有朋友、沒有餞別。(B)風起、日沉是傍晚景色，烘托旅途的蒼茫，不是比喻懷才不遇。(C)前面已寫「日沉夕」「山郭暗」，是黃昏入夜，蘆洲的白是蘆花或暮色中的顏色，不是日出。", "skill": "寫景詩先抓時間線索（日沉、暗、獨夜），再找情感句（憶秦關），景與情的關係就清楚了。"}], "difficulty": "中", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-17", "exam": "hk110", "nums": [17], "form": "單題", "img": "img/hk110-17.png", "source": "歐陽脩〈洛陽牡丹記‧風俗記〉（改寫）", "author": "歐陽脩", "genre": "筆記小品", "types": ["句意理解", "文化常識"], "passage": "洛陽之俗，大抵好牡丹，春時城中無分貴賤皆插花，雖負擔者亦然。花開時，士庶競為遊遨，至花落乃罷。洛陽至東京六驛，舊不進花，自今歲遣衙校一員，乘驛馬，一日一夕至京師。所進不過姚黃魏紫三數朵。以菜葉實竹籠子，藉覆之使馬上不動搖，以蠟封蒂，乃數日不落。", "translation": "洛陽的風俗，大多喜愛牡丹，春天時城裡不分貴賤都插戴牡丹，即使是挑擔子的人也一樣。花開的時候，士人和百姓爭著出遊賞花，直到花謝才停止。洛陽到東京（汴京）有六個驛站的距離，以前不進貢牡丹，從今年開始派一名衙校，騎著驛馬，一天一夜就送到京城。所進貢的不過是姚黃、魏紫三五朵。用菜葉塞滿竹籠，鋪墊、覆蓋在花上，使花在馬上不搖晃，再用蠟封住花蒂，這樣花就能幾天都不凋落。", "keywords": [{"w": "大抵", "m": "大多"}, {"w": "負擔者", "m": "挑擔子的人，指勞動百姓"}, {"w": "士庶", "m": "士人與百姓"}, {"w": "遊遨", "m": "遊玩"}, {"w": "乃", "m": "才"}, {"w": "進", "m": "進貢"}, {"w": "姚黃魏紫", "m": "兩種名貴牡丹品種"}, {"w": "實", "m": "塞滿（動詞）"}, {"w": "藉", "m": "鋪墊"}], "questions": [{"n": 17, "stem": "根據這段文字，下列關於牡丹的敘述何者最恰當？", "options": {"A": "姚黃魏紫指的皆是牡丹", "B": "洛陽權貴才有資格買牡丹", "C": "牡丹運送前須以蠟整株封存", "D": "牡丹運送時以菜葉提供其養分"}, "answer": "A", "explain": "文章講進貢牡丹，「所進不過姚黃魏紫三數朵」，可知姚黃、魏紫都是牡丹的品種，選(A)。(B)「無分貴賤皆插花，雖負擔者亦然」，人人都能插牡丹。(C)只是「以蠟封蒂」，封住花蒂，不是整株。(D)菜葉是用來塞滿籠子、鋪墊覆蓋，讓花不搖晃，不是提供養分。", "skill": "注意範圍詞與功能：「蒂」不等於「整株」，菜葉的作用要看後面「使馬上不動搖」。"}], "difficulty": "中", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-25", "exam": "hk110", "nums": [25], "form": "單題", "img": "img/hk110-25.png", "source": "辛棄疾〈西江月‧江行采石岸，戲作漁夫詞〉", "author": "辛棄疾", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法", "文化常識"], "passage": "辛棄疾〈西江月〉江行采石岸，戲作漁夫詞\n千丈懸崖削翠，一川落日鎔金。白鷗來往本無心。選甚風波一任。\n別浦魚肥堪膾，前村酒美重斟。千年往事已沉沉。閒管興亡則甚。", "translation": "千丈高的懸崖像削出來的一片青翠，整條江上的落日像熔化的黃金。白鷗來來往往本就沒有機心，管它什麼風波，一概任它去。別處水邊的魚肥美，正好切來做生魚片；前面村子的酒香醇，再斟上一杯。千年往事都已沉沒消逝，何必去管那些國家興亡的閒事呢？", "keywords": [{"w": "削翠", "m": "如刀削般的青翠山壁"}, {"w": "一川", "m": "整條江"}, {"w": "鎔金", "m": "熔化的黃金，形容落日映江"}, {"w": "選甚", "m": "不論什麼、管它什麼"}, {"w": "一任", "m": "任憑"}, {"w": "別浦", "m": "另一處水濱"}, {"w": "膾", "m": "切成細片的魚肉，此作動詞"}, {"w": "沉沉", "m": "深沉、消逝"}, {"w": "則甚", "m": "做什麼"}], "questions": [{"n": 25, "stem": "關於這闋詞的分析，下列敘述何者最恰當？", "options": {"A": "題目為〈西江月〉，後附小序", "B": "上、下片的首二句皆為對仗句", "C": "上片先情後景，下片先景後情", "D": "結尾寫出以天下為己任的抱負"}, "answer": "B", "explain": "上片「千丈懸崖削翠／一川落日鎔金」，下片「別浦魚肥堪膾／前村酒美重斟」，兩組字數相等、詞性相對，都是對仗，選(B)。(A)〈西江月〉是詞牌名，不是題目；「江行采石岸，戲作漁夫詞」才是題目。(C)上片先寫懸崖落日之景，再寫白鷗無心之情，是先景後情。(D)「閒管興亡則甚」是不管興亡，表現漁夫的超然，不是以天下為己任。", "skill": "詞的常識：詞牌≠題目；檢查對仗就把上下兩句逐字配對（千丈↔一川、懸崖↔落日）。"}], "difficulty": "中", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-27", "exam": "hk110", "nums": [27], "form": "單題", "img": "img/hk110-27.png", "source": "王國維《人間詞話》", "author": "王國維", "genre": "說理議論", "types": ["文意推論", "詩詞賞析"], "passage": "古今詞人格調之高，無如白石。惜不於意境上用力，故覺無言外之味、弦外之響。終不能與於第一流之作者也。", "translation": "古今詞人格調之高，沒有比得上姜白石的。可惜他不在意境上用功，所以讓人覺得他的詞沒有言外的韻味、弦外的餘音。終究不能列入第一流作者之中。", "keywords": [{"w": "格調", "m": "作品的風格品調"}, {"w": "無如", "m": "比不上"}, {"w": "惜", "m": "可惜"}, {"w": "言外之味、弦外之響", "m": "文字之外耐人尋味的餘韻"}, {"w": "與", "m": "參與、列入，音ㄩˋ"}], "questions": [{"n": 27, "stem": "王國維評姜白石詞：「古今詞人格調之高，無如白石。惜不於意境上用力，故覺無言外之味、弦外之響。終不能與於第一流之作者也。」下列何者最符合這段文字的觀點？", "options": {"A": "白石非第一流之作者", "B": "白石之詞善於經營意境", "C": "有弦外之響者必是第一流詞作", "D": "詞有言外之意方顯作者格調之高"}, "answer": "A", "explain": "結尾「終不能與於第一流之作者也」，明白說姜白石不能列入第一流，選(A)。(B)正好相反，他「不於意境上用力」。(C)文中只說沒有弦外之響就不能第一流，並沒說有了就「必是」第一流。(D)王國維認為白石格調最高卻沒有言外之味，可見格調與言外之意是兩回事。", "skill": "小心邏輯推論：「沒有A就不能B」不等於「有A就一定B」；並分清評論中的優點與缺點。"}], "difficulty": "中", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-28", "exam": "hk110", "nums": [28], "form": "單題", "img": "img/hk110-28.png", "source": "《後漢書‧淳于恭傳》", "author": "范曄", "genre": "史傳人物", "types": ["人物情感", "文意推論"], "passage": "淳于恭，字孟孫，北海人。人有盜刈恭禾者，恭見之，念其愧，因伏草中，至去乃起。", "translation": "淳于恭，字孟孫，北海人。有人偷割淳于恭田裡的稻禾，淳于恭看見了，顧念對方被撞見會羞愧，就趴伏在草叢中，等那人離開了才起身。", "keywords": [{"w": "刈", "m": "音ㄧˋ，割取"}, {"w": "念", "m": "顧念、想到"}, {"w": "因", "m": "於是"}, {"w": "伏", "m": "趴伏、躲藏"}, {"w": "乃", "m": "才"}], "questions": [{"n": 28, "stem": "「淳于恭，字孟孫，北海人。人有盜刈恭禾者，恭見之，念其愧，因伏草中，至去乃起。」根據這則故事，下列敘述何者最恰當？", "options": {"A": "當時五穀歉收，盜賊四處搶糧", "B": "淳于恭個性溫厚寬容，能體恤他人", "C": "北海地區盜賊兇悍，人民不敢與之對抗", "D": "淳于恭伏於草中，乃因心中有愧，不欲見人"}, "answer": "B", "explain": "淳于恭看到有人偷割自己的稻子，不但不責備，反而怕對方被看見而難堪，自己躲起來，表現出寬厚、體貼他人的個性，選(B)。(A)(C)文中沒有歉收、盜賊兇悍的描述。(D)「念其愧」的「其」指偷稻的人，是擔心對方羞愧，不是淳于恭自己有愧。", "skill": "代詞「其」要找對指代對象：『念其愧』是替別人著想，正是人物性格的關鍵。"}], "difficulty": "易", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-29", "exam": "hk110", "nums": [29], "form": "單題", "img": "img/hk110-29.png", "source": "高啟〈遊靈巖記〉（改寫）", "author": "高啟", "genre": "山水遊記", "types": ["主旨寓意", "文意推論"], "passage": "夫山之異於眾者，尚能待人而自見，而況人之異於眾者哉！天於詭奇之地不多設，人於登臨之樂不常遇。有其地而非其人，有其人而非其地，皆不足以盡夫遊觀之樂也。今靈巖為名山，諸公為名士，蓋必相須而適相值，夫豈偶然哉！宜其目領而心解，景會而理得也。", "translation": "與眾不同的山，尚且要等待懂得欣賞的人來才能顯現它的美，更何況是與眾不同的人呢！上天不常安排奇特的地方，人也不常遇到登高遊覽的樂趣。有好地方卻沒有適合的人，有適合的人卻沒有好地方，都不足以完全享受遊覽觀賞的樂趣。現在靈巖是名山，各位是名士，這必定是彼此需要而恰好相遇，哪裡是偶然的呢！難怪大家眼睛領略、心中理解，景物與心意相合而領悟道理。", "keywords": [{"w": "異於眾", "m": "與眾不同"}, {"w": "待", "m": "等待、依靠"}, {"w": "見", "m": "同「現」，顯現"}, {"w": "詭奇", "m": "奇特"}, {"w": "盡", "m": "完全享受"}, {"w": "相須", "m": "互相需要"}, {"w": "適", "m": "恰好"}, {"w": "值", "m": "遇到"}, {"w": "宜", "m": "難怪、應當"}], "questions": [{"n": 29, "stem": "「夫山之異於眾者，尚能待人而自見，而況人之異於眾者哉！天於詭奇之地不多設，人於登臨之樂不常遇。有其地而非其人，有其人而非其地，皆不足以盡夫遊觀之樂也。今靈巖為名山，諸公為名士，蓋必相須而適相值，夫豈偶然哉！宜其目領而心解，景會而理得也。」下列敘述何者與這段文字中的觀點最接近？", "options": {"A": "若能保持心靈的澄淨，所到之處都會是美景", "B": "徜徉於大自然中，可洗滌世俗的汙濁與煩憂", "C": "只要有名士登臨，無論怎樣的山水都可成為名勝", "D": "要盡遊觀之樂，須有特別的景致與懂得欣賞的人"}, "answer": "D", "explain": "關鍵句是「有其地而非其人，有其人而非其地，皆不足以盡夫遊觀之樂」，好地方和懂欣賞的人兩者缺一不可，選(D)。(A)只強調人的心境，忽略「地」。(B)文中沒有談洗滌煩憂。(C)「只要有名士」就忽略了也必須「有其地」。", "skill": "找出『缺一不可』的句型（有A而非B，有B而非A，皆不足），答案必須同時包含兩個條件。"}], "difficulty": "難", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-30", "exam": "hk110", "nums": [30], "form": "單題", "img": "img/hk110-30.png", "source": "歐陽脩《歸田錄》", "author": "歐陽脩", "genre": "筆記小品", "types": ["句意理解", "文意推論"], "passage": "胡旦晚年病目，閉門閒居。一日，史館共議作一貴侯傳，其人少賤，嘗屠豕豬。史官以為諱之即非實錄，書之即難為辭。相與見旦，旦曰：「何不曰『某少嘗操刀以割』，示有宰天下之志。」莫不嘆服。", "translation": "胡旦晚年眼睛有病，關起門來閒居。有一天，史館的官員一起商議要為一位顯貴的侯爵寫傳記，這個人年輕時地位卑賤，曾經殺豬。史官認為如果隱瞞這件事，就不是真實的記錄；如果寫出來，又很難措辭。於是一起去見胡旦，胡旦說：「為什麼不寫『某人年少時曾經拿刀宰割』，表示他從小就有主宰天下的志向呢？」大家沒有不讚嘆佩服的。", "keywords": [{"w": "病目", "m": "眼睛生病"}, {"w": "少賤", "m": "年輕時地位卑賤"}, {"w": "嘗", "m": "曾經"}, {"w": "豕", "m": "豬"}, {"w": "諱", "m": "隱瞞、避而不提"}, {"w": "實錄", "m": "真實的記錄"}, {"w": "為辭", "m": "措辭"}, {"w": "宰", "m": "宰割；主宰（雙關）"}], "questions": [{"n": 30, "stem": "根據這則故事，下列關於胡旦的敘述何者最恰當？", "options": {"A": "年少時曾操刀殺豬", "B": "史官共議為其立傳", "C": "史官因不知如何記實而登門求教", "D": "眾人因其有宰割天下之志而嘆服"}, "answer": "C", "explain": "史官覺得「諱之即非實錄，書之即難為辭」，不知怎麼寫，所以「相與見旦」去請教胡旦，選(C)。(A)年少殺豬的是那位貴侯。(B)要立傳的是貴侯，不是胡旦。(D)眾人嘆服的是胡旦巧妙的措辭（用「宰」字雙關，既真實又體面），「宰天下之志」是寫給貴侯的。", "skill": "區分人物：把事件分配給正確的人（胡旦／貴侯／史官），並看懂「宰」的雙關。"}], "difficulty": "中", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-31", "exam": "hk110", "nums": [31], "form": "單題", "img": "img/hk110-31.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["主旨寓意", "文意推論"], "passage": "有覆於上者如天，載於下者如地，而百姓不之知。有恩信及一物，教化及一夫，民則歸之。其猶豐年與旱歲也：豐年之民，不知甘雨柔風之力，不知生育長養之仁，而曰：『我耕作以時，倉廩以實』。旱歲之民，則野枯苗縮，然後決川以灌之。然則一川之仁豈深於四時也哉？", "translation": "在上面覆蓋像天、在下面承載像地那樣的大恩，百姓卻不知道。只要有一點恩惠信義施及一件事物、教化施及一個人，百姓就歸附他。這就像豐年和旱年：豐年的百姓，不知道是及時雨、和風的力量，不知道天地生養萬物的仁德，反而說：『是我按時耕作，糧倉才充實的。』旱年的百姓，看到田野乾枯、禾苗萎縮，然後有人挖開河川來灌溉，（他們就感激不已）。那麼一條河的恩惠，難道比四季（風調雨順）的恩惠更深嗎？", "keywords": [{"w": "覆", "m": "覆蓋"}, {"w": "載", "m": "承載"}, {"w": "不之知", "m": "不知之，不知道它（倒裝）"}, {"w": "及", "m": "施及、到達"}, {"w": "歸", "m": "歸附"}, {"w": "以時", "m": "按照時節"}, {"w": "倉廩", "m": "糧倉"}, {"w": "決川", "m": "挖開河川"}, {"w": "然則", "m": "那麼"}], "questions": [{"n": 31, "stem": "下列何者最能與這段文字的意旨相呼應？", "options": {"A": "對感情的得失順其自然，不執著強求", "B": "平日砥礪心志，災禍發生時才能處變不驚", "C": "購買生產過剩的農產品，幫助農民度過難關", "D": "對外人的一時之助充滿感謝，卻忽略父母深恩"}, "answer": "D", "explain": "文章說人們對天地四時長久而巨大的恩惠視而不見，對一時一處的小恩惠（一川之灌溉）卻感激不已。(D)對外人的一時幫忙很感謝，卻忽略父母長久的深恩，結構完全相同，選(D)。(A)(B)(C)都沒有『大恩不覺、小惠感激』的對比。", "skill": "應用類比題：先把原文抽象成一句原則（大而長久的恩惠被忽略，小而一時的恩惠被感謝），再找結構相同的生活情境。"}], "difficulty": "難", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-32", "exam": "hk110", "nums": [32], "form": "單題", "img": "img/hk110-32.png", "source": "出處待查（宋人筆記）", "author": "", "genre": "筆記小品", "types": ["人物情感", "文意推論"], "passage": "必備匙箸兩副，食前多品。擇取欲食者，以別箸取之，置一器中，食之必盡。飯前以別匙分而另置，始膳。吳后嘗問其故，曰：『不欲以殘食與宮人食也。』", "translation": "（宋高宗用餐）一定準備兩副湯匙和筷子，面前擺著多道菜。他先挑選想吃的，用另一雙筷子夾出來，放在一個器皿裡，夾出來的一定吃完。吃飯前也用另一支湯匙把飯分出來另外放，然後才開始用餐。吳皇后曾經問他原因，他說：「我不想把吃剩的食物給宮人吃。」", "keywords": [{"w": "匙箸", "m": "湯匙和筷子"}, {"w": "品", "m": "菜餚的種類"}, {"w": "別", "m": "另外的"}, {"w": "器", "m": "器皿"}, {"w": "膳", "m": "用餐"}, {"w": "嘗", "m": "曾經"}, {"w": "殘食", "m": "吃剩的食物"}], "questions": [{"n": 32, "stem": "「必備匙箸兩副，食前多品。擇取欲食者，以別箸取之，置一器中，食之必盡。飯前以別匙分而另置，始膳。吳后嘗問其故，曰：『不欲以殘食與宮人食也。』」這段文字記載宋高宗的用膳習慣，據此可看出他具備什麼樣的特質？", "options": {"A": "用餐講究排場", "B": "飲食注重養生", "C": "對妻言聽計從", "D": "待下體貼細心"}, "answer": "D", "explain": "宋高宗用公筷公匙先把要吃的分出來，剩下的菜沒碰過，可以讓宮人吃乾淨的食物，他自己說「不欲以殘食與宮人食」，可見他體貼下人、心思細膩，選(D)。(A)多道菜是宮廷常態，但做法的用意不在排場。(B)沒有提到養生。(C)吳后只是詢問原因，並不是吳后要求他這樣做。", "skill": "人物特質題：直接找人物說明動機的那句話（不欲……），從動機判斷性格。"}], "difficulty": "易", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-44", "exam": "hk110", "nums": [44, 45], "form": "題組", "img": "img/hk110-44.png", "source": "歐陽脩〈大明水記〉（改寫）", "author": "歐陽脩", "genre": "說理議論", "types": ["比較閱讀", "寫作手法", "文意推論"], "passage": "陸羽《茶經》論水云：「山水上，石泉又上，江水次而井水下。」又「江水取去人遠者，井取汲多者。」其說止於此，未嘗品第天下之水味。張又新《煎茶水記》云劉伯芻謂水有七等，以揚子江為第一，惠山石泉為第二，虎丘井第三，淮水居末。又載羽為李季卿論水次第有二十種，江水居山水上，井水居江水上。二說皆與《茶經》不合。\n水味有美惡而已，欲求天下之水一一而次第之者，謬說也。羽之論水，惡渟浸而喜泉源，故井取多汲者。江雖長，然眾水雜聚，故次山水。惟此說近物理云。", "translation": "陸羽《茶經》論水說：「山水最好，石間的泉水又更好，江水其次，井水最差。」又說：「江水要取離人居遠的，井水要取常被汲用的。」他的說法只到這裡，不曾把天下的水一一評定等級。張又新《煎茶水記》說劉伯芻認為水有七等，把揚子江列第一，惠山石泉第二，虎丘井第三，淮水最末。又記載陸羽替李季卿評定水的等第有二十種，把江水排在山水之上，井水排在江水之上。這兩種說法都和《茶經》不合。\n水的味道只有好與壞罷了，想把天下的水一一排出名次，是荒謬的說法。陸羽論水，厭惡停滯不動的水而喜歡有源頭的泉水，所以井水要取常被汲用的。江水雖然長，但是許多水流混雜聚集，所以排在山水之後。只有這種說法接近事物的道理。", "keywords": [{"w": "上", "m": "上等"}, {"w": "次", "m": "其次"}, {"w": "去人遠", "m": "離人居處遠"}, {"w": "汲", "m": "打水"}, {"w": "品第", "m": "評定等級"}, {"w": "次第", "m": "排列順序（動詞）"}, {"w": "惡", "m": "厭惡，音ㄨˋ"}, {"w": "渟浸", "m": "水停止不動"}, {"w": "物理", "m": "事物的道理"}], "questions": [{"n": 44, "stem": "根據本文，下列敘述何者最恰當？", "options": {"A": "張又新將天下的水按水質分成二十種", "B": "歐陽脩按水源的遠近和高低評定水質", "C": "在《煎茶水記》中，張又新反駁劉伯芻看法", "D": "依《茶經》論水的標準，揚子江優於虎丘井"}, "answer": "D", "explain": "《茶經》的標準是「江水次而井水下」，揚子江是江水、虎丘井是井水，所以江水優於井水，選(D)。(A)二十種是《煎茶水記》記載「羽為李季卿論水」的說法，不是張又新自己分的。(B)歐陽脩認為「欲求天下之水一一而次第之者，謬說也」，他反對排名次。(C)張又新只是記載劉伯芻和陸羽的說法，並沒有反駁；指出「二說皆與《茶經》不合」的是歐陽脩。", "skill": "多重引述要分層：誰的書、記載了誰的說法、又是誰在評論，逐層標清楚。"}, {"n": 45, "stem": "關於本文的寫作手法，下列敘述何者最恰當？", "options": {"A": "首段提出各家之說，末段表明作者的觀點", "B": "首段評比水質高下，末段以各家之說佐證", "C": "首段引述《茶經》的說法，末段舉各家之說駁斥", "D": "首段分論不同水源的特性，末段以取水標準總結"}, "answer": "A", "explain": "首段列出陸羽、劉伯芻、張又新所記的各家說法；末段「水味有美惡而已……謬說也」「惟此說近物理云」是歐陽脩自己的看法，選(A)。(B)作者並沒有評比水質高下，反而反對排名。(C)末段是肯定《茶經》、駁斥排名之說，不是用各家之說駁斥《茶經》。(D)首段重點是介紹各家之說，不是分論水源特性。", "skill": "結構題：看每段的『說話者』是誰——引述別人用「云」「謂」「載」，作者自己的判斷常出現「謬」「惟此說」等評語。"}], "difficulty": "難", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk110-46", "exam": "hk110", "nums": [46, 47, 48], "form": "題組", "img": "img/hk110-46.png", "source": "【甲】沈括《夢溪筆談》；【乙】宋祁〈故大理評事張公墓誌銘〉（皆改寫）", "author": "沈括；宋祁", "genre": "史傳人物", "types": ["字詞解釋", "比較閱讀", "文意推論"], "passage": "【甲】柳開少好任氣，大言凌物。應舉時，以文章投於主考簾前，凡千軸，載以獨輪車。引試日，自擁車入，欲以此駭眾取名。其時張景能文有名，唯袖一書簾前獻之。主考大稱賞，擢景優等。時人為之語曰：「柳開千軸，不如張景一書。」\n【乙】張景，字晦之，江陵公安人。幼能長言，嗜學尤力。貧不治產，往從柳開。開以文自名，而薦寵士類，一見歡甚，悉出家書予之，由是屬辭益有法度。開每曰：「今朝中之士，誰踰晦之者！」即厚饋，使如京師。後中進士。", "translation": "【甲】柳開年少時意氣用事，說大話、傲視他人。參加科舉時，把文章投到主考官簾前，共有一千卷，用獨輪車載著。面試那天，他自己推著車進去，想用這個來驚動眾人、博取名聲。當時張景擅長文章而有名，只在袖中藏一篇文章到簾前獻上。主考官大為讚賞，把張景拔擢為優等。當時的人為此說：「柳開的一千卷，比不上張景的一篇文章。」\n【乙】張景，字晦之，江陵公安人。小時候就能寫長篇文章，好學又特別努力。家貧不經營產業，前往跟隨柳開。柳開以文章自負有名，又推薦、愛護讀書人，一見張景就非常高興，把家中的藏書全部拿出來給他，張景寫文章因此更有法度。柳開常說：「現在朝中的士人，誰能超過晦之呢！」就送他豐厚的財物，讓他前往京城。後來張景考中進士。", "keywords": [{"w": "任氣", "m": "意氣用事"}, {"w": "凌物", "m": "傲視他人"}, {"w": "軸", "m": "卷（卷軸）"}, {"w": "引試", "m": "面試"}, {"w": "駭眾", "m": "使眾人驚駭"}, {"w": "袖", "m": "藏在袖中（名詞作動詞）"}, {"w": "擢", "m": "拔擢、提拔"}, {"w": "尤", "m": "特別"}, {"w": "治產", "m": "經營產業"}, {"w": "薦寵", "m": "推薦、愛護"}, {"w": "悉", "m": "全部"}, {"w": "屬辭", "m": "寫文章"}, {"w": "踰", "m": "超過"}, {"w": "饋", "m": "贈送"}, {"w": "如", "m": "前往"}], "questions": [{"n": 46, "stem": "下列文句「」中字的意義說明，何者最恰當？", "options": {"A": "駭眾取「名」——姓名", "B": "嗜學「尤」力——尚且", "C": "「悉」出家書予之——明白", "D": "使「如」京師——前往"}, "answer": "D", "explain": "「使如京師」是讓他前往京城，「如」是前往，選(D)。(A)「駭眾取名」是驚動眾人以博取名聲，名＝名聲。(B)「嗜學尤力」是好學特別努力，尤＝特別。(C)「悉出家書」是把家中藏書全部拿出來，悉＝全部。", "skill": "常見文言字義要熟記：如（往）、悉（全）、尤（特別）、名（名聲）。"}, {"n": 47, "stem": "關於甲、乙兩文的內容，下列說明何者最不恰當？", "options": {"A": "甲文比較柳開、張景才華的高下", "B": "乙文敘述張景投靠柳開後的際遇", "C": "兩文皆凸顯柳開自大的形象", "D": "兩文皆肯定張景不凡的文才"}, "answer": "C", "explain": "甲文的柳開「大言凌物」、載千卷文章駭眾，形象自大；但乙文的柳開愛護後進、送書贈金、稱讚張景無人能比，是提攜後輩的長者，並沒有凸顯自大，所以(C)最不恰當。(A)「柳開千軸，不如張景一書」就是比較。(B)乙文寫張景往從柳開，學問精進、得資助赴京、中進士。(D)甲文主考大稱賞張景，乙文柳開說朝中無人能超越他，都肯定張景。", "skill": "「兩文皆」選項：必須兩篇都成立才對，逐篇檢查人物形象是否一致。"}, {"n": 48, "stem": "根據丙表所列舉的年分，對照甲、乙兩文內容，下列推論何者最合理？", "options": {"A": "柳開中舉前已受張景愛戴", "B": "宋祁跟柳開兩人頗有交情", "C": "甲文的寫作時間早於乙文", "D": "乙文所述內容較甲文可信"}, "answer": "D", "explain": "丙表顯示柳開973年中舉，張景970年出生，當時才3歲，不可能如甲文所說和柳開同場應考、勝過柳開；而且甲文作者沈括1031年才出生，離事件很遠。乙文作者宋祁與張景時代較近，內容也與年分相符，所以乙文較可信，選(D)。(A)柳開中舉時張景才3歲。(B)柳開1001年過世時宋祁才3歲，難有交情。(C)沈括比宋祁晚三十多年出生，甲文不會比乙文早。", "skill": "文獻考證：把文中事件放進年表，計算人物當時的年齡，矛盾之處就是不可信的證據。"}], "difficulty": "難", "label": "110年會考", "year": 110, "kind": "會考"}, {"id": "hk111-8", "exam": "hk111", "nums": [8], "form": "單題", "img": "img/hk111-8.png", "source": "出處待查（筆記軼事）", "author": "", "genre": "筆記小品", "types": ["人物情感", "文意推論"], "passage": "陸公嘗於市遇一佳硯，議價未定。既還邸，使門人往，以一金易歸。門人持硯歸，公訝其不類。門人堅證其是。公曰：「向觀硯有鴝鵒眼，今何無之？」答曰：「吾嫌其微凸，路遇石工，令磨而平之。」公大惋惜。", "translation": "陸公曾經在市場上看到一塊好硯臺，價錢還沒談定。回到住處後，派門下的人前去，用一兩金子把它換了回來。門人拿著硯臺回來，陸公驚訝它和原來看到的不像。門人堅持說就是那一塊。陸公說：「先前看這硯臺上有鴝鵒眼，現在怎麼沒有了？」門人回答：「我嫌它有點凸起，路上遇到石匠，就叫他磨平了。」陸公非常惋惜。", "keywords": [{"w": "嘗", "m": "曾經"}, {"w": "邸", "m": "住所"}, {"w": "門人", "m": "門下的人、門客"}, {"w": "易", "m": "交換、買"}, {"w": "訝", "m": "驚訝"}, {"w": "類", "m": "相像"}, {"w": "證", "m": "證明、保證"}, {"w": "向", "m": "先前"}, {"w": "鴝鵒眼", "m": "硯石上圓形似鳥眼的石紋，被視為珍貴特徵"}], "questions": [{"n": 8, "stem": "下列關於故事中人物的敘述，何者最恰當？", "options": {"A": "門人買錯硯臺卻不知道", "B": "陸公惋惜是因石工技藝不佳", "C": "門人請人磨平硯眼是自作聰明", "D": "陸公對門人購硯的價格感到驚訝"}, "answer": "C", "explain": "鴝鵒眼正是這塊硯臺珍貴的地方，門人卻嫌它凸起，擅自叫石匠磨平，毀了寶物，這是自作聰明，選(C)。(A)門人買的確實是那塊硯，只是被磨掉了硯眼。(B)陸公惋惜的是珍貴的鴝鵒眼沒了，不是石匠技術差。(D)陸公驚訝的是硯臺「不類」（看起來不像），不是價格。", "skill": "找故事的「轉折點」：門人的一句解釋揭開真相，再判斷他的行為帶來什麼後果、作者想諷刺什麼。"}], "difficulty": "易", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk111-10", "exam": "hk111", "nums": [10], "form": "單題", "img": "img/hk111-10.png", "source": "呂祖謙《東萊博議》", "author": "呂祖謙", "genre": "說理議論", "types": ["主旨寓意", "文意推論"], "passage": "名不可以倖取也。天下之事，固有外似而中實不然者。倖其似而竊其名，非不可以欺一時，然他日人即其似而求其真，則情現實吐，無不立敗。", "translation": "名聲是不可以僥倖得來的。天下的事，本來就有外表看起來相似、內在其實不是那樣的。僥倖靠著外表相似而竊取名聲，不是不能騙過一時，但將來人們根據那個外表去追求它的真實內涵時，真相就會全部顯露出來，沒有不立刻失敗的。", "keywords": [{"w": "倖", "m": "僥倖、不當地"}, {"w": "固", "m": "本來"}, {"w": "中", "m": "內在"}, {"w": "竊", "m": "竊取"}, {"w": "即", "m": "就著、根據"}, {"w": "情現實吐", "m": "真情實況完全顯露"}, {"w": "立", "m": "立刻"}], "questions": [{"n": 10, "stem": "「名不可以倖取也。天下之事，固有外似而中實不然者。倖其似而竊其名，非不可以欺一時，然他日人即其似而求其真，則情現實吐，無不立敗。」下列何者最能與這段文字的意旨相呼應？", "options": {"A": "因其貌不揚被小看，沒想到靠著精湛演技成為影帝", "B": "不勞而獲的錢財，因為來得容易，往往被輕易揮霍", "C": "以作弊手段考上名校，最後卻因適應不良而中輟學業", "D": "當不切實際的夢想碰到冷酷的現實，也只能化為泡影"}, "answer": "C", "explain": "文章的道理是：靠假象僥倖得到名聲，可以騙一時，一旦要拿出真本事就會失敗。(C)用作弊得到名校學生的身分（竊名），真正上課時實力不夠而中輟（立敗），完全吻合。(A)是先被看輕、後憑實力成功，方向相反。(B)講的是錢財揮霍，不是名實不符。(D)講夢想落空，沒有「竊名」的成分。", "skill": "應用題先把原文濃縮成『條件→結果』（假象得名→被檢驗→失敗），再找情境中有同樣三步驟的選項。"}], "difficulty": "中", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk111-14", "exam": "hk111", "nums": [14], "form": "單題", "img": "img/hk111-14.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["字詞解釋"], "passage": "修身以為弓，矯思以為矢，立義以為的，定而後發，發必中矣。", "translation": "把修養品德當作弓，把矯正思想當作箭，把確立道義當作箭靶，心志安定之後再發射，射出去就一定會命中。", "keywords": [{"w": "修身", "m": "修養品德"}, {"w": "矯", "m": "矯正、使正直"}, {"w": "矢", "m": "箭"}, {"w": "的", "m": "箭靶，音ㄉㄧˋ"}, {"w": "中", "m": "命中，音ㄓㄨㄥˋ"}], "questions": [{"n": 14, "stem": "「修身以為弓，矯思以為矢，立義以為的，定而後發，發必中矣。」句中「矯」字的意義，與下列何者最接近？", "options": {"A": "「矯」世勵俗", "B": "「矯」若遊龍", "C": "「矯」捷身手", "D": "「矯」託天命"}, "answer": "A", "explain": "箭要直才射得準，「矯思」是矯正思想、使之端正，矯＝矯正。(A)矯世勵俗是矯正世風、勉勵風俗，意思相同。(B)矯若遊龍形容姿態強健靈活。(C)矯捷是強健敏捷。(D)矯託是假託、詐稱。", "skill": "從比喻推字義：「矯思」對應「矢」，想想箭需要什麼（直），就知道矯是「使正」。"}], "difficulty": "中", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk111-16", "exam": "hk111", "nums": [16], "form": "單題", "img": "img/hk111-16.png", "source": "孔尚任《桃花扇》（柳敬亭說書唱詞）", "author": "孔尚任", "genre": "古典詩詞曲", "types": ["文意推論", "文化常識"], "passage": "俺讀些稗官詞寄牢騷，對江山吃一斗苦松醪。小鼓兒顫杖輕敲，寸板兒軟手頻搖。一字字臣忠子孝，一聲聲龍吟虎嘯。快舌尖鋼刀出鞘，響喉嚨轟雷烈炮。呀！似這般冷嘲、熱挑，用不著筆抄、墨描，勸英豪一盤錯帳速勾了。", "translation": "我讀些民間小說故事來寄託心中的牢騷，面對江山喝上一斗苦澀的松醪濁酒。小鼓用顫動的鼓槌輕輕敲，小小的板子用靈活的手頻頻搖。說出的一字一句都是忠臣孝子的故事，一聲一聲像龍吟虎嘯般有氣勢。快嘴的舌尖像鋼刀出鞘，響亮的喉嚨像轟雷烈炮。呀！像這樣冷言嘲諷、熱語挑撥，用不著筆來抄、墨來寫，勸英雄豪傑們把人生的一筆糊塗帳趕快勾銷吧。", "keywords": [{"w": "俺", "m": "我"}, {"w": "稗官詞", "m": "民間小說故事"}, {"w": "寄", "m": "寄託"}, {"w": "醪", "m": "音ㄌㄠˊ，混有渣滓的濁酒"}, {"w": "寸板", "m": "說書伴奏用的小板"}, {"w": "冷嘲、熱挑", "m": "冷言諷刺、熱語挑逗"}, {"w": "勾了", "m": "勾銷、了結"}], "questions": [{"n": 16, "stem": "某古典戲曲中有一段唱詞：「俺讀些稗官詞寄牢騷，對江山吃一斗苦松醪。小鼓兒顫杖輕敲，寸板兒軟手頻搖。一字字臣忠子孝，一聲聲龍吟虎嘯。快舌尖鋼刀出鞘，響喉嚨轟雷烈炮。呀！似這般冷嘲、熱挑，用不著筆抄、墨描，勸英豪一盤錯帳速勾了。」據此判斷，唱詞中「俺」的職業最可能是下列何者？", "options": {"A": "說書人", "B": "算命師", "C": "外交使臣", "D": "監察御史"}, "answer": "A", "explain": "「讀些稗官詞」（講小說故事）、「小鼓兒」「寸板兒」（說書的伴奏樂器）、「一字字臣忠子孝」（講忠孝故事）、「快舌尖」「響喉嚨」（口才與聲音），而且「用不著筆抄、墨描」全靠一張嘴，這些都是說書人的特徵，選(A)。(B)算命不需鼓板，也不講忠孝故事。(C)(D)使臣、御史是官員，不會敲鼓搖板、講稗官故事。", "skill": "職業推論題：把文中的『道具、動作、內容』三類線索圈出來，再對照各職業的特徵。"}], "difficulty": "易", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk111-18", "exam": "hk111", "nums": [18], "form": "單題", "img": "img/hk111-18.png", "source": "李漁《閒情偶寄‧飲饌部》", "author": "李漁", "genre": "筆記小品", "types": ["句意理解", "寫作手法"], "passage": "粥之既熟，水米成交，猶米之釀而為酒矣。慮其太厚而入水於粥，猶入水於酒也，水入而酒成糟粕，其味尚可咀乎？故熬前挹水必限以數，使其勺不能增，滴無可減。", "translation": "粥熬熟以後，水和米已經交融在一起，就像米已經釀成了酒。擔心粥太濃稠而往粥裡加水，就像往酒裡加水一樣，水加進去酒就變成了糟粕，那味道還能品嚐嗎？所以熬粥之前舀水一定要限定份量，讓它多一勺也不能增加、少一滴也不能減少。", "keywords": [{"w": "既", "m": "已經"}, {"w": "成交", "m": "交融在一起"}, {"w": "猶", "m": "好像"}, {"w": "慮", "m": "擔心"}, {"w": "厚", "m": "濃稠"}, {"w": "糟粕", "m": "酒渣，比喻無味的東西"}, {"w": "咀", "m": "品嚐"}, {"w": "挹", "m": "舀水"}, {"w": "數", "m": "定數、份量"}], "questions": [{"n": 18, "stem": "「粥之既熟，水米成交，猶米之釀而為酒矣。慮其太厚而入水於粥，猶入水於酒也，水入而酒成糟粕，其味尚可咀乎？故熬前挹水必限以數，使其勺不能增，滴無可減。」根據這段文字，作者對於熬粥的看法，下列敘述何者最恰當？", "options": {"A": "熬煮前須加足適量的水", "B": "熬煮時可適度添加米飯", "C": "熬煮過程中可加酒提味", "D": "熬煮過久容易生出糟粕"}, "answer": "A", "explain": "作者反對粥熟後再加水，所以結論是「熬前挹水必限以數」，在煮之前就把水量放準，選(A)。(B)文中沒有提到加米飯。(C)酒只是比喻，不是真的加酒。(D)糟粕是比喻「後來加水會使味道變差」，不是煮太久。", "skill": "比喻說理題：分清楚喻體（酒）與本體（粥），結論通常在「故」字之後。"}], "difficulty": "易", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk111-20", "exam": "hk111", "nums": [20], "form": "單題", "img": "img/hk111-20.png", "source": "周在〈閨怨〉", "author": "周在", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "江南二月試羅衣，春盡燕山雪尚飛。應是子規啼不到，故鄉雖好不思歸。", "translation": "江南二月已經可以試穿輕薄的絲羅衣服，春天都快過完了，燕山那裡還在飄雪。想必是杜鵑鳥「不如歸去」的叫聲傳不到那裡，所以（他）雖然知道故鄉好，卻不想回來。", "keywords": [{"w": "試", "m": "開始穿"}, {"w": "羅衣", "m": "絲質的衣服"}, {"w": "燕山", "m": "北方的山，指遠方邊地"}, {"w": "子規", "m": "杜鵑鳥，啼聲如「不如歸去」"}], "questions": [{"n": 20, "stem": "「江南二月試羅衣，春盡燕山雪尚飛。應是子規啼不到，故鄉雖好不思歸。」關於這首詩的分析，下列說明何者最恰當？", "options": {"A": "就體裁而言，這是一首七言律詩", "B": "就形式而言，對仗工整，句句押韻", "C": "以「試羅衣」、「雪尚飛」對比兩地氣候差異", "D": "以遊子口吻寫出羈旅在外、難以返回的鄉愁"}, "answer": "C", "explain": "江南二月已穿薄衣，北方燕山春末還在下雪，用「試羅衣」和「雪尚飛」對比南北氣候，選(C)。(A)只有四句，是七言絕句。(B)絕句不要求對仗，本詩一、二句也沒有工整對仗；押韻的是衣、飛、歸，第三句「到」不押韻。(D)詩題是〈閨怨〉，是留在江南的女子埋怨遠在燕山的人不回家，不是遊子自述。", "skill": "先數句數判斷體裁；再想「說話的人在哪裡」——在江南穿羅衣、推想對方不歸的，是家中的人。"}], "difficulty": "中", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk111-22", "exam": "hk111", "nums": [22], "form": "單題", "img": "img/hk111-22.png", "source": "出處待查", "author": "", "genre": "說理議論", "types": ["文意推論", "寫作手法"], "passage": "學者如取水，終日取而不能踰其量，故操瓢者止於瓢，操盎者止於盎；教者如分火，終日分而未嘗虧其體，故散為十燈而明自若，散為千燈而明自若。故善學者＿＿＿＿，善教者＿＿＿＿。", "translation": "學習的人就像取水，整天取水也不能超過容器的容量，所以拿瓢的只能取一瓢，拿盆的只能取一盆；教導的人就像分火，整天分火也不曾減損本身的火，所以分成十盞燈，光明依然如故，分成千盞燈，光明還是如故。所以善於學習的人（不把自己的器量限制得狹小），善於教導的人（不吝惜自己的光亮）。", "keywords": [{"w": "踰", "m": "超過"}, {"w": "量", "m": "容量"}, {"w": "操", "m": "拿著"}, {"w": "瓢", "m": "舀水的瓢子"}, {"w": "盎", "m": "腹大口小的盆"}, {"w": "虧", "m": "減損"}, {"w": "自若", "m": "依然如故"}, {"w": "隘", "m": "使狹窄"}, {"w": "吝", "m": "吝惜"}], "questions": [{"n": 22, "stem": "「學者如取水，終日取而不能踰其量，故操瓢者止於瓢，操盎者止於盎；教者如分火，終日分而未嘗虧其體，故散為十燈而明自若，散為千燈而明自若。故善學者＿＿＿＿，善教者＿＿＿＿。」根據文意脈絡，畫線處依序填入下列何者最恰當？", "options": {"A": "不自隘其器／不自吝其光", "B": "如逆水行舟／似雪中取火", "C": "宜自知其量／宜自晦其光", "D": "無一時之患／有終身之憂"}, "answer": "A", "explain": "取水能取多少取決於容器大小，所以善學者要「不自隘其器」——不把自己的器量限制小；分火不會減損本身的光，所以善教者要「不自吝其光」——不吝惜分享，選(A)。(B)逆水行舟講不進則退，雪中取火講不可能，都與取水、分火的比喻無關。(C)「自知其量」接近，但「自晦其光」（隱藏光芒）與分火的道理相反。(D)與比喻無關。", "skill": "比喻對應：取水→器（容量）、分火→光（不虧），答案的關鍵字必須與比喻中的物件呼應。"}], "difficulty": "中", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk111-23", "exam": "hk111", "nums": [23], "form": "單題", "img": "img/hk111-23.png", "source": "《莊子‧秋水》", "author": "莊子", "genre": "寓言故事", "types": ["主旨寓意", "人物情感"], "passage": "莊子釣於濮水，楚王使大夫二人往先焉，曰：「願以境內累矣！」莊子持竿不顧，曰：「吾聞楚有神龜，死已三千歲矣，王巾笥而藏之廟堂之上。此龜者，寧其死為留骨而貴乎，寧其生而曳尾於塗中乎？」二大夫曰：「寧生而曳尾塗中。」莊子曰：「往矣！吾將曳尾於塗中。」", "translation": "莊子在濮水釣魚，楚王派兩位大夫先去表達心意，說：「希望把國內的政事託付給您，勞煩您了！」莊子拿著釣竿頭也不回，說：「我聽說楚國有一隻神龜，已經死了三千年，楚王用巾布包著、竹箱裝著，把牠供奉在廟堂上。這隻龜，是寧願死了留下骨頭被人尊貴供奉呢？還是寧願活著拖著尾巴在泥巴裡爬呢？」兩位大夫說：「寧願活著在泥巴裡拖著尾巴爬。」莊子說：「你們走吧！我也要拖著尾巴在泥巴裡爬。」", "keywords": [{"w": "先", "m": "先前往表達心意"}, {"w": "累", "m": "勞煩、拖累"}, {"w": "顧", "m": "回頭看"}, {"w": "巾笥", "m": "用巾包、用竹箱裝（名詞作動詞）"}, {"w": "寧", "m": "寧願"}, {"w": "曳", "m": "拖"}, {"w": "塗", "m": "泥巴"}, {"w": "往", "m": "離開、走吧"}], "questions": [{"n": 23, "stem": "根據這段文字，下列何者與莊子的想法最接近？", "options": {"A": "人死留名，虎死留皮", "B": "不慕榮利，唯願逍遙", "C": "神龜雖壽，猶有竟時", "D": "寧鳴而死，不默而生"}, "answer": "B", "explain": "神龜被供在廟堂是尊貴但已死去，比喻做官得到榮華卻失去自由；曳尾塗中雖卑微卻自在，比喻隱居自由。莊子選擇曳尾塗中，表示他不羨慕官位榮利，只想自在逍遙，選(B)。(A)重視死後留名，正好是莊子不要的「留骨而貴」。(C)講生命有盡頭，與本文無關。(D)寧願發聲而死，是強調直言的氣節，與莊子避世的態度相反。", "skill": "寓言對照：把兩個選項（死而貴／生而曳尾）分別對應到現實（做官／隱居），看人物選了哪一邊。"}], "difficulty": "易", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk111-24", "exam": "hk111", "nums": [24], "form": "單題", "img": "img/hk111-24.png", "source": "《呂氏春秋》", "author": "呂不韋門客", "genre": "說理議論", "types": ["寫作手法"], "passage": "世人之事君者，皆以孫叔敖之遇楚莊王為幸，自有道者論之則不然，此楚國之幸。楚莊王好周遊田獵，馳騁弋射，歡樂無遺，盡付其境內之勞與諸侯之憂於孫叔敖。孫叔敖日夜不息，不得顧及養生之事，故使莊王功績著乎竹帛，傳乎後世。", "translation": "世上侍奉君主的人，都認為孫叔敖遇到楚莊王是幸運的；但從有道之人的角度來看卻不是這樣，這其實是楚國的幸運。楚莊王喜歡四處遊玩打獵，騎馬奔馳、射鳥打獵，盡情享樂毫無保留，把國內的政務和對付諸侯的憂患全部交給孫叔敖。孫叔敖日夜不停地操勞，連保養身體的事都顧不上，所以使楚莊王的功績記載在史冊上，流傳到後世。", "keywords": [{"w": "事", "m": "侍奉"}, {"w": "以……為幸", "m": "認為……是幸運的"}, {"w": "有道者", "m": "明白事理的人"}, {"w": "田獵", "m": "打獵"}, {"w": "弋射", "m": "用帶繩的箭射鳥"}, {"w": "無遺", "m": "毫無保留"}, {"w": "付", "m": "交付"}, {"w": "著", "m": "記載、顯揚"}, {"w": "竹帛", "m": "史冊"}], "questions": [{"n": 24, "stem": "「世人之事君者，皆以孫叔敖之遇楚莊王為幸，自有道者論之則不然，此楚國之幸。楚莊王好周遊田獵，馳騁弋射，歡樂無遺，盡付其境內之勞與諸侯之憂於孫叔敖。孫叔敖日夜不息，不得顧及養生之事，故使莊王功績著乎竹帛，傳乎後世。」關於這段文字的寫作手法，下列說明何者最恰當？", "options": {"A": "先提出世俗看法，再以不同論點反駁", "B": "先從正、反兩面論述，再另舉他例說明", "C": "先記敘孫叔敖事蹟，再評論楚莊王功績", "D": "先以楚莊王觀點闡述，再從孫叔敖立場反駁"}, "answer": "A", "explain": "開頭「世人……皆以孫叔敖之遇楚莊王為幸」是世俗看法，接著「自有道者論之則不然，此楚國之幸」提出相反論點，再用莊王享樂、叔敖勞苦的事實證明是楚國得到叔敖才幸運，選(A)。(B)全文只談孫叔敖與楚莊王，沒有另舉他例。(C)開頭先是議論，不是記敘。(D)文中沒有站在楚莊王的觀點闡述。", "skill": "看到「世人皆以……，……則不然」的句型，就是『先立靶、再反駁』的駁論結構。"}], "difficulty": "難", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk111-39", "exam": "hk111", "nums": [39, 40], "form": "題組", "img": "img/hk111-39.png", "source": "【甲】《史記‧平準書》；【乙】《西京雜記》（皆改寫）", "author": "司馬遷；（舊題）劉歆／葛洪", "genre": "史傳人物", "types": ["比較閱讀", "文意推論", "文化常識"], "passage": "【甲】文帝時，莢錢益多，輕，乃更鑄四銖錢，上鑄「半兩」字樣，民亦得自鑄錢。故吳王就山鑄錢，富等天子，其後以此叛逆。又有大夫鄧通者，亦以鑄錢富甲天下。故吳、鄧氏錢布天下，而後乃生鑄錢之禁。\n【乙】漢文帝時，鄧通得賜蜀銅山，聽得鑄錢，形制文字重量，皆與天子四銖錢同。時吳王亦有銅山鑄錢，故有吳錢，微重，形制文字，與天子錢不異。", "translation": "【甲】漢文帝時，莢錢越來越多，又很輕，於是改鑄四銖錢，錢上鑄著「半兩」的字樣，百姓也可以自己鑄錢。所以吳王靠著山中銅礦鑄錢，富有得和天子相當，後來就憑這些財富叛亂。又有個大夫叫鄧通，也因為鑄錢而富甲天下。因此吳王和鄧氏的錢遍布天下，後來才產生禁止私鑄錢幣的法令。\n【乙】漢文帝時，鄧通得到皇帝賞賜的蜀地銅山，允許他鑄錢，錢的形制、文字、重量，都和天子的四銖錢相同。當時吳王也有銅山鑄錢，所以有「吳錢」，稍微重一點，形制文字和天子的錢沒有差別。", "keywords": [{"w": "莢錢", "m": "西漢初年所鑄銅錢，形如榆莢"}, {"w": "益", "m": "更加"}, {"w": "更", "m": "改"}, {"w": "得", "m": "可以"}, {"w": "就山", "m": "靠著山（的銅礦）"}, {"w": "等", "m": "相等"}, {"w": "布", "m": "遍布、流通"}, {"w": "聽", "m": "允許"}, {"w": "形制", "m": "形狀規格"}, {"w": "微", "m": "稍微"}, {"w": "不異", "m": "沒有不同"}], "questions": [{"n": 39, "stem": "根據甲、乙兩文推論，漢文帝時各種錢幣的重量依序最可能是下列何者？", "options": {"A": "四銖錢＞吳錢＞鄧通錢", "B": "四銖錢＝鄧通錢＞吳錢", "C": "吳錢＞四銖錢＞鄧通錢", "D": "吳錢＞鄧通錢＝四銖錢"}, "answer": "D", "explain": "乙文說鄧通錢「形制文字重量，皆與天子四銖錢同」，所以鄧通錢＝四銖錢；吳錢「微重」，比天子錢稍重，所以吳錢＞鄧通錢＝四銖錢，選(D)。", "skill": "比較數量：把每個「同」「微重」轉成等號、大於號，再排出順序。"}, {"n": 40, "stem": "根據甲、乙兩文，下列敘述何者最恰當？", "options": {"A": "鄧通與吳王同時自鑄莢錢，導致莢錢過多", "B": "鄧通與吳王所鑄銅錢上應有「半兩」字樣", "C": "鄧通叛逆謀反，文帝遂下令禁止私鑄銅錢", "D": "鄧通所鑄錢布天下，故文帝賜其銅山一座"}, "answer": "B", "explain": "甲文說文帝改鑄的四銖錢「上鑄『半兩』字樣」；乙文說鄧通錢、吳錢的形制文字都與天子錢相同，所以兩人鑄的錢上也應有「半兩」二字，選(B)。(A)莢錢過多是改鑄四銖錢之前的事，兩人鑄的是四銖錢樣式。(C)叛逆的是吳王，不是鄧通。(D)順序顛倒：先賜銅山，鄧通才能鑄錢，錢才遍布天下。", "skill": "兩文整合：甲文給一條資訊（四銖錢有「半兩」），乙文給另一條（形制文字相同），兩條相加才推得出答案。"}], "difficulty": "難", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk111-41", "exam": "hk111", "nums": [41, 42], "form": "題組", "img": "img/hk111-41.png", "source": "王定保《唐摭言》（改寫）", "author": "王定保", "genre": "筆記小品", "types": ["虛詞句式", "人物情感", "文意推論"], "passage": "王起主文柄，欲以白敏中為狀元，病其與賀拔惎為友。惎有文而落拓。乃密令門人申意，俾敏中與惎絕。門人復約敏中，具以告之。敏中曰：「皆如所教。」既而惎果造門，左右欺以敏中他適，惎遲留不言而去。俄頃，敏中躍出，連呼左右召惎，悉以實告，曰：「一第何患不致，奈輕負至交！」相與歡醉。門人睹之，大怒而去。懇告於起，且云不可必矣。起曰：「我原只得白敏中，今當更取賀拔惎矣。」", "translation": "王起主持科舉考試，想讓白敏中當狀元，卻不滿意他和賀拔惎是朋友。賀拔惎有文才但行為放蕩不羈。王起就祕密叫門人去轉達意思，要白敏中和賀拔惎斷交。門人又約見白敏中，把這些話都告訴他。白敏中說：「一切照您的指示。」不久賀拔惎果然登門拜訪，僕人騙他說白敏中到別處去了，賀拔惎停留了一會兒，沒說什麼就走了。一下子，白敏中跳出來，連聲叫僕人把賀拔惎找回來，把實情全部告訴他，說：「考取功名哪怕得不到呢？怎能輕易辜負至交好友！」兩人一起開懷暢飲。門人看到了，大怒離去，把情形告訴王起，並說白敏中一定不能錄取了。王起說：「我原本只取白敏中一人，現在應當再加取賀拔惎了。」", "keywords": [{"w": "主文柄", "m": "主持科舉考試"}, {"w": "病", "m": "不滿、擔憂（動詞）"}, {"w": "落拓", "m": "放蕩不羈"}, {"w": "申意", "m": "轉達意思"}, {"w": "俾", "m": "使"}, {"w": "絕", "m": "斷交"}, {"w": "具", "m": "全部"}, {"w": "造門", "m": "登門拜訪"}, {"w": "他適", "m": "到別處去"}, {"w": "悉", "m": "全部"}, {"w": "一第", "m": "一次科舉及第"}, {"w": "何患", "m": "何必擔心"}, {"w": "更", "m": "再、另外"}], "questions": [{"n": 41, "stem": "根據本文，下列文句省略的主語，何者是白敏中？", "options": {"A": "病其與賀拔惎為友", "B": "乃密令門人申意", "C": "悉以實告", "D": "大怒而去"}, "answer": "C", "explain": "「敏中躍出，連呼左右召惎，悉以實告」，一連串動作的主語都是白敏中，他把實情全部告訴賀拔惎，選(C)。(A)(B)不滿他交友、密令門人傳話的是主考官王起。(D)看到兩人歡醉而大怒離去的是門人。", "skill": "省略主語：沿著句子往前找最近出現的人名，並用情理檢查（誰有權命令門人？誰會生氣？）。"}, {"n": 42, "stem": "根據本文，王起說：「我原只得白敏中，今當更取賀拔惎矣。」這句話的原因，最可能是下列何者？", "options": {"A": "白敏中向王起推薦賀拔惎取代自己", "B": "賀拔惎已知此次科考內幕，只好破格錄取封口", "C": "比起白敏中的前倨後恭，賀拔惎的真誠顯得更為可貴", "D": "白敏中把賀拔惎看得比狀元還重，可知賀拔惎有過人之處"}, "answer": "D", "explain": "白敏中寧可冒著失去狀元的風險，也不願辜負賀拔惎，說「一第何患不致，奈輕負至交」。王起由此看出：能讓白敏中如此看重的朋友，一定有過人之處，所以決定加取賀拔惎，選(D)。(A)白敏中沒有向王起推薦任何人。(B)文中沒有封口的意思。(C)白敏中是先答應、後反悔，不是前倨後恭；文中也沒有寫賀拔惎的真誠表現。", "skill": "推論人物決定的理由：把結果（加取賀拔惎）和前面最關鍵的事件（白敏中重友輕名）連起來。"}], "difficulty": "難", "label": "111年會考", "year": 111, "kind": "會考"}, {"id": "hk112-10", "exam": "hk112", "nums": [10], "form": "單題", "img": "img/hk112-10.png", "source": "金聖歎〈三十三則不亦快哉〉（《貫華堂第六才子書西廂記》批語）", "author": "金聖歎", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "夏七月，赤日停天，亦無風，亦無雲。前後庭赫然如洪爐，無一鳥敢來飛。汗出遍身，縱橫成渠。置飯於前，不可得吃。呼簟欲臥地上，則地濕如膏，蒼蠅又來緣頸附鼻，驅之不去。正莫可如何，忽然疾澍澎湃之聲，如數百萬金鼓。簷溜浩於瀑布。身汗頓收，地燥如掃，蒼蠅盡去，飯便得吃。不亦快哉！", "translation": "農曆七月，烈日停在天上，沒風也沒雲。前後院熱得像大火爐，連一隻鳥都不敢飛來。全身冒汗，汗水縱橫流成小溝。飯放在面前，熱得吃不下。叫人拿竹蓆想躺在地上，地面卻溼得像油膏，蒼蠅又飛來爬在脖子、鼻子上，怎麼趕也趕不走。正無可奈何時，忽然傳來急雨澎湃的聲音，像幾百萬面鑼鼓齊響。屋簷流下的水比瀑布還大。身上的汗立刻收了，地面乾爽得像掃過，蒼蠅全跑光，飯也吃得下了。這不是很痛快嗎！", "keywords": [{"w": "赤日停天", "m": "烈日高掛不動"}, {"w": "簟", "m": "竹蓆"}, {"w": "緣", "m": "沿著、爬上"}, {"w": "疾澍", "m": "急降的大雨"}, {"w": "簷溜", "m": "屋簷流下的雨水"}, {"w": "頓", "m": "立刻"}], "questions": [{"n": 10, "stem": "「夏七月，赤日停天，亦無風，亦無雲。前後庭赫然如洪爐，無一鳥敢來飛。汗出遍身，縱橫成渠。置飯於前，不可得吃。呼簟欲臥地上，則地濕如膏，蒼蠅又來緣頸附鼻，驅之不去。正莫可如何，忽然疾澍澎湃之聲，如數百萬金鼓。簷溜浩於瀑布。身汗頓收，地燥如掃，蒼蠅盡去，飯便得吃。不亦快哉！」根據這段文字，作者心情轉變的關鍵最可能是下列何者？", "options": {"A": "發現美麗的景致", "B": "遠離擾人的蟲蠅", "C": "聽見悅耳的鼓聲", "D": "驟降消暑的大雨"}, "answer": "D", "explain": "前半寫酷熱難耐、汗流不止、吃不下飯、蒼蠅擾人；轉折點是「忽然疾澍澎湃之聲」──一場急雨，之後「身汗頓收，地燥如掃，蒼蠅盡去，飯便得吃」，所有煩惱一掃而空，所以關鍵是驟降消暑的大雨，選(D)。(A)文中沒有寫美景。(B)蒼蠅離開是下雨的「結果」，不是關鍵原因。(C)「如數百萬金鼓」是比喻雨聲，並非真的聽到鼓聲。", "skill": "找出文中「正莫可如何，忽然……」這個轉折點，分清楚原因（大雨）和結果（汗收、蠅去、能吃飯）；比喻句的喻體不能當真。"}], "difficulty": "易", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk112-12", "exam": "hk112", "nums": [12], "form": "單題", "img": "img/hk112-12.png", "source": "《國語‧晉語九》", "author": "左丘明（傳）", "genre": "史傳人物", "types": ["字詞解釋"], "passage": "少室周為趙簡子之右，聞牛談有力，請與之競，弗勝，致右焉。簡子許之，使少室周為宰，曰：「知賢而讓，可以為訓矣。」", "translation": "少室周擔任趙簡子的車右（貼身護衛），聽說牛談力氣很大，就請求和他比試，結果比輸了，便把車右的職位讓給牛談。趙簡子答應了，並讓少室周擔任家宰，說：「知道別人比自己賢能就讓位，可以作為大家的榜樣了。」", "keywords": [{"w": "右", "m": "車右，立在君主右邊負責保衛的職官"}, {"w": "競", "m": "比試"}, {"w": "致", "m": "禮讓、讓出"}, {"w": "宰", "m": "家臣之長、總管"}, {"w": "訓", "m": "典範、可效法的準則"}], "questions": [{"n": 12, "stem": "「少室周為趙簡子之右，聞牛談有力，請與之競，弗勝，致右焉。簡子許之，使少室周為宰，曰：『知賢而讓，可以為訓矣。』」根據文意脈絡，下列何者最適合用來說明「訓」字的意義？", "options": {"A": "典範", "B": "順從", "C": "教誨", "D": "解釋"}, "answer": "A", "explain": "趙簡子讚美少室周「知賢而讓」（知道別人比自己強就讓位），這種行為「可以為訓」，意思是可以作為眾人效法的榜樣，所以「訓」是典範、準則，選(A)。(B)順從：句意變成「可以作為順從」，不通。(C)教誨：「訓」雖常解作教導，但這裡是說少室周的行為值得效法，而非他在教誨別人。(D)解釋：如「訓詁」的訓，與文意無關。", "skill": "一字多義時，把每個選項代回原句「可以為○矣」讀讀看，再對照前文「知賢而讓」是一種值得學習的行為。"}], "difficulty": "中", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk112-13", "exam": "hk112", "nums": [13], "form": "單題", "img": "img/hk112-13.png", "source": "《韓非子‧外儲說右下》", "author": "韓非", "genre": "寓言故事", "types": ["主旨寓意"], "passage": "茲鄭引輦上高梁而不能支。茲鄭倚轅而歌，前者止，後者趨，輦乃上。使茲鄭無術以致人，則身雖絕力至死，輦猶不上也。今身不至勞苦而輦以上者，有術以致人之故也。", "translation": "茲鄭拉著人力車要上高橋，卻撐不住。茲鄭便靠在車轅上唱起歌來，前面的人停下來，後面的人趕過來（幫忙推），車子就上去了。假使茲鄭沒有招引別人的方法，那麼他就算用盡力氣累死，車子還是上不去。如今自己不必太勞苦車子就上去了，是因為他有招引別人來幫忙的方法啊。", "keywords": [{"w": "輦", "m": "古時用人拉著走的車"}, {"w": "梁", "m": "橋"}, {"w": "支", "m": "支撐"}, {"w": "趨", "m": "快步走來"}, {"w": "術", "m": "方法、技巧"}, {"w": "致人", "m": "招引別人"}], "questions": [{"n": 13, "stem": "「茲鄭引輦上高梁而不能支。茲鄭倚轅而歌，前者止，後者趨，輦乃上。使茲鄭無術以致人，則身雖絕力至死，輦猶不上也。今身不至勞苦而輦以上者，有術以致人之故也。」這段文字的主旨最可能是下列何者？", "options": {"A": "團結就是力量", "B": "做事要講究方法", "C": "堅持到底才能成功", "D": "沒有付出就沒有收穫"}, "answer": "B", "explain": "末句直接點題：「有術以致人之故也」──車子能上去，是因為茲鄭有「方法」吸引眾人幫忙；文中還對比「無術」就算「絕力至死」也上不去。所以主旨是做事要講究方法，選(B)。(A)雖然最後是眾人一起推，但文章強調的是茲鄭「懂得用方法招人」，不是團結本身。(C)茲鄭沒有靠硬撐，反而說硬撐到死也沒用。(D)文中說「身不至勞苦」就成功，與「要付出」相反。", "skill": "說理寓言的主旨通常藏在最後的議論句，抓住關鍵字「術」與「無術／有術」的對比。"}], "difficulty": "易", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk112-15", "exam": "hk112", "nums": [15], "form": "單題", "img": "img/hk112-15.png", "source": "白居易〈魏王堤〉、晁沖之〈春日〉", "author": "白居易、晁沖之", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "甲：花寒懶發鳥慵啼，信馬閑行到日西。何處未春先有思？柳條無力魏王堤。──白居易〈魏王堤〉\n乙：陰陰溪曲綠交加，小雨翻萍上淺沙。鵝鴨不知春去盡，爭隨流水趁桃花。──晁沖之〈春日〉", "translation": "甲：天氣還冷，花懶得開，鳥也懶得叫；我任馬隨意慢行，一直走到太陽西斜。哪裡還沒到春天就先有了春意？是魏王堤上那柔軟無力的柳條。\n乙：彎曲的溪邊綠蔭濃密交錯，小雨把浮萍翻打到淺灘沙上。鵝和鴨不知道春天已經過完，還爭著隨流水去追逐飄落的桃花。", "keywords": [{"w": "慵", "m": "懶"}, {"w": "信馬", "m": "任馬隨意行走"}, {"w": "思", "m": "情思，這裡指春意"}, {"w": "陰陰", "m": "幽暗濃密的樣子"}, {"w": "趁", "m": "追逐"}], "questions": [{"n": 15, "stem": "甲：花寒懶發鳥慵啼，信馬閑行到日西。何處未春先有思？柳條無力魏王堤。──白居易〈魏王堤〉　乙：陰陰溪曲綠交加，小雨翻萍上淺沙。鵝鴨不知春去盡，爭隨流水趁桃花。──晁沖之〈春日〉　關於這兩首詩的分析，下列敘述何者最恰當？", "options": {"A": "甲詩描寫清晨春寒料峭的景象", "B": "乙詩描寫春末溪邊所見的景致", "C": "兩詩首二句皆對仗，表達情思", "D": "兩詩皆屬七絕，只有偶句用韻"}, "answer": "B", "explain": "乙詩寫溪曲、綠蔭、小雨、浮萍、淺沙、鵝鴨，並說「春去盡」「流水趁桃花」（桃花已落），是春末溪邊景致，(B)正確。(A)甲詩「信馬閑行到日西」寫到傍晚，不是清晨。(C)甲詩首二句「花寒懶發鳥慵啼／信馬閑行到日西」、乙詩「陰陰溪曲綠交加／小雨翻萍上淺沙」字詞詞性不相對，都不是對仗。(D)兩首都是七言絕句沒錯，但甲詩「啼、西、堤」、乙詩「加、沙、花」，首句也押韻，不是只有偶句押韻。", "skill": "判斷時間點找時間詞（日西、春去盡）；檢查押韻要把第一、二、四句句尾字都唸一遍，不要只看偶數句。"}], "difficulty": "中", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk112-16", "exam": "hk112", "nums": [16], "form": "單題", "img": "img/hk112-16.png", "source": "出處待查", "author": "出處待查", "genre": "說理議論", "types": ["文意推論", "句意理解"], "passage": "蓋天下有反覆之小人，亦有反覆之君子。人但知不反覆不足以為小人，庸知不反覆亦不足以為君子。蓋小人之反覆也，因風氣勢利之所歸，以為變動；君子之反覆也，因學識之層累疊進，以為變動。其反覆同，其所以為反覆者不同。", "translation": "天下有反覆無常的小人，也有會改變立場的君子。人們只知道不反覆就稱不上小人，哪裡知道不反覆也稱不上君子呢？小人的反覆，是跟著風氣和權勢利益的流向而改變；君子的反覆，是因為學問見識一層層累積進步而改變。兩者的「反覆」看起來相同，但反覆的原因並不一樣。", "keywords": [{"w": "反覆", "m": "改變、變來變去"}, {"w": "但", "m": "只"}, {"w": "庸知", "m": "哪裡知道"}, {"w": "所歸", "m": "所趨向的地方"}, {"w": "層累疊進", "m": "一層層累積、不斷進步"}], "questions": [{"n": 16, "stem": "「蓋天下有反覆之小人，亦有反覆之君子。人但知不反覆不足以為小人，庸知不反覆亦不足以為君子。蓋小人之反覆也，因風氣勢利之所歸，以為變動；君子之反覆也，因學識之層累疊進，以為變動。其反覆同，其所以為反覆者不同。」根據這段文字，作者認為「不反覆亦不足以為君子」的原因，最可能是下列何者？", "options": {"A": "小人若洗心革面，一反前非即可成為君子", "B": "為應對小人反覆，不得不改變既有的策略", "C": "順應民心的向背，選擇最適合現況的做法", "D": "隨著所知的增長，會修正自己原本的觀點"}, "answer": "D", "explain": "文中說「君子之反覆也，因學識之層累疊進，以為變動」，君子會改變，是因為學問見識不斷累積、進步，所以會修正原本的看法；如果一成不變，反而表示沒有進步，所以「不反覆亦不足以為君子」，選(D)。(A)文章沒談小人如何變成君子。(B)君子改變是因為學識增長，不是為了應付小人。(C)「順應風氣、趨向勢利」反而是小人反覆的原因。", "skill": "遇到對比句（小人之反覆……君子之反覆……），先把兩邊的原因分開列出來，再找題目問的是哪一邊。"}], "difficulty": "中", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk112-20", "exam": "hk112", "nums": [20], "form": "單題", "img": "img/hk112-20.png", "source": "蘇軾〈西江月〉（世事一場大夢）", "author": "蘇軾", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "世事一場大夢，人生幾度新涼？夜來風葉已鳴廊，看取眉頭鬢上。　酒賤常愁客少，月明多被雲妨。中秋誰與共孤光，把盞淒然北望。", "translation": "世上的事就像一場大夢，人生能經歷幾次初秋的涼意？夜裡風吹落葉，在迴廊上沙沙作響；看看自己眉頭、鬢邊，已添了愁容與白髮。酒雖便宜，卻常愁沒有客人來共飲；月色明亮，又常被雲遮住。這中秋夜，有誰和我共賞這孤月？我只能端起酒杯，淒涼地向北方遙望。", "keywords": [{"w": "新涼", "m": "初秋的涼意"}, {"w": "看取", "m": "看看"}, {"w": "妨", "m": "妨礙、遮蔽"}, {"w": "孤光", "m": "孤月的光"}, {"w": "把盞", "m": "拿著酒杯"}], "questions": [{"n": 20, "stem": "蘇軾〈西江月〉：「世事一場大夢，人生幾度新涼？夜來風葉已鳴廊，看取眉頭鬢上。酒賤常愁客少，月明多被雲妨。中秋誰與共孤光，把盞淒然北望。」下列關於詞句的說明，何者最不恰當？", "options": {"A": "「看取眉頭鬢上」表達自己年華老去", "B": "「酒賤常愁客少」意謂難以維持生計", "C": "「月明多被雲妨」比喻美好的事物不可能長久", "D": "「中秋誰與共孤光」流露想與親友團聚的心願"}, "answer": "B", "explain": "本題選「最不恰當」。「酒賤常愁客少」是說酒雖便宜，卻少有朋友來共飲，寫的是孤獨寂寞與人情冷落，並不是賣酒的生意不好、難以維持生計，所以(B)不恰當。(A)眉頭的愁、鬢上的白髮，表示年華老去，正確。(C)明月常被雲遮，暗喻好景難以圓滿長久，正確。(D)中秋本是團圓節，「誰與共」「北望」表達思念親人、渴望團聚，正確。", "skill": "讀詞要把句子放回全詞的情感（孤寂、悲秋）去理解；選項若把抒情句解成現實經濟問題，多半是曲解。注意題目問「最不恰當」。"}], "difficulty": "中", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk112-22", "exam": "hk112", "nums": [22], "form": "單題", "img": "img/hk112-22.png", "source": "徐宏祖《徐霞客遊記‧遊黃山日記（後）》", "author": "徐宏祖（徐霞客）", "genre": "山水遊記", "types": ["文意推論", "人物情感"], "passage": "復北上，行石罅中，石峰片片夾起，路宛轉石間，塞者鑿之，陡者級之，斷者架木通之，懸者植梯接之。下瞰峭壑陰森，楓松相間，五色紛披，燦若圖繡。因念黃山當生平奇覽，而有奇若此，前未一探，茲遊快且愧矣！", "translation": "又往北走，走在石縫中，石峰一片片從兩旁夾立而起，路在石頭間曲折迴繞；堵住的地方就鑿開，陡峭的地方就鑿成臺階，斷開的地方架木頭接通，懸空的地方豎起梯子連接。往下看，陡峭的山谷幽深陰暗，楓樹和松樹交錯，五顏六色紛紛披散，燦爛得像錦繡圖畫。於是想到黃山是我這輩子見過最奇特的景觀，卻還有這樣奇特的地方，上次竟沒來探訪，這次遊覽既痛快又慚愧啊！", "keywords": [{"w": "罅", "m": "縫隙"}, {"w": "級之", "m": "鑿成臺階"}, {"w": "瞰", "m": "往下看"}, {"w": "壑", "m": "山谷"}, {"w": "紛披", "m": "散布錯雜"}, {"w": "茲", "m": "這、此"}], "questions": [{"n": 22, "stem": "「復北上，行石罅中，石峰片片夾起，路宛轉石間，塞者鑿之，陡者級之，斷者架木通之，懸者植梯接之。下瞰峭壑陰森，楓松相間，五色紛披，燦若圖繡。因念黃山當生平奇覽，而有奇若此，前未一探，茲遊快且愧矣！」根據這段文字，下列敘述何者最恰當？", "options": {"A": "作者對自己破壞自然環境感到慚愧", "B": "黃山片片石峰色彩繽紛，有如織錦", "C": "作者北上舊地重遊，乃因懷念黃山冬季美景", "D": "此遊窺得黃山奇景，作者心中因而喜愧交集"}, "answer": "D", "explain": "結尾「茲遊快且愧矣」：「快」是看到奇景的痛快，「愧」是慚愧上次沒來探訪（前未一探），所以喜與愧交織，選(D)。(A)「鑿之、級之」是開路的方式，作者慚愧的是之前沒來，而非破壞環境。(B)「五色紛披，燦若圖繡」形容的是峭壑中楓松交錯的顏色，不是石峰。(C)文中沒有說是為了懷念冬季美景而重遊；「楓松相間，五色紛披」反而是秋景。", "skill": "抓結尾的情感句「快且愧」，再往前找「快」與「愧」各自的原因；比喻句要先確認形容的對象是誰。"}], "difficulty": "中", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk112-23", "exam": "hk112", "nums": [23], "form": "單題", "img": "img/hk112-23.png", "source": "沈括《夢溪筆談‧卷十四》", "author": "沈括", "genre": "筆記小品", "types": ["文意推論", "寫作手法"], "passage": "往歲士人多尚對偶為文，穆脩、張景輩始為平文，當時謂之古文。穆、張嘗同造朝，適見有奔馬踐死一犬，二人各記其事。穆脩曰：「馬逸，有黃犬遇蹄而斃。」張景曰：「有犬死奔馬之下。」時文體新變，二人之語皆拙澀，當時已謂之工，傳之至今。", "translation": "過去讀書人寫文章大多崇尚對偶，穆脩、張景這些人才開始寫不講對偶的散文，當時稱為「古文」。穆脩和張景曾經一起上朝，剛好看到一匹狂奔的馬踩死一隻狗，兩人各自把這件事記下來。穆脩寫：「馬狂奔，有隻黃狗碰上馬蹄而死。」張景寫：「有狗死在奔馬底下。」當時文體剛剛改變，兩人的句子都笨拙生澀，但當時已經認為寫得很好，一直流傳到現在。", "keywords": [{"w": "尚", "m": "崇尚"}, {"w": "平文", "m": "不講對偶的散文"}, {"w": "造朝", "m": "上朝"}, {"w": "逸", "m": "奔跑"}, {"w": "斃", "m": "死"}, {"w": "工", "m": "精巧、寫得好"}], "questions": [{"n": 23, "stem": "「往歲士人多尚對偶為文，穆脩、張景輩始為平文，當時謂之古文。穆、張嘗同造朝，適見有奔馬踐死一犬，二人各記其事。穆脩曰：『馬逸，有黃犬遇蹄而斃。』張景曰：『有犬死奔馬之下。』時文體新變，二人之語皆拙澀，當時已謂之工，傳之至今。」根據這段文字，關於穆脩、張景針對奔馬踐死一犬的記事，下列敘述何者最恰當？", "options": {"A": "穆脩記事只著眼於犬", "B": "張景記事只著眼於馬", "C": "二人用語崇尚句式對偶", "D": "二人用語皆為時人稱頌"}, "answer": "D", "explain": "文中說「當時已謂之工，傳之至今」，可見兩人的句子在當時都被稱讚寫得好，選(D)。(A)穆脩寫「馬逸，有黃犬遇蹄而斃」，馬和狗都寫到。(B)張景寫「有犬死奔馬之下」，也同時寫到狗和馬。(C)他們是「始為平文」的人，正是不講對偶，與「崇尚對偶」相反。", "skill": "分清楚作者的評價（拙澀）和當時人的評價（謂之工）；檢查「只著眼於」這類絕對說法，回原句逐字核對。"}], "difficulty": "中", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk112-24", "exam": "hk112", "nums": [24], "form": "單題", "img": "img/hk112-24.png", "source": "沈括《夢溪筆談‧卷十一》", "author": "沈括", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "錢塘江石堤為洪濤所激，歲歲摧決。杜偉長為轉運使，人有獻說，自浙江稅場以東，移退數里為月堤，以避怒水。眾水工皆以為善，獨一老水工以為不然，密諭其黨：『移堤則歲無水患，吾等何所衣食？』眾人樂其利，乃從而和之。偉長不悟其計，費以巨萬，而江堤之害仍歲有之。", "translation": "錢塘江的石堤被洶湧的浪濤衝擊，年年崩塌決口。杜偉長擔任轉運使時，有人獻計：從浙江稅場往東，把堤岸往後移幾里，築成月牙形的堤，來避開兇猛的江水。水工們都認為這方法好，只有一位老水工不以為然，偷偷告訴同伴：「把堤移了，年年就沒有水患，我們靠什麼吃飯穿衣？」大家貪圖這種好處，就跟著附和他（反對移堤）。杜偉長沒看穿他們的算計，花費了巨額金錢，江堤的災害卻仍年年發生。", "keywords": [{"w": "激", "m": "衝擊"}, {"w": "摧決", "m": "崩毀決口"}, {"w": "月堤", "m": "月牙形的堤防"}, {"w": "諭", "m": "告知"}, {"w": "黨", "m": "同伴"}, {"w": "和", "m": "附和"}, {"w": "悟", "m": "察覺、明白"}], "questions": [{"n": 24, "stem": "「錢塘江石堤為洪濤所激，歲歲摧決。杜偉長為轉運使，人有獻說，自浙江稅場以東，移退數里為月堤，以避怒水。眾水工皆以為善，獨一老水工以為不然，密諭其黨：『移堤則歲無水患，吾等何所衣食？』眾人樂其利，乃從而和之。偉長不悟其計，費以巨萬，而江堤之害仍歲有之。」根據這段文字，下列敘述何者最恰當？", "options": {"A": "月堤耗時過久，使杜偉長浪費公帑", "B": "水工們為保生計，阻礙了移堤工程", "C": "老水工深知修築月堤無益於防堵水患", "D": "杜偉長堅持移堤，導致年年發生水患"}, "answer": "B", "explain": "老水工說「移堤則歲無水患，吾等何所衣食」，怕水患沒了就沒工作；眾人「樂其利，乃從而和之」，一起反對移堤。結果移堤沒做成，杜偉長花大錢修舊堤，水患照舊。所以是水工們為了保住飯碗而阻礙移堤，選(B)。(A)文中沒提月堤耗時；錢是花在沒有移堤的修補上。(C)老水工其實知道移堤「歲無水患」（有用），他反對是為私利。(D)杜偉長「不悟其計」，最後並沒有移堤，水患是因為沒移堤。", "skill": "追蹤人物「說的理由」和「真正動機」：老水工公開反對，私下卻承認移堤有效，這個落差就是答案的關鍵。"}], "difficulty": "難", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk112-39", "exam": "hk112", "nums": [39, 40], "form": "題組", "img": "img/hk112-39.png", "source": "《明史‧奸臣傳‧嚴嵩》", "author": "張廷玉等", "genre": "史傳人物", "types": ["文意推論", "句意理解", "人物情感"], "passage": "大將軍仇鸞，始為曾銑所劾，欲倚嚴嵩以抗曾銑，故約為父子。已而鸞得帝重，嵩猶視之若子，遂浸相惡。嵩密疏毀鸞，帝不聽，而頗納鸞所陳嵩父子過，少疏之。嵩當入值，不召者數矣。嵩見徐階、李本入西內，即與俱入。至西華門，門者以非詔旨格之。嵩還第，父子對泣。時陸炳掌錦衣，與鸞爭寵，嵩乃結炳共圖鸞。會鸞病死，炳訐鸞陰事，帝追戮之。於是益信任嵩，遣所乘龍舟過海子召嵩，載值西內如故。", "translation": "大將軍仇鸞，起初被曾銑彈劾，想依靠嚴嵩來對抗曾銑，所以和嚴嵩結為義父子。後來仇鸞受到皇帝重用，嚴嵩仍把他當兒子看待，兩人於是漸漸互相厭惡。嚴嵩祕密上奏詆毀仇鸞，皇帝不聽，反而頗採納仇鸞所說嚴嵩父子的過失，稍稍疏遠嚴嵩。嚴嵩該入宮值班，好幾次都沒被召見。嚴嵩看見徐階、李本進入宮中，就跟著一起進去，到了西華門，守門人以沒有皇帝詔令為由攔住他。嚴嵩回到家，和兒子相對哭泣。當時陸炳掌管錦衣衛，和仇鸞爭寵，嚴嵩就結交陸炳一起對付仇鸞。正好仇鸞病死，陸炳揭發仇鸞的祕密罪行，皇帝追究並戮其屍。從此皇帝更加信任嚴嵩，派自己乘坐的龍舟經過海子去召嚴嵩，載他入宮值班，和從前一樣。", "keywords": [{"w": "劾", "m": "彈劾、檢舉官員的罪"}, {"w": "浸", "m": "漸漸"}, {"w": "疏", "m": "上奏（動詞）；疏遠"}, {"w": "內", "m": "宮廷"}, {"w": "格", "m": "阻擋"}, {"w": "第", "m": "住宅"}, {"w": "訐", "m": "揭發別人的隱私或過錯"}, {"w": "陰事", "m": "祕密的事"}, {"w": "戮", "m": "殺；此指戮屍"}], "questions": [{"n": 39, "stem": "根據本文，下列何者最可能是仇鸞與嚴嵩一開始交惡的原因？", "options": {"A": "嚴嵩私下上奏，詆毀仇鸞", "B": "嚴嵩與曾銑結盟，疏遠仇鸞", "C": "仇鸞向皇帝稟告嚴嵩父子的罪行", "D": "仇鸞權位日重，不願嚴嵩仍以子視之"}, "answer": "D", "explain": "文中「已而鸞得帝重，嵩猶視之若子，遂浸相惡」：仇鸞受皇帝重用、地位提高，嚴嵩卻還把他當兒子看，兩人因此漸漸交惡──這是「一開始」的原因，選(D)。(A)(C)「嵩密疏毀鸞」「納鸞所陳嵩父子過」都發生在「遂浸相惡」之後，是交惡後的結果。(B)嚴嵩與曾銑沒有結盟，曾銑是仇鸞的對頭。", "skill": "題目問「一開始」，就要按時間順序找最早的轉折句（已而……遂浸相惡），後面發生的事是結果不是起因。"}, {"n": 40, "stem": "下列文句的解說，何者最恰當？", "options": {"A": "門者以非詔旨格之：守門者將徐階、李本擋下", "B": "嵩還第，父子對泣：嚴嵩與仇鸞兩人盡釋前嫌", "C": "炳訐鸞陰事，帝追戮之：皇帝認為陸炳毀謗死者，憤而殺之", "D": "遣所乘龍舟過海子召嵩：皇帝以高規格召回嚴嵩，以示禮遇"}, "answer": "D", "explain": "皇帝派出自己乘坐的龍舟去接嚴嵩，表示對他極為重視，等於用高規格禮遇召回他，選(D)。(A)被擋下的是沒有詔令卻跟著進去的嚴嵩，徐階、李本是被召入的。(B)「父子對泣」是嚴嵩和他的兒子（嚴世蕃）相對哭泣，不是和仇鸞和好。(C)「帝追戮之」的「之」指仇鸞，皇帝是追究仇鸞的罪而戮其屍，不是殺陸炳。", "skill": "代名詞「之」要回頭找它指的是誰；「父子」要分清楚是真父子還是前文的義父子。"}], "difficulty": "難", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk112-41", "exam": "hk112", "nums": [41, 42], "form": "題組", "img": "img/hk112-41.png", "source": "《列子‧楊朱》", "author": "列禦寇（傳）", "genre": "說理議論", "types": ["文意推論", "句意理解", "主旨寓意"], "passage": "楊朱見梁王，言治天下如運諸掌。梁王曰：「先生有三畝之園而不能耘，而言治天下如運諸掌，何也？」對曰：「君不見牧羊者乎？百羊而群，使五尺童子荷杖隨之，欲東而東，欲西而西。使堯牽一羊，舜荷杖隨之，則不能前矣。且臣聞之：吞舟之魚，不游支流；鴻鵠高飛，不集汙池。何則？其志遠也。黃鐘大呂不可從繁奏之舞。何則？其音疏也。將治大者不治細，成大功者不成小，此之謂矣。」", "translation": "楊朱去見梁王，說治理天下就像在手掌上轉東西一樣容易。梁王說：「先生家裡三畝的園子都除不好草，卻說治理天下像在手掌上轉東西，為什麼？」楊朱回答：「您沒看過牧羊的人嗎？上百隻羊成群，讓一個小孩拿著竹杖跟在後面，想往東就往東，想往西就往西。如果讓堯牽一隻羊、舜拿杖跟在後面，反而走不動了。而且我聽說：能吞下船的大魚，不在小支流裡游；高飛的鴻鵠，不停在汙水池邊。為什麼？因為牠們志向遠大。黃鐘、大呂這類莊重的音樂，不能用來配合節奏繁密的舞蹈。為什麼？因為它的音調舒緩。要治理大事的人不管細瑣小事，要成就大功的人不去做小事，說的就是這個道理。」", "keywords": [{"w": "運諸掌", "m": "在手掌上轉動，比喻非常容易"}, {"w": "耘", "m": "除草"}, {"w": "荷", "m": "扛、拿"}, {"w": "鴻鵠", "m": "天鵝一類的大鳥，比喻志向遠大的人"}, {"w": "集", "m": "鳥停棲"}, {"w": "疏", "m": "稀疏、舒緩"}], "questions": [{"n": 41, "stem": "根據本文，關於梁王與楊朱的敘述，下列何者最恰當？", "options": {"A": "梁王認為治理天下應重視禮樂之道", "B": "梁王質疑楊朱是否具有治理天下的能力", "C": "楊朱貶抑堯、舜，能治天下卻不能牧羊", "D": "楊朱以牧羊為例，說明治天下須從小事做起"}, "answer": "B", "explain": "梁王說「先生有三畝之園而不能耘，而言治天下如運諸掌，何也？」──連小菜園都管不好，怎敢說治天下很容易？這是在質疑楊朱的能力，選(B)。(A)梁王沒有談禮樂。(C)楊朱舉堯、舜牽羊不能前，是說大人物不適合做小事，並非貶低堯舜。(D)楊朱的結論是「將治大者不治細」，與「從小事做起」相反。", "skill": "把梁王的話拆成「事實（園不能耘）＋反問（何也）」，就能看出他的態度是質疑。"}, {"n": 42, "stem": "下列文句，何者最能呼應文中「吞舟之魚，不游支流；鴻鵠高飛，不集汙池」的涵義？", "options": {"A": "狡兔死，良狗烹；高鳥盡，良弓藏", "B": "高飛之鳥，死於美食；深泉之魚，死於芳餌", "C": "騏驥千里，一日而達；駑馬十駕，旬亦至之", "D": "剖三寸之蚌，難得明月之珠；探枳棘之巢，難求鳳凰之雛"}, "answer": "D", "explain": "「吞舟之魚不游支流，鴻鵠不集汙池」意思是：志向遠大、有大才能的人，不會待在狹小低下的地方。(D)小蚌裡找不到明月珠，荊棘叢的小巢裡找不到鳳凰雛，同樣是說大材不在小處，最能呼應。(A)比喻事成之後功臣被拋棄（兔死狗烹）。(B)比喻貪圖利益而喪命。(C)比喻資質差的人只要努力不懈也能達成（駑馬十駕）。", "skill": "先把題目句的比喻翻成一句白話道理（大材不處小地），再把每個選項也翻成道理，比對是否同一個意思。"}], "difficulty": "中", "label": "112年會考", "year": 112, "kind": "會考"}, {"id": "hk113-12", "exam": "hk113", "nums": [12], "form": "單題", "img": "img/hk113-12.png", "source": "張籍〈野老歌〉", "author": "張籍", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "老農家貧在山住，耕種山田三四畝。苗疏稅多不得食，輸入官倉化為土。歲暮鋤犁傍空室，呼兒登山收橡實。西江賈客珠百斛，船中養犬長食肉。", "translation": "老農家裡窮，住在山上，耕種三四畝山田。禾苗稀疏、賦稅又重，自己根本吃不到糧食；繳進官府糧倉的穀子，放到爛成泥土。到了年底，鋤頭犁具靠在空蕩蕩的屋裡，只好叫兒子上山撿橡樹果實充飢。可是西江來的商人擁有上百斛珍珠，連船上養的狗都常常吃肉。", "keywords": [{"w": "苗疏", "m": "禾苗稀疏"}, {"w": "輸", "m": "繳納"}, {"w": "化為土", "m": "（糧食）腐爛成泥土"}, {"w": "傍", "m": "靠著"}, {"w": "橡實", "m": "橡樹的果實，荒年用來充飢"}, {"w": "賈客", "m": "商人"}, {"w": "斛", "m": "容量單位"}], "questions": [{"n": 12, "stem": "「老農家貧在山住，耕種山田三四畝。苗疏稅多不得食，輸入官倉化為土。歲暮鋤犁傍空室，呼兒登山收橡實。西江賈客珠百斛，船中養犬長食肉。」關於這首詩的說明，下列敘述何者最恰當？", "options": {"A": "就形式而言，是一首七言律詩", "B": "就類別而言，是一首山居躬耕的閒適詩", "C": "就內涵而言，描繪農民於繁重稅賦下艱困的生活", "D": "就技巧而言，以農家與商賈對比，凸顯人情的可貴"}, "answer": "C", "explain": "「苗疏稅多不得食，輸入官倉化為土」直接寫出稅賦沉重、農民挨餓，年底只能撿橡實充飢，(C)正確。(A)雖然八句七言，但不講究平仄對仗，屬於樂府古體詩，不是律詩（例如第三、四句並不對仗）。(B)內容寫貧困痛苦，不是悠閒自在的閒適詩。(D)詩末確實用農家和富商對比，但凸顯的是貧富懸殊、社會不公，而不是「人情可貴」。", "skill": "選項分「形式／類別／內涵／技巧」四個角度，就逐一檢查：句數字數是否合律、情調是閒適還是悲苦、對比要凸顯的是什麼。"}], "difficulty": "易", "label": "113年會考", "year": 113, "kind": "會考"}, {"id": "hk113-14", "exam": "hk113", "nums": [14], "form": "單題", "img": "img/hk113-14.png", "source": "聶勝瓊〈鷓鴣天〉（玉慘花愁出鳳城）", "author": "聶勝瓊", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "玉慘花愁出鳳城，蓮花樓下柳青青。尊前一唱〈陽關曲〉，別個人人第五程？　尋好夢，夢難成。有誰知我此時情？枕前淚共階前雨，隔個窗兒滴到明。", "translation": "像玉一般悽慘、像花一般憂愁地送你走出京城，蓮花樓下柳色青青。酒杯前唱一曲送別的〈陽關曲〉，送別心上人後，你已走到第五站了吧？想在夢裡和你相會，夢卻做不成。有誰知道我此刻的心情？枕前的眼淚和臺階前的雨水，隔著一扇窗，一起滴到天亮。", "keywords": [{"w": "鳳城", "m": "京城"}, {"w": "尊", "m": "同「樽」，酒杯"}, {"w": "陽關曲", "m": "送別的歌曲（王維〈送元二使安西〉）"}, {"w": "人人", "m": "對親愛之人的暱稱"}, {"w": "程", "m": "驛站間的路程"}], "questions": [{"n": 14, "stem": "「玉慘花愁出鳳城，蓮花樓下柳青青。尊前一唱〈陽關曲〉，別個人人第五程？尋好夢，夢難成。有誰知我此時情？枕前淚共階前雨，隔個窗兒滴到明。」關於這闋詞的分析，下列敘述何者錯誤？", "options": {"A": "首句情景交融，「慘」、「愁」二字點出別情", "B": "下闋首句點出「我」為了追尋理想而遠離佳人", "C": "末尾二句暗示「我」滿懷離情別緒，一夜未眠", "D": "上闋描寫分別時的情景，下闋描寫別後的思情"}, "answer": "B", "explain": "本題選「錯誤」。下闋首句「尋好夢，夢難成」是說想在夢中和離去的人相見，卻連夢都做不成，表達思念之苦；並不是「我」為了追尋理想而離開佳人（而且離開的是對方，「我」是送別、留下的人），所以(B)錯誤。(A)用「玉慘花愁」寫景，又帶出離別的愁苦，情景交融，正確。(C)淚和雨「滴到明」，表示整夜流淚未眠，正確。(D)上闋寫出城送別、唱陽關曲，下闋寫別後夢難成、徹夜流淚，正確。", "skill": "先判斷詞中「誰走、誰留」；「夢」在詩詞中常是相思相會的媒介，不要望文生義解成「理想」。"}], "difficulty": "中", "label": "113年會考", "year": 113, "kind": "會考"}, {"id": "hk113-17", "exam": "hk113", "nums": [17], "form": "單題", "img": "img/hk113-17.png", "source": "虞集〈尚志齋說〉", "author": "虞集", "genre": "說理議論", "types": ["虛詞句式", "句意理解"], "passage": "夫學者之欲至於聖賢，猶射者之求中夫正鵠也。不以聖賢為準的而學者，是不立正鵠而射者也。", "translation": "求學的人想要達到聖賢的境界，就好比射箭的人想要射中箭靶的中心。不把聖賢當作目標而求學的人，就像是不立箭靶就射箭的人一樣。", "keywords": [{"w": "夫", "m": "句首發語詞"}, {"w": "猶", "m": "好像、如同"}, {"w": "夫（中夫正鵠）", "m": "那個，指示代詞"}, {"w": "正鵠", "m": "箭靶的中心，比喻目標"}, {"w": "準的", "m": "標準、目標"}, {"w": "是", "m": "這、這就是"}], "questions": [{"n": 17, "stem": "下列選項中的文字，旨在強調求學必須先立定志向。依據文意判斷，何者斷句最恰當？", "options": {"A": "夫學者之欲至於聖賢猶射者，之求中夫正鵠也。不以聖賢為準的而學者是，不立正鵠而射者也。", "B": "夫學者之欲至於聖賢，猶射者之求中夫正鵠也。不以聖賢為準的而學者，是不立正鵠而射者也。", "C": "夫學者之欲，至於聖賢猶射者之求中。夫正鵠也，不以聖賢為準的，而學者是不立正鵠而射者也。", "D": "夫學者之欲至，於聖賢猶射者之求。中夫正鵠也不以聖賢為準，的而學者是不，立正鵠而射者也。"}, "answer": "B", "explain": "文章是用射箭比喻求學：前句「學者之欲至於聖賢」對「射者之求中夫正鵠」，中間用「猶」（好像）連接；後句「不以聖賢為準的而學者」是主語，「是不立正鵠而射者也」是判斷，說這種人就像不立靶就射箭。(B)兩組結構完整對應，最恰當。(A)把「之求中」切開，「射者，之求中」不成句；「而學者是，」也把判斷詞「是」切錯邊。(C)「學者之欲」語意不完整，「夫正鵠也」不成句。(D)「準的」被拆開，「是不，立正鵠」更不通。", "skill": "斷句先找比喻的兩邊（A猶B）和判斷句（主語＋是＋……也），讓「學者之欲至於聖賢」與「射者之求中夫正鵠」、「不以聖賢為準的而學者」與「不立正鵠而射者」兩兩對稱。"}], "difficulty": "中", "label": "113年會考", "year": 113, "kind": "會考"}, {"id": "hk113-18", "exam": "hk113", "nums": [18], "form": "單題", "img": "img/hk113-18.png", "source": "干寶《搜神記‧卷十三》（亦見《後漢書‧蔡邕傳》）", "author": "干寶", "genre": "筆記小品", "types": ["文意推論"], "passage": "漢靈帝時，陳留蔡邕，以數上書陳奏，忤上旨意，又內寵惡之，慮不免，乃亡命江海，遠跡吳郡。吳有燒桐以爨者，邕聞火烈聲，曰：「此良材也。」因請之，削之以琴，果有美音。而其尾焦，因名「焦尾琴」。", "translation": "漢靈帝時，陳留人蔡邕因為多次上書陳述意見，違逆了皇帝的心意，又被皇帝寵信的宦官所厭惡，擔心自己難逃災禍，就逃亡到江海一帶，遠遠躲到吳郡。吳地有人燒桐木來煮飯，蔡邕聽到木頭燃燒時猛烈的爆裂聲，說：「這是好木材啊。」於是向那人要來，削製成琴，果然音色優美。但琴的尾端被燒焦了，所以取名為「焦尾琴」。", "keywords": [{"w": "數", "m": "屢次"}, {"w": "忤", "m": "違逆"}, {"w": "內寵", "m": "皇帝寵信的人（宦官）"}, {"w": "亡命", "m": "逃亡"}, {"w": "爨", "m": "音ㄘㄨㄢˋ，生火煮飯"}, {"w": "請", "m": "請求、要來"}], "questions": [{"n": 18, "stem": "根據這則故事，下列敘述何者最恰當？", "options": {"A": "焦尾琴因蔡邕識材而製成", "B": "吳人向來以燒桐製琴聞名", "C": "焦尾琴製成後經火烤而音色優美", "D": "蔡邕因忤逆上意而遭流放至吳郡"}, "answer": "A", "explain": "蔡邕聽到燒桐的聲音就判斷「此良材也」，把它要來做成好琴，所以焦尾琴是因為蔡邕能辨識好木材才製成的，選(A)。(B)吳人是拿桐木當柴燒，不是用來做琴。(C)是先被火燒焦，後來才製成琴，順序相反，而且音色好是因為木材好。(D)蔡邕是自己擔心遭禍而「亡命」逃走，不是被朝廷流放。", "skill": "注意事件的先後順序（先燒→後製琴），以及「亡命」（自己逃走）和「流放」（被處罰）的差別。"}], "difficulty": "易", "label": "113年會考", "year": 113, "kind": "會考"}, {"id": "hk113-19", "exam": "hk113", "nums": [19], "form": "單題", "img": "img/hk113-19.png", "source": "呂坤《呻吟語‧修身》", "author": "呂坤", "genre": "經典語錄", "types": ["主旨寓意", "句意理解"], "passage": "蝸以涎見覓，蟬以聲見黏，螢以光見獲。故愛身者，不貴赫赫之名。", "translation": "蝸牛因為留下黏液的痕跡而被人找到，蟬因為鳴叫聲而被人黏捕，螢火蟲因為發光而被人捉到。所以愛惜自身的人，不看重顯赫的名聲。", "keywords": [{"w": "涎", "m": "黏液"}, {"w": "見", "m": "被（表被動）"}, {"w": "覓", "m": "尋找"}, {"w": "貴", "m": "重視（動詞）"}, {"w": "赫赫", "m": "顯赫盛大的樣子"}], "questions": [{"n": 19, "stem": "「蝸以涎見覓，蟬以聲見黏，螢以光見獲。故愛身者，不貴赫赫之名。」這句話的涵義與下列何者最接近？", "options": {"A": "人過留名，雁過留聲", "B": "所榮者善行，所恥者惡名", "C": "名不可簡而成，譽不可巧而立", "D": "樹大招風風損樹，人為名高傷喪身"}, "answer": "D", "explain": "蝸牛、蟬、螢火蟲都因為自身的明顯特點（黏液、聲音、光）引人注意而遭殃，由此推論：名聲太顯赫容易招來禍害，愛惜自己就別追求盛名。(D)「樹大招風，人為名高傷喪身」同樣是說名高招禍，最接近。(A)鼓勵人要留下好名聲，相反。(B)講以善行為榮、惡名為恥，與「名高招禍」無關。(C)說名譽要靠實在努力得來，不能取巧，重點不同。", "skill": "「見＋動詞」常表被動（見覓＝被找到）；先從三個例子歸納共通點（特點顯眼→招禍），再找同義的俗語。"}], "difficulty": "中", "label": "113年會考", "year": 113, "kind": "會考"}, {"id": "hk113-21", "exam": "hk113", "nums": [21], "form": "單題", "img": "img/hk113-21.png", "source": "鞠武〈報燕太子丹書〉（《燕丹子》）", "author": "鞠武", "genre": "書信序跋", "types": ["寫作手法", "文意推論"], "passage": "臣聞快於意者虧於行，甘於心者傷於性。今太子欲滅悁悁之恥，除久久之恨，此實臣所當糜軀碎首而不避也。私以為智者不冀僥倖以要功，明者不苟從志以順心。事必成，然後舉；身必安，而後行。故發無失舉之尤，動無蹉跌之愧也。太子貴匹夫之勇，信一劍之任，而欲望功，臣以為疏。", "translation": "我聽說，只圖心裡痛快的人，行事會有虧損；只求心裡舒服的人，會傷害本性。現在太子想洗刷令人憤怒的恥辱、消除長久的怨恨，這本來是我應該粉身碎骨也不逃避的事。但我私下認為，聰明的人不會寄望僥倖來求取功業，明智的人不會隨便順從自己的意願來討自己開心。事情一定能成功，然後才行動；自身一定能安全，然後才去做。所以行動時不會有舉措失當的過錯，做事也不會有失誤的慚愧。太子看重一個人的匹夫之勇，信任一把劍（刺客）能完成任務，卻想靠此成功，我認為這太疏忽了。", "keywords": [{"w": "虧", "m": "損害"}, {"w": "悁悁", "m": "憤怒"}, {"w": "糜軀碎首", "m": "粉身碎骨"}, {"w": "冀", "m": "希望"}, {"w": "要", "m": "求取"}, {"w": "苟", "m": "隨便"}, {"w": "尤", "m": "過錯"}, {"w": "蹉跌", "m": "失誤"}, {"w": "疏", "m": "疏忽、不周密"}], "questions": [{"n": 21, "stem": "鞠武〈報燕太子丹書〉曰：「臣聞快於意者虧於行，甘於心者傷於性。今太子欲滅悁悁之恥，除久久之恨，此實臣所當糜軀碎首而不避也。私以為智者不冀僥倖以要功，明者不苟從志以順心。事必成，然後舉；身必安，而後行。故發無失舉之尤，動無蹉跌之愧也。太子貴匹夫之勇，信一劍之任，而欲望功，臣以為疏。」關於這段文字的寫作分析，下列敘述何者最恰當？", "options": {"A": "分析個中利害關係，鼓勵太子須建功立業", "B": "採取先抑後揚筆法，肯定太子能獨當一面", "C": "以工整句式加強文氣，勸諫太子應謀定而後動", "D": "列舉前人失敗的事例，提醒太子不宜心存僥倖"}, "answer": "C", "explain": "文中大量使用對稱工整的句子，如「快於意者虧於行，甘於心者傷於性」「事必成，然後舉；身必安，而後行」，增強說服的氣勢；主旨是勸太子不要靠僥倖與匹夫之勇，要確定能成功、能安全才行動，也就是「謀定而後動」，選(C)。(A)鞠武是勸太子別輕舉妄動，不是鼓勵建功。(B)結尾「臣以為疏」是批評，不是肯定。(D)文中沒有舉前人失敗的例子。", "skill": "寫作分析題要同時檢查「手法」和「目的」兩半：找出對偶句證明句式工整，再從結論句「臣以為疏」判斷作者的態度。"}], "difficulty": "難", "label": "113年會考", "year": 113, "kind": "會考"}, {"id": "hk113-22", "exam": "hk113", "nums": [22], "form": "單題", "img": "img/hk113-22.png", "source": "蒲松齡《聊齋誌異‧張不量》", "author": "蒲松齡", "genre": "筆記小品", "types": ["文意推論", "主旨寓意"], "passage": "賈人某，至直隸界，忽大雨雹，伏禾中。聞空中云：「此張不量田，勿傷其稼。」天霽，他田偃壞，張田獨無恙。蓋張氏積粟甚富，每春間貧民皆就貸焉。償時多寡不較，悉納之，未嘗執概取盈，故鄉人名之「不量」。", "translation": "有個商人到了直隸境內，忽然下起大冰雹，他趴在田裡的莊稼中躲避。聽見空中有聲音說：「這是張不量的田，不要傷害他的莊稼。」天晴後，別人的田地莊稼都倒伏毀壞，只有張家的田完好無損。原來張家積存了很多糧食，每年春天貧窮的百姓都向他借糧。還糧的時候他不計較多少，全部收下，從來不拿量米的刮板把斗刮平來量足，所以鄉人叫他「不量」。", "keywords": [{"w": "賈人", "m": "商人"}, {"w": "霽", "m": "雨停天晴"}, {"w": "偃", "m": "倒伏"}, {"w": "恙", "m": "損害"}, {"w": "就貸", "m": "前往借貸"}, {"w": "概", "m": "量米時刮平斗斛的木板"}, {"w": "取盈", "m": "取足"}], "questions": [{"n": 22, "stem": "根據本文，「張田獨無恙」的原因最可能是下列何者？", "options": {"A": "張氏行善積德，得到護佑", "B": "貧民虔誠祈願，感動上天", "C": "張氏田產甚多無法丈量，看不出損失", "D": "賈人福澤深厚，連帶使張田倖免於難"}, "answer": "A", "explain": "空中聲音說「此張不量田，勿傷其稼」，後文用「蓋」解釋原因：張氏借糧給貧民、還糧時不計較多少，是行善積德，所以上天保佑他的田，選(A)。(B)文中沒有貧民祈願。(C)「不量」是不計較還糧多少，不是田大到無法丈量。(D)商人只是旁觀者，與張田無恙無關。", "skill": "文言中「蓋……」常用來說明原因，找到它就找到答案；人名外號「不量」要回文中找由來，別照字面猜。"}], "difficulty": "易", "label": "113年會考", "year": 113, "kind": "會考"}, {"id": "hk113-24", "exam": "hk113", "nums": [24], "form": "單題", "img": "img/hk113-24.png", "source": "《尸子‧勸學》", "author": "尸佼", "genre": "說理議論", "types": ["寫作手法", "主旨寓意"], "passage": "夫繭，捨而不治，則腐蠹而棄。使女工繅之，以為美錦，國君服而朝之。身者，繭也，捨而不治，則智行腐蠹。使賢者教之，以為世士，則天下諸侯莫敢不敬。", "translation": "蠶繭如果放著不處理，就會腐爛生蟲而被丟棄。如果讓女工煮繭抽絲，織成美麗的錦緞，國君就會穿著它上朝。人的身心就像蠶繭，放著不加修治，智慧和品行就會腐敗。如果讓賢能的人教導他，使他成為當世傑出的人才，那麼天下的諸侯沒有不敬重他的。", "keywords": [{"w": "捨", "m": "放置不管"}, {"w": "治", "m": "整治、處理"}, {"w": "蠹", "m": "蛀蟲；被蟲蛀壞"}, {"w": "繅", "m": "音ㄙㄠ，煮繭抽絲"}, {"w": "朝", "m": "上朝"}, {"w": "世士", "m": "當世傑出之士"}], "questions": [{"n": 24, "stem": "「夫繭，捨而不治，則腐蠹而棄。使女工繅之，以為美錦，國君服而朝之。身者，繭也，捨而不治，則智行腐蠹。使賢者教之，以為世士，則天下諸侯莫敢不敬。」關於本文的分析，下列敘述何者最恰當？", "options": {"A": "以繭為喻，說明教化對修身的重要", "B": "以身著美錦，暗指上位者奢靡誤國", "C": "以女工與賢者對照，強調環境的影響", "D": "以腐蠹的蠶繭，嘲諷國政的敗壞衰頹"}, "answer": "A", "explain": "「身者，繭也」明白點出以繭比喻人：繭要經女工處理才成美錦，人要經賢者教導才成世士，強調教化對修身的重要，選(A)。(B)國君穿美錦只是說明繭經處理後的價值，沒有批評奢靡。(C)女工與賢者是「類比」（同樣扮演加工者），不是對照，也沒談環境。(D)「腐蠹」是說人不受教的後果，沒有嘲諷國政。", "skill": "找出「A者，B也」的比喻句，畫出兩邊的對應：繭↔身、女工↔賢者、美錦↔世士，主旨就清楚了。"}], "difficulty": "難", "label": "113年會考", "year": 113, "kind": "會考"}, {"id": "hk113-38", "exam": "hk113", "nums": [38, 39], "form": "題組", "img": "img/hk113-38.png", "source": "甲：呂祖謙《東萊集》；乙：《左宗棠全集》", "author": "呂祖謙、左宗棠", "genre": "說理議論", "types": ["比較閱讀", "句意理解", "主旨寓意"], "passage": "【甲】人讀聖人書二三十年，一旦遇事，便與里巷人無異，或有一聽老成語，便能終身服膺。豈老成之言過於六經哉？只緣讀書不作有用看故也。大抵看史見治則以為治，見亂則以為亂，見一事則止知一事，何取？觀史如身在其中，見事之利害、時之禍患，必掩卷自思，使我遇此等事，當作何處之──如此觀史，學問亦可以進，智識亦可以高，方為有益。（改寫自呂祖謙《東萊集》）\n【乙】讀書時，須細看古人處一事，接一物，是如何思量？如何氣象？及自己處事接物時，又細心將古人比擬。設若古人當此，其措置之法，當是如何？我自己任性為之，又當如何？然後自己過錯始見，古人道理始出。斷不可以古人之書，與自己處事接物為兩事。（《左宗棠全集》）", "translation": "【甲】有人讀聖賢書二三十年，一旦遇到事情，表現卻和街巷裡的普通人沒兩樣；也有人只聽了一次老成之人的話，就能一輩子牢記奉行。難道老成人的話比六經還高明嗎？只是因為讀書時沒把書當作能實際運用的東西來看罷了。一般人讀史書，看到治世就只知道是治世，看到亂世就只知道是亂世，看到一件事就只知道那一件事，這有什麼用呢？讀史應該像自己身在其中，看到事情的利害、時局的禍患，一定要闔上書自己思考：假如我遇到這種事，應該怎麼處理？──這樣讀史，學問才會進步，見識才會提高，才算有益。\n【乙】讀書時，要仔細看古人處理一件事、應對一件物，是怎樣思考的？是什麼樣的氣度？等到自己處事待物時，又要細心拿古人來比照。假如古人遇到這情況，他的處置方法會是怎樣？我自己憑著性子去做，又會怎樣？這樣之後，自己的過錯才看得出來，古人的道理才顯現出來。千萬不可把古人的書和自己的處事待物當成兩回事。", "keywords": [{"w": "里巷人", "m": "街坊平民"}, {"w": "老成", "m": "年高有經驗的人"}, {"w": "服膺", "m": "牢記在心、奉行"}, {"w": "只緣", "m": "只因為"}, {"w": "止", "m": "只"}, {"w": "氣象", "m": "氣度、風範"}, {"w": "措置", "m": "處置、安排"}, {"w": "任性", "m": "順著自己的性情"}], "questions": [{"n": 38, "stem": "下列關於甲、乙二文文句的說明，何者最恰當？", "options": {"A": "「一旦遇事，便與里巷人無異」是因書讀得不夠多", "B": "「見一事則止知一事」意謂對事情的理解不夠全面", "C": "「如何氣象」其意是思索今人當前所處的環境氛圍", "D": "「我自己任性為之」意謂今人比古人更加不受拘束"}, "answer": "B", "explain": "「見一事則止知一事」是說看到一件事就只知道那一件事，不會推想延伸、舉一反三，也就是理解不夠全面，選(B)。(A)甲文說已讀二三十年書，原因是「讀書不作有用看」，不是讀得不夠多。(C)「如何氣象」是看古人處事時的氣度風範，不是今人的環境氛圍。(D)「任性為之」是憑自己的性情去做，用來和古人的做法比較，不是說今人比古人自由。", "skill": "解釋文句要回到上下文：前面有「讀聖人書二三十年」就排除「讀得少」；「如何氣象」的主語是前面的「古人」。"}, {"n": 39, "stem": "關於甲、乙二文的說明與比較，下列何者最恰當？", "options": {"A": "甲文認為耳熟能詳的淺近道理，更勝於聖賢之言", "B": "乙文以古人處事的標準，評斷自身舉措是否合宜", "C": "二者都認為讀書應活用，不應拘泥於古人的看法", "D": "二者都覺得古人讀書講究方法，比今人更有效率"}, "answer": "B", "explain": "乙文說處事時要「細心將古人比擬」，想想古人會怎麼做、自己會怎麼做，然後「自己過錯始見」，也就是用古人處事的標準來檢視自己是否合宜，選(B)。(A)甲文反問「豈老成之言過於六經哉？」意思是並非老成之言勝過六經，問題出在讀法。(C)兩文都主張讀書要能應用沒錯，但乙文要人以古人為借鏡，並沒有說「不應拘泥於古人的看法」。(D)兩文談的是讀書應如何與實際結合，沒有比較古今讀書效率。", "skill": "比較閱讀要先各自寫出一句主旨（甲：讀史要設身處地；乙：讀書要以古人比照自己），再逐一檢查選項是否「兩篇都」成立。"}], "difficulty": "難", "label": "113年會考", "year": 113, "kind": "會考"}, {"id": "hk113-40", "exam": "hk113", "nums": [40, 41, 42], "form": "題組", "img": "img/hk113-40.png", "source": "劉向《列女傳‧辯通傳‧楚江乙母》", "author": "劉向", "genre": "史傳人物", "types": ["字詞解釋", "文意推論", "人物情感"], "passage": "楚人江乙為郢大夫。有入王宮中盜者，令尹以罪乙，請於王而黜之。其母往言於王曰：「妾夜亡布八匹，令尹盜之。」王謂母曰：「令尹信盜之，寡人不為其富貴而不行法焉。若不盜而誣之，楚國有常法。」母曰：「令尹不身盜之也，乃使人盜之。」王曰：「其使人盜奈何？」對曰：「昔孫叔敖之為令尹也，道不拾遺，門不閉關，而盜賊自息。今令尹之治也，耳目不明，盜賊公行，是故使盜得盜妾之布，是與使人盜何以異也？」王曰：「令尹在上，寇盜在下，令尹不知有何罪焉？」\n母曰：「昔日妾之子為郢大夫，有盜王宮中之物者，妾子坐而黜，妾子亦豈知之哉？然終坐之。令尹獨何人，而不以是為過也？昔者周武王有言曰：『百姓有過，在予一人。』上不明則下不治，相不賢則國不寧。王其察之。」", "translation": "楚國人江乙擔任郢都的大夫。有人潛入王宮偷東西，令尹（宰相）因此怪罪江乙，向楚王請求罷免了他。江乙的母親去對楚王說：「我晚上丟了八匹布，是令尹偷的。」楚王對她說：「令尹如果真的偷了，我不會因為他富貴就不依法處置。如果他沒偷而你誣告他，楚國也有固定的法律。」江母說：「令尹不是親自偷的，是派人去偷的。」楚王說：「他派人偷是怎麼回事？」江母回答：「從前孫叔敖當令尹時，路上沒人撿拾別人遺失的東西，家門不必上閂，盜賊自然消失。現在令尹治理國家，耳目不靈、看不清楚，盜賊公然橫行，所以才讓小偷偷走我的布，這和派人去偷有什麼不同呢？」楚王說：「令尹在上位，盜賊在下面，令尹不知道，有什麼罪呢？」江母說：「從前我的兒子當郢大夫，有人偷了王宮的東西，我兒子因此獲罪被罷官，我兒子難道知道那件事嗎？但最後還是被治罪。令尹又是什麼特別的人，卻不把這當成自己的過錯呢？從前周武王說過：『百姓有過錯，責任在我一個人。』上位者不明察，下面就治理不好；宰相不賢能，國家就不安寧。請大王明察這件事。」", "keywords": [{"w": "郢", "m": "楚國國都"}, {"w": "令尹", "m": "楚國官名，相當於宰相"}, {"w": "罪", "m": "怪罪、歸罪（動詞）"}, {"w": "黜", "m": "罷免"}, {"w": "亡", "m": "遺失"}, {"w": "信", "m": "確實、真的"}, {"w": "身", "m": "親自"}, {"w": "坐", "m": "因……而獲罪"}, {"w": "其（王其察之）", "m": "表示請求、希望的語氣"}], "questions": [{"n": 40, "stem": "根據本文，下列文句「」中的字義，何者說明最恰當？", "options": {"A": "妾夜「亡」布八匹：損壞", "B": "令尹「信」盜之：隨意", "C": "妾子「坐」而黜：受罰", "D": "王「其」察之：難道"}, "answer": "C", "explain": "「妾子坐而黜」是說我兒子因為這件事被治罪而遭罷官，「坐」是因……獲罪、受罰，(C)正確。(A)「亡」是遺失，布被偷走了，不是損壞。(B)「信」是確實、真的，「令尹信盜之」＝令尹真的偷了。(D)「王其察之」的「其」表示請求、希望，意為「希望大王明察」，不是反問的「難道」。", "skill": "把字義代回原句讀讀看，並配合文意：布是被偷（遺失）；楚王是在假設「如果真的偷了」；句末「之」配合請求語氣。"}, {"n": 41, "stem": "根據本文，下列關於令尹與楚王的敘述何者最恰當？", "options": {"A": "令尹打算偷盜布匹再將罪責嫁禍給他人", "B": "令尹主張楚國盜賊橫行是須正視的問題", "C": "楚王覺得宮中之物被盜應是令尹的責任", "D": "楚王認為不論身分地位都應該遵守法律"}, "answer": "D", "explain": "楚王說「令尹信盜之，寡人不為其富貴而不行法焉」──令尹若真偷了，不會因為他富貴就不依法辦理，表示不論身分都要守法，選(D)。(A)令尹並沒有真的偷布，江母是說治安不好等於「使人盜」。(B)主張盜賊橫行是問題的是江母，不是令尹。(C)楚王反而說「令尹不知有何罪焉」，認為令尹沒有責任。", "skill": "人物觀點題要分清楚「誰說的」：把每句話標上說話者（王／母），再對照選項的主語。"}, {"n": 42, "stem": "根據本文，江母見楚王的目的最可能是下列何者？", "options": {"A": "想要替兒子江乙頂罪", "B": "表達江乙被懲處的不公", "C": "向楚王告發郢大夫的罪行", "D": "建議楚王再用孫叔敖為令尹"}, "answer": "B", "explain": "江母先用「布被偷」引出治安責任在令尹，最後點明：「妾子坐而黜，妾子亦豈知之哉？然終坐之。令尹獨何人，而不以是為過也？」──兒子不知情卻被罷官，令尹同樣不知情卻不受罰，標準不一，可見她是要為江乙被懲處抱不平，選(B)。(A)她沒有要替兒子承擔罪責。(C)郢大夫就是她兒子江乙，她不會告發。(D)提孫叔敖只是舉例說明好令尹的治績，不是建議再用他（孫叔敖是過去的人）。", "skill": "說客式文章先繞圈子再點題，要看最後的真正訴求句（令尹獨何人，而不以是為過也）來判斷目的。"}], "difficulty": "難", "label": "113年會考", "year": 113, "kind": "會考"}, {"id": "hk114-8", "exam": "hk114", "nums": [8], "form": "單題", "img": "img/hk114-8.png", "source": "貫雲石〈小梁州‧秋〉", "author": "貫雲石", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "芙蓉映水菊花黃，滿目秋光。枯荷葉底鷺鷥藏。金風盪，飄動桂枝香。雷峰塔畔登高望，見錢塘一派長江。湖水清，江潮漾。天邊斜月，新雁兩三行。", "translation": "荷花倒映水中，菊花一片金黃，滿眼都是秋天的風光。枯黃的荷葉底下藏著鷺鷥。秋風吹蕩，飄來桂花的香氣。在雷峰塔旁登高遠望，看見錢塘江一道長長的江水。西湖水清澈，江潮蕩漾。天邊斜掛著月亮，剛南飛的大雁排成兩三行。", "keywords": [{"w": "芙蓉", "m": "荷花"}, {"w": "金風", "m": "秋風（五行中秋屬金）"}, {"w": "一派", "m": "一道（水流）"}, {"w": "漾", "m": "水波蕩動"}, {"w": "新雁", "m": "初秋南飛的大雁"}], "questions": [{"n": 8, "stem": "貫雲石〈小梁州〉秋：「芙蓉映水菊花黃，滿目秋光。枯荷葉底鷺鷥藏。金風盪，飄動桂枝香。雷峰塔畔登高望，見錢塘一派長江。湖水清，江潮漾。天邊斜月，新雁兩三行。」關於這首曲的分析，下列何者最恰當？", "options": {"A": "題目為〈小梁州〉，是散曲中的小令", "B": "在曲作的中間換韻，不是一韻到底", "C": "以「菊花」、「金風」、「桂枝」呼應「秋」", "D": "以「斜月」、「新雁」象徵世間繁華轉眼成空"}, "answer": "C", "explain": "菊花、桂花是秋天開的花，「金風」指秋風，都是秋天的代表景物，用來呼應題目「秋」，(C)正確。(A)〈小梁州〉是曲牌名（規定曲調格式），真正的題目是「秋」。(B)句尾「黃、光、藏、盪、香、望、江、漾、行」都押同一個韻（ㄤ），一韻到底；散曲本來就多一韻到底。(D)斜月、新雁是秋夜景色，全曲寫秋光明麗，沒有繁華成空的感慨。", "skill": "散曲「曲牌名＋題目」要分開：〈小梁州〉是曲調，「秋」才是題目；判斷押韻就把句尾字唸一遍。"}], "difficulty": "中", "label": "114年會考", "year": 114, "kind": "會考"}, {"id": "hk114-10", "exam": "hk114", "nums": [10], "form": "單題", "img": "img/hk114-10.png", "source": "宋應星《天工開物‧甘嗜‧蜂蜜》", "author": "宋應星", "genre": "筆記小品", "types": ["文意推論"], "passage": "蜂造之蜜出山崖、土穴者十居其八，而人家招蜂造釀而割取者，十居其二也。北方乾燥，土穴所釀多出於此。南方卑溼，故有崖蜜而無穴蜜。西北半天下，蓋與蔗漿分勝云。", "translation": "蜜蜂釀造的蜂蜜，出自山崖、土洞的占了十分之八，而人家招引蜜蜂來釀蜜再割取的，占十分之二。北方乾燥，土洞裡釀的蜜大多出產在這裡。南方地勢低又潮溼，所以只有崖蜜而沒有穴蜜。西北這半個天下（以蜂蜜為甜味來源），大概和（東南的）甘蔗糖漿各占優勢吧。", "keywords": [{"w": "十居其八", "m": "占十分之八"}, {"w": "割取", "m": "割下蜂巢取蜜"}, {"w": "卑溼", "m": "地勢低窪潮溼"}, {"w": "蓋", "m": "大概"}, {"w": "分勝", "m": "各占優勢、平分秋色"}], "questions": [{"n": 10, "stem": "「蜂造之蜜出山崖、土穴者十居其八，而人家招蜂造釀而割取者，十居其二也。北方乾燥，土穴所釀多出於此。南方卑溼，故有崖蜜而無穴蜜。西北半天下，蓋與蔗漿分勝云。」根據本文，下列推論何者最恰當？", "options": {"A": "穴蜜多產於乾燥之處", "B": "崖蜜多為人工養育而來", "C": "卑溼之地沒有天然的蜂造之蜜", "D": "西北蜂蜜產量是東南蔗漿的一半"}, "answer": "A", "explain": "「北方乾燥，土穴所釀多出於此」，土穴的蜜（穴蜜）多出產在乾燥的北方；南方潮溼則「無穴蜜」，可見穴蜜多產於乾燥處，選(A)。(B)崖蜜是野生的（出山崖），人工招蜂割取的只占十分之二。(C)南方卑溼仍「有崖蜜」，是天然的蜂蜜。(D)「西北半天下，與蔗漿分勝」是說蜂蜜和蔗漿在甜味來源上各擅勝場，不是產量一半。", "skill": "把文中資訊整理成對照表（北方乾燥→穴蜜多；南方卑溼→只有崖蜜；野生8：人工2），再逐一核對選項。"}], "difficulty": "中", "label": "114年會考", "year": 114, "kind": "會考"}, {"id": "hk114-17", "exam": "hk114", "nums": [17], "form": "單題", "img": "img/hk114-17.png", "source": "祖可〈小重山〉", "author": "祖可", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "誰向江頭遺恨濃？碧波流不斷，楚山重。柳煙和雨隔疏鐘。黃昏後，羅幕更朦朧。　桃李小園空。阿誰猶笑語，拾殘紅。珠簾捲盡夜來風。人不見，春在綠蕪中。", "translation": "是誰在江邊留下這麼濃的遺憾？就像碧綠的江水流個不停，楚地的山一重又一重。柳色如煙，混著雨，隔斷了遠處稀疏的鐘聲。黃昏之後，羅帳更加朦朧。小園裡桃花李花都已落盡。是誰還在說說笑笑，撿拾落花？珠簾全被昨夜的風捲起。人已不見，春天只留在一片綠草叢中。", "keywords": [{"w": "遺恨", "m": "留下的遺憾"}, {"w": "疏鐘", "m": "稀疏的鐘聲"}, {"w": "羅幕", "m": "絲織的帷幕"}, {"w": "阿誰", "m": "何人"}, {"w": "殘紅", "m": "落花"}, {"w": "綠蕪", "m": "叢生的綠草"}], "questions": [{"n": 17, "stem": "祖可〈小重山〉：「誰向江頭遺恨濃？碧波流不斷，楚山重。柳煙和雨隔疏鐘。黃昏後，羅幕更朦朧。桃李小園空。阿誰猶笑語，拾殘紅。珠簾捲盡夜來風。人不見，春在綠蕪中。」關於這闋詞的分析，下列何者最恰當？", "options": {"A": "上片押平聲韻，下片轉押仄聲韻", "B": "上片寫景抒情，下片敘事兼論理", "C": "「碧波流不斷」將「遺恨濃」具體化", "D": "藉由「綠蕪」來反襯「桃李」的豔冶"}, "answer": "C", "explain": "「遺恨濃」是抽象的情感，作者用流個不停的碧綠江水來表現遺憾綿延不斷，把抽象情感化為具體景物，(C)正確。(A)全詞「濃、重、鐘、朧、空、紅、風、中」都押同一個平聲韻（ㄨㄥ），沒有轉韻。(B)下片寫落花、拾殘紅、人不見，仍是寫景抒情，沒有說理。(D)「桃李小園空」表示桃李已謝，「春在綠蕪中」是說春意只剩綠草，並非用綠蕪反襯桃李的豔麗。", "skill": "看到抽象情緒（恨、愁）後面緊跟具體景物，就是「以景具化情」；押韻題把各句末字逐一唸出來。"}], "difficulty": "中", "label": "114年會考", "year": 114, "kind": "會考"}, {"id": "hk114-18", "exam": "hk114", "nums": [18], "form": "單題", "img": "img/hk114-18.png", "source": "皎然〈尋陸鴻漸不遇〉", "author": "皎然", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "移家雖帶郭，野徑入桑麻。近種籬邊菊，秋來未著花。扣門無犬吠，欲去問西家。報道山中去，歸來每日斜。", "translation": "你搬了家，雖然靠近城郭，但要走一條穿過桑麻田的鄉間小路才到。新近在籬笆邊種了菊花，秋天到了還沒開花。我敲門，連狗叫聲都沒有，正要離開，便去問西邊的鄰居。鄰居回答說：他到山裡去了，常常要到太陽西斜才回來。", "keywords": [{"w": "帶郭", "m": "靠近城郭"}, {"w": "野徑", "m": "鄉間小路"}, {"w": "著花", "m": "開花"}, {"w": "扣", "m": "敲"}, {"w": "報道", "m": "回答說"}, {"w": "每", "m": "常常"}], "questions": [{"n": 18, "stem": "皎然〈尋陸鴻漸不遇〉：「移家雖帶郭，野徑入桑麻。近種籬邊菊，秋來未著花。扣門無犬吠，欲去問西家。報道山中去，歸來每日斜。」根據本詩，作者此次訪友之行曾看見下列何者？", "options": {"A": "荒蕪的農地", "B": "盛開的菊花", "C": "歸來的鴻漸", "D": "鴻漸的鄰居"}, "answer": "D", "explain": "「欲去問西家。報道山中去」──作者去問西邊鄰居，鄰居回答陸鴻漸上山去了，可見作者見到了鴻漸的鄰居，選(D)。(A)小路穿過桑麻田，是有人耕種的田地，並不荒蕪。(B)「秋來未著花」，菊花還沒開。(C)題目是「不遇」，沒見到陸鴻漸；「歸來每日斜」是鄰居說他平常的作息。", "skill": "題目中的「不遇」就是重要線索；判斷「看見什麼」要分清楚實際所見和別人轉述的話。"}], "difficulty": "易", "label": "114年會考", "year": 114, "kind": "會考"}, {"id": "hk114-20", "exam": "hk114", "nums": [20], "form": "單題", "img": "img/hk114-20.png", "source": "《明史‧劉基傳》", "author": "張廷玉等", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "太祖以事責丞相李善長，劉基言：「善長勛舊，能調和諸將。」太祖曰：「是數欲害汝，汝竟為之言耶？吾將相汝矣。」基頓首曰：「是如易柱，須得大木。若束小木為之，且立覆。」", "translation": "明太祖因為某件事責備丞相李善長，劉基說：「李善長是有功勞的老臣，能協調各個將領。」太祖說：「他好幾次想害你，你竟然還替他說話？我要讓你當丞相了。」劉基叩頭說：「（換丞相）就像更換房屋的柱子，必須用大木頭。如果把小木頭綁在一起來充當，房子馬上就會倒塌。」", "keywords": [{"w": "責", "m": "責備"}, {"w": "勛舊", "m": "有功勳的老臣"}, {"w": "是", "m": "此人，指李善長"}, {"w": "數", "m": "屢次"}, {"w": "相", "m": "任命為丞相（動詞）"}, {"w": "頓首", "m": "叩頭"}, {"w": "且", "m": "將要"}, {"w": "覆", "m": "倒塌"}], "questions": [{"n": 20, "stem": "太祖以事責丞相李善長，劉基言：「善長勛舊，能調和諸將。」太祖曰：「是數欲害汝，汝竟為之言耶？吾將相汝矣。」基頓首曰：「是如易柱，須得大木。若束小木為之，且立覆。」關於文中人物的敘述，下列何者最恰當？", "options": {"A": "太祖因多次陷害劉基而心存愧疚", "B": "太祖想以李善長替代劉基為丞相", "C": "劉基認為李善長調和諸將就像束小木", "D": "劉基認為李善長比自己適合擔任丞相"}, "answer": "D", "explain": "劉基用「易柱須得大木，束小木為之且立覆」比喻：丞相是國家的柱子，要由李善長這樣的「大木」擔任，自己只是「小木」，硬撐會讓國家傾覆。所以他認為李善長比自己更適合當丞相，選(D)。(A)「數欲害汝」的主語「是」是李善長，不是太祖。(B)太祖說「吾將相汝矣」，是想讓劉基當丞相（取代李善長），方向相反。(C)「大木」才比喻李善長，「束小木」是劉基自謙。", "skill": "先確認代詞「是」「汝」各指誰，再把比喻對號入座：柱＝丞相，大木＝李善長，小木＝劉基自己。"}], "difficulty": "中", "label": "114年會考", "year": 114, "kind": "會考"}, {"id": "hk114-22", "exam": "hk114", "nums": [22], "form": "單題", "img": "img/hk114-22.png", "source": "韋絢《劉賓客嘉話錄》", "author": "韋絢（記劉禹錫語）", "genre": "筆記小品", "types": ["文意推論"], "passage": "安邑里巷口有賣餅者，吾每早過戶，未嘗不聞其歌。一日，召之與語，貧窘可憐。因與萬錢，令多其本，日取餅以償之。欣然持錢而去。後過其戶，則寂然不聞謳歌之聲。及呼乃至，謂曰：「爾何輟歌之遽乎？」曰：「本流既大，所謀益增，不暇唱曲矣。」", "translation": "安邑里巷口有個賣餅的人，我每天早上經過他家門口，沒有一次不聽到他唱歌。有一天，我叫他來談話，發現他貧困窘迫，很可憐。於是給他一萬錢，讓他增加本錢，每天拿餅來償還就好。他很高興地拿著錢走了。後來我經過他家，卻安安靜靜，聽不到唱歌的聲音了。我叫他過來，問他：「你為什麼這麼快就不唱歌了？」他說：「本錢變大了，要打算的事越來越多，沒空唱曲了。」", "keywords": [{"w": "過戶", "m": "經過他家門口"}, {"w": "未嘗不", "m": "沒有一次不"}, {"w": "本", "m": "本錢"}, {"w": "償", "m": "償還"}, {"w": "輟", "m": "停止"}, {"w": "遽", "m": "迅速、突然"}, {"w": "暇", "m": "空閒"}], "questions": [{"n": 22, "stem": "「安邑里巷口有賣餅者，吾每早過戶，未嘗不聞其歌。一日，召之與語，貧窘可憐。因與萬錢，令多其本，日取餅以償之。欣然持錢而去。後過其戶，則寂然不聞謳歌之聲。及呼乃至，謂曰：『爾何輟歌之遽乎？』曰：『本流既大，所謀益增，不暇唱曲矣。』」關於文中的「吾」與賣餅者，下列敘述何者最恰當？", "options": {"A": "「吾」喜歡吃賣餅者的餅，日日光顧", "B": "賣餅者生意資本擴增後，工作更繁忙", "C": "「吾」喜歡賣餅者的歌聲，勸他以此招攬生意", "D": "賣餅者經濟狀況改善之後，就不想再繼續賣餅"}, "answer": "B", "explain": "賣餅者說「本流既大，所謀益增，不暇唱曲矣」：本錢變多後，要操心的事更多，忙到沒空唱歌，選(B)。(A)「日取餅以償之」是賣餅者每天用餅來還錢，不是「吾」喜歡吃餅天天光顧。(C)「吾」沒有勸他用唱歌招攬生意。(D)他只是不唱歌了，仍在賣餅，而且生意做得更大。", "skill": "注意「日取餅以償之」的主語與用意（還債方式），並以人物自己說的理由作為判斷依據。"}], "difficulty": "易", "label": "114年會考", "year": 114, "kind": "會考"}, {"id": "hk114-23", "exam": "hk114", "nums": [23], "form": "單題", "img": "img/hk114-23.png", "source": "鼂錯〈守邊勸農疏〉", "author": "鼂錯（晁錯）", "genre": "說理議論", "types": ["比較閱讀", "文意推論"], "passage": "令遠方之卒守塞，一歲而更，不知胡人之能。不如選常居者家室田作，且以備之，以便為之高城深塹。先為室屋、具田器，乃募民免罪、拜爵，予冬夏衣、廩食，能自給而止。塞下之民，祿利不厚，不可使久居危難之地。胡人入驅而能止其所驅者，以其半予之。如是則邑里相救助，赴胡不避死，全親戚而利其財也。此與遠方之戍卒，不習地勢而心畏胡者，功相萬也。", "translation": "讓遠方來的士兵守邊塞，一年就輪換，他們不了解胡人的本事。不如挑選能長久定居的人，帶著家眷在那裡耕田，同時防備胡人，再方便地為他們築高城、挖深溝。先替他們蓋好房屋、準備農具，再招募百姓，給予免罪、封爵的獎勵，並供給冬夏衣服和糧食，直到他們能自給自足為止。邊塞百姓如果俸祿利益不優厚，就無法讓他們長久住在危險的地方。胡人入侵搶掠，能夠奪回被搶的東西的人，就把其中一半賞給他。這樣一來，鄉里之間會互相救助，對抗胡人不怕死，既是為了保全親人，也是為了得到財物。這和那些遠方來、不熟悉地勢又心裡害怕胡人的戍卒相比，功效相差萬倍。", "keywords": [{"w": "更", "m": "更換、輪替"}, {"w": "塹", "m": "護城的深溝"}, {"w": "募", "m": "招募"}, {"w": "拜爵", "m": "授予爵位"}, {"w": "廩食", "m": "官府供給的糧食"}, {"w": "驅", "m": "搶掠驅趕（人畜財物）"}, {"w": "功相萬", "m": "功效相差萬倍"}], "questions": [{"n": 23, "stem": "「令遠方之卒守塞，一歲而更，不知胡人之能。不如選常居者家室田作，且以備之，以便為之高城深塹。先為室屋、具田器，乃募民免罪、拜爵，予冬夏衣、廩食，能自給而止。塞下之民，祿利不厚，不可使久居危難之地。胡人入驅而能止其所驅者，以其半予之。如是則邑里相救助，赴胡不避死，全親戚而利其財也。此與遠方之戍卒，不習地勢而心畏胡者，功相萬也。」關於文中「遠卒守塞」、「募民屯戍」的比較，下列何者最恰當？（表格選項：(A)駐地的久暫：遠卒守塞＝久居／募民屯戍＝一歲而更　(B)獲得的福利：遠卒守塞＝室屋、田器／募民屯戍＝冬夏衣、廩食　(C)對地勢的了解：遠卒守塞＝熟習／募民屯戍＝不熟習　(D)對胡人的心態：遠卒守塞＝畏懼／募民屯戍＝不畏懼）", "options": {"A": "駐地的久暫：遠卒守塞「久居」；募民屯戍「一歲而更」", "B": "獲得的福利：遠卒守塞「室屋、田器」；募民屯戍「冬夏衣、廩食」", "C": "對地勢的了解：遠卒守塞「熟習」；募民屯戍「不熟習」", "D": "對胡人的心態：遠卒守塞「畏懼」；募民屯戍「不畏懼」"}, "answer": "D", "explain": "文末說遠方戍卒「不習地勢而心畏胡」，而募來的屯戍百姓「赴胡不避死」，所以遠卒畏懼胡人、募民不畏懼，(D)正確。(A)正好相反：遠卒「一歲而更」，募民是「常居者」久居。(B)室屋、田器、冬夏衣、廩食都是給募民的福利，遠卒沒有。(C)也相反：遠卒「不習地勢」，募民長居當地才熟悉。", "skill": "比較題先把原文分成兩欄（遠卒／募民）各自抄下關鍵句，再對照表格，就能發現哪些選項左右顛倒。"}], "difficulty": "中", "label": "114年會考", "year": 114, "kind": "會考"}, {"id": "hk114-24", "exam": "hk114", "nums": [24], "form": "單題", "img": "img/hk114-24.png", "source": "葉夢得《避暑錄話‧卷上》", "author": "葉夢得", "genre": "筆記小品", "types": ["文意推論", "主旨寓意"], "passage": "世傳《碧雲騢》一卷為梅聖俞作，皆歷詆慶曆以來公卿隱過，雖范文正亦不免。議者遂謂聖俞游諸公間，官竟不達，懟而為此以報之。君子成人之美，縱使萬有一不至，猶當為賢者諱，況未必有實。聖俞賢者，豈至是哉？後聞之，乃魏泰所為，嫁之聖俞也。此豈特累諸公，又將以誣聖俞？歐陽文忠《歸田錄》自言不記人之過惡，君子之用心當如此也。", "translation": "世上流傳《碧雲騢》一卷是梅聖俞寫的，書中一一詆毀慶曆年間以來公卿大臣不為人知的過失，連范仲淹也不能倖免。議論的人就說梅聖俞和這些大官交往，官位卻始終不顯達，心懷怨恨才寫這本書報復。君子成全別人的好處，即使萬一真有不周到的地方，也應該替賢者隱諱，何況這未必是事實。梅聖俞是賢人，怎麼會做這種事呢？後來聽說，原來是魏泰寫的，卻栽贓給梅聖俞。這豈只是連累了那些大臣，還誣衊了梅聖俞啊！歐陽脩在《歸田錄》中說自己不記錄別人的過錯醜事，君子的用心就應當像這樣。", "keywords": [{"w": "詆", "m": "毀謗"}, {"w": "隱過", "m": "不為人知的過失"}, {"w": "不達", "m": "不顯達、官運不好"}, {"w": "懟", "m": "怨恨"}, {"w": "諱", "m": "隱瞞、避而不說"}, {"w": "嫁", "m": "轉嫁、栽贓"}, {"w": "特", "m": "只"}, {"w": "誣", "m": "誣衊"}], "questions": [{"n": 24, "stem": "「世傳《碧雲騢》一卷為梅聖俞作，皆歷詆慶曆以來公卿隱過，雖范文正亦不免。議者遂謂聖俞游諸公間，官竟不達，懟而為此以報之。君子成人之美，縱使萬有一不至，猶當為賢者諱，況未必有實。聖俞賢者，豈至是哉？後聞之，乃魏泰所為，嫁之聖俞也。此豈特累諸公，又將以誣聖俞？歐陽文忠《歸田錄》自言不記人之過惡，君子之用心當如此也。」下列何者最符合本文的觀點？", "options": {"A": "范文正也曾揭發公卿的過錯", "B": "《碧雲騢》應非梅聖俞所作", "C": "魏泰因官運不亨而怨懟梅聖俞", "D": "《歸田錄》反對替賢者隱諱的筆法"}, "answer": "B", "explain": "作者說「聖俞賢者，豈至是哉」，又說後來得知「乃魏泰所為，嫁之聖俞」，認為《碧雲騢》不是梅聖俞寫的，是被栽贓，選(B)。(A)「雖范文正亦不免」是說范仲淹也被書中詆毀，不是他揭發別人。(C)「官竟不達，懟而為此」是議者對梅聖俞的猜測，與魏泰無關。(D)《歸田錄》「不記人之過惡」，正是替人隱諱的態度，與選項相反。", "skill": "區分「議者的說法」與「作者的觀點」：作者用反問句（豈至是哉）表態，再用「後聞之」提出證據。"}], "difficulty": "難", "label": "114年會考", "year": 114, "kind": "會考"}, {"id": "hk114-38", "exam": "hk114", "nums": [38, 39], "form": "題組", "img": "img/hk114-38.png", "source": "司馬遷《史記‧刺客列傳》（專諸）", "author": "司馬遷", "genre": "史傳人物", "types": ["文意推論", "文化常識"], "passage": "公子光之父曰吳王諸樊。諸樊弟三人：次曰餘祭，次曰夷眛，次曰季子札。諸樊知季子札賢而不立太子，以次傳三弟，欲卒致國於季子札。諸樊既死，傳餘祭。餘祭死，傳夷眛。夷眛死，當傳季子札。季子札逃不肯立，吳人乃立夷眛之子僚為王。公子光曰：「使以兄弟次邪，季子當立；必以子乎，則光真嫡嗣，當立。」", "translation": "公子光的父親是吳王諸樊。諸樊有三個弟弟：老二叫餘祭，老三叫夷眛，老四叫季子札。諸樊知道季子札賢能，所以不立太子，打算依兄弟次序把王位傳給三個弟弟，最終把國家交給季子札。諸樊死後，傳位給餘祭。餘祭死，傳給夷眛。夷眛死，應該傳給季子札。季子札逃走不肯即位，吳國人就立夷眛的兒子僚為王。公子光說：「假如按兄弟次序，應該是季子即位；如果一定要傳給兒子，那我才是真正的嫡長子孫，應該由我即位。」", "keywords": [{"w": "次", "m": "排行第二；次序"}, {"w": "卒", "m": "最終"}, {"w": "致國", "m": "把國家交給"}, {"w": "使", "m": "假如"}, {"w": "嫡嗣", "m": "正妻所生的繼承人"}], "questions": [{"n": 38, "stem": "下列何者最可能是文中人物的親屬關係示意圖？（選項為家族樹狀圖）", "options": {"A": "上一代（空格）下有諸樊、餘祭、夷眛、季子札四兄弟；諸樊之子為光，夷眛之子為僚", "B": "上一代（空格）下有諸樊、光、餘祭、夷眛；諸樊之子為季子札，夷眛之子為僚", "C": "諸樊之子為餘祭、夷眛、季子札；餘祭之子為光，夷眛之子為僚", "D": "諸樊之子為光、餘祭、夷眛、季子札；夷眛之子為僚"}, "answer": "A", "explain": "「公子光之父曰吳王諸樊」→光是諸樊的兒子；「諸樊弟三人：餘祭、夷眛、季子札」→四人是兄弟；「夷眛之子僚」→僚是夷眛的兒子。符合的是(A)。(B)把光當成諸樊的弟弟、季子札當成諸樊的兒子，錯。(C)(D)都把餘祭等人畫成諸樊的兒子，但他們是諸樊的弟弟；(C)又把光畫成餘祭之子。", "skill": "把每一句的親屬關係逐句畫出來（父子用直線、兄弟用橫線），再與選項比對。"}, {"n": 39, "stem": "根據本文，公子光最無法接受誰擔任吳王？", "options": {"A": "餘祭", "B": "夷眛", "C": "季子札", "D": "僚"}, "answer": "D", "explain": "公子光說：照兄弟次序應由季子札即位；照父子相傳，應由他這個諸樊的嫡子即位。不管哪一種規則，都輪不到夷眛的兒子僚，所以他最無法接受的是僚，選(D)。(A)(B)餘祭、夷眛依兄弟相傳合乎諸樊的安排。(C)季子札在兄弟次序中本來就「當立」，公子光也承認。", "skill": "把公子光的兩種假設（以兄弟次／以子）各推出一個人選，不在這兩個答案中的人，就是他不服的對象。"}], "difficulty": "中", "label": "114年會考", "year": 114, "kind": "會考"}, {"id": "hk114-40", "exam": "hk114", "nums": [40, 41, 42], "form": "題組", "img": "img/hk114-40.png", "source": "司馬光〈答薛虢州謝石月屏書〉", "author": "司馬光", "genre": "書信序跋", "types": ["字詞解釋", "文意推論", "人物情感"], "passage": "日前令郎訪逮，出手筆並石月屏為贈，捧玩不勝愧喜。比來，數於都下朋從處見此屏，觀其天質圓瑩，非刻非繪，如秋高氣清，迥然在望，信乎天地之異氣、山澤之殊寶也。素心悅之，無從可得，豈意一旦不煩懇請，坐致握中。性本疏野，雅叶所欲，雖受文錦十純，白璧百雙，在光之愚，未為重賜。俗故忽忽，久不遑修謝，尤增悚懼。令郎注官甚便，想加慰喜，未期接侍，倍希珍厚。", "translation": "前些日子令郎來訪，拿出您的親筆信和石月屏送給我，我捧著把玩，慚愧又欣喜得不得了。近來，我好幾次在京城朋友家見過這種石屏，看它天然的質地圓潤晶瑩，不是雕刻也不是彩繪，就像秋高氣爽時遠遠望見的明月，確實是天地間奇異之氣、山川中特殊的寶物。我一向很喜愛，卻沒辦法得到，沒想到有一天不必懇求，就坐著得到、握在手中了。我生性粗放不拘，這東西非常符合我的喜好，即使收到十段有花紋的錦緞、一百對白玉，在我這愚人看來，也比不上這份厚禮。因俗事繁忙，很久沒空寫信道謝，更加感到惶恐不安。令郎被授予的官職很合適，想必您更加欣慰歡喜。不知何時能當面奉陪，還望您多多保重。", "keywords": [{"w": "令郎", "m": "稱對方的兒子"}, {"w": "逮", "m": "及、到"}, {"w": "手筆", "m": "親筆書信"}, {"w": "比來", "m": "近來"}, {"w": "迥然", "m": "遙遠的樣子"}, {"w": "信", "m": "確實"}, {"w": "一旦", "m": "有一天、忽然"}, {"w": "坐致", "m": "不費力而得到"}, {"w": "叶", "m": "音ㄒㄧㄝˊ，符合"}, {"w": "純", "m": "布帛一段為一純"}, {"w": "俗故", "m": "世俗事務"}, {"w": "不遑", "m": "沒有空閒"}, {"w": "珍厚", "m": "保重"}], "questions": [{"n": 40, "stem": "根據文意脈絡，下列「」中的詞語，何者替換後意義仍相同？", "options": {"A": "日前「令郎」訪逮：令尊", "B": "「比來」，數於都下朋從處見此屏：近來", "C": "豈意「一旦」不煩懇請：剎那", "D": "「俗故」忽忽：老友"}, "answer": "B", "explain": "「比來」是近來，替換成「近來，數於都下朋從處見此屏」意思相同，選(B)。(A)「令郎」是對方的兒子，「令尊」是對方的父親，不同。(C)「一旦」在此指「有一天、忽然有一天」，不是極短的時間「剎那」。(D)「俗故」是世俗瑣事，「俗故忽忽」＝俗事繁忙，不是老朋友。", "skill": "敬稱詞要背清楚（令郎／令尊／令堂）；其餘詞語代回原句，看前後文是否通順。"}, {"n": 41, "stem": "關於文中的石月屏，下列敘述何者最恰當？", "options": {"A": "若不是薛虢州贈送石月屏，司馬光無從見其真貌", "B": "石月屏雖比文錦、白璧昂貴，但司馬光更重友情", "C": "司馬光初獲石月屏時雖心喜，當下仍堅守節操婉拒", "D": "石月屏自然生成，清氣可見，因此司馬光甚為喜愛"}, "answer": "D", "explain": "文中說它「天質圓瑩，非刻非繪，如秋高氣清，迥然在望」，是天然形成、清朗可見的寶物，所以司馬光「素心悅之」，選(D)。(A)他近來曾「數於都下朋從處見此屏」，早就見過。(B)「雖受文錦十純，白璧百雙……未為重賜」是說那些都比不上這份禮物在他心中的分量，並非比較價格，也沒說更重友情。(C)他收下了（坐致握中），而且寫信道謝，沒有婉拒。", "skill": "推論題要找原文證據逐一核對：「數……見此屏」推翻(A)，「坐致握中」推翻(C)。"}, {"n": 42, "stem": "根據本文，下列何者最可能是司馬光收下石月屏後的反應？", "options": {"A": "欲登門回禮，惜薛公務繁忙，擬另擇日造訪", "B": "獲贈禮物，喜出望外，故寫信向薛表達謝意", "C": "受薛贈寶深感有愧，已經備好厚禮回贈致謝", "D": "為辨優劣，邀請好友來家中共同鑑賞石月屏"}, "answer": "B", "explain": "「捧玩不勝愧喜」「豈意一旦不煩懇請，坐致握中」表現意外得到心愛之物的驚喜；這篇文章本身就是〈答薛虢州謝石月屏書〉──寫信道謝，選(B)。(A)「俗故忽忽」是司馬光自己忙，且沒有說要登門回禮。(C)文中沒有提備禮回贈。(D)沒有邀友鑑賞的內容。", "skill": "注意文章的體裁與題目：「謝……書」就是一封道謝信，作者的反應就寫在信裡（愧喜、致謝）。"}], "difficulty": "難", "label": "114年會考", "year": 114, "kind": "會考"}, {"id": "hk115-9", "exam": "hk115", "nums": [9], "form": "單題", "img": "img/hk115-9.png", "source": "出處待查（詠烘書之詩）", "author": "出處待查", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "烘書之情何所似，有如老翁撫病子。心知元氣不可復，但求無死斯足矣。書燒之時又何其，有如慈父怒啼兒。恨死擲去不回顧，徐徐復自撫摩之。此情自痴還自笑，心血既乾轉煩惱。上壽八十能幾何，為爾多累何其多。", "translation": "烘乾（受潮的）書時的心情像什麼？就像老翁撫摸生病的兒子。心裡知道書的元氣已經無法恢復，只求它不要壞掉就心滿意足了。書被烤焦的時候心情又是怎樣？就像慈父對著哭鬧的孩子發怒：氣得要死，把它丟開不再看一眼，過一會兒卻又慢慢地自己去撫摸它。這種感情連自己都覺得痴傻、忍不住自嘲，心血耗乾了反而更加煩惱。人就算長壽活到八十歲又能有多久，為了你（書）卻添了這麼多牽累。", "keywords": [{"w": "何所似", "m": "像什麼"}, {"w": "元氣", "m": "根本的生命力，此指書的原貌"}, {"w": "斯", "m": "就"}, {"w": "恨死", "m": "恨極、氣得要死"}, {"w": "上壽", "m": "高壽"}, {"w": "爾", "m": "你，指書"}, {"w": "累", "m": "牽累"}], "questions": [{"n": 9, "stem": "「烘書之情何所似，有如老翁撫病子。心知元氣不可復，但求無死斯足矣。書燒之時又何其，有如慈父怒啼兒。恨死擲去不回顧，徐徐復自撫摩之。此情自痴還自笑，心血既乾轉煩惱。上壽八十能幾何，為爾多累何其多。」關於這首詩的說明，下列敘述何者最恰當？", "options": {"A": "「心知元氣不可復」指作者時日無多而焚書", "B": "「恨死擲去不回顧」代表愛書之情至死不渝", "C": "「徐徐復自撫摩之」表達作者不忍書燒之情", "D": "「上壽八十能幾何」意指書籍保存有其時限"}, "answer": "C", "explain": "書被烤焦時，作者像慈父對哭鬧的孩子：一氣之下丟開（恨死擲去），過一會兒又捨不得地慢慢撫摸，表現他心疼、不忍書被燒壞，(C)正確。(A)「元氣不可復」說的是受潮的書（像病子）無法完全復原，並非作者要焚書。(B)「恨死擲去」是一時氣極把書丟開，和「至死不渝」無關。(D)「上壽八十能幾何」是感嘆人生有限，卻為書添了許多牽累，不是說書的保存期限。", "skill": "抓住詩中的兩組比喻（老翁撫病子、慈父怒啼兒），把「書」對應成「孩子」，再判斷每句是寫人還是寫書。"}], "difficulty": "中", "label": "115年會考", "year": 115, "kind": "會考"}, {"id": "hk115-12", "exam": "hk115", "nums": [12], "form": "單題", "img": "img/hk115-12.png", "source": "趙彥衛《雲麓漫鈔》", "author": "趙彥衛", "genre": "筆記小品", "types": ["文意推論", "文化常識"], "passage": "五代帝王多裹朝天襆頭，二腳上翹。四方之主，各創新樣，或翹上而反折於下，或如團扇蕉葉之狀，合抱於前。後蜀之君始以漆紗為之，楚國國主二角左右長尺餘，謂之龍角，人或誤觸之，則終日頭痛。至後漢高祖裹襆頭，左右長尺餘，橫直之，不復上翹，迄今不改。", "translation": "五代的帝王大多戴朝天襆頭，兩根帽腳向上翹。各地的君主各自創出新樣式，有的向上翹起再往下反折，有的像團扇、芭蕉葉的形狀，在前面合抱。後蜀的君主開始用漆紗來做，楚國國君的帽子兩角左右各長一尺多，叫做龍角，有人不小心碰到，國君就整天頭痛。到了後漢高祖戴的襆頭，左右各長一尺多，平直地伸出去，不再向上翹，一直到今天（宋代）都沒有改變。", "keywords": [{"w": "裹", "m": "戴（頭巾、帽子）"}, {"w": "襆頭", "m": "古代男子的一種帽子，後有兩腳"}, {"w": "翹", "m": "向上揚起"}, {"w": "橫直之", "m": "使它平直地向兩側伸出"}, {"w": "迄今", "m": "到現在"}], "questions": [{"n": 12, "stem": "宋 趙彥衛《雲麓漫鈔》：「五代帝王多裹朝天襆頭，二腳上翹。四方之主，各創新樣，或翹上而反折於下，或如團扇蕉葉之狀，合抱於前。後蜀之君始以漆紗為之，楚國國主二角左右長尺餘，謂之龍角，人或誤觸之，則終日頭痛。至後漢高祖裹襆頭，左右長尺餘，橫直之，不復上翹，迄今不改。」根據本文，宋代帝王襆頭的樣式與下列何者最接近？", "options": {"A": "兩腳平伸後向上折、末端再向下反折的樣式（圖）", "B": "兩腳向上彎翹的樣式（圖）", "C": "兩腳如團扇蕉葉、向前合抱的樣式（圖）", "D": "兩腳左右平直伸長的樣式（圖）"}, "answer": "D", "explain": "作者是宋人，「迄今不改」的「今」就是宋代。文中說後漢高祖的襆頭「左右長尺餘，橫直之，不復上翹，迄今不改」，所以宋代帝王的襆頭是兩腳左右平直伸長，選(D)。(A)接近「翹上而反折於下」的樣式。(B)兩腳上翹是五代的朝天襆頭。(C)「如團扇蕉葉之狀，合抱於前」是五代各地君主的新樣。", "skill": "注意作者的年代（宋），把「迄今」換成「到宋代」，就知道要找的是最後一種、沿用到作者當時的樣式。"}], "difficulty": "中", "label": "115年會考", "year": 115, "kind": "會考"}, {"id": "hk115-13", "exam": "hk115", "nums": [13], "form": "單題", "img": "img/hk115-13.png", "source": "張懷瓘《書斷》（事見《南齊書》、《南史‧王僧虔傳》）", "author": "張懷瓘", "genre": "筆記小品", "types": ["文意推論", "比較閱讀"], "passage": "齊高帝善草書，篤好不已，祖述子敬，稍乏風骨。嘗與王僧虔賭書，書畢曰：「誰為第一？」對曰：「臣書臣中第一，陛下書帝中第一。」帝笑曰：「卿可謂善自謀矣。」然高帝與僧虔賭書，亦猶雞之搏狸，稍不自知量力也。", "translation": "南齊高帝擅長草書，非常熱愛、從不停止，他效法王獻之（字子敬），但略微缺少剛健的筆力氣勢。他曾和王僧虔比賽寫字，寫完後問：「誰是第一？」王僧虔回答：「我的字在臣子中第一，陛下的字在皇帝中第一。」高帝笑說：「你可真是善於替自己打算啊。」然而高帝和王僧虔比賽書法，就像雞去和野貓搏鬥，有點不自量力。", "keywords": [{"w": "篤好", "m": "非常喜好"}, {"w": "祖述", "m": "效法、師承"}, {"w": "子敬", "m": "王獻之的字"}, {"w": "風骨", "m": "書法剛健的筆力氣勢"}, {"w": "賭書", "m": "比賽書法"}, {"w": "善自謀", "m": "善於為自己打算"}, {"w": "狸", "m": "野貓"}], "questions": [{"n": 13, "stem": "「齊高帝善草書，篤好不已，祖述子敬，稍乏風骨。嘗與王僧虔賭書，書畢曰：『誰為第一？』對曰：『臣書臣中第一，陛下書帝中第一。』帝笑曰：『卿可謂善自謀矣。』然高帝與僧虔賭書，亦猶雞之搏狸，稍不自知量力也。」關於文中人物書法的比較，下列敘述何者最恰當？", "options": {"A": "作者認為高帝書法不如僧虔", "B": "作者認為子敬書法天下第一", "C": "子敬覺得高帝的草書缺乏風骨", "D": "僧虔自認與高帝賭書猶雞之搏狸"}, "answer": "A", "explain": "末句是作者的評論：高帝和僧虔比書法「猶雞之搏狸，稍不自知量力」──雞打不過狸，表示高帝的書法比不上王僧虔，選(A)。(B)作者只說高帝效法子敬，沒有說子敬天下第一。(C)「稍乏風骨」是作者對高帝的評語，不是子敬說的（子敬是東晉人，早於南齊）。(D)「雞之搏狸」是作者的評論，王僧虔當面只巧妙地說「臣中第一、帝中第一」，沒有這樣說。", "skill": "分辨文中三種聲音：敘述者評語（稍乏風骨、雞之搏狸）、人物對話（臣中第一）、人物反應（善自謀），選項的主語要對得上。"}], "difficulty": "中", "label": "115年會考", "year": 115, "kind": "會考"}, {"id": "hk115-18", "exam": "hk115", "nums": [18], "form": "單題", "img": "img/hk115-18.png", "source": "《呂氏春秋‧慎行論‧下賢》", "author": "呂不韋（主編）", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "子產相鄭，往見壺丘子林，與其弟子坐，必以年。夫居相於萬乘之國，而能捨之，謀志論行，而以心與人相索，其唯子產乎？故相鄭十八年，唯刑三人、殺二人，桃李之垂於行者，莫之援也。", "translation": "子產擔任鄭國宰相，去拜見壺丘子林，和他的弟子們坐在一起時，一定依照年齡排座位。身為大國的宰相，卻能放下這個身分，和人討論志向、品行，用真心和人交往，大概只有子產吧！所以他擔任鄭國宰相十八年，只處刑三人、處死兩人；路邊垂到行人頭上的桃子李子，也沒有人去摘取。", "keywords": [{"w": "相", "m": "擔任宰相（動詞）"}, {"w": "以年", "m": "依年齡就座"}, {"w": "萬乘之國", "m": "大國"}, {"w": "捨之", "m": "放下（宰相的身分）"}, {"w": "相索", "m": "互相求取、交往"}, {"w": "援", "m": "採摘"}], "questions": [{"n": 18, "stem": "「子產相鄭，往見壺丘子林，與其弟子坐，必以年。夫居相於萬乘之國，而能捨之，謀志論行，而以心與人相索，其唯子產乎？故相鄭十八年，唯刑三人、殺二人，桃李之垂於行者，莫之援也。」關於文中子產的敘述，下列何者最恰當？", "options": {"A": "求才若渴，四處招募各國的賢士", "B": "認為教育乃治國根本，極力興學", "C": "推行嚴刑峻法，令人民路不拾遺", "D": "跳脫身分貴賤的框架，以誠待人"}, "answer": "D", "explain": "子產身為宰相，和壺丘子林的弟子坐在一起卻依年齡排座，「居相於萬乘之國，而能捨之」「以心與人相索」，表示他放下宰相身分、真誠待人，選(D)。(A)文中只寫他去拜見壺丘子林，沒有四處招募賢士。(B)沒有提到興學。(C)「唯刑三人、殺二人」表示用刑極少，不是嚴刑峻法；百姓不摘路邊果實是被他的德行感化。", "skill": "找出關鍵評語「而能捨之」「以心與人相索」，再看結果「唯刑三人」是用刑少，避免被「路不拾遺」的印象誤導。"}], "difficulty": "中", "label": "115年會考", "year": 115, "kind": "會考"}, {"id": "hk115-20", "exam": "hk115", "nums": [20], "form": "單題", "img": "img/hk115-20.png", "source": "沈括《夢溪筆談‧卷十》", "author": "沈括", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "蔣堂為淮南轉運使，屬縣依例致賀，皆投書即還。有一縣令使人，獨求回書，左右諭之皆不聽，呵逐亦不去，曰：「寧得罪，不得書不敢回邑。」時蘇子美在座頗駭怪，曰：「小吏如此野狠，其令可知。」蔣曰：「不然，令必能者，使人不敢慢其命令如此。」乃為簡答之，方去。子美歸吳中月餘，得蔣書曰：「縣令果能者。」遂為之延譽，後卒為名臣。", "translation": "蔣堂擔任淮南轉運使時，所屬各縣照慣例派人送賀信，都是送了信就回去。只有一位縣令派來的人，堅持要拿到回信，旁人勸他都不聽，罵他趕他也不走，說：「寧可得罪，拿不到回信我不敢回縣裡。」當時蘇子美在座，非常驚訝奇怪，說：「小吏這麼粗野蠻橫，他的縣令是什麼樣的人可想而知。」蔣堂說：「不是這樣，這縣令一定很能幹，才能讓手下不敢怠慢他的命令到這種程度。」於是寫了一封短信回覆，那人才離開。蘇子美回吳中一個多月後，收到蔣堂的信說：「那位縣令果然很能幹。」蔣堂於是替他宣揚名聲，那縣令後來終於成為名臣。", "keywords": [{"w": "屬縣", "m": "所管轄的縣"}, {"w": "諭", "m": "勸告"}, {"w": "呵逐", "m": "斥罵驅趕"}, {"w": "駭怪", "m": "驚訝奇怪"}, {"w": "慢", "m": "怠慢"}, {"w": "簡", "m": "書信"}, {"w": "延譽", "m": "宣揚名聲"}, {"w": "卒", "m": "終於"}], "questions": [{"n": 20, "stem": "關於文中人物的敘述，下列何者最恰當？", "options": {"A": "小吏仗勢欺人，目無尊長", "B": "縣令治事有方，管理嚴格", "C": "蔣堂寫信推薦蘇子美為吳中令", "D": "蘇子美有識人之明而成為名臣"}, "answer": "B", "explain": "小吏寧可得罪轉運使也要拿到回信，蔣堂判斷「令必能者，使人不敢慢其命令如此」，後來證實「縣令果能者」，可見縣令辦事能幹、管理部屬嚴格，選(B)。(A)小吏是怕違背縣令命令，不是仗勢欺人。(C)蔣堂寫信給蘇子美是告訴他「縣令果能者」，並非推薦蘇子美當官。(D)有識人之明的是蔣堂；蘇子美反而誤判，「後卒為名臣」的是那位縣令。", "skill": "把每個人的判斷列出來（子美：其令可知→錯；蔣堂：令必能者→對），再追「遂為之延譽，後卒為名臣」的「之」指誰。"}], "difficulty": "難", "label": "115年會考", "year": 115, "kind": "會考"}, {"id": "hk115-21", "exam": "hk115", "nums": [21], "form": "單題", "img": "img/hk115-21.png", "source": "《笑林廣記‧形體部》", "author": "遊戲主人（編）", "genre": "筆記小品", "types": ["文意推論", "寫作手法"], "passage": "或問：「世間何物最硬？」曰：「石頭與鋼鐵。」其人曰：「石可碎，鐵可鏨，安得為硬？以弟看來為兄面上髭鬚最硬，鐵石總不如也。」問其故，答曰：「兄面皮厚，竟被看出。」鬚者回嘲曰：「足下面皮更老，這等硬鬚還鑽不透。」", "translation": "有人問：「世上什麼東西最硬？」對方回答：「石頭和鋼鐵。」那人說：「石頭可以打碎，鐵可以雕鑿，怎麼算硬？依小弟看，老兄臉上的鬍鬚最硬，鐵和石頭都比不上。」問他原因，他回答：「老兄臉皮那麼厚，鬍鬚竟然還能穿出來。」有鬍子的人反過來嘲笑說：「閣下的臉皮更老更厚，這樣硬的鬍鬚都鑽不透（所以你長不出鬍子）。」", "keywords": [{"w": "或", "m": "有人"}, {"w": "鏨", "m": "雕鑿"}, {"w": "安得", "m": "怎能"}, {"w": "髭鬚", "m": "鬍鬚"}, {"w": "竟被看出", "m": "竟然被（鬍鬚）穿出來"}, {"w": "足下", "m": "對對方的敬稱，您"}, {"w": "老", "m": "厚、硬"}], "questions": [{"n": 21, "stem": "根據這則笑話，以鬚者的立場來看，下列何者最硬？", "options": {"A": "石頭與鋼鐵", "B": "鬚者的面皮", "C": "面皮上的髭鬚", "D": "無鬚者的面皮"}, "answer": "D", "explain": "無鬚者先嘲笑：鬍鬚能穿透有鬚者的厚臉皮，所以鬍鬚最硬。鬚者回嘲：「足下面皮更老，這等硬鬚還鑽不透」──連最硬的鬍鬚都穿不透你的臉皮，所以你的臉皮比鬍鬚還硬，也就是無鬚者的面皮最硬，選(D)。(A)兩人都說石鐵不算最硬。(B)鬍鬚能穿透鬚者面皮，表示它不是最硬。(C)鬍鬚是無鬚者心中最硬的，但在鬚者看來，還有比它更硬的。", "skill": "笑話的「回嘲」常順著對方的邏輯反將一軍：把「A能穿透B→A比B硬」的推理套到回嘲句上，就能排出硬度順序。"}], "difficulty": "中", "label": "115年會考", "year": 115, "kind": "會考"}, {"id": "hk115-22", "exam": "hk115", "nums": [22], "form": "單題", "img": "img/hk115-22.png", "source": "王闢之《澠水燕談錄‧卷十》", "author": "王闢之", "genre": "筆記小品", "types": ["文意推論", "寫作手法"], "passage": "往年士大夫好講水利。有言欲涸梁山泊以為農田者，或詰之曰：『梁山泊涸之，不幸秋夏之交，行潦四集，諸水並入，何以受之？』貢父適在坐，徐曰：『卻於泊之傍鑿一池，大小正同，則可受其水矣。』坐中皆絕倒，言者大慚沮。", "translation": "從前士大夫喜歡談論興修水利。有人說想把梁山泊的水抽乾，改成農田，有人質問他說：「梁山泊抽乾了，萬一碰上夏秋之交，雨水四面匯集，各路水流一起灌進來，要拿什麼來容納？」劉貢父剛好在座，慢慢地說：「那就在泊的旁邊再挖一個池子，大小剛好一樣，就可以容納那些水了。」在座的人都笑得前仰後合，提議的人十分羞愧沮喪。", "keywords": [{"w": "涸", "m": "使乾涸，抽乾"}, {"w": "詰", "m": "質問"}, {"w": "行潦", "m": "地面流動的雨水"}, {"w": "適", "m": "恰好"}, {"w": "徐", "m": "慢慢地"}, {"w": "絕倒", "m": "笑得前仰後合"}, {"w": "慚沮", "m": "羞愧沮喪"}], "questions": [{"n": 22, "stem": "「往年士大夫好講水利。有言欲涸梁山泊以為農田者，或詰之曰：『梁山泊涸之，不幸秋夏之交，行潦四集，諸水並入，何以受之？』貢父適在坐，徐曰：『卻於泊之傍鑿一池，大小正同，則可受其水矣。』坐中皆絕倒，言者大慚沮。」關於文中眾人對水利的想法，下列敘述何者最恰當？", "options": {"A": "為解決梁山泊秋夏淹水的問題，士大夫提議涸梁山泊為田", "B": "提出詰問的人擔憂梁山泊因泥沙淤積而難以吸納大量洪水", "C": "貢父表面提出方法，實則藉此凸顯欲涸梁山泊為田的荒謬", "D": "眾人對貢父的想法不以為然，仍堅持涸梁山泊為田的建議"}, "answer": "C", "explain": "在旁邊挖一個和梁山泊一樣大的池子來裝水，等於白忙一場，還不如不抽乾；貢父故意一本正經提出這個辦法，其實是諷刺「涸梁山泊為田」的荒謬，所以眾人大笑、提議者羞愧，選(C)。(A)提議者是想得到農田，淹水是詰問者提出的擔憂。(B)詰問者擔心的是抽乾後雨水沒地方容納，沒提泥沙淤積。(D)眾人「絕倒」、言者「大慚沮」，表示大家懂得貢父的諷刺，提議也就作罷。", "skill": "從旁人反應（絕倒、慚沮）倒推說話者的用意：讓人大笑又讓提議者羞愧的話，多半是反諷。"}], "difficulty": "中", "label": "115年會考", "year": 115, "kind": "會考"}, {"id": "hk115-23", "exam": "hk115", "nums": [23], "form": "單題", "img": "img/hk115-23.png", "source": "商衟〈越調‧天淨沙〉（詠梅）", "author": "商衟", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "寫作手法"], "passage": "【甲】寒梅清秀誰知？霜禽翠羽同期。瀟灑寒塘月淡，暗香幽意，一枝雪裡偏宜。\n【乙】野橋當日誰栽？前村昨夜先開。雪散珍珠亂篩，多情嬌態，一枝風送香來。", "translation": "【甲】寒梅的清秀有誰知道？只有霜中的白鳥和翠鳥與它同時相伴。寒冷的池塘邊月色淡淡，梅花瀟灑脫俗，散發幽幽暗香與深遠情意，一枝梅在雪中格外合宜。\n【乙】野橋邊的梅樹當年是誰栽種的？前村的梅花昨夜已經搶先開了。雪花像珍珠一樣紛亂地篩落，梅花姿態多情嬌美，一枝隨風送來陣陣香氣。", "keywords": [{"w": "霜禽", "m": "白色的鳥（或霜中的鳥）"}, {"w": "翠羽", "m": "翠鳥"}, {"w": "同期", "m": "同時相伴"}, {"w": "暗香", "m": "幽淡的香氣"}, {"w": "偏宜", "m": "特別合適"}, {"w": "篩", "m": "像過篩一樣灑落"}], "questions": [{"n": 23, "stem": "【甲】寒梅清秀誰知？霜禽翠羽同期。瀟灑寒塘月淡，暗香幽意，一枝雪裡偏宜。【乙】野橋當日誰栽？前村昨夜先開。雪散珍珠亂篩，多情嬌態，一枝風送香來。甲、乙兩曲皆詠梅，下列關於二者的比較，何者敘述最恰當？", "options": {"A": "甲以雪喻梅，乙以珍珠喻梅", "B": "二者皆有視覺與嗅覺的摹寫", "C": "皆於首句提問，次句明確回答", "D": "二者的視線推移皆是由近而遠"}, "answer": "B", "explain": "甲曲有「寒塘月淡」「雪裡」等視覺描寫，又有「暗香」（嗅覺）；乙曲有「雪散珍珠亂篩」「嬌態」（視覺），又有「風送香來」（嗅覺），兩曲都有視覺與嗅覺摹寫，選(B)。(A)甲是寫梅在雪中，不是以雪比喻梅；乙的「珍珠」比喻的是雪。(C)甲首句問「誰知」，次句「霜禽翠羽同期」算是回答；但乙首句問「誰栽」，次句「前村昨夜先開」並沒有回答是誰栽的。(D)兩曲都沒有明顯由近而遠的視線移動，最後都聚焦到「一枝」梅上。", "skill": "摹寫題逐句標記感官（看到的、聞到的、聽到的）；比喻題要找清楚「喻體」是什麼——「雪散珍珠」是用珍珠比喻雪。"}], "difficulty": "中", "label": "115年會考", "year": 115, "kind": "會考"}, {"id": "hk115-39", "exam": "hk115", "nums": [39, 40], "form": "題組", "img": "img/hk115-39.png", "source": "林紓〈僮遂小傳〉", "author": "林紓", "genre": "史傳人物", "types": ["虛詞句式", "文意推論", "人物情感"], "passage": "僮僕遂者，閩之海山人，至忠。吾妻劉孺人逝時，遂侵曉起，私市餺飥，漬茗跪進於靈次，拜不止。他僮笑之，遂怒曰：「我孝主母，弗類若不孝也！」嘗從余客荔城，過綿亭山，輿翻，遂咎輿夫曰：「明日再跌，當擇其平坦者，勿令碎吾主人輿中物也。」其愚如此。余來杭城，遂哭，將從余，余止之。後得家書，遂乃以今年五月十八日被疫死矣。嗚呼！吾聞南方多疫，勞者先死，是必吾家役之無方耳，傳之亦所以志余過也。", "translation": "僮僕阿遂，是福建海山人，非常忠心。我的妻子劉孺人過世時，阿遂天剛亮就起床，自己掏錢買了湯餅，泡了茶，跪著供奉在靈位前，不停地叩拜。別的僮僕笑他，阿遂生氣地說：「我孝順女主人，不像你們不孝！」他曾跟著我客居荔城，經過綿亭山時轎子翻了，阿遂責怪轎夫說：「明天如果還要跌倒，應該選平坦的地方跌，不要摔碎我主人轎子裡的東西。」他就是這樣憨直。我要到杭州，阿遂哭著要跟我去，我阻止了他。後來收到家書，才知道阿遂在今年五月十八日染上瘟疫死了。唉！我聽說南方多瘟疫，勞累的人先死，這一定是我家使喚他不得法啊，替他作傳，也是用來記下我的過錯。", "keywords": [{"w": "至", "m": "非常（副詞）"}, {"w": "侵曉", "m": "天剛亮"}, {"w": "市", "m": "買（動詞）"}, {"w": "餺飥", "m": "湯餅"}, {"w": "靈次", "m": "靈位前"}, {"w": "若", "m": "你們（代詞）"}, {"w": "客", "m": "客居、旅居（動詞）"}, {"w": "咎", "m": "責怪"}, {"w": "役之無方", "m": "使喚他不得法"}, {"w": "志", "m": "記下"}], "questions": [{"n": 39, "stem": "根據本文，下列「」中的字何者當動詞使用？", "options": {"A": "「至」忠", "B": "弗類「若」不孝也", "C": "嘗從余「客」荔城", "D": "傳之亦所以志余「過」也"}, "answer": "C", "explain": "「嘗從余客荔城」意思是曾跟著我客居（旅居）在荔城，「客」是動詞，選(C)。(A)「至忠」＝非常忠心，「至」是副詞。(B)「弗類若不孝」＝不像你們不孝，「若」是代詞「你們」。(D)「志余過」＝記下我的過錯，「過」是名詞。", "skill": "判斷詞性看位置與意思：前面有主語「余」、後面接地點「荔城」，中間那個字就是動作（住、旅居）。"}, {"n": 40, "stem": "關於文中僮僕遂的敘述，下列何者最恰當？", "options": {"A": "生母過世後，託人購買湯餅祭拜表達孝心", "B": "提醒轎夫選擇平坦的道路，以免自己受傷", "C": "雖想跟從主人前去杭城，最終仍聽命留下", "D": "流落南方不幸染疫，死後輾轉歸葬於海山"}, "answer": "C", "explain": "「余來杭城，遂哭，將從余，余止之」，後來作者收到「家書」才知道他病死，可見阿遂沒有跟去杭城，聽命留下了，選(C)。(A)過世的是作者的妻子（主母），而且是阿遂自己「私市」（自己去買），不是託人。(B)他叫轎夫挑平坦處跌倒，是怕摔壞主人轎中的東西，不是怕自己受傷。(D)文中沒提流落和歸葬；「南方多疫」是作者對他死因的推想。", "skill": "注意「私市」的主語與「主母」的身分；用「家書」這個線索推知阿遂留在家中。"}], "difficulty": "中", "label": "115年會考", "year": 115, "kind": "會考"}, {"id": "hk115-41", "exam": "hk115", "nums": [41, 42], "form": "題組", "img": "img/hk115-41.png", "source": "韓嬰《韓詩外傳‧卷二》", "author": "韓嬰", "genre": "寓言故事", "types": ["字詞解釋", "主旨寓意", "文意推論"], "passage": "田饒事魯哀公，而不見察。謂哀公曰：「臣將去君，黃鵠舉矣。」哀公曰：「何謂也？」田饒曰：「君獨不見夫雞乎？頭戴冠者，文也；足傅距者，武也；敵在前敢鬥者，勇也；見食相告者，仁也；守夜不失時者，信也。雞雖有此五德，君猶烹而食之者，何也？則以其所從來者近也。夫黃鵠一舉千里，止君園池，食君魚鱉，啄君黍粱，無此五德，君猶貴之者，何也？以其所從來者遠也。臣將去君，黃鵠舉矣。」遂去之燕，燕以為相，三年，燕政大平。", "translation": "田饒侍奉魯哀公，卻不被重視。他對哀公說：「我要離開您，像黃鵠一樣高飛遠去了。」哀公說：「這是什麼意思？」田饒說：「您難道沒看過雞嗎？頭上戴著雞冠，是文；腳上長著爪距，是武；敵人在前敢於搏鬥，是勇；找到食物會招呼同伴，是仁；守夜報曉從不錯過時辰，是信。雞雖然有這五種美德，您還是把牠煮來吃，為什麼？因為牠就在身邊、從近處來。黃鵠一飛千里，停在您的園池，吃您的魚鱉，啄您的穀物，沒有這五種美德，您卻很珍視牠，為什麼？因為牠是從遠方來的。我要離開您，像黃鵠一樣高飛了。」於是離開魯國前往燕國，燕國任命他為宰相，三年後燕國政治非常太平。", "keywords": [{"w": "事", "m": "侍奉"}, {"w": "不見察", "m": "不被重視、不被了解"}, {"w": "去", "m": "離開"}, {"w": "舉", "m": "高飛"}, {"w": "距", "m": "雞爪後突出的尖骨"}, {"w": "之", "m": "到、往（動詞）"}, {"w": "大平", "m": "太平"}], "questions": [{"n": 41, "stem": "下列文句「」中文字的解釋，何者最恰當？", "options": {"A": "田饒事魯哀公，而「不見察」：不懂得自我反省", "B": "「見食相告」者，仁也：看到食物就通知夥伴", "C": "夫黃鵠「一舉千里」：高踞樹頂，眼界開闊", "D": "「遂去之燕」，燕以為相：離開了燕國"}, "answer": "B", "explain": "「見食相告」是雞找到食物會互相招呼，即看到食物就通知夥伴，這是「仁」的表現，選(B)。(A)「不見察」的「見」表被動，意思是不被（哀公）了解重視，不是自己不反省。(C)「一舉千里」是一飛就是千里，「舉」是飛。(D)「去之燕」是離開（魯國）前往燕國，「之」是「到、往」，接著「燕以為相」也說明他到了燕國。", "skill": "「見＋動詞」常表被動；「去」是離開、「之」是前往，「去之燕」要拆成「去（魯）→之（燕）」。"}, {"n": 42, "stem": "根據本文，田饒認為哀公晉用人才的態度，與下列何者最接近？", "options": {"A": "肥水不落外人田", "B": "遠來的和尚會念經", "C": "不求有功，但求無過", "D": "內舉不避親，外舉不避仇"}, "answer": "B", "explain": "田饒用雞和黃鵠作比較：雞有五德卻被烹食，因為「所從來者近」；黃鵠沒有五德卻被珍視，因為「所從來者遠」。意思是哀公輕視身邊的人才、看重外來的人，就像「遠來的和尚會念經」，選(B)。(A)是好處只留給自己人，與哀公輕近重遠相反。(C)是消極保守的做事態度，無關用人。(D)是舉才只看能力、不論親仇，是公正的用人態度，不符哀公的偏差。", "skill": "寓言的比喻要對應現實：雞＝身邊的賢才（田饒），黃鵠＝外來的人；抓住「近→賤、遠→貴」這組對比。"}], "difficulty": "中", "label": "115年會考", "year": 115, "kind": "會考"}];
window.METHOD="<h2 style=\"margin-top:0\">文言文其實沒那麼可怕</h2>\n<p>會考的文言文多半是<b>沒看過的小故事</b>：某個人做了什麼事、說了什麼話，最後告訴你一個道理。</p>\n<p>你不用每個字都懂，只要能用自己的話說出<b>「誰，做了什麼，結果怎樣」</b>，大部分的題目就能答。</p>\n<p>下面七個步驟，每次讀文言文都照著做一遍，做久了就會變成習慣。</p>\n\n<h2>讀文言文的七個步驟</h2>\n<div class=\"step\"><div class=\"num\">1</div><div><b>先看題目：知道要找什麼</b><br>先讀題目和四個選項，再去讀文章。題目裡的「誰」「為什麼」「何者錯誤」「兩篇都」要圈起來，讀文章時才知道要找什麼。<br><span class=\"meta\">口訣：先看題，再看文，帶著問題去找答案。</span></div></div>\n<div class=\"step\"><div class=\"num\">2</div><div><b>先讀完一遍：不懂的字圈起來，繼續讀</b><br>第一遍不要卡在看不懂的字，圈起來先跳過，把整篇讀完。讀完問自己：這篇大概在講什麼？用一句話說說看。<br><span class=\"meta\">口訣：不懂先圈，不要停。</span></div></div>\n<div class=\"step\"><div class=\"num\">3</div><div><b>切成小段：看到「曰」、人名就切一刀</b><br>文言文的句子很長，先切小一點。看到「曰」（說）、人名、或是句尾的「也、矣、乎、焉」，就在後面畫一條斜線。<br><span class=\"meta\">口訣：見到「曰」、見到人，就切一刀。</span></div></div>\n<div class=\"step\"><div class=\"num\">4</div><div><b>每句都問：這句是「誰」做的？</b><br>文言文很常把主角省略不寫，這是最容易錯的地方！把人名框起來，每一句前面補上「誰」。看到「之」「其」，就畫箭頭連回它指的那個人。<br><span class=\"meta\">口訣：每句問誰，沒寫就補。</span></div></div>\n<div class=\"step\"><div class=\"num\">5</div><div><b>換成白話：一個字變兩個字</b><br>把文言的單字換成白話的兩個字，例如「使」→「派遣」、「走」→「奔跑」、「顧」→「回頭」。「之、乎、者、也」這類小字先跳過，每一小段寫成一句「誰＋做了什麼」。<br><span class=\"meta\">口訣：單字變雙字，一段一白話。</span></div></div>\n<div class=\"step\"><div class=\"num\">6</div><div><b>找出轉折：最後兩句最重要</b><br>看到「然」（但是）、「而」、「乃」（才、於是）、「則不然」（卻不是這樣），後面通常是作者真正想說的話。故事的道理常常藏在最後兩句。<br><span class=\"meta\">口訣：看到轉折要停下，最後兩句藏答案。</span></div></div>\n<div class=\"step\"><div class=\"num\">7</div><div><b>回到文章找證據</b><br>每個選項都要回到文章找到對應的句子。有些選項看起來跟文章很像，可是把人換掉了、或是把意思說反了，這些就是陷阱。<br><span class=\"meta\">口訣：每個選項都要找證據，很像的要小心。</span></div></div>\n\n<h2>最常掉進去的五個坑</h2>\n<table>\n<tr><th>坑</th><th>長什麼樣子</th><th>怎麼避開</th></tr>\n<tr><td>搞錯是誰做的</td><td>一段話裡有好幾個人，主角又常常省略</td><td>每句補上「誰」；人很多就畫一張人物關係圖</td></tr>\n<tr><td>「之」「其」指錯人</td><td>以為「之」指的是最近的那個人</td><td>畫箭頭連回去，再想想合不合理</td></tr>\n<tr><td>用現在的意思去讀</td><td>「走」以為是走路，其實是跑；「去」以為是前往，其實是離開</td><td>把每個可能的意思放回句子，看哪個說得通</td></tr>\n<tr><td>搞錯是誰說的話</td><td>文章引用了別人的說法，選項卻當成作者的想法</td><td>每句話標上「誰說的」；作者常用「豈……哉」（怎麼會……呢）表達自己的看法</td></tr>\n<tr><td>只看字面，沒想背後的意思</td><td>寓言、比喻表面講一件事，其實在講另一件事</td><td>問自己：表面上在講什麼？其實想告訴我什麼？</td></tr>\n</table>\n\n<h2>怎麼用這個練習場</h2>\n<ul>\n<li><b>剛開始</b>：在「練習」選「易」，先做基測的單題，熟悉文言文的感覺。</li>\n<li><b>練熟了</b>：選「題組」，練習讀一整段故事。</li>\n<li><b>想挑戰</b>：選「會考」加上「難」，這些是最能拉開分數的題目。</li>\n<li><b>做錯了</b>：看解析裡的「解題小撇步」，再到「錯題本」重做一次。錯題本會告訴你最常錯哪一種題型，就多練那一種。</li>\n</ul>\n";
